(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["md3"] = [{"id":"md3-105-1-1","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"51歲男性病患，因為近半年來右上背酸痛和右上肢麻痹和無力到院就醫。他因這些病症在他院接受止痛藥物治療和手術治療頸椎椎間盤突出開刀，但症狀未見改善。到院前三個月，他開始出現右眼皮下垂和視力模糊。他過去抽菸，一天一包達三十年之久。到院胸部X光和電腦斷層檢查如圖。多次痰液微生物顯微鏡檢和培養均為陰性。以下何者是最有可能的診斷？","options":["(A) pancoast tumor","(B) 過敏性肺部氣管麴菌感染（allergic bronchopulmonary aspergillosis）","(C) 肺膿瘍（lung abscess）","(D) 肺部動脈靜脈畸形（arterio-venous malformation of the lung）"],"answer":0,"image":"md3-105-1-1.jpeg"},{"id":"md3-105-1-2","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"85歲的陳婆婆最近3個月內跌倒了3次，還好都沒有明顯的受傷，今天來到門診做跌倒評估，醫師發現她有使用安眠藥的習慣，白內障導致她視力不佳，下肢肌力也不足，下列各項醫療建議，何者最不合適？","options":["(A) 藥物調整，減少安眠藥使用，教導正確的睡眠衛生習慣","(B) 尋求眼科醫師幫忙，考慮開刀治療白內障","(C) 利用運動與復健增加下肢肌力","(D) 服用維生素B增加下肢肌力"],"answer":3,"image":""},{"id":"md3-105-1-3","subject":"md3","topic":"內科-心臟血管","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"胡女士64歲，有糖尿病和瓣膜性心臟病病史，一週前拔牙後便開始高燒合併運動氣促，尿量減少。於急診室量得病人血壓為114/80 mmHg，體溫39℃，脈搏速128/min，呼吸速率26/min，且在病人心尖（apex）可聽到明顯之收縮期雜音，由以上初步病史與身體診察，那一個瓣膜最可能被感染？","options":["(A) 主動脈瓣","(B) 肺動脈瓣","(C) 二尖瓣","(D) 三尖瓣"],"answer":2,"image":""},{"id":"md3-105-1-4","subject":"md3","topic":"內科-心臟血管","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"65歲男性患者二週前因急性心肌梗塞住院接受冠狀動脈支架置放後出院，今日因為胸痛與輕微發燒（37.8攝氏度）而回診。沒有呼吸窘迫，肺部聽診沒有囉音，心臟沒有出現新的雜音、奔馬音（gallop）或心包摩擦音（friction rub）。初步檢查排除了感染情況，心電圖與出院之前做比較沒有變化。下列那一項治療較恰當？","options":["(A) 給予類固醇","(B) 給予高劑量aspirin","(C) 給予抗凝血劑（anticoagulant）","(D) 加重狹心症藥品（antianginal drugs）"],"answer":1,"image":""},{"id":"md3-105-1-5","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"門診來了一位52歲男性進行體檢，身高167公分，體重87公斤，平日沒有不適。身體診察發現血壓132/84毫米汞柱，心跳每分鐘72次，身體質量指數（BMI）31 kg/m2，其他身體檢查正常。在目前的血壓值所處的範圍，考慮前面的敘述，下列那一種生活型態修正對於降低血壓數值的效果最明顯？","options":["(A) 每天慢走十分鐘，每週四次","(B) 每天作息正常","(C) 減重大約九公斤","(D) 每日限鹽小於六公克"],"answer":2,"image":""},{"id":"md3-105-1-6","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"病人在門診自訴吞嚥困難已有一年之久，且常伴隨中段胸骨後方有東西卡住的感覺。吞嚥困難僅限於固態食物，喝流質東西則沒有困難。但並非每餐都會出現，時好時壞。病人也沒有體重減輕之現象。身體診察沒有異常發現。關於這位病人之診斷，下列各項敘述，何者正確？","options":["(A) 本病人之診斷，很可能是achalasia","(B) 本病人之致病機轉可能在於食道蠕動異常","(C) 鋇劑攝影（barium meal study）對本病人之診斷很有效益","(D) 此等病人雖非食道癌，其治療仍以手術為主"],"answer":2,"image":""},{"id":"md3-105-1-7","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"許先生有肝硬化合併腹水，也出現肝腦病變。最近被發現有日夜昏睡、意識不清的現象，抽血檢查發現NH3 = 110 µg/dL（normal range：19～60），下列何者不是此等病情常見的誘發因子？","options":["(A) 便秘","(B) 血鉀過高","(C) 腸胃道出血","(D) 感染"],"answer":1,"image":""},{"id":"md3-105-1-8","subject":"md3","topic":"內科-腎臟","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"69歲男性退休高中老師，沒有糖尿病史，但是有慢性腎臟病史，3年前的血液肌酸酐2.6 mg/dL。4週前打噴嚏後出現眼眶周圍紫斑，3週前腹瀉、瀝青便（tarry stool）、少尿、水腫、端坐呼吸。現在理學檢查身高160 cm，體重60 kg，肝脾明顯腫大，胸部X光心臟擴大, 兩側中心肺泡浸潤。腎臟超音波左腎長度11.5 cm，右腎長度11.0 cm，血中血色素7.5 g/dL，血中肌酸酐4.8 mg/dL，補體正常，尿液紅血球4～6/HPF，尿液蛋白質4+。下列何者是最可能的診斷？","options":["(A) 類澱粉症（amyloidosis）","(B) 冷凝球蛋白血症（cryoglobulinemia）","(C) 韋氏肉芽腫（Wegener’s granulomatosis）","(D) 全身性紅斑性狼瘡（SLE）"],"answer":0,"image":""},{"id":"md3-105-1-9","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"一位罹患僵直性脊椎炎的患者，有一天突覺左眼腫脹、怕光及視力模糊。下列何者為首選治療藥物？","options":["(A) methotrexate","(B) hydroxychloroquine","(C) local glucocorticoid administration","(D) azathioprine"],"answer":2,"image":""},{"id":"md3-105-1-10","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"63歲男性為HBV帶原者。5年前開始有兩手小關節、手腕、手肘、膝蓋及腳踝關節酸痛，抽血檢查發現RF：29.7 IU/mL（normal< 10 IU/mL），ESR：18 mm/1h，CRP：1.0 mg/dL（normal<0.8 mg/dL），ALT：62 U/L。下列何種檢查結果陽性對患者的鑑別診斷最有幫助？","options":["(A) anti-nuclear antibody","(B) anti-SSA/anti-SSB antibody","(C) anti-cyclic citrullinated peptide antibody","(D) C3 and C4"],"answer":2,"image":""},{"id":"md3-105-1-11","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"60歲的女病患主訴右膝關節腫脹及輕微疼痛已2週。抽出關節液檢驗，其外表黃色透明，黏稠度（viscosity）甚高，白血球濃度為250 cells/mm3。最適宜的診斷為何？","options":["(A) 痛風性關節炎","(B) 退化性關節炎","(C) 細菌性關節炎","(D) 乾癬性關節炎"],"answer":1,"image":""},{"id":"md3-105-1-12","subject":"md3","topic":"內科-血液","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"一位36歲女性，過去無特殊不適，亦未服用任何藥物，最近兩天出現左下肢腫脹、疼痛，經血管超音波檢查發現是深層靜脈栓塞。其周邊血檢查顯示血紅素12.1 gm/dL，白血球8750/µL，血小板123000/µL，prothrombin time INR 1.1，partial thromboplastin time 55”（control：28”），thrombin time 14.7”（control：5.1”），以下何者是最優先要做的檢查？","options":["(A) lupus anticoagulant","(B) factor VIII","(C) protein S","(D) protein C"],"answer":0,"image":""},{"id":"md3-105-1-13","subject":"md3","topic":"內科-血液","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"一位65歲男性主訴倦怠、無力，手腳有刺痛感。身體檢查發現臉色蒼白，有輕微黃疸，舌頭表面平滑，味蕾萎縮；神經學檢查顯示對振動(vibration)的感覺變差。血液檢查顯示血紅素7.2 gm/dL，平均紅血球體積110 fL，網狀紅血球1.1%，白血球2780/µL，分類正常，血小板98000/µL；全膽紅素（bilirubin）2.3 mg/dL，直接型0.5 mg/dL，AST 52 U/L（正常0～ 37），ALT 38 U/L（正常0～41），LDH 780 IU/L（正常140～271）。這位病人最可能的診斷為？","options":["(A) aplastic anemia","(B) iron deficiency anemia","(C) pernicious anemia","(D) hemolytic anemia"],"answer":2,"image":""},{"id":"md3-105-1-14","subject":"md3","topic":"內科-腫瘤","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"一位53歲家庭主婦，未曾抽菸，最近被發現有肺癌，且有肋膜侵犯及積水，無法開刀清除乾淨。其腫瘤細胞有epidermal growth factor receptor（EGFR）激活突變（activation mutation）。此時最適當的治療為？","options":["(A) gefitinib","(B) bevacizumab","(C) sunitinib","(D) trastuzumab"],"answer":0,"image":""},{"id":"md3-105-1-15","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"一位70歲男性病人因右側肋膜積液（pleural effusion）掛胸腔科門診，經胸腔超音波檢查並做肋膜積液抽吸送檢，肋膜積液分析發現白血球1280/mm3，neutrophil/lymphocyte ratio：8/92，蛋白質（protein）數值為3.8 g/dL，血清蛋白質為5.2 g/dL，細胞學檢查無惡性細胞，adenosine deaminase（ADA）為70 IU/L，在臺灣最可能的診斷是：","options":["(A) 惡性肋膜積液","(B) 結核性肋膜積液","(C) 肺炎併發肋膜積液","(D) 膿胸"],"answer":1,"image":""},{"id":"md3-105-1-16","subject":"md3","topic":"內科-感染","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"64歲男性有糖尿病和高血壓病史，五天來有發燒、寒顫、右上腹痛，無解尿困難或疼痛情形；腹部超音波發現右肝有4.5公分的異質性病灶，肝內膽道無擴大情形。需氧和厭氧血液培養瓶皆長出革蘭氏陰性桿菌。依此病況，最可能之病原菌為何？","options":["(A) Pseudomonas aeruginosa","(B) Bacteroides fragilis","(C) Enterobacter cloacae","(D) Klebsiella pneuomoniae"],"answer":3,"image":""},{"id":"md3-105-1-17","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"下列有關評估營養狀態之敘述，何者錯誤？","options":["(A) blood urea nitrogen（BUN）若低於8 mg/dL，代表蛋白質的攝取可能不足","(B) serum creatinine若低於0.6 mg/dL，代表因長期能量攝取不足而肌肉耗損（muscle wasting）","(C) prothrombin time延長，表示可能有維生素K缺乏","(D) serum total iron binding capacity（TIBC）> 500 µg/dL代表蛋白質攝取不足，可能有惡性營養不良（kwashiorkor）"],"answer":3,"image":""},{"id":"md3-105-1-18","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"一位因中風長期臥床之病友，平日由看護自製流質飲食經鼻胃管餵食。一個月前更換看護後，家人發現病友尾骶骨（sacrum）附近長出一個直徑3公分之壓瘡（pressure sore）。一個月來雖然每日早晚擦藥治療、勤於翻身，傷口反而擴大為直徑8公分。此病友最不可能缺乏下列何種營養素？","options":["(A) 維生素A","(B) 維生素C","(C) 鋅","(D) 蛋白質"],"answer":0,"image":""},{"id":"md3-105-1-19","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"下列有關吸煙之敘述，何者錯誤？","options":["(A) 吸煙者相較於未吸煙者，罹患胰臟癌與膀胱癌之風險較高","(B) 吸煙會減緩theophylline、propranolol、oxazepam等藥之代謝速率，吸煙者使用此等藥物宜減量","(C) 吸二手煙之小孩相較於未吸煙者，易發生中耳積水（effusion）與氣喘","(D) 吸煙者相較於未吸煙者，使用口服避孕藥更容易發生缺血性中風與心肌梗塞之不良反應"],"answer":1,"image":""},{"id":"md3-105-1-20","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"有一位急性中風病友四肢完全癱瘓，肌力為0分，也無法說話，但雙眼可依指令睜眼或閉眼。為此病友評估昏迷指數（Glasgow coma scale）時，運動反應（motor response）之得分為幾分？","options":["(A) 0","(B) 1","(C) 5","(D) 6"],"answer":3,"image":""},{"id":"md3-105-1-21","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"一位酗酒的病人有神經病變、肌肉無力、心臟肥大、水腫，給予下列何種維生素最可能對病情有幫助？","options":["(A) thiamine","(B) riboflavin","(C) niacin","(D) folate"],"answer":0,"image":""},{"id":"md3-105-1-22","subject":"md3","topic":"內科-心臟血管","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"下列何種藥物，非例行使用於治療非ST節段上升急性冠心症（non-ST elevation acute coronary syndrome）的病患？","options":["(A) 抗血小板藥物（aspirin，clopidogrel）","(B) 靜脈注射硝酸鹽（nitrate）","(C) 血栓溶解劑（fibrinolytic agent）","(D) 靜脈注射肝素（heparin or low molecular weight heparin）"],"answer":2,"image":""},{"id":"md3-105-1-23","subject":"md3","topic":"內科-心臟血管","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"對於急性心肌梗塞的患者，考慮給予血栓溶解藥物（fibrinolytic agents，如tPA）時，下列那一項不是絕對禁忌症？","options":["(A) 年齡超過75歲","(B) 曾有過腦出血病史","(C) 血壓超過180/110毫米汞柱","(D) 最近3個月曾有梗塞性腦中風病史"],"answer":0,"image":""},{"id":"md3-105-1-24","subject":"md3","topic":"內科-心臟血管","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"僧帽瓣狹窄（mitral valve stenosis）最常見的心律不整為：","options":["(A) 心房早期收縮（atrial premature contraction）","(B) 心室早期收縮（ventricular premature contraction）","(C) 心房顫動（atrial fibrillation）","(D) 心房撲動（atrial flutter）"],"answer":2,"image":""},{"id":"md3-105-1-25","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"70歲女性因食慾變差、上腹不適、體重減輕，接受胃鏡檢查，結果如圖，下列敘述何者正確？","options":["(A) 此疾病目前的發生率增加中","(B) 去除幽門螺旋桿菌可以治癒此疾病","(C) O型血型者罹患此病機會較高","(D) 腸化生（intestinal metaplasia）為此病之前驅病灶（precursor lesion）"],"answer":3,"image":"md3-105-1-25.jpeg"},{"id":"md3-105-1-26","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"下列何者不會產生腹水？","options":["(A) 肥胖","(B) 肝硬化","(C) 心臟衰竭","(D) 腹膜發炎"],"answer":0,"image":""},{"id":"md3-105-1-27","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"一位50歲男性，近日無使用任何藥物，日前接受國民健康保險局推行之定量免疫法糞便潛血檢驗後，接到通知告知其糞便呈現陽性潛血反應，則以下的各種情形何者的建議正確？ ①若患者於檢驗前三天內曾進食富含動物血色素食物，可能造成偽陽性，建議重新檢驗 ②若患者無排便異常情形，可觀察並建議2年後再檢驗一次 ③患者自述於檢驗前一天曾有流鼻血情形，可能因此而陽性，建議重新檢驗 ④若患者告知半年前曾自費接受相同檢查，但報告為陰性，建議仍須接受大腸鏡檢查或大腸攝影檢查","options":["(A) ①②③④","(B) 僅①③④","(C) 僅①②","(D) 僅④"],"answer":3,"image":""},{"id":"md3-105-1-28","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"下列那些藥物可能會加重逆流性食道炎（reflux esophagitis）？①降血脂藥（HMG-CoA reductase inhibitor） ②高血壓用藥（calcium channel blocker） ③氣喘用藥（theophylline） ④抗過敏藥物（antihistamine）","options":["(A) ①②③","(B) 僅②③","(C) ③④","(D) ①②④"],"answer":1,"image":""},{"id":"md3-105-1-29","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"一位34歲男性病人，因急性上腹痛至急診室求診。病人有長期飲酒史，父親有大腸癌之家族史。身體診察顯示病人無發燒、無腹瀉、無輻射性疼痛，但有輕微冒冷汗，身體向前傾可減輕疼痛，上腹有廣泛性觸痛，無shifting dullness。下列何者並非對此病人所須之第一線血液檢查？","options":["(A) ALT（GPT），AST（GOT）","(B) WBC","(C) amylase","(D) CEA"],"answer":3,"image":""},{"id":"md3-105-1-30","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"一位42歲女性病人之血液報告呈現HBsAg：陽性、anti-HBs antibody IgG：陽性。下列何者之判斷最合理？","options":["(A) 此病人仍為B型肝炎帶原者","(B) 此病人非B型肝炎帶原者，因為已有陽性之anti-HBs","(C) 實驗檢驗錯誤，HBsAg與anti-HBs不可能均為陽性","(D) 宜加作anti-HBc antibody（anti-HBc），才可作判定"],"answer":0,"image":""},{"id":"md3-105-1-31","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"有關自發性細菌性腹膜炎的敘述，下列何者錯誤？","options":["(A) 最常見的細菌感染為Escherichia coli","(B) 腹水感染二種以上細菌，要考慮續發性腹膜炎（如腸穿孔）的可能性","(C) 病人可能無發燒及腹痛","(D) 肝硬化合併腹水的病人，發生食道靜脈曲張出血時，不會增加自發性細菌性腹膜炎的發生"],"answer":3,"image":""},{"id":"md3-105-1-32","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"下列有關下消化道出血的敘述，何者錯誤？","options":["(A) 出血源不明（obscure）的消化道出血，病變常在小腸，須先排除上消化道及大腸直腸病變。因此上消化道內視鏡及大腸鏡檢查一定要施行，甚至不只檢查一次即足夠","(B) 嚴重的出血病例可以安排血管攝影檢查（angiography），找到出血源時可注射vasopressin或以血管栓塞（embolization）止血","(C) 核醫紅血球掃描（RBC scan），偵測出血較血管攝影術敏感，可以精確定位，幫助治療","(D) 如無活動性出血，除非是血管豐富（hypervascular）的腫瘤或是血管發育不良（angiodysplasia），否則血管攝影術幫助不大"],"answer":2,"image":""},{"id":"md3-105-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"下列何者免疫抑制劑與FKBP-12接合，可減少IL-2之產生？","options":["(A) cyclosporine","(B) tacrolimus","(C) mycophenolate mofetil","(D) sirolimus"],"answer":1,"image":""},{"id":"md3-105-1-34","subject":"md3","topic":"內科-腎臟","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"一位55歲女性病人，過去無腎臟病史，因最近一週尿量漸減且體重增加而住院。身體診察：血壓180/110 mmHg，脈搏72/min，呼吸次數16/min，呼吸音正常，心律規則無雜音，腹部平坦無壓痛，下肢有顯著壓陷性水腫。血液檢查：血紅素10 gm/dL，白血球10500 /µL，白蛋白2.5 g/dL，尿素氮35 mg/dL，肌酸酐3.0 mg/dL；尿液檢查：蛋白質（3+），紅血球20 ～25顆/高倍視野，並可見到紅血球圓柱體。本病人接受腎臟切片檢查後，最適當治療方式為？","options":["(A) 廣效性抗生素（broad-spectrum antibiotics）","(B) 免疫抑制劑（immunosuppressive therapy）","(C) 緊急血液透析（emergent hemodialysis）","(D) 補充白蛋白（albumin infusion）"],"answer":1,"image":""},{"id":"md3-105-1-35","subject":"md3","topic":"內科-腎臟","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"下列藥物可能引起急性腎臟損傷，而主要的作用是腎血管的影響，何者例外？","options":["(A) 非類固醇消炎劑（nonsteroidal anti-inflammatory drugs）","(B) 血管張力素阻斷劑（angiotensin-converting enzyme inhibitors）","(C) 含鉑的抗癌製劑（如cisplatin）","(D) 腎素抑制劑（renin inhibitors）"],"answer":2,"image":""},{"id":"md3-105-1-36","subject":"md3","topic":"內科-腎臟","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"有關腹膜透析和血液透析的優劣點，下列何者錯誤？","options":["(A) 血液透析對於超過濾（ultrafiltration）的控制比較正確","(B) 腹膜透析比較容易發生血脂肪升高","(C) 血液透析比較常有白蛋白流失","(D) 腹膜透析比較容易有低血鉀情況"],"answer":2,"image":""},{"id":"md3-105-1-37","subject":"md3","topic":"內科-腎臟","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"有關angiotensin-converting enzyme inhibitors的腎臟保護作用，下列何者錯誤？","options":["(A) 可以降低血壓","(B) 可以降低蛋白尿","(C) 可以增加腎絲球過濾速率","(D) 可以降低出球小動脈的壓力"],"answer":2,"image":""},{"id":"md3-105-1-38","subject":"md3","topic":"內科-腎臟","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"一位52歲男性因反覆發生下肢癱瘓入院，血壓168/98 mmHg，血液檢查發現：鈉146 mmol/L，鉀2.0 mmol/L，氯100 mmol/L，酸鹼值7.56，重碳酸根38 mmol/L，腎素（renin）0.1 ng/mL/hr（正常值0.3～3 ng/mL/hr），血清醛固酮（aldosterone）8 ng/dL（正常值2～9 ng/dL）；則下列敘述何者錯誤？","options":["(A) 病患為留鹽激素過多狀態（mineralocorticoid excess state）","(B) 應補充大量鉀離子直到病患肌肉力量恢復","(C) 因血清腎素偏低，可以排除腎素分泌腫瘤（renin-secreting tumor）及續發性高醛固酮症","(D) 因血清醛固酮正常，可以排除原發性高醛固酮症"],"answer":3,"image":""},{"id":"md3-105-1-39","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"55歲男性，有下背痛伴隨晨間僵硬（＞30分鐘）已有兩年，骨盆X光無明顯異常，病患曾有左跟踺（Achilles tendon）發炎病史，以目前病情判斷，何種疾病最有可能？","options":["(A) 僵直性脊椎炎（ankylosing spondylitis）","(B) 中軸脊椎關節炎（axial spondyloarthropathy）","(C) 退化性關節炎（osteoarthritis）","(D) 乾癬性關節炎（psoriatic arthritis）"],"answer":1,"image":""},{"id":"md3-105-1-40","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"下列對於全身性紅斑性狼瘡（SLE）病人血清中的各種自體抗體的描述，何者最為正確？","options":["(A) anti-RNP對於診斷SLE的特異性最高","(B) anti-histone抗體與SLE的腎炎最有相關","(C) anti-Sm與SLE的psychosis最有相關","(D) anti-phospholipid與habitual fetal loss最有相關"],"answer":3,"image":""},{"id":"md3-105-1-41","subject":"md3","topic":"內科-腫瘤","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"一位65歲女性10年前停經後得到第一期乳癌，只以外科治療。最近發現蝕骨性骨骼病灶，證實為乳癌轉移ER+，HER2-negative，此外無其他臟器轉移，下列何者為最適當的治療？","options":["(A) 芳香環轉化酶抑制劑+雙磷酸鹽","(B) 多種藥劑化學治療 +雙磷酸鹽","(C) capecitabine +雙磷酸鹽","(D) 單一藥劑化學治療 +strontium-89"],"answer":0,"image":""},{"id":"md3-105-1-42","subject":"md3","topic":"內科-血液","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"下列何種病人發生缺鐵性貧血的機會最小？","options":["(A) gastrectomy","(B) menorrhagia","(C) paroxysmal nocturnal hemogblobinuria","(D) thalassemia"],"answer":3,"image":""},{"id":"md3-105-1-43","subject":"md3","topic":"內科-血液","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"以下何者被視為造血幹細胞（hematopoietic stem cell）最重要的特徵？","options":["(A) 自我更新（self-renewal）","(B) 增殖（proliferation）","(C) 分化（differentiation）","(D) 計畫凋亡（programmed death）"],"answer":[0,2],"image":"","answer_note":"更正:第43題答Ａ、Ｃ給分"},{"id":"md3-105-1-44","subject":"md3","topic":"內科-血液","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"一位30歲平常健康良好的男性，主訴2～3週來易倦。理學檢查發現結膜蒼白無黃疸、頸部兩側多個不足一公分大小淋巴結、無肝脾腫大，下肢出現無癢紅色細小斑點；末梢血檢查結果顯示：WBC 1280/µL，N/L/Mo = 5/94/1，Hb 7.5 gm/dL，MCV 86 fL，Platelet 8,000/µL，ALT 42 U/L，T. Bil 0.6 mg/dL，Cr 1.1 mg/dL，Alb 3.7 g/dL。下列何種檢驗最有利於正確診斷？","options":["(A) 淋巴結切片（biopsy）","(B) 正子造影（positron emission tomography, PET）","(C) 骨髓切片","(D) 血液培養（blood culture）"],"answer":2,"image":""},{"id":"md3-105-1-45","subject":"md3","topic":"內科-血液","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"cyclosporine-A（CsA）是異體造血幹細胞移植（allogeneic hematopoietic stem cell transplantation）用來預防移植物反宿主疾病（graft-versus-host disease）的重要免疫抑制劑，下列何者不是CsA常見的副作用？","options":["(A) hypertension","(B) hyperlipidemia","(C) hyperglycemia","(D) nephrotoxicity"],"answer":2,"image":""},{"id":"md3-105-1-46","subject":"md3","topic":"內科-腫瘤","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"下列何者為抗癌化學藥物cisplatin之副作用？","options":["(A) 血鈣過高症","(B) 血鎂過低症","(C) 血鈉過低症","(D) 血氯過高症"],"answer":[1,2],"image":"","answer_note":"更正:第46題答Ｂ、Ｃ給分"},{"id":"md3-105-1-47","subject":"md3","topic":"內科-血液","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"凝血因子X（coagulation factor X）活化為Xa的反應中，下列何因子沒有參與？","options":["(A) factor Va","(B) factor VIIa","(C) factor VIIIa","(D) factor IXa"],"answer":0,"image":""},{"id":"md3-105-1-48","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"胸部電腦斷層發現毛玻璃狀病灶（ground glass opacity, GGO），有關其臨床意義的敘述，下列何者錯誤？","options":["(A) 有可能是早期adenocarcinoma","(B) 有可能是atypical adenomatous hyperplasia","(C) 如果是solid GGO，很可能是慢性發炎，定期追蹤即可","(D) 有可能是肺腺癌的前身，應積極正確診斷"],"answer":2,"image":""},{"id":"md3-105-1-49","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"60歲男性，主述長期咳痰，呼吸不暢，最近有關節痠痛症狀。身體檢查時看到杵狀指（clubbing fingers）。下列那些疾病應優先列入鑑別診斷？①肺癌 ②急性肺炎 ③支氣管擴張症 ④先天性心臟病 ⑤肝硬化 ⑥克隆氏症（Crohn’s disease）","options":["(A) ①②③④⑤⑥","(B) 僅③④⑤⑥","(C) 僅②④⑤⑥","(D) 僅①③⑤"],"answer":3,"image":""},{"id":"md3-105-1-50","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"肺癌患者出現下列何種表徵時，仍可考慮接受根除性手術治療？","options":["(A) 咳血","(B) 腫瘤侵犯造成上腔靜脈症候群（superior vena cava syndrome）","(C) 腫瘤或淋巴腺壓迫造成聲帶麻痺、聲音沙啞","(D) 惡性肋膜積水"],"answer":[0,1],"image":"","answer_note":"更正:第50題答Ａ、Ｂ給分"},{"id":"md3-105-1-51","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"下列關於theophylline在慢性阻塞性氣道疾病（chronic obstructive airway disease）的治療敘述，何者錯誤？","options":["(A) 抽煙與喝酒會增加theophylline的代謝","(B) 支氣管擴張效果主要來自於抑制呼吸道平滑肌之phosphodiesterase","(C) 低劑量theophylline有抗發炎效果，主要是直接抑制細胞核內histone deacetylase-2的活性","(D) 做為附加（add-on）治療，效果比吸入型長效性乙二型增效劑（long acting β2-agonist）弱"],"answer":2,"image":""},{"id":"md3-105-1-52","subject":"md3","topic":"內科-腫瘤","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"下列關於胸腺惡性腫瘤（malignant thymoma）的敘述，何者錯誤？","options":["(A) 最常見於前縱膈腔，好發於中年者，男女約各半","(B) 約有1/3合併重症肌無力","(C) 有心包膜（pericardium）或肋膜（pleura）侵犯時，治療以手術切除合併化學治療為主","(D) 重症肌無力患者實施胸腺切除手術，會比單獨內科治療有較高的症狀緩解率"],"answer":2,"image":""},{"id":"md3-105-1-53","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"一位68歲男性病患抽菸50年，10年前開始咳嗽且有黃痰，5年前開始出現運動性呼吸困難，最近3年有6次因為嚴重呼吸困難住院治療，其中4次被診斷為細菌性肺炎。本次住院在急診動脈血呈現PaO2 = 45 mmHg，PaCO2 = 70 mmHg，Resp. Rate = 30/min，病患被放置氣管內管後使用呼吸器（ventilator）來維持呼吸。住院後一星期病患出現發燒、黃痰增多，胸部X光片於右下肺葉出現新的浸潤，痰液培養為Pseudomonas aeruginosa，下列敘述何者錯誤？","options":["(A) 診斷可為ventilator-associated pneumonia","(B) 應該再輔以bronchoalveolar larvage或protected brush取得distal airways的檢體做quantitative culture來證明為Pseudomonas aeruginosa感染","(C) 使用monotherapy時aminoglycoside是首選有效的藥物","(D) tobramycin（300 mg）inhaled daily可以提供氣管支氣管mucosa有效的drug-level，是施行抗生素吸入治療的推薦藥物"],"answer":2,"image":""},{"id":"md3-105-1-54","subject":"md3","topic":"內科-胸腔","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"下列對於支氣管性氣喘的特性敘述，何者錯誤？","options":["(A) 支氣管反應過度（hyperresponsiveness）","(B) 陣發性產生呼吸困難、咳嗽或是哮鳴音","(C) 最常見之危險因子（risk factor）是過敏","(D) 因過敏性產生氣喘，常容易發生於40歲以後"],"answer":3,"image":""},{"id":"md3-105-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"下列何種病因，並非造成第二型糖尿病主要致病機轉？","options":["(A) 胰島素阻抗性","(B) 胰島素分泌不足","(C) 昇糖激素分泌不足","(D) 游離脂肪酸過多"],"answer":2,"image":""},{"id":"md3-105-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"關於遺傳學原理應用於臨床醫學上之敘述，下列何者錯誤？","options":["(A) 粒線體基因突變造成之疾病為父系遺傳（paternal transmission）","(B) 對於單基因孟德爾式遺傳疾病（monogenic Mendelian disorders），遺傳模式（mode of inheritance）一般以族譜分析（pedigree analysis）決定之","(C) 基因體印記（genomic imprinting）現象，會使某些疾病遺傳模式不符單基因孟德爾式遺傳模式","(D) 複雜性遺傳疾病（complex genetic disorders），其臨床表現易受環境因素所影響"],"answer":0,"image":""},{"id":"md3-105-1-57","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"關於肥胖（obesity）之敘述，下列何者錯誤？","options":["(A) 在臺灣，肥胖的定義是身體質量指數（BMI）大於等於30 Kg/m2","(B) 在臺灣，腹部肥胖的定義是女性腰圍大於80 cm，男性大於90 cm","(C) 肥胖很常見於Cushing’s syndrome","(D) craniopharyngioma會引發多食症而造成肥胖"],"answer":0,"image":""},{"id":"md3-105-1-58","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"關於非自主體重減輕（involuntary weight loss）之敘述，下列何者錯誤？","options":["(A) 一般臨床上有意義之體重減輕，定義為在6～12個月內，體重減輕＞5%","(B) 只有第一型糖尿病患控制不佳時，會有體重減輕；第二型糖尿病患控制不佳時仍多肥胖，不會體重減輕","(C) 病患沒有刻意節食或運動減重","(D) 合併有心悸或高血壓時，要考慮甲狀腺機能亢進或嗜鉻細胞瘤"],"answer":1,"image":""},{"id":"md3-105-1-59","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"下列那一種口服降血糖藥可能引起乳酸血症？","options":["(A) metformin","(B) sitagliptin","(C) pioglitazone","(D) acarbose"],"answer":0,"image":""},{"id":"md3-105-1-60","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"下列那一項是調控arginine vasopressin（AVP）增加分泌最重要的機制？","options":["(A) 下視丘的osmoreceptors感受血液滲透壓的增加","(B) 心臟的壓力感受器（pressure receptors）感受血液容積或血壓的下降","(C) 噁心或嘔吐刺激髓腦的催吐中樞（emetic center in the medulla）","(D) 血管升壓素（angiotensin）增加"],"answer":0,"image":""},{"id":"md3-105-1-61","subject":"md3","topic":"內科-感染","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"病毒性出血熱可能隨著國際旅遊而傳播，下列何者死亡率最高？","options":["(A) Hantavirus","(B) Ebola virus","(C) Dengue virus","(D) Yellow fever"],"answer":1,"image":""},{"id":"md3-105-1-62","subject":"md3","topic":"內科-感染","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"下列關於cephalosporin用於治療細菌感染之敘述，何者正確？","options":["(A) 第一代cephalosporin可治療沙門氏桿菌（Salmonella）感染","(B) 第二代cephalosporin可治療腸球菌（Enterococcus）感染","(C) 第三代cephalosporin可治療克雷白氏桿菌（Klebsiella）腦膜炎","(D) 第三代cephalosporin可治療李斯德菌（Listeria）腦膜炎"],"answer":2,"image":""},{"id":"md3-105-1-63","subject":"md3","topic":"內科-感染","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"退伍軍人菌（Legionella）肺炎若有適當痰液可供革蘭氏染色，則最不易有下列何種發現？","options":["(A) 每低倍鏡視野WBC多於25","(B) 每低倍鏡視野上皮細胞少於10","(C) 痰中細菌極少","(D) 痰中易看到細長之革蘭氏陰性桿菌"],"answer":3,"image":""},{"id":"md3-105-1-64","subject":"md3","topic":"內科-感染","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"梅毒血清檢驗包括nontreponemal tests（如VDRL或RPR test），及treponemal tests（如FTA-ABS test，TP-PA test或TPHA）。下列敘述何者錯誤？","options":["(A) 大規模篩檢建議用VDRL或RPR test","(B) 確定診斷建議用FTA-ABS test，TP-PA test或TPHA","(C) 評估治療反應建議用FTA-ABS test，TP-PA test或TPHA","(D) 診斷神經性梅毒，腦脊髓液建議用VDRL檢查"],"answer":2,"image":""},{"id":"md3-105-1-65","subject":"md3","topic":"內科-感染","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"一位26歲男性病人發生腸道感染，下列何種情形不須使用抗微生物製劑治療？","options":["(A) nontyphoidal salmonellosis","(B) giardiasis","(C) 有發燒和血便現象之traveler’s diarrhea","(D) 病人有發燒及糞便中很多白血球"],"answer":0,"image":""},{"id":"md3-105-1-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"60歲女性因血壓較高至門診追蹤，無其它異常。平日不抽菸，每日睡前喝紅酒30 mL。父親死於腦中風、母親有糖尿病。血壓170/100 mmHg，身體質量指數（BMI）27.1 kg/m2。應建議她如何作生活型態改變？","options":["(A) 應減輕體重","(B) 每日鈉攝取量應低於6 gm","(C) 每日酒精攝取量應降低","(D) 生活型態對血壓的影響，目前尚無實證支持"],"answer":0,"image":""},{"id":"md3-105-1-67","subject":"md3","topic":"內科-心臟血管","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"一位35歲男性，初次被診斷為高血壓，血壓為140/96 mmHg，脈搏為70拍/分，病人並無任何症狀，過去亦無特殊病史，理學檢查除血壓高之外，並無特殊異常發現。下列何者不是初步評估此病人所需安排之檢查？","options":["(A) 尿液常規檢查","(B) 鉀離子","(C) 甲狀腺刺激素","(D) 空腹血糖"],"answer":2,"image":""},{"id":"md3-105-1-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"有一位妊娠32週的孕婦前來接受產前檢查，醫師除了要問診本胎不適症狀、過去孕產史、家庭疾病史及進行身體檢查外，還需要安排實驗室檢查。下列那項檢查是此懷孕時程所必需安排的？","options":["(A) 甲狀腺功能","(B) 葡萄糖-6-磷酸去氫酶（蠶豆症檢查）","(C) 口服葡萄糖耐性試驗","(D) B型肝炎表面抗原檢查"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第68題一律給分。 (原公告答案 D)"},{"id":"md3-105-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"有關大腸癌各項篩檢方式的敘述，下列何者正確？","options":["(A) 大便潛血反應的特異性約可達80-90%","(B) 少於10%的大腸直腸癌可藉由肛門指診摸到","(C) 乙狀結腸鏡檢查（sigmoidoscope）可發現超過90%的大腸直腸癌","(D) 大腸鏡檢查（colonoscope）對發現小息肉的敏感度可達95%以上"],"answer":1,"image":""},{"id":"md3-105-1-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"50歲男性高血壓患者，本次回診時告訴醫師，有一位自然療法的朋友告訴他「每天吃玉米可以降血壓」，他生活的社區中也有許多人在使用，他解釋高血壓是「熱」的疾病，而玉米是「冷」的食物。假設吃玉米對此病人健康沒有危害，下列何者是醫師最適當的回應？","options":["(A) 「吃玉米不能降血壓，如果你堅持吃玉米，我無法繼續提供治療。」","(B) 「你那位朋友有接受過醫學訓練嗎？」","(C) 「那就先試吃玉米且暫停降血壓藥，等一個月後，如果血壓仍高，我再開降血壓藥給你。」","(D) 「藥物可以有效的降血壓，你可以跟玉米一起使用。」"],"answer":3,"image":""},{"id":"md3-105-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"林醫師是H鎮的衛生所主任，他依據Sidney Kark社區導向之基層醫療（community-oriented primary care）作H鎮的青少年吸菸防治工作；調查發現H鎮的青少年吸菸由國中時開始。經過與鎮民代表商議後，選擇某國中為試辦對象；林醫師下一步的工作為何？","options":["(A) 界定社區的範圍","(B) 利用流行病學方法找尋健康問題","(C) 擬定解決健康問題之方案","(D) 邀請社區參與評估"],"answer":2,"image":""},{"id":"md3-105-1-72","subject":"md3","topic":"家醫-緩和醫學","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"一位55歲男性患有肺癌及全身骨轉移，已使用高量嗎啡，病人仍感受無法忍受的不適，要求醫師讓他睡著就好了，下列那一項是不當的敘述？","options":["(A) 使用更高量的嗎啡止痛","(B) 給予足量的鎮靜劑協助病人入睡","(C) 給予鎮靜劑或止痛劑可能會影響病人的呼吸","(D) 若給予藥物後病人可能會死亡，等於是給病人安樂死，故不宜再給藥"],"answer":3,"image":""},{"id":"md3-105-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"下列何者不是安寧緩和醫療中常用的鎮靜或止痛藥物？","options":["(A) Morphine","(B) Demerol（pethidine, meperidine）","(C) Dormicum（midazolam）","(D) Valium（diazepam）"],"answer":1,"image":""},{"id":"md3-105-1-74","subject":"md3","topic":"影像醫學","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"病人主訴胸骨後和上腹部疼痛且食慾不佳，胸部X光檢查呈現如圖，下列那一項診斷最正確？","options":["(A) hiatal hernia","(B) aortic dissection","(C) myocardial infarction","(D) pneumomediastinum"],"answer":0,"image":"md3-105-1-74.jpeg"},{"id":"md3-105-1-75","subject":"md3","topic":"急診醫學","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"一位體重50公斤有C型肝炎及憂鬱症病史之中年婦人，與丈夫吵架後服用36顆500mg之普拿疼（acetaminophen）企圖自殺，2小時後出現噁心、嘔吐、全身乏力的症狀，丈夫立刻將其妻子送醫治療。病人抵達急診時血壓、呼吸、心跳、體溫正常，意識清楚可交談。病人自述嘔吐完後，精神已經較佳，下列處置何者最不恰當？","options":["(A) 考慮給予acetylcysteine","(B) 口服活性碳（activated charcoal）","(C) 檢測血中鉀離子濃度","(D) 保守觀察，不需進一步處理"],"answer":3,"image":""},{"id":"md3-105-1-76","subject":"md3","topic":"急診醫學","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"針對突發性心跳停止病人，使用治療性低溫療法，下列何者是最佳適應症（indication）？","options":["(A) 初始心律為心室顫動（ventricular fibrillation），急救後病人神智恢復","(B) 初始心律為心搏停止（asystole），急救後病人神智恢復","(C) 初始心律為心室顫動（ventricular fibrillation），急救後病人神智昏迷","(D) 初始心律為無脈搏電氣活動（pulseless electrical activity），急救後病人神智昏迷"],"answer":2,"image":""},{"id":"md3-105-1-77","subject":"md3","topic":"急診醫學","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"對於急性氣喘發作，下列何者藥物不是第一線的治療選項？","options":["(A) β-2 Adrenergic agents","(B) Anticholinergics","(C) Corticosteroids","(D) Theophylline"],"answer":3,"image":""},{"id":"md3-105-1-78","subject":"md3","topic":"急診醫學","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"你目睹一位約30歲女性跳河自殺，經救起後發現無意識與呼吸，於是開始幫她做心肺復甦術（cardiopulmonary resuscitation）。依照2010版美國心臟醫學會指引（American Heart Association guidelines），做心肺復甦術時胸部按壓與吹氣做幾個循環後需再確認脈搏？","options":["(A) 5個循環","(B) 10個循環","(C) 隨時可再確認","(D) 待病人有呼吸時"],"answer":0,"image":""},{"id":"md3-105-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"陳姓老翁1個月前因為罹患胰臟癌末期而簽署了安寧緩和醫療意願書，希望病危的時候可以放棄急救。3天前，陳老先生出現發燒、頻尿的情況，而被送往醫院救治，經過醫師的診察確認陳老先生為尿路感染合併敗血症，陳老先生於住院中因為血壓不穩，經過輸液治療而導致肺水腫，醫師建議進行氣管插管併用呼吸器治療，以緩解其肺水腫。此時是否應同意陳老先生接受插管？","options":["(A) 反對，因為陳老先生已經簽署了安寧緩和醫療意願書，不應該違反其意願而為其插管","(B) 反對，因為陳老先生為胰臟癌末期，不要再進行過於侵入性的治療，免得增加其痛苦","(C) 贊成，雖然陳老先生為胰臟癌末期，也簽署了安寧緩和醫療意願書，但本次住院的原因為泌尿道感染合併敗血症，並非不可治癒的疾病，醫師應該為其插管治療","(D) 贊成，雖然陳老先生為胰臟癌末期，也簽署了安寧緩和醫療意願書，但只要屬於病危的患者，均應該依醫師法定急救義務而加以急救"],"answer":2,"image":""},{"id":"md3-105-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"甲醫師受邀到藥廠所贊助的研討會擔任講師，支領鐘點費5,000元，擔心有利益衝突的問題。有關利益衝突的敘述與處理，下列何者錯誤？","options":["(A) 有效處理利益衝突第一個要件，就是察覺其存在","(B) 公開是處理利益衝突的金科玉律","(C) 核准與審核，也是處理利益衝突的方式之一","(D) 利益衝突本身就不道德，應全面禁止"],"answer":3,"image":""},{"id":"md3-105-2-1","subject":"md3","topic":"內科-感染","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"40歲女性，過去身體健康，因為近二日來說話不清楚、吞嚥困難和兩眼皮無法全張開，症狀逐漸加劇，來急診就醫。來院前五日她和媽媽與先生三人吃了路邊攤購買的素食豆干後，開始出現腹瀉、嘔吐和腹痛，後續發生前述症狀，同時，病患也逐漸出現近端肢體、顏面肌肉和呼吸無力。來院當日，媽媽和先生也開始出現類似的病症。理學檢查發現病患意識清楚，沒有發燒，心跳和血壓正常，但是呼吸較淺且費力；神經學檢查發現深部肌腱反射（deep tendon reflex）降低。最有可能的診斷為何？","options":["(A) Guillain-Barré syndrome due to campylobacteriosis","(B) tetanus","(C) botulism","(D) Lambert-Eaton syndrome"],"answer":2,"image":""},{"id":"md3-105-2-2","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"胡小姐44歲，無過往心臟病病史，主訴突發性心悸。於急診室病人意識清楚，血壓為104/60 mmHg，心電圖顯示心律不整，經施打adenosine後恢復正常竇性心律，以下何心電圖最可能是胡小姐的心律不整？","options":["(A) ","(B) ","(C) ","(D) "],"answer":1,"image":"md3-105-2-2.jpeg"},{"id":"md3-105-2-3","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"一位64歲有心肌梗塞及鬱血性心臟衰竭的男性病人，平躺休息時沒有症狀，但他表示每天當他以平常的方式洗澡之後，就覺得很累、胸悶及心跳變快，要坐在椅子上休息數分鐘之後才能接著吹乾頭髮。若依紐約心臟學會的心衰竭功能分級（New York Heart Association Functional Classification），他目前屬於第幾級？","options":["(A) 第一級","(B) 第二級","(C) 第三級","(D) 第四級"],"answer":2,"image":""},{"id":"md3-105-2-4","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"張先生被家屬送來急診室，他們只知道張先生因心情不好，吞了一大把頭痛藥（acetaminophen）後就一直噁心、嘔吐、全身倦怠無力。抽血檢查結果如下：alanine aminotransferase（ALT）：894 U/L（normal：0～40）；aspartate aminotransferase（AST）：720 U/L（normal：5～45）；total bilirubin：2.2 mg/dL（normal：0.2～1.6）；direct bilirubin：1.8 mg/dL（normal：0～0.3）；alkaline phosphatase（ALK-P）：42 U/L（normal：10～100）；gamma-glutamyl transpeptidase（γ- GT）：50 U/L（normal：6～60）。關於此藥物引起之傷害，何者最不正確？","options":["(A) 這是一種與劑量（dose dependent）有關的肝傷害","(B) 血中藥物濃度與肝傷害嚴重度相關","(C) 張先生如未發生肝衰竭，日後還是會演變成慢性肝病","(D) 可能引起腎衰竭"],"answer":2,"image":""},{"id":"md3-105-2-5","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"一位30歲男性，因為最近被發現有黃疸而就醫，抽血檢查結果：total bilirubin 6mg/dL（正常值：0.2～1.6）、direct bilirubin 1.5mg/dL（正常值：0～0.3）、urine routine bilirubin (+)。以下描述何者錯誤？","options":["(A) 病史詢問，應著重藥物史及溶血性疾病等","(B) 身體診察可能發現脾臟腫大","(C) ineffective erythropoiesis或Gilbert's syndrome也可能是本病人之病因","(D) 尿液中，所測到之bilirubin是unconjugated bilirubin"],"answer":3,"image":""},{"id":"md3-105-2-6","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"一位40歲病人原來腎功能正常，現其血肌酸酐（creatinine）上升至2.1 mg/dL，下列何種狀況最可判斷此病人傾向腎因性急性腎衰竭，而不是腎前性（prerenal）急性腎衰竭？","options":["(A) 尿中出現透明圓柱體（hyaline casts）","(B) 血中尿素氮（BUN）48 mg/dL","(C) 尿鈉（Na）濃度為8 mmol/L","(D) 尿鈉排泄分率（fractional excretion of sodium, FeNa）為2%"],"answer":3,"image":""},{"id":"md3-105-2-7","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"下列有關糖尿病腎病變之敘述，何者錯誤？","options":["(A) 蛋白尿或微蛋白尿不會出現於新診斷第二型糖尿病病人","(B) 病理上的變化如腎絲球基底膜變厚及腎小球內基質（mesangium）擴張是常見的","(C) 使用腎素－血管張力素系統（renin-angiotensin system）阻斷劑","(D) 國內目前每年進入透析的新病人其原發病因以糖尿病腎病變占第一位"],"answer":0,"image":""},{"id":"md3-105-2-8","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"一位34歲類風濕關節炎患者兩手PIP及MCP joints有腫脹，腕關節有腫脹及活動受限，兩側肘關節有腫脹及變形。ESR：83 mm/1h，CRP：5.36 mg/dL（normal < 0.8 mg/dL），RF：635 IU/mL（normal<10 IU/mL），經以methotrexate 15 mg/week+salfasalazine 500 mg QID及prednisolone 10 mg QD治療約半年無顯著效果，下一步應該選擇何種治療藥物最為恰當？","options":["(A) anti-TNF-α","(B) IL-1 receptor antagonist","(C) prednisolone 1000 mg/day pulse therapy for 3 days","(D) anti-pyrimidine agent"],"answer":0,"image":""},{"id":"md3-105-2-9","subject":"md3","topic":"內科-血液","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"一位54歲男性，過去無全身性疾病病史，亦無特殊不適，但其家人注意到他的臉總是紅紅的，身體檢查顯示臉部泛紅，血壓130/86 mmHg，脾臟在左肋緣下1指幅可觸摸到。抽血檢查發現血紅素19.5 gm/dL，血比容60%，白血球12500/µL，neutrophil 73%，monocyte 6%，lymphocyte 20%，eosinophil 1%，血小板546000/µL，血清中erythropoietin 3 mIU/µL（正常3.7～ 31.5），血球細胞有JAK2基因突變。對此病人最適當的治療為何？","options":["(A) hydroxyurea","(B) anagrelide","(C) radioactive phosphorus 32P","(D) phlebotomy"],"answer":3,"image":""},{"id":"md3-105-2-10","subject":"md3","topic":"內科-腫瘤","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"一個35歲男性患者診斷為malignant lymphoma，diffuse large B-cell type，stage IIA，下列有關敘述何者為正確？","options":["(A) 一般而言，積極化學治療約可達到70%的緩解率（remission rate）","(B) 除非進行造血幹細胞移植，否則無治癒可能","(C) 屬於aggressive malignancy，腫瘤生長速度快，化學藥物治療效果不佳","(D) 應該儘可能只給予radiation therapy就好，避免給予systemic chemotherapy，以免以後發生secondary leukemia"],"answer":0,"image":""},{"id":"md3-105-2-11","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"ㄧ位70歲男性病人，主訴為進行性呼吸困難、咳嗽、但痰不多，胸部X光片顯示兩側下肺葉浸潤，HRCT（high-resolution CT）顯示主要變化為basilar and subpleural reticular opacities，traction bronchiectasis and honeycombing表現，最可能的診斷為：","options":["(A) usual interstitial pneumonia（UIP）","(B) nonspecific interstitial pneumonia（NSIP）","(C) cryptogenic organizing pneumonia","(D) aspiration pneumonia"],"answer":0,"image":""},{"id":"md3-105-2-12","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"一位70歲男性，意識清楚，因咳嗽、黃痰和發燒來醫院就診，胸腔科門診的胸部X光片顯示右上葉肺炎，患者的vital signs：BP 150/80 mmHg，heart rate 110/min（regular），respiratory rate 33/min，BT：38℃；依據指引，此病患的最適宜治療方式是：","options":["(A) 門診治療","(B) 一般病房住院治療","(C) 加護病房住院治療","(D) 立即施打肺炎疫苗"],"answer":[1,2],"image":"","answer_note":"更正:第12題答Ｂ、Ｃ給分"},{"id":"md3-105-2-13","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"32歲女性長期無月經，最近因打籃球時發生肋骨骨折，骨密度檢查T-score為-2.8。病人曾於20歲時，因原發性無月經住院檢查，發現嗅覺不佳且子宮很小，因此曾服用口服避孕藥2年，之後因頭痛自行停藥。抽血檢查LH＜0.8 IU/L, estradiol＜20 pg/mL。下列有關骨鬆症之治療何者最恰當？","options":["(A) bisphosphonate","(B) estrogen","(C) calcium + Vit D","(D) human recombinant PTH"],"answer":1,"image":""},{"id":"md3-105-2-14","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"一位30歲女性懷孕三個月，體檢發現其甲狀腺輕微腫大觸感堅實。驗血發現free T4 0.6 ng/dL（normal range 0.8～1.8 ng/dL），T3 120 ng/dL（normal range 80～180 ng/dL），TSH 20µIU/mL（normal range 0.1～2.0 µIU/mL），你認為她的甲狀腺功能如何？","options":["(A) 正常甲狀腺功能（euthyroidism）","(B) 甲狀腺功能亢進（hyperthyroidism）","(C) 次發性甲狀腺功能低下（secondary hypothyroidism）","(D) 原發性甲狀腺功能低下（primary hypothyroidism）"],"answer":3,"image":""},{"id":"md3-105-2-15","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"70歲女性有糖尿病和高血壓，並控制良好，意識清楚且生活可自理。年度健康檢查，自解尿液作常規檢驗，發現有膿尿及菌尿症；經問診及理學檢查，確認病人無發燒、頻尿、解尿疼痛、腰部疼痛等，下列處置何者最適當？","options":["(A) 進行腹部電腦斷層檢查","(B) 住院進行靜脈抗生素治療","(C) 給予口服抗生素治療","(D) 觀察及衛教，不需抗生素治療"],"answer":3,"image":""},{"id":"md3-105-2-16","subject":"md3","topic":"內科-感染","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"65歲男性病人因嚴重肺炎合併呼吸衰竭，入住加護病房，經投予廣效抗生素三天後退燒；但在第五天出現腹痛，腹脹及水便（每日至少五次），下列敘述何者最為適當？","options":["(A) 糞便中Clostridium difficile toxin毒素檢測陰性，可排除Clostridium difficile相關腹瀉之診斷","(B) 糞便培養長出Clostridium difficile，可確診Clostridium difficile相關腹瀉之診斷","(C) 如腹瀉症狀明顯，可先使用loperamide來緩和症狀","(D) 可用口服metronidazole治療"],"answer":3,"image":""},{"id":"md3-105-2-17","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"下列有關懷孕對血行動力學及血壓的影響敘述，何者錯誤？","options":["(A) 懷孕期間，心輸出量增加約40%","(B) 懷孕期間，週邊血管阻力增加","(C) 懷孕期間，心跳加快","(D) 懷孕期間，血壓測量（連續二次，相隔超過6小時）超過140/90 mmHg為不正常"],"answer":1,"image":""},{"id":"md3-105-2-18","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"下列有關低血鈉症（hyponatremia）的描述，何者正確？","options":["(A) 如果血漿滲透壓（osmolality）偏低，應考慮是否有高血糖","(B) 心臟衰竭可能造成細胞外體液（extracellular fluid）增加及低血鈉","(C) 低血鈉及細胞外體液減少的病人，若尿液鈉離子濃度低於10 mmol/L，代表有Na+ wasting nephropathy","(D) 抗利尿激素不適當分泌（SIADH）的病人通常血漿滲透壓正常，但細胞外體液減少"],"answer":1,"image":""},{"id":"md3-105-2-19","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"下列何者，不是急性心衰竭合併肺水腫的主要用藥？","options":["(A) 靜脈注射dopamine or dobutamine","(B) 靜脈注射nitroglycerin","(C) 靜脈注射利尿劑","(D) 優先使用乙型交感神經阻斷劑（β-blocker）"],"answer":3,"image":""},{"id":"md3-105-2-20","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"下列有關肥厚性心肌病變（hypertrophic cardiomyopathy）的敍述，何者錯誤？","options":["(A) 有一半的病人可能有家族史及基因變異","(B) 聽診時常出現第四心音（S4）","(C) 最常見的死因為猝死（sudden cardiac death）","(D) 若病人臨床上出現氣促（dyspnea）及胸痛（chest pain），則以利尿劑（diuretics）及硝酸鹽（nitrate）為首選藥物"],"answer":3,"image":""},{"id":"md3-105-2-21","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"67歲男性本身有糖尿病，目前以口服降血糖藥物控制，前一天晚上11點左右喝了2瓶啤酒後，忽然發生心悸，一直到今日上午7時持續不舒服。因休息無法改善，故到急診求診。病患表示以前無發生過此症狀。生命徵象為：意識清楚，體溫36.5℃，心跳每分鐘140次，血壓150/80毫米汞柱，呼吸每分鐘24次。心電圖如下。下列處置何者最恰當？","options":["(A) 給予coumadin口服","(B) 立即胸前電擊100J","(C) 給予amiodarone靜脈注射治療","(D) 給予heparin靜脈注射治療"],"answer":2,"image":"md3-105-2-21.jpeg"},{"id":"md3-105-2-22","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"對於左心室收縮性功能異常的心臟衰竭病人，下列何種治療無法延長病人壽命？","options":["(A) 血管張力素轉化酶抑制劑（ACE inhibitors）","(B) 乙型交感神經接受器阻斷劑（beta-adrenergic receptor blockers）","(C) 毛地黃（digitalis）","(D) 血管擴張劑組合（combination of vasodilators）"],"answer":2,"image":""},{"id":"md3-105-2-23","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"下列何者為最常見規則性的陣發性上心室頻脈（paroxysmal regular supraventricular tachycardia）？","options":["(A) 心房撲動（atrial flutter）","(B) atrioventricular nodal reentry tachycardia（AVNRT）","(C) 心房顫動（atrial fibrillation）","(D) 多型性心房頻脈（multifocal atrial tachycardia）"],"answer":1,"image":""},{"id":"md3-105-2-24","subject":"md3","topic":"內科-心臟血管","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"一位85歲男性，有高血壓病史，因在家中昏倒被家人送到急診室，在急診室所做的心電圖如附圖，下列敘述何者正確？","options":["(A) 病人心電圖為第三度的房室傳導阻斷（3rd degree AV block）","(B) 病因應考慮高血壓用藥引起","(C) 如果是急性心肌梗塞所導致，大部分發生於前壁急性心肌梗塞病人（anterior wall myocardial infarction）","(D) 應立即置放永久性心臟節律器（permanent pacemaker）"],"answer":1,"image":"md3-105-2-24.jpeg"},{"id":"md3-105-2-25","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"60歲女性因急性腹痛、發燒至急診處，血液檢查結果為bilirubin（total/direct）：3.5/2.0 mg/dL，AST：100 U/L，ALT：75 U/L，腹部電腦斷層結果如圖，最可能的診斷為：","options":["(A) 急性肝炎","(B) 急性盲腸炎","(C) 急性膽管炎","(D) 急性腸胃炎"],"answer":2,"image":"md3-105-2-25.jpeg"},{"id":"md3-105-2-26","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"幽門螺旋桿菌感染不會增加下列何項疾病的風險？","options":["(A) reflux esophagitis","(B) non-cardiac gastric cancer","(C) gastric mucosa-associated lymphoid tissue（MALT）lymphoma","(D) gastric ulcer"],"answer":0,"image":""},{"id":"md3-105-2-27","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"68歲女性因肚臍周圍疼痛合併噁心嘔吐至急診，理學檢查發現體溫37.5℃，且肚臍周圍有壓疼，血液檢查WBC：14500/µL，分類segment：85%，腹部電腦斷層結果如圖，最可能的診斷為何？","options":["(A) acute appendicitis","(B) ventral hernia","(C) acute diverticulitis","(D) adynamic ileus"],"answer":1,"image":"md3-105-2-27.jpeg"},{"id":"md3-105-2-28","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"小型肝癌（small hepatocellular carcinoma）最常見的症狀為何？","options":["(A) 通常沒有症狀","(B) 腹水","(C) 黃疸","(D) 吐血"],"answer":0,"image":""},{"id":"md3-105-2-29","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"一位腹水病人之血中白蛋白（albumin）是3.0 g/dL，腹水中的白蛋白是1.2 g/dL，下列何項診斷較不可能？","options":["(A) 肝硬化（liver cirrhosis）","(B) 鬱血性心衰竭（congestive heart failure）","(C) 腎病症候群（nephrotic syndrome）","(D) Budd-Chiari症候群（Budd-Chiari syndrome）"],"answer":2,"image":""},{"id":"md3-105-2-30","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"下列有關乳糖不耐症（lactose intolerance）的敘述，何者錯誤？","options":["(A) 臨床可出現腹脹、腹瀉、腹痛、脹氣、放屁等症狀","(B) 亞洲人90%左右有此困擾，而白種人則不到25%","(C) 腹瀉屬於分泌性（secretory）腹瀉，停用乳糖製品可改善","(D) 給病人補充乳糖酵素可以改善。含活的乳酸菌之優酪乳（yogurt）因可產生乳糖酵素，病人可以接受"],"answer":2,"image":""},{"id":"md3-105-2-31","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"下列原發性膽原性肝硬化（primary biliary cirrhosis）臨床的敘述，何者錯誤？","options":["(A) 皮膚搔癢（pruritus）","(B) 好發於男性","(C) 好發於女性","(D) 絕大部分血清抗粒線體抗體（anti-mitochondrial antibody）升高"],"answer":1,"image":""},{"id":"md3-105-2-32","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"腎絲球過濾率可藉由自主控制（autoregulation）在血壓變化時，仍能保持穩定之腎絲球過濾率，下列有關腎絲球過濾率自主控制之敘述，何者正確？","options":["(A) 出球小動脈（efferent arteriole）之自主控制來自肌源性（myogenic）反射","(B) 腎小管腎絲球回饋（tubuloglomerular feedback），會影響出球小動脈（efferent arteriole）之收縮與舒張","(C) 腎小球旁器（juxtaglomerular apparatus）釋出腎素（renin），引發入球小動脈（afferent arteriole）之收縮","(D) 抑制腎小管產生腺苷（adenosine），可造成入球小動脈（afferent arteriole）之擴張"],"answer":[2,3],"image":"","answer_note":"更正:第32題答Ｃ、Ｄ給分"},{"id":"md3-105-2-33","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"最容易造成移植後糖尿病之免疫抑制劑為：","options":["(A) cyclosporine","(B) tacrolimus","(C) mycophenolate mofetil","(D) sirolimus"],"answer":1,"image":""},{"id":"md3-105-2-34","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"下列何種引起低血鈉的情況，最適合以注射0.9%生理食鹽水來治療？","options":["(A) 高血糖（hyperglycemia）","(B) 甲狀腺機能低下（hypothyroidism）","(C) 皮質醛酮素缺乏（aldosterone deficiency）","(D) SIADH（syndrome of inappropriate ADH secretion）"],"answer":2,"image":""},{"id":"md3-105-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"下列有關治療urticaria/angioedma的描述中，何者最為正確？","options":["(A) topical glucocorticoids ointment對於acute urticaria最有效","(B) H2 antihistamine對止癢最有效果","(C) systemic glucocorticoids對chronic urticaria最有效","(D) persistent vasculitic urticaria可以使用hydroxychloroquine作為輔助治療"],"answer":3,"image":""},{"id":"md3-105-2-36","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"抗磷脂質抗體症候群（antiphospholipid antibody syndrome）與下列何種異常最有相關？","options":["(A) thrombocytopenia","(B) proteinuria","(C) photosensitivity","(D) arthritis"],"answer":0,"image":""},{"id":"md3-105-2-37","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"全身性硬化症（systemic sclerosis）最常侵犯的內臟是：","options":["(A) 食道","(B) 心臟","(C) 腎臟","(D) 眼睛"],"answer":0,"image":""},{"id":"md3-105-2-38","subject":"md3","topic":"內科-風濕免疫過敏","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"下列關於關節炎分類的鑑別診斷中，何種組合最正確？","options":["(A) tuberculous arthritis－acute monoarticular arthritis","(B) virus-induced arthritis－chronic monoarticular arthritis","(C) sarcoidosis－chronic polyarticular arthritis","(D) infectious arthritis－acute polyarticular arthritis"],"answer":2,"image":""},{"id":"md3-105-2-39","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"一位35歲男子從常規的醫療檢查被診斷出患有B型肝炎，肝功能正常，血清甲型胎兒蛋白（α-fetoprotein, AFP）在正常範圍內。對這病人的建議，下列何者錯誤？","options":["(A) 每6個月門診追蹤","(B) 每6個月血清甲型胎兒蛋白（α-fetoprotein, AFP）檢查","(C) 每6個月腹部電腦斷層掃描","(D) 每6個月肝功能檢查"],"answer":2,"image":""},{"id":"md3-105-2-40","subject":"md3","topic":"內科-血液","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"20歲男子頸部淋巴結腫大有6星期之久，到教學醫院之耳鼻喉科求診，經fiberoscopy檢查顯示頭頸部區域黏膜正常，排除頭頸部惡性腫瘤的診斷。這名患者沒有感染的跡象，理學檢查顯示firm、non-tender及rubber-like，徑長3公分大之淋巴結。下列何者為在這個階段最適當的處置？","options":["(A) 淋巴結超音波（sonography）","(B) 切除性生檢（excisonal biopsy）","(C) 細針穿刺（fine needle aspiration）","(D) 正子掃描（PET scan）"],"answer":1,"image":""},{"id":"md3-105-2-41","subject":"md3","topic":"內科-腫瘤","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"一位40歲女性乳癌病人，手術後經過6次化學治療包括5-fluorouracil，methotrexate和cyclophosphamide，此位病人長期最可能發生的副作用為何？","options":["(A) 心臟毒性","(B) 白血病","(C) 提早停經","(D) 神經毒性"],"answer":2,"image":""},{"id":"md3-105-2-42","subject":"md3","topic":"內科-腫瘤","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"一位65歲男性病人，因貧血就診，大腸鏡發現上升結腸有腫瘤，切片病理報告為腺癌，電腦斷層檢查顯示多處肝轉移，經右半結腸切除，發現腸繫膜淋巴結也有癌細胞侵犯，肝轉移目前無法切除，分期為T3N2M1，腫瘤基因檢測：K-ras基因有G12D突變，術後除化學治療外會建議加何種標靶治療以期待肝轉移變為可切除？","options":["(A) EGFR抑制劑","(B) 血管增生抑制劑","(C) EGFR抑制劑+血管增生抑制劑","(D) EGFR抑制劑或血管增生抑制劑皆不使用，因二者都沒效"],"answer":1,"image":""},{"id":"md3-105-2-43","subject":"md3","topic":"內科-腫瘤","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"下列那一種腎細胞癌與von Hippel-Lindau基因的突變或低表現有關？","options":["(A) 透明細胞腎細胞癌（clear cell renal cell carcinoma）","(B) 類肉瘤腎細胞癌（sarcomatoid renal cell carcinoma）","(C) 難染性腎細胞癌（chromophobe renal cell carcinoma）","(D) 乳突狀腎細胞癌（papillary renal cell carcinoma）"],"answer":0,"image":""},{"id":"md3-105-2-44","subject":"md3","topic":"內科-腫瘤","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"一位淋巴瘤病人接受化學治療CHOP（cyclophosphamide，adriamycin，vincristine及prednisolone）後出現指端麻木感，這個症狀最可能是那種藥的副作用？","options":["(A) cyclophosphamide","(B) adriamycin","(C) vincristine","(D) prednisolone"],"answer":2,"image":""},{"id":"md3-105-2-45","subject":"md3","topic":"內科-腫瘤","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"一位病人被診斷為多發性骨髓瘤，抽血檢查發現其白蛋白為2.5 gm/dL，β2-microglobulin為5.7 mg/L。依照國際分類系統（international staging system），此病人是屬於第幾期？","options":["(A) 0","(B) I","(C) II","(D) III"],"answer":3,"image":""},{"id":"md3-105-2-46","subject":"md3","topic":"內科-血液","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"下列有關慢性淋巴性白血病（CLL）的敘述，何者錯誤？","options":["(A) 周邊血淋巴芽細胞數量超過5×109/L","(B) 免疫細胞染色展現白血病細胞上T-細胞抗原CD5和B-細胞抗原CD23均為陽性","(C) 西方國家成人最常見白血病","(D) 常見於老年人"],"answer":0,"image":""},{"id":"md3-105-2-47","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"COPD發炎反應中有許多發炎介質，包括IL-8, TNF-α, IL-1β這些發炎介質的基因活化主要是經由那一個轉錄因子（Transcriptional factor）？","options":["(A) NF-κB","(B) AP-1","(C) JNK","(D) HIF-1α"],"answer":[0,1],"image":"","answer_note":"更正:第47題答Ａ、Ｂ給分"},{"id":"md3-105-2-48","subject":"md3","topic":"內科-腫瘤","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"一位54歲女性第四期肺腺癌病患接受標靶藥物gefitinib治療，療效不佳，病況持續惡化。下列原因何者較不可能？","options":["(A) 病患長期抽煙","(B) 肺癌細胞上皮細胞生長激素受體（epidermal growth factor receptor, EGFR）基因沒有突變","(C) EGFR基因伴有T790M突變","(D) 肺癌細胞帶有EML4-ALK fusion protein"],"answer":3,"image":""},{"id":"md3-105-2-49","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"下列有關呼吸衰竭（respiratory failure）之敘述，何者錯誤？","options":["(A) 一般以動脈血中的氣體（如氧氣、二氧化碳）分壓為判斷標準","(B) 肺纖維化（idiopathic pulmonary fibrosis）是屬於第一類（type I）呼吸衰竭，又稱氧合衰竭（oxygenation failure）","(C) 重度慢性阻塞性肺疾（chronic obstructive pulmonary disease）是屬於第二類（type II）呼吸衰竭，又稱換氣衰竭（ventilation failure）","(D) 第一類（type I）呼吸衰竭的低血氧症皆能經由氧氣治療（oxygen therapy）得到改善"],"answer":3,"image":""},{"id":"md3-105-2-50","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"下列關於縱膈腔腫塊（mediastinal mass）的敘述，何者錯誤？","options":["(A) 畸胎瘤（benign teratoma）常出現在前縱膈腔","(B) 淋巴瘤（lymphoma）常出現在前、中縱膈腔","(C) 支氣管囊腫（bronchogenic cyst）、心包膜囊腫（pericardial cyst）常出現在中縱膈腔","(D) Morgagni’s橫膈疝氣（diaphragm hernia）常出現在後縱膈腔"],"answer":3,"image":""},{"id":"md3-105-2-51","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"下列有關肺栓塞（pulmonary embolism）的診斷敘述，何者錯誤？","options":["(A) 氣促（dyspnea）、胸痛、咳血等症狀不具特異性","(B) 診斷主要靠肺血管攝影（pulmonary angiography）","(C) 血清中d-dimer的檢測具有高敏感度、低特異性的特點","(D) 使用核醫通氣-灌注肺掃描檢查，會出現「通氣-灌注不吻合」（ventilation-perfusion mismatch）的影像"],"answer":1,"image":""},{"id":"md3-105-2-52","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"有關氣喘病患呼吸道過度反應性（airway hyperresponsiveness）之敘述，下列何者錯誤？","options":["(A) 常以支氣管激發試驗中使FEV1下降20%之methacholine濃度（PC20）或劑量（PD20）來表示","(B) 如果某病患methacholine劑量-反應曲線在高劑量時未出現平原（plateau）現象也代表呼吸道高反應性之存在","(C) 某病患methacholine PC20<8 mg/mL即可診斷為氣喘","(D) methacholine PC20值越低代表呼吸道高反應性越高"],"answer":2,"image":""},{"id":"md3-105-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"70歲男性，有慢性腎功能衰竭及甲狀腺濾泡癌。多年前甲狀腺癌曾接受過手術，且接受過放射性碘治療，但現又在肺出現多處轉移。下列何種處置最適宜？","options":["(A) 停服甲狀腺素四星期後，給予放射性碘治療","(B) 注射基因工程合成的甲促素（TSH），再給予放射性碘","(C) 手術切除肺部轉移病變","(D) 使用標靶治療"],"answer":1,"image":""},{"id":"md3-105-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"你正面對一位剛被診斷有第二型糖尿病的62歲女性，她懷疑自己也有骨質健康的問題，下列何者最能正確說明糖尿病和骨鬆症的相關性？","options":["(A) 第二型糖尿病患者相對於第一型糖尿病患者有較高的骨質密度","(B) 第二型糖尿病患相對於一般人較少發生骨折","(C) 第二型糖尿病患相對於第一型糖尿病患有較高的骨折風險","(D) 血糖控制不良會降低骨質密度"],"answer":0,"image":""},{"id":"md3-105-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"診斷庫欣氏症（Cushing’s syndrome）下列何者最可靠？","options":["(A) 早上8時皮醇（cortisol）血濃度","(B) 隔夜1 mg dexamethasone抑制試驗","(C) 半夜皮醇血濃度","(D) 低劑量dexamethasone抑制試驗"],"answer":3,"image":""},{"id":"md3-105-2-56","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"下列何者不是表面蛋白（apoproteins）的功能？","options":["(A) 與脂蛋白接受器結合","(B) 輔助其他酵素","(C) 是合成脂蛋白分解酵素（lipoprotein lipase）的前身（precursor）","(D) 穩定脂蛋白之結構"],"answer":2,"image":""},{"id":"md3-105-2-57","subject":"md3","topic":"內科-感染","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"下列何者不是抗流感病毒藥物？","options":["(A) Acyclovir（Zovirax®）","(B) Oseltamivir（Tamiflu®）","(C) Peramivir（Rapiacta®）","(D) Zanamivir（Relenza®）"],"answer":0,"image":""},{"id":"md3-105-2-58","subject":"md3","topic":"內科-感染","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"下列有關恙蟲病（scrub typhus）之敘述，何者錯誤？","options":["(A) 病原菌為Orientia tsutsugamushi","(B) 傳播媒介是鳥","(C) 潛伏期為6～21天","(D) 最佳治療藥物是Tetracycline類藥物"],"answer":1,"image":""},{"id":"md3-105-2-59","subject":"md3","topic":"內科-感染","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"臨床診斷感染性心內膜炎的Duke criteria，下列何者不屬於典型感染性心內膜炎的菌血症菌種？","options":["(A) Streptococcus bovis","(B) 社區感染Staphylococcus aureus","(C) 院內感染Enterococcus spp.","(D) Coxiella burnetii"],"answer":2,"image":""},{"id":"md3-105-2-60","subject":"md3","topic":"內科-感染","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"八八水災造成屏東低窪地區嚴重淹水，十天後，該地區有位50歲男性發生急性高燒38.5°C、頭痛、肌肉酸痛，週邊血白血球為17,000/µL，血小板120,000/µL，GOT：150 U/L及GPT：162 U/L，總膽紅素（total bilirubin）：4.1 mg/dL；血清肌酸酐（serum creatinine）：3.2 mg/dL。下列何種抗生素為最適當之治療選擇？","options":["(A) amikacin","(B) ciprofloxacin","(C) crystal penicillin G","(D) vancomycin"],"answer":2,"image":""},{"id":"md3-105-2-61","subject":"md3","topic":"內科-感染","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"53歲男性，無既往病史。主訴在一海邊漁釣場釣魚時被魚鰭刺及右手掌，之後數週皮膚傷口逐漸惡化形成一2公分直徑中央有慢性潰瘍之圓形肉芽腫，帶有分泌物。經皮膚切片檢查，病理變化有肉芽腫（granuloma）、氏巨大細胞（Langhans’giant cells）、且有多量嗜酸性桿菌，而且檢體在分支桿菌培養只在30°C培養長出菌。下列何者是最可能致病菌？","options":["(A) Mycobacterium abscessus","(B) Mycobacterium kansasii","(C) Mycobacterium marinum","(D) Mycobacterium ulcerans"],"answer":2,"image":""},{"id":"md3-105-2-62","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"一位85歲女性病友同時罹患糖尿病、心房纖維顫動（atrial fibrillation）、消化性潰瘍、腰椎退化性關節炎、肺結核、左下肢深部靜脈栓塞（deep vein thrombosis）與黴菌泌尿道感染。使用warfarin後，雖一再增加劑量仍未能達到預期之抗凝血效果。下列何種藥物最可能與此現象相關？","options":["(A) amiodarone","(B) cimetidine","(C) fluconazole","(D) rifampin"],"answer":3,"image":""},{"id":"md3-105-2-63","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"承上題，上題答案藥物最可能經由何種機轉影響warfarin之作用？","options":["(A) 改變胃中酸鹼值進而影響腸道吸收","(B) 影響細胞色素（cytochrome）P450作用","(C) 影響P醣蛋白（P glycoprotein）作用","(D) 改變腎小管藥物排泄速率"],"answer":1,"image":""},{"id":"md3-105-2-64","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"下列那一個病例不符合所列之動脈血氣體分析和血清電解質的檢查結果［pH 7.49，PaO2 90 mmHg，PaCO2 43 mmHg，HCO- 28；Na+ 139，K+ 3.0，Cl- 89（電解質的單位是mmol/L）］？3","options":["(A) 甲：40歲女病人，最近半年發現高血壓；病人有時會下肢無力，血漿皮質醛固酮濃度為38 ng/dL（正常為10～25）","(B) 乙：37歲女病人，患有Sjögren's syndrome，腎臟超音波發現兩側腎臟的腎盂有鈣化跡象","(C) 丙：30歲男病人因急性胰臟炎住院，給予鼻胃管引流，每天約引流出3000 mL","(D) 丁：22歲女病人長期服用thiazide diuretics減肥"],"answer":1,"image":""},{"id":"md3-105-2-65","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"承上題，檢查該病人尿液，發現氯離子濃度為10 mmol/L。何者最為符合此結果？","options":["(A) 甲病人","(B) 乙病人","(C) 丙病人","(D) 丁病人"],"answer":2,"image":""},{"id":"md3-105-2-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"依據2005年Starfield等人的研究報告，美國地區每10,000人口多增加一位家庭醫師，對死亡人數的影響為何？","options":["(A) 每100,000人口增加700人死亡","(B) 每100,000人口增加70人死亡","(C) 每100,000人口減少70人死亡","(D) 每100,000人口減少700人死亡"],"answer":2,"image":""},{"id":"md3-105-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"78歲男性因腦中風無法行動，住在長期照護機構，最近被發現其左後腳跟有一約1 cm之紅斑及瘀傷。下列有關處理此一壓瘡（pressure ulcer）之敘述何者最適當？","options":["(A) 進行全層皮膚移植（full-thickness skin graft）","(B) 進行擴創（debridement）並以優碘清洗","(C) 以泡沫軟墊保護腳跟，避免進一步傷害","(D) 將左腳抬高30度"],"answer":2,"image":""},{"id":"md3-105-2-68","subject":"md3","topic":"影像醫學","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"55歲有糖尿病的徐女士於2週前接受乳房攝影檢查，今天回診除看糖尿病外，並且要看乳房攝影檢查的報告，報告上寫著BIRADS category 0（0級），接下來給她何種建議?","options":["(A) 建議她趕快去看乳房外科並幫忙預約乳房外科門診，以免疾病拖太久","(B) 告訴她第4級及以上才是比較有惡性病變的可能，暫時觀察等明年再檢查就可以","(C) 告訴她0級表示沒有腫瘤，可兩年再檢查一次即可","(D) 告訴她0級表示不能排除有異狀，將為她安排乳房超音波檢查來協助進一步診斷"],"answer":3,"image":""},{"id":"md3-105-2-69","subject":"md3","topic":"內科-腎臟","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"為了早期發現糖尿病腎臟病變，下列何者為最適合的篩檢項目？","options":["(A) 肌胺酸酐","(B) 尿素氮","(C) 微蛋白尿","(D) 尿液常規檢查"],"answer":2,"image":""},{"id":"md3-105-2-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"下列何者不屬於Berlin與Fowkes所發展出來的LEARN模式？","options":["(A) 傾聽（listen）","(B) 解釋（explain）","(C) 支持（advocacy）","(D) 建議（recommend）"],"answer":2,"image":""},{"id":"md3-105-2-71","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"下列何者不包括在1986年渥太華健康促進宣言的健康促進五大行動綱領？","options":["(A) 健康政策","(B) 健康環境","(C) 社區的參與","(D) 媒體宣導"],"answer":3,"image":""},{"id":"md3-105-2-72","subject":"md3","topic":"急診醫學","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"一位40歲男性病患，到急診室求診主訴為吐鮮血（hematemesis），他過去很健康無消化性潰瘍及慢性肝病病史，最近亦無服用任何藥物，也無體重減輕現象，吐血前曾和朋友應酬聚餐及喝酒，並有劇烈嘔吐現象，您面對此病人首先要做的事是：","options":["(A) 插鼻胃管看有無胃出血","(B) 量vital signs，打上點滴輸液","(C) 趕快安排抽血檢驗血色素看有無貧血","(D) 趕快打電話會診胃腸科醫師"],"answer":1,"image":""},{"id":"md3-105-2-73","subject":"md3","topic":"內科-消化肝膽胰","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"承上題，病患理學檢查無蜘蛛斑（spider angioma）、肝掌斑（palmar erythema）、肝脾腫大（hepato-splenomegaly）及腹水現象，腹部超音波於肝膽胰脾無異常發現，此病人最可能之診斷為：","options":["(A) 食道靜脈曲張出血","(B) 胃癌出血","(C) Mallory-Weiss症候群","(D) 十二指腸潰瘍出血"],"answer":2,"image":""},{"id":"md3-105-2-74","subject":"md3","topic":"內科-胸腔","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"關於過敏性支氣管肺麴黴菌病（allergic bronchopulmonary aspergillosis），下列何種影像學徵象最少見？","options":["(A) 肺擴張不全（atelectasis）","(B) 支氣管囊腫（bronchocele）","(C) 肺實質化（consolidation）","(D) 明顯的肋膜積液（pleural effusion）"],"answer":3,"image":""},{"id":"md3-105-2-75","subject":"md3","topic":"急診醫學","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"您至隔壁病房協助一位猝死病患的急救，根據2010年心肺復甦術指引，下列何者錯誤？","options":["(A) 若需檢查脈搏，不超過10秒鐘","(B) 避免中斷胸部按壓，如有需要中斷，不超過10秒鐘","(C) 使用進階呼吸道（advanced airway）裝置人工通氣（ventilation）時，成人每6至8秒吹氣一次，與胸部按壓同步進行","(D) 若需實施去顫電擊，在每次電擊後立即實施胸部按壓"],"answer":2,"image":""},{"id":"md3-105-2-76","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"下࠻何者藥物不會有引起急性尿滯留（acute urinary retention）的副作用？","options":["(A) α-腎上腺素作用劑（α- adrenergic agents）","(B) 抗組織胺（antihistamines）","(C) 治療鼻塞的感冒藥","(D) 膽鹼作用劑（cholinergic agents）"],"answer":3,"image":""},{"id":"md3-105-2-77","subject":"md3","topic":"急診醫學","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"這幾天天氣較冷，50歲女性，感覺喉嚨不舒服，她以為是小感冒不以為意，3天後喉嚨痛更厲害，頸部腫脹並有牙關緊閉（trismus）的情況，而且呼吸有點困難合併有喘鳴音（stridor），病人最可能是下列何者診斷？","options":["(A) Ludwig's angina","(B) Pharyngitis","(C) Peritonsillar abscess","(D) Parapharyngeal abscess"],"answer":0,"image":""},{"id":"md3-105-2-78","subject":"md3","topic":"內科-內分泌代謝","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"57歲女性病人有挑食的習慣，幾天沒解大便，腹脹不舒服去看門診，醫師說她是代謝方面引起的急性便秘，下列何情況較不易引起急性便秘？","options":["(A) Hypothyroidism","(B) Hypoadrenalism","(C) Hypokalemia","(D) Hypocalcemia"],"answer":[0,2,3],"image":"","answer_note":"更正:第78題答Ａ、Ｃ、Ｄ給分。"},{"id":"md3-105-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"50歲的李先生糞便潛血呈現陽性反應，到家庭醫學科王醫師門診進行複診。醫師詳細說明大腸鏡與下消化道鋇劑攝影檢查的必要性以及優缺點等，但李先生仍然無法決定是否接受該檢查或是選擇何種檢查，希望王醫師給予專業建議。此時，王醫師不僅詳細的對病人說明，並將自己認為較好的價值與理念與病人分享，並提供選擇建議。請問王醫師與李先生的溝通，是屬於學者Emanuel所提的那種「醫病關係」模式？","options":["(A) 父權模式（paternalistic model）","(B) 資訊提供模式（informative model）","(C) 詮釋模式（interpretive model）","(D) 審議模式（deliberative model）"],"answer":3,"image":""},{"id":"md3-105-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"有關醫學研究，下列敘述何者錯誤？","options":["(A) 醫學研究以促進醫學進展為第一考量，受試者權益次之","(B) 即使醫師跟研究者是同一人，他在醫病關係中的醫師角色，和在研究者受試者關係中的研究角色是不同的","(C) 凡以人類為受試者的醫學研究，都必須先經由獨立的倫理委員會審查及核可，始得進行","(D) 以人類為受試者的醫學研究，必須要有合理的科學根據"],"answer":0,"image":""},{"id":"md3-106-1-1","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"75歲的李女士這幾個月來家人發現她都不太喜歡出門，沒有活力，感覺相當健忘、睡得不好、食慾不佳、體重減少、常有呼吸困難、胸口悶、全身不舒服，家人帶她至門診評估。下列敘述何者錯誤？","options":["(A) 老年人憂鬱症常伴隨認知功能的症狀，而被認為是「假性失智症」","(B) 甲狀腺機能低下或亢進的病人可能都會伴隨憂鬱的症狀，所以懷疑憂鬱的病人應該測量甲狀腺功能","(C) 藥物治療6～8週後，大約60～70%的病人可以得到控制","(D) SSRI（selective serotonin reuptake inhibitor）類的抗憂鬱藥品比TCA（tricyclic antidepressant）類的藥品更加有效"],"answer":3,"image":""},{"id":"md3-106-1-2","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"52歲男性病人過去並無高血壓或心臟病，近半年來運動時呼吸困難逐漸加重且有下肢水腫。經檢查肝腎功能正常，給予利尿劑治療，頸靜脈仍有顯著擴張。門診胸部X光顯示心臟並未擴大，身體診察無心雜音，肝臟稍腫大，有腹水及雙側下肢水腫。心導管檢查右心房平均壓力是15mmHg（正常＜8 mmHg），右心房壓力曲線呈現明顯的Y下降波。本病人另外可能出現下列那一種徵狀（sign）？","options":["(A) 血壓上升且脈搏壓變寬","(B) 呼氣時，頸動脈擴張可能更形顯著","(C) 少數病例聽診時會有心包敲擊音（pericardial knock），有些會出現｢奇脈｣（paradoxical pulse）","(D) 胸部X光片呈現肺鬱血（lung congestion）現象"],"answer":2,"image":""},{"id":"md3-106-1-3","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"32歲女性突然覺得心跳很快，這是本週第二次出現，第一次出現在數分鐘之後自行停止。這次已經持續半個小時，當她到達急診時，血壓120/70毫米汞柱，呼吸每分鐘十四次，氧合濃度百分之九十八（沒有使用氧氣），心電圖出現窄波規則心率，每分鐘一百八十次。此心律不整經給予頸動脈竇按摩及Valsalva maneuver，心跳並沒有下降。接下來給予何種藥物為佳？","options":["(A) verapamil 2.5到5 mg，一分鐘靜脈注射完畢","(B) digoxin 0.5 mg，靜脈緩慢注射","(C) adenosine 6 mg，靜脈快速注射","(D) diltiazem 0.25 mg/kg，一分鐘靜脈注射完畢"],"answer":2,"image":""},{"id":"md3-106-1-4","subject":"md3","topic":"內科-血液","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"有位55歲男性接受一般健檢時被意外發現hemoglobin 6.0 g/dL（正常值13～17），MCV = 70 fL（正常值77～102），RBC count = 200×104/mm3（正常值400～552×104）。仔細詢問病史，他並沒有明顯的活動性氣促（dyspnea on exertion, DOE），但最近確實感到較無力，爬樓梯不能一口氣爬上四樓。他食慾如常，大便習慣並未改變，顏色也與平常差不多。下列各項敘述，何者錯誤？","options":["(A) 他的貧血病因應該不是thalassemia","(B) hemoglobin electrophoresis應非需要優先安排檢查之項目","(C) 應予以檢查大便潛血反應（fecal occult blood test, FOBT）","(D) 不需要安排大腸檢查"],"answer":3,"image":""},{"id":"md3-106-1-5","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"45歲的秦先生被家屬勸來醫院。他們帶來秦先生的各項檢查結果，並轉述之前醫師的說法，認為秦先生有明顯的酒精性肝傷害，要你說服他戒酒。家屬所提供的數據皆支持秦先生有酒精性肝傷害，除了：","options":["(A) alanine aminotransferase（ALT）< aspartate aminotransferase（AST）","(B) 血中γ-GT數值偏高","(C) 超音波顯示有脂肪肝（fatty liver）現象","(D) ALT>2000 U/L（normal：0～40）"],"answer":3,"image":""},{"id":"md3-106-1-6","subject":"md3","topic":"內科-腎臟","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"56歲的男性，腎病症候群病史，最近2天嘔吐因此沒有吃利尿劑。身體診察有中度的全身水腫，動脈血氣體pH 7.48，PaCO2 47 mmHg，HCO- 34 mEq/L，血液osmolality 255 mOsmol/kg HO，BUN 30 mg/dL，肌酸酐1.5 mg/dL，Na 120 mmol/L。32尿液Na+ 30 mmol/L，尿液Cl- 8 mmol/L。下列敘述何者錯誤？","options":["(A) 病人的細胞外液量增加","(B) 病人的細胞內液量增加","(C) 病人的有效血液容量增加","(D) 病人的有效血液容量減少"],"answer":2,"image":""},{"id":"md3-106-1-7","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"26歲女性病人，最近一週有多喝和多尿。體重50公斤，血液osmolality 290 mOsmol/kg H2O，Na 140 mmol/L，K 3.8 mmol/L。尿液osmolality 200 mOsmol/kg H2O，限水試驗2小時之體重47公斤，尿液osmolality 290 mOsmol/kg H2O，給予ADH（DDAVP）後2小時內最高的尿液osmolality 320 mOsmol/kg H2O。下列敘述何者最正確？","options":["(A) 最可能的診斷是原發性多飲症（primary polydipsia）","(B) 治療使用限水","(C) 治療使用thiazides","(D) 最可能的診斷是中樞型尿崩症（central diabetes insipidus）"],"answer":2,"image":""},{"id":"md3-106-1-8","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"30歲男病人主訴左手第2、3指及右手3、4指的遠端指骨關節（distal interphalangeal joint）紅腫熱痛已3星期。同時兩側下肢的皮膚也出現了許多突出會脫屑的紅疹塊。最可能的診斷為何？","options":["(A) 類風濕性關節炎","(B) 細菌性關節炎","(C) 全身性紅斑性狼瘡","(D) 乾癬性關節炎"],"answer":3,"image":""},{"id":"md3-106-1-9","subject":"md3","topic":"內科-血液","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"一位27歲男性因為牙齦出血不止來到醫院，血液檢查發現血紅素為8.2 gm/dL，白血球1250/µL，其中promyelocyte 18%，segmented neutrophil 2%，monocytes 8%，lymphocytes 72%，血小板21000/µL。骨髓穿刺檢查證明為acute promyelocytic leukemia。下列各選項，何者是治療此病人所必須的？ ①platelet transfusion ②chemotherapy ③all-trans retinoic acid","options":["(A) ①②","(B) ②③","(C) ①③","(D) ①②③"],"answer":3,"image":""},{"id":"md3-106-1-10","subject":"md3","topic":"內科-血液","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"一位68歲女性被發現有蛋白尿，抽血檢查顯示血紅素8.7 gm/dL，白血球及血小板正常，白蛋白3.3 gm/dL，球蛋白1.8 gm/dL，Cr 1.7 mg/dL，尿中Bence-Jones protein陽性，頭部X-光如圖所示。此病人最可能的診斷為？","options":["(A) multiple myleoma","(B) carcinoma with bone metastasis","(C) anemia secondary to chronic kidney disease","(D) Paget’s disease"],"answer":0,"image":"md3-106-1-10.jpeg"},{"id":"md3-106-1-11","subject":"md3","topic":"內科-胸腔","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"林老太太因為咳嗽兩個月且體重減輕，至門診就醫，胸部X光如圖所示，最可能的診斷為：","options":["(A) 黴漿菌肺炎","(B) 支氣管擴張症","(C) 肺癌","(D) 肺氣腫"],"answer":2,"image":"md3-106-1-11.jpeg"},{"id":"md3-106-1-12","subject":"md3","topic":"內科-胸腔","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"邱女士，因有大量濃痰和咳血至門診就醫，胸部X光如圖所示，最正確的診斷為：","options":["(A) 肺栓塞（pulmonary embolism）","(B) 支氣管擴張症（bronchiectasis）","(C) 肺癌（lung cancer）","(D) 肺纖維化（lung fibrosis）"],"answer":1,"image":"md3-106-1-12.jpeg"},{"id":"md3-106-1-13","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"50歲男性業務經理，因倦怠、性慾減少、陽痿來診。病人已婚育有一子20歲，自覺症狀自5年前開始每況愈下。病人自認工作勝任愉快、夫妻關係良好。經泌尿科診治，抽血檢查：FSH 2 mIU/mL，LH 1 mIU/mL，testosterone 0.4 ng/mL皆比正常人為低，給予睪固酮注射症狀改善。下列敘述何者最為恰當？","options":["(A) 此為男性更年期，可以睪固酮症狀治療","(B) 睪丸應小而硬","(C) 應測定血中乳促素（prolactin）濃度","(D) 應以超音波測量陰莖血流"],"answer":2,"image":""},{"id":"md3-106-1-14","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"32歲男性病患，過去身體健康良好。此次因為近一日來四肢無力到急診求診。診視時發現病患在病床上意識清醒，呼吸正常，心跳為每分鐘124次，規則；血壓120/78 mmHg；四肢無法舉離病床，輕觸和疼痛的感覺雙側相同，深部肌腱反射（deep tendon reflex）下降。實驗室檢驗發現血鉀為1.5 meq/L；血中creatine kinase 671 IU/L（參考值，38～174 IU/L）；甲狀腺刺激素（thyroid stimulating hormone）為0.013 µIU/mL（參考值，0.35～5.5 µIU/mL）和游離T 4甲狀腺素（free T4 thyroxine）為4.51 ng/dL（參考值，0.89～1.80 ng/dL）。此病患最有可能的診斷為何?","options":["(A) 原發性皮質醛酮過多症（primary aldosteronism）","(B) 甲狀腺毒性週期性麻痹症（thyrotoxic periodic paralysis）","(C) 利尿劑使用過多","(D) 第一型及第二型腎小管酸血症（renal tubular acidosis）"],"answer":1,"image":""},{"id":"md3-106-1-15","subject":"md3","topic":"內科-感染","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"30歲本國籍未婚男性，有多位男女性伴侶；最近無服用藥物、出國旅遊或飼養寵物情形。五天來發現陸續身上出現紅疹與無痛或癢感的雙手病灶（如圖）；生殖器無特殊病灶，亦無發燒情形。下列何者為此病人最可能的致病原？","options":["(A) Streptococcus pyogenes","(B) Treponema pallidium","(C) Dengue virus","(D) Measles virus"],"answer":1,"image":"md3-106-1-15.jpeg"},{"id":"md3-106-1-16","subject":"md3","topic":"內科-感染","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"一35歲過去無特殊病史之已婚女性，因兩天的發燒、頻尿、左腰痛求診。急診所做血液培養：Staphylococcus epidermidis（只在一瓶需氧血液培養瓶長出；另一瓶厭氧瓶及另一套血液培養，則無細菌生長）; 尿液常規有膿尿症，尿液培養：Escherichia coli（菌量＞100,000 CFU/mL），腎臟超音波無特殊發現。此時最適當臨床處置為何？","options":["(A) 安排心臟超音波，尋找感染性心內膜炎之證據","(B) 依血液培養報告選擇抗生素，積極治療S. epidermidis菌血症","(C) 依尿液培養報告選擇抗生素，治療E. coli泌尿道感染","(D) 依血液與尿液培養報告選擇抗生素，同時治療S. epidermidis菌血症與E. coli泌尿道感染"],"answer":2,"image":""},{"id":"md3-106-1-17","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"有關冠心症心肌缺氧之敘述，下列何者錯誤？","options":["(A) 心肌缺氧（myocardial ischemia）是因為心臟氧氣的供應，不足以應付新陳代謝的需求","(B) 穩定性心絞痛患者，其胸痛可能持續數小時之久","(C) 不穩定心絞痛患者，其胸痛有可能是在休息狀態下發作","(D) 有些患者心肌缺氧發作時，僅有下巴、脖子、肩膀或手臂不適，而無胸痛"],"answer":1,"image":""},{"id":"md3-106-1-18","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"下列有關心雜音（heart murmur）之敘述，何者錯誤？","options":["(A) 正常健康的人不應該有心雜音","(B) 收縮期雜音在第一心音之時或稍後，而結束於接下來的第二心音或稍前","(C) 當頸動脈搏動（upstroke）時，其心雜音為收縮期雜音；頸動脈下沉時，其心雜音為舒張期雜音","(D) 舒張期雜音發生於第二心音之時或稍後，而結束於接下來的第一心音或稍前"],"answer":0,"image":""},{"id":"md3-106-1-19","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"下列有關ST節段上升的心肌梗塞（ST-elevation myocardial infarction，STEMI）的敍述，何者錯誤？","options":["(A) 病態生理學為血管內粥狀硬化斑瑰破裂，產生急性血栓將血管完全阻塞","(B) 心肌肌鈣蛋白（cardiac troponin）升高，通常可持續一週","(C) 通常到院前死亡是因為急性心衰竭","(D) 下壁心肌梗塞（inferior wall myocardial infarction）病患例行要做右前胸壁心電圖"],"answer":2,"image":""},{"id":"md3-106-1-20","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"下列何者不是造成動脈粥狀硬化的主要危險因子？","options":["(A) 高血壓","(B) 喝酒","(C) 抽菸","(D) 血漿高密度脂蛋白膽固醇（HDL cholesterol）過低（小於40 mg/dL）"],"answer":1,"image":""},{"id":"md3-106-1-21","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"一位25歲的女性病人因為最近一週發生胸悶而求診，胸悶的發作與活動無關；身體診察時在胸骨旁左下緣可聽見收縮中期滴答聲（mid-systolic click）以及第二度收縮末期雜音（late systolic murmur），下列何項是確認診斷的最佳診斷工具？","options":["(A) 標準12-導程心電圖","(B) 胸部X-光片","(C) 電腦斷層檢查","(D) 心臟超音波"],"answer":3,"image":""},{"id":"md3-106-1-22","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"下࠻何種藥物Ә可使用於non-ST elevation myocardial infarction或Ә穩定心絞痛患者？","options":["(A) aspirin","(B) low-molecular-weight heparin","(C) unfractionated heparin","(D) r-tPA（recombinant tissue plasminogen activator）"],"answer":3,"image":""},{"id":"md3-106-1-23","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"有關單獨二尖瓣狹窄（isolated mitral stenosis）之敘述，何者正確？","options":["(A) 大多數病患狹窄愈嚴重，第一心音（S1）愈弱","(B) opening snap如果聽得見，是在心收縮期","(C) 感染性心內膜炎在單獨二尖瓣狹窄病患的機率與合併二尖瓣閉鎖不全病患相同","(D) 臨床症狀除運動時呼吸困難外，有時會出現咳血、肺栓塞或肺炎等"],"answer":3,"image":""},{"id":"md3-106-1-24","subject":"md3","topic":"內科-心臟血管","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"一位50歲男性主訴胸部不適與行動時氣促，無高血壓病史，血壓130/80 mmHg，心跳規則每分鐘76次，聽診上有第四心音，但並無明顯雜音，胸部X光片無明顯異常，心電圖呈現左心室肥厚合併ST-T波變化，而心臟超音波呈現嚴重左心尖部肥厚與正常左心室收縮功能。下列何種藥物最不適當？","options":["(A) digitalis","(B) beta blockers","(C) diltiazem","(D) verapamil"],"answer":0,"image":""},{"id":"md3-106-1-25","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"目前治療C型肝炎的標準療法為何？","options":["(A) 干擾素單獨使用","(B) 雷巴威林（ribavirin）單獨使用","(C) 干擾素及雷巴威林（ribavirin）合併使用","(D) 干擾素與干安能（lamivudine）合併使用"],"answer":2,"image":""},{"id":"md3-106-1-26","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"在臺灣引起肝膿瘍最常見的細菌為何？","options":["(A) 幽門螺旋桿菌（H. pylori）","(B) 大腸桿菌（E. coli）","(C) 金黃色葡萄球菌（S. aureus）","(D) 克雷白氏肺炎桿菌（K. pneumoniae）"],"answer":3,"image":""},{"id":"md3-106-1-27","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"中年B型肝炎病人，突然間出現右上腹疼痛、冒冷汗、血壓降低且血紅素降低，最可能的診斷是？","options":["(A) 肝癌破裂","(B) 胰臟發炎","(C) 胃食道逆流","(D) 胃潰瘍"],"answer":0,"image":""},{"id":"md3-106-1-28","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"一位61歲男性慢性B型肝炎病人，經檢查發現在肝臟右葉有兩個肝細胞癌，直徑分別為4公分與3.5公分，左葉亦有一個肝細胞癌，直徑為1.5公分，主肝門靜脈暢通，病人肝功能Child-Pugh分級為A。在臺灣此病人最適當之初步治療方式為何？","options":["(A) 肝腫瘤切除術","(B) 標靶藥物治療","(C) 肝移植手術","(D) 經肝動脈栓塞治療術"],"answer":3,"image":""},{"id":"md3-106-1-29","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"下列有關幽門螺旋桿菌之敘述，何者正確？","options":["(A) 由於urease test之診斷率過低，因此需以細菌培養來確立診斷","(B) 無潰瘍之消化不良患者，若罹有此菌，國際共識認為需要殺菌","(C) 將幽門螺旋桿菌殺菌清除後，一定會增加胃食道逆流疾病之機會","(D) 胃潰瘍患者之幽門螺旋桿菌之罹患率低於十二指腸潰瘍患者"],"answer":[1,3],"image":"","answer_note":"更正:第29題答Ｂ、Ｄ給分"},{"id":"md3-106-1-30","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"下列有關消化性潰瘍治療藥物之敘述，何者錯誤？","options":["(A) 制酸劑（antacid）宜與第二型組織胺拮抗劑（H2 receptor antagonist）併用以增加療效","(B) 長期服用第二型組織胺拮抗劑可能有陽痿、男性女乳症、月經失調等藥物不良反應","(C) 長期服用質子幫浦抑制劑（proton pump inhibitor）可能會增加骨質疏鬆與髖骨骨折之機會","(D) 制酸劑會抑制四環素（tetracycline）在胃腸道之吸收"],"answer":0,"image":""},{"id":"md3-106-1-31","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"調整飲食為治療胃腸疾病重要的手段，下列有關胃腸疾病與飲食方式調整的敘述，何者錯誤？","options":["(A) gastroparesis患者最好用liquid meals","(B) dumping syndrome患者須限制脂肪量","(C) irritable bowel syndrome患者可考慮高纖飲食","(D) short bowel syndrome患者可進食medium-chain triglyceride"],"answer":1,"image":""},{"id":"md3-106-1-32","subject":"md3","topic":"內科-腎臟","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"治療慢性腎病（chronic kidney disease）合併之高血壓時，首選藥物為：","options":["(A) 利尿劑（diuretics）","(B) 鈣離子阻斷劑（calcium channel blockers）","(C) β-阻斷劑（β-blockers）","(D) 血管張力素轉化酶阻斷劑（angiotensin-converting enzyme inhibitors）或血管張力素接受器阻斷劑（angiotensin receptor blockers）"],"answer":3,"image":""},{"id":"md3-106-1-33","subject":"md3","topic":"內科-腎臟","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"一名58歲第5期慢性腎病男性，因胸痛1小時來院求診，身體檢查血壓150/94 mmHg，脈搏每分鐘80次，呼吸每分鐘18次，心臟聽診有明顯的心包膜摩擦音，下肢微腫，實驗室檢查血鈉135 mmol/L，血鉀5.3 mmol/L，血紅素8.0 g/dL，心電圖呈廣泛性ST-segment上升。下列何項是最根本的治療？","options":["(A) 給予kayexalate（sodium polystyrene sulfonate）降低血鉀","(B) 透析（dialysis）","(C) 輸血（blood transfusion）","(D) 經皮冠狀動脈介入治療（percutaneous coronary intervention）"],"answer":1,"image":""},{"id":"md3-106-1-34","subject":"md3","topic":"內科-腎臟","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"20歲男性，因下肢水腫住院，血清白蛋白是2.3 g/dL，血中尿素氮和血清肌酸酐各為27/1.2 mg/dL，24小時尿液蛋白質流失測得18 g。腎臟切片病理檢查，發現光學顯微鏡下腎絲球的結構正常。下列敘述何者正確？","options":["(A) 電子顯微鏡下應該看得到電子密集沈積","(B) 通常血清補體是正常的","(C) 如果治療有效，通常不會再發","(D) 通常對類固醇治療的效果不佳，有效果的約只有30%"],"answer":1,"image":""},{"id":"md3-106-1-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"下列有關anti-CCP（anti-cyclic citrullinated peptide antibody）之敘述，何者錯誤？","options":["(A) 多出現在類風濕性關節炎（RA）病患","(B) 一般而言此抗體高低與RA疾病的嚴重度相關","(C) 此CCP之形成，是由精氨酸（arginine）經由PAD酶轉換成瓜氨酸（citrulline）","(D) 使用anti-TNFα治療RA，anti-CCP抗體不會下降"],"answer":[1,3],"image":"","answer_note":"更正:第35題答Ｂ、Ｄ給分"},{"id":"md3-106-1-36","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"目前診斷Sjögren’s症候群，下列何種條件，可診斷原發性乾燥症（primary Sjögren’s syndrome）？①口乾 ②眼乾 ③Schirmer's test (+) ④唾液腺體切片異常（超過1 focus淋巴球聚集） ⑤唾液腺功能檢查異常 ⑥血中抗SSA或SSB抗體陽性 ⑦關節疼痛","options":["(A) ①②③④","(B) ①②⑤⑦","(C) ①②③⑤","(D) ①②⑥⑦"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第36題一律給分 (原公告答案 A)"},{"id":"md3-106-1-37","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"下列的何種全身性血管炎會有氣喘病的發作？","options":["(A) Churg-Strauss syndrome","(B) Goodpasture’s syndrome","(C) essential mixed cryoglobulinemia","(D) drug-induced vasculitis"],"answer":0,"image":""},{"id":"md3-106-1-38","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"32歲男性病人，因反覆發作葡萄膜炎（uveitis）從眼科轉診過來；詳細病史，發現其已有一年多常有口腔潰瘍疼痛的病史，且兩下肢也時常出現有壓痛的皮膚紅疹。但無慢性下背痛的病史，下列那一項檢查，可能具診斷的價值？","options":["(A) pathergy test","(B) Schober test","(C) Schirmer’s test","(D) PPD skin test"],"answer":0,"image":""},{"id":"md3-106-1-39","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"一位17歲的女性罹患蕁麻疹已有二年之久。時常會有無預警的發生全身搔癢、紅斑及條痕（erythema and wheal）出現。經服用抗組織胺（anti-histamine）有效，但是無法根除。則下列那一種檢查對疾病的病因追查最有幫忙？","options":["(A) 血清補體值（serum complement level）","(B) 嗜伊紅性白血球的總數（total eosinophil count）","(C) 抗過敏原IgE抗體的效價（allergen-specific IgE titer）","(D) 血清冷凝球蛋白的存在（presence of serum cryoglobulin）"],"answer":2,"image":""},{"id":"md3-106-1-40","subject":"md3","topic":"內科-腫瘤","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"一40歲女士因左乳房腫塊求診。體檢發現單一腫塊，堅實，無觸痛感，邊界不規則及模糊，固定不動於皮膚。在這個階段最適當的檢查為何？","options":["(A) 乳房X光攝影","(B) 切除性生檢（excisional biopsy）","(C) 乳房X光攝影後切除性生檢","(D) PET掃描"],"answer":2,"image":""},{"id":"md3-106-1-41","subject":"md3","topic":"內科-腫瘤","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"一位33歲男性病人，有一約6 cm前縱膈腔腫瘤，經抽血檢查發現血清的CEA濃度正常，AFP增加（80 ng/ml，normal range： <20 ng/mL），beta HCG增加（150 mIU/mL，normal range：<1 mIU/mL）；他的腫瘤最有可能是：","options":["(A) 肝癌（hepatocellular carcinoma）","(B) 精母細胞生殖細胞癌（seminoma）","(C) 非精母細胞生殖細胞癌（non-seminomatous germ cell tumor）","(D) 胸腺瘤（thymoma）"],"answer":2,"image":""},{"id":"md3-106-1-42","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"一位40歲女性病人由大腸鏡發現在升結腸有一腫瘤，而沒有其他息肉或發炎性大腸病變。病理切片發現是腺癌，分化不好（poorly differentiated adenocarcinoma），她媽媽於48歲死於子宮內膜癌，她爸爸目前健康良好，她43歲的姊姊在2年前診斷為早期結腸癌，追蹤至今無復發。此外，病人無其他兄弟姊妹，經過右半結腸切除，證實是T3 N1 M0腺癌，她擔心2個小孩有結腸癌的風險，想做基因檢測，此病人最有可能是那一種家族性的癌症症候群？","options":["(A) BRCA2突變","(B) 遺傳性非息肉性大腸直腸癌（hereditary nonpolyposis colorectal cancer（HNPCC））","(C) 家族性腺瘤性多發性息肉症候群（familial adenomatous polyposis（FAP））","(D) Li-Fraumeni症候群（Li-Fraumeni syndrome）"],"answer":1,"image":""},{"id":"md3-106-1-43","subject":"md3","topic":"內科-血液","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"下列何種營養素的缺乏是酗酒病人貧血最常見的原因？","options":["(A) folic acid","(B) vitamin B12","(C) iron","(D) zinc"],"answer":0,"image":""},{"id":"md3-106-1-44","subject":"md3","topic":"內科-血液","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"一位病人在體檢時發現血小板數為65000/µL，紅血球及白血球正常，下列何項檢查對於釐清血小板低下的原因幫忙最小？","options":["(A) platelet antibody","(B) antibody to hepatitis C virus","(C) antibody to human immunodeficiency virus","(D) antinuclear antibody"],"answer":0,"image":""},{"id":"md3-106-1-45","subject":"md3","topic":"內科-腫瘤","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"下列何種抗癌藥物最不會造成白血球減少（neutropenia）？","options":["(A) sunitinib","(B) paclitaxel","(C) gefitinib","(D) gemcitabine"],"answer":2,"image":""},{"id":"md3-106-1-46","subject":"md3","topic":"內科-胸腔","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"COPD患者休息狀態時，動脈血已出現缺氧現象，該病患較不可能因COPD而出現下列那一項呼吸生理的障礙？","options":["(A) 第一秒吐氣量（FEV1）低於預期值的50%","(B) 分流（shunt）增加","(C) 換氣／灌流失衡（ventilation/perfusion mismatching）","(D) 第一秒吐氣量（FEV1）低於預期值的25%時，可能同時伴有動脈血中二氧化碳升高（PaCO2）"],"answer":1,"image":""},{"id":"md3-106-1-47","subject":"md3","topic":"內科-胸腔","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"有關阻塞性睡眠呼吸中止症（obstructive sleep apnea, OSA）的敘述，下列何者錯誤？","options":["(A) 主要是靠肺量計（spirometry）和腦波圖來診斷","(B) 肥胖者與OSA的發生有密切關係","(C) 容易有打鼾、白天嗜睡及夜間睡眠呼吸中斷等症狀","(D) 治療以睡眠時佩戴正壓呼吸器（continuous positive airway pressure）為主"],"answer":0,"image":""},{"id":"md3-106-1-48","subject":"md3","topic":"內科-腫瘤","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"以標靶藥物（酪胺酸動力酶抑制劑，tyrosine kinase inhibitor）治療非小細胞肺癌，治療效果最主要的決定因素為何？","options":["(A) 細胞分類－肺腺癌","(B) 性別－女性","(C) 抽菸史－不抽菸者","(D) 表皮成長因子受體（epidermal growth factor receptor）特定基因變異"],"answer":3,"image":""},{"id":"md3-106-1-49","subject":"md3","topic":"內科-胸腔","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"下列關於氣喘（bronchial asthma）的治療敘述，何者正確？","options":["(A) 宜常規使用速效性乙二型交感神經增效劑（rapid acting β–agonist）來控制症狀","(B) 使用中劑量吸入性類固醇而效果不佳時，應優先提高類固醇劑量來控制發炎反應","(C) 使用吸入型長效性乙二型交感神經增效劑與吸入型類固醇合併製劑，可有效控制持續性氣喘（persistent asthma）","(D) 白三烯酸拮抗劑（leukotriene antagonist）適用於重度持續性氣喘（severe persistent asthma）"],"answer":2,"image":""},{"id":"md3-106-1-50","subject":"md3","topic":"內科-胸腔","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"快速、淺短呼吸指數（rapid-shallow-breathing index）為何時，病患成功脫離呼吸器之機會較高？","options":["(A) ＜105","(B) ＜140","(C) ＜210","(D) ＜250"],"answer":0,"image":""},{"id":"md3-106-1-51","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"50歲女性，有一甲狀腺結節，併高血壓，後來發現是甲狀腺髓質癌併嗜鉻細胞瘤。則她及她的小孩要作何種致癌基因（oncogene）檢查？","options":["(A) RAS","(B) TRK","(C) ERK","(D) RET"],"answer":3,"image":""},{"id":"md3-106-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"維生素D可調控鈣質吸收及肌肉力度的強弱，抽血檢驗何種項目可以測知體內維生素D含量不足？","options":["(A) 25 (OH) D","(B) 1,25 (OH)2 D","(C) 副甲狀腺素（PTH）","(D) 血中游離鈣的濃度"],"answer":0,"image":""},{"id":"md3-106-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"下列何者不是脂蛋白分解酵素（lipoprotein lipase）缺乏症之典型臨床表現？","options":["(A) 發疹性黃色瘤（eruptive xanthomas）","(B) 胰臟炎","(C) 動脈硬化","(D) 三酸甘油酯過高"],"answer":2,"image":""},{"id":"md3-106-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"下列那一種狀況合併之糖尿病是由於胰島素分泌不足引起？","options":["(A) type A insulin resistance","(B) leprechaunism","(C) Rabson-Mendenhall syndrome","(D) mutation(s) in insulin promoter factor-1（IPF-1）"],"answer":3,"image":""},{"id":"md3-106-1-55","subject":"md3","topic":"內科-感染","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"下列有關性病及病原菌配對，何者錯誤？","options":["(A) chancre-Treponema pallidum","(B) chancroid-Haemophilus ducreyi","(C) lymphogranuloma venereum-Chlamydia trachomatis","(D) granuloma inguinale（Donovanosis）-Mycoplasma genitalium"],"answer":3,"image":""},{"id":"md3-106-1-56","subject":"md3","topic":"內科-感染","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"細菌性脊椎骨髓炎最常見致病菌種為：","options":["(A) Staphylococcus aureus","(B) Salmonella enteritidis","(C) Escherichia coli","(D) Viridans group Streptococcus"],"answer":0,"image":""},{"id":"md3-106-1-57","subject":"md3","topic":"內科-感染","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"下列有關類鼻疽（melioidosis）之敘述，何者錯誤？","options":["(A) 致病菌為Burkholderia pseudomallei","(B) 最常見臨床表現為急性社區型肺炎","(C) 最佳治療選擇為ceftazidime或carbapenems等後線抗生素","(D) 療程約4週內，復發率低"],"answer":3,"image":""},{"id":"md3-106-1-58","subject":"md3","topic":"內科-感染","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"下列有關各項抗生素常見不良藥物反應之敘述，何項最不適當？","options":["(A) clindamycin-腹瀉","(B) gentamicin-腎毒性","(C) linezolid-皮疹","(D) vancomycin-紅人症候群（red man syndrome）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第58題一律給分 (原公告答案 C)"},{"id":"md3-106-1-59","subject":"md3","topic":"內科-感染","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"關於bacterial meningitis的敘述，下列何者錯誤？","options":["(A) CSF opening pressure常大於180 mmH2O","(B) CSF/serum glucose ratio大於0.4","(C) CSF protein上升，常大於45 mg/dL","(D) CSF Gram stain細菌染色之陽性率>50%"],"answer":1,"image":""},{"id":"md3-106-1-60","subject":"md3","topic":"內科-感染","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"在臺灣地區未有肝膽疾病之病人，如罹患原發性肝膿瘍，其最可能的致病菌是：","options":["(A) 金黃色葡萄球菌（staphylococcus aureus）","(B) A族鏈球菌（group A streptococcus）","(C) 大腸桿菌（E. coli）","(D) 克雷白氏肺炎桿菌（Klebsiella pneumoniae）"],"answer":3,"image":""},{"id":"md3-106-1-61","subject":"md3","topic":"內科-感染","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"下列有關不明熱（fever of unknown origin）的分類，何者錯誤？","options":["(A) 院內型的不明熱（nosocomial FUO）","(B) 社區型的不明熱（community FUO）","(C) 愛滋病毒相關的不明熱（HIV associated FUO）","(D) 嗜中性白血球低下的不明熱（neutropenic FUO）"],"answer":1,"image":""},{"id":"md3-106-1-62","subject":"md3","topic":"急診醫學","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"一位病友疑似誤食遭到日本福島核災幅射塵污染之食物。除可使用碘化鉀（potassium iodide）治療碘（iodine）-131污染外，亦可使用下列何者治療銫（cesium）-137污染？","options":["(A) aluminum phosphate","(B) bicarbonate","(C) calcium diethylenetriaminopentaacetate","(D) Prussian blue"],"answer":3,"image":""},{"id":"md3-106-1-63","subject":"md3","topic":"急診醫學","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"承上題，有一項檢查為幅射傷害之敏感指標，與病友幅射暴露量與預後相關。在幅射暴露後之數日內需要每日多次檢測。此項上題病友最需要頻繁檢驗之項目為何？","options":["(A) 絕對淋巴球計數（absolute lymphocyte count）","(B) 絕對嗜中性白血球計數（absolute neutrophil count）","(C) 乳酸脫氫酵素（lactate dehydrogenase）","(D) 嗜中性白血球染色體分析（neutrophil chromosomal analysis）"],"answer":0,"image":""},{"id":"md3-106-1-64","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"一位55歲男性這兩天意識變化被送至急診處。病人一個月前診斷為肺癌，但他拒絕任何進一步治療。家人敘述病人這個月情緒低落，但進食情況尚可，無嘔吐或發燒。身體檢查：體溫36.8℃，血壓130/78 mmHg，脈搏每分80次，呼吸每分19次。病人對時空有錯亂情形，以及嗜睡；其他神經學檢查無異常；右上鎖骨窩有一拇指大的淋巴結，下肢無水腫。初步檢查血比容42%，白血球8,300/mm3，血小板240,000/mm3；尿液檢查正常；尿素氮15 mg/dL，ALT 30 U/L，血糖156 mg/dL。血清電解質，Na+ 122，K+ 5.5，Cl- 86（電解質單位mmol/L）。有關此病人的可能診斷，下列那一個最適當？","options":["(A) 肺癌併發阻塞性肺炎","(B) 肺癌併發腦部轉移","(C) 肺癌併發厭食","(D) 肺癌併發抗利尿激素分泌不當"],"answer":[1,3],"image":"","answer_note":"更正:第64題答Ｂ、Ｄ給分。"},{"id":"md3-106-1-65","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"承上題，在急診處對該病人的處置，下列何者最為適當？","options":["(A) 腦部電腦斷層攝影，並給予口服kayexalate 60 mg","(B) 尿液滲透壓測定，並給予0.9% NaCl","(C) 動脈血氣體分析，並作血液的細菌培養","(D) 腦脊髓液檢查，並給予5%葡萄糖溶液，加入5單位的短效胰島素"],"answer":1,"image":""},{"id":"md3-106-1-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"75歲林先生，平時有失智症及糖尿病，偶而失眠。這幾天突然不講話，且有尿失禁現象，家屬起初不以為意，三日後狀況惡化，帶至急診室，經診斷為肺炎，下列敘述何者正確？","options":["(A) 林先生沒有老年病症候群","(B) 林先生之表現為失智症惡化造成","(C) 林先生可能有醫源性問題","(D) 林先生一開始之表現為非典型表現"],"answer":3,"image":""},{"id":"md3-106-1-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"63歲張女士，3個月前成人健檢報告顯示總膽固醇264 mg/dL，三酸甘油酯145 mg/dL，高密度脂蛋白膽固醇59 mg/dL，其它正常。張女士不抽菸，無其他疾病史，父親有糖尿病。複查結果低密度脂蛋白膽固醇150 mg/dL，血壓126/72 mmHg，身體質量指數（BMI）30.1 kg/m2，下列敘述何者最適當？","options":["(A) 張女士屬於心血管疾病中度風險者（moderate risk）","(B) 張女士之低密度脂蛋白膽固醇高於目標值","(C) 此時只須繼續生活方式改善，不須給予statin類藥物治療","(D) 須依Framingham Heart Study公式推估5年內罹患冠心症之風險值，才能決定張女士之膽固醇目標值"],"answer":2,"image":""},{"id":"md3-106-1-68","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"一位60歲女性，因屬骨質疏鬆症之高危險群，接受雙能量X光吸收儀（DEXA）骨質密度篩檢。檢查報告顯示有T值（T- score）及Z值（Z-score），下列數值何者為骨質疏鬆症的診斷標準？","options":["(A) T值≤－1.0","(B) T值≤－2.5","(C) Z值≤－1.0","(D) Z值≤－2.5"],"answer":1,"image":""},{"id":"md3-106-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"一位52歲患有高血壓並服用藥物的男性，計畫到印度鄉下去旅遊七天，若您要給他建議，下列何者不適當？","options":["(A) 高血壓藥可以不帶，因旅遊時間只有七天","(B) 自備ciprofloxacin以治療旅程中可能發生的旅遊者腹瀉或泌尿道感染","(C) 攜帶一些消炎止痛藥及抗組織胺以備不時之需","(D) 飲食必需煮熟，煮開，剝皮，否則就不要吃"],"answer":0,"image":""},{"id":"md3-106-1-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"王小姐是一位憂鬱症患者，長期使用藥物治療。最近由於和男朋友吵架，情緒低落且失眠更為嚴重，數次向朋友表示要燒炭自殺，並買了一包炭回家。下列何者為最適當的處理方式？","options":["(A) 調整抗憂鬱藥物","(B) 請家人多注意病人的行為","(C) 詳細評估壓力來源","(D) 轉介精神醫療院所住院治療"],"answer":3,"image":""},{"id":"md3-106-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"依據2011年的發表，美國、加拿大、英國之全科醫師（家庭醫師）占全部醫師的比例分別為31％、48％、68％。依此全科醫師比例來考量，有關這三個國家醫療花費分別占國內生產總值（Gross Domestic Product，GDP）比例的描述，下列何者正確？","options":["(A) 美國最高","(B) 加拿大最高","(C) 英國最高","(D) 三個國家相似"],"answer":0,"image":""},{"id":"md3-106-1-72","subject":"md3","topic":"家醫-行為與社區醫學","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"一位83歲男性，有認知能力退化現象，與女兒同住。被女兒送至急診室，他看起來營養狀況不良，身體可聞到尿味，兩上臂有瘀青現象，左手腕有擦傷。看起來有害怕的眼神，但他否認有任何人傷害他。急診室醫師在診療病人後首先應採取的作為，下列何者最適當？","options":["(A) 告訴他女兒，病人可能被虐待","(B) 儘快請他女兒將病人帶回家","(C) 聯絡社工來協助處理","(D) 安排尿液檢查"],"answer":2,"image":""},{"id":"md3-106-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"關於緩和醫療（palliative care），下列敘述何者正確？","options":["(A) 依據安寧緩和醫療條例，不施行心肺復甦術，應由二位醫師診斷確為末期病人，且應有意願人簽署之意願書","(B) 非類固醇類抗發炎藥（NSAID）控制神經痛之效果良好","(C) 對非類固醇類抗發炎藥無效之疼痛，可給予meperidine（Demerol）","(D) 根據Kubler Ross的理論，對親人死亡之悲傷調適階段，為否認、憤怒、討價還價、憂鬱"],"answer":0,"image":""},{"id":"md3-106-1-74","subject":"md3","topic":"影像醫學","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"61歲男性突發性的胸痛、呼吸困難，其胸部X光如圖示，最主要的診斷為何？","options":["(A) 肺氣腫","(B) 肺挫傷出血","(C) 氣胸","(D) 肺炎"],"answer":2,"image":"md3-106-1-74.jpeg"},{"id":"md3-106-1-75","subject":"md3","topic":"急診醫學","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"一位76歲獨居老人有心律不整之病史，平常服用毛地黃（Digoxin）控制。本次因頭暈、噁心和胸悶，被鄰居發現並且帶來急診室。經病史詢問後，病人表示因為心情不好就將半個月份的毛地黃都吃下去，到院時意識清楚，體溫正常、呼吸22次/min、心跳42次/min、血壓96/60mmHg，下列何項處置最不恰當？","options":["(A) 抽血檢測毛地黃濃度（digoxin level）","(B) 給予硝化甘油（nitroglycerin）","(C) 給予經皮心臟節律器（transcutaneous pacemaker, TCP）","(D) 靜脈注射atropine 0.5mg"],"answer":1,"image":""},{"id":"md3-106-1-76","subject":"md3","topic":"急診醫學","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"下列何種無脈搏電活性（pulseless electric activity，PEA）病人，接受碳酸氫鈉（sodium bicarbonate）治療最有效果？","options":["(A) 二氧化碳過高之呼吸性酸血症病人","(B) 心電圖顯示竇性心律且窄的QRS波型之出血性休克病人","(C) 心電圖呈現每分鐘45下且寬的QRS波形之高血鉀病人","(D) 心跳呼吸停止之代謝性酸血症病人"],"answer":2,"image":""},{"id":"md3-106-1-77","subject":"md3","topic":"急診醫學","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"一位9歲小孩在游泳池中，被發現溺水漂浮在水中，下列敘述何者錯誤？","options":["(A) 急救溺水的病人，仍維持叫病人、叫他人打電話119求救，開始心肺復甦術","(B) 應儘早清除此病人呼吸道的水分，儘速實施哈姆立克急救術","(C) 此溺水病人可能產生頸椎受傷的發生率低於千分之一，不需例行性使用頸圈","(D) 當病人在淺水域或脫離水域時，可以施予口對鼻呼吸，暫時取代口對口呼吸"],"answer":1,"image":""},{"id":"md3-106-1-78","subject":"md3","topic":"急診醫學","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"一位心臟停止的病人被送來急診，急診醫師已插入氣管內管，這時候呼吸通氣速率最恰當為？","options":["(A) 每4秒給一次呼吸","(B) 每6秒給一次呼吸","(C) 每8秒給一次呼吸","(D) 每10秒給一次呼吸"],"answer":1,"image":""},{"id":"md3-106-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"周醫師在幫病患王老先生進行胃鏡檢查時，發現王老先生胃部有一處胃潰瘍，周醫師初步判斷應該屬於良性潰瘍而沒有幫王老先生進行切片檢查。胃鏡檢查結束，王老先生很擔心該胃潰瘍會不會是胃癌，而多次詢問周醫師是否應該馬上再次做胃鏡配合切片檢查，周醫師告知只要吃藥4個月胃潰瘍就可以痊癒。4個月後，王先生再度接受胃鏡檢查，切片檢查顯示為胃癌。周醫師為了避免醫療糾紛，在第一次胃鏡報告上增加「病患想先吃藥」的敘述。下列敘述何者正確？","options":["(A) 可以有效避免醫療糾紛","(B) 屬於醫療糾紛發生後必要的病歷補登行為","(C) 雖然在倫理上有可議之處，在法律上卻是完全合法","(D) 不只在倫理上有可議之處，在法律上也是違法的行為"],"answer":3,"image":""},{"id":"md3-106-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"對於醫師診斷為不可治癒的癌症末期病患，在病人清醒情況下，根據安寧緩和醫療條例，下列那項要求合法？","options":["(A) 病人要求放棄施行心肺復甦術","(B) 未經病人同意，家屬要求放棄施行心肺復甦術","(C) 病人請醫師給予藥物以提早結束生命及痛苦","(D) 違反病人放棄施行心肺復甦術的意願，家人請求醫師全力救治，包括心肺復甦術"],"answer":0,"image":""},{"id":"md3-106-2-1","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"- 一位病人血液氣體分析顯示pH 7.51，PCO 49 mmHg，HCO38 mmol/L，下列何者正確？a23","options":["(A) 代謝性酸中毒（酸血症）","(B) 代謝性鹼中毒","(C) 呼吸性酸中毒","(D) 呼吸性鹼中毒"],"answer":1,"image":""},{"id":"md3-106-2-2","subject":"md3","topic":"家醫-行為與社區醫學","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"90歲的林奶奶患有血管性的失智症，近日來日夜顛倒，晚上無法睡覺，常常想要開門出去，外勞有時都拉不住，家人感到非常無助，來到門診尋求幫忙。下列有關失智症的敘述，何者正確？","options":["(A) 血管性的失智症是最常見的失智症","(B) 血管性的失智症可能來自於多次中風或大腦白質病變","(C) 初期失智症的病人一定會有記憶力喪失","(D) 失智症的病人如果有行為症狀，需要開立抗精神藥物，不需要行為治療"],"answer":1,"image":""},{"id":"md3-106-2-3","subject":"md3","topic":"急診醫學","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"65歲女性，過去僅有糖尿病的病史，第一次被診斷為高血壓，因為收縮壓在190～200 mmHg之間，由門診轉到急診，沒有任何不舒服，過去病人不知道自己有高血壓，下列何者處理欠佳？","options":["(A) 請病人稍作休息，再量一次血壓","(B) 詢問過去病史及家族病史","(C) 馬上給予舌下短效nifedipine降壓","(D) 注意有無神經學的變化"],"answer":2,"image":""},{"id":"md3-106-2-4","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"70歲女性，因雙側下肢水腫，氣促，呼吸困難來門診就醫，身體診察發現雙側肺囉音，心音發現S3 gallop，心臟超音波顯示左心室射出分率為55%，輕度二尖瓣及三尖瓣逆流合併舒張功能不良，有關下列敘述何者錯誤？","options":["(A) B-type natriuretic peptide（BNP）或者N-terminal pro-BNP可做為評估疾病嚴重度的指標","(B) 飲食的衛教方面應該限鹽","(C) 使用angiotensin-converting enzyme inhibitor已被證明對於此類病患長期的預後有幫助，應即刻開始使用","(D) 使用利尿劑改善症狀並控制好血壓是治療病患的首選做法"],"answer":2,"image":""},{"id":"md3-106-2-5","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"胡先生62歲患有็ࣾ病、高血壓於心臟科門診追蹤治療，主訴兩小時前開始嚴重上腹悶痛合併冒冷汗及嘔吐，在急診測得之心跳每分鐘約為52下，血壓為80/50 mmHg，頸靜脈鼓張，經診斷為急性心肌梗塞，下列何者心電圖變化最不可能和其診斷相關？","options":["(A) ST elevation在lead II, III, aVF","(B) ST depression在lead V1, V2","(C) ST elevation在lead V4R","(D) PR segment depression"],"answer":3,"image":""},{"id":"md3-106-2-6","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"陳小姐被發現有意識不清及黃疸而被送到急診就醫，檢查結果為total bilirubin：7.2 mg/dL（正常值：0.2～1.6 mg/dL）、direct bilirubin：4 mg/dL（正常值：0～0.3 mg/dL）、AST：478 U/L（正常值：5～45 U/L）、ALT：356 U/L（正常值：0～40 U/L）、alkaline phosphatase：102 U/L（正常值：10～100 U/L）、prothrombin time（INR）：3.1、albumin：3.6 g/dL（正常值：4.3～5.4 g/dL），下列之敘述何者錯誤？","options":["(A) 此病患可能發生hepatocellular jaundice","(B) 腹部超音波檢查膽管應無異常","(C) 此病患黃疸的病因，可能包括virus, autoimmune, toxin and metabolic disorder等","(D) 此病人之最可能病因為急性膽管炎"],"answer":3,"image":""},{"id":"md3-106-2-7","subject":"md3","topic":"內科-腫瘤","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"黃先生，60歲，經腹部電腦斷層、腹部血管攝影及肝臟切片檢查後確診為肝癌，下列敘述何者錯誤？","options":["(A) 手術切除對於小於5公分之單發性肝癌，是一種根除性（curative）的治療方法","(B) 肝腫瘤電燒治療對於小於3公分之單發性肝癌，治療成效良好","(C) 對於多發性肝癌，栓塞治療（trans-arterial embolization therapy, TAE）只會增加病患死亡率，不宜考慮","(D) 肝癌術後追蹤應包括腹部超音波及血中甲種胎兒蛋白（α-fetoprotein）檢查"],"answer":2,"image":""},{"id":"md3-106-2-8","subject":"md3","topic":"內科-腎臟","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"一位25歲女性病人被診斷為全身性紅斑性狼瘡（systemic lupus erythematosus, SLE），最近一次驗尿之RBC為50～75/HPF（high power field），每日尿蛋白為3.2公克，血中肌酸酐（creatinine）3個月內，由1.2 mg/dL上升至2.4 mg/dL，下列敘述何者錯誤？","options":["(A) 腎病理切片最可能是瀰漫增生性腎絲球腎炎（diffuse proliferative glomerulonephritis）","(B) 給予靜脈脈衝類固醇治療（pulse steroid therapy）","(C) 給予細胞毒性藥物如cyclophosphamide，此藥亦可用脈衝治療方式給予","(D) anti-double-stranded DNA抗體檢驗值的高低不可以當狼瘡腎炎活性的指標"],"answer":3,"image":""},{"id":"md3-106-2-9","subject":"md3","topic":"內科-腎臟","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"一位45歲男性病人有慢性C型肝炎病史，因尿中泡沫多及水腫且體重增加5公斤而來求診，其24小時尿蛋白流失為5公克，血中白蛋白（albumin）為2.4 g/dL，血中補體（complement）濃度下降，下列敘述何者錯誤？","options":["(A) 其蛋白尿程度已達腎病症候群之標準","(B) 病人血液中常出現冷凝蛋白（cryoglobulin）","(C) 較易出現腎動脈栓塞","(D) 若做腎臟穿刺，病理診斷最可能是MPGN（membranoproliferative glomerulonephritis）"],"answer":2,"image":""},{"id":"md3-106-2-10","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"一位61歲罹患乾癬症的病患，在7年之後，兩側手指逐漸腫脹有如香腸指，又遠端指間關節有發炎反應，且指甲變厚易脆（如附圖），最有可能的診斷為何？","options":["(A) osteoarthritis","(B) rheumatoid arthritis","(C) fungal infection","(D) psoriatic arthritis"],"answer":3,"image":"md3-106-2-10.jpeg"},{"id":"md3-106-2-11","subject":"md3","topic":"內科-血液","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"一位62歲病人，過去有心臟病史，正在接受治療，最近因出血傾向接受檢查，周邊血中血紅素、白血球及血小板數正常，prothrombin time（PT）INR 3.5，activated partial thromboplastin time 26”（正常對照27”）。下列何者是引起這位病人容易出血的最可能原因？","options":["(A) coumadin treatment","(B) heparin treatment","(C) liver disease","(D) von Willebrand disease"],"answer":0,"image":""},{"id":"md3-106-2-12","subject":"md3","topic":"內科-腫瘤","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"一位40歲亞裔女性病人，沒有抽過菸，最近被診斷為非小細胞肺癌第四期，腫瘤有EGFR（epidermal growth factor receptor）基因突變（exon 19 deletion），下列何種治療最為合適？","options":["(A) EGFR抑制劑","(B) EGFR抑制劑+化學治療","(C) 血管增生抑制抗體","(D) EGFR抑制劑+血管增生抑制抗體"],"answer":0,"image":""},{"id":"md3-106-2-13","subject":"md3","topic":"內科-胸腔","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"有關氣喘（bronchial asthma）的敘述，下列何者正確？","options":["(A) 吸入型類固醇（inhaled corticosteroid）的廣泛使用是近年來氣喘病患死亡率減少的主因之一","(B) 氣喘（bronchial asthma）的定義（definition）很容易達成共識，診斷也容易與其他疾病區隔分開","(C) 氣喘（bronchial asthma）病患的氣道黏膜（airway mucosa）發炎，主要是有白血球（neutrophils），B淋巴球（B-lymphocytes）和肥胖細胞（mast cells）浸潤造成","(D) 氣喘控制不良（poor control of bronchial asthma）的最主要原因是短效支氣管擴張劑（bronchodilators）不規則使用"],"answer":0,"image":""},{"id":"md3-106-2-14","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"28歲婦女產下健康男嬰2個月後，因體重增加、倦怠、怕冷、便秘來就診，目前仍哺乳中。病人自訴產前體檢皆為正常，但產後感覺力不從心，身體檢查除臉部圓大、皮膚略微乾燥外並無特殊發現。血壓150/100 mmHg（產前120/80 mmHg），脈搏60/min規則，抽血檢查Na：132 mM，K：3.5 mM，Ca：2.3 mM。下列那項檢查最具診斷價值：","options":["(A) ACTH，cortisol","(B) Blood glucose","(C) freeT4，hsTSH","(D) 憂鬱量表"],"answer":2,"image":""},{"id":"md3-106-2-15","subject":"md3","topic":"內科-感染","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"有一位22歲女性因發燒及頭痛一週就醫，最近兩天全身有淡淡紅疹。病患自訴兩週前曾至蘭嶼旅遊三天。理3學檢查在膕窩部位（popliteal area）有一黑色結痂病灶，無觸痛（如圖）。血液檢驗：白血球9,800/mm（Band 16％，Seg 35％，Mono9％，Lymph 40％），血紅素13.2 g/dL，血小板195,000/mm3；GOT/GPT：154/180 IU/L；胸部X光、腹部超音波肝脾、尿液檢驗，皆無異常。此病人最可能之診斷？","options":["(A) scrub typhus","(B) drug allergy","(C) chickenpox","(D) measles"],"answer":0,"image":"md3-106-2-15.jpeg"},{"id":"md3-106-2-16","subject":"md3","topic":"內科-感染","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"78歲女性患有高血壓、慢性腎功能不全、陳舊性中風，長期使用導尿管，居住在慢性養護機構；因發高燒兩天，消化不佳，解黑便及意識不清，住院治療。經檢查發現血液和尿液培養皆長出：具有廣效乙內醯胺酵素（extended-spectrum beta-lactamase，ESBL）之大腸桿菌（Escherichia coli），下列抗生素藥物治療及投與途徑，何者最適合用於治療初期？","options":["(A) oral cephalexin","(B) intravenous cefotaxime","(C) intravenous ertapenem","(D) intramuscular gentamicin"],"answer":2,"image":""},{"id":"md3-106-2-17","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"有關呼吸困難（dyspnea）之敘述，下列何者錯誤？","options":["(A) 焦慮不會引起呼吸困難","(B) 呼吸困難是一種主觀上對呼吸不順暢的感覺","(C) 呼吸困難的原因甚多，包括心衰竭或呼吸道阻塞","(D) 病人的呼吸困難，且伴隨著夜間陣發性呼吸困難（paroxysmal nocturnal dyspnea），其原因可能是心衰竭所致"],"answer":0,"image":""},{"id":"md3-106-2-18","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"有關水腫之敘述，何者正確？","options":["(A) 肝硬化引起水腫常伴隨頸靜脈曲張","(B) 單側下肢水腫常是因為靜脈或淋巴阻塞","(C) 血中蛋白質降低如nephrotic syndrome，不會引起臉或眼皮水腫","(D) 典型心衰竭引起的水腫，大致上和dependent sites無關"],"answer":1,"image":""},{"id":"md3-106-2-19","subject":"md3","topic":"醫學倫理與法規","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"依據美國內科醫學會（The American Board of Internal Medicine）與歐洲內科醫學會（The European Federation of Internal Medicine）於2002年提出之醫師憲章（Physician Charter）。下列何者不是醫師專業素養之基本原則？","options":["(A) 病人福祉優先原則（principle of primacy of patient welfare）","(B) 社會正義原則（principle of social justice）","(C) 實證醫學執業原則（principle of evidence-based practice）","(D) 病人自主原則（principle of patient autonomy）"],"answer":2,"image":""},{"id":"md3-106-2-20","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"下列有關風濕性心臟病合併僧帽瓣狹窄的敍述，何者錯誤？","options":["(A) 22正常僧帽瓣的開口大小為4～6 cm，若<1 cm為重度狹窄","(B) 常合併心房纖維顫動","(C) 常合併次發性肺高壓","(D) 聽診常發現高音舒張期雜音（high pitched early diastolic murmur）"],"answer":3,"image":""},{"id":"md3-106-2-21","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"下列有關頸靜脈壓力測量的敍述，何者錯誤？","options":["(A) 通常以右外頸靜脈（external jugular vein）測量最適當","(B) “a”波代表右心房收縮波型","(C) “c”波代表右心室收縮後，三尖瓣關閉","(D) 三尖瓣閉鎖不全會使“v”波變大"],"answer":0,"image":""},{"id":"md3-106-2-22","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"下列有關二尖瓣脫垂的敍述，何者錯誤？","options":["(A) 常見的病理變化為瓣膜呈現myxomatous change，好發於後葉瓣膜","(B) 好發於Marfan syndrome病患","(C) 好發於15～30歲的男性","(D) 大部分病人臨床無特別症狀，無須特別治療"],"answer":2,"image":""},{"id":"md3-106-2-23","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"一位55歲男性，有糖尿病病史，發生胸悶症狀約5小時來到急診，血壓140/100 mmHg，心跳每分鐘80次，經抽血及心電圖診斷為ST節段上升之心肌梗塞（ST-segment elevation myocardial infarction），有關此患者的治療，下列敘述何者錯誤？","options":["(A) 鈣離子阻斷劑在急性期可以緩解病患的症狀，特別是短效dihydropyridines類的鈣離子阻斷劑","(B) 如果沒有絕對禁忌症，應給予aspirin 160～325 mg","(C) 如果沒有禁忌症（如低血壓或曾服用phosphodiesterase-5 inhibitor），可以嘗試使用舌下含片nitroglycerin來緩解病患的症狀","(D) 如果沒有禁忌症，可給予靜脈注射或者口服的乙型交感神經阻斷劑（β-blockers）"],"answer":0,"image":""},{"id":"md3-106-2-24","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"有關心臟瓣膜置換或修補手術的死亡率，下列何者錯誤？","options":["(A) 主動脈瓣膜置換手術死亡率比二尖瓣（僧帽瓣）置換手術高","(B) 瓣膜置換手術加上冠狀動脈繞道手術比單純瓣膜置換手術死亡率高","(C) 多瓣膜置換手術比單一瓣膜置換手術死亡率高","(D) 二尖瓣（僧帽瓣）修補手術死亡率較二尖瓣置換手術死亡率低"],"answer":0,"image":""},{"id":"md3-106-2-25","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"30歲男性在大量喝酒後嘔吐，嘔吐物中有鮮血，接受胃鏡檢查及治療，結果在食道胃交接處有出血並做止血夾治療（如圖），其診斷最有可能為下列何者？","options":["(A) esophageal varices","(B) peptic ulcer","(C) Mallory-Weiss tear","(D) gastroesophageal reflux disease"],"answer":2,"image":"md3-106-2-25.jpeg"},{"id":"md3-106-2-26","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"下列有關膽酸（bile acid）的敘述，何者錯誤？","options":["(A) 無法經食物攝取獲得","(B) 由肝臟合成","(C) 絕大部分在空腸（jejunum）再吸收","(D) 原發性膽道肝硬化（primary biliary cirrhosis）患者因膽酸分泌發生問題而可能產生steatorrhea，甚至因此而導致鈣和維生素Ｄ的吸收不良"],"answer":2,"image":""},{"id":"md3-106-2-27","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"引起猛爆性肝炎常見的原因，不包括下列何者？","options":["(A) 藥物","(B) A型肝炎","(C) B型肝炎","(D) 熬夜"],"answer":3,"image":""},{"id":"md3-106-2-28","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"幽門螺旋桿菌（Helicobacter pylori）已知是部分消化道疾病的致病因子，下列何者除外？","options":["(A) 胃食道逆流（reflux esophagitis）","(B) 萎縮性胃炎（atrophic gastritis）","(C) B細胞胃淋巴癌（B cell gastric lymphoma）","(D) 十二指腸潰瘍（duodenal ulcer）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第28題一律給分 (原公告答案 A)"},{"id":"md3-106-2-29","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"一位42歲女性，主訴漸進性茶色尿、皮膚變黑且癢、無飲酒史、無長期中西藥服用史，身體診察顯示有黃疸、無腹部壓痛。初步血液檢查顯示：WBC：3800/mm3、Hb：11.8 g/dL、血小板：98000/mm3、ALT（GPT）：48 U/L、AST（GOT）：62 U/L、bilirubin（total/direct）：5.8/3.9 mg/dL、鹼性磷酸酶（alkaline phosphatase）：586 U/L（正常值＜100 U/L）、HBsAg：陰性、anti-HCV：陰性。下列何者不是適宜之檢查：","options":["(A) 腹部超音波檢查","(B) anti-mitochondrial antibody","(C) serum ceruloplasmin","(D) serum γ-GT"],"answer":2,"image":""},{"id":"md3-106-2-30","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"Ranson計分法是判定急性胰臟炎嚴重度很好的方法，最初48小時非用以計分之項目為：","options":["(A) 住院後血比容（hematocrit）","(B) 動脈血氧氣濃度","(C) 血清鉀","(D) 血清鈣"],"answer":2,"image":""},{"id":"md3-106-2-31","subject":"md3","topic":"內科-腎臟","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"下列何種腎臟替代療法為末期腎病之最佳治療（treatment of choice）？","options":["(A) 血液透析（hemodialysis）","(B) 腹膜透析（peritoneal dialysis）","(C) 腎臟移植（kidney transplantation）","(D) 血液過濾透析（hemodiafiltration）"],"answer":2,"image":""},{"id":"md3-106-2-32","subject":"md3","topic":"內科-腎臟","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"一名35歲女性因夜尿（nocturia）就診，身體檢查：血壓150/94 mmHg，脈搏78/min，其它檢查無異常。實驗室檢驗：blood urea nitrogen 15 mg/dL，creatinine 1.0 mg/dL，空腹血糖97 mg/dL，血鈉142 mmol/L，血鉀 - 2.8 mmol/L，血氯90 mmol/L，尿沉渣正常，尿鉀排泄量50 mmol/day，動脈氣體pH 7.45，[HCO3] 30 mmol/L，PaCO2 44 mmHg，則本病人最可能罹患？","options":["(A) 腎小管酸血症（renal tubular acidosis）","(B) 巴特氏症候群（Bartter’s syndrome）","(C) 絨毛狀腺瘤（villous adenoma）","(D) 原發性皮質醛酮症（primary aldosteronism）"],"answer":3,"image":""},{"id":"md3-106-2-33","subject":"md3","topic":"內科-腎臟","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"C型肝炎的病人有高達30%會伴隨有腎臟病變，其中以下列何種變化最為少見？","options":["(A) 冷凝球蛋白腎小球腎炎（cryoglobulinemic glomerulonephritis）","(B) 膜性腎病變（membranous glomerulonephritis）","(C) 急性腎間質腎炎（acute interstitial nephritis）","(D) 第一型膜增生性腎小球腎炎（type 1 membranoproliferative glomerulonephritis）"],"answer":2,"image":""},{"id":"md3-106-2-34","subject":"md3","topic":"內科-腎臟","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"40歲女性因為無痛性巨觀性血尿（painless gross hematuria）求診。下列那一項檢查最能夠判別血尿的來源是腎絲球病變引起的？","options":["(A) 血清肌酸酐濃度","(B) 血清補體C3濃度","(C) 尿液紅血球的形態","(D) 靜脈內泌尿攝影術（intravenous urography）"],"answer":2,"image":""},{"id":"md3-106-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"有關僵直性脊椎炎之敘述，下列何者錯誤？","options":["(A) HLA-B27陽性者較B27陰性者，易出現葡萄膜炎（uveitis）","(B) HLA-B27陽性者較陰性者，家族傾向較高","(C) 一般人口中，20%之HLA-B27陽性者，可出現僵直性脊椎炎","(D) HLA-B27在北美之印第安人（Indians）其盛行率，遠高於臺灣原住民"],"answer":[2,3],"image":"","answer_note":"更正:第35題答Ｃ、Ｄ給分"},{"id":"md3-106-2-36","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"一名50歲婦女，其主訴為突發性右肩嚴重疼痛，先前使用消炎鎮痛劑數天，卻無法有效緩解。到院時，右肩活動困難，觸診時subdeltoid bursa有明顯壓痛，尿酸8.0 mg/dL，rheumatoid factor 30 U/mL（正常＜20），經由X光及MRI照相結果如圖示，下列何種疾病最有可能？","options":["(A) 痛風關節炎","(B) 類風濕性關節炎","(C) apatite晶體引發之關節炎","(D) 冰凍肩（frozen shoulder）"],"answer":2,"image":"md3-106-2-36.jpeg"},{"id":"md3-106-2-37","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"一病人有狼瘡病腎炎（lupus nephritis），有蛋白尿2.0 gm/day，合併腎功能不足（creatinine 2.0 mg/dL），下列何種藥物，最不適用於此病人？","options":["(A) cyclosporine","(B) leflunomide","(C) rituximab","(D) mycofenolate mofetil"],"answer":0,"image":""},{"id":"md3-106-2-38","subject":"md3","topic":"內科-風濕免疫過敏","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"一位56歲婦女主訴兩側手指關節及膝關節疼痛已3個月，且兩眼乾澀，也常口渴喝水，最近2星期右側腮腺突然腫脹，下列那一項檢驗最不會出現陽性結果？","options":["(A) rheumatoid factors","(B) antinuclear antibodies","(C) anti-SS-A（Ro）/SS-B（La）antibodies","(D) anticardiolipin IgG and IgM"],"answer":3,"image":""},{"id":"md3-106-2-39","subject":"md3","topic":"內科-腫瘤","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"有關癌症患者化學治療期間發生細菌感染，在下列何種情況最常見？","options":["(A) corticosteroid治療","(B) 中性顆粒細胞（neutrophil）計數<500/µL","(C) Hb<7 gm/dL","(D) 體重損失>10%"],"answer":1,"image":""},{"id":"md3-106-2-40","subject":"md3","topic":"內科-腫瘤","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"一30歲男子因流鼻血4週求診。理學檢查顯示左邊submanibular angle有一firm、non-tender and fixed mass，該腫塊沒有局部感染之徵候，在這個階段最適當的檢查為何？","options":["(A) 淋巴結超音波","(B) 切除生檢（excisional biopsy）","(C) 細針穿刺（fine needle aspiration）","(D) fiberoscopic檢查和鼻咽部的生檢"],"answer":3,"image":""},{"id":"md3-106-2-41","subject":"md3","topic":"內科-血液","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"一位18歲男性因頸部淋巴結腫大應診，抽血檢查發現血紅素為12.5 gm/dL，白血球3550/µL，其中blast 2%，血小板135000/µL。胸部X光如圖所示。此病人最可能的診斷為何？","options":["(A) precursor B cell lymphoblastic lymphoma/leukemia","(B) precursor T cell lymphoblastic lymphoma/leukemia","(C) Burkitt's lymphoma","(D) adult T cell lymphoma/leukemia"],"answer":1,"image":"md3-106-2-41.jpeg"},{"id":"md3-106-2-42","subject":"md3","topic":"內科-血液","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"有關low-molecular-weight heparin（LMWH）特點的敘述，何者錯誤？","options":["(A) LMWH的使用劑量一般可依體重決定就好","(B) 一般可以用凝血時間的檢驗做監測，維持約正常值的兩倍左右","(C) 必要時可以監測Factor Xa activity看LMWH的藥量是否恰當","(D) LMWH主要由腎臟代謝排出"],"answer":[0,1],"image":"","answer_note":"更正:第42題答Ａ、Ｂ給分"},{"id":"md3-106-2-43","subject":"md3","topic":"內科-血液","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"有一32歲男性主訴兩三個月來易倦，腹脹。理學檢查發現體溫正常，結膜蒼白，脾臟在左肋下沿可觸診；血液常規檢查：WBC 120,000/uL，blast/promyelocyte/myelocyte/metamyelocyte/neutrophil/monocyte/eosinophil/ basophil/lymphocyte = 1/3/6/10/54/3/15/5/3％，骨髓染色體46XY，t（9；22）in 19/20 metaphases。目前學界共識第一線治療為何？","options":["(A) hydroxyurea","(B) interferon-alpha","(C) tyrosine kinase inhibitor","(D) allogeneic hematopoietic stem cell transplantation"],"answer":2,"image":""},{"id":"md3-106-2-44","subject":"md3","topic":"內科-血液","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"下列何種病人得到急性骨髓性白血病的機率不會較一般人高？","options":["(A) 唐氏症（Down syndrome）","(B) 類風濕性關節炎（rheumatoid arthritis）","(C) 長期接觸苯（benzene）","(D) 過去用過etoposide（VP-16）"],"answer":1,"image":""},{"id":"md3-106-2-45","subject":"md3","topic":"內科-血液","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"多發性骨髓瘤病患出現高鈣血症時，下列何種藥物治療不能達到治療目的？","options":["(A) bisphosphonate","(B) fluoride","(C) corticosteroid","(D) calcitonin"],"answer":1,"image":""},{"id":"md3-106-2-46","subject":"md3","topic":"內科-胸腔","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"下列有關bronchiectasis的治療敘述，何者錯誤？","options":["(A) 對反覆感染的病患應長期使用抗生素，以防止呼吸道進一步的破壞","(B) 適當的使用支氣管擴張劑可以改善病患的症狀","(C) 肺部復健改善呼吸道痰液蓄積，扮演重要的角色","(D) aspergilloma所引起反覆咳血，可以考慮外科切除治療"],"answer":0,"image":""},{"id":"md3-106-2-47","subject":"md3","topic":"內科-胸腔","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"使用成人呼吸器 \"volume-cycled\" 通氣模式時，降低吸氣流量（flow rate）之設定，而維持其他設定，會產生下列何種現象？","options":["(A) 延長吸氣時間（Ti）","(B) 增加潮氣容積（V）T","(C) 增加尖峰吸氣壓（PIP）","(D) 增加呼吸次數（RR）"],"answer":0,"image":""},{"id":"md3-106-2-48","subject":"md3","topic":"內科-胸腔","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"50歲男性，體重60公斤。因燒燙傷合併急性呼吸窘迫症候群接受呼吸器治療，三天後其動脈血液氣體分析為：pH = 7.50；PaCO = 22 mmHg；PaO= 78 mmHg。其呼吸器設定吸入氧氣濃度（FiO）= 0.5，呼吸22 2次數 = 14次/min，潮氣容積（tidal volume）= 660 mL，吐氣末正壓值（PEEP）= 10 cmHO，吸氣最大流量2（peak inspiratory flow）= 60 L/min。則應調整那個參數值最為妥當？","options":["(A) 增加吸入氧氣濃度（FiO）2","(B) 增加吐氣末正壓值（PEEP）","(C) 減少潮氣容積（tidal volume）","(D) 增加吸氣最大流量（peak inspiratory flow）"],"answer":2,"image":""},{"id":"md3-106-2-49","subject":"md3","topic":"內科-胸腔","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"下列何者不是滲出性肋膜積液（exudative pleural effusion）的常見原因？","options":["(A) 肺炎","(B) 惡性腫瘤","(C) 胰臟炎","(D) 心臟衰竭"],"answer":3,"image":""},{"id":"md3-106-2-50","subject":"md3","topic":"內科-腫瘤","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"關於肺癌病人，下列何者有比較高的表皮生長因子受體基因變異（epidermal growth factor receptor mutation）？①女性 ②腺癌（adenocarcinoma） ③抽煙 ④亞洲人種 ⑤小細胞癌（small cell carcinoma）","options":["(A) ①②③","(B) ③④⑤","(C) ①②④","(D) ①②⑤"],"answer":2,"image":""},{"id":"md3-106-2-51","subject":"md3","topic":"內科-胸腔","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"下列何者不是以low tidal volume; high PEEP改善acute respiratory distress syndrome（ARDS）的目的？","options":["(A) 減少barotrauma","(B) 減少氧氣毒性（oxygen toxicity）","(C) 減少死亡率","(D) 減少呼吸器引發的感染"],"answer":3,"image":""},{"id":"md3-106-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"24歲男性，兩手張開之長度較身高多兩吋，陰莖短小，無陰毛，嗅覺不佳。下列何者是此病人的檢查結果？","options":["(A) 睪丸小而軟","(B) 性染色體為47XXY","(C) 身材矮小，三角臉","(D) 重度肥胖，智障"],"answer":0,"image":""},{"id":"md3-106-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"35歲女性，月經不規則已有兩年，最近八個月則完全無月經。身體檢查發現乳房有乳汁分泌。腦垂腺核磁共振檢查，發現腦垂腺前葉有一直徑1.5公分的腫瘤。則下列何者錯誤？","options":["(A) 若不治療，長期會造成骨質疏鬆","(B) 腫瘤往上壓迫會造成視野缺損","(C) 可使用sulpiride治療","(D) 手術成功率與腫瘤大小呈負相關"],"answer":2,"image":""},{"id":"md3-106-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"18歲女性，左頸部腫痛且皮膚變紅，伴隨發燒，則下列何診斷最常見？","options":["(A) 亞急性甲狀腺炎","(B) 先天有梨狀竇瘻管（pyriform sinus fistula）","(C) 先天有甲狀腺舌管囊腫（thyroglossal duct cyst）","(D) 甲狀腺未分化癌"],"answer":1,"image":""},{"id":"md3-106-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"腦下垂體受到放射線治療，最常出現的激素異常是下列何者？","options":["(A) 生長激素（GH）","(B) 泌乳激素（Prolactin）","(C) 甲狀腺促進素（TSH）","(D) 腎上腺促進素（ACTH）"],"answer":0,"image":""},{"id":"md3-106-2-56","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"臨床上最常見的庫欣氏症候群（Cushing’s syndrome）原因是：","options":["(A) 腎上腺皮質腫瘤","(B) 腦下垂體腫瘤","(C) 類固醇過量使用","(D) 胸腺腫瘤"],"answer":2,"image":""},{"id":"md3-106-2-57","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"下列關於第二型糖尿病治療之敘述，何者錯誤？","options":["(A) 一般以糖化血紅素（hemoglobin A1c）小於7%為目標","(B) 口服降血糖藥物以磺氨尿素類（sulfonylurea）製劑為第一線用藥","(C) DPP-4抑制劑之功能是提高餐後血中GLP-1之濃度","(D) α-glucosidase抑制劑主要用於降低餐後血糖"],"answer":1,"image":""},{"id":"md3-106-2-58","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"下列何種病人在接受牙科治療時，不需要給預防性抗生素以預防心內膜炎？","options":["(A) 有二尖瓣（mitral valve）脫垂但無二尖瓣逆流的病人","(B) 有人工心臟瓣膜的病人","(C) 有心內膜炎病史的病人","(D) 心臟移植後有瓣膜病變的病人"],"answer":0,"image":""},{"id":"md3-106-2-59","subject":"md3","topic":"內科-感染","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"1歲大女嬰出現發燒、咳嗽、流鼻水及結膜炎，發燒後3～4天口腔出現柯氏斑點（Koplik's spots），最有可能診斷為何？","options":["(A) 嬰兒玫瑰疹","(B) 猩紅熱","(C) 川崎氏症","(D) 麻疹"],"answer":3,"image":""},{"id":"md3-106-2-60","subject":"md3","topic":"內科-感染","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"有關微生物及癌症的關係，下列何者關聯性最低？","options":["(A) Helicobacter pylori vs.胃癌（gastric cancer）","(B) Human papilloma virus vs.子宮癌（uterine cancer）","(C) Human herpesvirus type 8 vs.卡波氏肉瘤（Kaposi’s sarcoma）","(D) Epstein-Barr virus vs.霍金氏淋巴癌（Hodgkin’s lymphoma）"],"answer":1,"image":""},{"id":"md3-106-2-61","subject":"md3","topic":"內科-感染","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"下列各項有關西尼羅病毒感染（West Nile virus infection）之敘述，何者最不適當？","options":["(A) 鳥類是主要的傳染媒介（vector）","(B) 大部分受感染者為無症狀的感染","(C) 其嚴重併發症為腦炎及腦膜炎之神經侵襲性疾病表現","(D) 偶會合併嚴重致死性肝炎"],"answer":0,"image":""},{"id":"md3-106-2-62","subject":"md3","topic":"內科-感染","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"下列那一種微生物導致腹瀉所需之致病原數量最大？","options":["(A) Shigella","(B) Entamoeba histolytica","(C) Giardia lamblia","(D) Vibrio cholerae"],"answer":3,"image":""},{"id":"md3-106-2-63","subject":"md3","topic":"內科-感染","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"有關抗生素的使用，下列敘述何者錯誤？","options":["(A) 不當的使用抗生素會增加細菌抗藥性的產生，以及巨大的醫療浪費","(B) 不當的使用抗生素會增加病患的死亡率及副作用","(C) 抗生素之選用必須依病人年齡、免疫情況、代謝情況、營養情況、水和電解質平衡、肝和腎功能、病情嚴重程度等而調整","(D) 抗生素藥物劑量濃度高低與細菌是否產生抗藥性無關"],"answer":3,"image":""},{"id":"md3-106-2-64","subject":"md3","topic":"急診醫學","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"一位向來健康狀況良好之50歲男士登山迷路失聯，入夜後山區溫度驟降，禦寒衣物不足。次日搜救人員找到該男士立即送醫。身體檢查發現：昏迷、心跳每分鐘40次、呼吸每分鐘8次、血壓60/40毫米汞柱、體溫26℃、無明顯外傷、抽痰無明顯咳嗽反應。到院5分鐘後，病友突然發生心室顫動（ventricular fibrillation）。針對此病友之優先處理，下列何者最合宜？","options":["(A) 置放肺動脈導管或中心靜脈導管以監控體液量","(B) 使用溫熱乳酸林格氏液（lactated Ringer's solution）以補充體液不足","(C) 小心置放氣管內管以保護氣道","(D) 反覆施行去顫術（defibrillation）以矯正心室顫動"],"answer":2,"image":"","answer_note":"更正:第64題答Ｃ給分 (原公告答案 D)"},{"id":"md3-106-2-65","subject":"md3","topic":"急診醫學","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"承上題，下列何種方式可以最快提高上述男士之體溫？","options":["(A) 體外循環（cardiopulmonary bypass）","(B) 血液透析","(C) 腹膜透析","(D) 45℃溫水洗胃（gastric lavage）"],"answer":0,"image":""},{"id":"md3-106-2-66","subject":"md3","topic":"家醫-行為與社區醫學","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"下列各年齡層，那一個年齡層，生理及社會層面上，個體間差異性最大？","options":["(A) 孩童","(B) 青少年","(C) 中年","(D) 老年"],"answer":3,"image":""},{"id":"md3-106-2-67","subject":"md3","topic":"內科-內分泌代謝","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"下列關於肥胖的敘述，何者錯誤？","options":["(A) 減重是降低血壓的非藥物治療手段之一","(B) 成人肥胖與兒童肥胖無關","(C) 肥胖與血脂異常、第二型糖尿病、癌症有關","(D) 每天減少500至1000大卡，一星期大約可減少0.5～1公斤"],"answer":1,"image":""},{"id":"md3-106-2-68","subject":"md3","topic":"內科-胸腔","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"一位21歲男大學生因發燒咳嗽五天而就診。無重大疾病史，且不抽菸。症狀一開始是乾咳，逐漸出現稀疏的白色痰。他同時抱怨全身倦怠、頭痛及肌肉酸痛，沒有喉嚨痛、流鼻水等症狀。他有一位室友在五天前有類似的症狀。理學檢查發現體溫39℃，咽喉僅稍為泛紅，肺部可聽到下肺野有一些囉音（rales/crackles），無其它異常。下列那一處置最適當？","options":["(A) 可能是病毒感染，自己會好轉，不必作任何檢查","(B) 給予ampicillin治療，不必作任何檢查","(C) 安排胸部電腦斷層檢查，以免誤診","(D) 依臨床發現，安排胸部X光檢查"],"answer":3,"image":""},{"id":"md3-106-2-69","subject":"md3","topic":"醫學倫理與法規","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"一位28歲女性因氣喘控制不良，長期服用口服類固醇，而產生體重增加及情緒失調，若繼續下去，也可能造成股骨頭缺血性壞死（avascular necrosis）。下列有關病情告知的敘述，何者最正確？","options":["(A) 擔心告知後，會讓病人害怕而停止服藥造成氣喘惡化，故不應告知","(B) 為避免類固醇副作用的產生，不論氣喘控制與否，建議病人減少用量","(C) 告知病情，由病人自行決定是否繼續服用類固醇","(D) 不說明理由轉介至其它專科醫師處理"],"answer":2,"image":""},{"id":"md3-106-2-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"高媽媽帶著剛滿11個月的小孩前來看咳嗽及流鼻水，詢問高媽媽有關高小弟的疫苗接種情況，依據衛生福利部國民健康署的建議，高小弟應已接受下列那些疫苗注射？①卡介苗 ②B型肝炎 ③白喉破傷風百日咳混合疫苗 ④小兒麻痺口服疫苗 ⑤水痘疫苗 ⑥麻疹腮腺炎德國麻疹混合疫苗 ⑦日本腦炎疫苗 ⑧破傷風減量白喉混合疫苗？","options":["(A) ③④⑤⑥⑦","(B) ①②③④","(C) ①③④⑤⑥","(D) ①②⑤⑧"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第70題一律給分 (原公告答案 B)"},{"id":"md3-106-2-71","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"接受荷爾蒙替代療法（HRT）治療的女性，其冠狀動脈疾病之年發生率為37/10,000，對照組之冠狀動脈疾病年發生率為30/10,000。接受HRT治療發生冠狀動脈疾病的NNH（number needed to harm）為何？","options":["(A) 1292","(B) 1428","(C) 975","(D) 2104"],"answer":1,"image":""},{"id":"md3-106-2-72","subject":"md3","topic":"家醫-行為與社區醫學","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"戒菸門診中有一位40歲男性病人想要在一個月之內採取戒菸行動，是屬於跨越理論模式（transtheoretical model）中之那一期？","options":["(A) 未考慮階段（precontemplation）","(B) 考慮階段（preparation）","(C) 沈思階段（contemplation）","(D) 行動階段（action）"],"answer":1,"image":""},{"id":"md3-106-2-73","subject":"md3","topic":"家醫-行為與社區醫學","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"承上題，基層醫師介入之方法為：","options":["(A) 檢討病人戒菸計畫，減少對抽菸之誘惑情感","(B) 加強病人認知戒菸之好處，降低對抽菸好處之看法，使病人最後較趨向於戒菸","(C) 鼓勵病人設定開始戒菸的日期","(D) 討論抽菸對健康之影響"],"answer":2,"image":""},{"id":"md3-106-2-74","subject":"md3","topic":"影像醫學","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"病人主訴急性上腹疼痛，噁心嘔吐，腹部電腦斷層檢查呈現如圖，下列那一項診斷最正確？","options":["(A) acute gastritis","(B) ischemic bowel disease","(C) acute duodenitis","(D) acute pancreatitis"],"answer":3,"image":"md3-106-2-74.jpeg"},{"id":"md3-106-2-75","subject":"md3","topic":"內科-消化肝膽胰","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"56歲男性，有B型肝炎病史多年且有肝硬化，2個月前發生肝昏迷，經治療後改善，他家人發現他最近幾天有點異樣，就是有行為改變，且講話變得比較慢，也有嗜睡現象（drowsiness），此情形是肝腦病變（hepatic encephalopathy）的第幾期？","options":["(A) 第一期","(B) 第二期","(C) 第三期","(D) 第四期"],"answer":1,"image":""},{"id":"md3-106-2-76","subject":"md3","topic":"內科-血液","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"一位42歲女性病患，因右下肢腫痛多日來急診求診，經診斷是深層靜脈栓塞（deep vein thrombosis），下列何者較不可能是此疾病之危險因子？","options":["(A) 癌症病史","(B) 肥胖","(C) 懷孕","(D) 糖尿病"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第76題一律給分。 (原公告答案 D)"},{"id":"md3-106-2-77","subject":"md3","topic":"內科-心臟血管","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"一位40歲病患突發心悸、臉色蒼白、冒冷汗、意識模糊，血壓70/30 mmHg，其心電圖如下，應做何處置較適當？","options":["(A) 施予頸動脈竇按摩","(B) 注射atropine","(C) 同步心臟整流（cardioversion）","(D) 注射adenosine"],"answer":2,"image":"md3-106-2-77.jpeg"},{"id":"md3-106-2-78","subject":"md3","topic":"內科-感染","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"一位30歲健康男性，準備到國外旅遊，有關旅行者腹瀉（traveler' s diarrhea）的敘述，下列何者錯誤？","options":["(A) 應該使用抗生素預防旅行者腹瀉","(B) 細菌感染是旅行者腹瀉最常見之致病原因","(C) 如發生腹瀉，治療上以補充液體最重要","(D) 大部分感染性腹瀉會自己好（self-limited）"],"answer":0,"image":""},{"id":"md3-106-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"黃太太來門診看家庭醫師林醫師，說上高二的兒子咳嗽、流鼻水2天，想為他拿感冒藥。下列林醫師的那一種作法最恰當？","options":["(A) 說明醫師未親自診察不可給病人開藥而拒絕她的請求","(B) 向黃太太說明為她兒子的健康及課業著想，此次為他開藥但以後就不可以了","(C) 詳細詢問黃太太她兒子有沒有發燒、咳嗽及精神狀況後再做決定","(D) 向黃太太說明因孩子沒來，就照上次因感冒來看診的咳嗽及流鼻水藥開給他，若出現發燒或症狀變嚴重要立刻帶他就醫"],"answer":0,"image":""},{"id":"md3-106-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"依據「醫療法」中說明病情的相關規定，下列敘述何者正確？","options":["(A) 說明病情須由具醫師身分者為之","(B) 說明的對象僅限病人本人","(C) 說明的內容包括病情、治療方針、處置、用藥、預後情形及可能之不良反應","(D) 說明時須在病歷上記錄時間、地點、說明內容、說明的對象等"],"answer":2,"image":""},{"id":"md3-107-1-1","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"與年輕人相比，老年人罹患肺炎時的相關症狀，下列敘述何者正確？","options":["(A) 發燒的比例比年輕人高","(B) 咳嗽有痰的比例比年輕人高","(C) 產生心智功能障礙的比例比年輕人高","(D) 產生胸痛的比例比年輕人高"],"answer":2,"image":""},{"id":"md3-107-1-2","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"一位32歲男性馬拉松選手因為近日常覺得疲倦要求檢查。他五天前剛參加一場比賽，表現並沒有異狀。身體診察沒有異常，實驗室檢查了血色素與甲狀腺促素（TSH），檢查數值都正常。他的太太發現近日他在睡覺時常會打鼾，進行了睡眠檢查沒有發現呼吸中止，但24小時心電圖紀錄，在睡眠當中心跳每分鐘介於42～58次，清醒時心率則是每分鐘66～78次之間。針對該病人的心跳狀況應採取下列何項處置？","options":["(A) 安排住院接受心臟電氣生理檢查","(B) 不須治療","(C) 轉介安排心率節律器置入","(D) 給予頸動脈竇（carotid sinus）按摩"],"answer":1,"image":""},{"id":"md3-107-1-3","subject":"md3","topic":"內科-心臟血管","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"36歲有抽菸男性，因胸痛來到急診，胸痛已有八個小時，會傳向雙側上臂，且胸痛會因吸氣而加重，躺下時更嚴重，在坐起時上半身略向前傾會好一些。身體診察血壓140/72毫米汞柱，心跳每分鐘96次，沒用氧氣時血氧飽和度百分之九十八。肺部聽診沒有異常，只在左下胸骨邊緣聽到具三個成份的摩擦聲（three component friction rub）。此時進行心電圖檢查最可能看到：","options":["(A) 胸前導程反向T波（inverted T wave）","(B) PR節段在第二、第三和aVF導程上升","(C) 胸前導程（V1 – V6），ST段凸形彎曲（convex curvature）上升","(D) 胸前導程（V2 – V6）與第一導程，aVL導程，ST段凹形彎曲（concave curvature）上升"],"answer":3,"image":""},{"id":"md3-107-1-4","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"一位60歲男性因突然大量吐血而被送至急診，呈休克狀態，經緊急輸液治療後，病情改進。發病前並未喝酒及嘔吐，也沒有服用非類固醇消炎止痛藥（NSAID, non-steroidal anti-inflammatory drugs），最近也無特殊壓力。他是B型肝炎病毒慢性感染者。這位病人最可能是下列那種病灶出血？","options":["(A) 食道靜脈曲張破裂出血","(B) 胃癌出血","(C) 出血性胃炎","(D) 十二指腸第二部分出血"],"answer":0,"image":""},{"id":"md3-107-1-5","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"一位病人因腹瀉而來就醫。他自3天前開始腹瀉，大多為水狀排泄物，每天至少十次，偶而伴有腹痛，同時發燒至38.6oC，acetaminophen可稍退燒，但會再燒。他沒有噁心、嘔吐，但因怕腹瀉而不敢進食及喝水。下列各項敘述，何者錯誤？","options":["(A) 他可能有感染性腹瀉（infectious diarrhea），應趕快檢查其病因","(B) 其大便應送檢，包括pus cells及parasites ova，甚至細菌及病毒培養","(C) 除了補充水份，應立即給予強力止瀉藥以遏止腹瀉","(D) 若大便檢查發現pus cells，在正式病原尚未確定之前，試用抗生素（如quinolone或metronidazole）是合宜的"],"answer":2,"image":""},{"id":"md3-107-1-6","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"一位病人發現其小便像濃茶，至醫院就醫時，醫師也在身體診察中確認其皮膚及鞏膜有泛黃現象，小便檢驗發現bilirubin（3+）。下列各項檢查或檢驗，何者最不具診斷效益？","options":["(A) 腹部超音波檢查","(B) 抽血檢驗bilirubin（total）及bilirubin（direct），觀察二者之關聯","(C) 抽血檢驗amylase和lipase","(D) 抽血檢驗alkaline phosphatase及γ-glutamyl transpeptidase（γ-GT）"],"answer":2,"image":""},{"id":"md3-107-1-7","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"林小姐最近因疲累、噁心、右上腹不適到門診求診。身體診察顯示她有鞏膜泛黃現象，抽血檢查結果如下：alanine aminotransferase（ALT）：592 U/L（normal：0～40）；aspartate aminotransferase（AST）：204 U/L（normal：5～45）；total bilirubin：4.2 mg/dL（normal：0.2～1.6）；direct bilirubin：3.5 mg/dL（normal：0～0.3）；alkaline phosphatase（ALK-P）：62 U/L（normal: 10-100）；gamma-glutamyl transpeptidase（γ-GT）：54 U/L（normal：6～60）。下列各項檢查，何者最不適合？","options":["(A) HBsAg","(B) anti-nuclear antibody","(C) perinuclear anti-neutrophil cytoplasmic antibody（pANCA）","(D) anti-HAV IgM"],"answer":2,"image":""},{"id":"md3-107-1-8","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"一位50歲病人罹患慢性腎絲球腎炎20年，現出現尿毒症狀，且血中肌酸酐為11.0 mg/dL，BUN 120 mg/dL，病人選擇血液透析，下列敘述何者錯誤？","options":["(A) 長期血液透析，單次透析其尿素氮（BUN）減少的比率達到60%是足夠的","(B) 大多數臺灣病人接受每週3次，每次4小時的治療","(C) 所用透析液一般用重碳酸鹽來矯正尿毒病人的酸中毒（酸血症）","(D) 肌肉痙攣（muscle cramps）是透析時常見的併發症"],"answer":0,"image":""},{"id":"md3-107-1-9","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"一位55歲病人因腫瘤而安排須注射顯影劑（contrast medium）的電腦斷層攝影（CT scan），下列敘述何者錯誤？","options":["(A) 顯影劑腎病變產生的原因包括腎小管阻塞或腎血行動力學改變","(B) 顯影劑腎病變很少出現尿液fractional excretion of sodium（FeNa）＜1%","(C) 糖尿病是產生顯影劑腎病變的危險因子之一","(D) 高危險病人一定要做含顯影劑之檢查時，可先適度補充液體（hydration）"],"answer":1,"image":""},{"id":"md3-107-1-10","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"30歲的婦女，產前7天的血壓正常，血液肌酸酐0.6 mg/dL。產後當天有出血、高血壓、少尿、水腫。理學檢查皮膚沒有紅斑或紫斑，血液Hb 8.0 g/dL，血小板70,000/mm3，血液抹片有fragmented RBCs，haptoglobin下降，BUN 100 mg/dL，肌酸酐3.6 mg/dL，尿液osmolality 400 mOsmol/kg HO，尿液Na+ 10 2 mmol/L，尿液紅血球20～30/HPF，尿液蛋白質trace。最可能的診斷是：","options":["(A) 急性腎小管壞死（acute tubular necrosis）","(B) 溶血性尿毒症候群（hemolytic uremic syndrome）","(C) Goodpasture氏症候群","(D) 冷凝球蛋白血症（cryoglobulinemia）"],"answer":1,"image":""},{"id":"md3-107-1-11","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"一位47歲的女性，近三年來有輕度口渴、掉髮、冬天手指頭會變白及變紫。另外，在手掌及手背有明顯的微血管擴張（telangiectasis）。近半年有吞嚥障礙。經抽血檢查發現ANA 1：160 centromere pattern，C3 108 mg/dL，C4 23.5 mg/dL，anti-Scl-70 85 AU/mL（normal <120 AU/mL），anti-centromere protein 218 AU/mL（normal<120 AU/mL），anti-SSA 128 AU/mL（normal< 120 AU/mL），anti-dsDNA 108 IU/mL（normal<120IU/mL），anti-Sm/anti-RNP均為正常。最有可能的診斷為何？","options":["(A) polymyositis","(B) CREST syndrome","(C) Sjögren's syndrome","(D) systemic lupus erythematosus"],"answer":1,"image":""},{"id":"md3-107-1-12","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"adalimumab（Humira）為一種抗腫瘤壞死因子（anti-TNF）之單株抗體，最不建議用於治療下列何種疾病？","options":["(A) Crohn’s disease","(B) ankylosing spondylitis","(C) rheumatoid arthritis","(D) systemic lupus eryhematosus"],"answer":3,"image":""},{"id":"md3-107-1-13","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"32歲男病人罹患活動性C型病毒肝炎已數年。最近數星期，兩下肢皮膚出現許多有壓痛之小紅疹。且四肢麻木疼痛。檢查發現有輕度蛋白尿。下列那一項檢查陽性最具診斷價值？","options":["(A) 類風濕因子（RF）","(B) 抗細胞核抗體（ANA）","(C) 冷凝球蛋白（cryoglobulin）","(D) C型肝炎病毒量（viral load）"],"answer":2,"image":""},{"id":"md3-107-1-14","subject":"md3","topic":"內科-血液","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"一位57歲男性在40歲時曾經做過一次健康檢查，當時血液相是正常的。15年前因胃潰瘍穿孔接受了三分之二的胃切除手術，其他無特殊病史。最近因為容易疲倦，接受血液檢查，發現血紅素為8.7 gm/dL，MCV 71fL，白血球3650/µL，分類正常，血小板395000/µL。大便潛血反應為陰性，胃鏡檢查無潰瘍或腫瘤。此病人最可能的診斷為何？","options":["(A) thalassemia","(B) anemia of chronic disorder","(C) iron deficiency anemia","(D) vitamin B12 deficiency anemia"],"answer":2,"image":""},{"id":"md3-107-1-15","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"一位40歲男性過去無任何病史，最近因為極度疲倦、嗜睡、食慾減少來就醫。病患回想這些症狀是在三個月前一次嚴重頭痛後發生。檢查發現飯前血糖90 mg/dL，PR 70/min，BP 100/60 mmHg，free T4 0.5 ng/dL（normal range 0.8～1.8 ng/dL），TSH 1.0 µIU/mL（normal range 0.1～2.0 µIU/mL），early morning cortisol 2.0 µg/dL（normal range 9.0～15 µg/dL），體毛、鬍鬚減少。電腦斷層攝影發現蝶鞍（sella）部位有一3公分不均質腫塊，壓迫腦下垂體組織。最可能的診斷為何？","options":["(A) 泌乳激素瘤pituitary prolactinoma","(B) 腦下垂體中風pituitary apoplexy","(C) 顱咽管瘤craniopharyngioma","(D) 空蝶鞍症候群empty sella syndrome"],"answer":1,"image":""},{"id":"md3-107-1-16","subject":"md3","topic":"內科-感染","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"40歲海洛因毒癮患者因為喘，發燒及胸痛2天，前來急診就診。這位靜脈注射毒癮者，如果發生感染性心內膜炎，最可能的致病菌為：","options":["(A) Staphylococcus aureus","(B) Staphylococcus epidermidis","(C) Viridans streptococcus","(D) Enterococcus faecalis"],"answer":0,"image":""},{"id":"md3-107-1-17","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"有關休克（shock）之敘述，下列何者錯誤？","options":["(A) 休克的機轉肇因於組織血流灌注不足（inadequate tissue perfusion）","(B) 持續性嚴重腹瀉會造成大量脫水，但不致於造成休克","(C) 嚴重心肌梗塞會造成心因性休克","(D) 心包膜積水如發生心包膜填塞（pericardial tamponade），亦會造成休克"],"answer":1,"image":""},{"id":"md3-107-1-18","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"下列何種檢查結果代表病人可能有腎前性氮血症（prerenal azotemia）？","options":["(A) blood urea nitrogen /plasma creatinine（BUN/PCr）ratio< 10:1","(B) urine sodium（U）>40 meq/L Na","(C) urine osmolality <350 mOsmol/kg HO 2","(D) urine creatinine/plasma creatinine（UCr/PCr）>40"],"answer":3,"image":""},{"id":"md3-107-1-19","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"下列有關中毒情況與所使用解毒劑之配對，何者錯誤？","options":["(A) methanol---folinate","(B) lead encephalopathy---dimercaprol + edetate calcium disodium","(C) organophosphorus compounds---physostigmine","(D) cyanide---sodium thiosulfate"],"answer":2,"image":""},{"id":"md3-107-1-20","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"體溫過低的原因最不可能是下列何者？","options":["(A) 腦下腺機能低下","(B) 副甲狀腺機能低下","(C) 腎上腺機能低下（Addison's disease）","(D) 腦中風"],"answer":1,"image":""},{"id":"md3-107-1-21","subject":"md3","topic":"內科-心臟血管","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"下列有關慢性心衰竭的敍述，何者錯誤？","options":["(A) 在聽診方面，收縮性左心衰竭病患可聽到第三心音，在舒張性左心衰竭常聽到第四心音","(B) 內頸靜脈的壓力能完全反應左心室的功能","(C) 身體診察（physical examination）可發現最大心尖搏動點（point of maximal impulse）由原本位置（第5肋間及左鎖骨中線）向左及向下偏離","(D) 左心室射出分量（left ventricular ejection fraction）為評估心臟收縮功能的指標"],"answer":1,"image":""},{"id":"md3-107-1-22","subject":"md3","topic":"內科-心臟血管","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"下列有關心音（heart sounds）的敍述，何者錯誤？","options":["(A) 第一心音為房室瓣關閉（二尖瓣及三尖瓣）","(B) 第二心音為主動脈瓣及肺動脈瓣關閉","(C) 通常在正常吸氣時第二心音會產生生理性分裂（physiological splitting of S）2","(D) 第四心音的產生通常與左心的血流量增加有關，如合併二尖瓣閉鎖不全"],"answer":3,"image":""},{"id":"md3-107-1-23","subject":"md3","topic":"內科-心臟血管","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"下列有關慢性心房纖維性顫動（permanent atrial fibrillation）的敍述，何者錯誤？","options":["(A) 為最常見的慢性心律不整","(B) 75歲，女性，糖尿病患，應使用抗凝血劑治療","(C) 25歲，男性，風濕性心臟病合併僧帽瓣狹窄，不必使用抗凝血劑治療","(D) 可考慮只做心律速度的管控（rate control）"],"answer":2,"image":""},{"id":"md3-107-1-24","subject":"md3","topic":"內科-心臟血管","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"決定慢性重度二尖瓣閉鎖不全（severe mitral regurgitation）病人是否應接受手術治療，下列何者為最優先考量因素？","options":["(A) 左心室收縮功能","(B) 左心室收縮末期直徑","(C) 是否有症狀","(D) 是否適合二尖瓣修補術"],"answer":2,"image":""},{"id":"md3-107-1-25","subject":"md3","topic":"內科-心臟血管","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"一位45歲女教師，主訴半年內逐漸發生運動時氣促，倦怠，胸悶以及昏厥的症狀。身體診察發現頸靜脈壓力上升，可摸到右心室搏動，且在右側聽到S的心音，胸部X光發現肺動脈膨大，下列敘述何者最適當？4","options":["(A) 應檢測protein C，protein S，antithrombin III等是否異常","(B) 心電圖通常可以發現心軸向左偏轉及左心室肥大","(C) 可以用心臟超音波測量二尖瓣逆流的流速來估計肺動脈的壓力","(D) 病患肺血管主要的表徵為血管內皮增生，發炎反應增加，以及血管擴張"],"answer":0,"image":""},{"id":"md3-107-1-26","subject":"md3","topic":"內科-心臟血管","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"依照美國國家膽固醇教育計劃（NCEP ATP III），下列何者不屬於代謝症候群風險評估指標之一？","options":["(A) 高血壓","(B) 高血糖","(C) 高尿酸","(D) 高血脂"],"answer":2,"image":""},{"id":"md3-107-1-27","subject":"md3","topic":"內科-感染","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"一位38歲電子業公司總經理近兩個月體溫均在37.5至38.0℃左右，就診時主訴身體虛弱，無運動時呼吸困難症狀，但有心悸現象，身體檢查有貧血，血壓120/70 mmHg，心跳規則94/min，體溫38.1℃，肝腎功能正常，心臟觸診有左心室起伏（LV heave），聽診有grade III/VI全收縮期心雜音，在心尖處最大聲，無明顯全身性或四肢動脈栓塞的現象。心臟超音波檢查在二尖瓣（僧帽瓣）有一約15 mm飄動的贅生物，而在左右手分別採取的血液檢體培養均長出Streptococcus viridans。下列何者是適當的初步治療計畫？","options":["(A) 每8小時靜脈注射penicillin G二百萬到三百萬單位4週後考慮手術治療","(B) 每4小時靜脈注射penicillin G二百萬到三百萬單位4週後考慮手術治療","(C) 每4小時靜脈注射penicillin G二百萬到三百萬單位加上每8小時靜脈注射gentamicin 1 mg/kg，二週後如未發燒且血液培養陰性即可出院，不需考慮心臟外科手術治療","(D) 靜脈注射ampicillin每4小時2g加上每8小時靜脈注射gentamicin 1 mg/kg共4至6週後，考慮外科手術治療瓣膜病變"],"answer":1,"image":""},{"id":"md3-107-1-28","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"下列何種因子的分泌可減少胃酸的產生？","options":["(A) acetylcholine","(B) somatostatin","(C) gastrin","(D) histamine"],"answer":1,"image":""},{"id":"md3-107-1-29","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"阻塞性黃疸（obstructive jaundice）常見的病因不包括下列何者？","options":["(A) 膽道結石","(B) 壺腹部癌症（ampulla of Vater cancer）","(C) 胰臟頭部腫瘤","(D) 急性A型肝炎"],"answer":3,"image":""},{"id":"md3-107-1-30","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"下列何者不會引起脂肪肝？","options":["(A) 肥胖","(B) 糖尿病","(C) 高血脂症","(D) 胃食道逆流"],"answer":3,"image":""},{"id":"md3-107-1-31","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"39歲女性經診斷有十二指腸潰瘍及幽門螺旋桿菌感染，接受第一線殺菌藥物治療後，評估是否殺菌成功，下列何種檢查最簡便正確？","options":["(A) 13 C-urea breath test","(B) 血清幽門螺旋桿菌抗體檢查","(C) 經胃鏡切片組織學檢查","(D) 尿液幽門螺旋桿菌抗體檢查"],"answer":0,"image":""},{"id":"md3-107-1-32","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"下列那幾項敘述是正確的？①上腹痛原因不包括急性膽囊炎 ②急性大腸憩室炎的壓痛點為McBurney point ③急性胰臟炎容易輻射痛至右側肩膀 ④脾臟膿瘍容易輻射痛至左側肩膀 ⑤腹主動脈瘤剝離之疼痛可能傳導至肩膀區域","options":["(A) ①②","(B) ③④","(C) ④⑤","(D) ①④"],"answer":2,"image":""},{"id":"md3-107-1-33","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"下列有關慢性腎病（chronic kidney disease）所引發之次發性副甲狀腺機能亢進（secondary hyperparathyroidism）機轉之敘述，何者錯誤？","options":["(A) 腎臟衰竭造成高磷血症（hyperphosphatemia）","(B) Fibroblast growth factor 23抑制腎臟1-alpha hydroxylase，降低活性維他命D之合成","(C) 高磷血症（hyperphosphatemia）促進活性維他命D之產生","(D) 低鈣血症（hypocalcemia）刺激副甲狀腺荷爾蒙之產生"],"answer":2,"image":""},{"id":"md3-107-1-34","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"下列那一個病例最不符合所列之動脈血氣體分析和血清電解質的檢查結果［pH：7.49，PaO：90 mmHg，2 -++- PaCO2：43 mmHg，HCO3：28；Na 139，K 3.0，Cl 89（電解質的單位是mmol/L）］？","options":["(A) 長期使用利尿劑","(B) 急性腹瀉三天","(C) 原發性皮質醛酮症","(D) 噁心嘔吐兩天"],"answer":1,"image":""},{"id":"md3-107-1-35","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"一位47歲男性最近一個月胃口不佳、比較累且有噁心感。血液生化檢查：BUN 35 mg/dL，creatinine 1.6 mg/dL，Na+ 145 mmol/L，K+ 3.2 mmol/L，Cl- 92 mmol/L，free Ca 3.00 mmol/L。在詢問病史時，下列何者對於鑑別診斷上較無幫助？","options":["(A) 有無使用vitamin D","(B) 有無嚼檳榔（含石灰佐料）習慣","(C) 是否長期使用制酸劑","(D) 有無使用環狀利尿劑"],"answer":3,"image":""},{"id":"md3-107-1-36","subject":"md3","topic":"內科-腎臟","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"一位20歲男性，有嚴重多尿的現象。於禁水4小時後，小便滲透壓（osmolality）沒有明顯上升，注射desmopressin（DDAVP）後，小便滲透壓亦沒有明顯上升，最可能的診斷為何？","options":["(A) 正常","(B) 精神性多尿症","(C) 中樞性尿崩症（central diabetes insipidus）","(D) 腎性尿崩症（nephrogenic diabetes insipidus）"],"answer":3,"image":""},{"id":"md3-107-1-37","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"下列有關各種血管炎臨床特徵的描述，何者最為正確？","options":["(A) granulomatosis with polyangiitis—urticaria","(B) microscopic polyangiitis—chronic sinusitis","(C) Churg-Strauss syndrome—asthmatic attack","(D) polyarteritis nodosa—severe migraine"],"answer":2,"image":""},{"id":"md3-107-1-38","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"下列的何種發現對診斷ankylosing spondylitis最有幫助？","options":["(A) positive HLA-B27","(B) history of low back pain in old patients","(C) pain on motion during chest expansion","(D) symmetric sacroiliitis in X-ray films"],"answer":3,"image":""},{"id":"md3-107-1-39","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"對一個無乳癌家族或個人史的女性，下列何種乳癌篩選，比較符合美國、加拿大及歐洲的相關建議？","options":["(A) 自50歲起每2年做一次核磁共振檢查（MRI）","(B) 自40歲起每2年做一次乳房超音波（sonography）","(C) 自50歲起每2年做一次乳房攝影（mammography）","(D) 自35歲起每2年做正子攝影檢查（PET）"],"answer":2,"image":""},{"id":"md3-107-1-40","subject":"md3","topic":"內科-腫瘤","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"一位55歲停經後女性乳癌病人，第3期（T2 [3 cm] N1 [1/10] M0），ER+，PR+，HER2-negative，grade 2，她其他方面的健康良好，下列何者為較好的術後輔助治療？","options":["(A) 先行化學治療，再接續使用雌激素拮抗劑（如：tamoxifen）5年，不用芳香環轉化酶抑制劑","(B) 同時使用化學治療和雌激素拮抗劑","(C) 先行化學治療，再接續使用芳香環轉化酶抑制劑（如：anastrozole）","(D) 同時使用化學治療和芳香環轉化酶抑制劑"],"answer":2,"image":""},{"id":"md3-107-1-41","subject":"md3","topic":"內科-血液","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"下列有關急性前骨髓細胞白血病（acute promyelocytic leukemia）的敘述，何者錯誤？","options":["(A) 容易發生瀰漫性血管內凝血（DIC）","(B) 帶有染色體異常t（5;7）","(C) 有異常之PML/RARα融合基因","(D) 以反轉式維甲酸tretinoin治療，可以達到完全緩解"],"answer":1,"image":""},{"id":"md3-107-1-42","subject":"md3","topic":"內科-血液","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"標靶治療藥物rituximab合併化學治療已被證明可明顯延長下列何種病人的存活期？","options":["(A) diffuse large B cell lymphoma","(B) peripheral T cell lymphoma","(C) multiple myeloma","(D) acute lymphoblastic leukemia"],"answer":0,"image":""},{"id":"md3-107-1-43","subject":"md3","topic":"內科-血液","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"一位30歲臺灣人左手發生深層靜脈血栓（deep vein thrombosis，DVT），回顧其家族史，他的哥哥在35歲時死於肺栓塞。下列何者最不可能是這位病人DVT發生的原因？","options":["(A) protein C deficiency","(B) protein S deficiency","(C) antithrombin III deficiency","(D) factor V Leiden mutation"],"answer":3,"image":""},{"id":"md3-107-1-44","subject":"md3","topic":"內科-腫瘤","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"下列何種惡性病最可能以化學治療藥物（chemotherapy）治癒？","options":["(A) non-smal cell lung carcinoma","(B) colorectal carcinoma","(C) seminoma","(D) chronic myeloid leukemia"],"answer":2,"image":""},{"id":"md3-107-1-45","subject":"md3","topic":"內科-胸腔","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"一位67歲退休農夫近5年來逐漸感到運動時呼吸困難，經高解析度電腦斷層（HRCT）檢查，診斷出間質性肺纖維化（interstitial lung fibrosis）。下列敘述何者錯誤？","options":["(A) 自體免疫性或類肉瘤（sarcoidosis）所引起的病變機率較小","(B) 肺功能的異常包括：FVC, FEV1降低，FEV1/FVC接近正常，而TLC降低","(C) 運動肺功能的變化可作為預後的預測","(D) 一氧化碳瀰散量（CO diffusing capacity, DL）通常會降低，但DL/VA（alveolar ventilation）是正常COCO"],"answer":3,"image":""},{"id":"md3-107-1-46","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"休克狀態時，下列那一項生理變化對於組織缺氧惡化的影響最小？","options":["(A) 動脈平均血壓由70 mmHg降為50 mmHg","(B) 血色素由15 g/dL降為10 g/dL","(C) 動脈氧氣分壓由100 mmHg降為70 mmHg","(D) 動脈血氧飽和度由100%降為70%"],"answer":2,"image":""},{"id":"md3-107-1-47","subject":"md3","topic":"內科-胸腔","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"根據Light's criteria，下列何者不是診斷滲出性肋膜積液（exudative pleural effusion）的條件？","options":["(A) 胸水中，白蛋白（albumin）的量＞3 g/dL","(B) 「胸水中蛋白質」與「血清中蛋白質」的比值＞0.5","(C) 「胸水中lactate dehydrogenase（LDH）」與「血清中lactate dehydrogenase（LDH）」的比值＞0.6","(D) 「胸水中lactate dehydrogenase（LDH）值」大於「血清中lactate dehydrogenase（LDH）正常上限值」的2/3"],"answer":0,"image":""},{"id":"md3-107-1-48","subject":"md3","topic":"內科-腫瘤","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"腫瘤旁症候群（paraneoplastic syndrome）中，副甲狀腺素相關胜肽（parathyroid hormone- related peptide）的產生最常見於何種肺癌的組織學型態？","options":["(A) 小細胞肺癌（small cell lung cancer）","(B) 腺癌（adenocarcinoma）","(C) 鱗狀細胞癌（squamous cell carcinoma）","(D) 大細胞肺癌（large cell carcinoma）"],"answer":2,"image":""},{"id":"md3-107-1-49","subject":"md3","topic":"內科-感染","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"下列關於肺外結核（extrapulmonary tuberculosis）治療的敘述，何者錯誤？","options":["(A) 淋巴腺結核是最常見的肺外結核","(B) 脊椎結核（Pott's disease）所併發的脊髓病變（myelopathy）多數能隨著藥物治療而逐漸恢復","(C) 結核性心包膜炎（pericarditis）的治療除了抗結核標準治療外，類固醇治療未被確認可改善病情","(D) 結核性腦膜炎（meningitis）治療為標準抗結核治療6個月"],"answer":3,"image":""},{"id":"md3-107-1-50","subject":"md3","topic":"內科-胸腔","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"下列關於慢性阻塞性肺疾（chronic obstructive pulmonary disease, COPD）的敘述，何者錯誤？","options":["(A) 抽菸是最主要的危險因子","(B) 肺功能檢查中的「一秒量（FEV）」是單一最好評估嚴重度的指標1","(C) 不會呈現陽性之支氣管激發試驗（bronchial provocation test）","(D) 經支氣管擴張試驗（bronchodilator test）後之「一秒量（FEV1）」小於0.7"],"answer":[2,3],"image":"","answer_note":"更正:第50題答Ｃ、Ｄ給分。"},{"id":"md3-107-1-51","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"一位27歲男性氣喘患者，常有氣喘急性發作，下列何種檢查對於偵測此患者病情之變化最簡單有效？","options":["(A) 痰之嗜伊紅性白血球細胞數","(B) 免疫球蛋白E（IgE）之檢查","(C) FEV/FVC 1","(D) 自行使用尖峰呼氣流速（PEFR）之檢查"],"answer":3,"image":""},{"id":"md3-107-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"34歲男性，於健康檢查時發現高血鈣，低血磷，進一步測定intact parathyroid hormone（iPTH）發現過高，為750 pg/mL，但超音波檢查並沒有發現副甲狀腺腺瘤，這時進一步做何檢查最恰當？","options":["(A) 副甲狀腺Tc99m-sestamibi scan＋SPECT（single photon emission computed tomography）","(B) I-131 thyroid uptake and scan","(C) 頸部MRI（magnetic resonance imaging）","(D) 頸部CT（computed tomography）"],"answer":0,"image":""},{"id":"md3-107-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"52歲女性，於健康檢查時發現血中CEA（carcinoembryonic antigen）升高，但大腸鏡和胸部電腦斷層攝影檢查皆正常。身體檢查發現甲狀腺有一結節腫，細針抽吸細胞學檢查看到紡綞型的細胞和大而橢圓的細胞，有藍色細胞質（劉氏染色）。則抽血驗下列何者可幫助確認診斷？","options":["(A) thyroglobulin","(B) calcitonin","(C) CA-199","(D) CA-125"],"answer":1,"image":""},{"id":"md3-107-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"40歲女性，月亮臉，長青春痘，有水牛肩。抽血發現早上八點ACTH < 5.0 pg/mL，cortisol 22.6 µg/dL，下午四點ACTH < 5.0 pg/mL，cortisol 24.6 µg/dL，晚上11點口服1 mg之dexamethasone，隔天早上八點之cortisol 20.0 µg/dL。則下列何者正確？","options":["(A) 進一步可做腎上腺電腦斷層攝影","(B) 此病人之診斷為Cushing’s disease","(C) 手術後不用服用cortisone acetate","(D) 這病人顯然長期在使用dexamethasone"],"answer":0,"image":""},{"id":"md3-107-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"下列何種病變為第一型糖尿病自然病程中最早出現者？","options":["(A) 視網膜","(B) 神經","(C) 腎臟","(D) 心血管"],"answer":0,"image":""},{"id":"md3-107-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"下列何者最不可能造成甲狀腺功能亢進？","options":["(A) 葛瑞夫茲病（Graves' disease）","(B) 橋本氏甲狀腺炎","(C) 服用過量含碘物質","(D) 甲狀腺癌"],"answer":3,"image":""},{"id":"md3-107-1-57","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"關於血脂治療之敘述，下列何者錯誤？","options":["(A) fibric acid衍生物是治療血中三酸甘油脂（triglyceride）過高之第一線用藥","(B) statin是治療血中膽固醇（cholesterol）過高之第一線用藥","(C) fibric acid衍生物與Statin合併使用可能造成橫紋肌溶解症（rhabdomyolysis）","(D) fibric acid衍生物與Statin嚴禁合併使用"],"answer":3,"image":""},{"id":"md3-107-1-58","subject":"md3","topic":"內科-感染","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"下列何者不是登革出血熱的臨床表現？","options":["(A) 發燒","(B) 點狀出血、紫斑","(C) 血小板下降（thrombocytopenia）","(D) 血比容下降20%以上"],"answer":3,"image":""},{"id":"md3-107-1-59","subject":"md3","topic":"內科-感染","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"某新兵訓練中心爆發多名新兵發燒、頭痛、噁吐、理學檢查為頸部僵硬、出血性皮疹，腦脊髓液染色為格蘭氏陰性雙球菌，下列敘述何者錯誤？","options":["(A) 病人必須採負壓隔離（空氣隔離防護措施）","(B) 該病原菌是Neisseria meningitidis","(C) 抗生素投藥24小時後，一般病人即不具有傳染性","(D) 治療藥物為penicillin或ceftriaxone"],"answer":0,"image":""},{"id":"md3-107-1-60","subject":"md3","topic":"內科-感染","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"60歲男性，有長期菸癮習慣，過去病史已知有40年慢性B型肝炎及8年慢性支氣管炎。本次因食慾不佳及黃疸就醫住院，診斷為慢性B型肝炎急性惡化。入院15天後突發性高燒39°C，輕微腹瀉，及呼吸困難，血液白血3球為26,700/mm，低血鈉（130 mg/dL），室內空氣下（room air）血氧飽和度下降，並立即插置氣管內管接用人工呼吸器，胸部X光呈右側下肺葉葉性肺炎。氣管內管抽出黃白色痰液，在痰抹片革蘭氏染色下呈眾多多核性白血球（PMN），但無可見之鱗狀上皮細胞、細菌、或其它微生物；抗酸性染色（acid-fast stain）為陰性。下列何種抗生素為最適當之治療選擇？","options":["(A) ciprofloxacin","(B) fluconazole","(C) imipenem/cilastatin","(D) vancomycin"],"answer":0,"image":""},{"id":"md3-107-1-61","subject":"md3","topic":"內科-感染","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"下列各項有關肉毒桿菌毒素（botulism toxin）造成嚴重中毒臨床表現之敘述，何者最不可能？","options":["(A) 複視","(B) 吞嚥困難","(C) 呼吸困難","(D) 神智不清"],"answer":3,"image":""},{"id":"md3-107-1-62","subject":"md3","topic":"內科-感染","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"下列那一個致病菌目前沒有效的抗微生物製劑治療，且必須進行特殊隔離，以免傳播給其他人？","options":["(A) 嚴重急性呼吸道症候群（severe acute respiratory syndrome）","(B) 吸入型炭疽病（anthrax）","(C) 漢生病（Hansen’s disease）","(D) 流行性感冒"],"answer":0,"image":""},{"id":"md3-107-1-63","subject":"md3","topic":"內科-感染","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"下列那一種抗生素較不適合用來治療綠膿桿菌（Pseudomonas aeruginosa）的感染？","options":["(A) ceftazidime","(B) aztreonam","(C) ertapenem","(D) ciprofloxacin"],"answer":2,"image":""},{"id":"md3-107-1-64","subject":"md3","topic":"內科-血液","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"一50歲男性主訴下背痛，X光檢查顯示L2-L4壓迫性骨折（compression fracture）。血液生化檢驗結果如下：albumin 3.0 g/dL（3.7～5.3)；total protein 4.2 g/dL（6.4～8.4）；calcium 10.4 mg/dL（8.4～10.6）；creatinine 2.5 mg/dL（0.7～1.5）；IgG 498 mg/dL（751～1560）；IgA 55 mg/dL（82～453）；IgM 27 mg/dL（46～304）；骨髓穿刺細胞學檢驗顯示：normocellularity with fair maturation of erythroid and myeloid series，但有15% plasma cells，下列敘述何者錯誤？","options":["(A) 末稍血液抹片可能沒有rouleaux formation","(B) 末稍血液抹片plasma cells很少見","(C) 尿液dipstick test可偵測到蛋白尿","(D) 小便檢驗應可測出monoclonal light chain"],"answer":2,"image":""},{"id":"md3-107-1-65","subject":"md3","topic":"內科-血液","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"承上題，有關於上述病患之治療下列何者錯誤？","options":["(A) 即使在沒有高血鈣的情況下，bisphosphonate也是一個有效的附加治療（adjunctive therapy）","(B) melphalan+prednisolone（MP）可當作主要的一線化學治療","(C) bortezomib之類的所謂新型製劑（novel agents）合併化學治療可提高這類新診斷病患誘導治療的完全緩解率（complete remission rate）","(D) 日後的自體造血幹細胞移植（autologous hematopoietic stem cell transplantation）可以提高長期存活率"],"answer":1,"image":""},{"id":"md3-107-1-66","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"一位66歲男性高血壓病人，有30年抽菸史，年輕時有氣喘病史，最近發現有糖尿病，醫師建議加入「全民健康保險糖尿病共同照護網」。下列糖尿病照護的管理流程，那一項錯誤？","options":["(A) 每三個月檢查糖化血色素","(B) 每年檢查眼底視網膜病變","(C) 每年周邊動脈硬化檢查","(D) 需要時安排足底神經學檢查"],"answer":2,"image":""},{"id":"md3-107-1-67","subject":"md3","topic":"內科-胸腔","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"一位55歲男性，因慢性咳嗽已十幾年而至門診就醫，最近咳嗽症狀加劇，且咳嗽有黏稠、甚至膿痰。他抽菸已35年，每天約需兩包菸，一年前已戒菸。理學檢查發現血壓為160/86 mmHg，脈搏96次/分，身體質量指數（body mass index）為31，說話時有哮鳴聲，胸部X光發現支氣管壁增厚，兩側肺野肺紋增加。下列那一項肺功能檢查結果，與這位病人無關？","options":["(A) 殘餘容積（residual volume）減少","(B) 第一秒用力吐氣量（forced expiratory volume in one second, FEV）減少1","(C) 第一秒用力吐氣量與肺活量（forced vital capacity, FVC）比值（FEV/FVC）降低1","(D) 肺活量中間50%的用力吐氣流速（FEF25-75）降低"],"answer":0,"image":""},{"id":"md3-107-1-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"關於周全性老年評估，下列敘述何者錯誤？","options":["(A) 是在了解虛弱老人之問題，進而提供整體計畫，以作為治療及長期追蹤之參考","(B) 執行流程包括篩檢適合的病人、評估、建議及執行","(C) 可適用於各層級的老人照護","(D) 是以身體疾病的篩檢為主"],"answer":3,"image":""},{"id":"md3-107-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"72歲的吳女士過去無子宮頸癌病史，過去連續三年的子宮頸抹片檢查皆為正常，目前已無性行為。最近至衛生所接受成人健檢時，吳女士詢問醫師是否應該繼續接受抹片檢查，以及是否可以接受人類乳突狀病毒疫苗的注射。下列敘述何者正確？","options":["(A) 子宮頸抹片篩檢屬於公共衛生的初段預防","(B) 吳女士不需再接受子宮頸抹片檢查","(C) 根據美國癌症學會建議，吳女士接受子宮頸抹片檢查的年齡不應有上限","(D) 應建議吳女士接受人類乳突狀病毒疫苗注射"],"answer":1,"image":""},{"id":"md3-107-1-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"先天性甲狀腺功能低下症的篩檢，對於其檢查工具準確性（accuracy）的考量，下列敘述何者最正確？","options":["(A) 敏感度的考量比特異度的考量重要","(B) 特異度的考量比敏感度的考量重要","(C) 敏感度與特異度的考量一樣重要","(D) 視篩檢族群的不同，而有所不同"],"answer":0,"image":""},{"id":"md3-107-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"Berlin與Fowkes所發展的文化差異處理模式（LEARN），包括那五個步驟？","options":["(A) 傾聽、評估、認知、建議、包容","(B) 傾聽、評估、警覺、建議、包容","(C) 傾聽、解釋、警覺、建議、妥協","(D) 傾聽、解釋、認知、建議、妥協"],"answer":3,"image":""},{"id":"md3-107-1-72","subject":"md3","topic":"家醫-行為與社區醫學","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"下列何者是全民健康保險自1995年開辦以後，臺灣醫療環境所發生的變遷？","options":["(A) 地區醫院數目減少","(B) 基層診所數目減少","(C) 惡性腫瘤死亡率，超過心臟疾病成為第一大死亡原因","(D) 分級醫療及轉診制度的開始"],"answer":0,"image":""},{"id":"md3-107-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"當開立麻醉止痛藥（narcotic analgesic）給癌末病人時，下列何者是最需要同時開立之藥物？","options":["(A) 預防便祕之藥物","(B) 加強鎮靜（sedation）作用之藥物","(C) 預防頭暈之藥物","(D) 抗憂鬱劑"],"answer":0,"image":""},{"id":"md3-107-1-74","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"關於胃息肉症（gastric polyposis），下列何者錯誤？","options":["(A) 與息肉相關的疾病包括Peutz-Jeghers症候群、Gardner症候群及家族性大腸息肉症","(B) 息肉越大惡性機率越小","(C) 家族性大腸息肉症有很大的惡性機率","(D) 以增生性息肉（hyperplastic polyp）為最常見"],"answer":1,"image":""},{"id":"md3-107-1-75","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"一位普拿疼（acetaminophen）中毒之病人在第三天出現皮膚變黃、深茶色尿，最可能是何種毒性作用所致？","options":["(A) 肝毒性（hepatotoxicity）","(B) 心毒性（cardiotoxicity）","(C) 神經毒性（neurotoxicity）","(D) 腎毒性（nephrotoxicity）"],"answer":0,"image":""},{"id":"md3-107-1-76","subject":"md3","topic":"急診醫學","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"一位70歲病患疑似急性冠心症，測量其氧合血紅素飽和度顯示為91%，呼吸速度20次/分鐘，若考量使用氧氣治療，下列敘述何者正確？","options":["(A) 血紅素飽和度＞90 %，不需使用氧氣","(B) 若使用鼻導管（nasal cannula），流量每分鐘1～6 L，可提供的氧氣濃度約為21～30%","(C) 若使用Venturi面罩，流量每分鐘4～12 L，可提供的氧氣濃度約為24～50%","(D) 若使用非再吸入型面罩（non-rebreathing mask），流量每分鐘6～10 L，可提供的氧氣濃度約為60～100%"],"answer":2,"image":""},{"id":"md3-107-1-77","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"49歲王女士有高血壓病史，未接受規則治療，昨天晚上睡覺時突然感到頭痛而痛醒，她說這是她有生以來最厲害的頭痛，痛得幾乎要暈厥，王女士最有可能是什麼病？","options":["(A) Temporal arteritis","(B) Subarachnoid hemorrhage","(C) Encephalitis","(D) Meningitis"],"answer":1,"image":""},{"id":"md3-107-1-78","subject":"md3","topic":"內科-感染","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"62歲商人出差到國外，因水土不服腹瀉很厲害，到當地醫院就醫，醫師診斷他是感染性腹瀉而且有敗血症的現象，下列那一種細菌最有可能造成此病況？","options":["(A) Campylobacter species","(B) Salmonella species","(C) Yersinia enterocolitica","(D) Aeromonas hydrophila"],"answer":1,"image":""},{"id":"md3-107-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"依照醫師法第11條規定，醫師非親自診察，不得施行治療、開給方劑，或交付診斷書。依照此一規定，下列那些行為是違法的？①在偏遠的山地離島，對於年老行動不便的慢性病病人，以電話問診確認病況沒有改變後，開藥給病人的家人帶回去服用 ②對於在安養中心住院的植物人病患，統一由安養院書記蒐集健保卡，一個月一次來固定替病人領藥，免得病人奔波 ③對出國旅行的慢性病病人，由家人來代為看診領藥，以免病人斷藥 ④飛機上遇到緊急醫療情形，乘客利用手機將畫面傳給在地面上的醫師，由醫師研判後下令由機上具有護理背景的空服員執行急救","options":["(A) ①②④","(B) ①②③","(C) 僅②③","(D) 僅①③"],"answer":2,"image":""},{"id":"md3-107-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"78歲男性病人，罹患肺癌合併肝臟及腦部轉移，且呈現惡體質（cachexia），病人與家屬對病況的進展感到擔心，到甲醫師的門診諮詢。甲醫師的建議，下列何者錯誤？","options":["(A) 病人擔心疼痛無法控制，要求醫師幫忙注射致死藥物，提早結束生命。醫師表示，這是屬於積極的安樂死（active euthanasia），僅有少數國家是合法的，在臺灣是不合法的","(B) 病人退而求其次，要求醫師幫忙開立致死劑量的藥物，由病人自行服用，以結束生命。醫師表示，這本質上屬於醫師協助自殺（physician-assisted suicide），在臺灣也不合法","(C) 病人表示，若疼痛無法控制，希望能持續增加嗎啡的劑量，家屬也表示，常看到病人痛到掉眼淚。醫師表示，目前嗎啡劑量已經很大，若再增加嗎啡劑量，可能造成病人的呼吸抑制，違反倫理及違反法律，甲醫師不願意再增加劑量","(D) 病人及家屬諮詢氣管插管的事項。醫師表示，在生命近終點時，若不想插管急救，符合倫理與法律"],"answer":2,"image":""},{"id":"md3-107-2-1","subject":"md3","topic":"內科-腎臟","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"血陰離子隙（blood anion gap）是反應下列何項離子的多寡？","options":["(A) 未測量之陽離子（unmeasured cations）","(B) 鈉離子+鉀離子（Na++ K+）","(C) 未測量之陰離子（unmeasured anions）重碳酸離子+氯離子（HCO-+ Cl-）","(D) 3"],"answer":2,"image":""},{"id":"md3-107-2-2","subject":"md3","topic":"內科-腎臟","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"一位30歲女性病人尿液分析發現血尿，下列何項檢查結果支持是腎小球性（glomerular）血尿？","options":["(A) 尿沉渣看見顆粒性圓柱體","(B) 24小時蛋白尿排泄量> 2.5克","(C) 尿沉渣發現變形性紅血球","(D) 紅血球數目> 50顆⁄高倍視野"],"answer":2,"image":""},{"id":"md3-107-2-3","subject":"md3","topic":"內科-腎臟","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"一位35歲女性，因為最近血壓升高來就診。生化初步檢查都在正常值範圍內，除了血清鉀離子是2.5 mmol/L。下列那一個診斷最不可能考慮？","options":["(A) 單側腎動脈狹窄（unilateral renal arterial stenosis）","(B) 服用甘草（licorice）","(C) 高登症候群（Gordon’s syndrome）","(D) 原發性皮質醛酮症（primary aldosteronism）"],"answer":2,"image":""},{"id":"md3-107-2-4","subject":"md3","topic":"內科-腎臟","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"65歲男性因嘔吐不止兩天至急診處。病人過去有十二指腸潰瘍。身體診察，脈搏每分124次，血壓85/50 mmHg，無貧血或黃疸。血清電解質（mmol/L）：Na+ 132，K+ 2.9，Cl- 85。動脈氣體分析如下：pH：7.49，PaCO：47mmHg，PaO：90 mmHg，HCO-：32 mmol/L。下列有關對此病人的敘述何者最為正223確？","options":["(A) 血清滲透壓應該>310 mOsmol/kg H2O","(B) 尿液的鉀離子應該<10 mmol/L","(C) 尿液的滲透壓應該>500 mOsmol/kg H2O","(D) 尿液氯離子應該>20 mmol/L"],"answer":2,"image":""},{"id":"md3-107-2-5","subject":"md3","topic":"內科-腎臟","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"下列情況使用angiotensin-converting enzyme inhibitor（ACEI）比較容易發生急性腎衰竭，但何者例外？","options":["(A) 雙側腎動脈狹窄","(B) 合併使用鈣離子阻斷劑","(C) 使用大量利尿劑治療鬱血性心衰竭","(D) 合併使用非類固醇消炎劑"],"answer":1,"image":""},{"id":"md3-107-2-6","subject":"md3","topic":"內科-腎臟","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"下列那一個病例較符合所列之動脈血氣體分析和血清電解質的檢查結果［pH：7.32，PaO2：110 mmHg，PaCO：33 mmHg，HCO-：18；Na+ 138，K+ 3.0，Cl- 109（電解質的單位是mmol/L）］？23","options":["(A) 19歲女學生為第一型糖尿病，因期末考熬夜兩天，忘記注射胰島素","(B) 39歲女性經理服用作用於遠端腎小管之利尿劑減重","(C) 59歲女性有第五期慢性腎臟病","(D) 69歲女性腹瀉三天"],"answer":3,"image":""},{"id":"md3-107-2-7","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"關於kwashiorkor malnutrition的敘述，何者最不適當？","options":["(A) 是長期飢餓的結果（starvation-related malnutrition）","(B) 身體診察可能發現水腫、頭髮容易拔出（easy hair pluckability）","(C) 實驗室檢查可能發現血清白蛋白低（＜2.8 g/dL）、血液淋巴球減少（lymphocytes＜1,500/µL）","(D) Body mass index仍在正常範圍"],"answer":0,"image":""},{"id":"md3-107-2-8","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"一位65歲男性糖尿病患，最近剛在門診治療肺結核，追蹤抽血結果卻發現異常：total bilirubin 3 mg/dL（正常值：0.2～1.2）、direct bilirubin 0.3 mg/dL（正常值：0～0.4）。下列敘述何者最不適當？","options":["(A) 可能與肺結核藥物引發溶血有關","(B) 病患此時驗尿將發現urine bilirubin呈陽性反應","(C) 病患此時驗尿將發現urine urobilinogen呈陽性反應","(D) 病患此時驗血中的糖化血色素（HbA1C），會有假性偏低的可能"],"answer":1,"image":""},{"id":"md3-107-2-9","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"有關感覺之神經學檢查，下列那一項描述最正確？","options":["(A) 以針刺（pinprick）檢查痛感（pain），所檢查的神經纖維為大神經","(B) 以棉花縷（cotton wisp）檢查觸感（touch），所檢查的神經纖維為大神經及小神經","(C) 以音叉（tuning fork）檢查震動感覺（vibration），所檢查的神經纖維為小神經","(D) 以特定關節之被動移動（passive movement of specific joints）檢查關節位置（joint position），所檢查的神經纖維為小神經"],"answer":1,"image":""},{"id":"md3-107-2-10","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"高血鈣急症的治療原則下列那一項最不適當？","options":["(A) 立即補充生理食鹽水","(B) 使用thiazide類利尿劑","(C) 惡性腫瘤引發高血鈣可以考慮給予雙磷酸鹽（bisphosphonates）","(D) 維生素D造成的高血鈣症可以考慮使用類固醇治療"],"answer":1,"image":""},{"id":"md3-107-2-11","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"有關胸痛的鑑別診斷與描述，下列那一項最不適當？","options":["(A) 章魚壺心肌症（Takotsubo cardiomyopathy）通常以突然發作的胸痛或呼吸急促表現","(B) 氣胸（pneumothorax）的風險因素包括男性、抽菸、家族病史等","(C) 心包炎（pericarditis）引起的胸痛在平躺時改善，坐起或身體前傾時加劇","(D) 使用硝酸甘油（nitroglycerin）可能改善食道痙攣（esophageal spasm）所引起的胸痛"],"answer":2,"image":""},{"id":"md3-107-2-12","subject":"md3","topic":"家醫-行為與社區醫學","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"有關老年病人的評估，下列敘述何者正確？","options":["(A) Mini-Mental State Examination主要用來篩檢憂鬱症（depression）","(B) Mini-Cog test包括「倒背數字」與「系列減法」兩部分","(C) Timed up-and-go test用於評估行走與平衡能力","(D) 備餐、沐浴、移位、服藥等能力皆是基本日常生活活動功能（basic activities of daily living）的評估項目"],"answer":2,"image":""},{"id":"md3-107-2-13","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"下列何者並非動脈硬化獨立的危險因子？","options":["(A) 低密度脂蛋白（LDL cholesterol）過高","(B) 吸菸","(C) 肥胖","(D) 糖尿病"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第13題一律給分 (原公告答案 C)"},{"id":"md3-107-2-14","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"王先生今年54歲，胸悶及喘的症狀已有一年。他有家族遺傳的高血壓、糖尿病，而且一天抽兩包菸已有30年，還曾被診斷為慢性阻塞性肺病（COPD）。下列針對他可能合併冠心病之敘述，何者正確？","options":["(A) 若他雖仍能正常上班工作及活動，但吃飽後走上坡就會胸悶，則他的Canadian Cardiovascular Society功能分級為III級","(B) 因為考慮壓力性測試（stress testing）的風險，應避免運動心電圖檢查","(C) 多巴胺壓力（dobutamine stress）心臟超音波檢查雖然相當準確，但敏感度（sensitivity）略低於運動心電圖","(D) 電腦斷層檢查冠心病之正確性雖然頗高，但其對預測疾病預後之應用尚不明確"],"answer":3,"image":""},{"id":"md3-107-2-15","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"對於心電圖心軸偏左（left axis deviation）的可能原因，何者錯誤？","options":["(A) 左右手導程顛倒（reversal of the left and right arm electrodes）","(B) 可見於正常人（normal variant）","(C) 左心室肥厚（left ventricular hypertrophy）","(D) 下壁心肌梗塞（inferior myocardial infarction）"],"answer":0,"image":""},{"id":"md3-107-2-16","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"一位44歲女性因心悸至門診檢查，心電圖顯示如下圖，其附屬路徑或旁道（accessory pathway）最可能位在何處？","options":["(A) 右心室側壁（Right free wall）","(B) 左心室側壁（Left lateral ventricle）","(C) 前中膈（Anterior septum）","(D) 後中膈（Posterior septum）"],"answer":3,"image":"md3-107-2-16.jpeg"},{"id":"md3-107-2-17","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"在成人最常見的三尖瓣逆流（tricuspid regurgitation）原因為何？","options":["(A) 肺動脈高壓（pulmonary hypertension）","(B) 類癌（carcinoid）","(C) 愛伯斯坦氏異常（Ebstein’s anomaly）","(D) 心內膜炎（endocarditis）"],"answer":0,"image":""},{"id":"md3-107-2-18","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"有關主動脈瓣狹窄，下列敘述何者錯誤？","options":["(A) 當有心衰竭症狀時，建議接受主動脈瓣膜置換","(B) 當出現心衰竭症狀時，預期餘命大約是3年","(C) 鈣化性主動脈瓣狹窄，每年主動脈瓣膜面積大約下降0.1平方公分","(D) 大約有兩成猝死病人是因心律不整死亡"],"answer":1,"image":""},{"id":"md3-107-2-19","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"一位23歲大學王姓女畢業生規劃去位於菲律賓首都馬尼拉的貿易公司上班，在出發前兩週，因平常有過敏性鼻炎而先自行到住家附近的李姓家醫科診所拿藥。醫師問病史時王女除了提到鼻塞、流鼻水外，還表示偶而會有胸悶的症狀，但並無其他任何不適。而醫師在作身體診查時聽診前胸，發現有grade 1-2的mid-systolic murmur，於是醫師要王女轉診去附近的區域醫院作進一步檢查。王女到了區域醫院的心臟科門診就診，在問診確定病史和身體診查發現如同轉診單所記載後，其最合適的處置為：","options":["(A) 直接安排做心臟超音波檢查，再決定如何處置","(B) 直接安排做ECG檢查，如無異常，即可不用再做其他檢查","(C) 直接安排做CXR檢查，如無異常，再做心臟超音波檢查，之後再決定如何處置","(D) 直接安排做ECG和CXR檢查，如無異常，即可不用再做其他檢查"],"answer":3,"image":""},{"id":"md3-107-2-20","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"有關發紺（cyanosis）的敘述，下列何者錯誤？","options":["(A) 大的patent ductus arteriosus（PDA）引起的差異性發紺（differential cyanosis），經常是下半身發紺","(B) 周邊血管疾病引起的發紺部位，經常是在動脈血管管腔狹窄處的下游處","(C) 代表的生理意義為血氧含量降低，或是組織的灌注血流量不足","(D) 嚴重心衰竭引起的發紺，常伴有小血管的擴張"],"answer":3,"image":""},{"id":"md3-107-2-21","subject":"md3","topic":"內科-心臟血管","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"有關次發性高血壓的敘述，何者正確？","options":["(A) 腎血管狹窄引起的血壓高是所有次發性高血壓裡面最常見的","(B) 腎動脈發生纖維肌肉發育異常（Fibromuscular dysplasia）或是動脈硬化形成斑塊，引起血管狹窄，造成血壓高","(C) 腎上腺腫瘤製造過多的Aldosterone也是造成次發性高血壓的原因，表現常是：鈉堆積，高血壓，高血鉀，低的血中腎素（Renin）活性","(D) 嗜鉻細胞瘤（Pheochromocytoma）有80%的機會是來自家族遺傳，屬於自體顯性（Autosomal dominant）遺傳"],"answer":1,"image":""},{"id":"md3-107-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"黃疸是੿床上常ྏ的症૑。有一個20歲ࠕ輕男性，無任何肝臟病史，門診主訴ࢂཊ健康檢查中，發現血清Bilirubin 2.9/0.5 ㎎/dL（Total/Direct, reference value:＜1.0/＜0.3 mg/dL），其他肝功能檢查都正常，血清肝炎標誌都是陰性反應；਺學檢查無ʳ常，沒有搔癢症狀。下࠻何種診斷最有可能？","options":["(A) 肝內膽汁滯ৎ（Cholestasis）","(B) Dubin-Johnson Syndrome","(C) Gilbert's Syndrome","(D) Rotor Syndrome"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第22題一律給分。 (原公告答案 C)"},{"id":"md3-107-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"有關B型肝炎病毒的變異（variants），下列何者錯誤？","options":["(A) 核前區G1896A變異與e抗原陰性有關，較不會出現在基因型A的B型肝炎病毒","(B) 表面抗原145氨基酸glycine變異成arginine的B型肝炎病毒，會出現在表面抗體（anti-HBs）陽性的個案中","(C) Core-promoter的變異，可以導致病毒複製增加及快速進展肝硬化","(D) B型肝炎聚合酶YMDD區的變異，與自然演化有關"],"answer":3,"image":""},{"id":"md3-107-2-24","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"Child Pugh score是用來評估肝硬化嚴重的方式，Child Pugh score的組成共有5個項目，這5個項目是：","options":["(A) Albumin, bilirubin, prothrombin time, ascites, encephalopathy","(B) Albumin, bilirubin, ALT（Alanine Aminotransferase）, ascites, encephalopathy","(C) Albumin, bilirubin, ALT（Alanine Aminotransferase）, prothrombin time, ascites","(D) Albumin, bilirubin, prothrombin time, ALT（Alanine Aminotransferase）, encephalopathy"],"answer":0,"image":""},{"id":"md3-107-2-25","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"以下關於大腸直腸癌篩檢之敘述，何者正確？","options":["(A) 一旦診斷發炎性腸道疾病（inflammatory bowel disease），就要每1至3年施行一次大腸鏡","(B) 一般危險性族群，每1至2年以免疫法糞便潛血檢查篩檢是一個篩檢的好方式","(C) 一旦診斷有腺瘤性息肉並切除後，應每年追蹤大腸鏡","(D) 有一等親大腸癌家族史者，應從50歲開始每5年做一次大腸鏡"],"answer":1,"image":""},{"id":"md3-107-2-26","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"關於Ulcerative colitis及Crohn's disease的比較，下列何者正確？","options":["(A) 在內視鏡下，ulcerative colitis常有rectal sparing的現象，Crohn's disease則較罕見","(B) 在內視鏡下，ulcerative colitis常有cobblestoning的黏膜變化，Crohn's disease則較罕見","(C) 在放射線檢查下，ulcerative colitis不會呈現segmental colitis的現象，而Crohn's disease常會有此現象的發生","(D) 在臨床理學檢查下，ulcerative colitis常見significant perineal disease的症狀，而Crohn's disease罕有此症狀的發生"],"answer":2,"image":""},{"id":"md3-107-2-27","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"Helicobacter pylori infection業已證實為消化性潰瘍的主因，關於此細菌的特性，下列敘述何者正確？","options":["(A) Helicobacter pylori infection會造成10～15%的感染者產生慢性胃炎，這些患者少數會發生消化性潰瘍或胃癌","(B) Helicobacter pylori會分泌catalase，會產生NH3來中和胃酸，因此細菌得以於胃酸中存活","(C) 不同strain的Helicobacter pylori可能帶有不同的毒性因子，如pathogenicity island（cag-PAI）會encode毒性因子Cag A，它們會造成人體宿主較強的黏膜發炎反應","(D) Helicobacter pylori infection的outcome除了bacterial virulent factor之外，也與host factor有關，若兩者交互作用造成antrum-predominant胃炎，感染者的胃萎縮及胃癌的風險關聯性較大；若造成corpus-predominant胃炎，感染者的十二指腸潰瘍的風險較大，而與胃癌的風險關聯性較小"],"answer":2,"image":""},{"id":"md3-107-2-28","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"關於痛風（gout）和急性痛風性關節炎（acute gouty arthritis）的治療，下列敘述何者錯誤？","options":["(A) 急性痛風性關節炎如果不治療也可在3至10天內自然緩解","(B) 治療急性痛風性關節炎時，如合併使用colchicine和降尿酸的藥物（例如allopurinol），會有最好的消炎效果","(C) 使用allopurinol治療痛風時，病人如果帶有HLA-B*5801基因，則產生嚴重皮膚過敏反應的機率比不帶此基因的機率高很多","(D) Febuxostat是一種xanthine oxidase inhibitor，在腎臟功能不全的病人也可使用"],"answer":1,"image":""},{"id":"md3-107-2-29","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"有關復發性多軟骨炎（relapsing polychondritis）的敘述，下列何者正確？","options":["(A) 大部分病人會有類風濕因子（rheumatoid factor）陽性","(B) 大多數的病人會合併關節炎","(C) 大約有90%的病人會合併其他自體免疫疾病","(D) 治療以抗腫瘤壞死因子（anti-TNF）生物製劑為主"],"answer":1,"image":""},{"id":"md3-107-2-30","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"30歲女性主訴近半年來口乾眼乾越來越嚴重，即使每天喝很多水也無法改善，眼科醫師經過Schirmer's test之後確認為乾眼症，轉介至風濕免疫科門診。下列何種處置比較恰當？","options":["(A) 直接使用高劑量類固醇治療","(B) 直接使用Cyclophosphamide治療","(C) 直接使用Rituximab治療","(D) 先抽血檢驗Anti-SSA/SSB抗體"],"answer":3,"image":""},{"id":"md3-107-2-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"33歲女性因爲持續發燒1個多月前來求診。病人12歲時曾因下肢紫斑與牙齦出血在其他醫院診斷為「自體免疫血小板低下」，經類固醇治療約半年左右就病情穩定也未再回診。初步實驗室檢驗白血球（WBC），3,200/µL，Hgb 8.5 g/dL，血小板60,000/ µL，尿液常規有蛋白尿protein 3+，血尿RBC 10～20/HPF。下列何項檢查對確立診斷最有幫助？","options":["(A) C-反應蛋白（CRP）","(B) 抗中性球細胞質抗體（antineutrophil cytoplasmic antibodies）","(C) 抗核抗體（antinuclear antibodies）","(D) 間接庫姆氏試驗（indirect Coombs' test）"],"answer":2,"image":""},{"id":"md3-107-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"38歲謝先生約半年前開始出現陣發性關節腫痛。病人痛過的關節包括左膝關節、雙手腕關節、左手第2、3、4掌指關節、右手第2掌指關節及右手第2近端指間關節與右肘關節。每次腫痛只侵犯1個關節，約3至5天自癒，從來沒有痛過足部的關節。但近2個月雙腕關節及雙手第2、3掌指關節與右手第2近端指間關節腫痛一直不消退，造成生活極大不便。以下何種檢查對確診病人為類風濕性關節炎最為重要？","options":["(A) 血清尿酸（serum uric acid）","(B) 雙手X光照相（X-ray of both hands）","(C) 抗環瓜氨酸抗體（anti-cyclic citrullinated peptides antibodies）","(D) 腕關節超音波檢查"],"answer":2,"image":""},{"id":"md3-107-2-33","subject":"md3","topic":"內科-腫瘤","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"胃的惡性腫瘤中，約有15%為惡性淋巴癌，即原發性胃淋巴瘤（primary gastric lymphoma）。以下相關的敘述中，何者正確？","options":["(A) 胃鏡檢查下胃惡性淋巴瘤和胃腺癌可清楚辨別，不需切片病理診斷","(B) 絕大多數的原發性胃淋巴瘤為T-細胞淋巴瘤","(C) 若為mucosa-associated lymphoid tissue（MALT）淋巴瘤，應考慮使用抗生素治療清除H. pylori","(D) 若為high-grade、large-cell淋巴瘤，均應進行胃腫瘤及次全胃切除手術，再考慮化療，以避免發生腫瘤出血、阻塞或穿孔等合併症"],"answer":2,"image":""},{"id":"md3-107-2-34","subject":"md3","topic":"內科-腫瘤","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"針對TNM Staging System Stage I、3 cm的早期肝細胞癌，以下的治療方式，何者不是「具治癒性可能（curative-intent）」的治療策略？","options":["(A) Surgical resection","(B) Radiofrequency ablation","(C) Sorafenib","(D) Orthotopic liver transplantation"],"answer":2,"image":""},{"id":"md3-107-2-35","subject":"md3","topic":"內科-腫瘤","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"有關neuroendocrine tumors（NETs）的診治，以下敘述何者錯誤？","options":["(A) 組織病理學經常使用chromogranin A的免疫組織染色，協助診斷NETs","(B) NETs的grading system根據proliferative indices（即Ki-67及mitotic count），分為Grade 1、Grade 2及Grade 3","(C) Multiple endocrine neoplasia type 1（MEN1）是一種autosomal dominant疾病，主要肇因於VHL gene的缺陷","(D) 為控制腸胃道NET所導致的carcinoid syndrome，可使用somatostatin analogues"],"answer":2,"image":""},{"id":"md3-107-2-36","subject":"md3","topic":"內科-腫瘤","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"下列何者不是口咽部原發鱗狀上皮癌的危險因子？","options":["(A) 吸菸","(B) 喝酒","(C) Epstein-Barr病毒感染","(D) 人類乳突病毒感染（HPV）"],"answer":2,"image":""},{"id":"md3-107-2-37","subject":"md3","topic":"內科-腫瘤","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"腎細胞癌（renal cell carcinoma）的細胞型態，最常見的是：","options":["(A) 嗜酸粒細胞瘤（oncocytomas）","(B) 難染細胞（chromophobe）型","(C) 乳突（papillary）型","(D) 透亮細胞（clear cell）型"],"answer":3,"image":""},{"id":"md3-107-2-38","subject":"md3","topic":"內科-血液","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"一位68歲女性，因為倦怠無力而來門診求醫。理學檢查除了臉色特別紅潤，脾臟有腫大的現象。此外，並無其他異常。血液數據顯示：白血球12,200/µL，分類segmented neutrophil 79.7%，lymphocyte 12,7%，無不成熟細胞。血紅素20.3 g/dL，Hematocrit 61.5%，MCV（mean cell volume）89.2 fL，MCHC（mean cell hemoglobin concentration）33.8 g/dL，血小板446,000/µL，尿酸7.6 mg/dL（參考區間2.6～7.5）。骨髓檢查結果呈現hypercellularity，而且紅血球系列、白血球系列與巨核細胞（megakaryocyte）均有明顯增生的現象。JAK2 gene有V617F的突變。以下關於這位病人最可能的疾病之診斷與治療，何者錯誤？","options":["(A) Interferon可以縮小脾臟，降低各種血球數目，也可以減少突變基因JAK2 V617F之allelic burden","(B) 對於紅血球過多所引起之hyperviscosity，第一線的解決方法是phlebotomy","(C) 這種病人的plasma volume也是增加的，因此有些這樣的病人其hematocrit反而不會明顯增加","(D) 這種病人的serum erythropoietin levels通常是升高的"],"answer":3,"image":""},{"id":"md3-107-2-39","subject":"md3","topic":"內科-血液","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"一位45歲女性，平常健康狀況良好，但是近三個月感到腹脹，食慾不振，疲乏無力。理學檢查呈現臉色與結膜蒼白，另外腹部觸診可以摸到明顯之脾臟與肝臟腫大。實驗室數據顯示，白血球高達260,000/µL，Hemoglobin 7.7 g/dL，血小板650,000/µL，白血球分類顯示blast 10%，promyelocyte 19%，myelocyte 9.8%，metamyelocyte 9.5%，band 12.3%，segmented neutrophil 24%，basophil 7%，eosinophil 6.3%，lymphocyte 1.3%。骨髓細胞之染色體檢查顯示t(9;22)(q34;q11)。骨髓中之blasts是2%。其血液抹片如下圖所示。以下關於這位病人最可能的疾病之診斷與治療，何者錯誤？","options":["(A) 現在治療此病的第一線藥物是tyrosine kinase inhibitors，例如imatinib、dasatinib或是nilotinib","(B) 在慢性期，如果病人沒有明顯之臨床症狀，可以先觀察追蹤，不需立即用藥治療","(C) 這類病人之leukocyte alkaline phosphatase（LAP）score常常是降低的","(D) 對這個疾病而言，少有一開始診斷即是急性期"],"answer":1,"image":"md3-107-2-39.jpeg"},{"id":"md3-107-2-40","subject":"md3","topic":"內科-血液","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"38歲女性，主訴在最近6個月運動時有愈來愈嚴重的呼吸困難（exertional dyspnea）。血球檢查數據如下（括弧內是正常參考數值）：RBC 3.91 M/µL（3.78～4.99），HB 7.0 g/dL（10.8～14.9），HCT 26.2% （35.6～45.4），MCV 67.0 fL（80～100），MCH 17.9 pg（26～34），MCHC 26.7 g/dL（31～37），PLT 382 k/µL（150～361），WBC 6.07 k/µL（3.54～9.06）。以下那個檢查對這個病人之診斷較無相關？","options":["(A) 血清中鐵蛋白（ferritin）","(B) 糞便潛血檢查","(C) 血清中鐵的濃度","(D) 血清中銅的濃度"],"answer":3,"image":""},{"id":"md3-107-2-41","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"以下何項並非USPSTF（US Preventive Services Task Force）所強烈建議（class A）的癌症篩檢方式？","options":["(A) 針對40～49歲女性每兩年接受乳房攝影（mammography）","(B) 針對21～65歲女性每三年接受子宮頸抹片（Pap test）","(C) 針對50～75歲成人每年接受糞便潛血檢測（fecal occult blood testing）","(D) 針對50～75歲成人每十年接受大腸鏡檢查（colonoscopy）"],"answer":0,"image":""},{"id":"md3-107-2-42","subject":"md3","topic":"內科-胸腔","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"下列有關氣喘的發病機制（pathogenesis），何者正確？","options":["(A) 呼吸道上皮細胞主要為防禦功能，並不參與發炎反應","(B) 過敏原或病毒性感染會誘使T helper 2（TH2）淋巴球分泌interleukin-5，促使嗜酸性白血球進入呼吸道","(C) 氣喘的發炎介質會導致呼吸道平滑肌收縮，但平滑肌本身並不會釋放發炎介質","(D) 嗜中性白血球主要是對抗細菌性感染，並不參與發炎反應"],"answer":1,"image":""},{"id":"md3-107-2-43","subject":"md3","topic":"內科-胸腔","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"下列那一種肺癌組織型，為我國最常見者？","options":["(A) adenocarcinoma","(B) squamous cell carcinoma","(C) large cell carcinoma","(D) small cell carcinoma"],"answer":0,"image":""},{"id":"md3-107-2-44","subject":"md3","topic":"內科-胸腔","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"關於肺癌診斷及分期，下列何者正確？","options":["(A) 正子電腦斷層造影（PET-CT）之偽陽性低，如果發現對側淋巴腺有顯影，就表示N3，病人不宜手術切除腫瘤","(B) 肺臟核磁共振（MRI of lung）是肺癌的首選影像檢查","(C) 在急診胸部X光片中，發現右側胸腔全白，應馬上安排胸部電腦斷層","(D) 肺癌期別檢驗（staging workup）時，若病人有莫名疼痛或alkaline phosphatase（ALP）不明原因升高，可以安排全身骨骼掃描（whole body bone scan）檢查"],"answer":3,"image":""},{"id":"md3-107-2-45","subject":"md3","topic":"內科-胸腔","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"30歲之男性病人，因有突發性左側胸痛，呼吸困難而至急診處就醫，觸診（palpation）時發現左下肺野觸覺震顫（tactile fremitus）減少，敲診時為hyper-resonant，聽診時呼吸音減少，最可能診斷為下列何者？","options":["(A) 左側肋膜腔積水","(B) 左側氣胸","(C) 肺氣腫","(D) 左下肺葉肺炎"],"answer":1,"image":""},{"id":"md3-107-2-46","subject":"md3","topic":"內科-胸腔","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"24歲女性患者，因意識不清被送來急診處。在吸入室內空氣時，其動脈血液氣體分析顯示pH 7.12，PaCO2 80 mmHg，PaO 45 mmHg，HCO- 28 mEq/L，BE(ECF) 0 mEq/L。其低血氧症最可能之原因為何？23","options":["(A) 急性氣喘發作","(B) 慢性阻塞性肺疾併急性發作","(C) 安眠藥中毒，換氣不足","(D) 肺炎併呼吸衰竭"],"answer":2,"image":""},{"id":"md3-107-2-47","subject":"md3","topic":"內科-感染","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"因為父親罹患開放性肺結核而接受接觸者檢查的23歲男性，他的胸部X光檢查正常，但丙型干擾素血液測驗（interferon-γ release assay）為陽性。下列何種建議最不適當？","options":["(A) 接受9個月的每日一次isoniazid治療","(B) 接受12個劑量的每星期一次isoniazid及rifapentine治療","(C) 接受2個月的每日一次rifampin及pyrazinamide治療","(D) 若其父親罹患的菌株為isoniazid抗藥性，可建議服用4個月的rifampin治療"],"answer":2,"image":""},{"id":"md3-107-2-48","subject":"md3","topic":"內科-感染","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"42歲的男性，過去身體都十分健康，也沒有任何全身性疾病。此次因為罹患A型流行性感冒後，併發細菌性肺炎。其最可能的致病菌為何？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）或金黃色葡萄球菌（Staphylococcus aureus）","(B) 綠膿桿菌（Pseudomonas aeruginosa）或克雷氏桿菌（Klebsiella pneumoniae）","(C) 黴漿菌（Mycoplasma pneumoniae）","(D) 厭氧性細菌"],"answer":0,"image":""},{"id":"md3-107-2-49","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"甲狀腺的觸診是診斷疾病的重要依據，根據1994年UNICEF（聯合國兒童基金會）的分類法，對甲狀腺大小的分級描述何者正確？①甲狀腺組織看不到，也摸不到：Grade 0 ②甲狀腺組織看不到，但摸的到：Grade 1 ③甲狀腺組織看的到，也摸的到：Grade 2","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":3,"image":""},{"id":"md3-107-2-50","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"有關糖尿病口服藥物的敘述，下列何者錯誤？","options":["(A) Metformin單獨使用不太會引起低血糖，其最嚴重的副作用為乳酸血症","(B) Thiazolidinediones及dipeptidyl-peptidase IV inhibitors可能會引起心臟衰竭","(C) Dapagliflozin及empagliflozin屬於胰島素增敏劑","(D) Acarbose的作用機轉為抑制腸道的碳水化合物消化與吸收"],"answer":2,"image":""},{"id":"md3-107-2-51","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"糖尿病足部病變是導致下肢截肢的主要原因，下列敘述何者錯誤？","options":["(A) 下肢的神經病變可導致足部的變形","(B) 下肢動脈血流供應不足可引起間歇性跛行（intermittent claudication）","(C) 足部潰瘍經常伴隨細菌感染，因血糖控制不良，最常見的菌種為克雷伯氏肺炎桿菌（Klebsiella pneumoniae）","(D) 如果感染沒有適當控制，可引起骨髓發炎"],"answer":2,"image":""},{"id":"md3-107-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"關於減重，下列敘述何者錯誤？","options":["(A) 飲食控制的重點，在於減少總熱量的攝取","(B) 一般而言，在6個月內，減輕原先體重的15 %，是一個很容易達成的目標","(C) 對重度肥胖的病人，在內科療法無效時，減重手術（bariatric surgery）是一種合理的選擇","(D) Lorcaserin是作用在中樞神經，為抑制食慾的藥物"],"answer":1,"image":""},{"id":"md3-107-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"有關高脂血症之敘述，下列何者最不適當？","options":["(A) 血中三酸甘油酯濃度偏高，與心臟病無關","(B) 血中三酸甘油酯濃度偏高，治療的首選藥物是纖維酸衍生物（fibric acid derivatives）","(C) 血中低密度脂蛋白膽固醇（LDL-C）濃度偏高，與心臟病有關","(D) 治療高膽固醇血症，首選的藥物是使達錠（statin）"],"answer":0,"image":""},{"id":"md3-107-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"下列何者是原發性副甲狀腺功能亢進的患者，最可能出現的電解質變化？","options":["(A) 高血鈣、低血磷","(B) 低血鈣、高血磷","(C) 低血鈣、低血磷","(D) 高血鈣、高血磷"],"answer":0,"image":""},{"id":"md3-107-2-55","subject":"md3","topic":"內科-腫瘤","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"對於神經內分泌瘤（neuroendocrine tumor）的敘述，下列何者最正確？","options":["(A) 為良性腫瘤","(B) 只發生在腸胃道與胰臟","(C) 注射體抑素類似物（somatostatin analogue），為最有效的治療方式","(D) 可能合併腦下垂體腫瘤或副甲狀腺瘤"],"answer":3,"image":""},{"id":"md3-107-2-56","subject":"md3","topic":"內科-感染","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"人類免疫不全病毒（HIV）感染者感染梅毒（syphilis）或其他性行為傳染疾病的臨床表徵敘述，何者錯誤？","options":["(A) 人類免疫不全病毒感染者感染到梅毒，與一般人比較其疾病嚴重度及病程進展並無不同","(B) 大多數人類免疫不全病毒感染者的血清學檢測可用於確認梅毒的診斷","(C) 感染淋病（gonorrhea）可能會增加人類免疫不全病毒感染的危險，且淋病在男性不一定有明顯的症狀，更需小心診斷","(D) 梅毒是人類免疫不全病毒感染的危險因素"],"answer":0,"image":""},{"id":"md3-107-2-57","subject":"md3","topic":"內科-感染","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"下列關於肺炎鏈球菌（Streptococcus pneumoniae）感染的敘述，何者正確？","options":["(A) 肺炎鏈球菌菌血症在嬰兒和老人較一般成人常見","(B) 免疫不全的病人（如：脾切除的病人）施打肺炎鏈球菌疫苗是禁忌","(C) 肺炎鏈球菌咽喉炎是肺炎鏈球菌腦膜炎最常見的先行事件","(D) 血液白血球明顯增高（marked leukocytosis）相對於宿主因素，是預測肺炎鏈球菌感染預後不佳的主要因素"],"answer":0,"image":""},{"id":"md3-107-2-58","subject":"md3","topic":"內科-感染","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"35歲男性，因父親被診斷為具傳染性的肺結核感染，而被轉介至門診進行評估。沒有臨床症狀，血清丙型干擾素釋放測試（Interferon-gamma releasing assays, IGRAs）檢查為陽性，下列何種處置不恰當？","options":["(A) 照胸部X光，排除活動性肺結核（active TB）","(B) 照胸部X光，有病變則進行痰液結核菌抹片及培養","(C) 照胸部X光，若無病變則依潛伏性結核（latent tuberculosis）治療","(D) 負壓隔離病室隔離"],"answer":3,"image":""},{"id":"md3-107-2-59","subject":"md3","topic":"內科-感染","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"35歲男性，家住山上，在颱風之後清掃自家附近水溝，當時注意到有很多死老鼠，一週後因黃疸、茶色尿及發高燒被送到急診，最可能的致病菌是：","options":["(A) 鉤端螺旋體（Leptospira species）","(B) 腸病毒（enterovirus）","(C) 流感病毒（influenza virus）","(D) 登革熱病毒（dengue virus）"],"answer":0,"image":""},{"id":"md3-107-2-60","subject":"md3","topic":"內科-感染","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"40歲男性，感染人類免疫不全病毒（HIV），有憂鬱症病史，曾經有自殺意圖，CD4+ T細胞數50 cells/µL，HIV病毒量10,000 copies/mL，下列抗反轉錄病毒藥物，何者最不適合這位病人長期治療？","options":["(A) raltegravir","(B) rilpivirine","(C) dolutegravir","(D) efavirenz"],"answer":3,"image":""},{"id":"md3-107-2-61","subject":"md3","topic":"內科-感染","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"50歲男性，患有糖尿病多年，未規則服用降血糖藥物，因為右眼紅腫疼痛及發燒2天，至急診就醫，診斷有眼內炎（endophthalmitis），腹部超音波檢查發現有肝臟膿瘍。在國內，這位病人最恰當的抗生素治療為何？","options":["(A) ceftriaxone","(B) vancomycin","(C) cefazolin","(D) cefmetazole"],"answer":0,"image":""},{"id":"md3-107-2-62","subject":"md3","topic":"內科-感染","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"下列有關Clostridium difficile及其導致之腹瀉疾病之敘述，何者錯誤？","options":["(A) 健康新生兒無症狀腸道帶菌（asymptomatic fecal carriage）並不罕見","(B) 通常為醫療照護相關之感染","(C) 抗微生物製劑的使用是誘發本疾病的主因","(D) 治療後的復發率（recurrence rate）常低於5%"],"answer":3,"image":""},{"id":"md3-107-2-63","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"45歲女性病患來門診時，主訴疲倦（malaise），鞏膜泛黃（icteric sclera），急診檢驗資料顯示血清albumin level：3.6 g/dL（reference value＞3.5），total bilirubin level：5.6 mg/dL（reference value＜ 1.0），direct bilirubin level：2.4 mg/dL（reference value＜0.3），ALT level 1240 U/L（reference value＜ 40），AST level 1380 U/L（reference value＜40），ALP level 89 U/L（reference value＜100），PT INR 1.6（reference value 0.9～1.1），請依前述情況回答下列3題。以下何項訊息對病情診斷沒有幫助？","options":["(A) 藥物史（drug history）","(B) 抽菸史（smoking history）","(C) 過去肝炎病史（previous hepatitis history）","(D) 接觸危險行為史（exposure to risk behavior history）"],"answer":1,"image":""},{"id":"md3-107-2-64","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"進一步進行檢測，以下那些檢測與臆斷方向是不合理的？","options":["(A) 急性Ｂ型肝炎是可能診斷之一，建議檢測HBsAg與IgG anti-HBc","(B) 臺灣為B型肝炎盛行國家，慢性B型肝炎急性發作相當常見，需列入鑑別診斷，未來PT INR恢復正常之後，肝穿刺檢查可幫助判斷","(C) 急性C型肝炎為可能診斷之一，建議檢測anti-HCV，若呈現陽性反應，可進一步檢測HCV RNA","(D) 患者ALP數值在正常範圍之內，因急性膽道阻塞而引起肝炎的機會並不大"],"answer":0,"image":""},{"id":"md3-107-2-65","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"經本次急診抽血檢測發現患者血清HBsAg呈現陰性反應，anti-HCV呈現陽性反應，去年患者曾經接受健康檢查報告顯示當時anti-HCV為陰性反應，病史方面患者曾經於一個月前到某個私人診所接受關節軟骨生成刺激素注射治療。以下有關診斷與進一步處置規劃方面，何項是不合理的？","options":["(A) 患者可能得到急性C型肝炎","(B) C型肝炎患者若出現黃疸，有較高機會自行痊癒（spontaneous recovery）","(C) 急性期觀察3～4個月後，若HCV RNA持續存在，可以考慮給與抗C型肝炎病毒藥物治療","(D) 藥物選擇方面，單一使用長效型干擾素（peginterferon）是沒有用的"],"answer":3,"image":""},{"id":"md3-107-2-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"關於老人照護的原則，下列何者正確？","options":["(A) 強調疾病之治癒","(B) 以維持功能及維持自我照顧能力為原則","(C) 老年人的照護，僅需治療性的診治","(D) 老年人新出現的疾病，不會造成其功能進一步退化"],"answer":1,"image":""},{"id":"md3-107-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"某論文摘要如下：長期使用抗血小板藥物比上安慰劑的隨機分配試驗，每日劑量75 mg到325 mg的aspirin，平均追蹤1.3年。aspirin對於中風合併心肌梗塞或血管性事件有明顯下降（odds ratio (OR) 0.71, 95％ confidence interval (CI) 0.51 to 0.97）。服用aspirin者比未服用aspirin者發生中風合併心肌梗塞或血管性事件的敘述，何者正確？","options":["(A) 絕對風險下降率（absolute risk reduction，ARR）為71％","(B) 相對風險下降率（relative risk reduction，RRR）為71％","(C) 服用aspirin者發生事件與沒發生事件的比值，除以未服用aspirin者發生事件與沒發生事件的比值為0.71","(D) number needed to treat（NNT）為141"],"answer":2,"image":""},{"id":"md3-107-2-68","subject":"md3","topic":"家醫-行為與社區醫學","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"下列何者不屬於Smilkstein所創立出來的家庭APGAR功能問卷之五個成分？","options":["(A) 適應度（adaptation）","(B) 合作度（partnership）","(C) 成長度（growth）","(D) 資源度（resource）"],"answer":3,"image":""},{"id":"md3-107-2-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"有關疾病或狀況篩檢的原則，下列何者不是原則之一？","options":["(A) 該疾病或狀況需具有較高的罹病率或死亡率","(B) 該疾病或狀況需有較高的盛行率或較高的發生率","(C) 該疾病或狀況需具有有症狀的期間，才有足夠時間去檢查","(D) 該疾病或狀況必須有廣被接受的治療，且可改善疾病預後"],"answer":2,"image":""},{"id":"md3-107-2-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"下列有關青少年行為問題的描述，何者正確？","options":["(A) 青少年的冒險行為與雄性激素無關","(B) 性行為不屬於青少年的冒險行為","(C) 生理、心理、社會及環境變化的不同步，與冒險行為有關","(D) 物質濫用通常會合併使用興奮劑、大麻及古柯鹼"],"answer":2,"image":""},{"id":"md3-107-2-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"35歲王小姐，餐廳服務員，主訴雙膝痠痛已三個月。她的身體質量指數（BMI）為32 Kg/m2，最近她了解膝痛與體重有關，覺得現在是該減重的時候了，準備在一個月內採取行動。根據跨越理論模式（transtheoretical model），王小姐是處於行為改變的那一階段？","options":["(A) 未考慮階段（precontemplation）","(B) 考慮階段（contemplation）","(C) 準備階段（preparation）","(D) 行動階段（action）"],"answer":2,"image":""},{"id":"md3-107-2-72","subject":"md3","topic":"家醫-緩和醫學","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"一位85歲女性病人兩年前中風臥床，現身上有鼻胃管及導尿管，兩年中曾有三次因吸入性肺炎住進加護病房，下列有關居家訪視服務的描述，何者最不適當？","options":["(A) 討論有關末期狀況時所要作的處理","(B) 協助病人更換鼻胃管及導尿管","(C) 評估家屬之照顧能力","(D) 若有發燒馬上送醫院，以免肺炎的惡化"],"answer":3,"image":""},{"id":"md3-107-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"52歲男性，罹患轉移性腎細胞癌，主訴從臀部往下到左小腿之疼痛已數天。他描述疼痛性質是尖銳如刀刺、有灼熱感，疼痛分數可達7/10。下列何者是處理此病人疼痛最適當之藥物？","options":["(A) gabapentin","(B) codeine","(C) meperidine","(D) 非類固醇類抗發炎藥（NSAID）"],"answer":0,"image":""},{"id":"md3-107-2-74","subject":"md3","topic":"內科-消化肝膽胰","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"一名酗酒男性因上腹悶痛和食慾不佳來求診，電腦斷層檢查呈現如圖，箭號所指之異常最可能是下列那一項診斷？","options":["(A) bowel perforation","(B) chronic pancreatitis","(C) common bile duct stones","(D) splenic artery arteriosclerosis"],"answer":1,"image":"md3-107-2-74.jpeg"},{"id":"md3-107-2-75","subject":"md3","topic":"急診醫學","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"一位65歲女性病人，有肥胖、腦中風、高血壓的病史。4週前曾因大腿骨折而接受手術治療，目前在家臥床休養，傷口癒合良好。此病人清晨突然覺得噁心、胸悶，喘不過氣來，家人緊急送醫治療。到院時體溫正常意識清楚，呼吸27次/min，心跳120次/min，血壓88/43 mmHg，血氧飽和度86%。你發現心電圖在Lead V1至V4出現新的T wave inversion及S1-Q3-T3 pattern，該病人最可能之診斷為何？","options":["(A) 主動脈剝離（aortic dissection）","(B) 急性腦中風（acute stroke）","(C) 肺栓塞（pulmonary embolism）","(D) 大葉性肺炎（lobar pneumonia）"],"answer":2,"image":""},{"id":"md3-107-2-76","subject":"md3","topic":"內科-腎臟","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"一位59歲接受腹膜透析腎病患者，血壓為125/80 mmHg，心跳為76次/min，12導程心電圖發現有peaked T waves，血鉀值為7.0 mmol/L，無溶血。下列何種處置最不優先？","options":["(A) 會診腎臟科後，等待做腹膜透析","(B) 可使用葡萄糖（glucose）加胰島素（insulin）治療","(C) 可使用碳酸氫鈉（sodium bicarbonate）治療","(D) 可使用噴霧式支氣管擴張藥物（neubulized albuterol）治療"],"answer":0,"image":""},{"id":"md3-107-2-77","subject":"md3","topic":"急診醫學","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"一位56歲女性，由美國紐約返回臺北的飛機途中發生暈厥（syncope），下了飛機後因呼吸不順至急診就診，她以前不曾發生類似狀況，平常亦無特殊疾病，身體檢查發現血壓120/70 mmHg，心跳126次/分，呼吸28次/分，體溫37.2℃，呼吸音及心音皆正常，四肢活動自如，無腫脹現象，在給予40％氧氣五分鐘後，動脈氣體分析為pH=7.48，PaO2 =70mmHg，PaCO2 =28mmHg，O2 saturation=92%，此時應安排下列那一項檢查最適當？","options":["(A) 心臟超音波檢查","(B) 靜脈杜卜勒超音波檢查","(C) 注射顯影劑的螺旋快速胸部電腦斷層檢查","(D) 主動脈血管攝影"],"answer":2,"image":""},{"id":"md3-107-2-78","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"某老先生退休後經常感覺身體無力，走路走太久也會喘，他來看醫師，醫師發現他的嘴唇有點發紺，經檢查後告訴他是因為甲基血紅素（Methemoglobin）太高造成的，甲基血紅素達血紅素中最少約多少比率，會開始有發紺的現象？","options":["(A) 3～5%","(B) 10～15%","(C) 20～25%","(D) 30～35%"],"answer":1,"image":""},{"id":"md3-107-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"78歲的連先生在接受大腸鏡檢查時，被診斷罹患大腸癌，初步評估應該屬於早期。當主治醫師吳醫師想將病理檢查結果告知連老先生時，連老先生的家屬要求吳醫師隱瞞病情，並幫連老先生決定了拒絕進一步的檢查及治療。吳醫師應如何處理較為合適？","options":["(A) 先詢問連老先生是否想知道自己的病情，如果連老先生想了解自己的病情，即使其家屬反對醫師告知病情，仍然應該向連老先生告知相關病情","(B) 先詢問連老先生是否想知道自己的病情，如果連老先生並不想了解自己的病情，就不要再施予任何檢查或者治療","(C) 連老先生的家屬已經明白表示不要將相關的病情告知連老先生，因此不必再詢問連老先生的意願，而應該按照其家屬的請求隱瞞病情，同時不要再施予任何檢查或治療","(D) 連老先生的家屬已經明白表示不要將相關的病情告知連老先生，因此應該按照其家屬的請求而隱瞞病情。然而其家屬所做的醫療決定不利於連老先生的最佳利益，因此醫師應該依照醫療常規，幫連老先生繼續相關的檢查及治療"],"answer":0,"image":""},{"id":"md3-107-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"下列何者不是醫療上判斷病人是否有「決定能力」的項目？","options":["(A) 病患是否滿20歲","(B) 了解醫學問題的能力","(C) 了解醫師建議療法的能力","(D) 當拒絕所建議之療法時，能合理地預見其後果的能力"],"answer":0,"image":""},{"id":"md3-108-1-1","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"⼀位40歲女性，因⾞禍接受頭部電腦斷層攝影檢查，發現腦下垂體部位有空蝶鞍（empty sella）現象。她⽬ 前⽉經正常，飯前⾎糖90 mg/dL，PR 80/min，BP 130/80 mmHg，free T4 1.2 ng/dL（normal range 0.8～ 1.8 ng/dL)，TSH 1.0μIU/mL（normal range 0.1～2.0 μIU/mL），early morning cortisol 15 μg/dL（normal range 8～18 μg/dL）。下列處置何者最恰當？","options":["(A) 經蝶鞍腦下垂體⼿術（transsphenoid surgery）","(B) 放射治療（radiation therapy）","(C) 藥物（bromocriptine therapy）","(D) 說明病情使病患放⼼（reassurance）"],"answer":3,"image":""},{"id":"md3-108-1-2","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"⼀位35歲的男性，因為意識不清被家⼈送⾄急診就醫，抽⾎檢查發現⾎鈉過⾼（160 mEq/L，參考值135～ 145 mEq/L）。有關⾼⾎鈉（hypernatremia）的處理，下列描述何者最適當？","options":["(A) 估算全⾝⽔量（total-body water）：女性是體重的60%，⽽男性是體重的50%","(B) 此病患若體重70公⽄，計算free water缺乏量（free-water deficit）約5000 c.c.","(C) 不易感知的⽔分流失（insensible losses）約5 mL/kg/day","(D) ⾎鈉的矯正儘量不超過10 mM/day，以避免腦部⽔腫（cerebral edema）"],"answer":3,"image":""},{"id":"md3-108-1-3","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"⼀位35歲男性因慢性腹瀉就醫，此症狀在食⽤麵粉製品後會加劇，少吃會較緩解。⾎液學檢查顯⽰⾎紅素11.5 gm/dL，⽩⾎球及⾎⼩板正常，⽽⽣化學檢查顯⽰⾎鈣稍低（2.15 mmol/L，正常2.2～2.5 mmol/L），⾎清肌酸酐（creatinine，0.6 mg/dL）、鈉（139 mEq/L）及鉀（3.8 mEq/L）則在正常範圍，⾎中IgA tissue transglutaminase antibody為陽性。此病⼈最可能的診斷為何？","options":["(A) irritable bowel syndrome","(B) celiac disease","(C) eosinophilic gastroenteritis","(D) Crohn's disease"],"answer":1,"image":""},{"id":"md3-108-1-4","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"下列各項有關瓣膜性⼼臟病的敘述，何者正確？","options":["(A) ⼆尖瓣狹窄最常⾒的原因是風濕性（rheumatic）慢性發炎造成，常⾒在四、五⼗歲女性，臺灣近年病例數有減少趨勢","(B) ⾺凡⽒症候群（Marfan's syndrome）是主動脈瓣逆流的原因之⼀，聽診時病⼈胸前有舒張期雜⾳，且第⼆ ⼼⾳（S）變⼤聲2","(C) 主動脈瓣或⼆尖瓣急性逆流達中度以上、且伴有⼼衰竭症狀時，不應使⽤⾎管擴張劑，並應及早開⼑治療","(D) 單純主動脈瓣狹窄或單純⼆尖瓣狹窄病患，⼼導管均顯⽰左⼼室舒張末壓（LVEDP）升⾼"],"answer":0,"image":""},{"id":"md3-108-1-5","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"⼀位23歲男性因⼼悸⾄⾨診檢查，⼼電圖顯⽰如下圖，其附屬路徑或旁道（accessory pathway）最可能位在何處？","options":["(A) 右⼼室側壁（right free wall）","(B) 左⼼室側壁（left lateral ventricle）","(C) 前中膈（anterior septum）","(D) 後中膈（posterior septum）"],"answer":1,"image":"md3-108-1-5.jpeg"},{"id":"md3-108-1-6","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"⼀位82歲男性，有⾼⾎壓與慢性腎臟疾病，主訴最近疲倦無⼒，⾎壓152/90 mmHg，呼吸15次/分，⼼跳65次/分，體溫36.5℃，⼼電圖顯⽰如下圖，其最可能為何種電解質異常？","options":["(A) ⾼⾎鈣症（hypercalcemia）","(B) 低⾎鈣症（hypocalcemia）","(C) ⾼⾎鉀症（hyperkalemia）","(D) 低⾎鉀症（hypokalemia）"],"answer":2,"image":"md3-108-1-6.jpeg"},{"id":"md3-108-1-7","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"⼀位36歲女性無任何過去病史，因連續3⽇胸痛⾄急診求診。胸痛於特定姿勢可較緩解。她否認近⽇有使⽤藥物或創傷史，但⽬前有喉嚨痛等感冒症狀。抽⾎檢查發現D-dimer與⼼肌酶正常，但⽩⾎球與發炎指數（hsCRP）均有輕微升⾼現象。⼼電圖檢查如下圖所⽰。⼼臟超⾳波檢查顯⽰⼼臟收縮功能正常，且無局部室壁活動異常（regional wall motion abnormality），可⾒少量⼼包膜積液。其最可能診斷為何？","options":["(A) 急性冠⼼病","(B) ⼼肌炎","(C) ⼼包膜炎","(D) 肺栓塞"],"answer":2,"image":"md3-108-1-7.jpeg"},{"id":"md3-108-1-8","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"⼀位28歲女性因運動性呼吸困難⼤約半年⾄⼼臟科⾨診求診。病患否認有胸悶，端坐呼吸或陣發性夜間呼吸困難情形，⼤約在1週前突發性⼼悸不適狀況。⾝體診察發現有隨呼吸固定第⼆⼼⾳分裂（fixed splitting S）2以及輕微收縮期⼼雜⾳。⼼電圖顯⽰⼼軸右偏（right axis deviation）及V1 rSR’。胸部X光顯⽰右⼼房及肺動脈擴⼤。該病患最可能診斷為何？","options":["(A) ⼼房中膈缺損（atrial septal defect）","(B) ⼼室中膈缺損（ventricular septal defect）","(C) 主動脈縮窄（coarctation of the aorta）","(D) 法洛⽒四合症（tetralogy of Fallot）"],"answer":0,"image":""},{"id":"md3-108-1-9","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"王先⽣接受上下肢⾎壓的檢查，下肢dorsalis pedis artery收縮壓為90 mmHg，上臂測得的⾎壓為150/75 mmHg，平均⾎壓為100 mmHg，以下敘述何者正確？","options":["(A) ankle-brachial index為0.6","(B) 因下肢少了舒張壓的資料，無法計算ankle-brachial index","(C) ankle-brachial index為0.9","(D) 因下肢測量部位為dorsalis pedis artery，無法計算ankle-brachial index"],"answer":0,"image":""},{"id":"md3-108-1-10","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"李先⽣因呼吸困難⽽到醫院就診，在診間醫師問完病史後，就作⾝體診察，其中包括了abdominojugular reflex，結果發現原本無異樣的頸靜脈有明顯的⿎漲，⾄少在鎖骨上超過5公分。下列敘述何者最恰當：","options":["(A) ⼤⾎管動脈端有pressure overload","(B) 有volume overload","(C) 為紐約⼼臟協會的⼼衰竭功能分類（NYHA functional classification）的第四級","(D) 有左側⼼衰竭"],"answer":1,"image":""},{"id":"md3-108-1-11","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"下列改變⾎⾏動⼒學（hemodynamics）的動作，與⼼臟雜⾳之間的關係何者錯誤？","options":["(A) 當雙⼿緊握時（hand grip），僧帽瓣閉鎖不全的雜⾳強度會因為⾎流增加⽽增加","(B) 當病患進⾏佛薩⽡⽒壓⼒均衡呼吸法（Valsalva maneuver）時，如果是主動脈狹窄的病患雜⾳⻑度與強度都會減少","(C) 當病患進⾏完佛薩⽡⽒壓⼒均衡呼吸法（Valsalva maneuver）後，⼼臟右側雜⾳恢復到原來強度的速度快於左側的⼼雜⾳","(D) 當從坐姿站立時，若有⼼室出⼝阻塞性⼼肌病變（hypertrophic obstructive cardiomyopathy, HOCM）時， ⼼雜⾳聲⾳會因為⾎流減少⽽減弱"],"answer":3,"image":""},{"id":"md3-108-1-12","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"有關⼼臟⾎管系統的⾝體檢查與評估，下列何者錯誤？","options":["(A) 所謂differential cyanosis指的是發紺現象單獨出現在下肢，要考慮有從右到左的⾎液分流（shunting）病態 ⽣理現象","(B) 當⽪膚看起來有點像青銅⾊的⾊素沉積之際，⼼衰竭的鑑別診斷要考量⾎⾊素沈著病（hemochromatosis）","(C) ⾺凡⽒症（Marfan's syndrome）除了⾝形瘦⻑之外，在牙齦上的表現常常是有較低的牙腭⼸（low-arched palate）","(D) 所謂的杵狀指（clubbing finger）是暗⽰著病患可能有從右到左的⾎液分流（shunting）病態⽣理現象"],"answer":2,"image":""},{"id":"md3-108-1-13","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"下列有關利⽤肝穿刺診斷各種病毒性肝炎相關之肝臟疾病的敘述，何者錯誤？","options":["(A) 若肝穿刺檢體太⼩將無法提供⾜夠的資訊，檢體⻑度應⾄少達到0.5 cm","(B) 慢性C型肝炎引起的纖維化，初始階段常發⽣於portal及periportal area（zone 1）","(C) 非酒精性脂肪肝病引起的纖維化，初始階段好發於中⼼肝⼩靜脈（central perivenular）附近（zone 3）","(D) 嚴重腹⽔或是凝⾎功能異常延⻑時不能進⾏肝穿刺檢查"],"answer":0,"image":""},{"id":"md3-108-1-14","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"肝穿刺是診斷肝臟纖維化的黃⾦標準，但有其臨床應⽤的困難與判讀上的限制。非侵入性肝纖維化檢測是可 ⾏的替代⽅案，⽽且⽬前臨床上已經逐漸廣為採⽤。下列有關各種非侵入性肝纖維化檢測⽅法的描述，何者錯誤？","options":["(A) 兩⼤檢測主流包括利⽤⾎清⽣物學標誌檢測以及利⽤儀器檢測肝臟的硬度","(B) ⾎清⽣物學標誌檢測（如FibroTest）對於各種原因引起的肝臟疾病都可以精準判定各等級肝纖維化程度","(C) transient elastography（如FibroScan）可以快速簡單的檢測肝臟硬度，但對於過度肥胖與有腹⽔之患者測定能⼒會降低","(D) magnetic resonance elastography（MRE）判定各等級肝纖維化程度的能⼒比transient elastography好"],"answer":1,"image":""},{"id":"md3-108-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"有關B型肝炎病毒的敘述，下列何者錯誤？","options":["(A) 帶原者周邊⾎液中，數量最多的是22 nm⼤⼩的病毒顆粒，外觀為球形或⻑絲狀","(B) 42 nm⼤⼩的病毒顆粒，為雙外殼結構，分別為表⾯（surface）及核⼼（core）蛋⽩，數量僅有22 nm病毒顆粒的1/100到1/1,000","(C) 病毒的核衣殼（nucleocapsid）⼤⼩為27 nm，具有表⾯抗原（HBsAg），病毒DNA和DNA聚合酶","(D) B型肝炎病毒的e抗原（HBeAg），包含部分核前（precore）區蛋⽩及導引⾄內質網的訊號區"],"answer":2,"image":""},{"id":"md3-108-1-16","subject":"md3","topic":"內科-腫瘤","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"50歲的B型肝炎男性病⼈，肝臟內有⼀顆8公分的肝細胞癌併有肝⾨靜脈主幹腫瘤栓塞（main portal vein tumor thrombosis），及多處肺部轉移。病⼈沒有肝硬化，肝臟沒有任何失代償現象，沒有黃疸，沒有腹 ⽔。以下那⼀種治療最適合這位病⼈？","options":["(A) 肝臟移植","(B) ⼿術切除","(C) 無線射頻燒灼術（radiofrequency ablation）","(D) 標靶治療（sorafenib）"],"answer":3,"image":""},{"id":"md3-108-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"對於肝腎症候群（hepatorenal syndrome）的敘述，何者正確？","options":["(A) 肝腎症候群可分為第⼀型及第⼆型。第⼀型的特徵是比較穩定，預後較佳，第⼆型的特徵是腎功能在1～2星期內就逐漸惡化","(B) 肝腎症候群通常是發⽣於沒有腹⽔的病⼈","(C) 可⽤來治療肝腎症候群的藥物有terlipressin","(D) 由於腎實質已經受損，就算是進⾏肝臟移植，肝腎症候群也不會改善"],"answer":2,"image":""},{"id":"md3-108-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"關於發炎性腸道疾病（inflammatory bowel disease, IBD）的敘述，下列何者正確？ ①發病⾼峰期在20⾄40歲 ②其發⽣率在亞洲已開發國家有上升趨勢 ③出⽣第⼀年有使⽤抗⽣素的嬰兒，未來發⽣發炎性腸道疾病的風險比較⾼ ④有接受過闌尾切除⼿術（appendectomy），可以顯著降低發⽣潰瘍性⼤腸炎（ulcerative colitis）與克隆 ⽒症（Crohn's disease）的風險","options":["(A) 僅①②","(B) 僅①②③","(C) 僅②④","(D) ①②③④"],"answer":1,"image":""},{"id":"md3-108-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"關於⼤腸癌的症狀，何者正確？","options":["(A) 右側⼤腸癌以排便異常為主，左側⼤腸癌因容易出⾎故以貧⾎為主","(B) ⼤腸癌因為曝露在腸道，容易因糞便摩擦⽽出⾎，因此即便是第⼀期癌症也很容易有症狀","(C) 近年來⼤腸癌的發⽣，右側⼤腸癌個案顯著多於左側⼤腸與直腸癌個案","(D) ⼤腸癌所造成的貧⾎為⼩球性貧⾎"],"answer":3,"image":""},{"id":"md3-108-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"關於Zollinger-Ellison syndrome下列何者敘述正確？","options":["(A) 成因為beta cell endocrine tumor不正常分泌gastrin，導致胃酸⼤量分泌，造成難治性潰瘍","(B) 在peptic ulcer disease的病患中可占0.1～1%，此症狀發⽣gastrinoma，它與multiple endocrine neoplasia（MEN）type 1相關","(C) 在clinical presentation上以peptic ulcer及erosive esophagitis為主，下消化道腹瀉的症狀相當罕⾒","(D) Zollinger-Ellison syndrome之gastrinoma罕有惡性的可能性，腫瘤遠處轉移的狀況相當少⾒"],"answer":1,"image":""},{"id":"md3-108-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"關於胰臟癌的敘述，下列何者正確？","options":["(A) 抽菸是胰臟癌的重要危險因⼦，約有20～25%的胰臟癌與抽菸有關","(B) ⼤約有80%以上的胰臟癌有遺傳傾向，如germline mutations：STK11 gene、BRCA2、p16/CDKN2A、PALB2等","(C) 篩檢胰臟癌，⾎清學檢驗CA19-9及CEA都有相當不錯的敏感度及陽性預測值","(D) 晚期遠處轉移之胰臟癌的第⼀線治療為gemcitabine，使⽤此藥物治療，病患⼀年的存活率可達70%"],"answer":0,"image":""},{"id":"md3-108-1-22","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"72歲男性為慢性腎病病⼈，⾎中肌酸酐（creatinine）6.3 mg/dL，下列何種酸鹼電解質狀態最少發⽣在此病 ⼈？","options":["(A) + 鈉（Na）148 mEq/L","(B) + 鉀（K）5.6 mEq/L 3-","(C) 磷（PO）5.5 mg/dL 4","(D) ++ 鈣（Ca）8.0 mg/dL 3-"],"answer":0,"image":""},{"id":"md3-108-1-23","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"65歲女性病⼈因⻑期糖尿病腎病變，接受規則⾎液透析治療已5年，透析前⾎中磷（PO）6.8 mg/dL、鈣4 ++ （Ca）10.8 mg/dL、副甲狀腺賀爾蒙（PTH）88 pg/mL。對此病⼈，下列何者為最適當治療？","options":["(A) 使⽤磷結合劑（phosphate binder）","(B) 使⽤維他命D（vitamin D）33","(C) 使⽤擬鈣劑（calcimimetic）","(D) 使⽤鈣濃度3.0 mEq/L透析液"],"answer":0,"image":""},{"id":"md3-108-1-24","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"48歲男性末期腎病病⼈，接受⻑期免疫抑制劑治療，移植前無糖尿病病史，移植3個⽉後⾎中肌酸酐0.8 mg/dL，飯前⾎糖210 mg/dL，下列何種藥物最有可能產⽣此種合併症？","options":["(A) mycophenolate mofetil","(B) tacrolimus","(C) sirolimus","(D) everolimus"],"answer":1,"image":""},{"id":"md3-108-1-25","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"針對嘔吐導致急性腎損傷的病⼈，欲區分prerenal或intrinsic病因，下列何項指標最為適合？","options":["(A) fractional excretion of sodium","(B) urine-to-plasma urea ratio","(C) fractional excretion of chloride","(D) urine osmolality"],"answer":2,"image":""},{"id":"md3-108-1-26","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"下列何種疾病所造成的急性腎損傷，其⾎液檢驗結果最少發⽣eosinophilia？","options":["(A) microscopic polyangiitis","(B) atheroembolic disease","(C) NSAID-induced interstitial nephritis","(D) polyarteritis nodosa"],"answer":0,"image":""},{"id":"md3-108-1-27","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"依照2012年最新之KDIGO（Kidney Disease：Improving Global Outcomes）準則，下列診斷急性腎損傷（acute kidney injury）之定義何者錯誤？","options":["(A) ⾎清肌酸酐值於48⼩時內上升幅度⼤於或等於0.3 mg/dL","(B) ⾎清肌酸酐值於5天內上升幅度⼤於或等於25%","(C) ⾎清肌酸酐值於⼀星期內上升幅度⼤於或等於50%","(D) 尿液每⼩時之排出量少於0.5 mL/kg，並持續6⼩時"],"answer":1,"image":""},{"id":"md3-108-1-28","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"⼀位18歲男性⼤學新⽣，⼀星期前入學體檢報告正常。三天前參加新⽣盃籃球比賽後關節酸痛，⾃⾏購買⽌ 痛藥（diclofenac）服⽤後開始出現⼩便泡沫與腳腫，故⾄⾨診求診。無嘔吐、腹瀉、發燒與頻尿症狀。理學檢查發現：⾎壓160/90 mmHg，呼吸速率每分鐘20下，四肢出現紅疹，雙下肢4+⽔腫。⾎液檢查：尿素氮（BUN）52 mg/dL、肌酸酐：2.0 mg/dL，⽩蛋⽩1.8 g/dL，⽩⾎球7,000/μL，⾎⾊素10.2 g/dL，膽固醇320 mg/dL，三酸⽢油脂（triglyceride）260 mg/dL。尿液檢查：紅⾎球2～3顆/HPF，⽩⾎球3～5顆/HPF，尿液總蛋⽩質與肌酸酐比值為12 g/g Cr。下列何項為最可能的診斷？","options":["(A) hemolytic uremic syndrome","(B) minimal change disease","(C) rapidly progressive glomerulonephritis","(D) IgA nephropathy"],"answer":1,"image":""},{"id":"md3-108-1-29","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"⾼尿酸⾎症（hyperuricemia）是造成痛風（gout）的最主要原因，下列關於造成⾼尿酸⾎症的敘述何者正確？","options":["(A) hypoxanthine phosphoribosyl transferase（HPRT）基因位在X染⾊體上，當此基因突變時會造成⾼尿酸⾎ 症","(B) uric acid由肝臟代謝，因此肝臟功能不全時會造成⾼尿酸⾎症","(C) 利尿劑（diuretics）會增加尿酸從尿液排出⽽降低⾎中尿酸","(D) acute myeloid leukemia（AML）在化學治療時會產⽣⾼尿酸⾎症，因此可⽤benzbromarone來預防⾼尿酸 ⾎症"],"answer":0,"image":""},{"id":"md3-108-1-30","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"關於calcium pyrophosphate deposition（CPPD）和calcium apatite deposition引起的關節炎之敘述，下列何者錯誤？","options":["(A) CPPD引起的急性關節炎與急性痛風性關節炎（acute gouty arthritis）臨床表現很相似","(B) CPPD引起的急性關節炎常發⽣在年輕男性，因此要利⽤關節液結晶分析來和其他關節炎做鑑別診斷","(C) calcium apatite deposition引起的關節與關節附近發炎，更容易發⽣在慢性腎臟衰竭合併有hyperphosphatemia的病⼈","(D) CPPD與calcium apatite deposition結晶引起的關節炎皆可⽤colchicine和glucocorticoid治療"],"answer":1,"image":""},{"id":"md3-108-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"有關多發性肌炎（polymyositis）的敘述，下列何者正確？","options":["(A) statin類藥物會引發類似polymyositis的表現","(B) 在⼤於50歲的發炎性肌⾁病變（inflammatory myopathies）患者中，polymyositis是最常⾒的診斷","(C) 關節攣縮（joint contractures）常發⽣於polymyositis","(D) ⽪下鈣化（subcutaneous calcifications）常發⽣於polymyositis"],"answer":0,"image":""},{"id":"md3-108-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"有關顳動脈⾎管炎（temporal arteritis）的敘述，下列何者正確？","options":["(A) 屬於中⼩型⾎管炎","(B) 常常與風濕性多肌痛（polymyalgia rheumatica）⼀起發⽣","(C) 好發於20～40歲女性","(D) 通常對類固醇的治療反應不佳"],"answer":1,"image":""},{"id":"md3-108-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"40歲李女⼠約3年前診斷為全⾝性紅斑狼瘡（systemic lupus erythematosus），除發病時曾有關節腫痛與⽪ 膚紅斑外，近2年病情尚稱穩定。李女⼠過去驗⾎就知道⾎中的抗⼼脂抗體（anticardiolipin antibodies）很 ⾼，為正常上限值的3倍，但過去並不曾發⽣⾎管栓塞。本次因左腿急性腫痛⾄急診室求診，影像學檢查⾒ 左腿有深部靜脈栓塞（deep vein thrombosis）。下列處置何者最為適當？","options":["(A) 加上aspirin，每⽇100毫克","(B) 加上⼝服warfarin，希望⽬標international normalized ratio（INR）2.0～2.5","(C) 應立即⽤⾼劑量類固醇治療","(D) 加上新型抗凝⾎藥物（new oral anticoagulants, NOAC）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第33題一律給分。 (原公告答案 B)"},{"id":"md3-108-1-34","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"已知肝細胞癌（hepatocellular carcinoma, HCC）有不同的etiologic factors，且這些factors在不同地區和國家促成肝癌發⽣的重要性也不盡相同。以下有關「地區或國家：該地區或國家最重要的etiologic factor of HCC」的組合中，何者正確？","options":["(A) Europe & US：Hepatitis B chronic infection and Wilson's disease","(B) China：Hepatitis C chronic infection and nonalcoholic steatohepatitis","(C) Africa：Aflatoxin B1 and hepatitis B chronic infection","(D) Taiwan：Ethanol chronic consumption and primary biliary cirrhosis"],"answer":2,"image":""},{"id":"md3-108-1-35","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"有關「⾎清CA19-9值」於胰臟癌（pancreatic ductal adenocarcinoma）診療上的敘述，何者正確？","options":["(A) 「⾎清CA19-9值的升⾼」是診斷胰臟癌的必要條件","(B) 「⾎清CA19-9值的升⾼」建議使⽤於胰臟癌的篩檢（screening）","(C) 「⼿術前⾎清中CA19-9值」與病患胰臟癌的期別（stage）具相關性","(D) 「⼿術後⾎清中CA19-9值」與病患的預後無關"],"answer":2,"image":""},{"id":"md3-108-1-36","subject":"md3","topic":"內科-胸腔","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"關於原發性肺癌的敘述，何者錯誤？","options":["(A) 鱗狀上⽪癌（squamous cell carcinoma）是⽬前最常⾒的組織型態","(B) 腺癌（adenocarcinoma）會有腺泡（acinar）、乳突（papillary）、⿂鱗（lepidic）、固態（solid）等的型態","(C) 跟吸菸相關性⾼的是鱗狀上⽪癌、⼩細胞癌（small-cell carcinoma）","(D) 表⽪⽣⻑因⼦受體（epidermal growth factor receptor）突變常出現於腺癌"],"answer":0,"image":""},{"id":"md3-108-1-37","subject":"md3","topic":"內科-血液","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"⼀位46歲女性因為常常頭暈，爬樓梯時感到很喘⽽來醫院求診。⾝體檢查除臉⾊與結膜蒼⽩之外，並無其他明顯異常。患者⾎壓106/76 mmHg，脈搏每分鐘72次，規則⼼跳，無發燒，亦無體重減輕或是食慾降低的現象。⾎液數據顯⽰⾎紅素7.6 g/dL，⽩⾎球4,030/μL，無異常分類，⾎⼩板418,000/μL，MCV 74.8 fL（參考區間80～100），ferritin 3.84 ng/mL（參考區間28～365），serum iron 10 μg/dL（參考區間51～209），TIBC（total iron binding capacity）459 μg/dL（參考區間268～593）。⾎液抹片如下圖所⽰。有關這位病⼈ 最可能的疾病之描述，下列何者錯誤？","options":["(A) 此類病⼈的⾎液中的reticulocyte counts常是降低的","(B) 此類病⼈的骨髓中的sideroblast比例常是降低的","(C) 此類病⼈的紅⾎球中的protoporphyrin量常是降低的","(D) 此類病⼈的red cell distribution width（RDW）index常是增加的"],"answer":2,"image":"md3-108-1-37.jpeg"},{"id":"md3-108-1-38","subject":"md3","topic":"內科-血液","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"⼀位65歲男性，其⾎液數據顯⽰，⽩⾎球⾼達160,000/μL，⾎紅素12.7 g/dL，⾎⼩板是165,000/μL，⽩⾎球分類顯⽰segmented neutrophil 14%，lymphocyte 80.3%，無不成熟⾎球。其⾎液抹片之細胞顯⽰如下圖。這些淋巴球表達CD19、CD5、dim CD20、CD23、dim kappa light chain restriction。⽽CD10與CD34均陰性。以下關於這位病⼈最可能的疾病之診斷與治療，何者錯誤？","options":["(A) 典型的周邊⾎液抹片常出現basket cells或smudge cells","(B) ⼤多數的病⼈需要接受⾼劑量化學治療與異體造⾎幹細胞移植，以得到⻑期的存活","(C) 有些病⼈會合併有autoimmune thrombocytopenia或autoimmune hemolytic anemia","(D) 此類病⼈⼀開始通常無明顯與此病相關的症狀，⽽是偶然抽⾎檢驗⾎球數據時才發現此病"],"answer":1,"image":"md3-108-1-38.jpeg"},{"id":"md3-108-1-39","subject":"md3","topic":"內科-血液","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"⼀位30歲女性，過去健康狀況良好，並無重⼤疾病。她在最近5年的⾝體檢查中多次發現⾎⼩板低下，⾎⼩ 板數多維持在40,000/μL左右，⽽其他⾎球數⽬與⽩⾎球分類則未發現異常。最近⼀次⾎液檢查的⽩⾎球9,600/μL，⾎紅素12.7 g/dL，⾎⼩板41,000/μL，⽩⾎球分類無異常。病⼈否認有任何藥物的服⽤或是毒物的曝露，也無主觀上的不適。以下關於這位病⼈最可能的疾病之診斷與治療，何者錯誤？","options":["(A) 雖然病⼈沒有明顯的出⾎狀況，但是為了預防出⾎，此病⼈仍然需要給與類固醇以提升⾎⼩板數量⾄ 100,000/μL以上","(B) 此病⼈不需要立即安排骨髓切片檢查","(C) ⽪下注射romiplostim或是⼝服eltrombopag常可有效的提升此類病⼈之⾎⼩板數量","(D) 此種病⼈之周邊⾎液之⾎球型態與分化，⼀般⽽⾔，是正常的，但是偶⽽有較⼤的platelets"],"answer":0,"image":""},{"id":"md3-108-1-40","subject":"md3","topic":"內科-腫瘤","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"66歲男性，⾃訴以往健康良好。2個⽉前發現有兩側頸部、腋下與腹股溝淋巴結腫⼤，經左側淋巴結切片檢查診斷為angioimmunoblastic T cell lymphoma（AITL），接受全⾝性化學治療，處⽅為標準劑量的CHOP（cyclophosphamide, adriamycin, vincristine和prednisolone）。病⼈於化療2週後返回⾨診，主訴上腹脹、排便困難及⼿指指尖⿇⽊，醫師懷疑可能發⽣ileus。此副作⽤最可能由下列何種藥物引起？","options":["(A) cyclophosphamide","(B) adriamycin","(C) prednisolone","(D) vincristine"],"answer":3,"image":""},{"id":"md3-108-1-41","subject":"md3","topic":"內科-腫瘤","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"下列關於⼦宮頸癌（cervical cancer）的敘述，何者錯誤？","options":["(A) 發⽣率較⾼的地域包括南美洲、加勒比海及東南亞","(B) 有性⾏為前接受HPV疫苗注射可以減少HPV-16及HPV-18的感染，也可減少⼦宮頸的dysplasia","(C) HPV的E6及E8分⼦是HPV相關⼦宮頸癌之致病因⼦","(D) 侵犯骨盆腔或陰道下三分之⼀的⼦宮頸癌屬於FIGO分期的第三期"],"answer":2,"image":""},{"id":"md3-108-1-42","subject":"md3","topic":"內科-腫瘤","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"關於grade IV astrocytoma（glioblastoma）的敘述，何者錯誤？","options":["(A) 此疾病預後不佳，平均存活期⼩於2年","(B) ⾸次治療以⼿術，接續併⽤化學治療（temozolomide）及放射治療為主要治療⽅式","(C) 6 O-methylguanine-DNA methyltransferase（MGMT）有表現的腫瘤，對於temozolomide的治療較有療效","(D) bevacizumab可⽤於復發後的病⼈，此藥物可以減少腫瘤周邊的⽔腫，也可延⻑progression-free survival"],"answer":2,"image":""},{"id":"md3-108-1-43","subject":"md3","topic":"內科-胸腔","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"有關⽯綿肺症（asbestosis）的敘述，下列何者錯誤？","options":["(A) 主要是暴露於⽯綿⽣產過程所造成，常⾒⽤於防火或電流絕緣的材料中","(B) 肺部容易出現瀰漫性纖維化病灶","(C) 可能合併出現肺癌或間⽪細胞瘤（mesothelioma）","(D) 肺功能出現阻塞性功能障礙及氣體瀰散量（diffusing capacity）下降，為病⼈呼吸急促的主因"],"answer":3,"image":""},{"id":"md3-108-1-44","subject":"md3","topic":"內科-胸腔","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"關於肋膜腔積液（pleural effusion）的敘述，下列何者正確？","options":["(A) 正常⼈有肋膜液體（pleural fluid）做為潤滑作⽤，主要是由visceral pleura產⽣，然後由parietal pleura吸收","(B) 根據Light's criteria，鑑別肋膜腔積液（pleural effusion）是transudate或exudate，須檢測肋膜液體（pleural fluid）和⾎清（serum）的LDH和total protein","(C) 肋膜腔積液中adenosine deaminase（ADA）level＞50 mg/L，須⾼度懷疑為淋巴瘤（lymphoma）","(D) 結核（tuberculosis）造成的肋膜腔積液，⼤多可以培養出結核菌（Mycobacterium tuberculosis）"],"answer":1,"image":""},{"id":"md3-108-1-45","subject":"md3","topic":"內科-腫瘤","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"關於肺腺癌基因突變及標靶治療，下列敘述何者正確？","options":["(A) 在東亞肺腺癌，EGFR突變率約10～20%","(B) 有EGFR突變的第四期肺腺癌，可⽤EGFR tyrosine kinase inhibitor治癒（cure）","(C) ALK translocation的肺腺癌病⼈年紀中位數（median age），較整體肺腺癌患者的年紀中位數年輕","(D) ALK translocation之肺腺癌，經標靶治療產⽣抗藥性後，約50～60%產⽣exon 20 T790M突變"],"answer":2,"image":""},{"id":"md3-108-1-46","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"55歲之女性病⼈，有⾼⾎壓及糖尿病史在使⽤藥物，抱怨⻑期乾咳已有近3個⽉，沒有咳⾎及呼吸困難。⾝ 體診查及例⾏胸部X光片檢查皆為正常，對於病⼈的診斷，下列何者最為優先？","options":["(A) 肺功能檢查","(B) ⿐竇X光片檢查","(C) 詢問使⽤抗⾼⾎壓藥物情形","(D) 24⼩時食道pH值檢查"],"answer":2,"image":""},{"id":"md3-108-1-47","subject":"md3","topic":"內科-胸腔","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"75歲男性病⼈，因多年來有運動時呼吸困難現象，前來醫院就診。就診時沒有發燒，⾝體診查發現有兩⼿有杵狀指（clubbing fingers），且聽診時可聽到兩側下肺野有細囉⾳（fine crackles），下列何種疾病為最可能的診斷？","options":["(A) 肺纖維化症","(B) 肺⽔腫","(C) 肺炎","(D) 肺癌"],"answer":0,"image":""},{"id":"md3-108-1-48","subject":"md3","topic":"內科-感染","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"28歲的開放性肺結核女性病⼈，接受含有isoniazid, rifampin, ethambutol及pyrazinamide的抗結核藥物治療，在治療3個星期後，發⽣嚴重痛風。最有可能導致其痛風發作的藥物為何？","options":["(A) isoniazid","(B) rifampin","(C) ethambutol","(D) pyrazinamide"],"answer":3,"image":""},{"id":"md3-108-1-49","subject":"md3","topic":"內科-感染","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"過去⾝體都⼗分健康的46歲男性病⼈，因為發燒及咳嗽3天到⾨診就醫，胸部X光檢查有疑似肺炎病灶。下列何者最不可能為致病菌？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）","(B) 黴漿菌（Mycoplasma pneumoniae）","(C) 鮑⽒不動桿菌（Acinetobacter baumannii）","(D) 嗜⾎桿菌（Haemophilus influenzae）"],"answer":2,"image":""},{"id":"md3-108-1-50","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"下列何者不是典型之甲狀腺功能亢進（hyperthyroidism）的症狀？","options":["(A) 女性病患之⽉經量減少及⽉經週期不規則","(B) 體重增加","(C) ⼼悸或⼼律不整","(D) 怕熱"],"answer":1,"image":""},{"id":"md3-108-1-51","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"下列何者是甲狀腺髓質癌（medullary thyroid cancer）的細胞來源？","options":["(A) 濾泡細胞（follicular epithelial cells）","(B) 濾泡旁細胞（calcitonin producing cells, C cells）","(C) 淋巴球細胞（lymphocytes）","(D) 纖維⺟細胞（fibroblasts）"],"answer":1,"image":""},{"id":"md3-108-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"有關糖尿病的分類、診斷與病因，下列敘述何者最正確？","options":["(A) 第1型糖尿病好發於30歲以上，與⾃體免疫有關","(B) 空腹⾎糖超過100 mg/dL或HbA超過6%即達糖尿病診斷標準1c","(C) 第2型糖尿病與肥胖及家族遺傳有關，是臨床上最常⾒的糖尿病型態","(D) 妊娠型糖尿病好發於婦女懷孕的前3個⽉，與胰島素阻抗有關"],"answer":2,"image":""},{"id":"md3-108-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"有關⾎脂質的代謝，下列敘述何者最正確？","options":["(A) 最⼤的脂蛋⽩分⼦為非常低密度脂蛋⽩（very-low-density lipoprotein）","(B) Apolipoprotein是脂蛋⽩分⼦上的蛋⽩質，與⾎脂質的代謝有關","(C) 乳糜粒（chylomicron）在肝臟內形成，其蛋⽩質成分為apolipoprotein B-48","(D) 胰島素阻抗會使⾎脂質代謝異常，⾎中的⾼密度脂蛋⽩會上升"],"answer":1,"image":""},{"id":"md3-108-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"關於代謝症候群（metabolic syndrome）之敘述，下列何者錯誤？","options":["(A) 與胰島素作⽤的阻抗（insulin resistance）有關","(B) ⾎中⼩⽽緻密的低密度脂蛋⽩（small, dense LDL）濃度會減少","(C) 會增加⼼⾎管疾病的風險","(D) ⾎中極低密度脂蛋⽩（VLDL）的濃度會增加"],"answer":1,"image":""},{"id":"md3-108-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"52歲女性患者，半年來有間歇性⼼悸、冒冷汗、頭痛、⾎壓突然升⾼到約180/100 mmHg的情況，下列何種內分泌疾病最需要列入診斷考量？","options":["(A) 嗜鉻細胞瘤（pheochromocytoma）","(B) 甲狀腺功能亢進（hyperthyroidism）","(C) 庫欣⽒症（Cushing's syndrome）","(D) 原發性醛固酮過⾼症（primary aldosteronism）"],"answer":0,"image":""},{"id":"md3-108-1-56","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"下列何者最可能是⼈⼯瓣膜⼿術後2個⽉內引發⼼內膜炎（prosthetic valve endocarditis）的致病菌？","options":["(A) 流感嗜⾎桿菌（Hemophilus influenzae）","(B) 萬古黴素抗藥性腸球菌屬（vancomycin-resistant Enterococcus species）","(C) 肺炎鏈球菌（Streptococcus pneumoniae）","(D) 表⽪葡萄球菌（Staphylococcus epidermidis）"],"answer":3,"image":""},{"id":"md3-108-1-57","subject":"md3","topic":"內科-感染","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"下列關於導管相關尿路感染（catheter-associated urinary tract infection）的敘述，何者正確？","options":["(A) 常規使⽤抗⽣素塗抹於尿道⼝是預防導管相關尿路感染最有效的措施","(B) 常規使⽤⼝服抗⽣素預防導管相關尿路感染是實證依據強烈建議的措施","(C) 導管相關尿路感染的發⽣與尿路導管材質的品質關係最⼤","(D) 經尿管輸液沖洗膀胱，即使在輸液內加入抗⽣素，仍可能增加導管相關尿路感染的機會"],"answer":3,"image":""},{"id":"md3-108-1-58","subject":"md3","topic":"內科-感染","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"下列有關Q熱感染（Q fever）的病因與表現的敘述，何者正確？","options":["(A) 在臺灣的個案以境外移入為主","(B) ⽪膚發現紅疹可以做為感染Q熱診斷依據","(C) 在原有瓣膜疾病問題的病患，可能導致⼼內膜炎（endocarditis）","(D) 是急性感染症，不會造成慢性感染"],"answer":2,"image":""},{"id":"md3-108-1-59","subject":"md3","topic":"內科-感染","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"70歲肺癌病⼈化學治療後，電腦斷層追蹤發現右上肺有3 cm的結節，切片⼿術病理報告為：Granulomatous inflammation、caseous necrosis、multinucleus giant cell，下列初步處置何者最不恰當？","options":["(A) 痰液結核菌抹片及結核菌培養","(B) 病理切片進⼀步特殊染⾊，以判斷可能之致病菌","(C) 進⾏隔離直到排除開放性結核","(D) 立即給與amphotericin B治療"],"answer":3,"image":""},{"id":"md3-108-1-60","subject":"md3","topic":"內科-感染","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"⼈類免疫不全病毒（HIV）感染CD4+ T細胞，先與CD4接受器結合，再與副接受器（co-receptor）結合，副接受器也是⼀種趨化素接受器（chemokine receptor），下列何種副接受器若在open reading frame（ORF）上兩個對偶基因（allele）都有32鹼基對（base pair）缺失，則宿主不會感染HIV？","options":["(A) CCR2","(B) CCR5","(C) CXCR4","(D) CXCR6"],"answer":1,"image":""},{"id":"md3-108-1-61","subject":"md3","topic":"急診醫學","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"⼀位20歲運動員參加⾺拉松比賽約2⼩時後因昏倒與痙攣被救護⾞送醫治療。抵達醫院時，意識呈昏迷，⼼ 跳每分鐘120次，⾎壓98/52毫米汞柱（mmHg），體溫攝⽒40.8度。驗⾎發現：aspartate aminotransferase（AST）110 U/L、alanine aminotransferase（ALT）123 U/L、肌酸酐（creatinine）2.2 mg/dL、鈉143 mmol/L、鉀4.7 mmol/L、鈣2.4 mmol/L、葡萄糖75 mg/dL。病⼈過去健康情況良好，比賽前無不適症狀。比賽當⽇氣溫為攝⽒37度。請依前述情況回答下列3題。此病⼈最可能的診斷為何？","options":["(A) 熱痙攣（heat cramps）","(B) 熱衰竭（heat exhaustion）","(C) 中暑（heat stroke）","(D) 熱昏厥（heat syncope）"],"answer":2,"image":""},{"id":"md3-108-1-62","subject":"md3","topic":"急診醫學","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"上述病⼈的處置，何者最不適宜？","options":["(A) 使⽤acetaminophen降低體溫","(B) 置入氣管內管","(C) 補充⽣理食鹽⽔","(D) 必要時使⽤lorazepam治療痙攣"],"answer":0,"image":""},{"id":"md3-108-1-63","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"兩天後，上述病⼈抱怨兩腿酸痛、腫脹，並且發現茶⾊尿，但尿量沒有明顯變少。下肢檢查發現肌⾁有壓痛。⾎中肌酸激酶（creatine kinase）42,700 U/L、肌酸酐（creatinine）2.8 mg/dL、鉀5.0 mmol/L、鈣2.07 mmol/L；尿液潛⾎反應呈4+，但顯微鏡檢查未看到紅⾎球。下列處置何者最適當？","options":["(A) 維持每⼩時尿量200～300 mL","(B) 酸化尿液","(C) 每天補充2,500 mL⽣理食鹽⽔","(D) 開始透析治療"],"answer":0,"image":""},{"id":"md3-108-1-64","subject":"md3","topic":"內科-感染","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"40歲病⼈因劇烈頭痛發燒來到急診，之前沒有⽤過抗⽣素，腦脊髓液檢查發現腦壓（opening pressure）300 mmHO，⽩⾎球100/mL（Lymphocyte：Neutrophil＝90：10），Protein level：45 mg/dL，最不可能2的致病菌為何？","options":["(A) herpes simplex virus","(B) Mycobacterium tuberculosis","(C) Cryptococcus neoformans","(D) Klebsiella pneumoniae"],"answer":3,"image":""},{"id":"md3-108-1-65","subject":"md3","topic":"內科-感染","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"承上題，腦脊髓液培養初步結果顯⽰有yeast，下列處置何者錯誤？","options":["(A) 給amphotericin B＋flucytosine","(B) 檢查HIV screening test","(C) 照胸部X光，抽⾎做黴菌培養及抗原檢測","(D) 給echinocandin類藥物"],"answer":3,"image":""},{"id":"md3-108-1-66","subject":"md3","topic":"內科-胸腔","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"21歲陳先⽣，無過去病史。3天前開始發燒、咳嗽。今天就診時仍發燒，且呼吸較急促、呼吸時胸痛，意識清楚。⾎壓96/62 mmHg，脈搏102 bpm，呼吸24 bpm，⽿溫39.2℃，右下肺葉扣診濁⾳（dullness），胸部X光出現右下肺葉浸潤，診斷為肺炎。依據CURB-65的原則，是否需要住院？","options":["(A) 不需住院，可⾨診治療","(B) 需住院治療，但只需入住⼀般病房","(C) 需住院治療，且需入住加護病房","(D) 未抽⾎檢查，無法判定"],"answer":0,"image":""},{"id":"md3-108-1-67","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"21歲王⼩姐，主訴在運動時會有哮鳴及呼吸急促之現象。要預防在此情況下誘發氣喘，下列那⼀藥物是最佳選擇？","options":["(A) 短效吸入型⼄⼆型擬交感神經劑（β-agonist）2","(B) ⼝服aminophylline","(C) 吸入型抗膽鹼劑（anticholinergics）","(D) 吸入型sodium cromoglycate（cromolyn）"],"answer":0,"image":""},{"id":"md3-108-1-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"75歲具⾼中教育程度的男性病⼈，因⾼⾎壓及糖尿病的追踪治療前來就診，同時陳述最近⼀個⽉接連發⽣兩次的跌倒，為他進⾏周全性老年評估，下列各類評估的敘述何者正確?","options":["(A) 需使⽤迷你⼼智狀態檢查（MMSE）進⾏⼼智狀態的評估，若得分在24分以下就屬於異常","(B) 需使⽤老年憂鬱量表（GDS-15）來進⾏憂鬱症評估，若總分在4分以下為正常，超過8分就算有憂鬱症","(C) 可使⽤迷你營養評估量表（MNA）來進⾏營養評估，若總分⾼於10分，表⽰可能有營養不良，需進⼀步提供營養諮詢","(D) 可使⽤巴⽒量表來進⾏⽇常⽣活功能評估，若得分在31～60分屬於輕度失能"],"answer":0,"image":""},{"id":"md3-108-1-69","subject":"md3","topic":"內科-感染","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"下列「狂⽝病暴露後的疫苗注射」及建議時間，何者正確？","options":["(A) 第0、3、7、14、28天，共5次","(B) 第0、7、14、28天，共4次","(C) 第0、7、28天，共3次","(D) 第0、14、28天，共3次"],"answer":0,"image":""},{"id":"md3-108-1-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"馮科⻑45歲，體型微胖，半年多前開始有無故突然的胸痛發作。看了多間醫學中⼼的⼼、肺等專科，做了各種健保及⾃費檢查，都找不出器質性原因。雖然醫師⼀再保證⼼臟病的可能很少，馮先⽣依然擔⼼仍有隱伏的⾝體問題未找出來，繼續不斷尋找各種醫療與檢查。根據精神疾病診斷與統計⼿冊第五版（DSM-V），最可能的診斷是？","options":["(A) 重度憂鬱症（major depression）","(B) 輕鬱性情感障礙症（dysthymic disorder）","(C) ⾝體症狀障礙症（somatic symptom disorder）","(D) 焦慮症（anxiety disorder）"],"answer":2,"image":""},{"id":"md3-108-1-71","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"就實證醫學（evidence-based medicine）的證據層級比較⽽⾔，下列不同的研究型態，何者的層級是最⾼ 的？","options":["(A) 世代研究（cohort study）","(B) 專家意⾒（expert opinion）","(C) 統合分析（meta-analysis）","(D) 個案對照研究（case-control study）"],"answer":2,"image":""},{"id":"md3-108-1-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"有關臺灣的社區醫療體系中，沒有從事基層醫療服務的單位或組織為何？","options":["(A) 衛⽣所","(B) 社區健康營造中⼼","(C) 社區醫療群","(D) 基層診所"],"answer":1,"image":""},{"id":"md3-108-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"孔太太是⼀位⼤腸癌末期病⼈，進入安寧病房時已經意識不清無法辨識家⼈，完全臥床無法⾏動，只能進食少量半固體食物，⾝體⽇漸虛弱與消瘦。你認為這時最適當的治療⽅式是什麼？","options":["(A) 放置⿐胃管灌食","(B) 使⽤周邊靜脈導管給予⼈⼯營養及⽔分","(C) 放置中央靜脈導管給予全靜脈營養","(D) 繼續經⼝給予可接受的食物"],"answer":3,"image":""},{"id":"md3-108-1-74","subject":"md3","topic":"影像醫學","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"⼀位女性病患右側甲狀腺及右下邊脖⼦淋巴腺無痛性腫⼤，其右側甲狀腺灰階及彩⾊杜⼘勒超⾳波檢查如圖，最可能的診斷為何？","options":["(A) 甲狀腺炎（thyroiditis）","(B) 甲狀腺乳突狀癌（papillary carcinoma）","(C) 甲狀腺瘤（adenoma）","(D) 良性多發性結節（nodular goiter）"],"answer":1,"image":"md3-108-1-74.jpeg"},{"id":"md3-108-1-75","subject":"md3","topic":"急診醫學","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"依2015年American Heart Association Guidelines執⾏成⼈⼼肺復甦時，應提供的通氣次數及通氣量（潮氣容積），下列敘述何者較不適當？","options":["(A) 使⽤袋瓣⾯罩（Bag-Valve-Mask）時，成⼈為每分鐘通氣10～12次","(B) 當插上氣管內管時，成⼈每次通氣間隔約6秒","(C) 當插上氣管內管時，成⼈的壓胸及通氣比為30：2","(D) 維持每次6～7 mL/kg的通氣量"],"answer":2,"image":""},{"id":"md3-108-1-76","subject":"md3","topic":"內科-心臟血管","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"有關古柯鹼（Cocaine）所造成的急性冠⼼症時，下列那⼀種藥物是禁忌？","options":["(A) Diazepam（benzodiazepine類藥物）","(B) Morphine（鴉片類藥物）","(C) Phentolamine（α-腎上腺阻斷劑）","(D) Propranolol（β-腎上腺阻斷劑）"],"answer":3,"image":""},{"id":"md3-108-1-77","subject":"md3","topic":"內科-腎臟","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"⼀位66歲糖尿病合併腎病變病⼈，有胸悶、咳嗽無痰、呼吸急促、意識昏睡，⽣命徵象顯⽰⾎壓80/40 mmHg，⼼跳每分鐘40下，呼吸每分鐘26次，體溫36℃。經抽⾎檢查發現鉀離⼦7.7 mmol/L、⾎糖300 - =12 mEq/L mg/dL、動脈⾎：pH=7.20，HCO，BE= -12 mEq/L。下列何者治療不適當？3","options":["(A) 經靜脈給予碳酸氫鈉，可將鉀離⼦由細胞外移入細胞內","(B) 經靜脈給予葡萄糖⽔及胰島素，可將鉀離⼦由細胞外移入細胞內","(C) 經靜脈快速灌注⽣理食鹽⽔1000 mL，治療低⾎壓及稀釋鉀離⼦","(D) 經靜脈給予氯化鈣，以拮抗鉀離⼦對⼼臟細胞膜電位的影響"],"answer":2,"image":""},{"id":"md3-108-1-78","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"⼀位18歲男性因為8⼩時前開始腹痛⽽來急診，伴隨有些微噁⼼症狀，食慾不佳（anorexia），無發燒。腹部疼痛的位置原本在肚臍周圍（periumbilical area），到醫院時發現轉移到右下腹部。理學檢查發現腸⾳稍慢，右下腹有壓痛（tenderness），無反彈痛（rebound tenderness），有腰⼤肌徵象（psoas sign）。依 ⽬前的研究證據，你認為那⼀項症狀或徵象對於懷疑闌尾炎的敏感度（sensitivity）最⾼？","options":["(A) 腰⼤肌徵象（psoas sign）","(B) 轉移痛（migration pain）","(C) 右下腹痛（right lower quadrant pain）","(D) 發燒（fever）"],"answer":2,"image":""},{"id":"md3-108-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"依據安寧緩和醫療條例之規定，不施⾏⼼肺復甦術或維⽣醫療之意願書的內容，下列敘述何者錯誤？","options":["(A) 意願⼈之姓名、國⺠⾝分證統⼀編號及住所或居所","(B) 立意願書之⽇期","(C) 意願⼈接受安寧緩和醫療或維⽣醫療抉擇之意願及其內容","(D) 意願書之簽署，應有具完全⾏為能⼒者⼆⼈以上在場⾒證。⾒證⼈最好為實施安寧緩和醫療之醫療機構⼈ 員"],"answer":3,"image":""},{"id":"md3-108-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"下列何者不是學者Jonsen等⼈⽤來解決臨床醫學個案問題的四主題法或四象限法（four topics or four boxes method）的內容？","options":["(A) 不傷害原則（nonmaleficience）","(B) 醫療適應症（medical indications）","(C) 病⼈偏好（patient preferences）","(D) ⽣活品質（quality of life）"],"answer":0,"image":""},{"id":"md3-108-2-1","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"一位下肢水腫合併腹水的病人，血清中白蛋白（albumin）為3.0 g/dL，腹水中的白蛋白（ascitic albumin）及蛋白質總量（ascitic protein）分別為1.2及2.8 g/dL，下列何項診斷最不可能？","options":["(A) hepatic vein thrombosis, early stage","(B) heart failure","(C) liver cirrhosis","(D) hepatic sinusoidal obstruction syndrome"],"answer":2,"image":""},{"id":"md3-108-2-2","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"下列那一種藥物或狀況最不可能造成呼吸性鹼中毒？","options":["(A) 水楊酸鹽（salicylates）","(B) 高山","(C) 懷孕","(D) 嗎啡（morphine）"],"answer":3,"image":""},{"id":"md3-108-2-3","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"有關心導管檢查中各種壓力測量數據的敘述，下列何者正確？","options":["(A) 正常平均（mean）肺動脈壓力為30～40 mmHg","(B) 緊縮性（constrictive）心外膜炎跟限制性（restrictive）心肌病變不同，其右心室舒張末壓應小於右心室收縮壓之1/3","(C) 肺微血管楔壓（wedge pressure）在二尖瓣狹窄病人，可間接代表左心室舒張末壓","(D) 欲計算得到體循環血管阻力（systemic vascular resistence），需測得心輸出量、平均主動脈壓及平均右心房壓"],"answer":3,"image":""},{"id":"md3-108-2-4","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"有關心電圖PR間距（PR interval），最不可能代表下列心跳週期的那一部分？","options":["(A) 心房去極化（atrial depolarization）","(B) 心房再極化（atrial repolarization）","(C) 房室間細胞延遲（atrioventricular delay）","(D) 心室去極化（ventricular depolarization）"],"answer":3,"image":""},{"id":"md3-108-2-5","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"一位70歲女性患有糖尿病外，無其它病史，半夜突然胸痛、冒汗、想吐，送至急診時血壓137/79 mmHg，脈搏73次/分，呼吸18次/分，心電圖如下所示，緊急心導管檢查發現心肌梗塞，最可能是那一條冠狀動脈血管堵塞？","options":["(A) 左主幹","(B) 左前降支","(C) 左迴旋支","(D) 右冠狀動脈"],"answer":1,"image":"md3-108-2-5.jpeg"},{"id":"md3-108-2-6","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"以下何項特徵最可以區分心包膜填塞（cardiac tamponade）與限制性心包膜炎（constrictive pericarditis）？","options":["(A) 奇脈（pulsus paradoxus）","(B) Kussmaul’s sign","(C) 第三心音（third heart sound）","(D) 頸靜脈壓力波型呈現顯著的X波下降（prominent x descent）"],"answer":1,"image":""},{"id":"md3-108-2-7","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"一位60歲男性最近數月出現漸進性喘及活動後胸悶情形，至心臟內科門診求診。經過一系列檢查後，發現有擴張性心肌症合併心衰竭。以下何者錯誤？","options":["(A) 可能原因有很多種，包括感染、毒物、代謝性疾病或家族遺傳性","(B) 心臟超音波可見擴張左心室以及心臟收縮功能減弱","(C) 若病患合併有左束枝傳導阻斷（left bundle branch block），給予心臟再同步化節律器（cardiac resynchronization pacing）置放後可改善心臟收縮功能","(D) 藥物治療無法讓心臟收縮功能改善"],"answer":3,"image":""},{"id":"md3-108-2-8","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"在測量血壓時，由近心端往周邊的方向逐次測量，下列敘述何者正確？","options":["(A) 收縮壓上升，舒張壓降低","(B) 收縮壓上升，舒張壓上升","(C) 收縮壓不變，舒張壓降低","(D) 收縮壓上升，舒張壓不變"],"answer":0,"image":""},{"id":"md3-108-2-9","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"有關pulsus alternans之敘述，下列何者正確？","options":["(A) 一般而言，皆與心電圖記錄的electrical alternans同時出現","(B) 在嚴重左心衰竭病人身上出現時，代表心臟收縮力每次心跳之間有差異","(C) 常出現在清晨時","(D) 常出現在肺高壓合併右心衰竭的病人"],"answer":1,"image":""},{"id":"md3-108-2-10","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"下列何者不是肥厚型心肌病變的心因性猝死主要預測因子？","options":["(A) 病患有猝死的家族病史","(B) 病患左心室超音波顯示有異常的肥厚＞30 mm","(C) 年輕病患在運動達到最高量過程時，血壓上升","(D) 病患24小時心電圖顯示有自發性，但出現時間＜30秒的心室頻脈（spontaneous nonsustained ventricular tachycardia）"],"answer":2,"image":""},{"id":"md3-108-2-11","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"有關肺栓塞（pulmonary embolism）的藥物治療，下列何者正確？","options":["(A) 常見的症狀與表徵包括：胸痛，心搏過速，頸靜脈怒張，臨床檢查評估P2會變得較小聲","(B) 這些病患很容易再發，針劑與口服抗凝血劑使用至少3年的療程","(C) 萬一治療過程中，肺部電腦斷層仍然有大量血塊（massive pulmonary embolism），可以考慮靜脈注射溶血劑（thrombolytic therapy），或是使用導管就近注射溶血劑，為求有效，tissue plasminogen activator建議給與100 mg，與周邊給藥的劑量相同","(D) 臨床試驗發現，一些新型口服抗凝血藥物（例如：rivaroxaban，dabigatran，apixaban）效果不亞於warfarin，但出血事件較為減少"],"answer":3,"image":""},{"id":"md3-108-2-12","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"下列有關HDV的描述，何者錯誤？","options":["(A) HDV可以與HBV急性共同感染（coinfection），或是重覆感染（superinfection）於HBV帶原者","(B) 重覆感染HDV，對原本慢性HBV帶原者有不好的影響，可能促使肝臟疾病快速惡化或造成猛爆性肝衰竭","(C) HDV與HBV急性共同感染之後演變成慢性D型肝炎的機會較低","(D) interferon（或pegylated interferon）是目前唯一被證實有效治療HDV的藥物，根治率極高（＞80%）且不容易復發"],"answer":3,"image":""},{"id":"md3-108-2-13","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"有關自體免疫性肝炎（autoimmune hepatitis, AIH）之診斷與治療，根據International Autoimmune Hepatitis Group的評分建議，以下何者錯誤？","options":["(A) 診斷自體免疫性肝炎之前需要先排除常見肝臟疾病，包括病毒性肝炎","(B) 患者對免疫抑制療法的效果是診斷自體免疫性肝炎的評分項目之一","(C) antinuclear antibody（ANA）是最重要常見的免疫學指標","(D) 遺傳背景方面，AIH的發生與HLA-A2和DR6有相關"],"answer":3,"image":""},{"id":"md3-108-2-14","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"下列有關E型肝炎之敘述，何者錯誤？","options":["(A) E型肝炎病毒主要是經口糞途徑傳染，潛伏期約24週","(B) 感染急性E型肝炎患者，大多數預後良好，極少數患者感染後可能併發猛爆性肝衰竭（fulminant hepatic failure）","(C) E型肝炎病毒IgM抗體（IgM anti-HEV）為診斷急性E型肝炎的血清標記","(D) 感染急性E型肝炎之患者會完全痊癒，只有少數免疫功能嚴重受損之患者會演變成慢性E型肝炎"],"answer":0,"image":""},{"id":"md3-108-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"有關遺傳學與基因檢測在肝臟疾病的研究，下列敘述何者錯誤？","options":["(A) 在肝臟酒精代謝方面，酒精氧化代謝成乙醛（acetaldehyde）後，藉由乙醛脫氫酶（aldehyde dehydrogenase）氧化成乙酸（acetate）。當乙醛脫氫酶有基因突變時會造成乙醛堆積而發生症狀（包括臉潮紅），最常見突變點發生在ALDH2基因","(B) 在自體免疫性肝炎（autoimmune hepatitis）方面，遺傳背景與HLA-B1, -B8, -DR3和-DR4有相關","(C) 在遺傳性鐵質沉著症（hereditary hemochromatosis）方面，以HFE基因相關C282Y與H63D突變最常見","(D) 在威爾森症（Wilson's disease）方面，最常見突變點發生在ATP7B基因，且只有一種突變會發生"],"answer":3,"image":""},{"id":"md3-108-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"下列解讀B型肝炎血清標誌之敘述，何者錯誤？","options":["(A) IgM anti-HBc可以用來分辨急性或慢性B型肝炎","(B) rheumatoid factor（RF）high titer時，IgM anti-HBc有假陽性的可能","(C) 慢性B型肝炎急性發作（acute reactivation of chronic hepatitis B）時，IgM anti-HBc可以出現陽性反應","(D) antinuclear antibody（ANA）high titer時，IgM anti-HBc有假陽性的可能"],"answer":3,"image":""},{"id":"md3-108-2-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"肝硬化會導致肝門靜脈高壓（portal hypertension），以下那種情況與肝門靜脈高壓的相關性較低？","options":["(A) 肝性腦病變（hepatic encephalopathy）","(B) 食道靜脈曲張（esophageal varices）","(C) 脾腫大併脾臟機能亢進（splenomegaly and hypersplenism）","(D) 腹水（ascites）"],"answer":0,"image":""},{"id":"md3-108-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"關於大腸直腸癌之描述何者正確？","options":["(A) 大腸直腸癌治療後如有復發，多半集中在前四年，因此五年存活率極具參考價值","(B) T3N0M0屬於第三期","(C) T1N1M0屬於第二期","(D) 肺部是大腸直腸癌最容易轉移的內臟器官"],"answer":0,"image":""},{"id":"md3-108-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"下列關於大腸激躁症（irritable bowel syndrome）的敘述，何者正確？","options":["(A) 嚴重大腸激躁症，與腸道生理的相關性較強，與精神方面的異常關聯性較小","(B) 大腸激躁症的盛行率男性為女性的2～3倍","(C) 某些抗生素如rifaximin對於部分大腸激躁症病患會有效","(D) 抗憂鬱藥物（antidepressant drugs）對於大腸激躁症是無幫助的"],"answer":2,"image":""},{"id":"md3-108-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"下列關於消化道內視鏡處置之敘述，何者正確？","options":["(A) 如果病人解大量鮮血便（hematochezia），必為下消化道的大量出血，要緊急安排大腸鏡","(B) 施行內視鏡前，假如有服用低劑量阿斯匹靈則必須先停藥一週","(C) 所有黃疸病患都是施行逆行性膽胰鏡（endoscopic retrograde cholangiopancreatography, ERCP）的適應症","(D) 消化道早期表淺癌，逐漸有以內視鏡切除（endoscopic or endoluminal resection）之趨勢"],"answer":3,"image":""},{"id":"md3-108-2-21","subject":"md3","topic":"內科-腎臟","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"下列何種疾病不適合使用arginine vasopressin（AVP）拮抗劑（vaptans）？","options":["(A) 抗利尿激素不適當分泌症候群（SIADH）","(B) 高體液低鈉血症（hypervolemic hyponatremia）","(C) 小細胞肺癌合併之低鈉血症","(D) 尿崩症（diabetes insipidus）"],"answer":3,"image":""},{"id":"md3-108-2-22","subject":"md3","topic":"內科-腎臟","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"++ 56歲男性糖尿病人因胸部不適至急診，初步檢查血中creatinine 2.0 mg/dL、K 5.8 mEq/L、Na139 mEq/L、 - - 18 mEq/L Cl116 mEq/L、HCO、osmolality 290 mOsm/kg‧HO、尿中creatinine 12 mg/dL、K 9.6 mEq/dL、32 osmolality 580 mOsm/kg‧HO，病人最可能的診斷是：2","options":["(A) 第二型腎小管酸血症（type 2 renal tubular acidosis）","(B) metformin引發酸血症（metformin related acidosis）","(C) 低腎素低醛固酮血症（hyporeninemic hypoaldosteronism）","(D) 糖尿病酮酸血症（diabetic ketoacidosis）"],"answer":2,"image":""},{"id":"md3-108-2-23","subject":"md3","topic":"內科-腎臟","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"一名30歲女性，近2個月血清肌酸酐從1.0升至3.0 mg/dL，其血清anti-neutrophil cytoplasmic抗體呈陰性反應，血清C3降低，C4正常，經腎臟切片檢查確定為新月型腎絲球腎炎，電鏡檢查發現有subepithelial electron-dense沉積，glomerular basement membrane厚度正常，下列診斷何者正確？","options":["(A) membranous nephropathy","(B) membranoproliferative glomerulonephritis, type II","(C) lupus nephritis","(D) poststreptococcal glomerulonephritis"],"answer":3,"image":""},{"id":"md3-108-2-24","subject":"md3","topic":"內科-腎臟","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"一名40歲男性糖尿病患者，定期接受降血糖（metformin）和血壓藥物（amlodipine）治療，其居家血壓維持138/86 mmHg，最近HbA1c為6.8%，血紅素10.7 g/dL，尿蛋白1.5 g/day，estimated GFR 59 mL/min per 1.73 2 m，下列治療策略何者正確？","options":["(A) 輔以低劑量長效型胰島素","(B) 使用紅血球生成素減緩腎功能惡化","(C) 加上血管張力素受器阻斷劑","(D) 進行低蛋白飲食合併胺基酸補充品"],"answer":2,"image":""},{"id":"md3-108-2-25","subject":"md3","topic":"內科-腎臟","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"下列有關預防顯影劑腎病變的敘述，何者正確？","options":["(A) 通常血清肌酸酐於注射顯影劑後24～48小時開始上升，有高於1%病人需接受透析治療","(B) 以生理鹽水預防顯影劑腎病變，可於施打顯影劑後開始給與，持續6～24小時","(C) 統合分析顯示N-acetylcysteine預防顯影劑腎病變的效果佳且副作用低，建議臨床上常規使用","(D) 其致病機轉包括腎臟outer medulla缺氧、腎小管細胞自由基傷害及暫時性腎小管阻塞等因素"],"answer":3,"image":""},{"id":"md3-108-2-26","subject":"md3","topic":"內科-腎臟","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"有關慢性腎臟病所併發之腎性貧血（renal anemia），下列敘述何者錯誤？","options":["(A) 腎性貧血之紅血球型態常為正常血球大小（normocytic）與正常色素性（normochromic）","(B) 腎性貧血常出現虛弱、運動耐受力不良（exercise intolerance）、心衰竭與認知功能異常等症狀","(C) 因慢性腎臟病病患常合併血液凝集功能異常，故造成腎性貧血最主要的原因為胃腸道出血","(D) 將腎性貧血病患之血色素值矯正至正常人標準值（≥13 g/dL），無法改善病患之心血管併發症"],"answer":2,"image":""},{"id":"md3-108-2-27","subject":"md3","topic":"內科-腎臟","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"下列有關慢性腎臟病的敘述，何者錯誤？","options":["(A) 糖尿病乃目前臺灣新發生長期透析病患最常見之原發病因","(B) 慢性腎臟病患合併糖尿病，其血壓值應控制在130/80 mmHg以下","(C) 敗血症為最常造成慢性腎臟病患死亡的原因","(D) 低蛋白飲食有助於改善慢性腎臟病患之尿毒症狀"],"answer":2,"image":""},{"id":"md3-108-2-28","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"下列關於痛風（gout）和急性痛風性關節炎（acute gouty arthritis）的描述，何者錯誤？","options":["(A) 急性痛風性關節炎發生在下肢的機率比上肢高","(B) 痛風發生在男性的機率比女性高","(C) 高尿酸血症（hyperuricemia）是引起痛風的主要原因，因此急性痛風性關節炎發作時測血中尿酸值對疾病的診斷很有幫助","(D) 急性痛風性關節炎的關節液檢查可發現白血球上升的情形，關節液白血球計數可從數千至數萬"],"answer":2,"image":""},{"id":"md3-108-2-29","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"許多非關節炎疾病常可能合併關節病變，下列相關敘述何者正確？","options":["(A) hypertrophic osteoarthropathy與肺癌（lung cancer）有關","(B) pigmented villonodular synovitis（PVNS）與糖尿病（diabetes mellitus）有關","(C) hemophilic arthropathy與慢性腎臟病（chronic kidney disease）有關","(D) neuropathic joint disease與carpal tunnel syndrome有關"],"answer":0,"image":""},{"id":"md3-108-2-30","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"相較於瀰漫型硬皮症（diffuse systemic sclerosis），下列何者是侷限型硬皮症（limited systemic sclerosis）的特性？","options":["(A) 皮膚硬化進展較快","(B) 若併發間質性肺炎（interstitial lung disease）進展比較緩慢","(C) 關節疼痛較嚴重","(D) 常常出現anti-topoisomerase I（Scl-70）抗體陽性"],"answer":1,"image":""},{"id":"md3-108-2-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"有關貝賽特氏症（Behçet's syndrome）的敘述，下列何者正確？","options":["(A) 病人常常會反覆口腔與生殖器潰瘍","(B) 很少攻擊眼睛","(C) 女性病人比男性多，而且病情較嚴重","(D) 很少會併發關節痛"],"answer":0,"image":""},{"id":"md3-108-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"31歲王小姐被診斷為全身性紅斑狼瘡併腎炎約7年，初發病時經過prednisolone與mycophenolate治療後，近5年24小時尿蛋白都小於0.5克，血中creatinine為0.6 mg/dL，目前用藥為prednisolone每日5毫克加hydroxychloroquine 200毫克。王小姐因近日即將結婚，有懷孕的計畫，所以到門診來諮詢是否需調整藥物。下列何項臨床處置最為適當？","options":["(A) 將prednisolone換成等強度dexamethasone","(B) 維持目前用藥不需改變","(C) 停掉hydroxychloroquine","(D) 加上azathioprine"],"answer":1,"image":""},{"id":"md3-108-2-33","subject":"md3","topic":"內科-消化肝膽胰","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"有關肝細胞癌（hepatocellular carcinoma，即HCC）的臨床評估及診治，以下敘述何者錯誤？","options":["(A) 理學檢查時，應注意是否有jaundice、ascites、spider angioma、palmar erythema等可能指出有chronic liver disease或liver cirrhosis的signs","(B) 血清AFP是常用的tumor marker；但並非所有的HCC患者，血清AFP皆會升高","(C) ultrasound，triphasic CT及gadolinium-enhanced MRI皆是可應用來協助診斷HCC的影像檢查方式","(D) 正子攝影（FDG-PET）已被證實是診斷HCC最敏感的影像檢查方式"],"answer":3,"image":""},{"id":"md3-108-2-34","subject":"md3","topic":"內科-腫瘤","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"下列關於惡性黑色素細胞癌（malignant melanoma）的敘述，何者正確？","options":["(A) 西方病患惡性黑色素細胞癌的基因突變最多的是NRAS突變","(B) 東方病患惡性黑色素細胞癌的型態最常見的是肢端小痣（acral lentiginous）型","(C) 惡性黑色素細胞癌的初級預防是教育、篩檢、早期偵測","(D) 轉移惡性黑色素細胞癌的藥物治療只有標靶治療有效"],"answer":1,"image":""},{"id":"md3-108-2-35","subject":"md3","topic":"內科-腫瘤","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"關於第四期肺癌的治療，下列何者錯誤？","options":["(A) 第四期非小細胞肺癌有表皮生長因子受體（epidermal growth factor receptor）突變的治療是erlotinib、afatinib等標靶治療","(B) 第四期非小細胞肺癌有ALK基因重置（rearrangement）的治療是標靶治療，例如：crizotinib","(C) 免疫檢查站（checkpoint）抑制劑對第四期非小細胞肺癌的治療毫無幫助","(D) 第四期小細胞肺癌的治療主要是化學治療"],"answer":2,"image":""},{"id":"md3-108-2-36","subject":"md3","topic":"內科-腫瘤","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"去勢治療失敗的（castration-resistant）攝護腺癌（prostate cancer），其藥物治療不包括下列何者？","options":["(A) flutamide","(B) enzalutamide","(C) abiraterone acetate","(D) docetaxel"],"answer":0,"image":""},{"id":"md3-108-2-37","subject":"md3","topic":"內科-血液","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"一位46歲男性，過去無特殊病史，因呼吸急促，腹部腫脹而被送到急診求診。理學檢查呈現結膜蒼白，脾臟腫大並且有腹水。實驗室數據顯示：白血球8450/μL，分類blast 2.9%，myelocyte 1%，metamyelocyte 3.8%，band 6.7%，segmented neutrophil 37.1%，lymphocyte 31.4%。血紅素9.7 g/dL，血小板55,000/μL，尿酸12.1 mg/dL（參考區間2.6～7.5），lactate dehydrogenase（LDH）2342 U/L（參考區間140～271）。其骨髓細胞顯示如下圖。染色體有t(2;8)(p12;q24)之變化。以下關於這位病人最可能的疾病之診斷與治療，何者錯誤？","options":["(A) 此病之機轉包含了c-myc之deregulation","(B) 此病之病程相當快速，必須儘早治療","(C) 此病之治療過程必須包含腦脊髓液之檢查與intrathecal chemotherapy","(D) 一般而言，此病之治療效果不佳，以目前之治療，長期存活率小於3成"],"answer":3,"image":"md3-108-2-37.jpeg"},{"id":"md3-108-2-38","subject":"md3","topic":"內科-血液","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"維生素B是造血的重要元素之一，以下對維生素B的敘述何者錯誤？1212","options":["(A) 人體每日所需維生素B的量相當少（約1～3微克）12","(B) 在完全無法經由飲食吸收維生素B的狀況下，如果沒有另外補充，通常需要3～4年才能消耗完身體中的儲12存量","(C) 哺乳中的婦女若有維生素B缺乏容易造成嬰兒生長發育遲滯12","(D) 蔬果類食物含有豐富的維生素B 12"],"answer":3,"image":""},{"id":"md3-108-2-39","subject":"md3","topic":"內科-血液","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"58歲男性，近半年感到腹部不適，某日就診時發現有兩側頸部、腋下與腹股溝淋巴結腫大。病人體溫38.8℃，血壓90/50mmHg，並有畏寒與疲累的症狀，血球檢查數據如下（括弧內是正常參考數值）：RBC 4.12 M/μL（4～5.52），Hb 12.4 g/dL（13.2～17.2），Retic. 1.48%（0.5～2），PLT 261 k/μL（148～339），WBC 9.74 k/μL（3.54～9.06），Blast 0% ，Promyel. 0%，Myelo. 0%，Meta 0%，Band 0%，Seg 5.0%，Eos. 3.0%，Baso. 1.0%，Mono. 8.0%，Lym. 83.0%，Aty.Lym. 0.0%，Plasma cell 0.0%，Normobl. 0.0/100 WBC。以下那個敘述錯誤？","options":["(A) 因為白血球總數正常，只需要症狀治療","(B) 應該要做詳細的身體檢查，以找出可能的感染來源","(C) 應該要接受血液細菌培養","(D) 應該要儘早投與靜脈注射的廣效性抗生素"],"answer":0,"image":""},{"id":"md3-108-2-40","subject":"md3","topic":"內科-血液","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"下列何種疾病無法用異體造血幹細胞移植（hematopoietic stem cell transplantation）的方式來達到長期緩解？","options":["(A) 黏多醣症","(B) 嚴重再生不良性貧血","(C) 重度海洋性貧血","(D) 肝細胞癌"],"answer":3,"image":""},{"id":"md3-108-2-41","subject":"md3","topic":"內科-腫瘤","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"以下何者不是Krukenberg tumor常見的原發腫瘤部位？","options":["(A) 大腸（colon）","(B) 肺（lung）","(C) 胃（stomach）","(D) 乳房（breast）"],"answer":1,"image":""},{"id":"md3-108-2-42","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"48歲女性無抽菸史，因爬樓梯會喘，到內科門診，身體診察發現右側有胸水，經超音波導引胸水引流，胸水細胞檢驗發現adenocarcinoma，肺部電腦斷層顯現右下肺有3 cm腫瘤，併發兩側肺葉密密麻麻的轉移，核磁共振檢驗發現腦部無轉移，經支氣管切片，證實為肺腺癌（lung adenocarcinoma），其他器官功能正常，醫師評估performance status (PS) 1。下列那項處置最適當？","options":["(A) 右下肺葉切除併縱膈腔淋巴腺廓清（right lower lobe lobectomy＋mediastinal lymph nodes dissection）","(B) 單獨給與肋膜沾黏術（pleurodesis）","(C) 右下肺腫瘤立體定位放射手術（stereotactic radiosurgery）","(D) 用肺癌檢體，進行EGFR mutation及ALK rearrangements檢測"],"answer":3,"image":""},{"id":"md3-108-2-43","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"關於氣胸（pneumothorax）的敘述，下列何者正確？","options":["(A) 原發性自發性氣胸（primary spontaneous pneumothorax）的病人，發生一次氣胸後，約有50%會復發","(B) 一位使用呼吸器的病人，突然發生張力性氣胸（tension pneumothorax）時，醫師無法靠身體診查診斷出來","(C) 病人有肋膜積水（pleural effusion），經細針導管引流後，出現氣胸（pneumothorax），一定是針頭導致臟層肋膜（visceral pleura）破洞","(D) 慢性阻塞性肺病（chronic obstructive pulmonary disease）的病人發生氣胸，只要給與氧氣治療及觀察即可"],"answer":0,"image":""},{"id":"md3-108-2-44","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"52歲男性病人，在坐起來的時候，比躺下時有較低血氧症（orthodeoxia）及呼吸困難（platypnea），此位病人最可能罹患下列何種疾病？","options":["(A) 睡眠呼吸中止症候群","(B) 心臟衰竭","(C) 肝硬化併門脈高壓","(D) 氣喘"],"answer":2,"image":""},{"id":"md3-108-2-45","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"70歲的男性，因為咳嗽10個月及體重減輕就醫，其胸部X光檢查如附圖。關於進一步的檢驗，下列何者最不適當？","options":["(A) 痰液塗片耐酸性染色鏡檢（acid-fast stain）","(B) 痰液分枝桿菌培養（mycobacterial culture）","(C) 痰液結核菌核酸增幅檢驗（nucleic acid amplification test）","(D) 丙型干擾素血液測驗（interferon γ release assay）"],"answer":3,"image":"md3-108-2-45.jpeg"},{"id":"md3-108-2-46","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"關於非結核分枝桿菌（nontuberculous mycobacteria）的治療，下列敘述何者最不適當？","options":["(A) 一旦確認為非結核分枝桿菌的感染，就必須立刻治療，避免疾病惡化","(B) 通常治療非結核分枝桿菌肺部感染，都必須同時用多種藥物治療","(C) Mycobacterium avium complex通常治療藥物包括macrolide（如clarithromycin）, ethambutol及rifamycin（rifampin或rifabutin）","(D) Mycobacterium kansasii通常以isoniazid, rifampin及ethambutol治療"],"answer":0,"image":""},{"id":"md3-108-2-47","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"甲狀腺癌的病患接受手術切除，並完成高劑量之放射碘-131同位素治療後，臨床上，下列何者為血液中追蹤甲狀腺癌是否復發之生化指標？","options":["(A) 四碘甲狀腺素（T）4","(B) 三碘甲狀腺素（T）3","(C) 甲狀腺球蛋白（thyroglobulin）","(D) 甲促素（TSH）"],"answer":2,"image":""},{"id":"md3-108-2-48","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"低血糖是臨床上常見的現象，下列那一項敘述最不適當？","options":["(A) 胰島素瘤（insulinoma）的典型表現為Whipple's triad，是低血糖最常見的原因","(B) 低血糖可引起致命的結果，必須及時處理","(C) 低血糖的常見症狀包括發慌、心跳加速、冒冷汗及昏迷等","(D) 臨床上可引起低血糖的藥物包括胰島素、sulfonylureas及glinides類"],"answer":0,"image":""},{"id":"md3-108-2-49","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"關於非自主性的體重流失（involuntary weight loss）的敘述，下列何者錯誤？","options":["(A) 在6至12個月內，體重下降超過4.5公斤","(B) 在6至12個月內，體重下降大於原先體重的5%","(C) 甲狀腺功能亢進時，食慾減退是體重下降的主因","(D) 慢性阻塞性肺病是其中一個原因"],"answer":2,"image":""},{"id":"md3-108-2-50","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"有關脂質代謝之敘述，下列何者錯誤？","options":["(A) 腸道所吸收的脂肪，經腸細胞組成乳糜微粒（chylomicron）後，進入乳糜小管","(B) 分解血液中之三酸甘油脂的酶，是荷爾蒙敏感性脂肪酶（hormone-sensitive lipase）","(C) 低密度脂蛋白（LDL）是由血液中的極低密度脂蛋白（VLDL）轉化而成","(D) 高密度脂蛋白（HDL）可以和其他血中的脂蛋白進行脂質交換"],"answer":1,"image":""},{"id":"md3-108-2-51","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"因甲狀腺功能亢進造成心律不整的患者，應儘量避免使用下列何種藥物，以避免甲狀腺功能亢進惡化？","options":["(A) digoxin","(B) amiodarone","(C) propranolol","(D) diltiazem"],"answer":1,"image":""},{"id":"md3-108-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"若懷疑病人有橋本氏症（Hashimoto's thyroiditis）造成甲狀腺功能低下，檢查下列何種抗體最能佐證？","options":["(A) anti-dsDNA antibody","(B) anti-IgG4 antibody","(C) anti-TSH receptor antibody","(D) anti-thyroglobulin antibody, anti-thyroid peroxidase antibody"],"answer":3,"image":""},{"id":"md3-108-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"一位67歲女性，服用含類固醇中藥多年治療背痛，有庫欣氏症（Cushing's syndrome）外觀，經家人勸告後已停藥1個月。現因泌尿道感染引發低血壓休克、意識不清被送來急診。除使用抗生素、輸液、升壓藥物治療外，應立刻給與何種處置？","options":["(A) 立即抽血送驗cortisol，不必等報告結果出來，可立即注射糖皮質素（glucocorticoid）治療","(B) 立即抽血送驗cortisol，須等報告結果出來確認為腎上腺機能不足，才能給與糖皮質素（glucocorticoid）治療","(C) 抽血送驗上午8點與下午4點的cortisol後，立即注射糖皮質素（glucocorticoid）治療","(D) 立刻進行促腎上腺素刺激測驗（ACTH stimulation test），測驗完畢立即注射糖皮質素（glucocorticoid）治療"],"answer":0,"image":""},{"id":"md3-108-2-54","subject":"md3","topic":"內科-感染","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"下列關於氟喹諾酮類抗生素（quinolone，如ciprofloxacin、levofloxacin）的敘述，何者正確？","options":["(A) 是抑菌而不是殺菌型藥物","(B) 對淋病球菌（Neisseria gonorrhoeae）抗藥性增加，不建議做為第一線治療藥物","(C) 主要是由膽汁排泄清除，腎衰竭病人不需調整劑量","(D) 由於對綠膿桿菌（Pseudomonas aeruginosa）的殺菌作用不佳，發燒和中性顆粒細胞減少症病人是禁忌"],"answer":1,"image":""},{"id":"md3-108-2-55","subject":"md3","topic":"內科-感染","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"關於類鼻疽（melioidosis）疾病，下列敘述何者正確？","options":["(A) 通常是由人與人互相傳播而造成感染","(B) 病人在急性肺炎感染時，可以由血液或痰的培養來診斷疾病","(C) 首選抗生素是cefazolin（第一代頭孢子素）","(D) 使用有效的抗生素2週可治癒"],"answer":1,"image":""},{"id":"md3-108-2-56","subject":"md3","topic":"內科-感染","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"臨床上中央靜脈導管常使用於輸液注射與藥物給與，但必須預防併發導管相關的血流感染。此病原菌感染最常見的來源是：","options":["(A) 經由皮膚置入導管部位的污染","(B) 製備注射藥物的污染","(C) 由其他部位菌血症引起的細菌植入","(D) 製造輸液過程中的污染"],"answer":0,"image":""},{"id":"md3-108-2-57","subject":"md3","topic":"內科-感染","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"80歲女性因肺癌住院接受化學治療。住院第20天病人喘、寒顫、休克（血壓80/60 mmHg），X光顯示右下肺炎（lobar pneumonia），應進行的處置何者最不恰當？","options":["(A) 痰液鏡檢及培養","(B) 血液培養兩套","(C) 驗白血球計數及分類","(D) 給與第一代cephalosporin治療"],"answer":3,"image":""},{"id":"md3-108-2-58","subject":"md3","topic":"內科-感染","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"50歲健康男性，因牙結石進行相關治療，過去病史有penicillin過敏，下列建議何者最恰當？","options":["(A) 給與clindamycin預防心內膜炎","(B) 給與vancomycin預防心內膜炎","(C) 給與tetracycline預防心內膜炎","(D) 不需給與預防性抗生素"],"answer":3,"image":""},{"id":"md3-108-2-59","subject":"md3","topic":"內科-感染","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"下列診斷標誌，何者可以最早偵測急性人類免疫不全病毒（HIV）感染？","options":["(A) p24 antigen","(B) HIV viral load","(C) HIV antibody","(D) Western blot"],"answer":1,"image":""},{"id":"md3-108-2-60","subject":"md3","topic":"內科-感染","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"Abacavir是治療人類免疫不全病毒（HIV）的核苷反轉錄酶抑制劑，有些病人服用可能會引起致死性的超敏感性反應（hypersensitivity reaction），其與下列何者基因相關？","options":["(A) HLA-B5701","(B) HLA-B5801","(C) HLA-B27","(D) HLA-B46"],"answer":0,"image":""},{"id":"md3-108-2-61","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"有一位75歲男性病人，解尿時通常需要稍微用力才能解出來，且尿流較細，曾被泌尿科醫師診斷為前列腺肥大（benign prostatic hyperplasia or hypertrophy）。某日他因感冒與嘔吐服用藥物，結果突然發生無法排尿的情況，明明覺得膀胱很脹，但就是解不出來。請依前述情況回答下列3題。下列藥物何者最不可能造成此種情況？","options":["(A) codeine（一種opiate，用於止咳）","(B) diphenhydramine（一種抗組織胺[anti-histamine]）","(C) metoclopramide（一種胃腸蠕動促進劑[prokinetic]）","(D) pseudoephedrine（一種甲型腎上腺素受體促效劑[alpha-adrenergic agonist]）"],"answer":2,"image":""},{"id":"md3-108-2-62","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"上述病人嘗試去排尿後，立即使用超音波檢查膀胱，發現約有500 mL餘尿。當超音波探頭壓在下腹部時，可發現少量尿液不自主的從尿道口緩慢流出來。此種型態的尿失禁（urinary incontinence）稱為：","options":["(A) 功能性尿失禁（functional incontinence）","(B) 應力性尿失禁（stress incontinence）","(C) 溢流性尿失禁（overflow incontinence）","(D) 急迫性尿失禁（urge incontinence）"],"answer":2,"image":""},{"id":"md3-108-2-63","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"承上題，對於上述病人的處置，下列何者最可能有助益？","options":["(A) 使用甲型腎上腺素受體拮抗劑（alpha-adrenergic antagonist）","(B) 採用行為治療（behavioral therapy），如：骨盆腔底肌肉訓練","(C) 使用抗膽鹼劑（anticholinergic）","(D) 使用乙三型腎上腺素受體促效劑（beta 3-adrenergic agonist）"],"answer":0,"image":""},{"id":"md3-108-2-64","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"一位45歲男性清潔工，過去健康情形良好，無任何病史，因呼吸急促胸悶住院，chest X-ray發現兩側肺野有零散的毛玻璃病灶（ground-glass opacities），病人主訴前兩週去廢棄工廠打掃並清除雜物，一週前開始咳嗽、發燒、胸悶現象，住院後經支氣管鏡肺泡灌洗術（bronchoalveolar lavage）檢查發現有lymphocytosis現象，此病人最有可能的診斷為：","options":["(A) allergic bronchopulmonary aspergillosis","(B) eosinophilic pneumonia","(C) tuberculosis","(D) hypersensitivity pneumonitis"],"answer":3,"image":""},{"id":"md3-108-2-65","subject":"md3","topic":"內科-胸腔","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"承上題，此病人最佳的治療藥物為何？","options":["(A) 廣效型抗生素","(B) 抗黴菌藥物","(C) 類固醇","(D) 抗病毒藥物"],"answer":2,"image":""},{"id":"md3-108-2-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"周全性老年評估可以發現老年人之潛在性可治療的健康問題，使老年人獲得較好的健康照顧。下列何種狀況最不適合作周全性老年評估？","options":["(A) 疾病末期病人或有嚴重失智者","(B) 有多重疾病、服用多種藥物的老年人","(C) 日常生活活動功能不全的老年人，尤其在最近有惡化的情形者","(D) 最近多次住院，且原因未明確者"],"answer":0,"image":""},{"id":"md3-108-2-67","subject":"md3","topic":"內科-內分泌代謝","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"17歲女性病人由母親陪同就醫，母親發現病人最近半年瘦了10公斤，病人自覺容易口渴且排尿較為頻繁。理學檢查發現病人消瘦，血壓100/70 mmHg，其餘無特殊異常。如果只能安排一項檢查來診斷，下列何者最適當？","options":["(A) 尿蛋白與尿糖","(B) 指尖血糖測定","(C) 血清電解質","(D) 全血球計數（complete blood count）"],"answer":1,"image":""},{"id":"md3-108-2-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"某論文經搜尋Cochrane Library、MEDLINE等，取得多個類似研究資料，並合併分析後結果如下：長期使用抗血小板藥物比上安慰劑的隨機分配試驗，有1965位病人，使用每日劑量75 mg到325 mg的aspirin，平均追蹤1.3年。結果aspirin對於中風合併心肌梗塞或血管性事件有明顯下降（odds ratio (OR) 0.71, 95％ confidence interval (CI) 0.51 to 0.97）。依據實證醫學的原則，下列何者正確？","options":["(A) 這是一篇預後性的研究（prognostic study）","(B) 此類型的分析，個案對照研究（case control study）優於世代研究（cohort study）","(C) 此篇論文是屬於綜合分析的研究（meta-analysis）","(D) 此篇論文具有足夠的完成追蹤率（follow-up）"],"answer":2,"image":""},{"id":"md3-108-2-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"下列有關「新生兒先天性甲狀腺機能低下症篩檢」的敘述，何者錯誤？","options":["(A) 特異度比敏感度更重要","(B) 不會產生嚴重的副作用","(C) 偽陰性造成的結果，會影響病人的早期治療","(D) 偽陽性的機會高"],"answer":0,"image":""},{"id":"md3-108-2-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"何太太40歲育有一子，最近經常胸痛、盗汗、顫抖、同時會有呼吸困難，感覺自己快要窒息。症狀在約十分鐘內達到高峰，且發生時間不定，在睡眠時亦曾發生，在醫院做了很多檢查，都找不到器質性原因。最後在林醫師門診吃藥後慢慢獲得改善，林醫師的處方，最可能是那一種藥物？","options":["(A) isosorbide mononitrate","(B) propylthiouracil","(C) sertraline","(D) digoxin"],"answer":2,"image":""},{"id":"md3-108-2-71","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"78歲陳先生由親人陪同就診，主訴最近一週有尿失禁及倦怠無力。病人長期失眠，經常服用安眠藥。最近失眠加重，增加劑量仍未見效，而且血壓也上升。病人又自行購買高血壓藥物服用。身體檢查病人生命徵象穩定，意識清楚，行動正常且無局部神經異常症狀。對該病人的處置方式，下列何者最為適當？","options":["(A) 安排病人入住護理之家接受照顧","(B) 轉介精神神經專科檢查及調整安眠藥","(C) 作老人周全性評估","(D) 即刻安排病人住院治療"],"answer":2,"image":""},{"id":"md3-108-2-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"假設你收集100位肺癌病人及1000位年齡、性別及社會經濟狀況相似的非肺癌控制群為研究對象，100位肺癌病人有90位是有規律的吸菸者，1000位控制群有270位是規律的吸菸者，則吸菸得到肺癌的危險勝算比（odds ratio）是多少？","options":["(A) 4.1","(B) 24.33","(C) 300.0","(D) 3.33"],"answer":1,"image":""},{"id":"md3-108-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"癌症末期疼痛治療的原則，下列敘述何者錯誤？","options":["(A) 經口給藥是使用止痛藥的優先考慮途徑","(B) 以「疼痛時才給藥」的處方方式為原則","(C) 適時使用輔助藥物","(D) 使用正確的藥物品項及劑量，與正確的時間間隔，大多數的癌痛，可以得到緩解"],"answer":1,"image":""},{"id":"md3-108-2-74","subject":"md3","topic":"影像醫學","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"44歲女性有酗酒習慣，某日熬夜喝酒之後突然口語不清，吞嚥困難，因此被送到急診求治；患者未注射對比劑的電腦斷層掃描檢查如圖，最可能的診斷為何？","options":["(A) 小腦梗塞","(B) 小腦出血","(C) 腦幹梗塞","(D) 腦幹出血"],"answer":3,"image":"md3-108-2-74.jpeg"},{"id":"md3-108-2-75","subject":"md3","topic":"影像醫學","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"下圖為肝臟之超音波掃描圖，箭號所指處最不可能的病灶為：","options":["(A) 肝膿瘍","(B) 原發性肝細胞癌","(C) 單純性囊腫","(D) 轉移癌"],"answer":2,"image":"md3-108-2-75.jpeg"},{"id":"md3-108-2-76","subject":"md3","topic":"急診醫學","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"一位60歲男性病人因在診所發現有心搏過緩合併低血壓被轉診至醫院，若病史顯示病人可能有中毒或藥物過量，下列何者藥物最不可能有上述的症狀？","options":["(A) Organophosphates","(B) Carbamates","(C) Clonidine","(D) Antihistamines"],"answer":3,"image":""},{"id":"md3-108-2-77","subject":"md3","topic":"急診醫學","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"關於路易絲湖急性高山病（Lake Louise Acute Mountain Sickness）評估表內容的症狀及徵候，不包括下列何項？","options":["(A) 頭痛","(B) 噁心、嘔吐","(C) 腹瀉","(D) 失眠"],"answer":[2,3],"image":"","answer_note":"更正:第77題答Ｃ、Ｄ給分。"},{"id":"md3-108-2-78","subject":"md3","topic":"內科-心臟血管","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"65歲男性長期有高血壓，持續用藥控制中，幾天前門診醫師幫他換藥，這幾天就常感覺腹脹，而且有便秘現象，病人最可能用了下列何種藥？","options":["(A) Valsartan","(B) Renitec","(C) Labetalol","(D) Amlodipine"],"answer":3,"image":""},{"id":"md3-108-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"王醫師因為要出國旅遊，交代診所的病人如果只想要拿藥的話，可以按著以前的處方，由護士直接蓋上王醫師的章，就讓他們去拿藥，王醫師的做法對嗎？","options":["(A) 不對，違反親自診療的義務","(B) 為了方便病人無所謂","(C) 只要釋出處方箋就可以","(D) 王醫師如果有以電話問診就可以"],"answer":0,"image":""},{"id":"md3-108-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"一位68歲女性病患罹患肺癌末期，已經簽署DNR意願書。最近幾個月陸續有幾次呼吸道感染病史，經過抗生素治療後，都恢復得不錯。最近幾天病患開始出現發燒及頻尿的現象，急診診斷為泌尿道發炎，合併敗血症。於急診治療過程中，病患血壓開始不穩，尿量減少，有敗血性休克現象，隨後呼吸變得淺快，血氧下降。臨床上有氣管內管插管之必要性，但病患已經簽署DNR意願書，這時醫師是否應該為其插管，或進行抗生素及大量點滴輸液來進行治療？下列敘述何者最為正確？","options":["(A) 病患本次住院，係因為敗血性休克，屬於可治療之疾病，該疾病的病程進展也未必會死亡，因此不適用DNR的相關規定，醫師應該依據臨床需要，詢問病患以及家屬意見，必要時得進行插管，或進行抗生素及大量點滴輸液來進行治療","(B) 病患已經簽署了DNR，就應該尊重其意願，不論這次住院的疾病是否可治癒，也不論該病程是否一定會進展到死亡，都一律適用DNR相關規定，而不能為其插管，但可以考慮進行抗生素及大量點滴輸液來進行治療","(C) 病患已經簽署了DNR，就應該尊重其意願，醫師不僅不能為其插管，也不應該進行抗生素及大量點滴輸液來進行治療","(D) DNR簽署後，具有終身的效力，除非病患自己撤銷，否則相關急救的醫療行為，包括抗生素以及點滴治療等，應該早在其數個月前幾次的呼吸道感染時，就不應該給予"],"answer":0,"image":""},{"id":"md3-109-1-1","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"有關懷孕期間內科疾病的處理，下列敘述何者最為適當？","options":["(A) 子癲前症（preeclampsia）之特色是高血壓與蛋白尿，此類患者在懷孕過程中絕對禁用阿斯匹靈（aspirin），以避免生產時出血","(B) 孕婦於懷孕中、後期出現高血壓，為了減少蛋白尿的發生，在腎功能與鉀離子都正常時，應以選擇性的血管張力素受體阻斷劑（angiotensin receptor blocker），作為第一線高血壓治療用藥","(C) 瓣膜性心臟病患在懷孕過程中，心因性死亡的可能性以二尖瓣狹窄（mitral stenosis）患者為最高","(D) 妊娠糖尿病發生時，為了減少妊娠併發症，應積極以藥物控制孕婦血糖，其中，以DPP-IV抑制劑（dipeptidyl peptidase Ⅳinhibitor）最被建議為第一線藥物"],"answer":2,"image":""},{"id":"md3-109-1-2","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"下列有關譫妄（delirium）的敘述，何者最適當？","options":["(A) 老年人住院時譫妄的發生率，平均約為1.0～5.0 %","(B) 失智症（dementia）是譫妄最主要的前置因子（predisposing factor）","(C) 鴉片類藥物（opioids）或是抗膽鹼劑（anti-cholinergics）的使用，可有效幫助患者減少譫妄的發生","(D) 身體約束（physical restraint）及benzodiazepines注射，目前被建議用於譫妄的治療"],"answer":1,"image":""},{"id":"md3-109-1-3","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"下列口服降血糖藥，何種最可能引起維生素B缺乏？12","options":["(A) biguanides","(B) acarbose","(C) thiazolidinediones","(D) sulfonylureas"],"answer":0,"image":""},{"id":"md3-109-1-4","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"低血鈉的鑑別診斷，下列那一項最不適當？","options":["(A) 甲狀腺功能低下可能造成等容積型低血鈉症（euvolemic hyponatremia）","(B) 低容積（hypovolemia）會使血液中的加壓素（vasopressin）增加","(C) 心衰竭造成的高容積型低血鈉症（hypervolemic hyponatremia）其尿液中的鈉濃度通常大於20 mM","(D) 燒傷可能造成尿液中鈉濃度低於20 mM的低容積型低血鈉"],"answer":2,"image":""},{"id":"md3-109-1-5","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"以一群健康的80歲老人與一群健康的20歲年輕人相比，下列何者在老人組最不會下降？","options":["(A) 運動時可達到的最快心跳速率","(B) 動脈血氧分壓","(C) 腎絲球過濾率（glomerular filtration rate）","(D) 血中胰島素（insulin）濃度"],"answer":3,"image":""},{"id":"md3-109-1-6","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"下列有關主動脈瓣狹窄之敘述，何者錯誤？","options":["(A) 二瓣性主動脈瓣（bicuspid aortic valve）是一種最常見的先天性瓣膜異常，易導致主動瓣狹窄","(B) 因造成左心室血流輸出阻礙，疾病早期，左心室會擴大以代償輸出量之不足，但此時病人無明顯症狀","(C) 當病程進展到開始出現臨床心臟衰竭症狀時，若無妥善治療，平均病人存活時間僅剩2年以下","(D) 因器材技術進步，經導管主動脈置換術（TAVR），在外科開刀風險較高的病人族群的治療結果已與傳統瓣膜置換手術相近"],"answer":1,"image":""},{"id":"md3-109-1-7","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"下列何種狀況或藥物，最不可能出現心電圖QT延長的現象？","options":["(A) 蜘蛛網膜下出血（subarachnoid hemorrhage）","(B) 低血鈣症（hypocalcemia）","(C) 甲狀腺亢進（hyperthyroidism）","(D) amiodarone"],"answer":2,"image":""},{"id":"md3-109-1-8","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"一位40歲男性因疲倦及喘至門診求診。生命體徵血壓125/80 mmHg，心跳每分鐘85下且規律。室內空氣脈搏血氧飽和度(room air SpO）98%。身體診察有右心室頂起（right ventricle heave），並於左側第二肋間可觸及收2縮期顫抖（systolic thrill），且左側第二肋間可聽到收縮期心雜音。除此之外，也可聽到明顯且隨呼吸變化分裂第二心音（wide split second heart sound）。最可能之診斷為何？","options":["(A) 心房中隔缺損（atrial septal defect）","(B) 主動脈狹窄（aortic stenosis）","(C) 開放性動脈導管（patent ductus arteriosus）","(D) 肺動脈瓣狹窄（pulmonary stenosis）"],"answer":3,"image":""},{"id":"md3-109-1-9","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"一位55歲男性因胸悶與低血壓至急診求診。大約半小時前，病患在睡夢中突然因胸悶不適而驚醒。除此之外，病患也有頭暈無力與嘔吐數次。生命徵象顯示血壓78/40 mmHg，心跳每分鐘50次，呼吸每分鐘20次。肺部聽診無濕囉音（rales）。心電圖如下圖所示。胸部X光圖無縱隔腔擴大，無肺水腫情形。心臟超音波顯示左心室收縮功能正常，但右心室擴大。以下何者為最佳立即處置？","options":["(A) 立即置放主動脈氣球幫浦（intra-aortic balloon pump）","(B) 立即給與強心劑dobutamine","(C) 立即給與硝化甘油靜脈注射","(D) 立即給與快速輸液治療normal saline 500 mL"],"answer":3,"image":"md3-109-1-9.jpeg"},{"id":"md3-109-1-10","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"一位52歲在魚市場送貨的張先生，之前每週一到週六清晨5時載貨到某魚市場工作時，能扛10公斤為一箱的海鮮穿梭於市場約10來趟，勝任愉快。上週日參加喜宴，多喝了一些酒，第二天在同一魚市場進行相同工作時發覺走了5趟就覺得喘，需要休息10分鐘才能再搬貨。他原以為前一晚沒睡好，只要回家休息就可恢復，沒想到接下來3天皆是如此，因此前來醫院就醫。醫師的初步診斷為心衰竭。請問根據紐約心臟協會的功能分類（NYHA functional classification），應屬於：","options":["(A) 第一級","(B) 第二級","(C) 第三級","(D) 第四級"],"answer":1,"image":""},{"id":"md3-109-1-11","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"有關與血脂異常相關的黃色脂肪瘤（xanthoma）之敘述，下列何者錯誤？","options":["(A) 只有血液中低密度脂蛋白膽固醇（LDL cholesterol）過高時才會發生，與血液中甘油三脂（triglyceride）的濃度無關","(B) 常分布在皮下（subcutaneous）處","(C) 常分布在肌腱鞘（tendon sheath）處","(D) 常分布在身體四肢的伸肌表面（extensor surface）"],"answer":0,"image":""},{"id":"md3-109-1-12","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"有關心包膜疾病的敘述，下列何者錯誤？","options":["(A) 心包膜本身是一個雙層袋子，包括有visceral pericardium以及parietal pericardium兩層，之間由15～50毫升的心包膜液來分開","(B) 在急性心包膜發炎時，病患可能會出現有較為低頻（low-pitch）的friction rub的心音，在病患前傾，在呼氣末期時較容易聽到，隨著心包膜水量漸漸增加，有時會有心包膜填塞（cardiac tamponade）的表現，此時friction rub聲音反而會消失","(C) 在心電圖的表現上，早期較常看見廣泛性的ST節上升","(D) 在cardiac tamponade時有一個Beck’s triad：低血壓，心音聲音消失，頸靜脈怒張有明顯的X descent以及消失的Y descent"],"answer":1,"image":""},{"id":"md3-109-1-13","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"關於C型肝炎的自然病史，下列何者錯誤？","options":["(A) 慢性C型肝炎經過20～30年後，約有20～25%的帶原者會發展成肝硬化","(B) 肝硬化患者每年有1～4%罹患肝細胞癌","(C) 慢性C型肝炎是西方國家肝臟移植最主要的適應症之一","(D) 女性、酗酒、以及30歲以上的感染是慢性C型肝炎快速進展之重要因素"],"answer":3,"image":""},{"id":"md3-109-1-14","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"下列那一位病人的膽囊結石需治療，而且以使用口服膽鹽溶石劑（ursodeoxycholic acid, UDCA）來治療較合適？","options":["(A) 28歲婦女，有單顆1.0公分大小的膽結石在膽囊內；未曾有過症狀","(B) 72歲男人，已有數次右上腹疼痛，合併噁心嘔吐，胸部X光顯示右上腹膽囊部位有鈣化點；超音波顯示有3個膽結石，各為0.5公分大小","(C) 60歲婦女，右上腹疼痛已12小時，併有噁心嘔吐，體溫38°C，超音波顯示有3顆膽結石，直徑為1～2公分，膽囊壁厚，而膽囊周圍有液體滯留","(D) 70歲婦女，已有數次劇烈上腹痛，每次持續1～2小時，常於大餐之後發生，於2個月前才發作1次急性心肌梗塞。腹部X光看不到異常處，超音波顯示有1顆直徑大小0.4公分的膽結石"],"answer":3,"image":""},{"id":"md3-109-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"以下關於痙攣（spasm）of the sphincter of Oddi的敘述何者錯誤？","options":["(A) 偶而會有AST，ALT或alkaline phosphatase升高現象","(B) 常有右上腹或上腹疼痛，類似膽結石之症狀","(C) sphincter of the Oddi manometry有助於診斷","(D) 對於疼痛嚴重的病人，morphine是最適當的止痛劑"],"answer":3,"image":""},{"id":"md3-109-1-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"有關B型肝炎病毒的基因型敘述，下列何者錯誤？","options":["(A) 至少已有8個亞型（subtypes）及10種基因型（A–J）","(B) 基本上感染後的臨床病程嚴重度與病毒亞型有關","(C) 基因型B相較於基因型C、D，有較低的肝硬化及肝癌的風險","(D) 基因型A不管有無接受抗病毒藥物治療，相對其他基因型，有較高機會產生表面抗原（HBsAg）消失或是e抗原（HBeAg）消失"],"answer":1,"image":""},{"id":"md3-109-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"有關急性B型肝炎的敘述，下列何者錯誤？","options":["(A) nucleoside analogue或nucleotide analogue治療可以用於重症患者","(B) nucleoside analogue或nucleotide analogue治療可以縮短疾病病程","(C) 若需使用nucleoside analogue或nucleotide analogue治療，建議使用到HBsAg seroconversion後3個月，或是HBeAg seroconversion後6個月","(D) 約99%病患不會成為慢性帶原"],"answer":[1,3],"image":"","answer_note":"更正:第17題答Ｂ、Ｄ給分。"},{"id":"md3-109-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"關於肝硬化所導致的食道靜脈曲張（esophageal varices），以下敘述何者正確？","options":["(A) 非選擇性的beta阻斷劑（nonselective β-blockers），如propranolol或nadolol，可以降低第一次靜脈曲張出血的機率","(B) 內視鏡靜脈曲張結紮（endoscopic variceal ligation），對於預防第一次靜脈曲張出血的效果並不好","(C) 內視鏡靜脈曲張結紮，因可以降低肝門靜脈壓力，所以可以用來治療靜脈曲張出血","(D) 靜脈曲張出血的病人，最好能輸血將血紅素維持在10 g/dL以上"],"answer":0,"image":""},{"id":"md3-109-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"下列關於大腸直腸癌治療之敘述，何者正確？","options":["(A) 第二期或第三期的直腸癌，可以在術前施行CCRT（concurrent chemoradiotherapy）減少復發機會並促進治癒率","(B) 肛門癌的危險因子與大腸直腸癌相類似","(C) K-ras基因突變者，對於標靶藥物cetuximab會有比較好的反應","(D) 儘管手術完整切除腫瘤，縫合處復發（anastomotic recurrences）為大腸直腸癌術後最常見的復發部位，因此大腸鏡是最重要的追蹤檢查"],"answer":0,"image":""},{"id":"md3-109-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"關於inflammatory bowel disease的藥物治療，下列何者正確？","options":["(A) sulfasalazine可分解為sulfapyridine（anti-inflammatory effect）及5-aminosalicylic acid（ASA）（antibacterial effect）之成分，為臨床相當常用的口服藥物","(B) 在inflammatory bowel disease急性症狀控制之後，glucocorticoids的使用在疾病的maintenance therapy中為首選","(C) anti-TNF therapy可結合血液中TNF-alpha，而降低腸道發炎性反應，為moderately to severely active ulcerative colitis的重要治療；在慢性B型肝炎的患者，anti-TNF therapy並沒有產生reactivation of hepatitis B virus的風險","(D) 在急性發作時，bowel rest加上total parenteral nutrition（TPN）也具有inducing remission of active Crohn's disease的效果，其效果甚至與glucocorticoids相當"],"answer":3,"image":""},{"id":"md3-109-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"關於Helicobacter pylori的藥物治療，下列何者正確？","options":["(A) 若消化性潰瘍已經由proton pump inhibitor治療痊癒，其Helicobacter pylori就無需治療，因為不會影響潰瘍的復發率","(B) 在早期胃癌的病患，病灶雖然已切除，Helicobacter pylori仍需治療，因為會降低metachronous胃癌的復發率","(C) 除菌藥物包括amoxicillin、metronidazole、tetracycline、clarithromycin、bismuth compounds等，在抗生素除菌治療的期間，proton pump inhibitor是否給與並無影響抗生素的除菌效果","(D) 除菌治療後慣例要在7天內執行urea breath test來確認除菌成功"],"answer":1,"image":""},{"id":"md3-109-1-22","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"40歲男性有高血壓、慢性腎病，有時精神倦怠，血中肌酸酐（creatinine）6.5 mg/dL、血色素11.6 g/dL、鐵素（ferritin）105 ng/mL、維生素B 150 pg/mL、葉酸（folate）1.2 ng/mL。對此病人，使用下列何者治療最不12適當？","options":["(A) 紅血球生長素","(B) 鐵劑","(C) 維生素B 12","(D) 葉酸"],"answer":0,"image":""},{"id":"md3-109-1-23","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"52歲女性，全身倦怠、食慾不振，血中肌酸酐（creatinine）11.2 mg/dL，決定接受腎臟替代療法，目前下列何種治療有最差之5年存活率？","options":["(A) HLA相符腎臟移植","(B) HLA不相符腎臟移植","(C) ABO血型不相符腎臟移植","(D) 血液透析"],"answer":3,"image":""},{"id":"md3-109-1-24","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"45歲女性病人，接受腹膜透析，3天前腹痛，1天前透析液變混濁，今天至急診，透析液中的白血球356/μL，用抗生素治療3天後，透析液培養長出念珠菌（candidiasis）。下列何種處置最為適當？","options":["(A) 使用口服抗黴菌藥物","(B) 使用靜脈注射抗黴菌藥物","(C) 使用腹腔灌注抗黴菌藥物","(D) 拔除腹膜透析導管"],"answer":3,"image":""},{"id":"md3-109-1-25","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"下列有關postobstructive diuresis的敘述，何者錯誤？","options":["(A) 發生在雙側或單側尿路完全阻塞，經過成功疏通的病人","(B) 尿液為低張含大量鹽分，可能導致高血鈉","(C) 致病機轉為排泄先前滯留體內的尿素，產生滲透壓利尿（osmotic diuresis）","(D) 靜脈輸液治療不宜補充＞每日尿液流失量，以免發生醫源性體液容積增加"],"answer":0,"image":""},{"id":"md3-109-1-26","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"一位28歲女性，這兩年來有頭暈及容易疲倦的症狀，且越來越嚴重而住院治療。入院前八個月，因症狀持續加重，於某醫學中心發現血色素9 g/dL，血球容積92.5 fL，白血球及血小板數目正常，當時肌酸酐為1.3 mg/dL。住院後血壓140/90 mmHg，脈搏76/分鐘，心臟無雜音，下肢輕微水腫，實驗室檢查發現肌酸酐增至2.4 mg/dL，血色素8.5 g/dL，血清儲鐵蛋白（ferritin）591 ng/mL，鐵172 μg/dL，鐵結合總容量為190 μg/dL，大便潛血反應為陰性，尿液檢查無異常，下列何者為此病人腎功能惡化最可能之病變？","options":["(A) rapidly progressive glomerulonephritis","(B) thrombotic microaniopathy","(C) chronic tubulointerstitial disorders","(D) hypertensive nephrosclerosis"],"answer":2,"image":""},{"id":"md3-109-1-27","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"有關慢性腎臟病的治療，下列何者正確？","options":["(A) 若患者合併高血壓，其降血壓藥物首選為乙型阻斷劑（β-blocker）","(B) 若患者合併退化關節炎，可使用非類固醇類抗發炎藥物（NSAID）來止痛","(C) 患有重度蛋白尿之糖尿病慢性腎臟病患，最好合併使用血管張力素轉化酶抑制劑（ACEi）和血管張力素II型受體拮抗劑（ARB）來治療","(D) 患有蛋白尿之第4期慢性腎臟病患者，應採用低蛋白飲食療法"],"answer":3,"image":""},{"id":"md3-109-1-28","subject":"md3","topic":"內科-腎臟","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"有關慢性腎臟病-礦物質骨病變（chronic kidney disease-mineral bone disorder）的鈣磷異常，下列敘述何者錯誤？","options":["(A) 腎絲球過濾率下降會使尿磷排出減少，進而促進副甲狀腺素（PTH）和纖維母細胞生長因子23（fibroblast growth factor 23, FGF-23）生成","(B) 纖維母細胞生長因子23（FGF-23）增加，會抑制活性維他命D3生成，促進低血鈣","(C) 纖維母細胞生長因子23（FGF-23）會刺激副甲狀腺素生成","(D) 血清纖維母細胞生長因子23（FGF-23）值過高，與慢性腎臟病病患的死亡率有正相關"],"answer":2,"image":""},{"id":"md3-109-1-29","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"關於退化性關節炎（osteoarthritis）的敘述，下列何者錯誤？","options":["(A) 是一種常見的關節炎，好發於年紀較大的病人","(B) 好發的關節包括手部的distal interphalangeal（DIP）joints、hip joints及knee joints","(C) 關節的X ray檢查常會發現narrowed joint space，但通常不會有bone erosion的情形","(D) 因為關節有發炎，因此病人血中的CRP和ESR值常會有上升的情形"],"answer":3,"image":""},{"id":"md3-109-1-30","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"針對乾燥症（Sjögren's syndrome）合併腺體外表現（extraglandular manifestations）的治療，下列何者正確？","options":["(A) 若併發關節炎通常使用抗腫瘤壞死因子（anti-TNF）治療","(B) 若併發血管炎可使用類固醇與免疫抑制劑治療","(C) 若併發淋巴癌使用高劑量類固醇治療即可","(D) 若併發雷諾氏症要使用非類固醇類消炎止痛藥治療"],"answer":1,"image":""},{"id":"md3-109-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"有關僵直性脊椎炎（ankylosing spondylitis），下列敘述何者正確？","options":["(A) HLA-B27陰性就不是僵直性脊椎炎","(B) 結膜炎是僵直性脊椎炎常見的眼睛表現","(C) 僵直性脊椎炎病人大多數是HLA-B27陽性","(D) 僵直性脊椎炎病人女性比較多"],"answer":2,"image":""},{"id":"md3-109-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"王太太某日在果園工作時被一隻蜜蜂叮咬，約10幾分鐘後，出現全身蕁麻疹（urticaria），接著呼吸困難，家人連忙將她送到急診室求診。抵達急診室時血壓為88/54 mmHg，心跳110 BPM。對王太太目前的狀況，應以下列何項優先給藥？","options":["(A) methylprednisolone 60 mg靜脈注射","(B) diphenhydramine 50～100 mg靜脈注射","(C) albuterol 5 mg吸入","(D) epinephrine 0.5 mg肌肉注射"],"answer":3,"image":""},{"id":"md3-109-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"60歲何女士有高血壓10年，每日服用losartan 50 mg與hydrochlorothiazide 12.5 mg，血壓一直控制在理想範圍。2個月前因為肺結核開始服用四合一抗結核藥物，一週前何女士開始出現發燒及手部多發性小關節腫痛現象，抽血檢驗發現抗核抗體（ANA）1：1280陽性，anti-histone antibody陽性，但anti-dsDNA antibodies為陰性。下列處置何者最為適當？","options":["(A) 停掉losartan","(B) 停掉isoniazid","(C) 停掉hydrochlorothiazide","(D) 原有用藥都不停，加上prednisolone 0.5 mg/kg/day"],"answer":1,"image":""},{"id":"md3-109-1-34","subject":"md3","topic":"內科-腫瘤","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"以下有關hereditary nonpolyposis colon cancer（HNPCC；或稱Lynch's syndrome）常見的臨床病理及基因分子變異，何者錯誤？","options":["(A) HNPCC大腸直腸癌患者診斷的中位年齡，較其他一般民眾大腸直腸癌診斷的中位年齡來得較年長","(B) HNPCC患者的家屬也好發卵巢癌、子宮內膜癌或其他的腸胃道癌症","(C) HNPCC與germline mutations of hMSH2或hMLH1相關","(D) hMSH2或hMLH1之基因變異將導致細胞內DNA mismatch repair機制的缺損"],"answer":0,"image":""},{"id":"md3-109-1-35","subject":"md3","topic":"內科-腫瘤","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"下列關於頭頸癌的敘述何者錯誤？","options":["(A) 在西方國家，人類乳突病毒（human papilloma virus）與口咽部（oropharynx）頭頸癌的發生率增加有關","(B) 人類乳突病毒相關的頭頸癌與人類乳突病毒不相關的頭頸癌比較，預後較差","(C) 早期頭頸癌治療後，有可能在頭頸其他部位、肺部、食道出現第二原發（second primary）癌症","(D) 晚期頭頸癌有效的藥物治療，包括化學治療、標靶治療"],"answer":1,"image":""},{"id":"md3-109-1-36","subject":"md3","topic":"內科-腫瘤","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"下列腫瘤指數與其適用腫瘤種類的配對，何者錯誤？","options":["(A) 攝護腺癌：prostate specific antigen（PSA）","(B) 攝護腺癌：lactate dehydrogenase（LDH）","(C) 睪丸癌：alpha-fetoprotein（AFP）","(D) 睪丸癌：human chorionic gonadotropin（hCG）"],"answer":1,"image":""},{"id":"md3-109-1-37","subject":"md3","topic":"內科-血液","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"一位75歲女性，平常健康狀況良好，但是近三個月感到食慾不振，疲乏無力，下背疼痛。理學檢查呈現臉色與結膜蒼白，無肝脾腫大。實驗室數據顯示：白血球5,310/μL，分類無異常。血紅素7.8 g/dL，血小板171,000/μL。肝功能正常，serum creatinine是3.4 mg/dL。腰部脊椎之影像檢查呈現嚴重塌陷。其骨髓抹片顯示如下圖。以下關於這位病人最可能的疾病之診斷與治療，何者錯誤？","options":["(A) 此疾病好發於老人","(B) 診斷之後，立即給與高劑量的靜脈輸注化學治療是目前標準的治療方法","(C) 即使血液中測量不到monoclonal protein，也不能排除此病","(D) lenalidomide、steroid與bortezomib是治療此病的有效處方"],"answer":1,"image":"md3-109-1-37.jpeg"},{"id":"md3-109-1-38","subject":"md3","topic":"內科-血液","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"一位30歲女性，過去健康狀況良好，並無重大疾病。她在3個月前剖腹產下一個健康男嬰。懷孕及生產過程也很順利。但生產後，她卻發現即使沒有碰撞，也常有皮膚大片瘀青，有時甚至會有皮下血腫。病人否認有任何藥物的服用或是毒物的曝露。血液數據顯示，白血球9,600/μL，血紅素10.7 g/dL，血小板210,000/μL，白血球分類無異常。PT 10.3 sec（INR 0.95），aPTT 98 sec，以normal plasma做mixing test無法完全矯正延長的aPTT。factor VIIIc的活性小於1%，而factor VIII antibody是28.41 BU/mL（參考值＜0.6）。以下關於這位病人最可能的疾病之診斷與治療，何者錯誤？","options":["(A) 此類病人常常有hemarthrosis","(B) 除了懷孕生產之外，此病亦可能與惡性腫瘤與自體免疫疾病有關連性，但是約有一半的病人找不到明顯的原因","(C) 嚴重出血危及生命時，可以輸注PCC（prothrombin complex concentrate）或是recombinant factor VIIa來止血","(D) 治療有反應者，在停藥之後，還是可能有高達約20%的病人在半年內復發"],"answer":0,"image":""},{"id":"md3-109-1-39","subject":"md3","topic":"內科-血液","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"79歲女性，自訴以往健康良好，沒有服用任何藥物或營養品，某天早上起床時發現全身四肢有多處瘀青。隔日就診，身體檢查發現口腔裡有多處潰瘍和血塊。血球檢查數據如下（括弧內是正常參考數值）：RBC 5.02 M/μL（3.78～4.99），Hb 11.1 g/dL（10.8～14.9），Hct 34.6 %（35.6～45.4），MCV 68.9 fL（80～100），PLT 5 K/μL（150～361），WBC 10.14 K/μL（3.54～9.06），白血球分類：Seg 58.1%，Eos. 1.0%，Baso. 0.4%，Mono. 4.1%，Lym. 36.4%。以下何項敘述錯誤？","options":["(A) 病人應考慮接受骨髓檢查協助診斷","(B) 病人有可能是假性的血小板低下症，需要用含肝素（heparin）的採血管採集病人的血液之後，再做一次檢查","(C) 病人應該立即輸注血小板濃縮液","(D) 病人應避免劇烈活動"],"answer":1,"image":""},{"id":"md3-109-1-40","subject":"md3","topic":"內科-血液","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"24歲女性，於員工健檢的血球檢查數據如下（括弧內是正常參考數值）：RBC 4.08 M/μL（3.78～4.99），Hb 12.0 g/dL（10.8～14.9），Hct 37.2%（35.6～45.4），MCV 91.2 fL（80～100），MCH 29.4 pg（26～34），MCHC 32.3 g/dL（31～37），PLT 606 k/μL（150～361），WBC 171.25 k/μL（3.54～9.06），血球分類：Blast 0.5%，Promye l. 5.8%，Myelo. 14.8%，Meta 17.0%，Band 12.0%，Seg 37.9%，Eos. 1.0%，Baso. 3.5%，Mono. 4.0%，Lym. 3.5%。為了確立診斷，下列那一項檢查較不需要？","options":["(A) 骨髓細胞染色體分析","(B) 周邊血BCR/ABL1基因定性檢定","(C) 白血球LAP score","(D) 周邊血球免疫分型檢查（immunophenotyping）"],"answer":3,"image":""},{"id":"md3-109-1-41","subject":"md3","topic":"內科-腫瘤","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"以下那個遺傳基因變異導致卵巢癌發生的風險最高？","options":["(A) BRCA1","(B) BRCA2","(C) MSH2","(D) CHK2"],"answer":0,"image":""},{"id":"md3-109-1-42","subject":"md3","topic":"內科-腫瘤","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"以下何者不是子宮內膜癌（endometrial carcinoma）的危險因子？","options":["(A) 肥胖","(B) 使用tamoxifen治療乳癌","(C) 單獨使用estrogen來治療停經後症候群","(D) 使用progestin治療不孕症"],"answer":3,"image":""},{"id":"md3-109-1-43","subject":"md3","topic":"內科-胸腔","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"有關慢性阻塞性肺病（chronic obstructive pulmonary disease）之敘述，下列何者錯誤？","options":["(A) 主要造成因素包括抽菸、空氣污染或基因缺陷所導致","(B) 發炎細胞主要為嗜中性白血球（neutrophils）及巨噬細胞（macrophages），並無T lymphocytes或eosinophils參與","(C) 臨床症狀及肺功能表現與慢性氣喘有時不易區分","(D) 臨床治療以支氣管擴張劑為主，部分特定病患也可以使用吸入型類固醇"],"answer":1,"image":""},{"id":"md3-109-1-44","subject":"md3","topic":"內科-胸腔","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"下列何者為成人常見的前縱膈腔腫瘤？","options":["(A) 食道腫瘤（esophageal tumor）","(B) 神經性腫瘤（neurogenic tumor）","(C) 胸腺瘤（thymoma）","(D) 支氣管囊腫（bronchogenic cyst）"],"answer":2,"image":""},{"id":"md3-109-1-45","subject":"md3","topic":"內科-胸腔","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"關於間皮瘤（mesothelioma）的敘述，下列何者正確？","options":["(A) peritoneal mesothelioma比pleural mesothelioma較常見","(B) pleural fluid或ascites之cytology，通常就足以診斷","(C) 預後良好，中位數存活期（median overall survival）為3年","(D) 少部分的間皮瘤（mesothelioma）為良性"],"answer":3,"image":""},{"id":"md3-109-1-46","subject":"md3","topic":"影像醫學","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"要診斷肺尖（lung apices）上的病灶，下列何種X光片的照法，最為適當？","options":["(A) PA view","(B) lateral view","(C) lateral decubitus view","(D) lordotic view"],"answer":3,"image":""},{"id":"md3-109-1-47","subject":"md3","topic":"內科-胸腔","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"70歲男性抽菸近50年，有多年長期咳嗽及運動時呼吸困難症狀，近日咳嗽及呼吸困難加劇前往急診處就醫。身體診查發現病人意識清楚，血壓穩定，但呼吸快速及胸部聽診有呼氣喘鳴聲（wheezes）。胸部X光片沒有肺炎之現象，痰液不多，其呼吸空氣時動脈血液氣體分析顯示pH 7.274，pCO78 mmHg，pO40 mmHg，2 2 - 36 mEq/L HCO，BE(ECF) +9 mEq/L。給予氧氣後，下列何種處理最為正確？3","options":["(A) 給予重碳酸鈉輸液來改善酸血症","(B) 迅速給予氣管內插管及使用呼吸器以改善pCO至40 mmHg 2","(C) 給予茶鹼（aminophylline）靜脈注射治療","(D) 先給予支氣管擴張劑吸入治療，並考慮使用非侵襲性呼吸器治療"],"answer":3,"image":""},{"id":"md3-109-1-48","subject":"md3","topic":"內科-感染","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"下列何種菌株的藥物敏感性試驗結果，符合多重抗藥性結核病（multidrug-resistant tuberculosis）的定義？","options":["(A) isoniazid及streptomycin抗藥，但rifampin及ethambutol敏感","(B) isoniazid, ethambutol及streptomycin抗藥，但rifampin敏感","(C) isoniazid及rifampin抗藥，但ethambutol及streptomycin敏感","(D) rifampin, ethambutol及streptomycin抗藥，但isoniazid敏感"],"answer":2,"image":""},{"id":"md3-109-1-49","subject":"md3","topic":"內科-感染","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"關於呼吸器相關肺炎（ventilator-associated pneumonia），下列敘述何者最不適當？","options":["(A) 住院後5到7天內發生的呼吸器相關肺炎，致病菌可能不是多重抗藥菌，而是如肺炎鏈球菌（Streptococcus pneumoniae）或嗜血桿菌（Haemophilus influenzae）等","(B) 住院7天後發生的呼吸器相關肺炎，致病菌較可能為多重抗藥菌，如綠膿桿菌（Pseudomonas aeruginosa）或鮑氏不動桿菌（Acinetobacter baumannii）等","(C) 氣管內管插管雖可避免大量的分泌物吸入，但無法避免微量吸入（microaspiration）","(D) 為避免呼吸器相關肺炎，必須將病人頭部抬高至少60度，以避免產生吸入性肺炎"],"answer":3,"image":""},{"id":"md3-109-1-50","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"有關甲狀腺荷爾蒙對於人體代謝及發育的敘述，下列何者錯誤？","options":["(A) 在幼年期缺少甲狀腺荷爾蒙，會造成智力不足、身材矮小且終身不可逆的呆小症（cretinism）","(B) 甲狀腺荷爾蒙可以降低細胞對氧氣的消耗，並且降低脂肪和碳水醣類化合物的代謝平衡，以提供正常生長和發育的需求","(C) 若甲狀腺荷爾蒙過度分泌，會造成身體消瘦、情緒緊張焦慮、心跳加速、雙手顫抖，有時甚至會造成心臟衰竭","(D) 甲狀腺荷爾蒙是維持生命所不可或缺的，一旦缺乏會造成人體對寒冷的耐受性降低，體重異常增加、身體黏液性腫（myxedema）、神智和身體活動變得笨拙和遲鈍"],"answer":1,"image":""},{"id":"md3-109-1-51","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"有關糖尿病慢性併發症的敘述，下列何者錯誤？","options":["(A) 糖尿病慢性併發症的發生與糖尿病的罹病期及血糖控制有關","(B) 病人最好能定期接受糖尿病慢性併發症的篩檢","(C) 病人可能有腹瀉或便秘的現象","(D) 糖尿病的腎臟病變在早期就會有肌酸酐上升的現象"],"answer":3,"image":""},{"id":"md3-109-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"有關代謝症候群（metabolic syndrome）的敘述，下列何者錯誤？","options":["(A) 與肥胖及年齡有關，胰島素阻抗為可能的病理成因","(B) 病人可能會有血壓或血糖的升高","(C) 有代謝症候群的人罹患心臟血管疾病的風險會上升","(D) 診斷的條件包括高三酸甘油脂血症及低密度脂蛋白膽固醇升高"],"answer":3,"image":""},{"id":"md3-109-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"關於減重手術（bariatric surgery），下列敘述何者錯誤？","options":["(A) 對新陳代謝的好處，部分是因為改變了腸道荷爾蒙分泌濃度所致","(B) 通常在限制型（restrictive）手術之外，再合併吸收不良型（malabsorptive）手術，可增加減重效果","(C) 可用來改善重度肥胖之第二型糖尿病病人的血糖控制","(D) 無法降低重度肥胖病人的死亡率"],"answer":3,"image":""},{"id":"md3-109-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"下列何種降血糖藥物，最容易發生低血糖的副作用？","options":["(A) dipeptidyl peptidase-4（DPP-4）抑制劑","(B) sodium-glucose co-transporter 2（SGLT2）抑制劑","(C) meglitinide","(D) glucagon-like peptide 1（GLP-1）受體促進劑"],"answer":2,"image":""},{"id":"md3-109-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"下列何者是術前診斷甲狀腺瘤良惡性最準確的方式？","options":["(A) 甲狀腺細針穿刺細胞學檢查","(B) 甲狀腺超音波","(C) 頸部電腦斷層","(D) 頸部核磁共振"],"answer":0,"image":""},{"id":"md3-109-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"一位50歲男性患者，未服用任何藥物和保健食品，主訴體重上升，有月亮臉、水牛肩、中心型肥胖、皮膚薄、易瘀青，下列處置何者最不適當？","options":["(A) 隨機測量血中ACTH和cortisol","(B) 抽血測量上午8點與下午4點的ACTH和cortisol","(C) 測量24小時尿液的cortisol量","(D) 做1 mg dexamethasone suppression test"],"answer":0,"image":""},{"id":"md3-109-1-57","subject":"md3","topic":"內科-感染","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"下列那一項處置最不會增加住院病人醫療照護相關感染肺炎（healthcare-associated pneumonia）的風險？","options":["(A) 儘量讓病人平躺以維持住院的舒適度","(B) 給與麻醉藥物（narcotics）全天止痛","(C) 為方便抽痰延長使用氣管內插管（endotracheal intubation）","(D) 使用口服sucralfate藥物治療胃炎"],"answer":3,"image":""},{"id":"md3-109-1-58","subject":"md3","topic":"內科-感染","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"下列有關皰疹相關病毒的敘述，何者正確？","options":["(A) 免疫正常的人發生過皮膚性帶狀皰疹（herpes zoster），大於10%會反覆發作","(B) 未曾施打水痘（chickenpox）疫苗且未曾感染過水痘者，在接觸水痘病人後有小於40%會被感染","(C) 感染性單核細胞增多症（infectious mononucleosis）的最常見症狀是發燒、喉嚨痛、淋巴結腫大","(D) 在年輕人，感染性單核細胞增多症的潛伏期為5〜10天"],"answer":2,"image":""},{"id":"md3-109-1-59","subject":"md3","topic":"內科-感染","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"根據美國疾病管制署對人類免疫不全病毒（HIV）感染及相關機遇性感染與腫瘤的分類，下列何種惡性腫瘤不是後天免疫不全症候群相關疾病（AIDS-defining conditions）？","options":["(A) Hodgkin's lymphoma","(B) Kaposi's sarcoma","(C) Burkitt's lymphoma","(D) invasive cervical carcinoma"],"answer":0,"image":""},{"id":"md3-109-1-60","subject":"md3","topic":"內科-感染","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"人類免疫不全病毒（HIV）感染的孕婦服用合併抗反轉錄病毒治療，若偵測不到血漿HIV病毒量（＜20 copies/mL），則生下嬰兒感染HIV機會大約多少？","options":["(A) 25%","(B) 15%","(C) 7%","(D) ＜1%"],"answer":3,"image":""},{"id":"md3-109-1-61","subject":"md3","topic":"內科-感染","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"39歲男性過去身體健康良好，因一週來發燒和持續性的頭痛到院就醫。身體診察檢查發現體溫39.0℃，口腔上顎有白斑，頸部並沒有僵硬。血液檢查發現白血球數7020/μL。電腦斷層僅顯示腦部水腫。脊椎穿刺（lumbar puncture）發現壓力>600 mmHO，生化檢查發現蛋白質94 mg/dL，顯微鏡檢如圖示。下列敘述何者2最不適當？","options":["(A) 應進行愛滋病毒感染檢驗","(B) 最有可能的病原是Cryptococcus neoformans","(C) 目前標準的治療藥物組合是amphotericin B＋flucytosine","(D) 治療療程完成4週即可停止治療"],"answer":3,"image":"md3-109-1-61.jpeg"},{"id":"md3-109-1-62","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"一位74歲男性有高血壓病史，因喘、下肢水腫住院，住院檢查發現左心室功能正常，也無心律不整，給予利尿劑與抗高血壓藥物治療，數日後卻出現反覆不省人事，無脈搏、無血壓，需電擊治療，心電圖監測紀錄如下所示，最可能合併何種電解質異常？","options":["(A) 低血鈉症（hyponatremia）","(B) 高血鉀症（hyperkalemia）","(C) 高血鈣症（hypercalcemia）","(D) 低血鉀症（hypokalemia）"],"answer":3,"image":"md3-109-1-62.jpeg"},{"id":"md3-109-1-63","subject":"md3","topic":"內科-心臟血管","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"承上題，當給予1～2 g硫化鎂（magnesium sulfate）滴注後仍出現反覆不省人事與上述心電圖時，下列處置何者最適當？","options":["(A) amiodarone 150 mg滴注IVF","(B) lidocaine 50 mg靜注IV","(C) isoproterenol滴注IVF加速心跳至100～120次/分","(D) 暫時性節律器心跳維持70次/分"],"answer":2,"image":""},{"id":"md3-109-1-64","subject":"md3","topic":"內科-感染","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"54歲男性有糖尿病史多年，至泰國旅遊一個月，3天前返臺，因發燒及咳嗽有痰2天至急診就診。胸部X光發現右上肺有大片的實質浸潤（consolidation），腹部電腦斷層發現有脾臟膿瘍，痰液及由脾臟引流的膿瘍經革蘭氏染色檢查發現有細胞內革蘭氏陰性桿菌，下列何者為這位病人最可能的致病菌？","options":["(A) Pseudomonas aeruginosa","(B) Haemophilus influenzae","(C) Burkholderia pseudomallei","(D) Escherichia coli"],"answer":2,"image":""},{"id":"md3-109-1-65","subject":"md3","topic":"內科-感染","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"承上題，下列何種抗生素治療對這位病人最為恰當？","options":["(A) amikacin","(B) ceftazidime","(C) ciprofloxacin","(D) cefazolin"],"answer":1,"image":""},{"id":"md3-109-1-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"關於生理心理社會模式（biopsychosocial models）的敘述，下列何者正確？","options":["(A) 生理層面包含影響生理功能之環境因素","(B) 心理層面包含基因及疾病史","(C) 社會層面包含情感及意志","(D) 社會層面包含人格特質及應對方式（coping style）"],"answer":0,"image":""},{"id":"md3-109-1-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"有關周全性評估老人功能的量表與目的，下列敘述何者錯誤？","options":["(A) 日常生活活動功能（basic activities of daily living, ADLs）使用巴氏生活量表（Barthel's index）評估個人日常生活的自我照顧能力","(B) 工具性日常生活活動功能（instrumental activities of daily living, IADLs）評估個人於社區獨立生活的能力","(C) 簡式智能評估量表（mini-mental status examination, MMSE）篩檢智商與溝通能力","(D) 老年憂鬱量表（geriatric depression scale, GDS）篩檢及評估憂鬱狀況"],"answer":2,"image":""},{"id":"md3-109-1-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"17歲男生因感冒至家庭醫學科診所就醫，依據美國預防醫學工作小組（US Preventive Services Task Force）的建議，下列何者是屬於家庭醫師須透過密集諮詢（intensive counseling）而非經由簡短諮詢（brief counseling）的項目？","options":["(A) 避免酗酒（alcohol misuse）","(B) 預防皮膚癌（skin cancer）","(C) 預防菸品使用（tobacco use）","(D) 性接觸傳染病（sexually transmitted infection）"],"answer":3,"image":""},{"id":"md3-109-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"有關旅行者腹瀉（traveler's diarrhea）的敘述，下列何者最正確？","options":["(A) 最常造成旅行者腹瀉的病原體是Salmonella","(B) 去東南亞國家旅遊發生腹瀉時，治療首選藥物為ciprofloxacin","(C) azithromycin是治療的選擇之一，但孕婦不能使用","(D) bismuth subsalicylate是預防的選擇，但小孩不建議使用"],"answer":3,"image":""},{"id":"md3-109-1-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"Smilkstein於1978年提出家庭功能評估的APGAR評估量表，其中APGAR各自代表：Adaptation、Partnership、Growth、Affection、Resolve。這個評估量表最主要來自於何種概念模式？","options":["(A) Biopsychosocial model","(B) Systems approach","(C) Stress and coping model","(D) Life span perspective"],"answer":1,"image":""},{"id":"md3-109-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"家庭醫師欲規劃社區登革熱介入措施，依社區導向基層醫療（community-oriented primary care）循環的順序，下列何者正確？","options":["(A) 確認問題→確認群體→策略規劃→介入實施→評估成效","(B) 確認群體→確認問題→策略規劃→介入實施→評估成效","(C) 確認問題→確認群體→介入實施→策略規劃→評估成效","(D) 確認群體→確認問題→介入實施→策略規劃→評估成效"],"answer":1,"image":""},{"id":"md3-109-1-72","subject":"md3","topic":"家醫-行為與社區醫學","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"下圖所示為2011年A, B, C三個國家醫療花費占其國內生產毛額（GDP: gross domestic products）的比例，分別是8.5%, 10.4%, 16.2%，呈現一個國家基層醫療醫師人數越多，醫療照護成本越低。下列何種國家組合最符合本圖？","options":["(A) A：英國，B：美國，C：加拿大","(B) A：英國，B：加拿大，C：美國","(C) A：加拿大，B：英國，C：美國","(D) A：美國，B：加拿大，C：英國"],"answer":1,"image":"md3-109-1-72.jpeg"},{"id":"md3-109-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"下列有關瀕死癌末病人因為意識不清，無法再進食時的營養處置，何者最正確？","options":["(A) 馬上接上全靜脈營養（total parenteral nutrition），以防營養不足","(B) 立即插上鼻胃管，以防營養不足","(C) 與家屬討論給與人工營養水分的利弊得失","(D) 建議病人接受經皮內視鏡胃造口術（percutaneous endoscopic gastrostomy）"],"answer":2,"image":""},{"id":"md3-109-1-74","subject":"md3","topic":"影像醫學","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"32歲女性，主訴食慾不振和倦怠感，經超音波與未施打對比劑腹部電腦斷層檢查後如圖，最有可能的診斷為？","options":["(A) 阻塞性黃疸（obstructive jaundice）","(B) 脂肪肝（fatty liver）","(C) 肝硬化（liver cirrhosis）","(D) 肝細胞癌（hepatocellular carcinoma）"],"answer":1,"image":"md3-109-1-74.jpeg"},{"id":"md3-109-1-75","subject":"md3","topic":"影像醫學","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"50歲男性主訴胸痛和咳嗽，胸部影像如圖，則最可能的診斷為下列何者？","options":["(A) 肺癌","(B) 侷限性肋膜積液","(C) 葉間積液（interlobar effusion）","(D) 肺動脈栓塞（pulmonary embolism）"],"answer":0,"image":"md3-109-1-75.jpeg"},{"id":"md3-109-1-76","subject":"md3","topic":"急診醫學","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"76歲李先生因胸痛來急診，初步診斷為右心室心肌梗塞（right ventricular infarction），血壓為76/44 mmHg，下列何項處置最不恰當？","options":["(A) 給予氧氣","(B) 給予抗血小板藥物（antiplatelet agents）","(C) 給予血栓溶解藥物（fibrinolytic agents）","(D) 給予硝化甘油（nitroglycerin）"],"answer":3,"image":""},{"id":"md3-109-1-77","subject":"md3","topic":"急診醫學","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"一位53歲男性，有長期高血壓病史，突發撕裂性胸痛且轉移至背部及腹部，血壓210/110 mmHg。他另外的主訴為右下肢痛，身體檢查發現摸不到右側股動脈脈搏，右下肢蒼白冰冷、腳趾無法活動，此時下列那一項處置較適當？","options":["(A) 維持收縮壓在150 mmHg以上，以確保適當的末肢循環","(B) 避免使用止痛藥，以免影響病情的觀察及血壓的監控","(C) 使用肝素（heparin），以免動脈阻塞更加厲害","(D) 立即安排電腦斷層檢查"],"answer":3,"image":""},{"id":"md3-109-1-78","subject":"md3","topic":"急診醫學","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"一位50歲男性至急診求治，主訴下巴紅腫疼痛，舌頭向後移位，下列敘述何者最不恰當？","options":["(A) Ludwig's angina是可能的鑑別診斷","(B) 病人可因蛀牙或口腔未保持清潔所引起","(C) 可給口服抗生素後門診追蹤","(D) 可使用電腦斷層進行診斷"],"answer":2,"image":""},{"id":"md3-109-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"已婚的陳先生與妻子分居多年，他因為隱球菌性腦膜炎住院，而後被診斷為愛滋病，陳先生再三交代院方醫護人員，不要告訴他的任何家人，所有他的醫療決策都委由一位王姓男性友人做主並已立下委任書。現在，他突然昏迷，需要緊急插管並轉到加護病房，醫師想要討論有關病人之DNR事宜，應該找誰？","options":["(A) 他的男性友人王先生","(B) 陳太太","(C) 陳先生的父母親","(D) 陳先生的成年長子"],"answer":0,"image":""},{"id":"md3-109-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"急診醫師被通知健保核刪到院前死亡的病人急救過程中的CPR和氣管插管。下列敘述何者正確？","options":["(A) 到院前死亡的病人不需要CPR和氣管插管，健保核刪為合理","(B) 到院前死亡的病人一定要CPR和氣管插管，健保核刪不合理","(C) 急診醫師應依其臨床判斷決定是否需要CPR和氣管插管。健保核刪應據理力爭","(D) 依醫院規定，決定是否對到院前死亡的病人急救"],"answer":2,"image":""},{"id":"md3-109-2-1","subject":"md3","topic":"內科-腎臟","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"一位25歲男性，突然發現下肢無力、無法站立與走路、需家人攙扶，遂在隔天早上由家屬陪同就醫。實驗室檢查發現低血鉀（2.0 mEq/L）及低血磷（1.8 mg/dL），而血清肌酸酐（creatinine 0.6 mg/dL）、鈉（139 mEq/L）、鈣（2.2 mmol/L）及血清滲透壓（serum osmolality 290 mOsm/kg）則在正常範圍。同時尿液中的鉀與滲透壓分別為10 mEq/L與580 mOsm/kg。下列敘述何者最適當？","options":["(A) TTKG（transtubular potassium gradient）計算後等於2.0","(B) 此病患低血鉀是因腎臟排出過多鉀離子","(C) 需加驗甲狀腺功能","(D) 經由周邊靜脈補鉀時，應將氯化鉀加在葡萄糖水裡，鉀離子濃度儘量不超過20～40 mmol/L"],"answer":2,"image":""},{"id":"md3-109-2-2","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"疾病篩檢的原則應該包括下列那一項？","options":["(A) 被篩檢出的疾病是可治療的","(B) 被篩檢的疾病其自然史是不清楚的","(C) 被篩檢的疾病對於健康沒有太大影響","(D) 篩檢方式具有高風險性"],"answer":0,"image":""},{"id":"md3-109-2-3","subject":"md3","topic":"家醫-行為與社區醫學","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"基本日常生活的自我照顧能力（Basic Activities of Daily Living：Self-Care Tasks）之評估，不包括下列那一項？","options":["(A) 個人衛生","(B) 穿衣脫衣","(C) 自行服藥","(D) 在床與椅子間移動"],"answer":2,"image":""},{"id":"md3-109-2-4","subject":"md3","topic":"內科-血液","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"一位病人的網狀細胞紅血球計數（reticulocyte count）為9%，血色素（hemoglobin）為7.5 gm/dL，血球比容值測定（hematocrit）為23%，則其網狀細胞紅血球生產指數（reticulocyte production index）為何？","options":["(A) 9.0","(B) 4.5","(C) 2.25","(D) 1.12"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第4題一律給分 (原公告答案 C)"},{"id":"md3-109-2-5","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"針對腹痛病人施行的身體檢查，下列敘述何者正確？","options":["(A) Grey Turner sign是指肚臍周圍有藍色瘀青，代表後腹腔出血","(B) 小腸阻塞初期，聽診常可發現低頻率、低活動性腸音（hypoactive bowel sounds）","(C) 右上腹觸診在吸氣與吐氣時，皆出現壓痛且停止呼吸，可記錄為Murphy sign陽性","(D) 執行Obturator sign檢查時，通常右側髖關節（hip）保持彎曲（flexion）；而施行Psoas sign時，膝關節則伸直"],"answer":3,"image":""},{"id":"md3-109-2-6","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"有關參與急性冠心症（acute coronary syndrome）之分子機制敘述，下列何者錯誤？","options":["(A) 穩定的冠脈動脈硬化斑塊，受發炎細胞分泌之tumor necrosis factor、matrix metalloprotease等因子浸潤，會因膠原蛋白（collagen）之分解而趨於不穩定","(B) 當不穩定斑塊發生崩壞、血小板接觸到血管內膜下之蛋白質成分時，會發生活化並釋出其胞內之thromboxane、serotonin、fibrinogen等因子，造成局部血管收縮，並激活更多血小板","(C) 被激活之血小板會以其表面的glycoprotein IIb/IIIa receptor彼此直接連結，形成血小板團塊","(D) 被激活之血小板釋出之thrombin會將fibrinogen轉換為fibrin，進而形成更多血栓"],"answer":2,"image":""},{"id":"md3-109-2-7","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"有關非ST段上升心肌梗塞（NSTEMI）之敘述，下列何者錯誤？","options":["(A) 急性非ST段上升心肌梗塞，係指患者臨床表現有不穩定心絞痛、心電圖未有明顯ST段上升、但心肌酶（cardiac enzyme）有升高者","(B) 各種心肌酶（cardiac enzyme）中，cardiac troponin的特異性及敏感度較高，出現升高的時間也比較早","(C) 非ST段上升心肌梗塞的心肌受損程度雖然比ST段上升心肌梗塞的少，但所有病人仍然應該在12小時內接受冠脈介入治療","(D) 對非ST段上升心肌梗塞病患的藥物治療中，應包括抗血小板藥物、抗凝血藥物、乙型交感神經阻斷劑（beta blocker）、及硝酸甘油等"],"answer":2,"image":""},{"id":"md3-109-2-8","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"一位76歲女性，最近稍微走路就會喘，到醫院檢查發現已患有高血壓和糖尿病，心電圖呈現心房顫動，但心室收縮功能正常且無瓣膜性心臟病，也無中風或其他心血管病史，評估病人使用抗凝血劑預防中風的CHA2DS2- VASc Score分數是多少？","options":["(A) 4","(B) 5","(C) 6","(D) 7"],"answer":[1,2],"image":"","answer_note":"更正:第8題答Ｂ、Ｃ給分"},{"id":"md3-109-2-9","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"一位69歲男性，過去無不適症狀，最近1個月開始有胸悶，容易疲倦無力，運動耐受力不佳，門診時血壓130/70 mmHg，心跳48次/分，呼吸16次/分，心電圖顯示如下圖，關於其心電圖的檢查結果，下列何者最正確？","options":["(A) 有竇性心動過緩（sinus bradycardia）","(B) 有QTc間期延長（prolonged QTc）","(C) 有左心室肥厚（left ventricular hypertrophy）","(D) 有房室傳導阻滯（atrioventricular block）"],"answer":3,"image":"md3-109-2-9.jpeg"},{"id":"md3-109-2-10","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"一位18歲男性無任何過去病史，因在跑馬拉松時暈厥被送至急診評估。根據同學描述，病人當時並無抽搐或眼睛上吊情形。且病患自述事發當時並無特別印象或記憶，但近日活動並沒有胸悶或活動性喘狀況。病患父親於50歲左右不明原因於登山過程中猝死。身體診察發現病人有收縮期心雜音。心電圖檢查如下。心臟超音波檢查顯示左心室壁肥厚且有心室內壓力梯度（intraventricular pressure gradient）。以下動作何者可造成病患心雜音更明顯？","options":["(A) 用力握手（handgrip）","(B) 蹲下（squatting）","(C) 站起（standing）","(D) 抬腳（leg raising）"],"answer":2,"image":"md3-109-2-10.jpeg"},{"id":"md3-109-2-11","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"有關心音paradoxical splitting之敘述，下列何者正確？","options":["(A) 係指二尖瓣的關閉時間提前所致","(B) 在嚴重主動脈瓣狹窄病人身上出現時，代表主動脈瓣關閉時間延後所致","(C) 常出現在心電圖紀錄有right bundle branch block的病人","(D) 常出現在肺高壓合併右心衰竭的病人"],"answer":1,"image":""},{"id":"md3-109-2-12","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"有關下肢周邊血管疾病之敘述，下列何者錯誤？","options":["(A) 一般而言，出現有皮膚溫度較涼、跛足、脈搏異常，表示疾病較為嚴重","(B) 若偵測到有血管雜音（vascular bruit），表示血管有分流（shunting）","(C) 當pulse oximetry在手指比腳趾有大於2%的氧飽合（oxygen saturation）差異時，可用以偵測本病之存在","(D) 血管雜音（vascular bruit）音量的大小和狹窄程度無關"],"answer":1,"image":""},{"id":"md3-109-2-13","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"有關心臟雜音的敘述，下列何者正確？","options":["(A) 主動脈狹窄的典型心雜音是早期收縮期心雜音，在S1之後，S2之前","(B) 左心室出口阻塞性肥厚型心肌病變患者，由蹲下姿態改變成站立時，心雜音會因而變小聲","(C) 發現有連續性的心雜音，應考慮的鑑別診斷包括：sinus of Valsalva破裂以及心房中膈缺損","(D) 僧帽瓣狹窄的心雜音，主要是舒張期的中段到末段雜音，病患左側躺時，在心尖部位會聽到低頻的心音"],"answer":3,"image":""},{"id":"md3-109-2-14","subject":"md3","topic":"內科-心臟血管","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"有關收縮性心衰竭的治療，下列何者不宜？","options":["(A) 利尿劑：包括aldosterone拮抗劑","(B) 鈣離子阻斷劑：特別是verapamil及diltiazem","(C) RAAS抑制劑：包括angiotensin converting enzyme inhibitor以及angiotensin II receptor antagonist類的藥物","(D) 降心跳藥物：包括乙型阻斷劑以及ivabradine"],"answer":1,"image":""},{"id":"md3-109-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"下列有關懷孕期間可能發生的肝臟疾病（liver disease of pregnancy）之敘述，何者錯誤？","options":["(A) rd AFLP（acute fatty liver of pregnancy）主要發生在妊娠第三期（3trimester），其肝臟病理主要呈現為microvesicular fat","(B) HELLP（hemolysis, elevated liver enzymes, low platelets syndrome）發生時，立即生產是主要的治療方法","(C) 懷孕期間，肝臟常見功能的變化包括血清alkaline phosphatase，AST及ALT上升","(D) 懷孕會增加肝臟腺瘤（adenoma）破裂出血的機會"],"answer":2,"image":""},{"id":"md3-109-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"下列有關primary sclerosing cholangitis（PSC）及primary biliary cirrhosis（PBC）的敘述何者錯誤？","options":["(A) PSC常同時合併有ulcerative colitis（UC）","(B) PBC患者有較高的風險得到cholangiocarcinoma","(C) 針對末期PBC患者，除了換肝手術外，UDCA（ursodeoxycholic acid）並無法有效改善PBC的存活率","(D) PBC的患者，女性占大多數"],"answer":1,"image":""},{"id":"md3-109-2-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"下列有關於化膿性肝膿瘍（pyogenic liver abscess）之敘述，何者錯誤？","options":["(A) 由血流散布到肝臟引起的肝膿瘍，多為單一微生物感染，以Staphylococcus aureus及Streptococcal species最常見","(B) 原發性肝膿瘍（primary liver abscess）最常見為Escherichia coli所引起","(C) 糖尿病患發生Klebsiella pneumoniae肝膿瘍時，可能併發endophthalmitis","(D) 目前之標準處理方式為膿瘍引流（drainage）加上抗生素注射治療"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第17題一律給分。 (原公告答案 B)"},{"id":"md3-109-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"有關解讀下表個案之B型肝炎血清標誌，何者敘述錯誤？","options":["(A) 個案1可以是e抗原（HBeAg）陰性慢性B型肝炎或是急性B型肝炎感染的後期","(B) 個案2仍然屬於慢性B型肝炎帶原","(C) 個案3屬於過往的B型肝炎感染，目前不可能偵測到病毒存在","(D) 個案4可以是B型肝炎疫苗注射後或是假陽性"],"answer":2,"image":"md3-109-2-18.jpeg"},{"id":"md3-109-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"有關慢性B型肝炎治療的敘述，下列何者錯誤？","options":["(A) 抗病毒藥物的potency（抑制B型肝炎病毒複製的能力）由高往低排序，依序為entecavir＞telbivudine＞ tenofovir＞pegylated interferon","(B) 干擾素治療的優點為固定療程，無抗藥性，失代償性肝硬化也可使用","(C) 使用nucleotide analogues如tenofovir disoproxil fumarate要監控腎功能","(D) 肝硬化患者，且HBV DNA≧2,000 IU/mL，應該要給與抗病毒藥物治療"],"answer":1,"image":""},{"id":"md3-109-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"對於肝性腦病變（俗稱肝昏迷）（hepatic encephalopathy）的敘述，何者正確？","options":["(A) 病人血液中的氨（ammonia）值通常會升高，而且氨值的高低與肝性腦病變的嚴重度成正比","(B) 誘發因素很多，例如感染及低血鉀","(C) 必須嚴格的限制蛋白質的攝取","(D) 可以使用軟便劑如氧化鎂（MgO）來治療"],"answer":1,"image":""},{"id":"md3-109-2-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"關於發炎性腸道疾病（inflammatory bowel disease, IBD）的治療，何者正確？①類固醇在remission induction與maintenance therapy都扮演很重要角色 ②生物製劑（biologics）可以降低使用類固醇的機會，讓發炎性腸道疾病的治療進入新紀元 ③生物製劑（biologics）可以增進瘻管（fistula）癒合，降低需手術或引流的機會 ④5-ASA藥物為潰瘍性大腸炎重要的維持治療藥物","options":["(A) 僅①②③","(B) 僅②③④","(C) 僅②④","(D) ①②③④"],"answer":1,"image":""},{"id":"md3-109-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"下列關於大腸激躁症（irritable bowel syndrome）的敘述，何者正確？","options":["(A) 主要為腸道壁的異常所致，與中樞神經較無關連性","(B) 急性感染性腸炎後發生的大腸激躁症，以男生多於女生","(C) 患者以45歲以上者居多","(D) 嚴重大腸激躁症以女性居多，約占80%"],"answer":3,"image":""},{"id":"md3-109-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"關於可遺傳性胃腸道息肉增生症候群（hereditable gastrointestinal polyposis syndromes），下列敘述何者正確？","options":["(A) familial adenomatous polyposis其大腸息肉組織型態為腺瘤（adenoma），腺瘤常具有癌化可能，此症候也常伴隨各種先天性異常（congenital abnormalities）","(B) Peutz-Jeghers syndrome其息肉組織型態為腺瘤（adenoma），腺瘤常具有癌化可能，此病症息肉可能發生在大小腸及胃部","(C) Turcot's syndrome其大腸息肉組織型態為腺瘤（adenoma），腺瘤常具有癌化可能，也常伴隨發生骨瘤（osteomas）、纖維瘤（fibroma）、脂肪瘤（lipoma）、表皮樣囊腫（epidermoid cysts）、壺腹癌（ampullary cancers）、先天性視網膜色素上皮肥大（congenital hypertrophy of retinal pigment epithelium）","(D) nonpolyposis syndrome（Lynch's syndrome）其大腸息肉組織型態為腺瘤（adenoma），腺瘤常發生於近端大腸（proximal colon），息肉具有癌化可能，此病症可能伴隨有子宮內膜及卵巢腫瘤（endometrial and ovarian tumors），雖然發生率較少，但是也有可能發生胃癌（gastric cancer）、泌尿生殖癌（genitourinary cancers）、胰臟癌（pancreatic cancer）、膽道癌（biliary cancer）"],"answer":3,"image":""},{"id":"md3-109-2-24","subject":"md3","topic":"內科-腎臟","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"55歲女性病人，因慢性腎絲球腎炎導致末期腎病，5年前接受親屬捐贈活體腎移植，長期接受tacrolimus、mycophenolate mofetil治療，一個月前血中肌酸酐0.8 mg/dL，3天前噁心、嘔吐，肌酸酐升至3.3 mg/dL，腎切片檢查呈現腎小球、腎小管有C4d沉積，內皮細胞損傷，目前最佳治療方式是：","options":["(A) 增加tacrolimus和mycophenolate mofetil劑量","(B) 類固醇脈衝治療（methylprednisolone pulse therapy）","(C) 降低tacrolimus劑量加血液透析","(D) 血漿置換術加免疫球蛋白注射"],"answer":3,"image":""},{"id":"md3-109-2-25","subject":"md3","topic":"內科-腎臟","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"23歲女性病人，於上呼吸道感染後3天發現血尿，尿液檢查發現有血尿、蛋白尿，腎切片檢查發現腎小球膜基質（mesangium）有免疫球蛋白沉澱，此病人最可能之診斷為：","options":["(A) 微小變化腎病變（minimal change disease）","(B) A型免疫球蛋白腎病變（IgA nephropathy）","(C) 局部腎硬化（focal glomerulosclerosis）","(D) 膜性腎病變（membranous nephropathy）"],"answer":1,"image":""},{"id":"md3-109-2-26","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"下列抗體和疾病之間的致病機轉組合，何者錯誤？","options":["(A) anti-proteinase-3 antibodies and granulomatosis with polyangiitis","(B) anti-hyaluronidase antibodies and poststreptococcal glomerulonephritis","(C) anti-phospholipase A2 receptor antibodies and primary membranous glomerulonephritis","(D) anti-α5 NC1 domain of collagen IV antibodies and Goodpasture syndrome"],"answer":3,"image":""},{"id":"md3-109-2-27","subject":"md3","topic":"內科-腎臟","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"某70歲女性患者近2週嘔吐、腹痛漸增而至急診；過去病史：糖尿病10多年，一個月前腎功能正常，目前使用 + 之藥物包括metformin 1.5 g daily，losartan 50 mg daily，以及simvastatin 20 mg daily。實驗室檢查發現：Na +-2+ 139 mmol/L，K 4.9 mmol/L，Cl 103 mmol/L，glucose 216 mg/dL，cholesterol 220 mg/dL，Ca 8 mg/dL，Cr - 6.5 mg/dL；動脈血氣體pH 7.0，HCO34.0 mEq/L，PCO2 14 mmHg，尿液無異常。下列何者為最可能之診斷？","options":["(A) diabetic ketoacidosis","(B) rhabdomyolysis","(C) lactic acidosis","(D) type 4 renal tubular acidosis"],"answer":2,"image":""},{"id":"md3-109-2-28","subject":"md3","topic":"內科-腎臟","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"下列有關急性腎損傷（acute kidney injury）的敘述，何者錯誤？","options":["(A) 腎前性（prerenal）急性腎損傷之血清尿素氮（BUN）與肌酸酐（creatinine）比值常大於20","(B) 敗血症為造成腎因性（intrinsic）急性腎損傷常見原因之一","(C) 泌尿道阻塞造成之腎後性（postrenal）急性腎損傷，解決阻塞為最首要的治療方式","(D) 慢性腎臟病患併發急性腎損傷，若尿鈉排出分率（fractional excretion of sodium, FeNa）大於1%，則可排除腎前性（prerenal）急性腎損傷"],"answer":3,"image":""},{"id":"md3-109-2-29","subject":"md3","topic":"內科-腎臟","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"下列有關腎移植抗排斥藥物與其副作用之配對，何者錯誤？","options":["(A) 類固醇（glucocorticoid）：骨質疏鬆","(B) 環孢靈（cyclosporine）：腎毒性","(C) 普樂可復（tacrolimus）：移植後糖尿病","(D) 斥消靈（sirolimus）：高尿酸血症"],"answer":3,"image":""},{"id":"md3-109-2-30","subject":"md3","topic":"內科-腎臟","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"有關尿毒性出血（uremic bleeding）的敘述，下列何者錯誤？","options":["(A) 尿毒性出血常導因於血小板凝集功能不良","(B) 若尿毒性出血病患合併貧血，輸血也有助於凝血","(C) 可輸注desmopressin、cryoprecipitate來治療尿毒性出血","(D) 若持續出血，可考慮給與androgen幫助止血，但須注意可能有血栓栓塞（thromboembolism）的風險"],"answer":3,"image":""},{"id":"md3-109-2-31","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"關於sarcoidosis的臨床表現與診斷治療之敘述，下列何者正確？","options":["(A) sarcoidosis是一種會產生granuloma的發炎性免疫疾病，過度的CD4 T淋巴細胞活化為主要致病機轉","(B) sarcoidosis最少侵犯肺部，也很少造成肺動脈高壓（pulmonary artery hypertension）","(C) 病人因血中的angiotensin-converting enzyme（ACE）上升而造成hypercalcemia","(D) 目前最有效的生物製劑是IL-1 inhibitor"],"answer":0,"image":""},{"id":"md3-109-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"某些自體免疫抗體與自體免疫疾病有相關性，因此測血中的自體免疫抗體有助於自體免疫疾病的診斷，下列的自體免疫疾病與自體免疫抗體之配對何者錯誤？","options":["(A) Sjögren's syndrome－anti-Ro（SS-A）antibody","(B) systemic lupus erythematosus（SLE）－anti-ds DNA antibody","(C) mixed connective tissue disease（MCTD）－anti-centromere antibody","(D) diffuse systemic sclerosis－anti-Scl-70 antibody"],"answer":2,"image":""},{"id":"md3-109-2-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"下列何者是風濕熱（rheumatic fever）最有可能的病理機轉（pathogenesis）？","options":["(A) 鏈球菌抗原（streptococcal antigens）的分子模仿（molecular mimicry）免疫反應","(B) 金黃色葡萄球菌（Staphylococcus aureus）感染引起","(C) 癌細胞侵襲（cancer cell invasion）引起","(D) 類風濕性關節炎（rheumatoid arthritis）引起"],"answer":0,"image":""},{"id":"md3-109-2-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"有關僵直性脊椎炎（ankylosing spondylitis）的治療，下列何者正確？","options":["(A) sulfasalazine對脊椎發炎比較有效","(B) 生物製劑抗腫瘤壞死因子（anti-TNF）只對周邊關節炎有效，對於脊椎發炎沒有明顯幫助","(C) 非類固醇類消炎止痛藥（nonsteroidal anti-inflammatory drugs, NSAIDs）是第一線藥物","(D) methotrexate對於輔助anti-TNF治療僵直性脊椎炎很重要，最好每個病人都要併用"],"answer":2,"image":""},{"id":"md3-109-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"65歲謝女士因爲全身酸痛多年到門診求診。主訴睡眠不佳、注意力不能集中，已經看了10位以上的不同專科醫師，做過腦部電腦斷層、肌電圖及血液檢查，都沒有確切診斷，只知道以前的醫生告知她所有檢查都是正常。若懷疑病人是纖維肌痛症（fibromyalgia），則下列何項處置對確立診斷最為適當？","options":["(A) 問卷評估疼痛區及全身症狀","(B) 安排頸椎核磁共振","(C) 再檢驗一次血中類風濕因子（rheumatoid factor）","(D) 女性荷爾蒙檢查"],"answer":0,"image":""},{"id":"md3-109-2-36","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"某50歲男性為一慢性B型肝炎患者，在超音波檢查中發現有一個2公分的肝腫瘤，醫師懷疑為肝細胞癌（hepatocellular carcinoma, HCC）。以下的血液檢查報告，何者不代表該病患已有肝硬化（liver cirrhosis）的現象？","options":["(A) 血小板數＝70,000/μL","(B) albumin＝2.8 g/dL","(C) INR（international normalized ratio）＞2.2","(D) AST＝100 U/L"],"answer":3,"image":""},{"id":"md3-109-2-37","subject":"md3","topic":"內科-腫瘤","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"Localized non-metastatic resectable的pancreatic ductal adenocarcinoma，應考慮的治療為「外科切除」。以下敘述中，何者正確？","options":["(A) 大多數（約60%）初診斷的胰臟癌，皆屬於localized non-metastatic resectable disease","(B) 經過手術切除後，大多數病患預後良好，5年整體存活率大約為60%","(C) 手術病理檢驗發現約有30%病患仍有microscopic residual disease（即為R1 resection）","(D) 手術後的輔助性化學治療對病患的整體存活期並無助益，不應進行"],"answer":2,"image":""},{"id":"md3-109-2-38","subject":"md3","topic":"內科-腫瘤","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"下列何者不是第四期腎細胞癌有效的治療？","options":["(A) 免疫檢查站（checkpoint）抑制劑","(B) 化學治療（chemotherapy）","(C) 抗血管新生標靶治療","(D) mTOR抑制劑標靶治療"],"answer":1,"image":""},{"id":"md3-109-2-39","subject":"md3","topic":"內科-血液","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"一位67歲男性，因為倦怠無力，臉色蒼白泛黃而到門診求醫。理學檢查發現結膜蒼白，鞏膜泛黃，舌頭平滑發炎且無突起。其餘身體檢查並無特殊之處。血液數據顯示，白血球2,950/μL，分類無明顯異常，血紅素6.0 g/dL，MCV（mean corpuscular volume）120.4 fL，血小板84,000/μL，總膽紅素輕微升高3.23 mg/dL，直接膽紅素0.25 mg/dL，lactate dehydrogenase（LDH）高達1030 U/L（參考區間140～271）。病人並未接受過任何胃腸道的手術，但是有atrophic gastritis，且anti-parietal cell antibody呈陽性反應。以下關於這位病人最可能的疾病之描述，何者錯誤？","options":["(A) 此類病人的血液中的reticulocyte counts常是降低的","(B) 此類病人的骨髓中的erythroid precursors的數量常是降低的","(C) 此類病人的高LDH數值主要是因為ineffective erythropoiesis與intramedullary hemolysis而造成","(D) 此類病人的血液中的granulocytes常有hypersegmented nuclei"],"answer":1,"image":""},{"id":"md3-109-2-40","subject":"md3","topic":"內科-血液","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"一位75歲女性，5年前因為風濕性心臟病而裝置金屬心臟瓣膜，長期服用warfarin以防止血栓。某日例行性的門診發現INR（international normalized ratio）是5.4，但是臨床上並無出血的現象。以下關於此藥物與這位病人的處置，何者錯誤？","options":["(A) warfarin之抗凝血效果通常不會在服藥後立刻出現，因此需要在開始治療時，同時使用約5天的其他抗凝血藥物，例如heparin，以快速達到抗凝血的效果","(B) 為了預防出血，此病人應該給與vitamin K靜脈注射，直到INR回到3以下","(C) 對於臨床上有出血的情況，fresh-frozen plasma（FFP）可以快速地補充vitamin K-dependent凝血因子","(D) warfarin會抑制protein C與protein S的血中濃度，對於protein C或是protein S缺乏的病人，使用warfarin要特別小心，以免引發血栓"],"answer":1,"image":""},{"id":"md3-109-2-41","subject":"md3","topic":"內科-血液","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"下列何者不適合當作病人接受造血幹細胞移植（hematopoietic stem cell transplantation）的來源？","options":["(A) 骨髓細胞（bone marrow cells）","(B) 顆粒球群落刺激因子（granulocyte colony-stimulating factor, G-CSF）驅動後的周邊血幹細胞（G-CSF mobilized peripheral blood stem cells）","(C) 臍帶血細胞（umbilical cord blood cells）","(D) 成人脾臟細胞（adult spleen cells）"],"answer":3,"image":""},{"id":"md3-109-2-42","subject":"md3","topic":"內科-腫瘤","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"下列何種頭頸癌在早期可考慮以放射治療，以保持器官功能？","options":["(A) 口頰癌（buccal cancer）","(B) 喉癌（laryngeal cancer）","(C) 舌癌（tongue cancer）","(D) 唾液腺癌（salivary gland cancer）"],"answer":1,"image":""},{"id":"md3-109-2-43","subject":"md3","topic":"內科-腫瘤","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"在早期癌症病患接受根治性手術後，何種癌症可以用所列出之標靶治療為輔助性療法（adjuvant therapy），以有效提升整體存活率？","options":["(A) EGFR基因突變之肺癌：gefitinib","(B) K-RAS無突變之大腸癌：cetuximab","(C) HER2基因過度表現之乳癌：trastuzumab","(D) HBV相關的肝癌：sorafenib"],"answer":2,"image":""},{"id":"md3-109-2-44","subject":"md3","topic":"內科-腫瘤","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"60歲已停經女性，無其他特殊疾病，經乳房腫瘤切片證實罹患乳癌，病理顯示estrogen receptor及progesterone receptor皆為陽性，HER2為陰性，骨骼掃描發現多處肋骨轉移，斷層掃描並未發現胸腹有任何轉移，下列何種藥物最適合當作第一線治療？","options":["(A) bevacizumab","(B) trastuzumab","(C) chemotherapy","(D) aromatase inhibitor"],"answer":3,"image":""},{"id":"md3-109-2-45","subject":"md3","topic":"內科-腫瘤","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"在相同期別下，下列那一種亞型（subtype）的肺腺癌（lung adenocarcinoma）經手術完全切除後，病人的預後最佳？","options":["(A) micropapillary pattern","(B) solid pattern","(C) acinar pattern","(D) lepidic pattern"],"answer":3,"image":""},{"id":"md3-109-2-46","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"60歲之男性病人，因有左側胸痛，咳嗽及呼吸困難而至急診處就醫，聽診時發現左後側肺野有明顯的支氣管音（bronchial sound），其最可能之診斷為何？","options":["(A) 左側肋膜腔積水","(B) 左側氣胸","(C) 肺水腫","(D) 左下葉大葉性肺炎"],"answer":3,"image":""},{"id":"md3-109-2-47","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"76歲男性病人，長期抽菸已有40年，近3年來有漸進性呼吸困難現象，肺功能檢查顯示FEV1/FVC 78%，FEV1 1.73 L（66% predicted），FVC 2.21 L（65% predicted），TLC 3.54 L（66% predicted），DLco 8.6 mL/mmHg·min（40% predicted），此病人最可能罹患下列何種疾病？","options":["(A) 慢性阻塞性肺病（COPD）","(B) 胸廓畸形（chest wall deformity）","(C) 重症肌無力（myasthenia gravis）","(D) 肺纖維化症（pulmonary fibrosis）"],"answer":3,"image":""},{"id":"md3-109-2-48","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"關於潛伏結核感染（latent TB infection），下列敘述何者正確？","options":["(A) 通常以結核菌素皮膚測驗（tuberculin skin test）或丙型干擾素血液測驗（interferon-γ release assay）來診斷","(B) 潛伏結核感染者約30%會發展成為活動性肺結核","(C) 潛伏結核感染者在未接受治療前，必須戴外科口罩，以避免傳染他人","(D) 經有效的潛伏結核感染治療，可降低約70%的發病率"],"answer":0,"image":""},{"id":"md3-109-2-49","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"關於肺膿瘍，下列敘述何者最不適當？","options":["(A) 最常見的原發性肺膿瘍產生原因是吸入性（aspiration）","(B) 最常見的原發性肺膿瘍病灶位置為右中葉（right middle lobe）及左舌葉（left lingular lobe）","(C) 治療時間通常3星期以上，必要時需進行手術","(D) 致病菌常為多種微生物（polymicrobial）"],"answer":1,"image":""},{"id":"md3-109-2-50","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"下列何者不是典型之甲狀腺功能低下（hypothyroidism）的症狀？","options":["(A) 全身呈現黏液性腫（myxedema）","(B) 休息靜態下之心跳過慢","(C) 體重急速下降","(D) 怕冷"],"answer":2,"image":""},{"id":"md3-109-2-51","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"有關胰島素製劑與使用的敘述，下列何者正確？","options":["(A) 中長效型胰島素製劑包含detemir、glargine及lispro","(B) 短效型胰島素注射提供糖尿病病人每天基礎胰島素（basal insulin）的需求","(C) 預混型胰島素含有魚精蛋白（protamine）可加速胰島素的吸收與作用","(D) 第1型糖尿病病人需仰賴胰島素的注射來控制血糖並預防酮酸血症的發生"],"answer":3,"image":""},{"id":"md3-109-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"糖尿病可以引起許多慢性併發症，其中大血管疾病相當常見，下列敘述何者最不恰當？","options":["(A) 糖尿病病人發生大血管疾病的風險為無糖尿病者的2～4倍","(B) 良好地控制血糖、血壓及血脂是預防大血管疾病的有效方法","(C) 糖尿病病人膽固醇治療準則與無糖尿病者一樣","(D) aspirin及statin類藥物已被證實可以有效地預防糖尿病病人發生大血管疾病"],"answer":2,"image":""},{"id":"md3-109-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"依據衛生福利部國民健康署之代謝症候群（metabolic syndrome）判定標準，下列敘述何者正確？","options":["(A) 2男女身體質量指數（BMI）都要超過24 kg/m","(B) 低密度脂蛋白膽固醇（LDL-C）大於100 mg/dL","(C) 男女之高密度脂蛋白膽固醇（HDL-C）小於50 mg/dL","(D) 女性之腰圍大於80公分"],"answer":3,"image":""},{"id":"md3-109-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"2一位26歲患者，外觀正常，身體質量指數（BMI）為20 kg/m，無不適。健檢發現高血壓、低血鉀、心跳正常。為了探討次發性高血壓的可能，此病患宜安排下列何種檢查最合適？","options":["(A) 抽血檢驗aldosterone和plasma renin activity","(B) 抽血檢驗ACTH和cortisol","(C) 測量24小時尿液的VMA和catecholamines","(D) 抽血檢驗fT4（free thyroxine）和TSH"],"answer":0,"image":""},{"id":"md3-109-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"下列何者不是常用於治療甲狀腺功能亢進的方式之一？","options":["(A) 口服抗甲狀腺藥物","(B) 手術切除甲狀腺","(C) 立體定位放射線治療","(D) 放射性碘治療"],"answer":2,"image":""},{"id":"md3-109-2-56","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"一位20歲男性，體檢時發現聲音細、無鬍子、無陰毛、陰莖短、睪丸皆在陰囊中但小而軟，其下一步最適當的處置為何？","options":["(A) 安排睪丸超音波","(B) 注射男性荷爾蒙治療","(C) 安排腦下垂體與下視丘核磁共振檢查","(D) 抽血測量FSH、LH、testosterone"],"answer":3,"image":""},{"id":"md3-109-2-57","subject":"md3","topic":"內科-感染","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"下列有關鉤端螺旋體病（leptospirosis）特徵的敘述，何者正確？","options":["(A) 蚊子是傳播鉤端螺旋體的重要載體","(B) 鉤端螺旋體病通常最初感染的症狀是發燒、頭痛和肌肉酸痛","(C) 鉤端螺旋體肝炎常引起明顯的轉氨酶（transaminase）增高，而血液的膽紅素（bilirubin）卻是正常或些微升高","(D) 診斷急性鉤端螺旋體病的最準確方法是血液塗片的暗視野（dark field）顯微鏡檢查"],"answer":1,"image":""},{"id":"md3-109-2-58","subject":"md3","topic":"內科-感染","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"35歲急性白血病病人化療後2週，出現白血球低下合併發燒，則下列藥物單獨使用時何者最恰當？","options":["(A) ertapenem（carbapenem類）","(B) cefepime（第4代cephalosporin）","(C) tigecycline（tetracycline類）","(D) daptomycin（lipopeptide類）"],"answer":1,"image":""},{"id":"md3-109-2-59","subject":"md3","topic":"內科-感染","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"30歲醫療工作者懷孕30週，因高燒、喉嚨痛、肌肉酸痛及頭痛就醫，下列處置何者不恰當？","options":["(A) 詢問旅遊史及是否有接觸流感病人","(B) 若同仁有相同症狀，則需通知感染管制單位，並依規定通報衛生局","(C) 居家靜養自我健康管理","(D) 因懷孕不建議任何抗病毒藥物治療（如：oseltamivir）"],"answer":3,"image":""},{"id":"md3-109-2-60","subject":"md3","topic":"內科-感染","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"60歲糖尿病人因右眼視力模糊，鼻腔有黑色分泌物來住院，經耳鼻喉科開刀病理化驗結果如附圖，則下列何者是最可能的致病菌？","options":["(A) 麴菌（Aspergillus）","(B) 念珠菌（Candida）","(C) 非結核分枝桿菌（nontuberculous mycobacteria, NTM）","(D) 金黃色葡萄球菌（Staphylococcus aureus）"],"answer":0,"image":"md3-109-2-60.jpeg"},{"id":"md3-109-2-61","subject":"md3","topic":"內科-感染","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"40歲男性感染人類免疫不全病毒（HIV）8年，從未接受抗反轉錄病毒治療，CD4+ T細胞數70 cells/μL，病毒量53,000 copies/mL，因感染肺結核開始接受抗結核藥物治療。後續這位病人想接受HIV的治療，則何時開始使用抗反轉錄病毒治療最合適？","options":["(A) 立即同步治療","(B) 抗結核藥物治療2～4週後","(C) 抗結核藥物治療3～4月後","(D) 抗結核藥物治療結束後"],"answer":1,"image":""},{"id":"md3-109-2-62","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"60歲女性，為家庭主婦，至門診求診，主訴過去幾年咳嗽有濃痰、胸悶、走路或上下樓梯會喘，過去無抽菸史，無免疫方面疾病，年輕時常因感冒出現發燒、咳嗽、濃痰情況，chest x-ray出現兩側下肺葉有“tram tracks”sign，此病人最可能的診斷為何？","options":["(A) allergic bronchopulmonary aspergillosis","(B) bronchial asthma","(C) pulmonary alveolar proteinosis","(D) bronchiectasis"],"answer":3,"image":""},{"id":"md3-109-2-63","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"承上題，對於此病人之治療方式，下列敘述何者正確？","options":["(A) 只要痰液培養出現NTM（nontuberculous mycobacteria），應立刻給予治療避免傳染他人","(B) 即使無急性發作的狀況，病人也應接受抗生素做預防性治療，減少細菌生長","(C) 支氣管擴張劑霧化治療或化痰劑對於這類病人並無幫助","(D) 若病灶只出現在局部區域，並出現反覆難以控制之感染，可以考慮外科切除"],"answer":3,"image":""},{"id":"md3-109-2-64","subject":"md3","topic":"急診醫學","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"醫療工作者發生針扎事件，於除夕夜來到急診處，下列處置何者最不恰當？","options":["(A) 進行針扎來源者及被針扎者的anti-HIV抗體檢驗","(B) 進行HCV、HBV、梅毒（syphilis）血清檢查","(C) 告知空窗期及後續抽血時間","(D) 安排年初四至感染科等指定門診追踨及後續處置"],"answer":3,"image":""},{"id":"md3-109-2-65","subject":"md3","topic":"內科-感染","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"承上題，針扎來源者的血清化驗結果顯示anti-HIV抗體陰性，但是醫療工作者本人anti-HIV screening test為陽性：7.2 S/CO（陽性定義為：S/CO≧1.00），此時可以為他進行的最恰當處置為：","options":["(A) 通報衛生福利部疾病管制署（CDC）","(B) 進行西方墨點法檢查（Western blot）","(C) 開始抗病毒藥物預防性投藥","(D) 觀察即可，一個月後再做一次HIV screening test"],"answer":1,"image":""},{"id":"md3-109-2-66","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"林先生45歲，接受成人健康檢查結果如下：腰圍88 cm，血壓132/88 mmHg，空腹血糖106 mg/dL，總膽固醇196 mg/dL，三酸甘油脂180 mg/dL，高密度膽固醇42 mg/dL，低密度膽固醇120 mg/dL。依據我國衛生福利部代謝症候群的定義，林先生符合幾項？","options":["(A) 2項","(B) 3項","(C) 4項","(D) 5項"],"answer":1,"image":""},{"id":"md3-109-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"75歲男性病人主訴雙腳容易痠痛，經病史詢問在2個月前曾跌倒，之後越來越不想出門運動；就診時，醫師請病人「由椅子站起來往前走3公尺，轉身180度，走回到椅子前，再轉身，坐下」，結果病人花16秒完成。下列敘述何者錯誤？","options":["(A) 該檢查為起身行走測驗（get-up-and-go test）","(B) 該病人測驗所需時間異常，屬跌倒高風險","(C) 該測驗是在檢查坐骨神經功能","(D) 該病人已有衰弱現象（frail）"],"answer":2,"image":""},{"id":"md3-109-2-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"政府推動轉診制度，鼓勵雙向轉診，轉診是屬於家庭醫師那一項特色的表現？","options":["(A) 可近性（accessibility）","(B) 負責性（accountability）","(C) 協調性（coordination）","(D) 持續性（continuity）"],"answer":2,"image":""},{"id":"md3-109-2-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"有關慢性疾病運動的處方建議，以重視安全、漸進與個人化為原則，下列建議何者最不適當？","options":["(A) 運動型態：有氧運動增加心肺耐力，阻力訓練改善肌力與肌耐力，伸展操改善柔軟度","(B) 運動強度：主觀感受評估運動強度，中等強度為「可以說話，沒辦法唱歌」","(C) 運動頻率：每週至少3天","(D) 運動持續時間：不可分段做，每次須連續大約半小時至1個小時"],"answer":3,"image":""},{"id":"md3-109-2-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"下列有關篩檢工具的特性，那些對臨床醫師及病人最有意義？","options":["(A) 敏感度（sensitivity）及特異度（specificity）","(B) 敏感度（sensitivity）及陽性預測值（positive predictive value）","(C) 特異度（specificity）及陰性預測值（negative predictive value）","(D) 陽性預測值（positive predictive value）及陰性預測值（negative predictive value）"],"answer":3,"image":""},{"id":"md3-109-2-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"關於非語言溝通（nonverbal communication）的描述，下列何者正確？","options":["(A) 在人與人的溝通，非語言溝通所蒐集的訊息約占全部訊息的十分之一","(B) 個人情緒及臉部所呈現之表情，在不同文化其表現方式有很大差異","(C) 頭部微傾且注視對方，代表有興趣及專注於溝通","(D) 兩手臂交叉於胸前代表放鬆"],"answer":2,"image":""},{"id":"md3-109-2-72","subject":"md3","topic":"家醫-行為與社區醫學","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"在基層服務的家庭醫師想進行社區健康促進計畫，以提升鄉民的健康，下列執行內容何者不適當？","options":["(A) 界定健康促進的鄉民範圍，譬如年齡、性別","(B) 確認鄉民的健康課題","(C) 擬定健康促進的介入計畫及執行步驟","(D) 辦理衛生教育活動，同時宣導診所服務項目"],"answer":3,"image":""},{"id":"md3-109-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"末期病人出現躁動不安，甚至有視幻覺等譫妄（delirium）症狀時，如果需要選用藥物，下列何者為首選？","options":["(A) 安眠藥（如Zolpidem）","(B) 抗精神病藥物（如Haloperidol）","(C) 肌肉鬆弛劑（如Chlorzoxazone）","(D) 鎮靜劑（如Benzodiazepine）"],"answer":1,"image":""},{"id":"md3-109-2-74","subject":"md3","topic":"內科-感染","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"有關骨髓炎的診斷，下列何者正確？","options":["(A) 診斷是否及時與預後無明顯關係","(B) 一般多需要先進行患部的X光片檢查，有時可據此加以診斷","(C) 侵犯脊椎的骨髓炎大都不需要接受磁振造影檢查","(D) 白血球同位素檢查為骨髓炎必要的診斷工具"],"answer":1,"image":""},{"id":"md3-109-2-75","subject":"md3","topic":"內科-消化肝膽胰","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"一名酗酒男性因腹脹和食慾不佳來求診。超音波檢查發現病人有肝硬化，電腦斷層檢查呈現如圖，箭號所指之異常最可能是下列何種疾病所造成？","options":["(A) portal hypertension","(B) lymphadenopathy","(C) hepatocellular carcinoma","(D) intra-abdominal bleeding"],"answer":0,"image":"md3-109-2-75.jpeg"},{"id":"md3-109-2-76","subject":"md3","topic":"內科-胸腔","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"老人肋骨骨折之後，最常引發何種併發症？","options":["(A) 肺炎","(B) 肺栓塞","(C) 張力性氣胸","(D) 心包膜填塞"],"answer":0,"image":""},{"id":"md3-109-2-77","subject":"md3","topic":"急診醫學","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"有關化學災難（chemical disaster）現場，應依化學災害處理原則，下列何者最為正確？","options":["(A) 傷患的除污（decontamination）應在冷區（cold zone）執行","(B) 檢傷分類（triage）應該在暖區（warm zone）進行","(C) 熱區（hot zone）應只執行傷患的搜救與移出污染區","(D) 化學災難現場仍應先進行檢傷分類之後再執行除污"],"answer":2,"image":""},{"id":"md3-109-2-78","subject":"md3","topic":"內科-內分泌代謝","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"關於高滲透壓高血糖狀態（hyperosmolar hyperglycemic state, HHS），下列敘述何者最不適當？","options":["(A) 血糖值通常＞600 mg/dL，血清重碳酸（serum bicarbonate）＞15 mEq/L，動脈血pH值＞7.3","(B) 血中鈉離子濃度可當成體液缺少的可靠指標","(C) 可能出現代謝性酸中毒（metabolic acidosis）","(D) 血清滲透壓（serum osmolality）與疾病嚴重度、意識狀態改變和昏迷有正相關"],"answer":1,"image":""},{"id":"md3-109-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"A醫師預備要進行新藥品人體試驗，為讓更多病患進入此試驗，且因為現有治療方式效果不佳，A醫師不想在同意書上說明現有之治療方式。下列敘述何者正確？","options":["(A) 依據人體研究法之規定，人體研究之研究對象知情同意須告知事項，不包括其他可能之治療方式及說明，故A醫師可不用告知","(B) 依據醫療法之規定，人體試驗之研究對象知情同意須告知事項，包括其他可能之治療方式及說明，故A醫師須告知","(C) 知情同意是倫理問題，告知事項越多越好，法律並無規定","(D) A醫師可自行決定告知內容"],"answer":1,"image":""},{"id":"md3-109-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"為確保醫事人員執行醫療業務時之安全，依醫療法規定，下列敘述何者錯誤？","options":["(A) 任何人不得以強暴、脅迫、恐嚇或其他非法之方法，妨礙醫療業務之執行，致生危害醫療安全或其設施","(B) 警察機關應協助排除或制止妨礙醫療業務之行為","(C) 如涉及刑事責任者應由醫療機構主動提出告訴","(D) 醫療法第24條規定醫療機構應採必要措施，以確保醫事人員執行醫療業務時之安全"],"answer":2,"image":""},{"id":"md3-110-1-1","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"一位48歲男性因急性腹痛住院。他曾接受過腹部手術，在住院前2天開始感到肚臍周圍有陣發性絞痛，厲害時伴有嘔吐，其腹痛與姿勢無關，仍可平躺，這2天沒有大便。身體診察發現腹部鼓脹，腸子蠕動音較高亢，且頻率增快，但無明顯腹部肌肉僵硬（rigidity）現象。下列各項敘述，何者錯誤？","options":["(A) 本病人之腹部Ｘ光片（plain abdomen）很可能會出現小腸脹大，有air-fluid levels，但看不到大腸之腸氣","(B) 抽血檢驗很可能會發現澱粉酶（amylase）異常上升10倍以上","(C) 其病情很可能與過去的腹部手術有關","(D) 對此病人之處置，不必急著開刀，可先放置鼻胃管，經由靜脈給與補充水分及電解質"],"answer":1,"image":""},{"id":"md3-110-1-2","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"美國Dr. Linda Fried團隊所提出的老人衰弱（frailty）定義不包括下列何者？","options":["(A) 認知功能不佳","(B) 手握力不足","(C) 體重下降","(D) 行動遲緩"],"answer":0,"image":""},{"id":"md3-110-1-3","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"下列何者不是體溫偏低（hypothermia）的危險因子（risk factor）？","options":["(A) 甲狀腺功能低下（hypothyroidism）","(B) 30歲至50歲之間的成年人","(C) 休克（shock）","(D) 營養不良（malnutrition）"],"answer":1,"image":""},{"id":"md3-110-1-4","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"有關高脂血症治療用藥之敘述，下列何者錯誤？","options":["(A) fibric acid derivatives可以減少膽結石的生成","(B) statins可能造成肌肉酸痛","(C) nicotinic acid的適應症包括高密度脂蛋白膽固醇（high-density lipoprotein cholesterol，HDL-C）過低","(D) omega-3 fatty acids可以增加triglyceride（TG）的分解代謝（catabolism）"],"answer":0,"image":""},{"id":"md3-110-1-5","subject":"md3","topic":"內科-感染","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"接受腎移植後可能出現的伺機性感染（opportunistic infection）中，下列何者感染較常出現於移植後一個月內？","options":["(A) Herpesvirus","(B) Aspergillus","(C) Nocardia","(D) Hepatitis C"],"answer":0,"image":""},{"id":"md3-110-1-6","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"臨床上診斷心包填塞（pericardial tamponade）需要高度的警覺性，臨床上心包填塞的Beck's triad是指下列那一種情況？","options":["(A) 低血壓（hypotension），低沉（muffled）的心音，Kussmaul’s徵候","(B) 心包摩擦音（friction rub），低血壓，低沉的心音","(C) 低沉的心音，頸靜脈怒張（jugular vein distention），低血壓","(D) Kussmaul’s徵候，心包摩擦音，心電圖上QRS波電位降低"],"answer":2,"image":""},{"id":"md3-110-1-7","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"許多疾病可引發次發性肺高壓（secondary pulmonary hypertension），下列何者除外？","options":["(A) 肝硬化合併肝門靜脈高壓（liver cirrhosis with portal hypertension）","(B) 心包膜填塞（pericardial tamponade）","(C) 結締性組織疾病（connective tissue disease），如硬皮症","(D) 慢性阻塞性肺病（chronic obstructive pulmonary disease）"],"answer":1,"image":""},{"id":"md3-110-1-8","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"下列有關先天性主動脈狹縮（congenital coarctation of the aorta）之敘述，何者錯誤？","options":["(A) 先天性雙主動脈瓣（congenital bicuspid aortic valve）為常見的合併先天性異常","(B) 通常下肢血壓會較上肢為低","(C) 可在兩側肩胛骨間區域聽到輕度收縮期雜音","(D) 胸部X光檢查在第3～9肋骨上緣可看到凹痕（notching）"],"answer":3,"image":""},{"id":"md3-110-1-9","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"有關慢性心衰竭（左心室射出分量<35%）的口服藥物治療原則，何者錯誤？","options":["(A) angiotensin-converting enzyme inhibitor或angiotensin receptor blocker屬優先選用藥物","(B) 乙型交感神經阻斷劑（β-blocker，如carvedilol or bisoprolol）如臨床無水腫狀況亦應優先選用","(C) aldosterone antagonist（aldactone）即使病人臨床上並無水腫現象亦屬優先選用藥物","(D) 口服硝酸鹽（nitrates）及hydralazine血管擴張劑組合，宜優先選用"],"answer":3,"image":""},{"id":"md3-110-1-10","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"下列何者比較不會造成atrioventricular block？","options":["(A) carotid sinus hypersensitivity","(B) acute inferior wall myocardial infarction","(C) hyperthyroidism","(D) hyperkalemia"],"answer":2,"image":""},{"id":"md3-110-1-11","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"一位50歲男性病人，因急性下壁心肌梗塞，接受緊急心導管治療，在right coronary artery置放支架後血壓130/90 mmHg，心跳90/min，轉至加護病房治療，隔天要拔除femoral sheath時，病人主訴做導管處傷口異常疼痛，之後臉色蒼白，血壓下降至80/50 mmHg，心跳也下降至40/min，則此時立即的處理何者最恰當？","options":["(A) IV dopamine or norepinephrine","(B) IV atropine and fluid challenge","(C) 緊急放置主動脈氣球幫浦","(D) 回導管室做心導管檢查"],"answer":1,"image":""},{"id":"md3-110-1-12","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"下列有關經皮冠狀動脈介入術（PCI）的敘述何者錯誤？","options":["(A) 對穩定心絞痛病人而言，當代PCI與積極藥物治療相比，可較有效減少心絞痛、增加運動耐受、增進生活質量，並減少心肌梗塞及死亡","(B) 使用藥物塗抹金屬支架，比起傳統裸金屬支架，再狹窄率變小，但仍有支架血栓風險","(C) 雖然現今PCI的成功率已大量提升，但在慢性全阻塞病灶的成功率各家報告差異甚大","(D) 糖尿病人合併複雜多處冠狀動脈病灶時，以外科繞道手術治療優於PCI"],"answer":0,"image":""},{"id":"md3-110-1-13","subject":"md3","topic":"急診醫學","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"48歲男性，有高血壓及吸菸史，早上8點進辦公室便感到胸口悶痛、冒冷汗，被同事送至急診，9點做心電圖顯示如下圖，你是急診醫師，下列判斷及處置何者正確？","options":["(A) 儘快完成身體診察，若血壓穩定且無肺水腫，則應等待抽血檢測心肌酶是否升高，以決定診斷及後續處置","(B) 心電圖顯示急性ST段上升心肌梗塞，應盡快通知心臟科醫師並啟動緊急心導管流程","(C) 給與氧氣鼻管2 L/min，aspirin 100 mg，確認血壓穩定後給與硝酸甘油靜脈注射（nitroglycerin IV drip）","(D) 急性藥物溶栓治療可爭取時效，較緊急心導管介入治療療效更好，應優先考慮"],"answer":1,"image":"md3-110-1-13.jpeg"},{"id":"md3-110-1-14","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"李先生，29歲，是位業務員。他過去一年來斷斷續續有下腹痛的現象，伴隨有解便次數增加及軟便情形，且常於上完大號後腹痛減輕。有關病情，下列何者最不正確？","options":["(A) 病史詢問應包含誘發因素、過去的內外科病史、家族大腸直腸腫瘤病史等","(B) 如果常大便大不乾淨，即表示直腸附近長了腫瘤","(C) 如果李先生晚上常去上大號，不一定有器質性的問題","(D) 除身體診察外，須留意其大便的型態及顏色，並詢問體重是否變動"],"answer":1,"image":""},{"id":"md3-110-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"一位48歲男性，因5個月來出現餐後腹痛、腹脹及嘔吐等症狀而就醫。他在5年前曾因胃穿孔而開刀（subtotal 2 gastric resection+Billroth II anastomosis）。病人之body mass index是19 kg/m、血清albumin：3.1（normal：4.3 ～5.4）g/dL、Hb：9.6（normal：13～17）g/dL、MCV（mean corpuscular volume）：106（normal：80～ 100）fL，下列何者是最可能的診斷？","options":["(A) irritable bowel syndrome","(B) bile reflux gastropathy","(C) afferent loop syndrome","(D) Zollinger-Ellison syndrome"],"answer":2,"image":""},{"id":"md3-110-1-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"58歲酒精性肝硬化患者，有食道靜脈瘤出血病史，因吐血而就醫，血壓90/50 mmHg、心跳：148/min，意識不清並躁動，下列的初步處置，何者為宜？①建立中心靜脈導管或兩條周邊靜脈導管以利大量輸液輸注 ② 給與propranolol（β blocker）以降低肝門靜脈壓，減緩出血程度 ③安排大腸鏡檢查 ④給與氣管插管以避免吸入性肺炎","options":["(A) ①②③","(B) ①②④","(C) 僅②③","(D) 僅①④"],"answer":3,"image":""},{"id":"md3-110-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"一位40歲女性病人，主訴胸口燒灼感，正中胸骨下微痛，平躺睡覺時不適加劇，甚至有咳嗽之情形。下列何者為最可能之診斷？","options":["(A) 下壁心肌梗塞","(B) 慢性支氣管炎","(C) 胃食道逆流疾病","(D) 鬱血性心衰竭"],"answer":2,"image":""},{"id":"md3-110-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"一位53歲女性病人主訴食慾不振與茶色尿有10天。身體診察顯示無發燒、無腹部壓痛，但有黃疸。血液檢查3顯示：bilirubin（total/direct）：8.2/5.8 mg/dL、ALT：148 U/L、WBC：5600 /mm。下列進一步之檢查何者對診斷沒有幫助？","options":["(A) reticulocyte count","(B) alkaline phosphatase","(C) hepatitis B surface antigen","(D) abdominal sonography"],"answer":0,"image":""},{"id":"md3-110-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"一位32歲女性主訴全身皮膚發癢與膚色變黑。血液檢查顯示：bilirubin（total/direct）：3.8/2.9 mg/dL，ALT：235 U/L（正常值＜40 U/L），alkaline phosphatase：312 U/L（正常值＜100 U/L）。腹部超音波並無特殊之發現。下列何者對此病人之診斷沒有幫助？","options":["(A) hepatitis B surface antigen","(B) anti-hepatitis A antibody IgG","(C) antimitochondrial antibody","(D) antinuclear antibody"],"answer":1,"image":""},{"id":"md3-110-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"幽門螺旋桿菌（Helicobacter pylori）感染不會造成下列何者疾病？","options":["(A) 消化性潰瘍","(B) 胃食道逆流性疾病","(C) 胃腺癌","(D) 胃黏膜相關淋巴組織淋巴癌"],"answer":1,"image":""},{"id":"md3-110-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"關於Charcot's triad，下列何者不是條件之一？","options":["(A) 右上腹部可以觸及脹大的膽囊","(B) 右上腹部或上腹部疼痛","(C) 發冷發熱","(D) 黃疸"],"answer":0,"image":""},{"id":"md3-110-1-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"對於早期（TNM stage 1或BCLC stage 0 or A）的肝細胞癌（hepatocellular carcinoma），且沒有肝失代償（hepatic decompensation）的情況下，以下那一種治療是較好的選擇？","options":["(A) 標靶治療","(B) 化學治療","(C) 開刀或無線射頻燒灼術（radiofrequency ablation）","(D) 經動脈栓塞化學治療（transcatheter arterial chemoembolization, TACE）"],"answer":2,"image":""},{"id":"md3-110-1-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"關於大腸憩室症（diverticular disease），下列敘述何者正確？","options":["(A) 大部分的大腸憩室炎必須外科手術","(B) 診斷最好的工具是plain abdominal film","(C) 服用抗發炎藥物如mesalazine可以減少症狀性憩室疾病的復發","(D) 抽菸並非大腸憩室炎的危險因子"],"answer":2,"image":""},{"id":"md3-110-1-24","subject":"md3","topic":"內科-腎臟","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"下列何種檢驗對區分腹瀉或腎小管酸血症（renal tubular acidosis）引起正常陰離子隙代謝性酸中毒最具診斷價值？","options":["(A) 尿陰離子隙（urine anion gap）","(B) 血陰離子隙（blood anion gap）","(C) 血鉀濃度","(D) 血氯濃度"],"answer":0,"image":""},{"id":"md3-110-1-25","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"++ 56歲男性病人因意識不清至急診，身體診察發現呼吸22次/分鐘且深沉，初步血液檢查K 4.6 mEq/L、Na 138 -- mEq/L、Cl 99 mEq/L、HCO3 10 mEq/L，動脈血氣分析呈現pH 7.20、pCO2 22 mmHg，此病人最不可能的診斷為：","options":["(A) 乳酸酸血症（lactic acidosis）","(B) 酮酸血症（ketoacidosis）","(C) 急性腹瀉","(D) 慢性腎衰竭"],"answer":2,"image":""},{"id":"md3-110-1-26","subject":"md3","topic":"內科-腎臟","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"65歲女性病人糖尿病已15年，1個月前血中肌酸酐（creatinine）為1.1 mg/dL，3天前開始咳嗽有痰、發燒、呼吸困難、急促，今日意識不清、發燒持續，送至急診，血壓130/70 mmHg，身體診察右下胸有濁音，胸部X光 - 呈現右下肺浸潤病灶，血中白血球16,580 /μL、血中肌酸酐8.5 mg/dL、血中鉀離子6.5 mEq/L、HCO312 mEq/L，則病人此時最不適合接受何種治療？","options":["(A) 連續性靜脈血液過濾術（continuous venovenous hemofiltration）","(B) 間歇性血液透析術（hemodialysis）","(C) 血漿置換術（plasmapheresis）","(D) 腹膜透析（peritoneal dialysis）"],"answer":2,"image":""},{"id":"md3-110-1-27","subject":"md3","topic":"內科-腎臟","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"一名63歲有高血壓的女性病患經體外碎石後確診為草酸鈣結石，下列何項措施無法預防結石復發？","options":["(A) 喝水保持尿量＞2 L/day","(B) 限制飲食鹽分攝取","(C) 改用thiazide為降壓藥","(D) 減少飲食鈣量攝取"],"answer":3,"image":""},{"id":"md3-110-1-28","subject":"md3","topic":"內科-腎臟","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"下列有關腎因性全身纖維化（nephrogenic fibrosing dermopathy）的敘述，何者錯誤？","options":["(A) 與使用gadolinium有關，病症類似scleromyxedema","(B) CKD第3期仍可減量使用gadolinium","(C) 肝臟疾病是罹患此症的危險因子","(D) 血液透析無法清除gadolinium"],"answer":3,"image":""},{"id":"md3-110-1-29","subject":"md3","topic":"內科-腎臟","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"關於急性腎損傷（acute kidney injury）的治療方式，下列何者錯誤？","options":["(A) 針對急性腎損傷的治療原則，目前以支持性療法為主","(B) 可使用等張生理食鹽水來預防顯影劑造成之急性腎損傷","(C) 急性腎損傷若併發高血鉀症，應停用血管張力素轉化酶抑制劑（ACEi）或血管張力素II型受體拮抗劑（ARB）","(D) 羥乙基澱粉溶液（hydroxyethyl starch）可有效改善低血容積引發之急性腎損傷"],"answer":3,"image":""},{"id":"md3-110-1-30","subject":"md3","topic":"內科-腎臟","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"63歲女士因背痛服用diclofenac持續半年，因下肢水腫至門診求診，最近無噁心、嘔吐及腹瀉。身體診察查：血壓126/66 mmHg，心跳每分鐘74下，雙側下肢水腫程度1+。血液檢查：白血球7,900/μL，血色素10.9 g/dL，血小板282,000/μL，球蛋白3.9 g/dL，白蛋白3.0 g/dL，尿素氮12 mg/dL，肌酸酐0.63 mg/dL，血糖84 mg/dL，乳酸去氫酶（LDH）288 U/L（正常值131～250 U/L），尿酸9.7 mg/dL，鈉離子136 mEq/L，鉀離子4.2 mEq/L，膽固醇260 mg/dL，三酸甘油脂80 mg/dL，低密度膽固醇175 mg/dL。尿液試紙檢查：尿蛋白陰性，尿比重1.015，尿液沉渣無紅血球或白血球。尿液總蛋白質與肌酸酐比值為4.907克/克肌酸酐。下列有關此位病患之敘述，何者正確？","options":["(A) 病患蛋白尿的原因可能是非類固醇抗發炎藥（NSAID）造成","(B) 檢anti-phospholipase A2 receptor抗體有助診斷病因","(C) 檢測血清免疫電泳（immunoelectrophoresis）有助診斷病因","(D) 此病患首選治療為低劑量血管張力素II型受體拮抗劑"],"answer":2,"image":""},{"id":"md3-110-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"27歲女性，主訴兩手小關節的酸痛，併有光過敏及Raynaud's phenomenon。在門診的檢查結果為：ANA 1：160 speckled, RF 42 IU/mL（normal<10 IU/mL），hemoglobin：10.7 mg/dL，ESR 37 mm/1h，CRP：0.06 mg/dL，anti-dsDNA 144 IU/mL（normal<120 IU/mL），anti-SSB: 164 AU/mL（normal <120 AU/mL），anti- RNP：241 AU/mL（normal<120AU/mL），尿液常規檢查正常。這位患者最有可能的診斷為何？","options":["(A) rheumatoid arthritis","(B) systemic lupus erythematosus","(C) Sjögren's syndrome","(D) systemic sclerosis"],"answer":1,"image":""},{"id":"md3-110-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"乾癬（psoriasis）病人較常出現下列何種基因？","options":["(A) HLA-A2","(B) HLA-B27","(C) HLA-Cw*06","(D) HLA-DR4"],"answer":2,"image":""},{"id":"md3-110-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"Cytoplasmic ANCA（antineutrophil cytoplasmic antibodies）在下列那一種全身性血管炎中出現的百分比最高？","options":["(A) polyarteritis nodosa","(B) Wegener’s granulomatosis","(C) Goodpasture’s syndrome","(D) Takayasu’s arteritis"],"answer":1,"image":""},{"id":"md3-110-1-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"關於原發性免疫缺陷疾病（primary immunodeficiency diseases）和免疫功能檢查的敘述，下列何者正確？","options":["(A) 當病人血中IgG和IgA免疫球蛋白低下時，表示病人的B淋巴細胞有缺陷，不會與T淋巴細胞缺陷有關","(B) 病人血中T細胞和B細胞的數量會與免疫缺陷的嚴重程度成正比","(C) leukocyte adhesion deficiency病人血中neutrophil的數目常會有上升情形","(D) X-linked agammaglobulinemia病人血中常會有eosinophilia"],"answer":2,"image":""},{"id":"md3-110-1-35","subject":"md3","topic":"內科-感染","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"35歲男性因腦膜炎住院。腦脊髓液培養為李斯特菌（Listeria monocytogenes）。他主訴近一年來曾經發生過2次帶狀疱疹。下列何項檢查對評估病人目前免疫功能最為適當？","options":["(A) serum immunoglobulin levels","(B) blood cell count and lymphocyte phenotype","(C) 50% hemolytic complement（CH50）","(D) nitroblue tetrazolium（NBT）assay"],"answer":1,"image":""},{"id":"md3-110-1-36","subject":"md3","topic":"內科-血液","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"一位36歲病人過去無特殊病史，最近發現頸部及腋下有多顆直徑1～3公分之淋巴結，腹股溝亦有數顆淋巴結，最大者直徑約4公分。頸部淋巴結切片診斷為B細胞瀰漫性大細胞淋巴瘤（diffuse large B cell lymphoma）。對此病人最適當的治療為？","options":["(A) cyclophosphamide, vincristine, prednisolone（COP）","(B) rituximab + COP","(C) cyclophosphamide, doxorubicin, vincristine, prednisolone（CHOP）","(D) rituximab + CHOP"],"answer":3,"image":""},{"id":"md3-110-1-37","subject":"md3","topic":"內科-腫瘤","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"一位40歲亞裔女性病人，沒有抽菸史，最近被診斷有非小細胞肺癌第四期。下列何種基因檢測對她的治療選擇最重要？","options":["(A) K-ras突變","(B) EGFR突變","(C) VEGF receptor突變","(D) BRAF突變"],"answer":1,"image":""},{"id":"md3-110-1-38","subject":"md3","topic":"內科-血液","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"下列有關費城染色體陽性之急性淋巴芽細胞白血病（ALL）的敘述何者錯誤？","options":["(A) 在孩童費城染色體陽性之ALL的發生率較成人高","(B) 有異常之BCR-ABL融合基因","(C) 使用化學治療其療效較費城染色體陰性之ALL為差","(D) 使用imatinib可以改善預後"],"answer":0,"image":""},{"id":"md3-110-1-39","subject":"md3","topic":"內科-血液","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"所謂嚴重型A型血友病（severe hemophilia A）是指血中第八凝血因子（factor VIII）之濃度低於正常值之多少%？","options":["(A) 1%","(B) 2%","(C) 5%","(D) 10%"],"answer":0,"image":""},{"id":"md3-110-1-40","subject":"md3","topic":"內科-腫瘤","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"胃腺癌（gastric adenocarcinoma）依組織學分為diffuse type及intestinal type。以下有關兩者的敘述，何者錯誤？","options":["(A) diffuse type的癌細胞易浸潤於胃壁中，甚至侵犯整個胃，形成所謂的linitis plastica","(B) intestinal type易形成潰瘍性腫瘤（ulcerative mass），好發於胃的賁門部（cardia）","(C) loss of expression of E-cadherin是diffuse type胃腺癌重要的基因變異","(D) intestinal type胃腺癌的致癌機制，可能與H. pylori感染有關"],"answer":1,"image":""},{"id":"md3-110-1-41","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"65歲男性，因大便習慣改變合併有間歇性血便，到院就診。經系列檢查，發現患有一位於乙狀結腸的腫瘤，手術證實為adenocarcinoma，臨床及病理分期為T2N2M0。下列敘述何者正確？","options":["(A) T2：腫瘤已侵犯至腸壁的muscularis propria","(B) N2：腫瘤已轉移2顆局部淋巴結","(C) 標準術後輔助治療為bevacizumab加上化學治療","(D) 病患整體的腫瘤分期為stage II"],"answer":0,"image":""},{"id":"md3-110-1-42","subject":"md3","topic":"內科-血液","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"一位18歲男性，因為輕微黃疸而來門診求醫。身體診察除了鞏膜泛黃之外，並無其他異常。患者血液數據顯示：白血球10,000/μL，分類無明顯異常，血紅素13.3 g/dL，MCV（mean corpuscular volume）84.5 fL，MCHC（mean corpuscular hemoglobin concentration）37.0 g/dL，血小板218,000/μL，總膽紅素輕微升高4.63 mg/dL，直接膽紅素0.77 mg/dL，lactate dehydrogenase（LDH）173 U/L（參考區間140～271），而haptoglobin是＜30 mg/dL（參考區間44～215）。自體免疫相關的檢查無異常。Direct Coombs’ test與indirect Coombs’ test都是negative。其血液抹片如下圖所示。病人平時健康狀況良好，但是有膽結石。他的爸爸與祖父也有類似症狀與臨床表徵。以下關於這位病人最可能的疾病之診斷與治療，何者錯誤？","options":["(A) 這個病人主要是血管內的溶血","(B) 脾臟切除是緩解這類病人之症狀的方式，但是必須小心使用，非嚴重的狀況，不建議使用","(C) 感染常會加劇此病人之臨床症狀，例如黃疸與貧血","(D) 此類疾病緣起於RBC membrane-cytoskeleton之異常"],"answer":0,"image":"md3-110-1-42.jpeg"},{"id":"md3-110-1-43","subject":"md3","topic":"內科-血液","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"一位31歲男性，過去無特殊病史，因血尿與倦怠無力而被送到急診求診。身體診察呈現結膜蒼白與多處皮膚瘀青。實驗室數據顯示：白血球3,000/μL，分類blast 5%，promyelocyte 67%，segmented neutrophil 5%，lymphocyte 18%。血紅素9.0 g/dL，血小板31,000/μL，lactate dehydrogenase（LDH）1549 U/L（參考區間140 ～271）。FDP（fibrin degradation product）131.8 μg/mL（參考值＜4.6），D-dimer＞35.2 μg/mL（參考值＜ 0.56）。其血液抹片之異常細胞顯示如下圖所示。以下關於這位病人最可能的疾病之治療，何者錯誤？","options":["(A) 一般而言，此種疾病在現代的治療之下，長期存活率非常高","(B) 對於這位病人，目前研究顯示tretinoin加上arsenic trioxide的處方，免除傳統的chemotherapy，也可以達到很好的治療效果","(C) arsenic trioxide可能引起QT interval的延長，增加發生arrhythmia的風險。因此使用此藥物時，要定期監測EKG","(D) 單獨tretinoin持續使用，不加上其他療法，也可以維持長期的疾病控制"],"answer":3,"image":"md3-110-1-43.jpeg"},{"id":"md3-110-1-44","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"關於慢性阻塞性肺病（COPD），下列敘述何者最正確？","options":["(A) 最常見的症狀是咳嗽、痰和喘鳴（wheezing）","(B) 在病程最早期身體診察（physical examination）幾乎正常","(C) 氣道的阻力（resistance）增加主要在中型氣道（medium-size airways）","(D) 只要FEV1下降到預期的50％（predicted FEV1），PaO2幾乎都偏低"],"answer":1,"image":""},{"id":"md3-110-1-45","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"45歲男性重症肌無力病人，因為上呼吸道感染後肌無力症狀惡化，且意識紊亂，由家人送至急診處。動脈血 - 氧氣體分析（room air）結果如下：PaCO2 70mmHg，PaO2 55 mmHg，HCO326 mEq/L。下列敘述何者錯誤？","options":["(A) 屬於急性缺氧性呼吸衰竭","(B) 主要是因為呼吸系統發生唧筒衰竭（pump failure）","(C) 必須使用呼吸器協助呼吸","(D) 動脈血之酸鹼值＜7.30"],"answer":0,"image":""},{"id":"md3-110-1-46","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"下列何種因素易導致吸入性肺炎（aspiration pneumonia）？①全身性硬化症（systemic sclerosis） ②巴金森氏症（parkinsonism） ③肺部纖維化（pulmonary fibrosis） ④無脾症（asplenia）","options":["(A) ①④","(B) ①②","(C) ②③","(D) ①③"],"answer":1,"image":""},{"id":"md3-110-1-47","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"有關間質性肺疾（interstitial lung disease）主要病理生理學的變化，下列敘述何者錯誤？","options":["(A) 明顯氣道阻塞現象（airflow limitation）","(B) 全肺活量（total lung capacity）正常或減少","(C) 一氧化碳瀰散量（CO diffusing capacity, DLco）降低","(D) 動脈血氧分壓（PaO2）容易下降"],"answer":0,"image":""},{"id":"md3-110-1-48","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"下列有關結核性肋膜積液（tuberculous pleural effusion）之敘述，何者錯誤？","options":["(A) 成因是結核菌在肺部原發性感染後，直接引起延遲性免疫反應所造成","(B) 積液中細胞分類，淋巴球比率很高，間皮細胞（mesothelial cell）則很少超過5%","(C) 積液中生物性標記（biological marker）adenosine deaminase ≤ 40 U/L時，結核性肋膜積液機會很低","(D) 胸水引流後，不需要做肋膜粘連術（pleurodesis）"],"answer":0,"image":""},{"id":"md3-110-1-49","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"50歲之女性病人，因呼吸困難而前來就診，近距離即可聽到其吸氣時有stridor聲音，最可能診斷為下列何者？","options":["(A) 氣喘","(B) 慢性阻塞性肺病","(C) 肋膜積水","(D) 雙邊聲帶麻痺"],"answer":3,"image":""},{"id":"md3-110-1-50","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"74歲婦女因下肢無力、容易瘀青、下肢水腫約有3個月而就診。病人有退化性關節炎及骨鬆症，服用alendronate 70 mg/week，calcium citrate及Vit.D，並未服用中藥。身體檢查：病人有庫欣氏症體態，四肢肌肉萎縮無力。抽血檢查：ACTH<10 pg/mL，Cortisol<1 μg/dL，電解值正常。下一步的最佳檢查是：","options":["(A) 測dexamethasone suppression test","(B) 測24-h urine free cortisol","(C) 腦部核磁共振","(D) 腎上腺電腦斷層"],"answer":1,"image":""},{"id":"md3-110-1-51","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"25歲女性，有心悸、手抖、怕熱、體重減輕等症狀，正服用抗甲狀腺藥物治療。最近出現發燒、喉嚨痛。下列何處置應最優先考量？","options":["(A) 立即給與抗生素","(B) 檢查白血球及分類","(C) 給與Lugol’s solution","(D) 給與lithium"],"answer":1,"image":""},{"id":"md3-110-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"50歲女性，每日尿量5公升，限水測試後，尿滲透壓並無變化，每小時尿量並未減少。5小時後，靜脈注射desmopressin acetate 2 μg，尿滲透壓上升，每小時尿量減少。下列何者是此病人最適當的診斷？","options":["(A) 原發性多飲症（primary polydipsia）","(B) 滲透性利尿（osmotic diuresis）","(C) 中樞性尿崩症（central diabetes insipidus）","(D) 腎性尿崩症（nephrogenic diabetes insipidus）"],"answer":2,"image":""},{"id":"md3-110-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"實體腫瘤（solid tumor）引起之高血鈣症，最常因腫瘤分泌下列何者而引起？","options":["(A) 副甲狀腺素（parathyroid hormone）","(B) 噬骨細胞活化因子（osteoclast activating factor, OAF）","(C) 副甲狀腺素相關胜肽（parathyroid hormone-related peptide, PTHrP）","(D) 1,25(OH)2 D"],"answer":2,"image":""},{"id":"md3-110-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"糖皮素（glucocorticoids）最不可能出現下列何種副作用？","options":["(A) 抑制生長","(B) 抑制腎上腺","(C) 高血鈣","(D) 胰島素抗性"],"answer":2,"image":""},{"id":"md3-110-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"有關葡萄糖恆定（glucose homeostasis）的敘述，下列何者最為恰當？","options":["(A) 身體許多細胞與器官都參與葡萄糖代謝，肝臟是葡萄糖消耗的最主要器官","(B) 胰島素與升糖素都由胰島細胞所分泌，有互相拮抗的作用","(C) 胰島素在經過肝門脈系統後，約90%會被肝臟分解而失去作用","(D) 胰島素最具有生理活性的部分為C-peptide"],"answer":1,"image":""},{"id":"md3-110-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"有關肥胖的敘述，下列何者錯誤？","options":["(A) 南亞或華人男性之腹部肥胖，其定義為腰圍≧85公分","(B) 瘦素（leptin）由脂肪細胞分泌，為控制食慾的荷爾蒙","(C) 一般而言，肥胖的人血中瘦素濃度比瘦的人高","(D) 2體重90公斤，身高170公分的人，其身體質量指數約為31.1 kg/m"],"answer":0,"image":""},{"id":"md3-110-1-57","subject":"md3","topic":"內科-感染","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"一位26歲男同性戀，出現4週左右發燒、腹瀉、食慾不振、肛門潰瘍和體重減輕，身體診察發現口腔有念珠菌感染，血液培養長出nontyphoidal Salmonella，此時首要考慮下列何種疾病？","options":["(A) 後天免疫不全症候群","(B) 第一型胰島素依賴型糖尿病","(C) 急性骨髓性白血病","(D) 多發性骨髓瘤"],"answer":0,"image":""},{"id":"md3-110-1-58","subject":"md3","topic":"內科-感染","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"77歲病患有糖尿病和高血壓10年，持續接受藥物（metformin、amlodipine、aspirin）穩定控制外，身體健康，並維持規律運動。家人描述病患在最近結束郵輪旅遊4天後，出現漸進性發燒、寒顫、乾咳和腹瀉，來院前意識不清。病人就醫時，檢查發現病患對於環境、時間、和人定位感喪失，體溫39.5℃，血壓96/58 mmHg，脈搏每分鐘128下，呼吸急促，每分鐘36次。肺部聽診左右雙側都有囉音（rales）。血液相發現白血球3 17400/mm，血鈉125 mmol/L。其餘生化檢查正常。血氧飽和度在使用面罩給予每分鐘10L氧氣（濃度60%）下，血氧飽和度是89%。痰液革蘭氏染色（Gram's stain）低倍顯微鏡檢僅發現50～60顆白血球，無可見微生物。緊急胸部X光如圖。此病患最有可能的診斷為何？","options":["(A) 急性心肌梗塞","(B) 急性肺栓塞","(C) 肺結核","(D) 退伍軍人症"],"answer":3,"image":"md3-110-1-58.jpeg"},{"id":"md3-110-1-59","subject":"md3","topic":"內科-感染","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"下列何種抗生素的使用一般不需依腎功能的高低而調整使用劑量？","options":["(A) cefazolin","(B) levofloxacin","(C) metronidazole","(D) vancomycin"],"answer":2,"image":""},{"id":"md3-110-1-60","subject":"md3","topic":"內科-感染","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"下列何者是普通感冒最常見之致病病毒？","options":["(A) rhinoviruses","(B) parainfluenza viruses","(C) coxsackievirus A","(D) coxsackievirus B"],"answer":0,"image":""},{"id":"md3-110-1-61","subject":"md3","topic":"內科-感染","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"下列關於Listeria monocytogenes的敘述，何者正確？","options":["(A) 革蘭氏陽性球菌","(B) 產孢子的革蘭氏陰性桿菌","(C) 會引起腦膜炎","(D) 首選藥物是第三代cephalosporin"],"answer":2,"image":""},{"id":"md3-110-1-62","subject":"md3","topic":"內科-感染","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"下列關於上呼吸道感染的敘述，何者最不恰當？","options":["(A) 健康年輕人突然打噴涕、流鼻水、鼻塞、咳嗽，最可能的致病原是病毒","(B) 健康年輕人有上呼吸道感染症狀，合併有膿性分泌物，但沒有發燒或局部症狀，要考慮續發性細菌性感染，並立即投與細菌藥物治療","(C) 健康年輕人有上呼吸道感染症狀，若病程延長、病情惡化且局部症狀明顯，如副鼻竇處有壓痛時，要考慮續發性細菌性副鼻竇炎","(D) 健康中年人突然發燒、打噴涕、流鼻水、鼻塞、全身肌肉酸痛，其家人兩天前亦有類似症狀，則最可能的致病原是流行性感冒病毒"],"answer":1,"image":""},{"id":"md3-110-1-63","subject":"md3","topic":"內科-感染","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"下列關於二級梅毒（secondary syphilis）的臨床表現與治療，何者錯誤？","options":["(A) 二級梅毒開始抗生素治療後，有小於15%的病人會出現Jarisch-Herxheimer反應","(B) doxycycline或azithromycin是青黴素（penicillin）過敏病人的治療選擇","(C) 約15%的病人有明顯的生殖器病灶","(D) 非梅毒螺旋體反應性試驗（nontreponemal test）結果幾乎總是呈現陽性"],"answer":0,"image":""},{"id":"md3-110-1-64","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"25歲男性氣喘病人至門診求診，主訴最近一個月內有常規性使用吸入性類固醇，白天運動量沒有太大問題，但是一週使用急救藥物短效支氣管擴張劑3～4次，晚上睡覺偶爾會胸悶醒來，尖峰呼氣流量為正常預測值之75%，則此病人氣喘的控制情況為何？","options":["(A) totally controlled","(B) well controlled","(C) partly controlled","(D) uncontrolled"],"answer":[2,3],"image":"","answer_note":"更正:第64題答Ｃ、Ｄ給分。"},{"id":"md3-110-1-65","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"承上題，此病人的最佳藥物使用，應建議如何調整？","options":["(A) 無須調整，維持正常運動量","(B) 增加必要時（as needed）吸入型短效乙二型支氣管擴張劑（short-acting β2 agonist）的使用","(C) 增加規則性（regular）吸入型長效乙二型支氣管擴張劑（long-acting β2 agonist）的使用","(D) 增加必要時（as needed）口服類固醇的使用"],"answer":2,"image":""},{"id":"md3-110-1-66","subject":"md3","topic":"家醫-行為與社區醫學","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"28歲未婚男性主訴自從換工作後，睡不好、經常會半夜全身冒汗且白天嗜睡、腰痠背痛、口乾、胃口不佳，體重雖未見明顯改變，但容易心悸又偶而暈眩，早上都不想去上班，如此已經持續超過3個月。以上述的病史資料，照顧這位病人最適當的診療模式為下列何者？","options":["(A) biomedical family model","(B) holistic social model","(C) biopsychosocial model","(D) ethnomedical cultural model"],"answer":2,"image":""},{"id":"md3-110-1-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"有關男女性青少年在發育特徵的差異，下列敘述何者錯誤？","options":["(A) 青少男的肩膀寬度變得比較寬；青少女則是在髖部變寬","(B) 青少男在肌肉的質量及力量增加較多，而四肢的脂肪組織則是明顯減少","(C) 青少男平均紅血球細胞數（red blood cell mass）及血色素（hemoglobin）數值低於青少女","(D) 青少男青春期開始的時間較晚，且身高成長最大速率（peak height velocity）的出現時間亦較晚"],"answer":2,"image":""},{"id":"md3-110-1-68","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"關於老年人譫妄（delirium）的敘述，下列何者正確？","options":["(A) 譫妄是一種慢性發作的疾病","(B) 譫妄的病患一定很躁動，不會很安靜","(C) 譫妄已有Food and Drug Administration（FDA）核准的治療藥物","(D) 高齡患者手術前先進行老年醫學會診，可降低術後譫妄的發生率"],"answer":3,"image":""},{"id":"md3-110-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"依據美國預防醫學工作小組（US Preventive Services Task Force）的建議，下列何者為實證A級的化學預防（chemoprevention）措施？","options":["(A) 對於準備懷孕的女性每日攝取0.4～0.8 mg（400～800 µg）葉酸","(B) 對於幼稚園孩童給與牙齒塗氟以預防蛀牙","(C) 對於罹患乳癌高風險的婦女給與泰莫西芬（tamoxifen）以預防乳癌","(D) 對於65歲以上老年人給與補充維他命D以預防骨折"],"answer":0,"image":""},{"id":"md3-110-1-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"依據美國預防醫學工作小組（US Preventive Services Task Force）建議，下列那一臨床問題的行為改變並非簡短諮詢（brief counseling）就能改變，需要強度更高更密集的諮詢（intensive counseling）或轉介（referral）？","options":["(A) 皮膚癌高危險青少年的降低紫外線暴露","(B) 性活躍青少年的性病（sexually transmitted disease）預防","(C) 中壯年的酒精濫用（alcohol misuse）預防","(D) 抽菸個案的戒菸諮詢"],"answer":1,"image":""},{"id":"md3-110-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"有關溝通的空間因子（spatial factors），下列敘述何者正確？","options":["(A) 親密空間（intimate space）為60～120公分","(B) 社會空間（social space）為大於360公分","(C) 個人空間（personal space）為0～60公分","(D) 醫護人員因臨床照護常需進入個人空間（personal space）"],"answer":3,"image":""},{"id":"md3-110-1-72","subject":"md3","topic":"內科-胸腔","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"下列有關職業性肺病（occupational lung disease）之敘述，何者最適當？","options":["(A) 成年氣喘病人中，至少10%與其職業暴露有關","(B) 塵肺症（pneumoconiosis）是暴露到有機的固體顆粒所致","(C) 過敏性肺炎（hypersensitivity pneumonitis）是暴露到無機物質所致之廣泛性肺實質病變","(D) 最有效之預防策略是個人防護具之使用"],"answer":0,"image":""},{"id":"md3-110-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"有關末期病人呼吸困難（dyspnea）的評估及處置，下列敘述何者最不適當？","options":["(A) 癌症末期病人中最常出現呼吸困難的是肺癌病人","(B) 應先尋找可逆的原因，予以適當處置","(C) 社會、心理或靈性等層面都可能引起末期病人呼吸困難的症狀","(D) 無論末期病人呼吸困難的原因為何，目前建議都可以使用嗎啡予以控制"],"answer":3,"image":""},{"id":"md3-110-1-74","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"關於食道裂孔疝氣（hiatal hernia），下列何者錯誤？","options":["(A) 係指部分胃臟滑脫至膈肌食道裂孔之上方","(B) 分滑型（sliding）疝氣和食道旁（paraesophageal）疝氣","(C) 食道旁疝氣較為常見","(D) 滑型疝氣係指食道胃連接（gastroesophageal junction）上移至胸腔"],"answer":2,"image":""},{"id":"md3-110-1-75","subject":"md3","topic":"影像醫學","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"下列兩張圖為肝之超音波掃描，以下相關敘述何者錯誤？","options":["(A) 肝內有實質性腫塊","(B) 有呈現膽結石","(C) 箭號所指為肝門靜脈","(D) 若肝門靜脈內有血栓（portal vein thrombosis），最常見的診斷是膽管癌"],"answer":3,"image":"md3-110-1-75.jpeg"},{"id":"md3-110-1-76","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"下列關於糖尿病酮酸中毒（diabetes ketoacidosis, DKA）之敘述，何者最不適當？","options":["(A) 臨床表現與高血糖、液體不足（volume depletion）和酸血症（acidosis）有關","(B) 臨床檢驗會出現呼吸性酸血症（respiratory acidosis）","(C) DKA的誘發因子包括胰島素注射不足、感染、懷孕等","(D) 病人全身鉀離子通常不足"],"answer":1,"image":""},{"id":"md3-110-1-77","subject":"md3","topic":"內科-心臟血管","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"下列何種臨床情況，最不適合使用阿托平（atropine）作為心跳低於每分鐘50下的治療？","options":["(A) 收縮壓低於90 mmHg且心電圖顯示為第二度第一型房室傳導阻滯病人","(B) 接受心臟移植病人合併呼吸急促的竇性心搏過緩","(C) 意識昏迷的病人合併竇性心搏過緩","(D) 嚴重胸痛的病人合併第一度房室傳導阻滯"],"answer":1,"image":""},{"id":"md3-110-1-78","subject":"md3","topic":"急診醫學","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"18歲高中男生身高182公分，體重58公斤，平常喜歡打籃球，昨天打籃球時，突然感到左胸疼痛，感覺是尖銳的痛且深呼吸更嚴重，有喘不上來的感覺，他最有可能的診斷為何？","options":["(A) 心肌梗塞","(B) 肺栓塞","(C) 氣胸","(D) 心包膜炎"],"answer":2,"image":""},{"id":"md3-110-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"甲藥廠想要找乙醫師進行骨關節炎之非類固醇止痛藥（NSAIDs）的新藥臨床試驗計畫。下列敘述何者錯誤？","options":["(A) 人體試驗必須在受試者自由意志下同意，換言之，必須要有告知後同意","(B) 受試者對於研究內容要有一定程度的了解","(C) 試驗進行過程應有適當的監督與保護機制","(D) 人體試驗前不一定要有實驗室實驗或動物實驗"],"answer":3,"image":""},{"id":"md3-110-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"40歲胰臟癌末期病人，呈現癌症惡體質（cachexia），因疼痛難以控制入住安寧病房。病人表示，弟弟最了解他，知道自己不願意急救的意願，並已預立弟弟為醫療委任代理人。若病人昏迷時，下列家屬簽具拒絕心肺復甦術的順位，何者正確？①父母 ②配偶 ③弟弟 ④成人子女","options":["(A) ①②③④","(B) ②④①③","(C) ③②④①","(D) ②①④③"],"answer":2,"image":""},{"id":"md3-110-2-1","subject":"md3","topic":"急診醫學","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"82歲的李奶奶最近有些小感冒，醫師開了一些藥物給她吃。從3天前起，她開始活動力下降，胃口不好，昨天開始發燒，今天早上家人發現無法叫她起床，人不太清醒，於是趕快送到急診。對於本病人之初始評估（initial evaluation），下列那一個項目最不需要？","options":["(A) 詳細的病史查詢，包括含用藥史","(B) 腰椎穿刺","(C) 身體檢查應包括神經學檢查","(D) 血液檢驗包括全血球計數、電解質、肝功能、腎功能檢查"],"answer":1,"image":""},{"id":"md3-110-2-2","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"下列何種狀況不是使用angiotensin-converting enzyme（ACE）inhibitors的禁忌？","options":["(A) 腎功能持續惡化","(B) 低血鉀","(C) 懷孕","(D) 雙側腎動脈狹窄"],"answer":1,"image":""},{"id":"md3-110-2-3","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"有關自體免疫疾病在男性與女性之間，其發生率（incidence）與特色的敘述，下列何者最不適當？","options":["(A) 自體免疫甲狀腺疾病（autoimmune thyroid diseases）、硬皮症（scleroderma）與全身性紅斑狼瘡，都是女性的發生率較高","(B) 類風濕性關節炎之女性患者，在懷孕期間該疾病可能比較容易緩解","(C) 第一型糖尿病（type 1 diabetes mellitus），女性的發生率較高","(D) 僵直性脊椎炎（ankylosing spondylitis），男性的發生率較高"],"answer":2,"image":""},{"id":"md3-110-2-4","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"一位70歲男性糖尿病患，長期服用glimepiride、metformin、acarbose、pioglitazone控制血糖。接受血管攝影4天 - 後，因意識不清被送至急診。抽動脈血液檢驗結果顯示代謝性酸中毒（pH 6.8、Pco2 39.3 mmHg、HCO36.2 ++- mEq/L）、BUN 86 mg/dL、creatinine 6.8 mg/dL、Na 135 mEq/L、K 6.0 mEq/L、Cl90 mEq/L、glucose 131 mg/dL、lactic acid 26.6 mmol/L（參考值0.5～2.2 mmol/L）、ketone body（negative）。其所服用的藥物中，何者與此急性病變最具相關性？","options":["(A) glimepiride","(B) metformin","(C) acarbose","(D) pioglitazone"],"answer":1,"image":""},{"id":"md3-110-2-5","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"下列有關腹瀉的敘述，何項最適當？","options":["(A) 急性腹瀉中大約有30～40% 是因為傳染原（infectious agents）所造成","(B) 輪狀病毒（rotavirus）引起的急性腹瀉，其潛伏期通常小於6小時","(C) 腎功能不全病人的腹瀉應該優先使用bismuth subsalicylate治療","(D) 長期使用酒精（ethanol）可能造成分泌型腹瀉（secretory-type diarrhea）"],"answer":3,"image":""},{"id":"md3-110-2-6","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"胡先生76歲患有糖尿病、高血壓、慢性腎功能不全及心房顫動於心臟科門診追蹤治療，主訴近兩天頭暈、倦怠及運動後呼吸急促之症狀，在急診測得之心跳呈現不規則，每分鐘約為32下，以下何者門診用藥最不可能和其症狀相關？","options":["(A) 乙型交感神經阻斷劑（β-blocker）","(B) 毛地黃（digoxin）","(C) 鈣離子通道阻斷劑（calcium channel blocker）","(D) 甲型交感神經阻斷劑（α-blocker）"],"answer":3,"image":""},{"id":"md3-110-2-7","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"80歲肥胖女性住院病人，因為漸進出現的雙下肢水腫，夜間喘咳和新出現的輕微發燒，在深夜由家人送來急診。醫師在檢查中包含了B型利鈉胜肽（B-type natriuretic peptide, BNP），檢查數值為100 pg/mL，有關該項檢查應用在心衰竭診斷上下列何者正確？","options":["(A) 這一位喘的病人如果出現BNP上升到100 pg/mL，就可以診斷是左心室收縮功能衰竭","(B) 在肥胖的心衰竭病人，BNP數值會略低於不肥胖的心衰竭病人","(C) 在腎衰竭的病人，如果有心衰竭，BNP也不容易上升","(D) 住院中會以反覆系列測量BNP當作心衰竭治療方針的依據"],"answer":1,"image":""},{"id":"md3-110-2-8","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"65歲有冠心症，經乙型阻斷劑（beta blockers）治療且症狀穩定的男性病人，因為咳嗽與黃色痰，接受胸部X光檢查，結果發現兩側肺野正常但呈現紆曲的（tortuous）主動脈，同時有縱膈腔擴大。接下來的電腦斷層檢查顯示在胸部降主動脈有4公分大小的主動脈瘤，沒有剝離狀況。這位病人的主動脈瘤，下列處置何者較佳？","options":["(A) 每年檢查一次胸部電腦斷層，動脈瘤若有每年增大超過1公分，轉介外科手術處理","(B) 立刻會診外科手術處理","(C) 每年檢查一次胸部電腦斷層，動脈瘤大小達到4.5公分時，轉介外科手術處理","(D) 每年檢查一次心臟超音波檢查（transthoracic echocardiography）追蹤動脈瘤，如果增加大於1公分即轉介外科手術處理"],"answer":0,"image":""},{"id":"md3-110-2-9","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"下列何者成年人的先天性心臟病於出生時即為cyanotic type？","options":["(A) atrial septal defect","(B) ventricular septal defect","(C) tetralogy of Fallot","(D) patent ductus arteriosus"],"answer":2,"image":""},{"id":"md3-110-2-10","subject":"md3","topic":"急診醫學","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"22歲女性因心悸來到急診求診。生命徵象為：意識清楚，體溫37℃，心跳每分鐘160次，血壓110/70毫米汞柱，呼吸每分鐘24次。心電圖如下，以下處置何者最不恰當？","options":["(A) 胸前電擊100J","(B) 給與adenosine靜脈注射治療","(C) 對病患實施carotid sinus massage","(D) 給與verapamil靜脈注射治療"],"answer":0,"image":"md3-110-2-10.jpeg"},{"id":"md3-110-2-11","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"當高血壓病人同時合併下列狀況時，較不考慮有次發性高血壓？","options":["(A) 抽血檢查發現低血鉀症","(B) 易有頭痛、心悸和盜汗","(C) 睡覺會打鼾，且白天常想睡","(D) 高血脂症"],"answer":3,"image":""},{"id":"md3-110-2-12","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"一位55歲男性病人在3個月之內發生數次暈厥（syncope），每次都是坐姿時發生，每次都持續約兩分鐘後自然恢復意識，沒有任何後遺症；初步的身體診察並未發現心血管方面的異常，病人臥姿的血壓是130/80 mmHg，沒有姿態性低血壓，以下何項診斷工具最不可能發現導致暈厥的原因？","options":["(A) 肺功能檢查","(B) 心臟超音波","(C) 24-小時心電圖（Holter monitoring）","(D) 心臟電生理檢查（electrophysiological study）"],"answer":0,"image":""},{"id":"md3-110-2-13","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"下列何項因素不會影響正確的血壓測量？","options":["(A) 受檢者的身體姿勢","(B) 受檢者的手臂尺寸","(C) 使用的儀器種類","(D) 受檢者的性別"],"answer":3,"image":""},{"id":"md3-110-2-14","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"肝硬化病人身體診察常發現的身體表徵，下列何者錯誤？","options":["(A) 胸前有蜘蛛痣","(B) 紅掌","(C) 男性出現女乳症","(D) 下肢靜脈曲張"],"answer":3,"image":""},{"id":"md3-110-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"有關dumping syndrome，下列何者為最常見的原因？","options":["(A) 細菌過度滋生（bacteria overgrowth）","(B) 攝食過多的碳水化合物（carbohydrate）","(C) 膽汁排出受阻","(D) 切斷迷走神經（vagus nerve）導致消化道蠕動異常"],"answer":1,"image":""},{"id":"md3-110-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"62歲肝硬化合併黃疸患者，抽血結果如下：albumin 2.55 g/dL（正常3.5～5.0）；ammonia 98 μg/dL（正常＜ 70）；bilirubin（total）：21.05 mg/dL（正常0.2～1.0）；PT 16.3 seconds（正常＜11.2）；ALT（GPT）100 U/L（正常＜40），下列何者不宜作為本病人肝衰竭之指標？","options":["(A) albumin","(B) ammonia","(C) bilirubin","(D) ALT"],"answer":[1,3],"image":"","answer_note":"更正:第16題答Ｂ、Ｄ給分。"},{"id":"md3-110-2-17","subject":"md3","topic":"內科-感染","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"為了避免藥物不良反應，結核病人在開始行抗結核藥物治療後，宜定期做下列之血液檢查，除了：","options":["(A) ALT（GPT）","(B) bilirubin","(C) creatine kinase（CK）","(D) 紅白血球計數"],"answer":2,"image":""},{"id":"md3-110-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"下列有關原發性膽管性肝硬化（primary biliary cirrhosis）的敘述，何者錯誤？","options":["(A) 多數病人抗粒線體抗體（antimitochondrial antibody）為陽性","(B) 可發生xanthelasma及xanthomata","(C) 以ursodeoxycholic acid治療可治癒此疾病","(D) 血清免疫球蛋白（immunoglobulin）上升主要為IgM"],"answer":2,"image":""},{"id":"md3-110-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"30歲女性疲倦、關節痛及肝指數異常至胃腸科門診就診。病人無搔癢也無藥物濫用過去史。抽血檢查發現AST/ALT：380/410 U/L（reference value：≦40/40）、HBsAg陰性反應、anti-HCV Ab陰性反應、anti-nuclear Ab（ANA）陽性反應。則下列敘述，何者正確？","options":["(A) antibodies to liver-kidney microsomes（anti-LKM）也可能呈現陽性反應","(B) 此種病人併發肝細胞癌的機會比病毒性肝炎相關肝硬化高","(C) 抗平滑肌抗體（anti-smooth-muscle antibodies, ASMA）應呈現陰性","(D) 肝穿刺檢查常發現慢性非化膿性破壞性膽管炎（chronic nonsuppurative destructive cholangitis）"],"answer":0,"image":""},{"id":"md3-110-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"有關慢性B型肝炎的敘述，下列何者錯誤？","options":["(A) 病毒量的高低與肝癌發生的風險成正比，因此高病毒量患者都應該要積極接受抗病毒藥物治療","(B) 慢性B型肝炎可以有肝外症狀的表現，較常見的是arthralgia及arthritis","(C) 肝臟纖維化的程度，美國常使用histologic activity index（HAI）分為0～6分，歐洲常使用METAVIR系統分為0～4分","(D) 肝臟纖維化的判斷也可以非侵襲性方式得知，如抽血檢測纖維的生物標誌（serum biomarkers of fibrosis）及利用影像學方式檢測肝臟的彈性（liver elasticity）"],"answer":0,"image":""},{"id":"md3-110-2-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"以下關於潰瘍性大腸炎（ulcerative colitis）與克隆氏症（Crohn's disease）的描述，何者正確？","options":["(A) 潰瘍性大腸炎較容易有skip lesion","(B) 克隆氏症比較不容易有全身性症狀","(C) 克隆氏症比較容易併發腸道狹窄","(D) 潰瘍性大腸炎比較不會有黏液血便"],"answer":2,"image":""},{"id":"md3-110-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"關於急性胰臟炎的嚴重度評估，可包括三大類，如risk factors for severity、markers of severity at admission or within 24 hours及markers of severity during hospitalization，下列敘述何者正確？","options":["(A) 2與嚴重程度相關的因子（risk factors for severity）包括有年齡＞60歲、BMI＜30 kg/m、具有comorbid diseases","(B) markers of severity at admission or within 24 hours之中包括有hemodilution（hematocrit＜40%）","(C) markers of severity at admission or within 24 hours之中包括有core temperature＜36度或＞38度、heart rate＞90 beats/min","(D) markers of severity during hospitalization包括有elevated C-reactive protein（CRP）及elevated blood sugar"],"answer":2,"image":""},{"id":"md3-110-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"慢性胃炎（chronic gastritis）為上消化道內視鏡檢查下常見的現象，下列敘述何者正確？","options":["(A) 慢性胃炎可根據其範圍分為type A: body-predominant gastritis及type B: antral-predominant gastritis","(B) body-predominant gastritis主要導因為Helicobacter pylori infection，而antral-predominant gastritis主要導因為autoimmune related problem","(C) autoimmune gastritis的病程會依循multifocal atrophic gastritis、gastric atrophy、metaplasia，最後可能導致gastric adenocarcinoma","(D) antral-predominant gastritis與pernicious anemia有關連，病人血液中會有antibodies against parietal cells及intrinsic factor"],"answer":0,"image":""},{"id":"md3-110-2-24","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"18歲男性病人，10天前喉嚨痛，當時血液肌酸酐1.0 mg/dL。最近4天有發燒、高血壓、少尿、水腫、運動性呼吸困難。血液肌酸酐1.6 mg/dL，明顯的補體下降，尿液紅血球25～40/HPF，紅血球圓柱體（RBC cast） +，蛋白質1+。最不可能的診斷是：","options":["(A) 鏈球菌感染後之腎絲球腎炎（poststreptococcal glomerulonephritis）","(B) 韋氏肉芽腫（Wegener’s granulomatosis）","(C) 紅斑性狼瘡腎炎（lupus nephritis）","(D) 心內膜炎（infective endocarditis）"],"answer":1,"image":""},{"id":"md3-110-2-25","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"巴特氏症候群（Bartter’s syndrome）的腎小管上皮細胞功能失調出現在：","options":["(A) 近端腎小管","(B) 亨利氏環粗上升支","(C) 遠端腎小管","(D) 集尿小管"],"answer":1,"image":""},{"id":"md3-110-2-26","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"一位50歲無糖尿病男性，生化檢驗結果呈現血清肌酸酐3.5 mg/dL，尿素氮40.1 mg/dL，估算之腎絲球過濾率20 mL/min，白蛋白4.0 g/dL，血鉀4.1 mmol/L，血鈣2.05 mmol/L，血磷4.5 mg/dL，25(OH) vitamin D 10 ng/mL，intact parathyroid hormone 255 pg/mL。下列治療何者最優先？","options":["(A) cinacalcet","(B) cholecalciferol","(C) calcitriol","(D) ergocalcitriol"],"answer":2,"image":""},{"id":"md3-110-2-27","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"5下列4類無症狀性大腸桿菌菌尿症（＞10colony forming units/mL）病人，何者最需要接受抗生素治療？","options":["(A) 24歲性活躍女性","(B) 30歲懷孕12週女性","(C) 50歲糖尿病女性","(D) 75歲置有長期導尿管男性"],"answer":1,"image":""},{"id":"md3-110-2-28","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"王先生為54歲男性，因IgA nephropathy進展至末期腎臟病，無其他過去病史。若要為王先生建議腎臟替代療法，下列何種療法的長期（大於1年）存活率及生活品質最佳？","options":["(A) 血液透析（hemodialysis）","(B) 腹膜透析（peritoneal dialysis）","(C) 連續性靜脈對靜脈血液過濾術（continuous venovenous hemofiltration）","(D) 腎臟移植（renal transplantation）"],"answer":3,"image":""},{"id":"md3-110-2-29","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"一位56歲的高血壓患者，因血壓控制的需要，已服用利尿劑一段時間。某天晚上十點多鐘，患者突覺左側大腳趾、足踝關節及腳背紅腫劇痛。送急診後，左腳X光檢查正常，ESR 28 mm/1h，CRP 11.4 mg/dL（正常<0.8 mg/dL），WBC 9650/μL。下列何種檢查對診斷最有幫助？","options":["(A) septic work-up","(B) joint fluid examination","(C) anticardiolipin antibodies","(D) serum uric acid level"],"answer":1,"image":""},{"id":"md3-110-2-30","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"28歲女性近2年來，下肢偶會有隆起性的紫斑，並有3次急性氣喘發作。經服用類固醇30 mg/day 3天之後，氣3喘及紫斑均很快消失。抽血檢查發現WBC 9600/μL，platelet count 287×10/μL，但eosinophil高達27%。血清學檢查發現：ANA 1：80，ESR 17 mm/1h，CRP 0.81 mg/dL。下列何種檢查陽性對疾病的診斷最有幫助？","options":["(A) antineutrophil cytoplasmic antibodies","(B) IgE","(C) IgG4","(D) sputum smear"],"answer":0,"image":""},{"id":"md3-110-2-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"36歲的女性，自覺有微燒並發現上眼瞼及臉頰部有紅疹。近2週來，早上醒來時身體無力，必須側身以雙手扶持起床。血液常規檢查正常，血清學檢查ANA 1：40 speckled，C3 116 mg/dL，C4 9.8 mg/dL，ESR 31 mm/1h，CRP 1.1 mg/dL。最有可能的診斷為下列何者？","options":["(A) dermatomyositis","(B) systemic lupus erythematosus","(C) eczema","(D) photosensitivity"],"answer":0,"image":""},{"id":"md3-110-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"21歲男性，因為肺炎（pneumonia）住院診療。痰液培養顯示為流行性感冒嗜血桿菌（Haemophilus influenzae），經詢問病史，病人自15歲起便曾因肺炎於不同醫院住院多次，並一直有慢性鼻竇炎（chronic sinusitis）與支氣管擴張（bronchiectasis）問題。病人本次血液常規WBC = 9,700 /μL，Hb 14.4 g/dL，platelet count = 198 k/μL，neutrophil = 74.2%，lymphocyte = 17.7%，monocytes = 6.6%，eosinophil = 1.1%，basophil = 0.4%。後續下列何項檢查對評估病人的免疫功能缺損最為適當？","options":["(A) CD4與CD8淋巴細胞計數","(B) 血中免疫球蛋白G（serum IgG）","(C) 血中免疫球蛋白E（serum IgE）","(D) 血中第三補體與第四補體（serum C3 and C4）"],"answer":1,"image":""},{"id":"md3-110-2-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"下列何項檢驗對確診全身性紅斑狼瘡（systemic lupus erythematosus）幫助最小？","options":["(A) 抗核抗體（anti-nuclear antibodies）","(B) 第四補體（C4）","(C) 全血球計數與血球分類（complete blood count and differential count）","(D) 抗SSA抗體（anti-SSA antibodies）"],"answer":3,"image":""},{"id":"md3-110-2-34","subject":"md3","topic":"內科-腫瘤","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"一位40歲女性，有癌症家族史，來諮詢她發生乳癌的風險。她有兩個姑媽在60歲左右時診斷乳癌，爸爸有淋巴癌，堂兄有結腸癌，她的姑媽BRCA-1和BRCA-2基因檢測的結果為陰性。下列敘述何者正確？","options":["(A) 相關的基因遺傳非來自父系","(B) 她是發生癌症的高危險群，應該每年接受正子攝影（positron emission tomography [PET] scans）檢查","(C) 應考慮BRCA-1及BRCA-2以外的基因檢測","(D) 她應開始服用芳香環轉化酶抑制劑（aromatase inhibitor）以降低風險"],"answer":2,"image":""},{"id":"md3-110-2-35","subject":"md3","topic":"內科-腫瘤","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"上皮生長激素受體（epidermal growth factor receptor, EGFR）的標靶治療（包括EGFR small-molecule inhibitor, anti-EGFR antibody, anti-HER2 antibody）不被應用在下列何種癌症上？","options":["(A) 結腸癌（colon cancer）","(B) 肺癌（lung cancer）","(C) 腸平滑肌惡性肉瘤（intestinal leiomyosarcoma）","(D) 乳癌（breast cancer）"],"answer":2,"image":""},{"id":"md3-110-2-36","subject":"md3","topic":"內科-腫瘤","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"標靶治療藥物imatinib是何種蛋白的抑制劑？","options":["(A) Bcr-Abl","(B) PML-RARα","(C) NF-κB","(D) EGFRα"],"answer":0,"image":""},{"id":"md3-110-2-37","subject":"md3","topic":"內科-血液","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"下列有關lupus anticoagulant陽性病患的描述，何者錯誤？","options":["(A) 病人通常沒有出血傾向","(B) activated partial thromboplastin time（aPTT）經常延長，但在混合正常血漿的試驗（mixing test）中，會變為正常","(C) 不是systemic lupus erythematosus（SLE）的患者，也可能出現lupus anticoagulant","(D) VDRL梅毒檢驗可能呈陽性反應"],"answer":1,"image":""},{"id":"md3-110-2-38","subject":"md3","topic":"內科-血液","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"一位30歲懷孕婦女，主訴其姊姊在生產時曾大量出血，擔心自己也會有類似的情形，因此來求診。詢問過去病史，除月經量較多外，無其他明顯出血情形，且未服用任何藥物或補藥。身體檢查發現，身上無明顯紫斑或其他異常情況，關節正常。血液檢查結果如下：血紅素11.5 g/dL，白血球5,200/μL，分類正常，血小板275,000/μL，bleeding time 14分（正常值：小於7.1分），prothrombin time（PT）12秒（正常值：小於12.5秒），activated partial prothrombin time（aPTT）44秒（正常值：小於36秒）。這位婦女最可能得了什麼病？","options":["(A) hemophilia A","(B) von Willebrand disease","(C) chronic hepatitis","(D) uremia"],"answer":1,"image":""},{"id":"md3-110-2-39","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"下列關於原發性肺癌的敘述，何者錯誤？","options":["(A) 肺癌局部擴散會造成膈神經（phrenic nerve）麻痺，導致Horner氏症候群（Horner's syndrome）","(B) Horner氏症候群症狀包括眼球陷沒（enophthalmos）、眼皮下垂（ptosis）、瞳孔縮小（miosis）、無汗（anhydrosis）","(C) 肺癌長在肺尖局部擴散會侵犯第8頸神經、第1胸神經、第2胸神經，導致Pancoast症候群（Pancoast syndrome）","(D) Pancoast症候群症狀包括肩痛並輻射至手臂尺骨（ulnar）側"],"answer":0,"image":""},{"id":"md3-110-2-40","subject":"md3","topic":"內科-腫瘤","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"病患初診斷膀胱癌時的期別，最常見的是：","options":["(A) 表淺（superficial）型","(B) 平滑肌侵犯（muscle-invasive）型","(C) 轉移（metastatic）型：轉移至肺部","(D) 轉移（metastatic）型：轉移至肝臟"],"answer":0,"image":""},{"id":"md3-110-2-41","subject":"md3","topic":"內科-血液","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"對缺鐵性貧血的敘述，下列何者錯誤？","options":["(A) 常見於生理期經血過多的女性","(B) 慢性痔瘡出血是男性缺鐵性貧血的常見原因之一","(C) 為了減輕體重而接受胃腸繞道手術的人，可能併發缺鐵性貧血","(D) 有遺傳性海洋性貧血的人容易有缺鐵性貧血"],"answer":3,"image":""},{"id":"md3-110-2-42","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"陳先生每天抽一包菸已40年，最近一年來，走路爬坡出現呼吸困難現象，門診的胸部Ｘ光檢查顯現兩側肺野皆透亮較黑，若要安排肺功能檢查，下列項目何者最適當？","options":["(A) 篩檢肺功能（screening spirometry），包括FVC, FEV1, FEV1/FVC","(B) 標準肺功能（standard spirometry），包括FVC, FEV1, FEV1/FVC及肺容積","(C) 一氧化碳肺瀰散量檢查（CO diffusing capacity test）","(D) 支氣管激發試驗（bronchoprovocation test）"],"answer":1,"image":""},{"id":"md3-110-2-43","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"下列何者不是廣泛性支氣管擴張症（diffuse bronchiectasis）常見的致病原因？","options":["(A) Kartagener's syndrome","(B) 游離肺（pulmonary sequestration）","(C) 反覆吸入性肺炎","(D) 免疫球蛋白缺乏症（hypogammaglobulinemia）"],"answer":1,"image":""},{"id":"md3-110-2-44","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"有關類肉瘤病（sarcoidosis），下列敘述何者錯誤？","options":["(A) 致病機轉與T淋巴球（T lymphocyte）及巨噬細胞（macrophage）激活有關","(B) 急性期病患血清中angiotensin-converting enzyme（ACE）值會升高","(C) 通常以兩側肺門淋巴結腫大表現，組織切片診斷出noncaseating granuloma","(D) 肺泡灌洗術（bronchoalveolar lavage）發現淋巴球數目及比例增高，CD4/CD8比例會下降"],"answer":3,"image":""},{"id":"md3-110-2-45","subject":"md3","topic":"內科-感染","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"24歲男性，因為高燒、喉嚨不適與肌肉酸痛，被診斷出罹患H3N2流感。有關此病症之敘述，下列何者錯誤？","options":["(A) 屬於B型流感，曾因為抗原突變造成全球大流行","(B) 以oseltamivir治療效果優於adamantanes","(C) 可以用疫苗加以預防，需每年定期接種","(D) 肺炎是最重要的併發症"],"answer":0,"image":""},{"id":"md3-110-2-46","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"23歲女性幼稚園老師，無過往病史，因4天的咳嗽、胸痛至急診求治。體溫38.8°C，呼吸不順暢，聽診顯示左側下肺部呼吸聲減弱，觸診之觸覺震顫（tactile fremitus）降低，叩診左下肺部有濁音（dullness）。在尚無檢驗室結果可供參考之前，下列敘述何者最正確？","options":["(A) 肺栓塞是最可能的診斷","(B) 最可能是病毒感染","(C) 為孕齡女性，不應作胸部X光攝影","(D) 需考慮胸腔穿刺術（thoracentesis）"],"answer":3,"image":""},{"id":"md3-110-2-47","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"下列有關原發性肺纖維化（idiopathic pulmonary fibrosis）之敘述，何者錯誤？","options":["(A) 是自發性間質性肺炎（idiopathic interstitial pneumonia）中最常見的一種疾病","(B) 在病理變化上是屬於非特異性間質性肺炎（nonspecific interstitial pneumonia）","(C) 在胸部電腦斷層影像上常呈現蜂窩狀（honeycombing appearance）","(D) 對類固醇的治療反應不佳"],"answer":1,"image":""},{"id":"md3-110-2-48","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"28歲女性因在前額中部頭痛、噁心4星期後來診。病人月經一向正常，直到3年前，月經量開始減少且變得不規則。此次經檢測尿液發現懷孕反應陽性且尿糖陽性。身體檢查發現牙齒間隙大，舌頭大且下顎突出，後頸部有黑色棘皮症但無水牛肩或腹部條紋，下一步應做那一項檢查最為恰當？","options":["(A) 血清β-hCG test","(B) 血糖測定","(C) 頭部電腦斷層","(D) 測量IGF-I"],"answer":3,"image":""},{"id":"md3-110-2-49","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"一位25歲女性，過去沒有任何病史，因為神智不清被送到急診處。身體檢查沒有異常，但是血糖35 mg/dL，一小時後經靜脈注射葡萄糖輸液，神智恢復。隔日早晨又出現低血糖45 mg/dL，同時被檢測有高血鈣13 mg/dL。她最不可能有的病灶為：","options":["(A) 胰島素瘤（insulinoma）","(B) 副甲狀腺瘤（parathyroid adenoma）","(C) 甲狀腺髓質癌（medullary thyroid carcinoma）","(D) 泌乳激素瘤（pituitary prolactinoma）"],"answer":2,"image":""},{"id":"md3-110-2-50","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"35歲女性病患，體檢時發現血壓偏高。她主訴近2個月來覺得頭痛、全身無力和倦怠。理學檢查除了血壓高（160/100 mmHg）以外，並無特殊發現。血液檢驗發現血中肌酸酐（creatinine）1.1 mg/dL，鈉離子137 mmol/L，鉀離子2.6 mmol/L，動脈血液氣體檢查發現代謝性鹼中毒（metabolic alkalosis），血清中腎素（renin）為0.04 ng/mL/hr（參考值，1～5 ng/mL/hr）；血中皮質醛酮濃度（plasma aldosterone concentration）為39.2 ng/dL（參考值，5～30 ng/dL）；血中腎上腺刺激素（adrenocorticotropin）為12 pg/mL（參考值，10～ 65 pg/mL）。此病患最有可能的診斷為何？","options":["(A) 腎動脈狹窄（renal artery stenosis）","(B) 甲狀腺亢進（hyperthyroidism）","(C) 原發性皮質醛酮症（primary aldosteronism）","(D) 庫欣氏症候群（Cushing's syndrome）"],"answer":2,"image":""},{"id":"md3-110-2-51","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"關於低血糖（hypoglycemia）之敘述，下列何者錯誤？","options":["(A) 低血糖時，血中皮質醇（cortisol）濃度會上升","(B) Whipple’s triad包括低血糖之症狀應隨血糖上升而消失或減緩","(C) 正常人空腹血漿血糖值通常不低於70 mg/dL","(D) 胰島素瘤（insulinoma）是空腹低血糖最常見的原因"],"answer":3,"image":""},{"id":"md3-110-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"關於血脂代謝之敘述，下列何者錯誤？","options":["(A) statin抑制膽固醇合成最重要之速率決定酶HMG-CoA oxidase","(B) HDL是逆向膽固醇運輸（reverse cholesterol transport）最重要的脂蛋白（lipoprotein）","(C) 空腹時，血中三酸甘油脂（triglyceride）主要由VLDL脂蛋白運輸","(D) LDL受體（receptor）是細胞接受血中膽固醇最重要的受體"],"answer":0,"image":""},{"id":"md3-110-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"有關先天性腎上腺增生（congenital adrenal hyperplasia）之敘述，下列何者最不可能？","options":["(A) 最常見的是CYP21A2基因突變","(B) 血中17-OH progesterone增加","(C) cortisol分泌增加","(D) ACTH分泌增加"],"answer":2,"image":""},{"id":"md3-110-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"有關甲狀腺之敘述，下列何者錯誤？","options":["(A) 甲狀腺是內分泌腺體，主要分泌的荷爾蒙是三碘甲狀腺素（Triiodothyronine, T3）及四碘甲狀腺素（Thyroxine, T4）","(B) 甲促素（Thyroid-stimulating hormone, TSH）是由腦下垂體分泌的荷爾蒙，TSH與T3、T4之間具有回饋控制的現象","(C) 在碘攝取缺乏之地區，人體內甲狀腺荷爾蒙T3比T4多，但是T4對身體組織的作用活性比T3強","(D) 正常之生理常態下，當T3及T4上升，則TSH下降；反之，當T3及T4下降，則TSH就升高"],"answer":2,"image":""},{"id":"md3-110-2-55","subject":"md3","topic":"內科-感染","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"使用下列何種抗生素治療時應避免與牛奶製品、含鎂或鋁制酸劑合用，以免影響吸收？","options":["(A) cephalexin + erythromycin","(B) tetracycline + ciprofloxacin","(C) ampicillin + clarithromycin","(D) dicloxacillin + cefuroxime"],"answer":1,"image":""},{"id":"md3-110-2-56","subject":"md3","topic":"內科-感染","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"下列關於Nesseria meningitidis的敘述，何者正確？","options":["(A) 屬革蘭氏陰性雙球菌","(B) 屬革蘭氏陽性雙球菌","(C) 沒有移生（colonization）狀態，一定會引起宿主嚴重的侵襲性感染","(D) 現有的疫苗可涵蓋所有的血清型"],"answer":0,"image":""},{"id":"md3-110-2-57","subject":"md3","topic":"內科-感染","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"關於myositis或pyomyositis的敘述，下列何者錯誤？","options":["(A) influenza virus與coxsackievirus B可造成myositis","(B) 細菌引起的myositis通常會有劇烈的肌肉疼痛症狀","(C) 寄生蟲不會引起myositis","(D) Staphylococcus是pyomyositis常見的致病菌"],"answer":2,"image":""},{"id":"md3-110-2-58","subject":"md3","topic":"內科-感染","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"下列關於分枝桿菌（Mycobacterium species）的敘述，何者錯誤？","options":["(A) M. tuberculosis是由開放性結核病人藉由空氣傳播給他人","(B) nontuberculous mycobacteria（NTM）主要是由病人藉由空氣傳播給他人","(C) NTM可以是移生狀態（colonization），也可以引起肺炎","(D) NTM可由環境中培養出來"],"answer":1,"image":""},{"id":"md3-110-2-59","subject":"md3","topic":"內科-感染","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"外科重症加護病房病人有甲氧西林抗藥金黃色葡萄球菌（methicillin-resistant Staphylococcus aureus, MRSA）引起的群聚感染。管制此次MRSA傳播最有效的手段為何？","options":["(A) 採取嚴格的感染管制措施，且以頭孢菌素（cephalosporin）治療感染的病人","(B) 採取嚴格的感染管制措施，且以高劑量苯唑西林（oxacillin）治療感染的病人","(C) 採取嚴格的感染管制措施，且以萬古黴素（vancomycin）治療感染的病人","(D) 感染管制措施是無效的，所有帶菌（包括感染及移生）的病人一律使用有效的抗生素以去除MRSA"],"answer":2,"image":""},{"id":"md3-110-2-60","subject":"md3","topic":"內科-感染","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"40歲男性人類免疫不全病毒（HIV）感染者，體重65公斤，服用抗反轉錄病毒治療2年，服用組合為lopinavir/ritonavir（蛋白酶抑制劑）＋tenofovir/emtricitabine（核苷反轉錄酶抑制劑），CD4+ T細胞數600 cells/μL，HIV病毒量＜20 copies/mL，潛伏結核（latent tuberculosis）檢查為陽性，若要接受潛伏結核治療，且不改變抗反轉錄病毒治療，則下列何種處置最為恰當？","options":["(A) 每天isoniazid 300 mg，治療9個月","(B) 每天isoniazid 300 mg＋rifampin 600 mg，治療3個月","(C) 每天rifampin 600 mg＋pyrazinamide 1,500 mg，治療2個月","(D) 每週isoniazid 900 mg＋rifapentine 900 mg，治療12週"],"answer":0,"image":""},{"id":"md3-110-2-61","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"50歲男性病人有慢性C型肝炎，近2日咳嗽有濃痰，今天凌晨出現發燒和寒顫。上午10點至急診就醫時意識清醒但是呼吸急促，體溫39.0℃，呼吸每分鐘30次，血壓116/86 mmHg，身體診察並未聽見心雜音。胸部X光顯示右側下肺葉浸潤增加。痰液經革蘭氏染色（Gram's stain）結果如圖示。經使用呼吸器和ceftriaxone，病人在隔日凌晨仍出現持續呼吸衰竭，併發休克後死亡。最可能的致病菌為何?","options":["(A) Staphylococcus aureus","(B) Streptococcus pneumoniae","(C) Listeria monocytogenes","(D) Streptococcus pyogenes"],"answer":1,"image":"md3-110-2-61.jpeg"},{"id":"md3-110-2-62","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"一位55歲男性兩天來嘔吐不止送至急診處。病人過去有十二指腸潰瘍，兩天前開始噁心嘔吐，但無腹痛或發燒。身體診察，脈搏每分鐘118，血壓88/50 mmHg，無貧血或黃疸；胸腔和心臟正常，上腹部稍有壓痛但無 ++- 反彈疼痛，腸動聲稍減，血清電解質（mmol/L）：Na 136，K 2.9，Cl 89。動脈氣體分析如下：pH 7.49， - PaCO2 45 mmHg，PaO2 98 mmHg，HCO3 32 mEq/L。下列有關對此病人的敘述何者最為正確？","options":["(A) 尿液的氯離子應該<20 mmol/L","(B) 尿液的滲透壓應該<300 mOsmol/kg H2O","(C) 血液的滲透壓應該<270 mOsmol/kg H2O","(D) 尿液的鉀離子應該<10 mmol/L"],"answer":0,"image":""},{"id":"md3-110-2-63","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"承上題，下列那個處置最為適合此病人？","options":["(A) 給與5%葡萄糖水1000 mL + 20 mmol KCl","(B) 給與0.45% NaCl 1000 mL + 20 mmol KCl","(C) 給與0.9% NaCl 1000 mL + 20 mmolKCl","(D) 給與lactated Ringer’s solution 1000 mL"],"answer":2,"image":""},{"id":"md3-110-2-64","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"張先生，30歲，有皮膚過敏（skin allergy）病史。因感冒後斷斷續續咳嗽2個月來求診。主訴最近四、五年來，每當感冒後常常咳嗽會持續超過一個月以上，且好發於秋冬之際。依病人所述，下列何者症狀最不可能發生？","options":["(A) 咳嗽多發生在清晨","(B) 咳嗽常合併胸悶或喘鳴聲","(C) 咳嗽常發生在進食後","(D) 過敏原暴露或運動時常誘發咳嗽"],"answer":2,"image":""},{"id":"md3-110-2-65","subject":"md3","topic":"內科-胸腔","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"承上題，醫師安排張先生接受肺功能之支氣管擴張試驗（bronchodilator test)，下列檢查結果何者最為可能？","options":["(A) 吸入支氣管擴張劑後一秒量（FEV1）較吸入前增加50ml且＞3%","(B) 吸入支氣管擴張劑後一秒量（FEV1）較吸入前增加100ml且＞7%","(C) 吸入支氣管擴張劑後一秒量（FEV1）較吸入前增加150ml且＞10%","(D) 吸入支氣管擴張劑後一秒量（FEV1）較吸入前增加200ml且＞12%"],"answer":3,"image":""},{"id":"md3-110-2-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"有關Fried定義的五項衰弱指標（frailty phenotype），下列敘述何者錯誤？","options":["(A) 體重減輕：最近一年體重減少超過10磅（4.5公斤）","(B) 步行速度變慢：步行15呎（4.57公尺）所需時間大於依性別與身高估計之參考秒數","(C) 疲累感覺：無法提起精神從事日常活動","(D) 肌力下降：以站姿原地抬腿評估受試者下肢肌力，2分鐘次數低於100次"],"answer":3,"image":""},{"id":"md3-110-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"15歲女生由媽媽陪同至青少年門診就醫，媽媽詢問施打疫苗的必要性。依據美國預防醫學工作小組（US Preventive Services Task Force）的建議，下列何種疫苗是她目前最不需要接種的？","options":["(A) Hepatitis A vaccine","(B) Human Papilloma Virus vaccine","(C) Tdap（Tetanus, diphtheria, acellular pertussis）vaccine","(D) Zoster vaccine"],"answer":3,"image":""},{"id":"md3-110-2-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"家庭醫師在診察一位主訴為咳嗽、打噴嚏及流鼻涕之75歲男性病人時，同時詢問其是否接種過肺炎雙球菌疫苗、最近體重變化及睡眠狀況等，這種看診方式是實踐了下列那一項家庭醫師的特色？","options":["(A) 持續性照顧（continuing care）","(B) 協調性照顧（coordinated care）","(C) 周全性照顧（comprehensive care）","(D) 負責性（accountability）"],"answer":2,"image":""},{"id":"md3-110-2-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"70歲男性，高血脂症服藥穩定控制，體適能普通，休息時心跳66下／分鐘，血壓122/80 mmHg，醫師建議運動以預防心血管疾病。有關其運動處方，下列何者最不適當？","options":["(A) 運動型態：平地步行健走，安全運動場所為主，可在公園或學校操場等平地步行","(B) 運動強度：由輕度開始，漸進到中等強度，至心跳數達目標心跳數150次／分鐘","(C) 運動時間：伸展暖身5分鐘，達到目標心跳的運動時間20分鐘，緩和運動5分鐘","(D) 運動頻率：每週至少3天"],"answer":1,"image":""},{"id":"md3-110-2-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"疾病篩檢工具的陽性預測值（positive predictive value），受下列何者的影響最大？","options":["(A) 疾病發生率（incidence）","(B) 疾病盛行率（prevalence）","(C) 疾病死亡率（mortality）","(D) 疾病存活率（survival）"],"answer":1,"image":""},{"id":"md3-110-2-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"下列有關醫病溝通的敘述，何者正確？","options":["(A) 大部分病人均可完整描述病情而不被醫師打斷","(B) 醫師看病人時，眼神接觸（eye contact）的時間占整個會談時間的90%以上，最能改善醫病關係","(C) 一般醫病溝通在聆聽時，眼神接觸（eye contact）的時間約占整個聆聽時間的80%左右","(D) 與醫師眼神接觸（eye contact）維持的時間，憂鬱症病人是非憂鬱症病人之3倍"],"answer":2,"image":""},{"id":"md3-110-2-72","subject":"md3","topic":"家醫-行為與社區醫學","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"有關執行疾病共享決策（Shared Decision Making, SDM）會遭遇的挑戰，下列敘述何者錯誤？","options":["(A) 權威的健康照護文化","(B) 缺乏足夠的溝通時間","(C) 民眾的健康識能充足","(D) 缺乏合適的輔助工具"],"answer":2,"image":""},{"id":"md3-110-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"有關居家安寧療護及在宅善終的優點，下列敘述何者錯誤？","options":["(A) 可節省醫療支出","(B) 病人在家，最為熟悉","(C) 在家過世，較有尊嚴","(D) 症狀控制較方便"],"answer":3,"image":""},{"id":"md3-110-2-74","subject":"md3","topic":"內科-消化肝膽胰","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"有關大腸扭轉的敘述，下列何者最合理？","options":["(A) 大腸扭轉最常發生在兒童","(B) 大腸扭轉最好發於盲腸","(C) 大腸扭轉常合併腹股溝疝氣","(D) 大腸扭轉可利用電腦斷層掃描加以診斷"],"answer":3,"image":""},{"id":"md3-110-2-75","subject":"md3","topic":"影像醫學","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"下圖為右上腹部超音波掃描，對於箭號所指之處的相關敘述，何者錯誤？","options":["(A) 和Rokitansky-Aschoff憩室無關","(B) 病灶有伴隨假影","(C) 假影的呈現有助於病灶的診斷","(D) 最可能診斷為膽囊腺肌症伴隨膽固醇結晶"],"answer":0,"image":"md3-110-2-75.jpeg"},{"id":"md3-110-2-76","subject":"md3","topic":"內科-心臟血管","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"下列何者最不適合同步心臟整流（synchronized cardioversion）？","options":["(A) 心室頻脈（ventricular tachycardia）合併休克的病人","(B) 心房顫動合併快速心室反應（atrial fibrillation with rapid ventricular response）且意識不清的病人","(C) 上心室頻脈（supraventricular tachycardia）合併急性肺水腫的病人","(D) 沒有呼吸心跳的心室顫動（ventricular fibrillation）病人"],"answer":3,"image":""},{"id":"md3-110-2-77","subject":"md3","topic":"內科-腎臟","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"關於低血鉀（hypokalemia）的敘述，下列何者最正確？","options":["(A) 利尿劑spironolactone（Aldactone）是造成低血鉀症的原因","(B) 輕度且穩定的低血鉀症病人，補充鉀離子應該以口服方式為主","(C) 低血鉀症可能同時合併有高血鎂（hypermagnesemia）的情形","(D) 建議補充氯化鉀加入含有葡萄糖溶液中，以利鉀離子儘快吸收"],"answer":1,"image":""},{"id":"md3-110-2-78","subject":"md3","topic":"內科-內分泌代謝","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"下列關於高滲透壓高血糖狀態（Hyperosmolar hyperglycemic state, HHS）之敘述，何者錯誤？","options":["(A) HHS的定義為血糖值＞600 milligrams/dL且血漿滲透壓＞300 mOsm/kg","(B) HHS病人不一定會出現昏迷或酮酸中毒","(C) 臨床症狀可出現皮膚、黏膜乾燥或低血壓","(D) 有些病人會出現痙攣（seizure）"],"answer":0,"image":""},{"id":"md3-110-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"45歲男性因心血管阻塞欲置放心導管支架，住院後醫師說明了手術風險，並請病人簽具同意書。第2天到了心導管室時，醫師詢問病人是否要放置自費塗藥的心導管支架，效果比較好，病人猶豫後同意放置，出院後立即反悔。下列敘述何者最適當？","options":["(A) 同意有效，因病人在心導管室時同意使用自費塗藥的心導管支架","(B) 同意有效，醫師只是好意並未強迫病人。病人如不想要放置自費的心導管支架，就不要同意，同意後再反悔，毫無誠信","(C) 同意無效，因為未簽具自費同意書","(D) 同意無效，因病人自覺是在心理受到壓迫下做的決定，違反同意的自願性"],"answer":3,"image":""},{"id":"md3-110-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"28歲女性病患因為臉頰紅斑、掉頭髮、兩下肢水腫，由其未婚夫陪同求診，經檢查確認為全身性紅斑狼瘡合併腎炎。病患知道檢查結果後，要求醫師不要將紅斑狼瘡相關病情告知其未婚夫。下列敘述何者最為正確？","options":["(A) 病患的未婚夫並非病患家屬，醫師本來就沒有告知其未婚夫相關病情的必要性","(B) 病患的未婚夫雖非家屬，但屬於關係人，醫師對於病患的關係人，依法就有告知的義務，並無需病患同意後，才能告知","(C) 病情告知的對象以病患本人為原則，本案中病患並非未成年，也未喪失行為能力，因此醫師不得對其配偶、親屬以及關係人，進行病情說明","(D) 病情告知的對象以病患本人為原則，本案中患者已經成年而且具有行為能力，因此病患得以書面敘明，對特定之人不予告知病情"],"answer":3,"image":""},{"id":"md3-111-1-1","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"關於造成昏厥（syncope）的原因，下列敘述何者最不適當？","options":["(A) 血管迷走神經性昏厥（vasovagal syncope）是最常見的原因","(B) 心因性（cardiac）昏厥的原因包括心律不整（arrhythmias）及結構性心臟病（structural heart disease）","(C) 姿勢性低血壓（orthostatic hypotension）也可能造成昏厥。在站立後第3分鐘時收縮壓下降15毫米汞柱或是舒張壓下降5毫米汞柱，符合姿勢性低血壓的定義","(D) 懷疑是血管迷走神經性昏厥（vasovagal syncope）時可建議病人做傾斜床測試（tilt table test）"],"answer":2,"image":""},{"id":"md3-111-1-2","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"關於骨鬆性骨折（osteoporotic fracture）的敘述，下列何者最不適當？","options":["(A) 影像上發現脊椎骨壓迫性骨折，大部分是沒有症狀的","(B) 在第一次脊椎骨壓迫性骨折一年內，再度發生其他節脊椎骨骨折的風險達20%","(C) 抗骨質再吸收劑（anti-resorptive drugs）之使用目的在於急性疼痛的緩解，但無法預防脊椎骨骨折的再發","(D) 若出現發燒、體重減輕或發生在胸椎第四節以上的骨折，要懷疑不是單純由老化所引發的骨折"],"answer":2,"image":""},{"id":"md3-111-1-3","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"70歲男性病人，過去病史有高血壓及B型肝炎，最近3個月因活動時呼吸氣促而逐漸臥床，身體診察時發現病人端坐時比平躺時更覺得胸悶吸不到氣，下列身體診察何者對確定診斷最沒有幫助？","options":["(A) Castell's sign","(B) abdominal shifting dullness","(C) diastolic rumbling heart murmur","(D) right ventricle heave"],"answer":3,"image":""},{"id":"md3-111-1-4","subject":"md3","topic":"急診醫學","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"某位70歲女性因為喝有機磷（organophosphate）農藥自殺而被送來醫院急救。當農藥毒性發作時，最不可能導致下列何種徵象？","options":["(A) 肌肉無力","(B) 口水、淚液減少","(C) 癲癇發作（seizure）","(D) 腹瀉、大便失禁"],"answer":1,"image":""},{"id":"md3-111-1-5","subject":"md3","topic":"急診醫學","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"承上題，針對上述病人之治療，下列何種方式最不適當？","options":["(A) 服用活性碳","(B) 注射atropine","(C) 注射physostigmine","(D) 注射pralidoxime（2-PAM）"],"answer":2,"image":""},{"id":"md3-111-1-6","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"下列有關主動脈瘤之敘述，何者錯誤？","options":["(A) 造成主動脈瘤之可能病因為：退化、Marfan氏症候群等遺傳性症候群、慢性主動脈剝離、感染及非感染性動脈炎、創傷等","(B) 胸主動脈瘤破裂的機會與其大小有關，直徑在4 cm以下者，風險約為每年2～3%，但若直徑大於6 cm，則風險升高至每年7%","(C) 直徑4 cm以上的腹主動脈瘤，大多因動脈硬化所致，位於腎動脈以上，若瘤體內有管壁血栓，則可能因此造成下肢周邊血管栓塞","(D) 無症狀腹主動脈瘤若直徑5.5 cm以上，應考慮進行主動脈瘤修補術，以血管內（endovascular）介入方式之短期死亡率較傳統外科手術為低，而長期死亡率相似"],"answer":2,"image":""},{"id":"md3-111-1-7","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"當病人因心功能失常或嚴重心肌缺血而出現血行動力不穩、甚或心因性休克時，除強心藥物外，可能需要機械性循環支持，下列相關敘述，何者錯誤？","options":["(A) 主動脈氣球泵浦（IABP）之球囊置放於降主動脈，由氦氣充填，於心舒張早期充氣、舒張中後期消氣，因此可降低主動脈早期舒張期血壓以增加冠狀動脈血流，且降低主動脈收縮期血壓以降低左心室後負荷","(B) Impella導管可經由股動脈逆行置入左心室，其先端部位有一小型軸向泵浦，可將左心室血液泵至主動脈，以增加心輸出量並降低左心室壓力","(C) TandemHeart系統可經由左心房導管將血液抽出、由離心泵浦推送至股動脈，提供每分鐘達5公升之血流量","(D) 體外膜氧合系統（ECMO）可用於急性心衰竭合併心因性休克及嚴重肺損傷合併呼吸衰竭"],"answer":0,"image":""},{"id":"md3-111-1-8","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"下列狀況何者不是壓力催迫性檢查（stress test）的絕對禁忌症？","options":["(A) 不穩定心絞痛","(B) 嚴重心內膜炎","(C) 無症狀之主動脈狹窄","(D) 嚴重心律不整，且曾併發血行動力學不穩定"],"answer":2,"image":""},{"id":"md3-111-1-9","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"使用下列何種抗心律不整藥物可能會造成心電圖上出現ST節段升高（ST segment elevations）情形？","options":["(A) class 1C antiarrhythmic drugs","(B) class II antiarrhythmic drugs","(C) class III antiarrhythmic drugs","(D) class IV antiarrhythmic drugs"],"answer":0,"image":""},{"id":"md3-111-1-10","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"一位75歲男性因心悸至門診，十二導程心電圖顯示心房顫動。下列對心房顫動之敘述何者錯誤？","options":["(A) 心房顫動為女性多於男性","(B) 心房顫動風險因子（risk factor）包括甲狀腺亢進、高血壓、糖尿病及肥胖等","(C) 心房顫動可能會造成心衰竭","(D) 心房顫動之缺血性中風風險評估可用CHA2DS2-VASc score"],"answer":0,"image":""},{"id":"md3-111-1-11","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"關於慢性靜脈疾病，包括靜脈曲張（varicose vein）的描述，下列何者正確？","options":["(A) 原發性靜脈曲張的病人絕大多數是因為靜脈高壓所造成，很少有家族史","(B) 女性使用荷爾蒙替代療法不會增加靜脈曲張的風險","(C) 原發性的靜脈曲張常發生在深層靜脈","(D) 慢性靜脈疾病的主要診斷工具是venous duplex ultrasonography"],"answer":3,"image":""},{"id":"md3-111-1-12","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"下列何種乙型交感神經阻斷劑（beta blocker）無法改善左心室射出分率降低的心衰竭（heart failure with reduced ejection fraction）之預後？","options":["(A) carvedilol","(B) bisoprolol","(C) propranolol","(D) metoprolol succinate"],"answer":2,"image":""},{"id":"md3-111-1-13","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"有關心臟衰竭（heart failure, HF）血清標記的描述，何者錯誤？","options":["(A) 當低收縮分率心臟衰竭患者使用angiotensin receptor neprilysin inhibitor（ARNI）後，B-type natriuretic peptide（BNP）的濃度會降低","(B) 當年齡增加時，N-terminal pro-BNP（NT-proBNP）血清濃度會增加","(C) 當腎功能變差時，NT-proBNP血清濃度會增加","(D) 在門診呼吸困難患者中，BNP或NT-proBNP的測量可用於支持有關HF診斷的臨床決策，尤其是在臨床不確定性情況下"],"answer":0,"image":""},{"id":"md3-111-1-14","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"一位75歲的女性病人最近感覺到漸進性運動性氣促，下列何項檢查對呼吸困難的鑑別診斷幫助最小？","options":["(A) 胸部X光","(B) 身體診察（physical examination）","(C) 24小時心電圖（Holter monitoring）","(D) 心臟超音波"],"answer":2,"image":""},{"id":"md3-111-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"下列何者不是慢性B型肝炎患者，是否需要接受抗B型肝炎病毒藥物治療根據的因素？","options":["(A) B型肝炎病毒核醣核酸（RNA）濃度","(B) 肝臟損傷（纖維化）嚴重度","(C) 血中丙胺酸轉胺酶（alanine aminotransferase, ALT）高低","(D) 病人是否因其他疾病須接受抗癌化學藥物治療"],"answer":0,"image":""},{"id":"md3-111-1-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"25歲女性來急診室主訴3天前開始噁心，肚臍周圍及上腹疼痛，隔天疼痛轉移到右下腹部，且疼痛加劇。這時候開始發燒、畏寒。關於此問題的診療及處置，下列敘述何者錯誤？","options":["(A) 病史詢問需要考慮泌尿道及婦產科方面的問題：包括子宮內膜異位、子宮外孕（ectopic pregnancy），以及骨盆腔發炎都是有可能的診斷","(B) 身體診察上要注意右下腹部的檢查。在McBurney's point上有壓痛的情形即為Rovsing's sign陽性，需要懷疑是急性闌尾炎（acute appendicitis）","(C) 若沒有懷孕的可能，可以安排電腦斷層檢查，以協助診斷。急性闌尾炎常會看到闌尾壁變厚，周邊發炎，但不一定會看到糞石（fecalith）","(D) 若闌尾破裂被腸繫膜包住形成局部膿瘍，需要給與廣效抗生素及考慮安排引流。手術切除可延後至局部發炎改善後再進行"],"answer":1,"image":""},{"id":"md3-111-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"關於大腸直腸癌，下列敘述何者錯誤？","options":["(A) 腺瘤樣息肉（adenomatous polyp）屬於癌前病變，而增生性息肉（hyperplastic polyp）則較不會有惡性的變化","(B) 息肉有分扁平狀（sessile）、鋸齒狀（serrated）及突起狀（pedunculated），突起狀息肉較具侵襲性","(C) familial adenomatous polyposis產生大腸癌的風險較Peutz-Jeghers syndrome的風險為高","(D) Lynch's syndrome導致的大腸癌與遺傳有關，也會增加發生子宮內膜癌或是卵巢癌的風險"],"answer":1,"image":""},{"id":"md3-111-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"關於胃酸的分泌，下列何者錯誤？","options":["(A) ++ 主管胃酸分泌之parietal cells其細胞膜上分泌胃酸的主要幫浦為H/K- ATPase","(B) parietal cells因靠離子濃度差異進行胃酸分泌，因此其中粒腺體（mitochondria）之數目很少","(C) parietal cells之胃酸分泌受到胃泌素受體（gastrin receptor）、乙醯膽鹼受體（acetylcholine receptor）以及組織胺受體（histamine receptor）所調控","(D) parietal cell之尖端細胞膜（apical membrane）型態會因在休息狀態（resting）或受刺激狀態（stimulated）有所改變"],"answer":1,"image":""},{"id":"md3-111-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"下列關於急性膽囊炎（acute cholecystitis）的敘述何者錯誤？","options":["(A) 必定同時伴隨膽囊結石","(B) 及早進行膽囊切除對大多數患者是最佳治療方式","(C) Murphy's徵象（Murphy's sign）常為陽性","(D) 可能同時合併有總膽管結石"],"answer":0,"image":""},{"id":"md3-111-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"下列關於膽管癌（cholangiocarcinoma）之敘述何者錯誤？","options":["(A) 依部位可分為肝內（intrahepatic）、肝門（perihilar）及遠端（distal）3類","(B) 手術切除是唯一的根治性治療","(C) 肝結石症（hepatolithiasis）是其危險因子","(D) 原發性硬化性膽管炎（primary sclerosing cholangitis）並不會增加膽管癌之風險"],"answer":3,"image":""},{"id":"md3-111-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"決定肝臟移植接受者（recipient）接受肝臟移植的優先次序（prioritization），通常是根據下列何項指標？","options":["(A) Model for End-Stage Liver Disease（MELD）score","(B) Child-Turcotte-Pugh score","(C) Maddrey's discriminant function score","(D) Sequential Organ Failure Assessment（SOFA）score"],"answer":0,"image":""},{"id":"md3-111-1-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"一位51歲男性主訴3天前黑便兩次，生命跡象正常，血液檢查：Hb 11.2 g/dL。此病人之上腸胃道內視鏡檢查，何者可以讓我們告訴病人3天內再出血之機會不大？","options":["(A) 胃潰瘍上有黏附之血塊，但未見出血","(B) 胃潰瘍底部有未出血之血管","(C) 胃潰瘍合併乾淨之潰瘍底部","(D) 無消化潰瘍，但在胃體部上方有一小段可見之動靜脈畸生血管（arteriovenous malformation）"],"answer":2,"image":""},{"id":"md3-111-1-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"有關B型肝炎病毒感染後的血清學反應，下列何者錯誤？","options":["(A) 最早出現的血清病毒標誌為表面抗原（HBsAg），最常在感染後的8～12週可偵測到","(B) 表面抗原（HBsAg）的出現時間比血清轉氨酶（transaminase）上升及臨床症狀的出現可以早2～6週","(C) isolated anti-HBc陽性，可以出現在急性B型肝炎病毒感染或是隱匿性B型肝炎感染（occult HBV infection）","(D) 急性感染時，核心抗體（anti-HBc IgM）在表面抗原（HBsAg）出現的4週後才可以偵測到"],"answer":3,"image":""},{"id":"md3-111-1-24","subject":"md3","topic":"內科-腎臟","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"53歲男性腎臟移植病人，移植腎功能惡化，1個月內serum creatinine由1.0 mg/dL，上升至2.0 mg/dL，移植腎切片顯示內皮細胞損傷（endothelial injury）、C4d沉積，下列何種治療最不適當？","options":["(A) 血漿置換（plasmapheresis）","(B) 免疫球蛋白注射（immunoglobulin infusion）","(C) anti-IL2接受器（anti-IL2 receptor）單株抗體注射","(D) anti-CD20單株抗體（rituximab）注射"],"answer":2,"image":""},{"id":"md3-111-1-25","subject":"md3","topic":"內科-腎臟","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"一名50歲男性尿路結石病人的尿液檢查發現結晶物質如附圖所示，下列何項建議最為適當？","options":["(A) consume a low-calcium diet from now on","(B) need not modulate urine pH","(C) start taking tiopronin or penicillamine","(D) supply high-dose vitamin C"],"answer":1,"image":"md3-111-1-25.jpeg"},{"id":"md3-111-1-26","subject":"md3","topic":"內科-腎臟","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"下列何項不是急性間質性腎炎（acute interstitial nephritis）的常見臨床表現？","options":["(A) 尿液分析僅輕度蛋白尿（＜1.0 g/24 hours）和血尿","(B) 血清肌酸酐上升合併鈉排出率（fractional excretion of sodium）＞1.0","(C) 使用氫離子幫浦阻斷劑後發生腎病症候群程度的蛋白尿（nephrotic-range proteinuria）","(D) 腎衰竭發展耗時數日至數週，符合原發性免疫反應動力學（kinetics）"],"answer":2,"image":""},{"id":"md3-111-1-27","subject":"md3","topic":"內科-腎臟","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"有關多囊性腎臟病的敘述，下列何者錯誤？","options":["(A) 自體顯性多囊性腎臟病（autosomal dominant polycystic kidney disease, ADPKD）是最常見的遺傳性腎臟疾病","(B) 自體顯性多囊性腎臟病（autosomal dominant polycystic kidney disease, ADPKD）的致病基因目前已知的有兩型：第一型：PKD1基因，位在第16對染色體短臂上（16p13.3）；第二型：PKD2基因，位在第4對染色體長臂上（4q21-q23）","(C) 多囊性腎臟病的患者，約3.2%~10%會發生腦部動脈瘤，男性有較高的盛行率，特別是年紀小於30歲者","(D) 多囊性腎臟病的患者與一般末期腎病不同的是，患者發生嚴重貧血的機率較小，當惡化至尿毒症時，患者一樣可接受透析治療或腎臟移植"],"answer":2,"image":""},{"id":"md3-111-1-28","subject":"md3","topic":"內科-腎臟","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"下列原發性腎病變引起的腎病症候群（nephrotic syndrome），那一種最容易發生血栓併發症（如：renal vein thrombosis、pulmonary embolism和deep-vein thrombosis）？","options":["(A) type I membranoproliferative glomerulonephritis（MPGN）","(B) focal segmental glomerulosclerosis（FSGS）","(C) membranous nephropathy（MN）","(D) minimal change disease（MCD）"],"answer":2,"image":""},{"id":"md3-111-1-29","subject":"md3","topic":"內科-腎臟","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"在皮質集尿管（cortical collecting duct）有三種上皮細胞，下列敘述何者正確？","options":["(A) 主細胞（principal cells）是負責鉀離子的再吸收細胞","(B) + 作用在主細胞（principal cells）包括：醛固酮，K-sparing利尿劑及醛固酮拮抗劑","(C) A型間細胞（type A intercalated cells）控制酸的再吸收與重碳酸根分泌","(D) B型間細胞（type B intercalated cells）控制酸的分泌與重碳酸根再吸收"],"answer":1,"image":""},{"id":"md3-111-1-30","subject":"md3","topic":"內科-腎臟","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"關於急性腎損傷處置的敘述，下列何者錯誤？","options":["(A) 對於非出血性休克病人的靜脈輸液，建議使用等張晶體溶液（isotonic crystalloid solution）","(B) 建議重症病人以低蛋白飲食來延緩透析","(C) 在體液容積足夠的情況下，furosemide stress test能夠作為急性腎損傷惡化的預測工具","(D) 不建議使用低劑量多巴胺（dopamine）來預防急性腎損傷"],"answer":1,"image":""},{"id":"md3-111-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"關於痛風（gout）疾病的敘述，下列何者最適當？","options":["(A) 痛風常發生在中年男性，而女性在停經（menopause）之後痛風的發生率會降低","(B) 急性痛風關節炎發作時，血中的uric acid濃度可以是在正常值的範圍內","(C) X光檢查常會看到明顯的關節破壞，但關節的ultrasound檢查較無法看到尿酸結晶的關節變化","(D) 針對痛風合併腎臟功能不全的病人，不應使用glucocorticoid的藥物來治療急性痛風關節炎"],"answer":1,"image":""},{"id":"md3-111-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"30歲女性，類風濕性關節炎長期吃藥控制，最近要準備懷孕，下列何種用藥建議最適當？","options":["(A) methotrexate與leflunomide都可以在懷孕前使用，驗到受孕再停止即可","(B) 所有生物製劑都可以在懷孕中全程使用","(C) hydroxychloroquine與sulfasalazine都可以在懷孕中全程使用","(D) 低劑量類固醇在懷孕前可以使用，一旦驗到受孕就不能再使用類固醇"],"answer":2,"image":""},{"id":"md3-111-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"有關急性風濕熱（acute rheumatic fever）的敘述，下列何者正確？","options":["(A) 大多數都是由感染group B Streptococci所引起","(B) 從感染到出現關節炎，平均大概會間隔3個月左右","(C) erythema marginatum屬於較罕見臨床表徵（約小於5%）","(D) 大概有10 %病人會進展到風濕性心臟病（rheumatic heart disease）"],"answer":2,"image":""},{"id":"md3-111-1-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"42歲周女士因為類風濕性關節炎，自1年前開始接受腫瘤壞死因子拮抗劑（tumor necrosis factor-alpha inhibitor）adalimumab每2週40 mg注射治療。大概3週前，周女士發現臉上、手臂伸側、上背部及頸部後側開始出現紅疹，驗血發現抗核抗體（antinuclear antibodies, ANA）以及抗雙股DNA抗體（anti-dsDNA antibodies）由用藥前的陰性轉為陽性，下列處置何者最適當？","options":["(A) 停掉adalimumab，改用etanercept","(B) 加上prednisolone 1 mg/kg/day，繼續使用adalimumab","(C) 停掉adalimumab，改用rituximab","(D) 停掉adalimumab，改用infliximab"],"answer":2,"image":""},{"id":"md3-111-1-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"目前認為脊椎關節炎（spondyloarthritis）最起始之病灶為何處？","options":["(A) 軟骨（cartilage）","(B) 肌腱附著點（enthesis）","(C) 硬骨（bone）","(D) 滑膜（synovium）"],"answer":1,"image":""},{"id":"md3-111-1-36","subject":"md3","topic":"內科-腫瘤","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"腫瘤細胞常藉著分泌生物激素與其他免疫相關分子來抑制免疫反應，減少免疫相關分子來毒殺腫瘤細胞，下列有關免疫反應相對應機轉之敘述何者錯誤？","options":["(A) 腫瘤細胞分泌interferon-γ等抑制免疫之細胞激素，可以抑制免疫反應","(B) 腫瘤細胞class I major histocompatibility complex（MHC）喪失，影響免疫細胞活化","(C) 腫瘤細胞影響調節T細胞（regulatory T cells）可以抑制免疫細胞功能","(D) 腫瘤細胞產生CTLA-4可讓毒殺T細胞（cytotoxic T cells）不活化"],"answer":[0,3],"image":"","answer_note":"更正:第36題，答Ａ或Ｄ或AD者均給分"},{"id":"md3-111-1-37","subject":"md3","topic":"內科-腫瘤","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"全球的食道癌（esophageal cancer），常見的組織學型態是squamous cell carcinoma；但在北美地區，adenocarcinoma已逐漸成為主要的食道癌類型。下列有關與食道adenocarcinoma相關的危險或致病因子中，何者的相關性最低？","options":["(A) obesity","(B) chronic gastroesophageal reflux","(C) cigarette smoking","(D) Helicobacter pylori"],"answer":3,"image":""},{"id":"md3-111-1-38","subject":"md3","topic":"內科-腫瘤","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"胰臟癌（pancreatic ductal adenocarcinoma）逐年增加，其藥物治療學近年來也有相當的進展。下列有關胰臟癌藥物治療進展的敘述，何者最不恰當？","options":["(A) 局部胰臟癌手術後，應進行輔助性化學治療半年","(B) 胰臟癌術後輔助性化學治療，已有第三期臨床試驗證實gemcitabine + capecitabine優於gemcitabine","(C) 晚期及轉移的胰臟癌應進行全身性化學治療，目前的研究顯示：組合式化學化療（combination chemotherapy）並未優於gemcitabine單一治療","(D) 針對gemcitabine治療失敗的晚期或轉移胰臟癌病患，liposomal irinotecan + 5-fluorouracil + leucovorin因可改善病患的整體存活期，已被美國衛生主管機關（FDA）核准通過"],"answer":2,"image":""},{"id":"md3-111-1-39","subject":"md3","topic":"內科-腫瘤","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"沒有遠端轉移的非小細胞肺癌，治癒性切除（curative resection）的禁忌症是：","options":["(A) 上腔靜脈症候群（superior vena cava syndrome）","(B) 同側肺門淋巴結轉移（ipsilateral hilar lymph node metastasis）","(C) 穩定性心絞痛（stable angina pectoris）","(D) 肺功能檢查FEV1大於1公升"],"answer":0,"image":""},{"id":"md3-111-1-40","subject":"md3","topic":"內科-腫瘤","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"關於膀胱癌的敘述，下列何者錯誤？","options":["(A) 原發性膀胱癌最常見的組織型是泌尿上皮癌","(B) 低惡性度（low-grade）膀胱癌常見的基因變異是FGFR3突變或基因融合；高惡性度（high-grade）膀胱癌常見的基因變異是TP53突變、RB1突變","(C) 剛發現時，絕大多數的膀胱癌都已經遠端轉移，其次是平滑肌肉層侵犯（muscle-invasive）膀胱癌、非平滑肌肉層侵犯（non-muscle-invasive）膀胱癌最少","(D) 對於高風險（例如：T1腫瘤、high-grade、CIS）的非平滑肌肉層侵犯（non-muscle-invasive）膀胱癌，使用經尿道膀胱腫瘤切除術切除所有肉眼可見的腫瘤後，膀胱灌注BCG可以減少復發的機會"],"answer":2,"image":""},{"id":"md3-111-1-41","subject":"md3","topic":"內科-血液","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"下列有關後天嚴重型再生不良貧血（severe acquired aplastic anemia）的治療的描述，何者最不恰當？","options":["(A) 類固醇（glucocorticoid）常用於第一線治療，療效甚佳","(B) 異體造血幹細胞移植（allogeneic hematopoietic stem cell transplantation）是治癒此病的選項之一","(C) antithymocyte globulin（ATG）合併cyclosporin是常用的治療選項之一","(D) granulocyte colony-stimulating factor（G-CSF）通常無效"],"answer":0,"image":""},{"id":"md3-111-1-42","subject":"md3","topic":"內科-血液","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"下列那一種人類的hemoglobin在胎兒10～11週時，是主要的hemoglobin？","options":["(A) Hb Portland（ζ2γ2）","(B) Hb Gower I（ζ2ε2）","(C) Hb Gower II（α2ε2）","(D) HbF（α2γ2）"],"answer":3,"image":""},{"id":"md3-111-1-43","subject":"md3","topic":"內科-血液","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"慢性骨髓性白血病，其病因是在第9號染色體（ABL locus）和第22號染色體（BCR區）的長臂有相互平衡的轉位（balanced translocation），導致有BCR-ABL1癌蛋白（oncoprotein）產生。下列敘述何者錯誤？","options":["(A) 因染色體斷裂點不同，可以導致有不同的分子量之BCR-ABL1癌蛋白，其中以p210最為常見","(B) BCR-ABL1癌蛋白會使tyrosine kinase的活性增加而使細胞過度生長","(C) 臨床上可以利用定量此一變異來檢測疾病控制的效果","(D) 輻射傷害常常會導致這種轉位"],"answer":3,"image":""},{"id":"md3-111-1-44","subject":"md3","topic":"內科-血液","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"下列何者不是動脈性血栓（arterial thrombi）的特徵？","options":["(A) 主要的成分包括血小板，纖維蛋白（fibrin）和紅血球","(B) 富含血小板","(C) 急性的周邊動脈性血栓治療以全身性纖維蛋白溶解劑治療（systemic fibrinolytic therapy）為主","(D) 急性心肌梗塞是屬於動脈性的血栓造成的併發症"],"answer":2,"image":""},{"id":"md3-111-1-45","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"下列有關氣喘（asthma）致病機轉的敘述，何者最適當？","options":["(A) 過敏原刺激dendritic cells釋放chemokine CCL17和CCL22，誘使TH1 lymphocytes分泌IL-5，進而吸引eosinophils進入呼吸道","(B) 病毒可刺激呼吸道上皮細胞分泌IL-25和IL-33導致ILC2 lymphocytes分泌IL-5，吸引eosinophils進入呼吸道","(C) 一氧化氮在氣喘病患的呼出氣體中，代表呼吸道發炎反應的程度，與呼吸道的dendritic cells和lymphocytes有正性相關","(D) IL-10和IL-12是proinflammatory mediators，由呼吸道發炎細胞產生與氣喘的嚴重度有正性相關"],"answer":1,"image":""},{"id":"md3-111-1-46","subject":"md3","topic":"內科-胸腔","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"22歲女性病患主訴胸悶及運動性氣促。感冒時症狀加劇，有過敏性鼻炎症狀，最近爬樓梯到2樓就覺得很喘。身體診察有輕微哮鳴音，下列何者檢查最適合幫助診斷？","options":["(A) methacholine provocation test","(B) bronchodilator test","(C) allergen test","(D) 呼氣一氧化氮測試"],"answer":1,"image":""},{"id":"md3-111-1-47","subject":"md3","topic":"內科-胸腔","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"62歲男性患者，因近三個月有慢性咳嗽而前來就診，肺部聽診時發現有單頻喘鳴聲（monophonic wheeze），最有可能的診斷為何？","options":["(A) 心衰竭","(B) 肺癌","(C) 肺纖維化症","(D) 肺炎"],"answer":1,"image":""},{"id":"md3-111-1-48","subject":"md3","topic":"內科-胸腔","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"70歲男性病人因運動時呼吸困難前來就診，其肺功能檢查顯示：TLC為70%預測值，FEV1為65%預測值，FEV1/FVC 78%，DLco為55%預測值，最有可能的診斷為何？","options":["(A) 胸廓畸形","(B) 右側氣胸","(C) 間質性肺病","(D) 肺氣腫"],"answer":2,"image":""},{"id":"md3-111-1-49","subject":"md3","topic":"內科-感染","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"70歲男性因咳嗽數個月而就醫被診斷為肺結核，分子檢測時，發現此病人痰液結核菌中的rpoB基因有突變。此病人應該合理的被認為對下列何種藥物具有抗藥性？","options":["(A) isoniazid","(B) rifampin","(C) ethambutol","(D) pyrazinamide"],"answer":1,"image":""},{"id":"md3-111-1-50","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"31歲女性，健康狀況良好，突然間抱怨無法忍受的頭痛，合併頸部僵硬、噁心、嘔吐，接著喪失意識。最有可能的診斷為何？","options":["(A) 腦膜炎","(B) 梗塞性中風","(C) 顱內動脈瘤破裂","(D) 偏頭痛"],"answer":2,"image":""},{"id":"md3-111-1-51","subject":"md3","topic":"內科-胸腔","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"非侵襲性正壓呼吸器（noninvasive positive pressure ventilator）的禁忌症，不包括下列何者？","options":["(A) 血壓60/40 mmHg","(B) 昏迷指數3分","(C) 每20分鐘需要抽痰一次","(D) PaCO2 70 mmHg"],"answer":3,"image":""},{"id":"md3-111-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"下列有關甲狀腺癌的敘述，何者錯誤？","options":["(A) 手術可以切除病灶有助於組織病理及癌症分期確認","(B) 若懷疑有甲狀腺癌，可以使用甲狀腺超音波進行頸部中央及兩側淋巴結的檢查，並在可疑之淋巴結作細針穿刺細胞學檢查","(C) 病理學上，細胞分化良好之甲狀腺癌，例如乳突癌或濾泡癌，術後追蹤腫瘤是否再發的主要生物指標是胎兒球蛋白（alpha-fetoprotein）","(D) 甲狀腺癌之同位素放射線根除療法，使用之放射線同位素是碘-131（I-131），而碘-131之半衰期約為8.04天"],"answer":2,"image":""},{"id":"md3-111-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"下列何者最不可能引起糖尿病？","options":["(A) 一些病毒感染後引起自體免疫反應","(B) 肌肉、脂肪或肝臟產生的胰島素阻抗","(C) 類固醇的使用","(D) 投與雙胍類的藥物"],"answer":3,"image":""},{"id":"md3-111-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"下列有關肥胖的敘述，何者錯誤？","options":["(A) 肥胖可以引起胰島素阻抗及糖尿病","(B) 身體質量指數越小則代表越胖","(C) 肥胖與飲食習慣、運動及基因等因素有關","(D) 脂肪細胞可以分泌許多影響肥胖發生的物質"],"answer":1,"image":""},{"id":"md3-111-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"下列敘述何者錯誤？","options":["(A) 第一型糖尿病人（type 1 diabetes mellitus）以全靜脈營養（total parenteral nutrition）治療時，除輸液中加胰島素外，應同時給長效胰島素（long acting insulin）","(B) 使用類固醇（glucocorticoid）之糖尿病人，若空腹血糖超過200 mg/dL以上控制不佳時，常需給與胰島素控制血糖","(C) 脂質營養不良性之糖尿病（lipodystrophic diabetes mellitus）病人，可使用重組人類瘦素（recombinant human leptin）治療","(D) 80歲以上之糖尿病病人，其血糖控制目標為糖化血色素＜6.5%"],"answer":3,"image":""},{"id":"md3-111-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"造成次發性高血壓的內分泌疾病中，下列何者最常見？","options":["(A) 原發性醛固酮過高（primary aldosteronism）","(B) 嗜鉻細胞瘤（pheochromocytoma）","(C) 庫欣氏症候群（Cushing's syndrome）","(D) 肢端肥大症（acromegaly）"],"answer":0,"image":""},{"id":"md3-111-1-57","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"一位42歲有白斑的女性到門診就醫，主訴這半年來感覺疲倦、怕冷、變胖、抽筋。抽血檢查發現free T4為0.4 ng/dL（正常參考值為0.6～1.75 ng/dL），TSH為25 μIU/mL（正常參考值為0.1～4.5 μIU/mL），有關其病因的鑑別診斷，下列何種診療最不需要？","options":["(A) 甲狀腺觸診和詢問甲狀腺疾病相關家族史","(B) 甲狀腺超音波檢查","(C) 抽血測量甲狀腺相關自體免疫指數，例如anti-thyroid peroxidase antibody（anti-TPO）","(D) 腦下垂體核磁共振檢查"],"answer":3,"image":""},{"id":"md3-111-1-58","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"一位27歲男性，主訴一年來體重上升，身體診察發現有月亮臉、水牛肩、中心型肥胖、皮膚易瘀青、在腹部和雙腿近端有紫色條紋（purple striae），接下來進行何項檢查最為合適？","options":["(A) 抽血檢查早上8點和下午4點的cortisol和ACTH","(B) 進行high dose dexamethasone suppression test","(C) 安排腎上腺電腦斷層檢查","(D) 安排腦下垂體核磁共振檢查"],"answer":0,"image":""},{"id":"md3-111-1-59","subject":"md3","topic":"內科-感染","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"醫療人員在照顧不同病人之間執行手部衛生，下列何種情境不適合單獨使用酒精性乾洗手液？①手部有明顯髒污（visibly soiled） ②照護困難梭狀桿菌（C. difficile）患者後 ③要置放導尿管之前 ④照護新型冠狀病毒患者（COVID-19）之前","options":["(A) 僅①②","(B) 僅②③","(C) 僅②④","(D) ①②③④"],"answer":[0,1],"image":"","answer_note":"更正:第59題，答Ａ或Ｂ或AB者均給分。。"},{"id":"md3-111-1-60","subject":"md3","topic":"內科-感染","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"有關進行性多發性白質腦病變（progressive multifocal leukoencephalopathy, PML）之敘述，下列何者錯誤？","options":["(A) 常可以在腦組織的寡樹突細胞（oligodendrocytes）發現John Cunningham virus（JC）病毒顆粒","(B) 近年來大部分病例出現在愛滋病（AIDS）病人","(C) PML病灶，在CT影像會呈現明顯水腫或腫塊效應（edema or mass effect），難以跟其他腫瘤或膿瘍區分","(D) 目前沒有有效治療方式"],"answer":2,"image":""},{"id":"md3-111-1-61","subject":"md3","topic":"內科-感染","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"關於初次發生、未曾使用過抗生素預防或治療的腹膜炎，其致病原與抗生素治療，下列敘述何者錯誤？","options":["(A) 肝硬化病人發生原發性細菌性腹膜炎（primary bacterial peritonitis）的經驗性抗生素治療（empirical antibiotic therapy）選擇，原則上不需要考慮針對厭氧菌（anaerobes）","(B) 肝硬化病人發生原發性細菌性腹膜炎（primary bacterial peritonitis）的致病原中，最常見是革蘭氏陽性菌（Gram-positive bacteria）","(C) 次發性細菌性腹膜炎（secondary bacterial peritonitis）的致病原，常見的是腸道革蘭氏陰性菌（enteric Gram- negative bacteria）和厭氧菌（anaerobes）","(D) 次發性細菌性腹膜炎（secondary bacterial peritonitis）的治療除了抗生素以外，也需要開刀介入"],"answer":1,"image":""},{"id":"md3-111-1-62","subject":"md3","topic":"內科-感染","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"28歲確診人類免疫不全病毒（HIV）感染男性病人有3週漸進嚴重的體重減輕、發燒、乾咳與氣促（dyspnea），入院檢查發現臉部脂漏性皮膚炎（seborrheic dermatitis）、口腔念珠菌感染（oral candidiasis）、嘴唇粘膜發紺（cyanosis），在呼吸室內空氣（ambient air）時血氧飽和度（oxygen saturation）是86%。胸部X光和電腦斷層顯示雙側嚴重間質性肺炎（interstitial pneumonitis），並未發現肋膜積液（pleural effusion）。針對這位病人的間質性肺炎，下列病因與處置的敘述，何者錯誤？","options":["(A) 此臨床肺炎病徵最常見的診斷是肺囊蟲肺炎（Pneumocystis jirovecii pneumonia）","(B) 針對此臨床肺炎病徵最常見的致病原，trimethoprim-sulfamethoxazole是優先建議的治療","(C) 針對此肺炎臨床病徵最常見的致病原，此時病人的輔助治療並不適合加上類固醇（steroids）","(D) 針對此肺炎臨床病徵最常見的致病原，在治療療程結束後，還需要續用低劑量原抗生素以預防再發"],"answer":2,"image":""},{"id":"md3-111-1-63","subject":"md3","topic":"內科-感染","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"皮膚軟組織感染之經驗性抗微生物製劑選擇，若過去無藥物過敏記錄，且沒有其他慢性疾病，則下述各診斷，建議的第一線治療何者最不恰當？","options":["(A) 狗咬傷 — amoxicillin-clavulanate或ampicillin-sulbactam","(B) 帶狀疱疹（免疫力正常，大於50歲）— acyclovir","(C) 蜂窩性組織炎（staphylococcal or streptococcal）— vancomycin","(D) 壞死性筋膜炎 — 能同時治療嗜氧菌及厭氧菌的抗生素組合"],"answer":2,"image":""},{"id":"md3-111-1-64","subject":"md3","topic":"內科-胸腔","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"下列社區型肺炎診斷工具的說明，何者錯誤？","options":["(A) 痰液抹片有利於致病菌的診斷。而品質好的抹片標準是每個低倍視野下有＞10個嗜中性白血球（neutrophil）及＞10個上皮細胞（squamous epithelial cells）","(B) 若是需住院的社區型肺炎，一般而言血液培養的陽性率約為5～14%","(C) 可用尿液檢測Legionella pneumophila（serogroup 1）","(D) 可用尿液檢測pneumococcal感染"],"answer":0,"image":""},{"id":"md3-111-1-65","subject":"md3","topic":"內科-感染","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"引起皮膚軟組織感染的病原菌，可能有不同接觸史或表現形態，下列何者錯誤？","options":["(A) Pseudomonas — hot-tub folliculitis","(B) Streptococcus pyogenes — lymphangitis","(C) Treponema pallidum — 露珠狀水泡（dewdrop vesicle）","(D) herpes simplex virus-1（HSV-1）— 唇邊水泡"],"answer":2,"image":""},{"id":"md3-111-1-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"42歲女性無慢性病史，成人預防保健檢查報告：身高158公分、體重64公斤、腰圍88公分、血壓136/88 mmHg、空腹血糖106 mg/dL、總膽固醇198 mg/dL、三酸甘油脂325 mg/dL、高密度脂蛋白膽固醇52 mg/dL。依前述情況，下列敘述何者錯誤？","options":["(A) 依照臺灣標準屬於肥胖","(B) 空腹血糖偏高","(C) 高三酸甘油脂血症","(D) 符合代謝症候群之診斷標準"],"answer":0,"image":""},{"id":"md3-111-1-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"關於周全性老年醫學評估，下列敘述何者正確？","options":["(A) 所有高齡病患都須進行周全性老年醫學評估","(B) 僅用於了解老人問題及篩選疾病","(C) 評估包含生理、心理、社會及功能等面向","(D) 周全性老年醫學評估很簡單，僅需10分鐘即可完成"],"answer":2,"image":""},{"id":"md3-111-1-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"有關家族樹（genogram or family tree）的敘述，下列何者錯誤？","options":["(A) 是家庭醫師提供以家庭為單位的病人照顧之關鍵工具","(B) 是了解病人家庭背景最簡單且有效率的方法","(C) 可提供病人重要家庭病史及遺傳疾病等資訊","(D) 畫家族樹時病人會緊張，故初診時避免詢問"],"answer":3,"image":""},{"id":"md3-111-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"根據得舒飲食（Dietary Approaches to Stop Hypertension, DASH）對血壓控制的多篇隨機對照試驗（randomized controlled trials），所做系統性回顧與統合分析（systematic review and meta-analysis），結果如下圖，下列敘述何者錯誤？","options":["(A) 證據等級為IIa，結果之建議等級（Grade of recommendation）為A","(B) 整體得舒飲食組顯著下降收縮壓6.74 mmHg（95%CI: -8.26,-5.22）","(C) 在不同亞組的血壓下降程度有所不同","(D) 研究的異質性可能解釋來自各研究設計不同、高血壓狀態、介入持續時間、參與者數量和基線血壓值不同"],"answer":0,"image":"md3-111-1-69.jpeg"},{"id":"md3-111-1-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"在動機式晤談（motivational interviewing）中，RULE代表了晤談的四個重點的英文縮寫，分別是Resist the“righting reflex”，Understand your patient's motivations，Listen to your patient及下列何項？","options":["(A) Engage your patient","(B) Empower your patient","(C) Endorse your patient","(D) Empathy your patient"],"answer":1,"image":""},{"id":"md3-111-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"有關行為改變之跨理論模式（transtheoretical model），下列敘述何者正確？","options":["(A) 可分為考慮期（contemplation）、準備期（preparation）、行動期（action）、維持期（maintenance）四個階段","(B) 考慮期（contemplation）代表病人並無改變的意圖","(C) 行動期（action）代表病人計劃在一個月內開始行為改變","(D) 維持期（maintenance）代表行為改變已持續六個月以上"],"answer":3,"image":""},{"id":"md3-111-1-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"70歲男性退化性膝關節炎病人，詢問使用葡萄糖胺（glucosamine）是否能改善其關節疼痛的症狀，下列以實證醫學PICO方法進行實證查詢之敘述，何者最正確？","options":["(A) patient：老年病人","(B) intervention：葡萄糖胺","(C) comparison of intervention：玻尿酸（hyaluronic acid）","(D) clinical outcome：膝關節置換減少比例"],"answer":1,"image":""},{"id":"md3-111-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"一位65歲男性被診斷為肺癌第四期，預期生命不超過3個月的末期病人，他自述有呼吸困難（dyspnea）的症狀，胸部X光顯示腫瘤有逐漸增大現象，其氧氣飽和度（oxygen saturation）在不使用氧氣下為94%。下列何者最可能解除病人呼吸困難之症狀？","options":["(A) 鴉片類藥物（opioids）","(B) 鎮靜劑，如benzodiazepines","(C) 非類固醇類抗發炎藥（NSAIDs）","(D) 支氣管擴張劑，如albuterol"],"answer":0,"image":""},{"id":"md3-111-1-74","subject":"md3","topic":"影像醫學","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"45歲的林女士到醫院做健康檢查，超音波掃描時意外發現肝臟右葉有一個約4 cm之腫瘤。Dynamic CT影像如圖。林女士最可能的診斷為何？","options":["(A) 肝細胞癌（hepatocellular carcinoma）","(B) 海綿狀血管瘤（cavernous hemangioma）","(C) 多房性包蟲囊腫（multilocular hydatid cyst）","(D) 膽管癌（cholangiocarcinoma）"],"answer":1,"image":"md3-111-1-74.jpeg"},{"id":"md3-111-1-75","subject":"md3","topic":"影像醫學","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"62歲的楊先生，罹患B型肝炎已十多年，每年到醫院追蹤檢查。這次醫師為他開立電腦斷層掃描，發現有異常如圖示。則楊先生最有可能罹患：","options":["(A) 肝硬化（liver cirrhosis）","(B) 脂肪肝（fatty liver）","(C) 猛爆性肝炎（fulminant hepatitis）","(D) 肝血色沉著（hemochromatosis）"],"answer":0,"image":"md3-111-1-75.jpeg"},{"id":"md3-111-1-76","subject":"md3","topic":"內科-心臟血管","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"關於使用藥物治療心臟衰竭的敘述，下列何者正確？","options":["(A) 避免使用carvedilol，可能增加心臟衰竭的死亡率","(B) angiotensin-converting enzyme inhibitor（ACEI）是治療孕婦心臟衰竭的首選藥物","(C) furosemide可能導致低血鈣或高尿酸血症","(D) calcium channel blockers可以降低心臟衰竭的死亡率"],"answer":2,"image":""},{"id":"md3-111-1-77","subject":"md3","topic":"急診醫學","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"有關孕婦急救，下列敘述何者錯誤？","options":["(A) 懷孕婦女造成心臟停止（cardiac arrest）的原因，主要是跟懷孕相關的併發症最有關係","(B) 嚴重外傷的孕婦，昏迷不醒需要心肺復甦術（cardiopulmonary resuscitation, CPR）時，優先救治母親","(C) 急救時輸液的給與，急救輸液量要比標準建議劑量增加50%以上","(D) 心臟停止的孕婦，血管升壓劑（vasopressor）使用的劑量要比未懷孕時增加"],"answer":3,"image":""},{"id":"md3-111-1-78","subject":"md3","topic":"內科-腫瘤","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"++ 42歲男性患有鼻咽癌且正接受放射治療，近數日食慾不振且全身倦怠，抽血檢查Ca16.0 mg/dL，Albumin 2.9 g/dL。下列敘述何者最不適當？","options":["(A) ++ 校正後Ca應為16.88 mg/dL","(B) 心電圖可能出現QT段縮短","(C) 血液透析對於高血鈣治療效果有限","(D) calcitonin的治療效果比bisphosphonates快"],"answer":2,"image":""},{"id":"md3-111-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"病人重症昏迷使用呼吸器，無法簽署醫療之知情同意書，依我國法律規定之親屬代理決定權，代理簽署的優先順序是：","options":["(A) 配偶＞成人直系血親卑親屬＞父母","(B) 父母＞兄弟姐妹＞成人直系血親卑親屬","(C) 祖父母＞兄弟姐妹＞曾祖父母","(D) 祖父母＞一親等直系姻親＞曾祖父母"],"answer":0,"image":""},{"id":"md3-111-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"癌症末期的老婦人自知日子不多，在意識清楚時簽署了DNR意願書交給醫院，將副本交給兒子留存。該老婦人病況惡化失去意識後，患者兒子執意要求醫師竭盡所能為母親施予心肺復甦及插管急救。最後醫師讓步作了急救，但老婦人仍宣告不治。下列關於DNR意願書的敘述，何者最為正確？","options":["(A) 老婦人的DNR意願書，係在其意識清楚時就已經簽立，醫師及病患家屬都應該加以尊重，不應該為其進行心肺復甦以及插管急救等急救措施","(B) 老婦人病況惡化而喪失意識後，既然無法表達其意願，應該由其最近親屬出具DNR同意書來代替，因此醫師並非不能幫老婦人進行急救，但應該先取得其兒子的同意書","(C) 老婦人病況惡化而喪失意識後，既然無法表達其意願，應該由其最近親屬來代理其醫療決定，既然老婦人的兒子執意要求醫師進行急救，醫師應該加以尊重，而進行急救","(D) 老婦人的DNR意願書，係在其意識清楚時就已經簽立，醫師及病患家屬都應該加以尊重。但老婦人病況惡化而喪失意識後，其最近親屬卻要求進行急救。當老婦人的意願與其兒子的決定不同時，醫師只要依照其中一個人的意願即可，不論急救與否，都符合法律上的要求"],"answer":0,"image":""},{"id":"md3-111-2-1","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"病人主訴頻尿，每次尿量都很多，並未使用利尿劑。收集24小時尿液檢查結果：總尿量3500 mL/day，urine osmolality 450 mosmol/L。病人的檢查數值，最符合下列那一種多尿症的診斷？","options":["(A) 溶質性利尿（solute diuresis）","(B) 原發性多飲症（primary polydipsia）","(C) 中樞性尿崩症（central diabetes insipidus）","(D) 腎源性尿崩症（nephrogenic diabetes insipidus）"],"answer":0,"image":""},{"id":"md3-111-2-2","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"關於懷孕期間慢性高血壓的治療建議，下列何者最不適當？","options":["(A) 首選藥物為血管收縮素轉化酶抑制劑（angiotensin-converting enzyme inhibitor）或血管收縮素受體阻斷劑（angiotensin receptor blocker）","(B) 可以使用labetalol或nifedipine控制血壓","(C) 尚無足夠證據證實輕微高血壓的治療能改善懷孕預後","(D) 收縮壓目標控制在130～150 mmHg，而舒張壓目標控制在80～100 mmHg"],"answer":0,"image":""},{"id":"md3-111-2-3","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"在評估胸痛病患時，下列那一個病史與急性主動脈症候群（acute aortic syndrome）之相關性最低？","options":["(A) Ehlers-Danlos syndrome","(B) pregnancy","(C) bicuspid aortic valve","(D) sick sinus syndrome"],"answer":3,"image":""},{"id":"md3-111-2-4","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"下列身體診察徵象與疾病的組合，何者的相關性最低？","options":["(A) Chvostek's sign；低鈣血症","(B) Duroziez's sign；主動脈瓣閉鎖不全","(C) Kussmaul's sign；代謝酸中毒","(D) Romberg's sign；感覺性共濟失調（sensory ataxia）"],"answer":2,"image":""},{"id":"md3-111-2-5","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"下列關於轉移痛（referred pain）之敘述，何者錯誤？","options":["(A) 胸腔或心臟疾病可以有上腹部轉移痛","(B) 胸椎神經病變可以有下腹部轉移痛","(C) 膽道發炎的疼痛常會轉移到鎖骨上或肩胛骨下的區域","(D) 當原發處之疼痛不明顯時，可利用按壓轉移痛的區域來誘發疼痛"],"answer":3,"image":""},{"id":"md3-111-2-6","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"下列有關冠狀動脈心臟病的非侵入式檢查敘述，何者錯誤？","options":["(A) 靜態標準十二導程心電圖之ST段或T波異常，並不能確診是冠狀動脈心臟病","(B) 運動心電圖是最廣泛使用的檢查評估工具，但因運動檢查有千分之一的死亡風險，故檢查場所必須備有急救器材","(C) 合併藥物催迫（pharmacological stress）之核醫心肌灌注造影可用以檢出心肌缺血（ischemia）及心肌梗塞後之疤痕（scar）","(D) 電腦斷層（multi-detector CT）測得之鈣化分數（calcium score）可準確診斷冠狀動脈心臟病，但對疾病預後之應用尚不明確"],"answer":[1,3],"image":"","answer_note":"更正:第6題，答Ｂ或Ｄ或BD者均給分"},{"id":"md3-111-2-7","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"下列何種狀況運動心電圖出現ST-segment depression時，冠狀動脈心臟病可能性最高？","options":["(A) 58歲男性，早發性冠狀動脈心臟病家族史，靜態心電圖為竇性脈及左束支傳導阻滯（LBBB）","(B) 45歲女性，糖尿病及高血壓，靜態心電圖有左心室肥厚（LVH）","(C) 76歲女性，近期運動出現氣促，長期抽菸，靜態心電圖無特殊異常","(D) 65歲男性出現運動後氣促，長期使用乙型交感神經阻斷劑（beta blocker），毛地黃（digoxin）及硝酸鹽（nitrate）類藥物"],"answer":2,"image":""},{"id":"md3-111-2-8","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"下列關於壓力催迫性（stress）核醫心肌灌流造影（stress SPECT）與冠狀動脈心臟病的敘述，何者錯誤？","options":["(A) 電腦斷層高鈣化指數者建議安排運動心電圖或壓力催迫性核醫心肌灌流檢查，依據心肌缺血嚴重度決定是否需要血管再通術","(B) 非心臟外科手術術前風險評估除了考慮心肌缺氧嚴重度及範圍、左心室功能之外，還要考量手術種類及麻醉方式","(C) 若前一次的壓力催迫性核醫心肌造影正常，受試者一年內出現急性心肌梗塞或是死亡的年度風險低於1%。如無特殊狀況，兩年內不需要再追蹤；年長或是糖尿病等高風險族群，可以一年後再複查。完全不需要用藥治療","(D) 壓力催迫性核醫心肌造影完全正常，並不能完全斷言絕對不會發生急性心肌梗塞；因為有時候血管狹窄雖然不嚴重，仍可能發生急性的動脈硬化斑塊破裂，導致血栓形成"],"answer":2,"image":""},{"id":"md3-111-2-9","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"59歲男性，過去有冠狀動脈疾病開過繞道手術，最近6個月運動時胸悶加劇、喘，就診時發現心電圖有新的變化，因此心臟科醫師安排了靜態核醫心肌灌流單光子造影（MPI-SPECT）（圖一）及F-18 FDG正子掃描（PET）（圖二），下列敘述何者錯誤？","options":["(A) 在左心室側壁的心肌灌流缺損多為休休眠的心肌，可以考慮積極進行血管再通治療療","(B) 左心室前壁大部分是瘢痕心肌，血管管再通治療效果不佳","(C) 左心室下壁混和有瘢痕與休眠心肌，血管再通治療效果可能較全為存活心肌處略略差","(D) 左心室心尖混和有瘢痕與休眠心肌，血管再通治療效果可能較全為存活心肌處略差"],"answer":1,"image":"md3-111-2-9.jpeg"},{"id":"md3-111-2-10","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"一位年輕男性因心悸胸悶至急診，心電圖顯示regular narrow QRS tachycardia。下列何者是最不可能的診斷？","options":["(A) orthodromic atrioventricular reentrant tachycardia（AVRT）","(B) atrioventricular nodal reentry tachycardia（AVNRT）","(C) atrial tachycardia","(D) ventricular tachycardia"],"answer":3,"image":""},{"id":"md3-111-2-11","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"一位65歲女性因胸悶至門診，十二導程心電圖發現有心房顫動。為了評估之後缺血性中風風險，可以使用CHA2DS2-VASc score。下列何者不是CHA2DS2-VASc score之計分項目？","options":["(A) 心衰竭","(B) 冠狀動脈心臟病","(C) 年紀大於等於65歲","(D) 深部靜脈血栓"],"answer":3,"image":""},{"id":"md3-111-2-12","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"關於身體診察的異常發現，下列敘述何者錯誤？","options":["(A) 姿態性低血壓的定義為從平躺到起立的3分鐘內收縮壓下降超過20 mmHg，或舒張壓下降超過10 mmHg","(B) 身體診察時看到右上胸骨旁有脈動（pulsation），可懷疑升主動脈瘤","(C) 脈搏每跳之間有差異，稱為奇脈（pulsus paradoxus），常出現在嚴重的左心室收縮功能不全的病人","(D) 雙峰脈波（bifid pulse）可以出現在肥厚型阻塞性心肌症（hypertrophic obstructive cardiomyopathy）的病人"],"answer":2,"image":""},{"id":"md3-111-2-13","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"適當的使用下列藥物被認為對治療heart failure with reduced ejection fraction可以改善症狀和預後，但何者除外？","options":["(A) angiotensin converting enzyme inhibitor","(B) mineralocorticoid receptor antagonist","(C) second-generation calcium channel blocker","(D) angiotensin receptor neprilysin inhibitor"],"answer":2,"image":""},{"id":"md3-111-2-14","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"有關心臟衰竭（heart failure, HF）相關猝死（sudden death）預防描述，何者錯誤？","options":["(A) 在大約一半的心衰竭患者中，是由於心室性心律不整（ventricular arrhythmia）所引起的猝死，HFrEF患者中尤為普遍","(B) 在猝死發作後倖存的心衰竭患者被認為具有很高再猝死的風險，應考慮植入式心臟內去顫器（implantable cardioverter-defibrillator, ICD）","(C) 無論心衰竭的病因為何，凡具有心衰竭的NYHA第I級症狀，但LVEF大於35%的患者，是考慮植入式心臟內去顫器（implantable cardioverter-defibrillator, ICD）預防性治療的合適候選人","(D) 對於心肌梗塞發生之後已經3個月，LVEF≦30%且仍有心室頻脈，即使已使用最佳藥物治療的患者，也建議植入式心臟內去顫器（implantable cardioverter-defibrillator, ICD）"],"answer":2,"image":""},{"id":"md3-111-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"68歲李女士，30年前因輸血感染C型肝炎，目前AST：100 U/L，ALT：126 U/L，HCV genotype 1，腹部超音波下無肝硬化，下列敘述何者錯誤？","options":["(A) 李女士應定期接受肝癌篩檢，包括腹部超音波與胎兒蛋白","(B) 李女士應該接受抗病毒藥物治療","(C) 目前C型肝炎治療主要為「長效干擾素（pegylated interferon）」合併「雷巴威林（ribavirin）」","(D) 若能清除C型肝炎病毒，可以減少肝硬化、肝癌之風險"],"answer":2,"image":""},{"id":"md3-111-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"肝臟切片對評估肝損傷的嚴重程度和級別藉以推測其預後相當重要。在現今肝炎組織學的評分系統中最常用為肝炎組織學活動指數（histologic activity index）。下列何者組織切片發現不屬於其評分系統？","options":["(A) 門脈周邊壞死（periportal necrosis）","(B) 漿細胞浸潤（plasma cell infiltration）","(C) 肝小葉區壞死（intralobular necrosis）","(D) 門脈發炎（portal inflammation）"],"answer":1,"image":""},{"id":"md3-111-2-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"20歲的林小姐最近三個月早晨上班前，發生間斷性下腹部絞痛，其排便次數變多，且糞便形態從正常轉成常便秘，但有時又會腹瀉。她感覺排便完腹部絞痛就會減輕。關於她的症狀，下列敘述何者錯誤？","options":["(A) 此疾病各個年齡層都可能發作，女性較男性為多","(B) 糞便的calprotectin為其診斷性生物標記","(C) 此疾病常伴有脹氣、消化不良、噁心、嘔吐感等症狀","(D) 病理機轉目前仍不清楚，可能與腸道蠕動異常、腸道過度敏感、病患的心理因素、腸道菌叢改變或腸道感染有關"],"answer":1,"image":""},{"id":"md3-111-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"關於大腸直腸癌的敘述何者正確？","options":["(A) 起源於右側結腸的腫瘤預後比左側結腸的好","(B) 肺部是大腸癌最容易轉移的內臟器官","(C) 血清carcinoembryonic antigen（CEA）是用來篩檢大腸癌的指標","(D) 大多數大腸癌的切除後復發會於四年內發生，因此五年存活可當作治癒的指標"],"answer":3,"image":""},{"id":"md3-111-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"下列有關胃腺癌的敘述何者錯誤？","options":["(A) 胃腺癌病理下可分成兩種類型：腸道型及瀰漫型","(B) 瀰漫型胃腺癌好發族群較年輕，其腫瘤之黏附能力消失，且容易造成胃壁之浸潤和增厚，稱為皮革胃（linitis plastica）","(C) 腸道型胃腺癌常以潰瘍來表現，可能和胃幽門螺旋桿菌感染相關","(D) 帶有signet ring cell的瀰漫型胃腺癌若轉移至子宮，稱為Krukenberg's tumor"],"answer":3,"image":""},{"id":"md3-111-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"若因腫瘤而切除十二指腸段，下列何者之吸收過程較不會受到影響？","options":["(A) 鈣","(B) 維他命B12","(C) 葉酸","(D) 鐵"],"answer":1,"image":""},{"id":"md3-111-2-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"下列何者不是胰腺癌（pancreatic adenocarcinoma）的常見症狀？","options":["(A) 體重減輕","(B) 黃疸（jaundice）","(C) 背痛","(D) 低血糖"],"answer":3,"image":""},{"id":"md3-111-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"下列何種情況不是肝細胞癌（hepatocellular carcinoma）的高危險群？","options":["(A) B型肝炎帶原者","(B) 慢性C型肝炎","(C) 肝鈣化點（calcified spot of liver）","(D) 酒精性肝硬化"],"answer":2,"image":""},{"id":"md3-111-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"下列何種情況不適合做肝臟移植？","options":["(A) 失代償性（decompensated）肝硬化","(B) 在UCSF criteria以內的肝細胞癌","(C) 第四期原發性膽管性肝硬化（primary biliary cirrhosis或稱primary biliary cholangitis）","(D) 活動性精神病（active psychosis）"],"answer":3,"image":""},{"id":"md3-111-2-24","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"下列何種免疫抑制劑作用於T淋巴球活化過程中的costimulatory pathway？","options":["(A) tacrolimus","(B) mycophenolate mofetil","(C) sirolimus","(D) belatacept"],"answer":3,"image":""},{"id":"md3-111-2-25","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"下列何項不是馬兜鈴酸腎病變（aristolochic acid nephropathy）的臨床特徵？","options":["(A) marked protein-energy malnutrition","(B) rapid progression to renal failure","(C) upper urinary tract urothelial cancer","(D) disproportionate anemia"],"answer":0,"image":""},{"id":"md3-111-2-26","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"一名60歲女性，3小時前開始左腰疼痛並出現血尿，體溫38.3℃，靜脈腎盂攝影檢查10分鐘前、後呈像如附圖左、右。下列何項治療處置應最優優先考慮？","options":["(A) 給與α1腎上腺素受體阻斷劑","(B) 照會泌尿科醫師尋求介入治療","(C) 投與經驗性抗生素並追蹤培養結果","(D) 開立止痛藥並鼓勵大量喝水"],"answer":1,"image":"md3-111-2-26.jpeg"},{"id":"md3-111-2-27","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"一位27歲女性，長期在腎臟科門診追追蹤IgA nephropathy與輕度蛋白尿。最近懷孕並出現高血壓，下列高血壓相關藥物處置，何者最不適合？","options":["(A) 使用methyldopa控制血壓","(B) 使用long-acting calcium channel blockeers（CCB）控制血壓","(C) 使用labetalol控制血壓","(D) 使用angiotensin-converting-enzyme innhibitors（ACE inhibitors）藥物降低蛋白尿，預預防發生pre-eclampsia"],"answer":3,"image":""},{"id":"md3-111-2-28","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"有關focal segmental glomerulosclerosis（FSGS）的敘述，何者錯誤？","options":["(A) FSGS以血尿、高血壓、各種程度的的蛋白尿及腎功能不全表現，如果出現腎功能不不全、大量蛋白尿，有較高的風險會進入透析治療","(B) 病理報告應包括在corticomedullary jjunction的腎絲球，如果切片的位置太淺，常會會被誤判為minimal change disease（MCD）","(C) 病理報告collapsing type FSGS with seegmental or global glomerular collapse代表有比較較好的預後","(D) 治療續發性的FSGS，不需使用類固固醇，必須針對潛在的根本原因治療"],"answer":2,"image":""},{"id":"md3-111-2-29","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"下列那一段腎小管（renal tubule）可透透過抗利尿荷爾蒙（antidiuretic hormone, ADH））的作用增加對水分的通透性？","options":["(A) 近端腎小管（proximal tubule）","(B) Henle氏環下行枝（descending limb of Henle's loop）","(C) 遠端腎小管（distal convoluted tubule）","(D) 集尿管（collecting duct）"],"answer":[2,3],"image":"","answer_note":"更正:第29題，答Ｃ或Ｄ或CD者均給分。。"},{"id":"md3-111-2-30","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"一位50歲男性因懷疑腎結石接受intravenous urography（IVU）檢查，第3天發現BUN由30 mg/dL升至70 mg/dL，血中creatinine由1.5 mg/dL升至4.5 mg/dL。下列有關顯影劑與腎病變的敘述，何者正確？","options":["(A) 顯影劑可經過reactive oxygen species之機轉，直接傷害腎絲球","(B) 血中creatinine通常在10～14天達高峰，於2～3週後開始恢復","(C) 顯影劑之種類、劑量與腎損傷之嚴重程度無關","(D) 病人若有multiple myeloma或既有的腎臟疾病，較容易發生此併發症"],"answer":3,"image":""},{"id":"md3-111-2-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"關於sarcoidosis疾病的描述，下列何者最適當？","options":["(A) 主要致病機轉為B細胞的活化和自體免疫抗體的產生，再經antibody-dependent cell-mediated cytotoxicity造成組織破壞","(B) 大於95%的病人會有皮膚的侵犯，而約有43%病人會有肺部的侵犯","(C) 典型的淋巴結病理切片檢查之特徵為出現noncaseating granuloma","(D) 大於90%的病人會有hypercalcemia和／或hypercalciuria，常會有腎臟腎絲球的侵犯而造成血中angiotensin- converting enzyme濃度的上升"],"answer":2,"image":""},{"id":"md3-111-2-32","subject":"md3","topic":"內科-胸腔","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"一位72歲男性病人手部有clubbing of fingers的症狀，手部X光檢查發現有hypertrophic osteoarthropathy，此病人的這些臨床特徵與下列何種疾病最有關係？","options":["(A) diabetes mellitus","(B) hemochromatosis","(C) acromegaly","(D) bronchogenic carcinoma"],"answer":3,"image":""},{"id":"md3-111-2-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"有關乾燥症（Sjögren's syndrome），下列敘述何者最適當？","options":["(A) 大於半數以上病人會有明顯臨床症狀之腎臟侵犯","(B) 唾液腺發炎是以CD8+ T淋巴球浸潤為主","(C) 關節炎大部分是屬於non-erosive","(D) 跟HLA-DR5有關"],"answer":2,"image":""},{"id":"md3-111-2-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"下列那個疾病通常不是因為單一基因突變造成發炎體（inflammasome）過度活化（overactive）所引起？","options":["(A) systemic lupus erythematosus（SLE）","(B) familial Mediterranean fever（FMF）","(C) Muckle-Wells syndrome（MWS）","(D) familial cold autoinflammatory syndrome（FCAS）"],"answer":0,"image":""},{"id":"md3-111-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"33歲趙小姐，因為反覆流產3次前來評估是否有免疫相關問題。病人流產兩次發生在孕期8～9週，一次發生33在16週。病人上週於他院驗血之報告如下：WBC＝5,180/mm，HgB＝12.0 g/dL，platelet count＝91,000/mm。下列處置何者對於確立診斷最沒有幫助？","options":["(A) 檢驗lupus anticoagulant","(B) 檢驗anti-platelet antibodies","(C) 檢驗anti-cardiolipin antibodies","(D) 檢驗anti-beta 2 glycoprotein I antibodies"],"answer":1,"image":""},{"id":"md3-111-2-36","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"一位30歲孕婦，產前檢查時診斷罹患侵襲性滋養層細胞疾病（invasive trophoblastic disease），下列何者狀況不屬於高危險因子，因此此病人可以不須接受多種化學藥物組合治療？","options":["(A) 腦部轉移","(B) 懷孕四個月後才發生此疾病","(C) 肺部轉移","(D) 肝臟轉移"],"answer":2,"image":""},{"id":"md3-111-2-37","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"癌細胞透過製造並釋放類似內分泌的體液因子（humoral factors）而產生了所謂的paraneoplastic syndrome。下列paraneoplastic syndrome與其肇因的癌細胞分泌的類似內分泌的體液因子之組合，何者錯誤：","options":["(A) hypercalcemia of malignancy；1,25-dihydroxyvitamin D","(B) Cushing's syndrome；adrenocorticotropic hormone（ACTH）","(C) syndrome of inappropriate antidiuretic hormone secretion（SIADH）；vasopressin","(D) hypercalcemia of malignancy；thyroid hormone"],"answer":3,"image":""},{"id":"md3-111-2-38","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"胃腺癌（gastric adenocarcinoma）的治療，需考慮腫瘤的病理組織表現及腫瘤的分期。下列有關胃腺癌治療的敘述，何者最恰當？","options":["(A) 局部的胃腺癌進行根治性手術切除後，單獨追加輔助性放射治療可增加存活率","(B) 胃腺癌癌細胞對放射治療甚為敏感，針對局部胃腺癌施以放射治療合併化學治療已可達到與根治性手術相當的治癒率","(C) 具有高度表現HER-2/neu（HER-2 over-expression）之胃癌發生轉移復發時，化學治療合併anti-HER2的trastuzumab相較於單獨化學治療可顯著延長存活時間","(D) 組合式化學治療（合併2～3種化學治療藥物）是轉移／復發胃腺癌藥物治療的主流，化學治療合併bevacizumab相較於單獨化學治療可顯著延長存活時間"],"answer":2,"image":""},{"id":"md3-111-2-39","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"Stage II或stage III的直腸癌（rectal cancer）最主要的治療方式仍是手術切除。下列降低直腸癌局部復發的治療方式，何者最不恰當？","options":["(A) 手術採total mesorectal excision（TME）術式","(B) 術前或術後針對骨盆進行放射治療","(C) 5-fluorouracil（5-FU）化學治療合併放射治療","(D) 對抗epidermal growth factor receptor（EGFR）的cetuximab藥物治療合併放射治療"],"answer":3,"image":""},{"id":"md3-111-2-40","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"關於睪丸生殖細胞癌（germ cell tumor）治癒後，下列敘述何者錯誤？","options":["(A) 如果當初接受過包括cisplatin的化學治療，會增加後續發生高血壓、高血脂、代謝症候群、心血管事件的風險","(B) 如果當初接受過高累積劑量的etoposide的化學治療，會增加發生11q23轉位（translocation）的急性骨髓性白血病的絕對風險至80%","(C) 如果當初接受過cisplatin的化學治療，會增加後續發生第二個固態癌症的風險","(D) 如果當初接受過放射治療，會增加後續發生第二個固態癌症的風險"],"answer":1,"image":""},{"id":"md3-111-2-41","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"下列何種做法，對於降低癌症治療造成的中性球低下併發燒（febrile neutropenia）的致死率最沒有幫助？","options":["(A) 一旦發生中性球低下併發燒，立刻給與以經驗為依據的（empirical）抗細菌藥物","(B) 如果中性球低下併發燒持續4至7天以上，使用抗生素治療後，仍持續發燒且無培養結果，給與以經驗為依據的（empirical）抗黴菌藥物","(C) 如果中性球低下併發燒持續7至10天以上，給與以經驗為依據的（empirical）抗病毒藥物","(D) 一旦發生極重度中性球低下（例如：惡性淋巴瘤接受高劑量化學治療後），在未發燒前就立刻給與以經驗為依據的（empirical）抗細菌藥物預防"],"answer":2,"image":""},{"id":"md3-111-2-42","subject":"md3","topic":"內科-血液","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"下列有關於遺傳性球形紅血球症（hereditary spherocytosis）的敘述，何者錯誤？","options":["(A) 過高的mean corpuscular hemoglobin concentration（MCHC＞34）是此病的重要特徵","(B) 所呈現的溶血，主要是血管內溶血（intravascular hemolysis）","(C) 是基因突變引起的疾病。ANK1、SLC4A1、SPTB、SPTA1等基因之突變均可能造成此病","(D) 並不全然是autosomal dominant的遺傳形式，也可以是autosomal recessive的遺傳形式"],"answer":1,"image":""},{"id":"md3-111-2-43","subject":"md3","topic":"內科-血液","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"慢性淋巴性白血病（chronic lymphocytic leukemia, CLL）的特徵，何者錯誤？","options":["(A) 病人周邊血中clonal B cells 5,000/μL以上，是診斷CLL的重要依據","(B) 初步診斷時有貧血的病人，比沒有貧血的病人預後較佳","(C) 其周邊血液抹片常可看到泥細胞（smudge cell）","(D) 丙型球蛋白（gamma globulin）的降低是常見表現之一"],"answer":1,"image":""},{"id":"md3-111-2-44","subject":"md3","topic":"內科-心臟血管","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"Aspirin是目前最廣泛使用的抗血小板藥物，其抗血小板的作用機轉是透過：","options":["(A) 阻斷thromboxane A2引發的血小板活化","(B) 阻斷血小板上的P2Y12接受器","(C) 抑制ADP引發的血小板聚集","(D) 抑制vWF（von Willebrand factor）的功能"],"answer":0,"image":""},{"id":"md3-111-2-45","subject":"md3","topic":"內科-胸腔","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"下列有關氣喘治療敘述，何者最為適當？","options":["(A) 懷孕婦女不可使用任何吸入性類固醇，避免造成畸胎","(B) aspirin-sensitive asthma對吸入性類固醇沒有療效","(C) 氣喘如果得到良好控制，在手術過程中全身麻醉及插管並非禁忌","(D) allergic bronchopulmonary aspergillosis發生在氣喘病人，口服類固醇是禁忌不可使用"],"answer":2,"image":""},{"id":"md3-111-2-46","subject":"md3","topic":"內科-風濕免疫過敏","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"63歲女性，3週前因下背劇痛至門診求診，並接受non-steroid anti-inflammatory drug止痛劑緩解症狀。最近一週開始出現咳嗽、發燒症狀及呼吸急促現象，至急診室求診發現胸部X光片有兩側肺野浸潤疑似肺炎現象，無3心臟擴大或肋膜積水，血液檢查白血球：14,200/mm；neutrophil：70%；eosinophil：25%；C-reactive protein：0.9 mg/dL，其他生化檢查正常。下列何種檢查對確定診斷最有幫助？","options":["(A) 胸部電腦斷層","(B) blood antineutrophil cytoplasmic antibody","(C) serum anti-IgE","(D) bronchoalveolar lavage"],"answer":3,"image":""},{"id":"md3-111-2-47","subject":"md3","topic":"內科-胸腔","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"下列何種檢查，最能正確診斷特發性肺纖維化症（idiopathic pulmonary fibrosis）？","options":["(A) 胸部X光片","(B) 電腦斷層攝影","(C) 動脈血液氣體分析","(D) 肺功能檢查"],"answer":1,"image":""},{"id":"md3-111-2-48","subject":"md3","topic":"內科-胸腔","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"關於呼吸器相關肺炎（ventilator associated pneumonia），下列敘述何者最適當？","options":["(A) 當病人接受氣管內管插管並將氣囊充氣打飽後，可完全避免吸入性肺炎","(B) 應將病人頭部抬高至15度，以避免產生呼吸器相關的吸入性肺炎","(C) 給與長期之預防性抗生素，可避免產生呼吸器相關的肺炎","(D) 因為心因性肺水腫而導致的呼吸衰竭，採用非侵襲性正壓通氣較插管使用呼吸器可減少呼吸器相關肺炎的發生"],"answer":3,"image":""},{"id":"md3-111-2-49","subject":"md3","topic":"內科-感染","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"罹患開放性肺結核的35歲女性病人，接受含有isoniazid、rifampin、ethambutol及pyrazinamide的抗結核藥物治療；治療前的檢查證實並未罹患B或C型肝炎且AST為20 U/L（正常值：13～39 U/L），ALT為14 U/L（正常值：7～52 U/L）。在治療1個月時，病人精神明顯改善且食慾良好，但卻發現肝功能指數異常（AST：48 U/L及ALT：71 U/L）。下列何者為最適當之處置？","options":["(A) 繼續維持目前治療處方，並密切追蹤肝功能","(B) 停止所有抗結核藥物，等待肝功能恢復後，再重新治療","(C) 停止isoniazid、rifampin及pyrazinamide等可能會傷害肝臟的藥物，並加入streptomycin及moxifloxacin等不會傷害肝臟的藥物治療","(D) 先停止最容易傷害肝臟的藥物pyrazinamide，並密切追蹤肝功能"],"answer":0,"image":""},{"id":"md3-111-2-50","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"75歲獨居老太太，有糖尿病及高血壓病史，被鄰居發現倒在地下室，神智不清，下列何者最不可能造成她神智不清？","options":["(A) 低血糖","(B) 中風","(C) 低血脂","(D) 低血壓"],"answer":2,"image":""},{"id":"md3-111-2-51","subject":"md3","topic":"內科-感染","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"下列何者不是COVID-19肺部感染的特徵？","options":["(A) COVID-19引起的呼吸衰竭主要是第二型呼吸衰竭（type II respiratory failure）","(B) COVID-19可以造成急性呼吸窘迫症候群","(C) COVID-19引起的呼吸衰竭，通常需要呼吸器來幫忙維持足夠的血氧濃度","(D) 嚴重感染COVID-19時，肺泡充滿了液體，內含有許多的發炎物質"],"answer":0,"image":""},{"id":"md3-111-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"下列有關葛瑞夫氏病（Graves' disease）的敘述，何者最不適當？","options":["(A) 常見於女性，男性發病率只有女性發病率的十分之一。發病年齡通常介於20至50歲之間","(B) 於老年人發病時，甲狀腺機能亢進的症狀較不明顯，可能僅以疲倦及體重減輕表現，稱為淡漠性甲狀腺機能亢進（apathetic thyrotoxicosis）","(C) 發病時，臨床會出現心悸、心跳過速、體重減輕等症狀，可能有高達約80%的病例，會出現甲狀腺過氧化酶抗體（thyroid peroxidase antibody）","(D) 臨床病程中常合併眼病變，可能造成眼瞼內縮、凸眼、複視。甲狀腺功能高低與眼病變的臨床症狀成正相關"],"answer":3,"image":""},{"id":"md3-111-2-53","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"甲狀腺癌是目前臺灣及全世界成長最快速的癌症之一，下列有關甲狀腺癌的敘述，何者錯誤？","options":["(A) 甲狀腺乳突癌是最常見的甲狀腺癌，約占細胞分化良好之甲狀腺癌的80～85%","(B) 甲狀腺乳突癌無法以甲狀腺細針穿刺細胞學提供術前診斷","(C) 甲狀腺濾泡癌的侵襲性多以血行性轉移至肺部及骨骼","(D) 甲狀腺濾泡癌的病患中，若原發腫瘤大於4公分或病患年齡大於50歲，其治療的預後不佳"],"answer":1,"image":""},{"id":"md3-111-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"下列有關糖尿病與心臟血管疾病的敘述，何者最不恰當？","options":["(A) 糖尿病會增加心肌梗塞及心臟衰竭的發生率","(B) 有心肌梗塞或心臟衰竭的病人都不可以使用metformin","(C) aspirin及statin類藥物可以有效預防糖尿病病人的心臟血管疾病發生","(D) thiazolidinediones可能會增加心臟衰竭的發生"],"answer":1,"image":""},{"id":"md3-111-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"下列敘述何者錯誤？","options":["(A) pioglitazone會增加鬱血性心臟衰竭的風險","(B) DPP-4（dipeptidyl peptidase-4）抑制劑會提升胰島素分泌，減少昇糖素（glucagon）分泌，單獨使用易引起低血糖","(C) SGLT2（sodium-glucose cotransporter 2）抑制劑比起其它降血糖藥物，有較明顯減輕體重的功效","(D) metformin可以減少肝臟葡萄糖新生（gluconeogenesis）"],"answer":1,"image":""},{"id":"md3-111-2-56","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"下列敘述何者錯誤？","options":["(A) 低密度脂蛋白受體（LDL receptor）發生突變失去功能，會增加血中低密度脂蛋白膽固醇，加速動脈粥狀硬化","(B) PCSK9基因突變失去功能，會增加血中低密度脂蛋白膽固醇，加速動脈粥狀硬化","(C) 降膽固醇首選藥物是statin類","(D) 降三酸甘油脂首選藥物是fibrate類"],"answer":1,"image":""},{"id":"md3-111-2-57","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"下列敘述何者錯誤？","options":["(A) 肥胖易伴有代謝症候群（metabolic syndrome）","(B) 脂質營養不良（lipodystrophy）易伴有代謝症候群","(C) 代謝症候群的病人，血中高密度脂蛋白膽固醇（HDL-C）濃度比一般人高","(D) 代謝症候群的病人，血中脂締素（adiponectin）濃度比一般人低"],"answer":2,"image":""},{"id":"md3-111-2-58","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"一位25歲的男性，因高血壓至門診就醫，檢查發現左側腎上腺有一個4公分的腫瘤，經尿液與影像檢查後，高度懷疑為嗜鉻細胞瘤（pheochromocytoma），即將接受手術治療。目前除了未服藥的狀況下血壓高達150/90 mmHg以外，心跳、呼吸、血氧皆正常。下列處置，何者最正確？","options":["(A) 立刻安排緊急手術切除","(B) 儘快安排電腦斷層導引的腎上腺腫瘤切片檢查","(C) 手術前7～10天需先給與適量的α阻斷劑和水分補給，必要時再給與β阻斷劑","(D) 立即給與體抑素類似物（somatostatin analogue）治療，抑制兒茶酚胺（catecholamines）的分泌"],"answer":2,"image":""},{"id":"md3-111-2-59","subject":"md3","topic":"內科-感染","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"有關肺結核病患之感染管制，下列敘述何者最不適當？","options":["(A) 開放性肺結核病人須儘早移入單人負壓隔離病室","(B) 病室門窗應關閉，且每小時應有6至12次氣體交換","(C) 照護者使用N95口罩（或更高等級）做防護","(D) 醫療人員接種BCG疫苗（卡介苗）可有效預防感染肺結核之風險"],"answer":3,"image":""},{"id":"md3-111-2-60","subject":"md3","topic":"內科-感染","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"Extended-spectrum β-lactamase（ESBL）可以水解下列那些β-lactam類抗生素，而使其失效？ћcefotaxime（第三代頭孢子素） ќaztreonam（monobactam） ѝertapenem（carbapenem）","options":["(A) 僅ћќ","(B) 僅ћѝ","(C) 僅ќѝ","(D) ћќѝ"],"answer":0,"image":""},{"id":"md3-111-2-61","subject":"md3","topic":"內科-感染","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"下列有關Q熱疾病（Q fever）的敘述，何者正確？","options":["(A) 相同的暴露風險下，小於15歲的年輕人相對於年長者有症狀的感染是較常見的","(B) 人傳人是常見的傳播途徑","(C) 急性感染常表現為心內膜炎","(D) 宿主可經由吸入霧化空氣（aerosol）中Q熱細菌而感染"],"answer":3,"image":""},{"id":"md3-111-2-62","subject":"md3","topic":"內科-感染","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"針對細菌性腦膜炎病人的診斷，下列有關腦脊髓液（CSF）檢查之敘述何者錯誤？","options":["(A) 超過一半病人的CSF會有polymorphonuclear（PMN）白血球增加至＞100 cells/μL現象","(B) 超過一半病人的CSF/serum glucose比值＜0.4","(C) 超過一半病人的CSF細菌培養會是陽性","(D) 病人CSF進行Gram's stain檢查幫助不大，只有大約20%可以看到致病原"],"answer":3,"image":""},{"id":"md3-111-2-63","subject":"md3","topic":"內科-腫瘤","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"48歲男性二週來頭隱隱的痛與漸進步履不穩，入院身體檢查沒有發燒，但是發現口腔念珠菌感染（oral candidiasis）和困難維持軀幹平衡，胸部X光並無異常。電腦斷層發現右側一個3.5 cm小腦腫瘤併有病灶周圍水腫（perifocal edema）。血液人類免疫不全病毒（HIV）西方墨點（Western blot）呈現陽性反應，血液CD4數3值是48 cells/mm，血漿HIV病毒量是432,000 copies/ml。血清弓蟲（Toxoplasma gondii）抗體呈陽性反應，隱球菌抗原（cryptococcal antigen）呈現陰性反應。針對這些病徵的病因與處置，下列敘述何者錯誤？","options":["(A) 此臨床腦部病徵最常見的病因是原發性中樞神經淋巴瘤（primary central nervous system lymphoma），預後不好，開顱手術（craniotomy）有風險應該避免執行。同時應儘快給與化學治療（chemotherapy）","(B) 先以抗弓蟲腦炎治療一到二週後，再追蹤腦部影像學變化。如果沒有改善，需要開顱手術確認診斷","(C) 病人已經符合愛滋病（AIDS）診斷，在排除隱球菌腦膜腦炎（cryptococcal meningoencephalitis）和結核腦膜腦炎（tuberculous meningoencephalitis）後，儘快投與抗病毒組合治療（combination antiretroviral therapy）","(D) 這位病人需要服用trimethoprim-sulfamethoxazole預防肺囊蟲肺炎（Pneumocystis jirovecii pneumonia）"],"answer":0,"image":""},{"id":"md3-111-2-64","subject":"md3","topic":"內科-感染","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"20歲男性病人，自從兒童時被診斷有hypogammaglobulinemia，需要定期輸注免疫球蛋白（immunoglobulin）。近期，與同學前往山區露營，返家5天後出現日趨嚴重的腹瀉、腹脹、噁心、嘔吐和體重降低，服用止瀉藥和ciprofloxacin，均不見改善。整個病程並沒有發燒。糞便檢查並未出現潛血（occult blood）反應，細菌學培養也沒有長出腸道致病性細菌。糞便顯微鏡檢400倍下發現有移動的寄生原蟲。下列敘述何者正確？","options":["(A) 最有可能的致病原是Giardia lamblia","(B) 針對此感染最好的治療是azithromycin","(C) 預防此感染原的最好方法是飲用經氯消毒處理的水","(D) 治癒後很常出現Guillain-Barré syndrome併發症"],"answer":0,"image":""},{"id":"md3-111-2-65","subject":"md3","topic":"內科-感染","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"80歲男性因發燒一週，合併下背痛來到診間就診，外院診斷為腰椎L1～L2的骨髓炎，則下列敘述何者錯誤？","options":["(A) 成人脊椎骨髓炎症狀並不典型，較常見的症狀為發燒及局部疼痛","(B) 腰椎不是成人的急性脊椎骨髓炎最常見的感染部位","(C) 最常見的致病原為格蘭氏陽性菌","(D) magnetic resonance imaging（MRI）是脊椎骨髓炎診斷的黃金標準，若不適合使用MRI，則考慮使用positron emisson tomography（PET）"],"answer":1,"image":""},{"id":"md3-111-2-66","subject":"md3","topic":"家醫-行為與社區醫學","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"有關健康與疾病照護模式（models of health, illness & health care）的敘述，下列何者正確？","options":["(A) 醫療化（medicalization）是biopsychosocial model的優點","(B) 生物適應（biological adaptation）是biomedical model的特性","(C) holistic model認為illness is a creative opportunity","(D) ethnomedical cultural model是合併biomedical, holistic and cultural factors"],"answer":2,"image":""},{"id":"md3-111-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"80歲中風且有尿失禁的男性病人，因右股骨頸骨折被送至急診室，病史詢問時發現是家人摑掌且推倒所致。有關老人虐待（elder abuse）議題，下列敘述何者錯誤？","options":["(A) 該案例屬於忽略（neglect）或自我忽視（self-neglect）","(B) 老人虐待會發生在家庭、社區、醫療機構、安養中心","(C) 加害者可以是陌生人、照護者、家庭成員或長照機構住戶","(D) 心理虐待為經由言語或非言語的行為，造成老人心理情緒痛苦沮喪"],"answer":0,"image":""},{"id":"md3-111-2-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"有關家庭醫師照顧青少年病人時的角色敘述，下列何者錯誤？","options":["(A) 要能了解生長與體重的變化，才能發現可能的問題","(B) 學校成績問題是此發展階段最重要的議題","(C) 須注意此階段的肥胖及飲食問題，並提供病人及家屬衛教諮詢","(D) 應於就診時與其討論藥物或喝酒對於駕駛的危險"],"answer":1,"image":""},{"id":"md3-111-2-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"有關旅遊前疫苗的接種原則，下列何者最正確？","options":["(A) 活性減毒疫苗與非活性疫苗可同時接種；不同時接種時，至少要間隔28天","(B) 2種活性減毒疫苗可同時接種；不同時接種時，至少要間隔28天","(C) 活性減毒疫苗與非活性疫苗不可同時接種","(D) 2種活性減毒疫苗不可同時接種"],"answer":1,"image":""},{"id":"md3-111-2-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"55歲肥胖糖尿病男性，最近在家人及心臟科醫師的強烈要求下，來到戒菸特別門診。從病史得知一年前曾發生疑似心肌梗塞，當時醫師即建議戒菸，因為許多因素而未戒菸。依據戒菸行為諮商的5A策略，此病人目前最可能符合下列那一個策略階段？","options":["(A) Ask：確認有抽菸的習慣，說明戒菸的好處及給予衛教單張","(B) Assess：評估未來30天內戒菸的意願","(C) Assist：積極給予協助，安排戒菸計畫","(D) Arrange：安排各項追蹤策略，包含約診與電話聯繫等"],"answer":1,"image":""},{"id":"md3-111-2-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"某社區居民約有8000位，老年人口約為24%，醫療機構僅有衛生所，沒有私人藥局也沒有其他的基層診所。若想協助當地民眾找出健康問題並予以改善，下列何種方式最有效且可靠？","options":["(A) 儘速召集全區主要關鍵人物（key person）座談，以了解當地民眾的健康需求","(B) 開始著手規劃進行流行病學調查，以收集正確的居民健康狀態資料","(C) 即刻走訪該地區各個角落觀察可能的問題，並詢問居民對於健康的需求","(D) 先蒐集官方衛政資料及過去該地區的流病報告，了解該地區的健康狀態"],"answer":3,"image":""},{"id":"md3-111-2-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"85歲女性居家照護個案，近一個月跌倒兩次，下列何者可能是導致她跌倒的內在因子（intrinsic factors）？ћ 跌倒過去史 ќ視力障礙 ѝ憂鬱 ў認知障礙 џ下肢無力","options":["(A) 僅ћќџ","(B) 僅ћќѝџ","(C) 僅ћќўџ","(D) ћќѝўџ"],"answer":3,"image":""},{"id":"md3-111-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"下列何者不是推動安寧緩和醫療的目的？","options":["(A) 提升末期病人生活品質","(B) 提升末期病人死亡品質","(C) 改善症狀不適","(D) 延長生命"],"answer":3,"image":""},{"id":"md3-111-2-74","subject":"md3","topic":"影像醫學","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"十二指腸潰瘍在癒合過程中會造成十二指腸球部的變形，此變形符合下列何者？","options":["(A) 幸運草（三葉草）變形（cloverleaf deformity）","(B) 雙壁徵象（double wall sign）","(C) 足球徵象（football sign）","(D) 倒V徵象（inverted V sign）"],"answer":0,"image":""},{"id":"md3-111-2-75","subject":"md3","topic":"影像醫學","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"39歲女性，健康檢查時發現有心雜音，進一步做了電腦斷層檢查影像如附圖，最可能的診斷為下列何者？","options":["(A) 開放性動脈導管（patent ductus arteriosus）","(B) 主動脈假性動脈瘤（aortic pseudoaneurysm）","(C) 主動脈瘤（aortic aneurysm）","(D) 主動脈縮窄（coarctation of aorta）"],"answer":0,"image":"md3-111-2-75.jpeg"},{"id":"md3-111-2-76","subject":"md3","topic":"內科-腎臟","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"75歲女性被家人送至急診室，主訴最近1個月食慾不振和全身虛弱，過去病史有高血壓及糖尿病約10年。上星期門診和此次急診血液生化檢驗皆發現病人有低血鈉的情形。關於低血鈉（hyponatremia）的敘述，下列何者最不適當？","options":["(A) 須做血糖狀況的評估，以排除因為高血糖（hyperglycemia）所導致的低血鈉","(B) 如果病人呈現全身水腫（edema）的情形，應考慮低血鈉可能與心臟衰竭、腎臟疾病有關","(C) 如果血液鈉離子小於130 mEq/L，緊急處置必須包含靜脈滴注3% hypertonic saline","(D) 嚴重低血鈉病人，補充血中鈉離子時，其上升速度不可超過每24小時6 mEq"],"answer":2,"image":""},{"id":"md3-111-2-77","subject":"md3","topic":"急診醫學","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"依據2015美國心臟學會心肺復甦術及緊急心臟照護指引，有關心跳停止（cardiac arrest）病人恢復自發性循環（return of spontaneous circulation, ROSC）後，下列敘述何者正確？o","options":["(A) 使用低溫療法，控制中心體溫（core body temperature）在32-36 C之間，持續24小時，可以改善存活率及神經學症狀","(B) ROSC後6小時內的神經反射（neurologic reflexes）可以用來預測預後，因此可做為治療準則之參考","(C) ROSC後的病人，神智意識清醒時，仍建議使用低溫療法來增加存活率o","(D) 低溫療法病人，在維持溫度為32 C時，產生高血鉀比產生低血鉀之機會較高"],"answer":0,"image":""},{"id":"md3-111-2-78","subject":"md3","topic":"內科-內分泌代謝","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"關於糖尿病酮酸中毒（Diabetic ketoacidosis, DKA）之敘述，下列何者最不適當？","options":["(A) DKA主要發生在第一型糖尿病（type Ⅰ DM）病人，也可發生於新診斷第二型糖尿病（type Ⅱ DM）病人","(B) 血糖值通常＞250 mg/dL，陰離子間隙（anion gap）＞10 mEq/L，動脈血pH＜7.3","(C) DKA病人的血糖值亦可能為正常","(D) DKA病人的血清鉀離子濃度大多為低下"],"answer":3,"image":""},{"id":"md3-111-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"林先生最近因為頻繁的胃痛而到某教學醫院求診，經過陳醫師診療後建議接受胃鏡檢查。林先生於接受胃鏡檢查時，發現為他進行胃鏡檢查的陳醫師，一面進行胃鏡檢查，一面對他身後好幾位穿著白袍的醫學生討論其病情，同時解說胃內的結構，林先生覺得心裡不太舒服，也覺得這次胃鏡做得特別久。請問陳醫師這樣的教學方式是否適當？","options":["(A) 合適，林先生既然到教學醫院求診，應該預期會遇到許多實習醫師或見習醫師，因此陳醫師的教學並沒有不適當的地方","(B) 合適，林先生對於陳醫師教學的當時，並沒有表示反對的意思，因此陳醫師的教學並沒有不適當的地方","(C) 不合適，林先生雖然沒有表示反對，但陳醫師為林先生進行的是侵入性檢查，所以不應該有學生在旁邊觀看","(D) 不合適，陳醫師事前並沒有對林先生說明教學的意旨，也未事前徵求林先生的同意"],"answer":3,"image":""},{"id":"md3-111-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"進行愛滋病患的人體試驗時，為確保病患隱私，簽署同意書時應注意的狀況，下列敘述何者正確？","options":["(A) 知情同意即可，病患可不用簽署同意書","(B) 病患讀完同意書了解後，由他人（非指定）代簽，以確認有此病患","(C) 病患讀完同意書了解後，由指定的人員代簽，以確認有此病患","(D) 病患或其法定代理人必須簽署同意書"],"answer":3,"image":""},{"id":"md3-112-1-1","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"19歲女性病患，自述過去身體健康，並無酗酒或病毒性肝炎病史。因為近一個月來下肢浮腫和血液檢查發現肝功能異常就醫。在外院腹部超音波顯示肝硬化。血液檢查發現albumin：3.2 g/dL；AST（GOT）：51 U/L；ALT（GPT）：43 U/L；總膽紅素：1.11 mg/dL；鹼性磷酸酶（alkaline phosphatase）：274 U/L；ceruloplasmin為11.1 mg/dL（正常參考值，20～60 mg/dL）。病患最有可能的診斷為何？","options":["(A) hemochromatosis","(B) amyloidosis","(C) primary biliary cirrhosis","(D) Wilson's disease"],"answer":3,"image":""},{"id":"md3-112-1-2","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"有關頭痛之敘述，下列何者正確？","options":["(A) 原發性頭痛（primary headache）最常見原因為腦瘤（brain tumor）","(B) 偏頭痛患者常見單側性頭痛，伴隨抽痛及嘔吐或畏光","(C) 次發性頭痛（secondary headache）最常見原因為腦部血管異常","(D) 新發生的嚴重性頭痛，一般而言僅給與止痛劑治療即可"],"answer":1,"image":""},{"id":"md3-112-1-3","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"一位80歲獨居老人，多日未外出，經里長發現意識不清、皮膚乾癟、眼眶深陷，血壓80/55 mmHg。緊急送醫3發現頸靜脈低陷，胸部X光肺野清晰、心電圖為竇性頻脈、血中白血球7000/mm、BUN 45 mg/dL、creatinine + 1.4 mg/dL、Na155 mEq/L。此病人最有可能的診斷為：","options":["(A) 急性心肌梗塞引起心因性休克（cardiogenic shock）","(B) 嚴重性過敏反應（anaphylaxis）","(C) 低血容積性休克（hypovolemic shock）","(D) 心包膜填塞（pericardial tamponade）引起休克"],"answer":2,"image":""},{"id":"md3-112-1-4","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"血液中酒精濃度超過多少g/dL，可能造成輕度昏迷（light coma）及生命徵候不穩（depressed vital signs）？","options":["(A) 0.05","(B) 0.10","(C) 0.20","(D) 0.30"],"answer":3,"image":""},{"id":"md3-112-1-5","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"下列有關藥物動力或藥效的描述，那一項最正確？","options":["(A) 心臟衰竭時，藥物在心臟或腦部的效用會相對減低","(B) 心臟衰竭時，藥物從腸胃道的吸收會增加","(C) 心臟衰竭時，藥物經由腎臟或肝臟的廓清率（clearance）會增加","(D) 一般來說，即使沒有明顯的腎臟疾病，老年人之藥物腎廓清率仍然可能下降達35～50%"],"answer":3,"image":""},{"id":"md3-112-1-6","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"關於淋巴水腫（lymphedema）的描述，下列何者錯誤？","options":["(A) 持續的淋巴水腫會引起發炎和免疫反應，造成脂肪和膠原蛋白在皮膚以及皮下的堆積","(B) 次發性淋巴水腫常見於腋下或是鼠蹊部淋巴結的手術摘除以及放射線治療","(C) 下肢淋巴水腫的病人使用潤膚劑塗抹患側是禁忌，因為會增加皮膚感染","(D) 淋巴水腫的肢體經常不會伴隨疼痛"],"answer":2,"image":""},{"id":"md3-112-1-7","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"關於B-type natriuretic peptide（BNP）和N-terminal pro-BNP（NT-proBNP）在心衰竭的診斷與治療，下列何者正確？","options":["(A) 在舒張性心衰竭不會上升","(B) 對收縮性心衰竭的診斷有幫助，但是無法評估疾病的預後","(C) 在健康人的血中濃度會隨著年紀而上升","(D) 血中濃度在右心衰竭的病人不會上升"],"answer":2,"image":""},{"id":"md3-112-1-8","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"有關心音及心雜音的敘述，下列何者錯誤？","options":["(A) 在嚴重肺高壓症病患，肺動脈瓣環擴大造成肺動脈瓣閉鎖不全，在左胸骨側會有舒張期心雜音，稱為Graham Steell murmur","(B) 主動脈瓣膜閉鎖不全會產生舒張早期如風吹的心雜音，稱為Austin Flint murmur","(C) 嚴重二尖瓣（僧帽瓣）狹窄病患有些聽診時會有opening snap，通常在心尖內側，第二心音後約0.05至0.12秒","(D) 二尖瓣（僧帽瓣）閉鎖不全的心雜音，通常位於心尖部位，為全收縮期雜音，且會傳至左腋下"],"answer":1,"image":""},{"id":"md3-112-1-9","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"比較竇結細胞（sinus nodal cell）與心室細胞（ventricular cell）的動作電位，下列敘述何者正確？","options":["(A) 就靜態膜電位（resting membrane potential）而言，竇結細胞較極化（more polarized）","(B) 第0期（Phase 0）上衝速度（upstroke），竇結細胞較快速","(C) 第2期（Phase 2），竇結細胞較顯著","(D) 第4期（Phase 4）有舒張期去極化（diastolic depolarization）是竇結細胞的特徵"],"answer":3,"image":""},{"id":"md3-112-1-10","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"下列針對主動脈縮窄（coarctation of the aorta）的敘述，何者錯誤？","options":["(A) 狹窄處最常見於左鎖骨下動脈遠端，且近動脈韌帶（ligamentum arteriosum）開口端","(B) 屬於一種先天性心臟病","(C) 通常女性多於男性","(D) 常見於有性腺發育不全（gonadal dysgenesis）的患者（例如Turner's syndrome）"],"answer":2,"image":""},{"id":"md3-112-1-11","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"某女士因前一日無故暈倒到醫院內科門診求治，醫師懷疑是orthostatic hypotension，就讓該女士平躺5分鐘後，測量血壓，為124/78 mmHg，再請該女士起立，於1分鐘內再測量血壓，為90/62 mmHg。下列診斷何者為正確？","options":["(A) 因收縮壓下降超過20 mmHg，舒張壓下降超過10 mmHg，符合orthostatic hypotension的診斷","(B) 因收縮壓下降超過20 mmHg，但舒張壓下降未超過20 mmHg，不符合orthostatic hypotension的診斷","(C) 因未測量心跳數，無法判斷是否有orthostatic hypotension","(D) 因起立後不到3分鐘即測量血壓，無法判斷是否有orthostatic hypotension"],"answer":0,"image":""},{"id":"md3-112-1-12","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"有關抗血小板藥物的敘述，下列何者正確？","options":["(A) 新的抗血小板藥物ticagrelor比過去clopidogrel抑制adenosine diphosphate（ADP）受體半衰期更長，作用時間更久","(B) 相較於clopidogrel，ticagrelor與prasugrel兩種藥物對STEMI病患在心臟死亡事件及心肌梗塞與中風的機會均有意義下降","(C) aspirin抑制血小板活性，主要是抑制cyclooxygenase，使arachidonic acid無法變成thromboxane A2","(D) 長期口服glycoprotein IIb/IIIa antagonist被證實可以有效地降低心肌梗塞發作及死亡率"],"answer":2,"image":""},{"id":"md3-112-1-13","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"下列何者不是寬的脈搏壓（wide pulse pressure）要考慮的鑑別診斷？","options":["(A) 主動脈瓣狹窄（aortic stenosis）","(B) 甲狀腺毒症（thyrotoxicosis）","(C) 感染發燒","(D) 開放性動脈導管（patent ductus arteriosus）"],"answer":0,"image":""},{"id":"md3-112-1-14","subject":"md3","topic":"內科-心臟血管","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"有關心臟冠狀動脈血管檢查的歷史沿革與相關敘述，下列何者錯誤？","options":["(A) 最初開始在人體進行心臟心導管檢查的人是Forssmann，他在1929年將當時的無菌導尿管經過手部靜脈植入到右心房，再以X光透視確定導管的位置","(B) 1940年代，Cournand以及Richards將Forssmann的血管攝影方式改良後用在評估人體的心血管系統上面","(C) 進行心臟冠狀動脈血管攝影最常見的合併症是血管植入部位的出血，約占1.5～2.0%","(D) 因為資訊與機器的進步，要檢查心臟冠狀動脈的解剖學與生理變化，心臟血管電腦斷層已經取代心導管檢查，成為最標準的方法"],"answer":3,"image":""},{"id":"md3-112-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"一位60歲病人最近體重明顯減輕，右上腹悶脹，食慾尚可。就醫後身體診察發現右鎖骨中線下（right mid- clavicular line, RMCL）肝臟長度為18公分，無腹水，腸蠕動正常。超音波檢查發現肝內有多顆大小不一之低回音結節。抽血檢驗結果：albumin = 3.6 g/dL（正常值＞3.5），bilirubin（total）= 0.9 mg/dL（正常值＜ 1.2），AST = 35 U/L（正常值＜37），ALT = 32 U/L（正常值＜41），α-fetoprotein（AFP）= 8 ng/mL（正常值＜20），carcinoembryonic antigen（CEA）= 521 ng/mL（正常值＜5），CA 19-9 = 45 U/mL（正常值＜ 37）。其診斷最可能為下列何者？","options":["(A) 肝細胞癌","(B) 膽管細胞癌","(C) 轉移性肝癌","(D) 肝臟局部結節增生（focal nodular hyperplasia）"],"answer":2,"image":""},{"id":"md3-112-1-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"有關潰瘍性大腸炎（ulcerative colitis, UC）及克隆氏病（Crohn's disease, CD）之敘述，何者正確？","options":["(A) 抽菸可增加CD的發生","(B) 口服避孕藥會增加UC的發生","(C) appendectomy可預防CD的發生","(D) 不論UC或CD，亞洲人的發生率高於美國人"],"answer":0,"image":""},{"id":"md3-112-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"一位阻塞性黃疸患者被診斷為Mirizzi's syndrome，造成膽汁排泄阻塞的原發原因為何？","options":["(A) 總膽管結石","(B) 胰臟腫瘤","(C) 膽囊管（cystic duct）結石","(D) 總膽管血塊"],"answer":2,"image":""},{"id":"md3-112-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"一位58歲男性病人，因腹痛、發燒、畏寒，至急診室求診。身體診察發現病人有黃疸且腹部鼓脹，且有shifting dullness與反彈痛（rebound pain），手部有palmar erythema與flapping tremor。經抽腹水檢查，發現腹33水WBC：1,250/mm，neutrophil 85%，lymphocyte 15%、RBC：40/mm。下列何者為最可能之診斷？","options":["(A) 自發性細菌性腹膜炎","(B) 十二指腸潰瘍合併穿孔","(C) 腸套疊","(D) 肝細胞癌破裂"],"answer":0,"image":""},{"id":"md3-112-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"一位懷疑有藥物引起肝傷害病人之生化值檢查如下：ALT：56 U/L、AST：72 U/L、alkaline phosphatase：795 U/L（正常值＜100 U/L）、total bilirubin：1.8 mg/dL（正常值＜1.6 mg/dL）。下列何種藥最可能導致此病人之肝傷害？","options":["(A) methotrexate","(B) isoniazid","(C) methyltestosterone","(D) acetaminophen"],"answer":2,"image":""},{"id":"md3-112-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"下列有關小腸腫瘤之敘述，何者錯誤？","options":["(A) 小腸最常見的良性腫瘤為平滑肌瘤（leiomyoma）或adenoma","(B) 大部分Peutz-Jeghers症候群的息肉易惡性病變","(C) 小腸淋巴瘤好發於迴腸","(D) 小腸最常見的肉瘤（sarcoma）為平滑肌肉瘤（leiomyosarcoma）"],"answer":1,"image":""},{"id":"md3-112-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"下列何者不是胃上皮細胞的攻擊因子？","options":["(A) 前列腺素（prostaglandin）","(B) 酒精","(C) Helicobacter pylori","(D) 膽鹽（bile salt）"],"answer":0,"image":""},{"id":"md3-112-1-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"2一位45歲男性因肝功能異常來門診，沒有肥胖（BMI 23 kg/m），喝酒史：每星期五次，每次兩罐啤酒（500毫升，5% alcohol），長達15年，抽血檢查發現AST/ALT：85/52 U/L（reference value：≦40/40）、HBsAg陰性反應、anti-HCV Ab陽性反應，腹部超音波檢查時發現有中度脂肪肝。下列評估與敘述，何者較不適當？","options":["(A) 患者可能已經發生酒精性脂肪肝疾病（alcoholic fatty liver disease）","(B) 酒精性脂肪肝疾病之發生與肥胖以及胰島素抗性（insulin resistance）有密切相關","(C) 戒酒是改善肝功能最重要的方法之一，高劑量類固醇治療在這個階段並沒有幫助","(D) 患者可能同時有C型肝炎，是併發較嚴重酒精性脂肪肝疾病的臨床危險因子，須積極評估HCV RNA及給與治療"],"answer":1,"image":""},{"id":"md3-112-1-23","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"關於大腸直腸癌篩檢之敘述，下列何者正確？","options":["(A) 糞便潛血檢查陽性代表已罹患大腸癌","(B) 肛門指診是大腸癌篩檢的好方法","(C) 糞便潛血檢查陽性者應該進一步接受大腸鏡進行確診","(D) 下消化道攝影與大腸鏡同為大腸癌篩檢的好方法"],"answer":2,"image":""},{"id":"md3-112-1-24","subject":"md3","topic":"內科-腎臟","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"一位40歲女病人，因意識障礙送入醫院，身體診察無明顯水腫，抽血檢查血鈉（Na）為115 mmol/L，血中蛋白質、血糖、三酸甘油脂皆在正常範圍內，病人未施打mannitol，下列敘述何者錯誤？","options":["(A) 抽血檢查血滲透壓（osmolality），其數值應較正常低","(B) 尿中滲透壓為250 mOsm/kg H2O，限水對此病人的治療無益","(C) 可考慮使用高張溶液，如3%食鹽水（saline）","(D) 不宜在24小時內將血鈉矯正至135 mmol/L"],"answer":1,"image":""},{"id":"md3-112-1-25","subject":"md3","topic":"內科-腎臟","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"下列有關顯影劑引起之急性腎損傷（contrast-induced acute kidney injury）的敘述，何者正確？","options":["(A) 一旦發生，有2～7%病人需要接受透析治療","(B) 以生理鹽水預防，只須於施打顯影劑後馬上給與，持續至少12小時，即有效果","(C) 以sodium bicarbonate預防，只須於施打顯影劑前1小時施打即有效果","(D) 以N-acetylcysteine預防，臨床上常使用但並未證實有一致的療效，目前並不例行推薦"],"answer":3,"image":""},{"id":"md3-112-1-26","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"一位57歲男性病人因神智不清被送至急診處。身體診察無發燒、血壓134/89 mmHg、脈搏90/min；頸部可摸到一個兩公分大小之淋巴結，心臟無雜音，肺部呼吸聲正常，腹部無特殊發現。神經學檢查無局部性缺損，神智呈現錯亂、譫妄（delirium）。生化檢查結果：BUN 88 mg/dL，肌酸酐2.8 mg/dL，血糖90 mg/dL；電解 ++-2+ 質（單位mmol/L）：Na 143，K 4.0，Cl 90，Ca 3.45。有關此病人的進一步處置，下列何者正確？","options":["(A) 給與1000 mL的生理食鹽水，並給與利尿劑","(B) 緊急血液透析","(C) 給與5%葡萄糖1000 mL，並給與鎮靜劑，如benzodiazepam","(D) 給與氯化鈣靜脈注射"],"answer":0,"image":""},{"id":"md3-112-1-27","subject":"md3","topic":"內科-腎臟","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"在臺灣造成末期腎病之最主要原發疾病為：","options":["(A) 高血壓腎病變","(B) 糖尿病腎病變","(C) 慢性腎絲球腎炎","(D) 中草藥腎病變"],"answer":1,"image":""},{"id":"md3-112-1-28","subject":"md3","topic":"內科-腎臟","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"35歲女性病人，上呼吸道感染後全身乏力、無腹瀉，肌酸酐由0.8 mg/dL上升至6.2 mg/dL，血色素由12.0 g/dL 3下降至8.6 g/dL，血小板80 × 10/μL，血液抹片呈微小血管溶血性貧血（microangiopathic hemolytic anemia），ADAMTS13＞15%，下列何種治療最為適當？","options":["(A) bortezomib","(B) rituximab","(C) eculizumab","(D) immunoglobulin"],"answer":2,"image":""},{"id":"md3-112-1-29","subject":"md3","topic":"內科-腎臟","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"造成慢性腎臟病貧血的原因，下列何者錯誤？","options":["(A) 病患身體所製造之紅血球生成素（erythropoietin）相對缺乏","(B) 病患體內鐵質儲存量（iron store）過多","(C) 病患合併出血傾向（bleeding diathesis）","(D) 病患處於慢性發炎狀態（chronic inflammation）"],"answer":1,"image":""},{"id":"md3-112-1-30","subject":"md3","topic":"內科-腎臟","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"下列有關需緊急血液透析的適應症，何者最不適當？","options":["(A) 經藥物治療無效的高血鉀症","(B) 急性肺水腫且合併對利尿劑無反應的寡尿","(C) 碳酸氫鈉無法矯正的代謝性酸血症","(D) 2腎絲球過濾率6 mL/min/1.73 m之慢性腎臟病患者，不論有無尿毒症狀"],"answer":3,"image":""},{"id":"md3-112-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"全身性紅斑狼瘡（systemic lupus erythematosus）病人的神經及精神症狀中，下列何者最為常見？","options":["(A) cognitive dysfunction","(B) transverse myelopathy","(C) cerebral hemorrhage","(D) autonomic nerve imbalance"],"answer":0,"image":""},{"id":"md3-112-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"下列何種血管炎患者的血清中，可以檢測到antineutrophil cytoplasmic antibodies（ANCA）？","options":["(A) serum sickness","(B) Kawasaki disease","(C) granulomatosis with polyangiitis","(D) vasculitis associated with collagen vascular diseases"],"answer":2,"image":""},{"id":"md3-112-1-33","subject":"md3","topic":"內科-感染","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"下列細胞激素（cytokine）中，何者與敗血病關係較不密切？","options":["(A) interleukin-5（IL-5）","(B) interleukin-1（IL-1）","(C) tumor necrosis factor α（TNF-α）","(D) interleukin-6（IL-6）"],"answer":0,"image":""},{"id":"md3-112-1-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"Autoinflammatory diseases包括某些有反覆發燒症狀的發炎性免疫疾病，但下列何者不屬於此類疾病？","options":["(A) tumor necrosis factor receptor-associated periodic syndrome","(B) familial Mediterranean fever","(C) granulomatosis with polyangiitis","(D) neonatal-onset multisystem inflammatory disease"],"answer":2,"image":""},{"id":"md3-112-1-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"有關發炎性肌肉病變（inflammatory myopathies）的敘述，下列何者正確？","options":["(A) inclusion body myositis好發於年輕人","(B) dermatomyositis通常不會有肌肉之外的表現（extramuscular manifestations）","(C) polymyositis通常會有強烈的家族遺傳相關（familial association）","(D) dermatomyositis有可能與癌症相關"],"answer":3,"image":""},{"id":"md3-112-1-36","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"子宮頸癌治療預後常跟原發腫瘤之侵犯位置與侵犯周邊器官有關，下列何者臨床狀況，其5年預後最差？","options":["(A) 子宮頸癌只侵犯到子宮頸區域","(B) 子宮頸癌侵犯到陰道之下1/3區域","(C) 子宮頸癌侵犯到骨盆側壁（pelvic side wall）","(D) 子宮頸癌侵犯到膀胱區域"],"answer":3,"image":""},{"id":"md3-112-1-37","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"大腸直腸癌（colorectal cancer）是國人最常見的惡性腫瘤之一。下列與大腸直腸癌發生相關的危險因子中，何者最不恰當？","options":["(A) 飲食中的動物性脂肪（animal fat）","(B) inflammatory bowel disease","(C) Lynch's syndrome","(D) enterococcus bacteremia"],"answer":3,"image":""},{"id":"md3-112-1-38","subject":"md3","topic":"內科-血液","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"一位23歲病人因咳嗽、喉嚨痛吃了兩天藥房買的藥後，突然發現小便呈現暗紅色，尿液檢查潛血反應為陽性，沉澱物中紅血球0～2/HPF，白血球1～2/HPF。抽血檢查顯示血紅素10.8 g/dL，網狀紅血球7.6%，白血球9,850/μL且分類正常，血小板178,000/μL，血球抹片如圖所示。AST 72 U/L（正常0～37），ALT 35 U/L（正常0～41），LDH 1,080 U/L，總膽紅素4.3 mg/dL，直接型膽紅素0.8 mg/dL，Coombs test陰性。病人回憶他小學時亦曾經在服用感冒藥後發生類似狀況，但幾天後就好了，當時並未去看醫生。此病人最可能的診斷為何？","options":["(A) autoimmune hemolytic anemia","(B) glucose 6-phosphate dehydrogenase（G6PD）deficiency","(C) acute glomerulonephritis","(D) acute hepatitis"],"answer":1,"image":"md3-112-1-38.jpeg"},{"id":"md3-112-1-39","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"一位62歲男性因跌倒就醫，實驗室檢查顯示Hb 7.6 g/dL，MCV 85 fL，platelet 120,000/μL。下圖分別為其骨髓抹片及Ｘ光，其診斷最可能為下列何者？","options":["(A) 腺癌併多處骨轉移","(B) vitamin D嚴重缺乏症","(C) 多發性骨髓瘤","(D) 骨癌併多處轉移"],"answer":2,"image":"md3-112-1-39.jpeg"},{"id":"md3-112-1-40","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"評估癌症病人的活動能力（performance status），如採用Karnofsky performance status scale，70分表示：","options":["(A) 活動及工作皆不受限制","(B) 整日躺床，完全無法照顧自己","(C) 能照顧自己，但已不能工作或做正常的活動","(D) 日常生活需要他人相當多的協助及醫療照顧"],"answer":2,"image":""},{"id":"md3-112-1-41","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"一位60歲男性病人，咳嗽6週，喘氣、虛弱、胃口差、體重減輕。經詢問後，還有輕微頭疼及隱隱右側腹痛。他自16歲起每天抽兩包菸。身體診察呈現惡病質（cachexia），右臂及右頸無明顯腫脹，沒有胸前靜脈鼓起。胸部X光顯示右上肺葉有一大腫瘤，經皮穿刺生檢證實是小細胞肺癌，電腦斷層呈現上腔靜脈輕微壓迫，右縱膈腔淋巴結明顯腫大及肝轉移。最適當治療的方法為何？","options":["(A) 緊急胸部放射治療","(B) 化學治療","(C) 支架撐開上腔靜脈，接著化學治療","(D) 胸部放射治療，接著化學治療"],"answer":1,"image":""},{"id":"md3-112-1-42","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"下列何者不是芳香酶抑制劑（aromatase inhibitor）？","options":["(A) anastrazole","(B) exemestane","(C) letrozole","(D) tamoxifen"],"answer":3,"image":""},{"id":"md3-112-1-43","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"關於頭頸癌與病毒感染的相關敘述，下列何者錯誤？","options":["(A) 與口咽癌（oropharyngeal cancer）發生有關的病毒是human papilloma virus 16（HPV 16）","(B) human papilloma virus（HPV）感染與西方國家口咽癌（oropharyngeal cancer）發生率上升相關","(C) human papilloma virus（HPV）相關的口咽癌（oropharyngeal cancer）較HPV不相關的口咽癌預後較差","(D) 與鼻咽癌（nasopharyngeal cancer）發生有關的病毒是Epstein-Barr virus（EBV）"],"answer":2,"image":""},{"id":"md3-112-1-44","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"下列何者不是乳癌患者接受乳房保留手術（breast-conserving surgery）的相對或絕對禁忌症？","options":["(A) 腋下淋巴轉移","(B) 同側乳房多發性病灶","(C) 腫瘤侵犯nipple-areola","(D) collagen-vascular disease患者"],"answer":0,"image":""},{"id":"md3-112-1-45","subject":"md3","topic":"內科-胸腔","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"張小姐因肺炎治療一星期後持續發燒且出現胸痛的症狀，胸部X光檢查發現右側肋膜積液（pleural effusion），下列肋膜積液生化檢查的結果，何者最應積極引流治療？","options":["(A) pH = 7.3","(B) glucose = 38 mg/dL","(C) LDH = 700 U/L","(D) WBC = 7000/μL"],"answer":1,"image":""},{"id":"md3-112-1-46","subject":"md3","topic":"內科-胸腔","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"吳先生45歲，不抽菸，因咳嗽2個月至門診就醫，胸部Ｘ光檢查結果如圖所示，最可能的診斷為何？","options":["(A) 細菌性肺炎","(B) 間質性肺炎","(C) 肺結核","(D) 肺癌"],"answer":2,"image":"md3-112-1-46.jpeg"},{"id":"md3-112-1-47","subject":"md3","topic":"內科-胸腔","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"張先生經醫師診斷為氣喘病人，依氣喘診療指引，下列關於其治療與追蹤敘述何者錯誤？","options":["(A) 第二階的氣喘病人應接受吸入型類固醇治療","(B) 對於氣喘病情的監測，可教育病人使用尖峰呼氣流速計（peak flowmeter）記錄峰速值（peak expiratory flow rate）","(C) 氣喘治療採階梯式治療原則","(D) 每一階段的治療至少要2個月以上才能考慮降階"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第47題一律給分 (原公告答案 D)"},{"id":"md3-112-1-48","subject":"md3","topic":"內科-胸腔","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"有關慢性阻塞性肺病（COPD）病人的治療策略，下列敘述何者錯誤？","options":["(A) 輕度病人平時治療可僅使用吸入型抗膽鹼（inhaled anticholinergic）藥物，以改善呼吸功能障礙","(B) 頻繁急性發作（acute exacerbation）的病人，可嘗試使用吸入型類固醇","(C) 胸腔復健對COPD患者的成效不彰","(D) 肺臟移植為治療選項之一"],"answer":2,"image":""},{"id":"md3-112-1-49","subject":"md3","topic":"內科-胸腔","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"急性呼吸窘迫症（acute respiratory distress syndrome, ARDS）與心因性肺水腫（cardiogenic pulmonary edema）最大的不同在於：","options":["(A) ARDS時，肺動脈wedge pressure通常＞18 mmHg","(B) ARDS肺部浸潤較少見於肺部周圍（pulmonary periphery）","(C) ARDS時，肺部血管的通透性（permeability）增加","(D) ARDS出現缺氧的原因，主要導因於肺泡氣體擴散障礙（alveolar diffusion impairment）"],"answer":2,"image":""},{"id":"md3-112-1-50","subject":"md3","topic":"內科-胸腔","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"下列關於矽肺症（silicosis）的敘述，何者錯誤？","options":["(A) 主要是因吸入free silica（SiO2）造成","(B) 持續暴露於高濃度矽粉塵數年後，產生急性、亞急性矽肺症，只要離開污染源，疾病即不再惡化","(C) 胸腔影像呈現上肺野小結節陰影、肺門淋巴腺腫大、鈣化或進行性大量纖維化（progressive massive fibrosis）","(D) 容易合併肺結核（pulmonary tuberculosis）、肺癌或自體免疫疾病如類風濕性關節炎（rheumatoid arthritis）等"],"answer":1,"image":""},{"id":"md3-112-1-51","subject":"md3","topic":"內科-腫瘤","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"下列那個標誌無法區分小細胞肺癌與非小細胞肺癌？","options":["(A) CD56","(B) neural cell adhesion molecule（NCAM）","(C) chromogranin","(D) thyroid transcription factor-1（TTF-1）"],"answer":3,"image":""},{"id":"md3-112-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"一位26歲女性患有高血壓半年，三個月前開始伴有心悸、頭痛、流汗。主治醫師安排她做尿液24小時catecholamine測定。若欲給藥治療其高血壓，下列何者不適宜？","options":["(A) α-adrenergic blocker alone","(B) β-adrenergic blocker alone","(C) calcium channel blocker","(D) β-adrenergic blocker after α-adrenergic blocker"],"answer":1,"image":""},{"id":"md3-112-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"下列何者不是營養不良（malnutrition）高危險群之特徵？","options":["(A) 敗血症（sepsis），高燒不退","(B) 老年人","(C) 長期酗酒（alcohol abuse）","(D) 好喝汽水可樂"],"answer":3,"image":""},{"id":"md3-112-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"一位50歲男性病人因倦怠、體重減輕來診。患者10年前曾接受鼻咽癌放射線治療，2個月前回診無復發情形。身體診察發現血壓110/70 mmHg，脈搏96次/min，除了乳暈稍有褪色、腋毛及恥毛稍減外並無異常。抽血檢查 ++ Na 131 mmol/L、K 4.0 mmol/L、glucose 90 mg/dL（空腹）。下列那一項檢查對診斷及治療最有幫助？","options":["(A) free T4、TSH","(B) ACTH、cortisol","(C) tumor marker","(D) FSH、LH、testosterone"],"answer":1,"image":""},{"id":"md3-112-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"關於代謝症候群（metabolic syndrome）之敘述，下列何者錯誤？","options":["(A) 血中脂聯素（adiponectin）的濃度通常會增加","(B) 血中C-反應蛋白（C-reactive protein）濃度通常會增加","(C) 血中尿酸濃度通常會增加","(D) 低密度脂蛋白膽固醇（LDL-C）的血中濃度，一般不是常用的診斷條件之一"],"answer":0,"image":""},{"id":"md3-112-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"有關低血糖之敘述，下列何者最不適當？","options":["(A) 血漿中葡萄糖濃度低於50 mg/dL，可能會造成認知障礙","(B) 造成低血糖最常見的原因，是胰島素瘤","(C) 雙胍類藥物（biguanides）不易造成低血糖","(D) Whipple's triad的判定，需要有可靠的血糖檢測"],"answer":1,"image":""},{"id":"md3-112-1-57","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"一位20歲女性，3個月來有心悸、怕熱、手抖、體重減輕、雙眼突出、紅腫及瀰漫性甲狀腺腫等症狀。她最有可能罹患下列何種疾病？","options":["(A) 甲狀腺癌","(B) 甲狀腺功能過低","(C) 葛雷夫茲氏症（Graves' disease）","(D) 亞急性甲狀腺炎"],"answer":2,"image":""},{"id":"md3-112-1-58","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"治療腦下垂體生長激素瘤造成肢端肥大症的首選方法為何？","options":["(A) 手術切除","(B) 注射體抑素類似物（somatostatin analogue）治療","(C) 立體定位放射線治療（stereotactic radiosurgery）","(D) 口服多巴胺促效劑（dopamine agonist）治療"],"answer":0,"image":""},{"id":"md3-112-1-59","subject":"md3","topic":"內科-感染","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"下列有關HIV初次感染（primary infection）引起acute HIV syndrome之敘述，何者錯誤？","options":["(A) 大多數HIV初次感染之病人於急性期並無症狀，只有小於10%的病人會出現急性症狀","(B) 急性症狀通常在感染後3～6週時出現","(C) 此時病人會有病毒血症（viremia），血中會有很高量之HIV病毒","(D) 出現acute HIV syndrome後若未給與抗病毒藥物治療，症狀也會自然消失"],"answer":0,"image":""},{"id":"md3-112-1-60","subject":"md3","topic":"內科-感染","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"關於醫療人員手部衛生（濕洗手或以酒精乾洗手）時機之敘述，下列何者錯誤？①醫師查房時，手未碰觸病人，僅碰觸病人床欄，離開病室不用洗手 ②輸送小組人員至病房接病人至檢查室、協助病人從床上移至輪椅，不用洗手 ③加護病房護理人員倒第一床病人的尿壺時因有戴手套且未碰到病人床，再倒第二床之間都不用洗手 ④護理人員在準備藥物或是協助病人清潔身體前不用洗手 ⑤呼吸照護病房護理人員準備替病人導尿，將圍簾拉起，乾洗手後再幫病人導尿","options":["(A) 僅①②③④","(B) 僅②③⑤","(C) 僅①④⑤","(D) ①②③④⑤"],"answer":0,"image":""},{"id":"md3-112-1-61","subject":"md3","topic":"內科-感染","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"診斷感染性心內膜炎所使用之Duke criteria中，下列何者屬於major criteria？①兩套blood culture培養出典型引起感染性心內膜炎的細菌，其中包括HACEK Group的細菌 ②心臟超音波檢查見到心臟瓣膜上有oscillating mass ③體溫超過38℃ ④出現Janeway lesion或Osler's node","options":["(A) 僅①②","(B) 僅③④","(C) 僅①②④","(D) ①②③④"],"answer":0,"image":""},{"id":"md3-112-1-62","subject":"md3","topic":"內科-感染","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"下列有關流感之敘述，何者錯誤？","options":["(A) 流行性感冒病毒屬於RNA病毒","(B) 主要傳播方式是透過飛沫傳染與接觸傳染","(C) 免疫缺損病人及兒童可傳染期較成人病例為長","(D) 流感快篩陰性，即可排除流感"],"answer":3,"image":""},{"id":"md3-112-1-63","subject":"md3","topic":"內科-感染","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"下列何種菌種不屬於Mycobacterium tuberculosis complex？","options":["(A) M. africanum","(B) M. bovis","(C) M. chelonae","(D) M. microti"],"answer":2,"image":""},{"id":"md3-112-1-64","subject":"md3","topic":"內科-感染","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"40歲男性，有肝硬化病史多年。夏天時在高雄旗津海邊釣魚被魚刺刺傷左腳，隔天因左腳紅腫熱痛被送至急診，左腳發現有紫紅色水泡，且有休克現象，這位病人最可能之致病菌為何？","options":["(A) Staphylococcus aureus","(B) Streptococcus pyogenes","(C) Pseudomonas aeruginosa","(D) Vibrio vulnificus"],"answer":3,"image":""},{"id":"md3-112-1-65","subject":"md3","topic":"內科-感染","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"承上題，下列何種抗生素治療對這位病人最為恰當？","options":["(A) vancomycin＋gentamicin","(B) clindamycin＋penicillin","(C) ceftazidime＋tetracycline","(D) cefazolin＋amikacin"],"answer":2,"image":""},{"id":"md3-112-1-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"71歲女性因跌倒來門診就醫，她有認知功能障礙、帕金森氏症、退化性膝關節炎，下列何者不屬於跌倒的內生性危險因子（intrinsic risk factor）？","options":["(A) 年紀大於65歲","(B) 認知功能障礙","(C) 帕金森氏症","(D) 退化性膝關節炎"],"answer":0,"image":""},{"id":"md3-112-1-67","subject":"md3","topic":"家醫-行為與社區醫學","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"關於憂鬱症（depression）的敘述，下列何者正確？","options":["(A) 憂鬱症只要完治之後，就不會再復發","(B) 老年自殺比率不高，所以不用進行憂鬱篩檢","(C) 憂鬱症藥物必須一輩子服用，故無法停藥","(D) 憂鬱症治療除藥物治療外尚包括非藥物治療，例如：認知行為治療"],"answer":3,"image":""},{"id":"md3-112-1-68","subject":"md3","topic":"醫學倫理與法規","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"臨床上，醫師與病人在醫療決策層面所扮演的角色，以何種方式最為理想？","options":["(A) 醫師依病人個別選擇及保險需要，來進行醫療決策","(B) 醫師依個人經驗與醫學證據，來進行醫療決策","(C) 醫師依個人經驗及病人保險需要，來進行醫療決策","(D) 醫師依醫學證據及病人個別選擇，來進行醫療決策"],"answer":3,"image":""},{"id":"md3-112-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"針對盛行率低的疾病（Disease）進行社區篩檢時，下列何種篩檢（Test）呈現的結果假陽性較低，最適合使用？","options":["(A) Disease (+)Disease (-) Test (+)30050 Test (-)100550","(B) Disease (+)Disease (-) Test (+)5050 Test (-)50850","(C) Disease (+)Disease (-) Test (+)50050 Test (-)50400","(D) Disease (+)Disease (-) Test (+)100550 Test (-)30050"],"answer":1,"image":"md3-112-1-69.jpeg"},{"id":"md3-112-1-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"在醫病非語言的溝通與觀察中，醫病雙方出現鏡相姿勢（mirroring posture）代表何種意義？","options":["(A) 為敵對的關係","(B) 已建立適當的關係","(C) 為從屬的關係","(D) 正要開始建立關係"],"answer":1,"image":""},{"id":"md3-112-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"有關暴力零容忍的敘述，下列何項最不適當？","options":["(A) 依據美國預防醫學工作小組（US Preventive Services Task Force）的建議，育齡婦女親密伴侶暴力（intimate partner violence）篩檢為B等級","(B) 依據美國預防醫學工作小組（US Preventive Services Task Force）的建議，老人虐待（elder abuse）篩檢為B等級","(C) 在臺灣，若家庭暴力已經持續存在一段時間，受害者可以隨時撥打「113」進行諮詢與通報，或可逕洽各地方政府家庭暴力及性侵害防治中心尋求協助","(D) 在臺灣，在家庭暴力發生的當下，受害者可以儘快撥打「110」報警，由警察介入制止暴力，蒐集犯罪證據，並協助護送被害人就醫"],"answer":1,"image":""},{"id":"md3-112-1-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"腕隧道症候群（carpal tunnel syndrome）是常見之職業性肌肉骨骼系統疾病，下列何者是腕隧道症候群之危險因子？","options":["(A) 反覆性手舉過肩","(B) 反覆性手肘施力","(C) 糖尿病","(D) 甲狀腺機能亢進"],"answer":2,"image":""},{"id":"md3-112-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"55歲女性，一年前被診斷為卵巢癌接受化學治療，主訴最近有噁心、嘔吐及食慾不振的現象。檢查發現呼吸每分鐘約30次，結膜蒼白，腹部鼓脹，有腹水且有一10×30 cm之腫塊。導致此病人噁心、嘔吐最可能之原因為何？","options":["(A) 腸阻塞","(B) 腦壓增加","(C) 情緒低落","(D) 高鈣血症"],"answer":0,"image":""},{"id":"md3-112-1-74","subject":"md3","topic":"影像醫學","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"有關上腸胃道鋇劑檢查，下列敘述何者最不恰當？","options":["(A) 主動脈弓會在食道右側形成壓迹","(B) 左主支氣管會在食道左側形成壓迹","(C) 胃食道交界可在食道穿過橫膈膜的位置辨認","(D) 吞嚥會引發食道蠕動波，推動食糜往下排空"],"answer":0,"image":""},{"id":"md3-112-1-75","subject":"md3","topic":"影像醫學","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"關於慢性阻塞性肺病（COPD）的影像學表現，下列敘述何者最不恰當？","options":["(A) 可能導致肺部X光片中肺部體積增加","(B) 因肺氣腫可導致肺部血管於X光片中相對稀疏的徵象","(C) 可能呈現支氣管擴張，於X光片中呈現管狀或環狀影的徵象","(D) 胸部電腦斷層檢查無法診斷支氣管擴張"],"answer":3,"image":""},{"id":"md3-112-1-76","subject":"md3","topic":"家醫-緩和醫學","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"有關高齡之躁動（agitation）處置原則，何者最不適當？","options":["(A) 先治療原有疾病","(B) 控制藥物要從最低有效劑量開始給與，再逐漸提高","(C) 除藥物治療外，其他治療也有重要角色","(D) 老人比較不會有精神藥物的副作用"],"answer":3,"image":""},{"id":"md3-112-1-77","subject":"md3","topic":"內科-腎臟","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"下列有關低血鉀症（hypokalemia）的敘述，何者最不適當？","options":["(A) 低血鉀症的心電圖常呈現QTc延長","(B) 嚴重低血鉀症可能導致心房顫動（atrial fibrillation）及torsades de pointes等心律不整","(C) + hyperaldosteronism所導致的低血鉀症，transtubular K gradient（TTKG）通常低於5 mEq/L","(D) 低血鉀症病人的尿液鈣磷比（calcium/phosphate ratio），若小於1.6，可以作為甲狀腺亢進週期性癱瘓（thyrotoxic periodic paralysis）的診斷佐證"],"answer":3,"image":""},{"id":"md3-112-1-78","subject":"md3","topic":"家醫-行為與社區醫學","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"有關天然災害如颱風（颶風）及地震造成的傷害，下列描述何者最不適當？","options":["(A) 颱風（颶風）於急性期（acute phase）時造成民眾傷亡較復原期（recovery period）多","(B) 颱風（颶風）於急性期造成之外傷性死亡多肇因於墜落物外傷及車禍事件","(C) 地震發生後之死亡事件多發生於震後3小時","(D) 地震復原期災區常規醫療需求不易，環境衛生及傳染病為最大隱憂"],"answer":0,"image":""},{"id":"md3-112-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"張先生是70歲的退休老師，平時開朗樂觀，與唯一的兒子一家同住。近兩個月來因為腹脹和體重減輕就醫，經檢查後確認為胃淋巴癌末期且無法開刀。他兒子強力要求不要告知父親癌症末期的消息，擔心他會承受不了。雖然主治醫師已對兒子解釋告知病情的重要性，但兒子仍堅持不能告知。醫師後續的作法，下列何者最為適當？","options":["(A) 病人往生後對醫師有意見的通常是家屬，聽家屬的話比較不會產生糾紛","(B) 最了解病人的是同住家人，既然兒子提出要求還是不要明講比較好","(C) 病人是自己身體的主人，如表達想知道的意願還是應該告知","(D) 病人雖然是末期癌症但病況難以預料，還是用模糊的說法帶過較好"],"answer":2,"image":""},{"id":"md3-112-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"下列何者不是研究倫理常用的原則或準則？","options":["(A) 紐倫堡守則（the Nuremberg Code, 1947年）","(B) 赫爾辛基宣言（the Declaration of Helsinki, 1964年）","(C) 貝爾蒙報告書（the Belmont Report, 1979年）","(D) 里斯本宣言（the Declaration of Lisbon, 1981年）"],"answer":3,"image":""},{"id":"md3-112-2-1","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"35歲女性，健檢發現血鈣偏低（2.05 mmol/L，參考值2.2～2.5），血清肌酸酐（creatinine, 0.6 mg/dL）、鈉（139 mEq/L）及鉀（3.8 mEq/L）則在正常範圍。對於此病患之低血鈣（hypocalcemia）應優先安排下列評估，但何者最不適當？","options":["(A) 測血中白蛋白（albumin）及磷（phosphorus）濃度","(B) 測血中副甲狀腺素（PTH）濃度","(C) 測血中1,25(OH)2D濃度","(D) 測血中鎂（magnesium）濃度"],"answer":2,"image":""},{"id":"md3-112-2-2","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"下列那一種情形最可能發生高血鉀（hyperkalemia）？","options":["(A) 注射胰島素","(B) 鎂（magnesium）缺乏","(C) 使用非類固醇抗發炎藥物（non-steroidal anti-inflammatory drugs）","(D) 使用β2-adrenergic agonists支氣管擴張劑"],"answer":2,"image":""},{"id":"md3-112-2-3","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"35歲男性過去無慢性疾病，有飲酒習慣，至門診就醫，主訴疲倦以及尿液顏色變深，下列處置何者最不適當？","options":["(A) 抽血檢驗total及direct bilirubin是否上升","(B) 檢驗尿液中urobilinogen是否上升","(C) 視診鞏膜及舌下黏膜是否變黃","(D) 抽血檢驗creatinine是否上升"],"answer":3,"image":""},{"id":"md3-112-2-4","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"65歲女性病人，每日服用trichlormethiazide 4 mg控制血壓已10年。某日半夜病人因突發左踝劇痛而醒來，發覺該處有明顯紅腫現象。醫師自該處抽取關節液化驗，發現有針狀或桿狀、強烈負雙折射性（negative birefringent）結晶，並有部分結晶被白血球吞噬。針對此病人急性關節發炎之處置，下列何種藥物治療最不恰當？","options":["(A) colchicine","(B) febuxostat","(C) ibuprofen","(D) prednisolone"],"answer":1,"image":""},{"id":"md3-112-2-5","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"承上題，上述病人10年後某日突發右腰劇痛，上廁所發現有血尿現象。急診室醫師以超音波檢查發現病人兩側腎臟中皆有結石，最大者直徑約1.2公分，但照一般X光片卻無法明顯看到結石。有關此病人結石之處置，下列何種藥物治療最不恰當？","options":["(A) allopurinol","(B) potassium citrate","(C) probenecid","(D) sodium bicarbonate"],"answer":2,"image":""},{"id":"md3-112-2-6","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"下列有關心導管檢查及冠狀動脈造影之敘述，何者錯誤？","options":["(A) 心導管檢查可用以確診及評估許多心血管疾病，但擇期性（elective）心導管仍有可能發生意外，包括＜ 0.1%心肌梗塞、0.01%中風、0.1%死亡等風險","(B) 檢查中使用之顯影劑可能產生嚴重類過敏（anaphylactoid）反應，機率為0.1～0.2%","(C) 顯影劑可能造成急性腎臟損傷，因此術前均應給與病人足夠輸液及N-acetylcysteine以降低風險","(D) 懷疑冠狀動脈心臟病之病人，於檢查前均應服用aspirin，但因心導管屬無菌操作，所以並不需預防性投與抗生素"],"answer":2,"image":""},{"id":"md3-112-2-7","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"下列有關冠狀動脈心臟病的藥物治療敘述，何者正確？","options":["(A) 乙型交感神經阻斷劑（beta blocker）可減少心肌耗氧，因此可以減少心絞痛，甚至可以降低心肌梗塞後之死亡率","(B) 鈣離子阻斷劑（calcium channel blocker）可以擴張冠狀動脈、增加心肌供血，因此短效型dihydropyridine類鈣離子阻斷劑特別適用於無法耐受乙型交感神經阻斷劑（beta blocker）副作用的病人","(C) 阿斯匹靈（aspirin）為可逆性血小板cyclooxygenase抑制劑，減低血小板活化能力，冠狀動脈心臟病人常用劑量為每日75～325 mg","(D) 有機硝酸鹽類（nitrate）經人體代謝後，可釋放一氧化氮（NO）與血管平滑肌adenylyl cyclase結合，造成血管擴張"],"answer":0,"image":""},{"id":"md3-112-2-8","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"27歲男性病人與好友熬夜玩電玩，翌日清晨突然倒地急救，經119 EMT施行心肺復甦術，30分內送抵急診，中間多次VT/VF並施行DC shock，到院後CPCR共50分及電擊5次，除了急救藥物使用之外，並在50分鐘內找心臟外科醫師放置葉克膜。病況穩定後進行身體檢查，體溫35.4°C、HR：80/min、RR：20/min、BP：125/68 mmHg，聽診呈現心尖及lower left sternal border（LLSB）有grade 3/6 systolic murmur。緊急冠狀動脈血管攝影顯示無冠狀動脈狹窄或血栓阻塞。心電圖跟心臟超音波如附圖所示。下列何者敘述錯誤？","options":["(A) 這位病人的診斷是肥厚型心肌症（hypertrophic cardiomyopathy）","(B) 因惡性心律不整可能復發，應考慮植入式心律去顫器﹙implantable cardioverter defibrillator, ICD﹚的置入","(C) 如果病人左心室出口阻塞的症狀嚴重，可以考慮心導管酒精消融（alcohol ablation）或是外科手術，要是還是無法改善，可以考慮換心","(D) 除了考慮乙型交感神經阻斷劑（beta blocker），鈣離子阻斷劑（calcium channel blocker）等，還要增加利尿劑的使用量，避免心臟衰竭"],"answer":3,"image":"md3-112-2-8.jpeg"},{"id":"md3-112-2-9","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"一位65歲男性過去無任何病史，今日早上因突然胸悶合併心悸至急診，心跳每分鐘約130下，心電圖如附圖，診斷為何？","options":["(A) sinus tachycardia","(B) atrial tachycardia","(C) atrial fibrillation","(D) ventricular tachycardia"],"answer":2,"image":"md3-112-2-9.jpeg"},{"id":"md3-112-2-10","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"關於肺高壓的描述，下列何者錯誤？","options":["(A) 病人在疾病初期所表現的症狀常無專一性","(B) 當懷疑病人有肺高壓，心臟超音波是優先考量的篩檢工具","(C) 本病的確診須靠右側心導管（right heart catheterization）檢查","(D) 確診的病人常合併有貧血"],"answer":3,"image":""},{"id":"md3-112-2-11","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"關於Raynaud's phenomenon的描述，下列何者錯誤？","options":["(A) 常表現於硬皮症（scleroderma）的病人","(B) 原發性的病人常有較嚴重的症狀","(C) 年紀在50歲以上，動脈粥狀硬化是Raynaud's phenomenon常見的原因","(D) 症狀嚴重的病人可以使用dihydropyridine鈣離子阻斷劑減輕症狀"],"answer":1,"image":""},{"id":"md3-112-2-12","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"關於心包膜疾病的描述，下列何者正確？","options":["(A) 急性心包膜炎的臨床分類主要包括fibrinous和effusive（serous or sanguineous）兩大類","(B) 急性心包膜炎常見的症狀是以發燒為主，但罕見胸痛","(C) 只有不到10%急性心包膜炎的病人在疾病過程中可以聽到friction rub","(D) colchicine用於治療急性不明原因性心包膜炎（acute idiopathic pericarditis）病人的標準治療期程不可超過兩週，否則轉變成慢性心包膜炎的機率會增加"],"answer":0,"image":""},{"id":"md3-112-2-13","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"有關心衰竭的New York Heart Association Classification，下列何者當下的functional capacity是屬於class II？","options":["(A) 一位24歲的大學畢業男性在兵役體檢的時候發現有主動脈瓣二葉畸形（bicuspid aortic valve），該位男性表示之前在學校的籃球課表現並無異樣","(B) 一位45歲的魚市場搬運男工平常扛20公斤的魚貨從卡車走到倉庫的二樓都不需休息，但是兩週前心律不整發生後扛15公斤樓梯走到一半就很喘，完全無法走上二樓","(C) 一位75歲的男性診斷有中度二尖瓣閉鎖不全。平時很少運動，每天頂多走到離家20公尺的便利商店買報紙。最近1個禮拜腳漸漸腫起來，還是可以走到該便利商店買報紙，但是會覺得明顯比之前喘和累","(D) 一位50歲女性診斷有擴大型心肌症（dilated cardiomyopathy），平常可以躺平一覺睡到天亮，最近2個禮拜腳漸漸腫起來，需要頭部墊兩個枕頭才有辦法躺下來睡"],"answer":2,"image":""},{"id":"md3-112-2-14","subject":"md3","topic":"內科-心臟血管","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"一位78歲男性病患因心房顫動就診，該心律不整病史已有1年以上。過去有高血壓及糖尿病史，最近有呼吸困難與腳部水腫；心臟超音波左心射出分率29%。無心肌梗塞、中風或周邊血管阻塞疾病病史。估算其CHA2DS2-VASc score，該病患之分數為：","options":["(A) 2","(B) 3","(C) 4","(D) 5"],"answer":3,"image":""},{"id":"md3-112-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"44歲女性，體檢發現B型肝炎帶原後有定期追蹤，目前AST及ALT正常，HBeAg陰性，anti-HBe陽性。她的媽媽與哥哥也是B肝帶原，家族中一位阿姨得到肝細胞癌。下列敘述何者正確？","options":["(A) 患者體內已無B型肝炎病毒","(B) 患者目前處於B型肝炎自然病程中之「免疫耐受期（immune tolerance phase）」","(C) 患者感染B型肝炎途徑最有可能是垂直感染","(D) 患者無需每半年接受腹部超音波檢查"],"answer":2,"image":""},{"id":"md3-112-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"曉華健康檢查發現bilirubin total/direct為3.6/2.5 mg/dL，但alkaline phosphatase（ALP）、 γ-glutamyl transpeptidase（GGT）、aspartate aminotransferase（AST）、alanine aminotransferase（ALT）皆正常。下列疾病何者最有可能？","options":["(A) Crigler-Najjar syndrome","(B) Gilbert's syndrome","(C) Dubin-Johnson syndrome","(D) G6PD deficiency"],"answer":2,"image":""},{"id":"md3-112-2-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"關於直腸肛門口的疾病，下列敘述何者錯誤？","options":["(A) 生產時骨盆底受傷、失智、腦瘤、中風、重症肌無力或是腸躁症的患者比較容易會有大便失禁","(B) 大便失禁的治療可以給與高纖飲食、糞便體積增加劑（bulking agent）及止瀉劑。或用生物回饋的方式來做復健治療","(C) 痔瘡突出需要用手動的方式才能推回去屬於第四級痔瘡，可以給與高纖食物，含類固醇的塞劑以及考慮手術治療","(D) 肛門直腸膿瘍常發生在免疫低下的患者（如糖尿病、血液疾病及HIV陽性的患者）。標準的治療是要切開膿瘍引流"],"answer":2,"image":""},{"id":"md3-112-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"關於急性腹膜炎的敘述何者錯誤？","options":["(A) 當腸道穿孔時，腸道內的細菌會進入腹腔中而導致續發性腹膜炎（secondary peritonitis）","(B) 血液的白血球過低，是導致自發性細菌性腹膜炎（spontaneous bacterial peritonitis）常見的重要因子","(C) 身體檢查上，需要注意壓痛的位置，如McBurney's point疼痛，Murphy's sign以及是否有木板樣僵直（board- like rigidity）及腹膜炎的反彈痛","(D) X光檢查要注意腸道外的氣體（free air），若有則代表有腸穿孔的可能性，需要緊急手術"],"answer":1,"image":""},{"id":"md3-112-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"一位78歲男性，平時抽菸每日兩包已有五十年、每日睡前喜歡喝烈酒才能入睡。最近因吞嚥困難來到診間求診，胃鏡檢查及切片診斷為食道鱗狀上皮細胞癌。下列敘述何者錯誤？","options":["(A) 喝酒與抽菸為食道鱗狀上皮細胞癌發生之危險因子","(B) 病人同時也是口咽癌的高危險群","(C) 釐清病人吞嚥困難的種類（固體、液體）和先後發展時序有助於吞嚥困難的鑑別診斷","(D) 食道鱗狀上皮細胞癌產生之高鈣血症不會出現在沒有骨骼轉移的病人"],"answer":3,"image":""},{"id":"md3-112-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"一位67歲B型肝炎及肝硬化之男性病人，因吐血來到急診，內視鏡下可見食道靜脈瘤正在出血。下列敘述何者錯誤？","options":["(A) 食道靜脈瘤出血可以內視鏡結紮術進行止血","(B) 靜脈注射血管活性藥物包括terlipressin及octreotide，對食道靜脈瘤出血之止血有幫助","(C) 病人於急性期可使用nonselective beta blockers改善急性出血","(D) 內視鏡檢查要注意胃靜脈瘤（gastric varices）的有無和出血跡象"],"answer":2,"image":""},{"id":"md3-112-2-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"下列關於胰腺癌（pancreatic adenocarcinoma）之敘述何者錯誤？","options":["(A) 先天BRCA2基因突變（germline BRCA2 mutation）者有較高罹病風險","(B) 慢性胰臟炎（chronic pancreatitis）是胰腺癌之危險因子","(C) 腫瘤若侵犯到上腸繫膜動脈（superior mesenteric artery）則無法手術切除","(D) 手術切除後進行輔助化學治療（adjuvant chemotherapy）無確定療效，並非標準治療方式"],"answer":3,"image":""},{"id":"md3-112-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"有關肝細胞癌（hepatocellular carcinoma, HCC），下列敘述何者正確？","options":["(A) 射頻消融術（radiofrequency ablation, RFA）並不是一種根除性的治療","(B) 經動脈化學栓塞（transarterial chemoembolization, TACE）的療效與開刀差不多","(C) 由於肝細胞癌併發肝門靜脈主幹侵犯（main portal vein thrombosis）對於開刀或栓塞（TACE）的效果都不佳，因此建議做肝臟移植","(D) 對於肝細胞癌的治療，除了腫瘤外，也要考慮到肝臟本身的情況（如：肝硬化、病毒性肝炎）"],"answer":3,"image":""},{"id":"md3-112-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"下列何種情況，並不是肝硬化常見的併發症？","options":["(A) 肝性腦病變（hepatic encephalopathy）","(B) 腹水（ascites）","(C) 肝臟局部結節性增生（focal nodular hyperplasia）","(D) 食道靜脈曲張（esophageal varices）"],"answer":2,"image":""},{"id":"md3-112-2-24","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"58歲男性，高血壓已10年，無噁心、嘔吐，走路及一般日常生活不喘，下肢無水腫，腎臟功能持續惡化，腎2絲球過濾率（eGFR）降至11 mL/min/1.73 m、血色素11.3 g/dL、血壓128/80 mmHg，使用兩種降壓藥，血 -+ HCO3 22 mEq/L、血P 3.5 mg/dL、血K 4.5 mEq/L，現階段下列何種治療或策略對病人日後的存活率最沒有助益？","options":["(A) 維持目前血色素濃度","(B) 持續控制血壓","(C) 開始透析治療","(D) 轉介照會腎臟科醫師做進一步處置"],"answer":2,"image":""},{"id":"md3-112-2-25","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"48歲男性，末期腎病病人，無糖尿病病史和家族史，接受血液透析治療2年後，接受親屬腎臟移植。術後移植腎功能正常，血中creatinine下降至0.8 mg/dL，但飯前血糖多次檢測皆高於200 mg/dL，下列何種藥物與其血糖升高最有關係？","options":["(A) cyclosporine","(B) tacrolimus","(C) sirolimus","(D) mycophenolate mofetil"],"answer":1,"image":""},{"id":"md3-112-2-26","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"下列何種慢性腎小管間質性病變，其致病機轉尚未被證實與DNA損傷有關？","options":["(A) Mesoamerican nephropathy","(B) karyomegalic interstitial nephritis","(C) Chinese herbal nephropathy","(D) Balkan endemic nephropathy"],"answer":0,"image":""},{"id":"md3-112-2-27","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"下列有關腎結石症（nephrolithiasis）的處置敘述，何者錯誤？","options":["(A) 肌肉注射非類固醇抗發炎劑對於腎絞痛（renal colic）的療效可比擬甚至優於類鴉片藥物","(B) 補充大量體液或投與利尿劑無法促進結石排出","(C) 內科排出療法可降低輸尿管痙攣並增加結石自行排出率","(D) 統合分析結果顯示體外震波（extracorporeal shock wave）是輸尿管結石的治療首選"],"answer":3,"image":""},{"id":"md3-112-2-28","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"下列何項處置無助於減緩自體顯性多囊性腎臟病（autosomal dominant polycystic kidney disease, ADPKD）病人的腎功能惡化？","options":["(A) 第一線使用鈣離子阻斷劑，控制血壓在140/90 mmHg之下，在腎功能不良下，收縮壓儘量控制小於110 mmHg","(B) 如果有囊泡感染的狀況，使用lipid-soluble antibiotics，如：trimethoprim-sulfamethoxazole、quinolones、chloramphenicol，因為囊泡穿透性較佳，效果較好，常需要使用四星期以上","(C) 使用vasopressin antagonist（tolvaptan）來減緩囊泡的形成及腎功能惡化","(D) 建議病人限制低鹽（＜5 g/day）飲食"],"answer":0,"image":""},{"id":"md3-112-2-29","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"有關糖尿病腎病變，下列何者錯誤？","options":["(A) 是目前臺灣最常見造成慢性腎臟病的原因","(B) 大約有20%糖尿病患者產生糖尿病腎病變","(C) 產生糖尿病腎病變的危險因子包括gene polymorphisms affecting the activity of the renin-angiotensin-aldosterone axis","(D) 糖尿病視網膜病變和病理上的Kimmelstiel-Wilson nodules有很強的相關性"],"answer":1,"image":""},{"id":"md3-112-2-30","subject":"md3","topic":"內科-腎臟","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"在哺乳類腎臟的腎絲球–腎小管發育時，不同時期有不同的基因調控。在前腎小管聚合期（pretubular aggregation）時，下列那一個基因未參與？","options":["(A) VEGF-A / Kdr","(B) Wnt4","(C) Emx2","(D) Fgf8"],"answer":0,"image":""},{"id":"md3-112-2-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"一位52歲女性有多處關節疼痛的症狀，經診斷患有fibromyalgia，且未伴隨其他的免疫疾病，其典型的血中C- reactive protein（CRP）和erythrocyte sedimentation rate（ESR）的值應為如何？","options":["(A) CRP和ESR皆上升","(B) CRP上升，但ESR正常","(C) CRP正常，但ESR上升","(D) CRP和ESR皆正常"],"answer":3,"image":""},{"id":"md3-112-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"有關類風濕性關節炎臨床表現，下列何者正確？","options":["(A) 通常一開始以左右不對稱、大關節發炎為主，後期才會影響小關節","(B) 當遠端指間關節（distal interphalangeal joint）也受影響時，通常代表同時也患有退化性關節炎","(C) 伸側（extensor）肌腱發生肌腱滑膜炎（tenosynovitis）的機會比曲側（flexor）肌腱常見很多","(D) 頸椎發炎雖然少見，但是通常發生在疾病的早期"],"answer":1,"image":""},{"id":"md3-112-2-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"有關inflammatory myopathies的鑑別診斷，下列何者正確？","options":["(A) dermatomyositis主要以成人為主，polymyositis則是成人跟幼童都可以發生","(B) inclusion body myositis主要發生在大於50歲病人，且以女性居多","(C) polymyositis病人的肌肉切片以endomysial與perivascular inflammation表現，且以CD8+ T cells浸潤為主","(D) necrotizing myopathy與惡性腫瘤較無關"],"answer":2,"image":""},{"id":"md3-112-2-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"病人出現下列何種感染時，最應考慮是否有補體系統的缺損（complement deficiencies）？","options":["(A) 反覆分枝桿菌（Mycobacteria）感染","(B) 反覆奈瑟氏菌（Neisseria）感染","(C) 反覆帶狀疱疹（herpes zoster）感染","(D) 反覆葡萄球菌（Staphylococcus）感染"],"answer":1,"image":""},{"id":"md3-112-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"下列有關退化性關節炎（osteoarthritis, OA）之敘述，何者錯誤？","options":["(A) 手部及髖關節之OA與遺傳基因較有關，而膝關節與遺傳基因的相關性較少","(B) 關節type 2之軟骨主要被MMPs（matrix metalloproteinases）破壞","(C) 華人髖關節OA較白種人少見","(D) 90%以上OA患者必須先行使用非類固醇抗發炎藥物（NSAID）"],"answer":[1,3],"image":"","answer_note":"更正:第35題答Ｂ或Ｄ或BD者均給分"},{"id":"md3-112-2-36","subject":"md3","topic":"內科-腫瘤","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"一位35歲婦女，因右側乳房有一腫塊，後接受切除切片證實為estrogen receptor（ER）陽性、progesterone receptor（PR）陽性、HER2陽性（組織免疫染色3+）之侵襲性乳癌，與主治醫師討論後，病人決定接受右側乳房保留手術和前哨淋巴結切片手術，其最後病理檢體證實腫瘤為直徑3公分，腋下淋巴結2顆轉移之侵襲性乳癌，下列何者術後輔助治療對降低病人乳癌局部及遠處轉移之效果最好？","options":["(A) anthracycline為主化學治療，加上抗賀爾蒙治療以及放射線治療","(B) 紫杉醇為主化學治療，加上抗賀爾蒙治療和放射線治療","(C) 合併化學治療以及卵巢去功能手術","(D) 化學治療合併trastuzumab，以及抗賀爾蒙治療和放射線治療"],"answer":3,"image":""},{"id":"md3-112-2-37","subject":"md3","topic":"內科-腫瘤","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"針對原發部位不明轉移腺癌（adenocarcinoma of unknown primary）之病人，臨床醫師可藉由組織學染色之一系列流程，來鑑別可能之原發腺癌，下列敘述何者錯誤？","options":["(A) 若CK（cytokeratin）7+，CK20+：可以幫助診斷卵巢癌或胰臟癌","(B) 若CK（cytokeratin）7+，CK20-：可以幫助診斷子宮內膜癌或肺癌","(C) 若CK（cytokeratin）7-，CK20+：可以幫助診斷前列腺癌或甲狀腺癌","(D) 若CK（cytokeratin）7-，CK20-：可以幫助診斷肝細胞癌或腎細胞癌"],"answer":2,"image":""},{"id":"md3-112-2-38","subject":"md3","topic":"內科-腫瘤","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"某些癌症的治療可能與某些second malignancies的發生相關。下列有關癌症治療與second malignancy的組合，何者最不恰當？","options":["(A) topoisomerase inhibitors；acute lymphoblastic leukemia associated with deletions in chromosome 5 or 7","(B) tamoxifen；endometrial cancer","(C) 異體骨髓移植使用T-cell depletion；EBV-associated lymphoproliferative disorder","(D) 化學治療；myelodysplastic syndrome"],"answer":0,"image":""},{"id":"md3-112-2-39","subject":"md3","topic":"內科-腫瘤","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"胃的惡性腫瘤中，腺癌（adenocarcinoma）約占85%。其餘15%非腺癌的胃的惡性腫瘤中，下列敘述何者正確？","options":["(A) 胃的淋巴瘤（lymphoma）中，T-cell origin遠多於B-cell origin","(B) 局限於胃部的mucosa-associated lymphoid tissue（MALT）lymphoma第一線治療為清除Helicobacter pylori的抗生素治療","(C) 局限於胃部的leiomyosarcoma治療首選（treatment of choice）是化學治療合併放射治療","(D) 胃的gastrointestinal stromal tumor（GIST）若轉移至肝臟，應考慮組合式化學治療"],"answer":1,"image":""},{"id":"md3-112-2-40","subject":"md3","topic":"內科-腫瘤","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"下列藥物中何者最常使用於第四期腎細胞癌的全身性藥物治療？","options":["(A) 化學治療的doxorubicin","(B) 標靶治療的axitinib","(C) 標靶治療的trastuzumab","(D) 免疫治療的sipuleucel-T"],"answer":1,"image":""},{"id":"md3-112-2-41","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"關於癌症預防的敘述，下列何者錯誤？","options":["(A) B型肝炎疫苗能預防因為慢性B型肝炎病毒感染導致的肝炎、肝細胞癌","(B) 如果先前未被某一型的人類乳突病毒感染過，接受該型人類乳突病毒疫苗，能預防該型人類乳突病毒感染的持續感染","(C) 如果先前未被某一型的人類乳突病毒感染過，接受該型人類乳突病毒疫苗，能預防該型人類乳突病毒感染所造成的癌前病變","(D) 人類乳突病毒疫苗接種過後可有終生免疫效果"],"answer":3,"image":""},{"id":"md3-112-2-42","subject":"md3","topic":"內科-血液","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"下列有關血小板（platelet）的敘述，何者錯誤？","options":["(A) 血小板無核，也無RNA，因此沒有合成蛋白質的能力","(B) 正常的血小板之直徑約1～5 μm，平均在血液中的存活期約7～10天","(C) 血小板的GPIb-IX-V複合體，對血小板之黏附（adhesion）與血小板之活化非常重要","(D) 在急性冠狀動脈症候群（acute coronary syndrome）的病人血液中，其血小板彼此之間，以及血小板與白血球之間的交互作用均增強"],"answer":0,"image":""},{"id":"md3-112-2-43","subject":"md3","topic":"內科-血液","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"下列有關造血幹細胞移植（hematopoietic stem cell transplantation）的敘述，何者最不恰當？","options":["(A) n一位病人若有n個同父同母的兄弟姊妹，則可以找到至少一位HLA全合的兄弟姊妹的機率是1-(0.75)","(B) 進行異體造血幹細胞移植（allogeneic hematopoietic stem cell transplantation），若是ABO血型不相合，通常在移植前的免疫抑制劑的劑量必須增加或是進行recipient之脾臟切除","(C) 自體造血幹細胞移植（autologous hematopoietic stem cell transplantation）並無graft-versus-host disease（GVHD）或是graft rejection的風險","(D) 周邊血液中，在施打granulocyte colony-stimulating factor（G-CSF）數天之後，也可能收集到足夠的造血幹細胞進行移植。若是收集的數量不足，施打plerixafor（一種CXCR4的拮抗劑），可以幫助收集到更多的造血幹細胞"],"answer":[1,2],"image":"","answer_note":"更正:第43題答Ｂ或Ｃ或BC者均給分"},{"id":"md3-112-2-44","subject":"md3","topic":"內科-血液","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"慢性淋巴性白血病（chronic lymphocytic leukemia, CLL）的病人，具有下列何種的染色體變異，有較佳的預後？","options":["(A) del(13)(q14.3)","(B) del(11)(q22.3)","(C) trisomy 12","(D) del(17)(p13.1)"],"answer":0,"image":""},{"id":"md3-112-2-45","subject":"md3","topic":"內科-胸腔","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"65歲男性至門診求診，主訴慢性咳嗽及運動性氣促，過去無心臟病或糖尿病之病史，抽菸史50包年，已戒菸2年。最近咳嗽氣促的症狀加劇，下列何者是診斷COPD的必要檢查？","options":["(A) 胸部電腦斷層","(B) 支氣管鏡檢查","(C) 支氣管擴張試驗","(D) serum alpha-1 antitrypsin level"],"answer":2,"image":""},{"id":"md3-112-2-46","subject":"md3","topic":"內科-胸腔","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"3 COPD病人接受長效型支氣管擴張劑治療3個月後症狀仍不穩定，抽血檢查發現WBC：9,500/mm；neutrophil：70%；eosinophil：5%；C-reactive protein：1.5 mg/dL，下列治療何者最為恰當？","options":["(A) add-on theophylline","(B) add-on macrolide","(C) add-on leukotriene modifier","(D) add-on inhaled corticosteroid"],"answer":3,"image":""},{"id":"md3-112-2-47","subject":"md3","topic":"影像醫學","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"體外胸腔超音波檢查對下列何種情況之診斷，最沒有幫助？","options":["(A) 肋膜腔積水","(B) 氣胸","(C) 橫膈膜麻痺","(D) 兩側肺門淋巴腺腫"],"answer":3,"image":""},{"id":"md3-112-2-48","subject":"md3","topic":"內科-胸腔","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"63歲男性病人，因運動時呼吸困難前來就診，肺功能檢查顯示TLC 70%預測值，FEV1/FVC 80%，最大吸氣壓力（maximal inspiratory pressure）55%預測值，下列何者為最有可能之診斷？","options":["(A) 慢性阻塞性肺病","(B) 肥胖症","(C) 肺葉切除術後","(D) 重症肌無力"],"answer":3,"image":""},{"id":"md3-112-2-49","subject":"md3","topic":"內科-感染","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"因為丈夫罹患isoniazid抗藥性的開放性肺結核而接受接觸者檢查的33歲女性，她的胸部X光檢查正常但丙型干擾素血液測驗（interferon-γ release assay）為陽性。下列何者為此女性最適合的潛伏結核感染治療處方？","options":["(A) 9個月的每日一次isoniazid治療","(B) 2個月的rifampin及pyrazinamide治療","(C) 4個月的每日一次rifampin治療","(D) 9個月的每日一次levofloxacin治療"],"answer":2,"image":""},{"id":"md3-112-2-50","subject":"md3","topic":"內科-感染","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"關於非結核分枝桿菌（nontuberculous mycobacteria），下列敘述何者最適當？","options":["(A) 非結核分枝桿菌的肺部感染，幾乎都發生於人類免疫缺陷病毒感染的病人","(B) 非結核分枝桿菌中的M. gordonae表現與結核菌相似，容易造成肺部的感染","(C) M. avium complex是慢速生長菌；此菌引起的肺部感染，治療時間通常需要達18個月","(D) M. abscessus是快速生長菌；此菌引成的肺部感染，藥物治療時間與一般肺炎相同，約需2個星期"],"answer":2,"image":""},{"id":"md3-112-2-51","subject":"md3","topic":"內科-胸腔","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"下列有關急性肺栓塞（acute pulmonary embolism）的敘述，何者正確？","options":["(A) 胸痛為Wells' clinical prediction rule臨床診斷準則項目之一","(B) plasma D-dimer test對急性肺栓塞的診斷有極高敏感度（sensitivity）與專一性（specificity）","(C) 經靜脈或皮下注射的抗凝劑，如低分子量肝素（low-molecular-weight heparin），應持續使用5天以上，並維持international normalized ratio在2.0～3.0之間至少連續2天","(D) 嚴重肺栓塞病人最常見的死因為右心室衰竭所導致的心因性休克"],"answer":3,"image":""},{"id":"md3-112-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"下列有關原發性副甲狀腺高能症（primary hyperparathyroidism）的敘述，何者錯誤？","options":["(A) 副甲狀腺瘤造成之副甲狀腺高能症，此時副甲狀腺之腫瘤多半是單一腺瘤（isolated adenoma）","(B) 副甲狀腺瘤可能是多發性內分泌腫瘤（multiple endocrine neoplasia）的一種臨床表現","(C) 常表現高血鈣、高血磷及低血氯","(D) 血鈣濃度高於14 mg/dL（3.5 mmol/L）時，病理學報告經常是副甲狀腺癌"],"answer":2,"image":""},{"id":"md3-112-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"老年男性血中之雄性激素濃度較高時，下列疾病或狀況何者最不可能發生？","options":["(A) 性慾較高","(B) 罹患冠狀動脈疾病機率較低","(C) 罹患糖尿病機率較高","(D) 死亡率較低"],"answer":2,"image":""},{"id":"md3-112-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"下列有關糖尿病與高血壓的敘述，何者錯誤？","options":["(A) 糖尿病病人的高血壓盛行率較沒有糖尿病者高","(B) 糖尿病病人罹患高血壓的首選控制血壓藥物為angiotensin-converting enzyme inhibitors或是angiotensin receptor blockers","(C) 糖尿病病人的血壓控制目標一般建議比沒有糖尿病的患者來得寬鬆","(D) 高血壓會促進糖尿病的大血管與小血管病變的發生及惡化"],"answer":2,"image":""},{"id":"md3-112-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"下列何種藥物未曾被核准用來減輕體重？","options":["(A) liraglutide","(B) lorcaserin","(C) orlistat","(D) sitagliptin"],"answer":3,"image":""},{"id":"md3-112-2-56","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"有關血糖的調控，下列敘述何者錯誤？","options":["(A) 胰島素是由胰臟所分泌，會使血液中的葡萄糖濃度降低","(B) 一般正常人的血糖會隨著飲食及運動等狀況在一定的範圍內波動","(C) 血糖太低可能會導致死亡","(D) metformin是最常引起低血糖的口服降血糖藥物"],"answer":3,"image":""},{"id":"md3-112-2-57","subject":"md3","topic":"內科-腫瘤","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"下列何者是最常見的甲狀腺癌？","options":["(A) 乳突癌（papillary carcinoma）","(B) 濾泡細胞癌（follicular carcinoma）","(C) 髓質癌（medullary carcinoma）","(D) 未分化癌（anaplastic carcinoma）"],"answer":0,"image":""},{"id":"md3-112-2-58","subject":"md3","topic":"內科-內分泌代謝","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"腦下垂體後葉若遭受破壞，最可能出現下列何種疾病？","options":["(A) 尿崩症","(B) 腎上腺機能不足","(C) 甲狀腺功能不足","(D) 性功能異常"],"answer":0,"image":""},{"id":"md3-112-2-59","subject":"md3","topic":"內科-感染","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"有關中心靜脈導管相關血流感染之預防措施組合（bundle），包括下列那些項目：①參與導管及置放照護人員需接受教育訓練②中心導管置入時使用最大無菌面防護（maximal barrier precaution） ③皮膚消毒使用含有chlorhexidine的抗菌液 ④常規每兩週更換中心靜脈導管","options":["(A) ①②③④","(B) 僅①②③","(C) 僅③④","(D) 僅①②④"],"answer":1,"image":""},{"id":"md3-112-2-60","subject":"md3","topic":"內科-感染","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"血液幹細胞移植後使用一年trimethoprim-sulfamethoxazole（TMP-SMX）預防，可以減少的致病原感染，下列何者最不適當？","options":["(A) Listeria monocytogenes","(B) Nocardia spp.","(C) Streptococcus pneumoniae","(D) Neisseria meningitidis"],"answer":3,"image":""},{"id":"md3-112-2-61","subject":"md3","topic":"內科-感染","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"對於年紀3個月以下嬰兒、55歲以上民眾及細胞媒介免疫（cell-mediated immunity）缺損病人感染細菌性腦膜炎時，要考慮針對革蘭氏陽性桿菌Listeria monocytogenes的治療，應以下列何種藥物為首選？","options":["(A) ceftriaxone","(B) ampicillin","(C) vancomycin","(D) ciprofloxacin"],"answer":1,"image":""},{"id":"md3-112-2-62","subject":"md3","topic":"內科-風濕免疫過敏","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"35歲病人因為出現兩天的尿道分泌物與灼熱疼痛感就醫，沒有符合腸胃感染的腹瀉病徵。經檢測診斷為non- gonococcal urethritis，治癒大約四週後，出現膝、踝和薦椎部等關節炎，同時併有結膜炎（conjunctivitis）與葡萄膜炎（uveitis）、手掌與腳部丘疹。下列敘述何者錯誤？","options":["(A) 病人發生staphylococcal infective endocarditis和septic arthritis","(B) 病人發生reactive arthritis","(C) 病人先前的non-gonococcal urethritis和後續併發的病症，最有可能和Chlamydia trachomatis感染相關","(D) 發生這些併發症的病人，超過80%帶有HLA-B27表現型（phenotype）"],"answer":0,"image":""},{"id":"md3-112-2-63","subject":"md3","topic":"內科-感染","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"關於細菌性食物中毒與旅行者腹瀉（traveler's diarrhea）的敘述，下列何者錯誤？","options":["(A) 潛伏期（incubation period）最短的致病菌是Staphylococcus aureus和Bacillus cereus","(B) Shigella spp.只能藉由污染的飲水和食物傳播，不會由人對人直接傳染","(C) Shigella spp.、Entamoeba histolytica、Giardia lamblia引起疾病所需感染劑量（infectious dose），遠低於Vibrio cholerae","(D) Vibrio cholerae所致的腹瀉係因產生enterotoxin，糞便中鮮少或不會出現白血球"],"answer":1,"image":""},{"id":"md3-112-2-64","subject":"md3","topic":"內科-感染","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"60歲男性病患，已接受血液透析治療10年。此次因發燒、喘及胸部X光發現診斷為肺炎，住院後痰液培養為methicillin-resistant Staphylococcus aureus（MRSA），則可能的抗生素治療中，下列何者不宜？","options":["(A) vancomycin","(B) teicoplanin","(C) linezolid","(D) oxacillin"],"answer":3,"image":""},{"id":"md3-112-2-65","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"65歲男性病人抽菸30年，因慢性阻塞性肺病在門診追蹤多年，此次肺炎經抗生素治療後順利出院，則針對肺炎的預防治療中，下列何者錯誤？","options":["(A) 戒菸","(B) 若之前沒有打疫苗，可建議接種肺炎鏈球菌疫苗","(C) 於流感季節前，建議每年施打流感疫苗","(D) 預防性抗生素治療"],"answer":3,"image":""},{"id":"md3-112-2-66","subject":"md3","topic":"家醫-行為與社區醫學","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"臨床上有關生物心理社會模式中的心理因素，可使用人格特質五因素模型（five-factor model of personality, OCEAN）來探討，下列有關此模型意涵之敘述何者錯誤？","options":["(A) 經驗開放性（Openness to experience）：對不同經驗傾向保持好奇和欣賞","(B) 盡責性（Conscientiousness）：傾向自我訓練，有計畫地達成目標","(C) 效能性（Efficacy）：傾向能達成任務的能力和信念","(D) 親和性（Agreeableness）：傾向與其他人合作，較喜歡融洽"],"answer":2,"image":""},{"id":"md3-112-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"關於老人虐待（elder abuse）的敘述，下列何者最正確？","options":["(A) 老人虐待發生率很低，不必篩檢","(B) 虐待的定義範圍僅限於身體及情緒的虐待","(C) 下肢水腫是虐待常見的徵候","(D) 藥物順從性不佳，也有可能是虐待的徵候"],"answer":3,"image":""},{"id":"md3-112-2-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"18歲大一男生因咳嗽來門診就醫，其健康狀況良好且有親密女友，依據美國預防醫學工作小組（US Preventive Services Task Force）的預防保健建議，下列何者是最不需要的篩檢或諮詢項目？","options":["(A) 脊椎側彎（idiopathic scoliosis）","(B) 肥胖（obesity）","(C) 性接觸傳染病（sexually transmitted infection）","(D) 預防菸品使用（tobacco use）"],"answer":0,"image":""},{"id":"md3-112-2-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"有關旅遊疫苗接種的敘述，下列何者最正確？","options":["(A) 免疫功能正常者建議於旅遊至少1週前接種一劑A型肝炎疫苗","(B) 免疫功能正常者建議於旅遊至少1週前接種一劑B型肝炎疫苗","(C) 黃熱病（yellow fever）疫苗原則上終生有效，然部分國家仍建議每10年追加1劑","(D) 流行性腦脊髓膜炎（meningococcus）疫苗為前往沙烏地阿拉伯的旅客所需，建議每10年追加1劑"],"answer":2,"image":""},{"id":"md3-112-2-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"關於敏感度（sensitivity）、特異度（specificity）、陽性預測值（positive predictive value）及陰性預測值（negative predictive value）的定義，下列何者正確？","options":["(A) 敏感度是「罹患疾病且檢驗為陽性者的比率」","(B) 特異度是「罹患疾病且檢驗為陰性者的比率」","(C) 陽性預測值是「檢驗陽性且沒有患病的比率」","(D) 陰性預測值是「檢驗陰性且有患病的比率」"],"answer":0,"image":""},{"id":"md3-112-2-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"下列有關動機晤談（motivational interviewing）的敘述，何者正確？","options":["(A) 最早是使用於糖尿病飲食衛教","(B) 為一種由醫師主導增強病人改變動機之看診模式","(C) 行為改變的動機及目標在與病人討論後，由醫師協助決定","(D) 溝通時須運用同理心及主動式傾聽（active listening）的原則與技巧"],"answer":3,"image":""},{"id":"md3-112-2-72","subject":"md3","topic":"家醫-行為與社區醫學","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"根據美國2003年聯邦醫療保險Medicare的統計資料及Barbara Starfield針對基層醫療的研究，下列敘述何者最不恰當？","options":["(A) 專科醫師（specialists）所占比例越高，照護品質越高，醫療花費越高","(B) 全科醫師（generalists）所占比例越高，照護品質越高，醫療花費越低","(C) 基層醫療較完善充足的地區，心臟病（heart disease）及中風（stroke）的發生率減少","(D) 基層醫療較完善充足的地區，低出生體重（low birth weight）嬰兒比率減少"],"answer":0,"image":""},{"id":"md3-112-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"當末期病人呼吸困難（dyspnea）時，下列安寧緩和醫療常用方法中，何者最不適當？","options":["(A) 給與氧氣","(B) 給與低劑量嗎啡","(C) 給與鎮定","(D) 給與氣管擴張劑"],"answer":2,"image":""},{"id":"md3-112-2-74","subject":"md3","topic":"影像醫學","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"有關下列疾病所選用的影像學檢查，其中何者最不適宜？","options":["(A) 鋇劑吞嚥食道攝影（barium esophagogram）可以偵測急性胰臟炎（acute pancreatitis）","(B) 電腦斷層（CT）或超音波（US）可以用於胰臟假性囊腫（pancreatic pseudocyst）的追蹤","(C) 鋇劑吞嚥食道攝影（barium esophagogram）可用於偵測食道阻塞或吞嚥困難（dysphagia）","(D) 注射對比劑的腹部電腦斷層檢查（CT of abdomen with contrast）可用於偵測嚴重胰臟炎（pancreatitis）"],"answer":0,"image":""},{"id":"md3-112-2-75","subject":"md3","topic":"影像醫學","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"下圖為肝臟超音波掃描，最可能的診斷為：","options":["(A) 肝臟之蛔蟲疾病（hepatic ascariasis）","(B) 原發性肝細胞癌（hepatocellular carcinoma）","(C) 氣膽（pneumobilia）","(D) 肝內膽管結石（intrahepatic bile duct stones）"],"answer":2,"image":"md3-112-2-75.jpeg"},{"id":"md3-112-2-76","subject":"md3","topic":"急診醫學","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"熱衰竭（heat exhaustion/heat stress）不會出現下列何種症狀？","options":["(A) 心跳加速（tachycardia）","(B) 肌肉抽筋（muscle cramp）","(C) 姿勢性低血壓（orthostatic hypotension）","(D) 意識混亂（confusion）"],"answer":3,"image":""},{"id":"md3-112-2-77","subject":"md3","topic":"內科-感染","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"下列有關傷寒（typhoid fever）的敘述，何者最正確？","options":["(A) 常見有多天的發燒、腹瀉及血便為主要的表現","(B) 病人可能有白血球下降、肝功能異常及脾腫大","(C) 使用抗生素後，最容易培養出細菌的方法是糞便培養","(D) Salmonella typhi菌株對於fluoroquinolone類抗生素沒有抗藥性的產生"],"answer":1,"image":""},{"id":"md3-112-2-78","subject":"md3","topic":"急診醫學","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"65歲陳先生有高血壓、糖尿病之病史。晚上睡到一半忽然覺得胸部劇烈壓迫性疼痛合併有冒冷汗、呼吸急促的症狀。家人迅速將他送醫治療，到院時意識清楚，體溫正常，呼吸24/min，心跳72/min，血壓80/54 mmHg，心電圖顯示Lead II、Lead III和aVF有ST-segment上升大於2 mm的現象。最可能的診斷為下列何者？","options":["(A) 肺栓塞（pulmonary embolism）","(B) 主動脈剝離（aortic dissection）","(C) 急性心肌梗塞（acute myocardial infarction）","(D) 急性心肌炎（acute myocarditis）"],"answer":2,"image":""},{"id":"md3-112-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"一位年輕男性發生車禍被救護車送至急診室，醫師判斷必須立即動手術，否則恐有生命危險，但該病人已經意識不清，身上亦未攜帶任何證件可證明身分或聯絡家人，醫院應如何處理該狀況？","options":["(A) 由手術醫師代理病人簽署手術同意書","(B) 由社會工作人員代理病人簽署手術同意書","(C) 若情況緊急，可逕行急救手術","(D) 在聯絡到病人親屬前不得進行手術"],"answer":2,"image":""},{"id":"md3-112-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"關於守密義務，下列敘述何者錯誤？","options":["(A) 是屬於醫學倫理尊重病人自主原則的內涵","(B) 醫師因業務知悉或持有他人的秘密，其保密義務限於執業期間，退休之後可以出書揭露","(C) 涉及重大的公益事件，醫師權衡利弊，有時可以違反保密原則，適當的揭露","(D) 違反守密義務，涉及民事與刑事責任"],"answer":1,"image":""},{"id":"md3-113-1-1","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"關於妊娠糖尿病（gestational diabetes mellitus, GDM）的敘述，下列何者最不適當？","options":["(A) GDM的篩檢時程通常是在懷孕第24～28週執行","(B) 確診有GDM的病患，先以飲食控制使血糖達到理想範圍","(C) 飲食控制無法使血糖達標時，可加上胰島素或口服降血糖藥控制","(D) 患有GDM的女性將來發生第二型糖尿病的風險跟沒有GDM的女性接近"],"answer":3,"image":""},{"id":"md3-113-1-2","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"4位醫學生分別使用下列量表評估病人的預後，何者最不恰當？學生量表評估對象甲生APACHE II Score加護病房重症病人乙生BODE Index壓傷（pressure injury）病人International丙生非何杰金氏淋巴瘤（non-Hodgkin's lymphoma）病人Prognostic Index非ST波段上升之急性冠心症（non-ST segment elevation acute丁生TIMI Risk Score coronary syndrome）病人","options":["(A) 甲生","(B) 乙生","(C) 丙生","(D) 丁生"],"answer":1,"image":"md3-113-1-2.jpeg"},{"id":"md3-113-1-3","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"承上題，上述4種量表中，共有幾種將「年齡」納入評分項目之內？","options":["(A) 1種","(B) 2種","(C) 3種","(D) 4種"],"answer":2,"image":""},{"id":"md3-113-1-4","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"80歲男性過去有高血壓、糖尿病、高血脂症及痛風病史，最近3週以來主訴全身水腫，特別是在早晨起床時覺得眼皮周圍及臉部腫脹，日間活動之後才會逐漸改善，問診時病人表示平躺時沒有呼吸困難，半夜沒有因為喘不過氣而醒來，下列抽血檢驗結果何者最符合此病人的特徵？","options":["(A) NT-Pro-BNP：2500 pg/mL","(B) Albumin：1.8 g/dL","(C) TSH：9.0 μIU/mL","(D) Free T4：2.8 ng/dL"],"answer":1,"image":""},{"id":"md3-113-1-5","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"為病人進行身體診查時，以手指拍打病人耳前之面神經分支，同側之面部肌肉會收縮；改以血壓計之纏臂（cuff）包裹手臂，加壓至高於病人收縮壓20 mmHg以上維持3分鐘，出現手腕抽筋（carpal spasm），該病人最可能有下列何種離子異常？","options":["(A) 高血鈣（hypercalcemia）","(B) 低血鈣（hypocalcemia）","(C) 高血磷（hyperphosphatemia）","(D) 低血磷（hypophosphatemia）"],"answer":1,"image":""},{"id":"md3-113-1-6","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"下列有關診斷性心導管中所得各項壓力之敘述，何者正確？","options":["(A) 主動脈瓣狹窄病人當心室早搏後，於下一心跳時會出現左心室及主動脈間壓差變大，且主動脈脈搏壓減少，稱為Brockenbrough-Braunwald sign","(B) 心包積液病人發生心包填塞時，右心房壓力會上升，且壓力曲線之「y下降段（y descent）」會變得極明顯","(C) 束縮性心包膜炎（constrictive pericarditis）病人之右心室收縮期壓力一般低於50 mmHg，且其壓力曲線會呈現square root sign","(D) 限制性心肌症（restrictive cardiomyopathy）病人之右心室舒張末期壓力，一般高於右心室收縮期壓力之1/3，且與左心室舒張末期壓力相差不超過5 mmHg"],"answer":2,"image":""},{"id":"md3-113-1-7","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"下列有關非ST段上升急性冠狀動脈症候群（non-ST-segment elevation acute coronary syndrome, NSTE- ACS）之敘述，何者正確？","options":["(A) 超過一半的NSTE-ACS病人，在急診行心電圖檢查能發現新的ST段下降，深的（＞3mV）T波倒置也很常見","(B) NSTE-ACS的病人，若抽血發現cardiac troponin升高，但creatine kinase仍正常，尚不能診斷非ST段上升心肌梗塞（non-ST-segment elevation myocardial infarction, NSTEMI）","(C) 因NSTE-ACS之致病機轉通常為不穩定斑塊破裂，所以所有病人須合併使用aspirin、P2Y12抑制劑、醣蛋白GPIIb/IIIa受體抑制劑三者，以抑制血小板凝集","(D) 生命跡象及血行動力穩定、胸痛可以用藥物控制，但GRACE危險評分＞140的NSTE-ACS病人，應考慮在24小時內進行心導管及血流重建治療"],"answer":3,"image":""},{"id":"md3-113-1-8","subject":"md3","topic":"影像醫學","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"下列關於核醫心肌灌流造影的敘述，何者錯誤？","options":["(A) 同位素心肌攝取量與血流量及心肌是否存活有關","(B) Thallium-201（Tl-201）半衰期12小時，為主動運輸進入心肌，不同狀況的心肌細胞其清除率及活性不同，在心肌受傷或缺氧時，活性較高且清除率較快，因此會有「逆再分布（reverse redistribution）」的現象","(C) Tc-99m sestamibi半衰期為6小時，是利用被動運輸進入心肌","(D) Thallium-201（Tl-201）擁有與鉀離子相同的生物學特性"],"answer":1,"image":""},{"id":"md3-113-1-9","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"一位40歲男性病患，沒有任何心臟的病史，因為中風而住院。經詢問病史，過去一年躺臥呈某特定姿勢時，會伴隨眼前發黑的徵兆（black out）、倦怠、體重減輕等狀況；身體診察發現心臟聽診於心尖部舒張中期有一低頻心音，輕微杵狀指（digital clubbing）；心臟超音波檢查如附圖。圖①為心室收縮期呈像，圖②為心室舒張期呈像（RA=右心房；RV=右心室；LV=左心室），經診斷為左心房黏液瘤（left atrial myxoma），下列敘述何者正確？","options":["(A) 男女的比例約為3比1","(B) 因復發率高，開刀後需要肝素（heparin）或新型抗凝血劑（NOAC）治療以預防中風","(C) 大部分發生在右心房，左心房次之，其他也可能在心室且常是多發性","(D) 其腫瘤表面纖細（fine）、呈現絨毛（villous）、凝膠（gelatinous）狀、易碎，一旦脫落就會產生栓塞"],"answer":3,"image":"md3-113-1-9.jpeg"},{"id":"md3-113-1-10","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"一位80歲男性，過去有高血壓、高血脂及心肌梗塞病史。最近一次抽血腎功能正常（CCr = 100 mL/min）今日因喘至門診，十二導程心電圖如附圖所示。為降低病患之後罹患缺血性中風之風險，下列對於給與藥物治療之敘述，何者正確？","options":["(A) 病患不需要接受抗凝血劑治療","(B) 若選擇dabigatran，當有緊急出血情況時，有抗凝血藥物反轉劑（reversal agent）可使用","(C) 若病患希望選擇一天僅需吃一次的藥物，應選擇apixaban","(D) 若病患出血風險高，根據目前心房顫動治療指引，可選擇aspirin替代"],"answer":1,"image":"md3-113-1-10.jpeg"},{"id":"md3-113-1-11","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"關於心雜音的描述，下列何者錯誤？","options":["(A) Valsalva maneuver會使主動脈狹窄（aortic stenosis）的心雜音變短和變弱","(B) 在吐氣時三尖瓣回流（tricuspid regurgitation）的心雜音會變大聲","(C) 在站立時二尖瓣回流（mitral regurgitation）的心雜音會變小聲","(D) 在蹲著時肥厚型阻塞性心肌症（hypertrophic obstructive cardiomyopathy）的心雜音會變小聲"],"answer":1,"image":""},{"id":"md3-113-1-12","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"關於肥厚型心肌症（hypertrophic cardiomyopathy）的描述，下列何者正確？","options":["(A) 演變成擴大型心肌症的比率小於10%","(B) 大部分病人在出生時即有左心室肥厚的現象","(C) 若有左心室出口阻塞，藥物處理原則是擴張血管和降低心率","(D) 運動時血壓增加30 mmHg是猝死的危險因子"],"answer":0,"image":""},{"id":"md3-113-1-13","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"下列有關血壓測量的敘述，何者錯誤？","options":["(A) 小腿與上臂的血壓差增加常見於重度主動脈閉鎖不全（aortic regurgitation）或嚴重下肢周邊血管疾病","(B) 小腿的收縮壓通常比上臂的收縮壓高20 mmHg","(C) 血壓袖帶的長度和寬度應分別為手臂圓周的80%和40%。使用不合適的小袖帶，會導致對實際血壓值明顯低估","(D) 兩側上臂的收縮血壓差距，正常應在10 mmHg以內"],"answer":2,"image":""},{"id":"md3-113-1-14","subject":"md3","topic":"內科-心臟血管","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"有關心室性心律不整（ventricular arrhythmia）與心臟猝死（sudden cardiac death）的敘述，下列何者錯誤？","options":["(A) 心室性心律不整的診斷是通過在心電圖上記錄心律不整，或通過植入的心律設備（如：心律調節器或植入性心內去顫器﹝Implanted Cardioversion Defibrillator, ICD﹞）或在電生理檢查過程中引發的心律不整來確定的","(B) 如果可能，面對心臟猝死的病患應獲取心律不整的十二導程心電圖，並研究潛在起源部位和潛在可能心臟病","(C) 猝死的發生多見於心肌缺氧性心室顫動（ventricular fibrillation）。當有植入性心內去顫器（Implanted Cardioversion Defibrillator, ICD）啟動而迅速終止心室心律不整時，代表病患在往後的死亡率與心衰竭的風險均大幅減少","(D) 對於心室性心律不整的病患，其初始治療以穩定病患的血流動力學為處理目標"],"answer":2,"image":""},{"id":"md3-113-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"Aspartate aminotransferase（AST）及alanine aminotransferase（ALT）血中數值的升高代表肝細胞的破壞，其上升幅度及AST/ALT比值能幫助我們做鑑別診斷。下列肝臟發炎性疾病何者較不會出現肝指數大幅升高（aminotransferase＞1000 IU/L）的情形？","options":["(A) 自體免疫性肝炎","(B) 缺血性肝炎","(C) 脂肪性肝炎","(D) 藥物性肝炎"],"answer":2,"image":""},{"id":"md3-113-1-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"陳小姐40歲，證券公司股票交易員，主訴右下腹部絞痛、腹瀉、噁心、體重減輕、發燒、大便帶有黏液，反覆發作已有3個月。右下腹有摸到一個腫塊，膝蓋關節疼痛且有紅色結節，大腸鏡檢查發現升結腸部位有鵝卵石樣（cobble stone）病變。下列敘述何者錯誤？","options":["(A) 病因可能與腸道菌叢及陳小姐的免疫力失調有關","(B) 疾病可能影響所有腸胃道，其病灶常是跳躍狀，嚴重時會導致腸道瘻管、膿瘍及狹窄","(C) 病理上的特徵是非乾酪性壞死肉芽腫（noncaseating granuloma）","(D) 當使用5-ASA類藥物（如sulfasalazine）、類固醇藥物或是免疫抑制劑（如azathioprine、6-MP、cyclosporine、tacrolimus），治療無效時，下一步選擇為手術治療"],"answer":3,"image":""},{"id":"md3-113-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"病人因胃潰瘍需要接受藥物治療，關於胃藥之機轉與使用下列何者錯誤？","options":["(A) 制酸劑（antacid）透過酸鹼中和之方法提高胃部酸鹼值","(B) 第二型組織胺受體阻斷劑（H2 receptor antagonist）透過抑制胃部chief cell上之histamine receptor達到阻斷胃酸之功能","(C) ++ 氫離子幫浦抑制劑（proton pump inhibitor）以共價鍵結方式不可逆的結合於受體H/K-ATPase上","(D) 病人由於胃食道逆流使用氫離子幫浦抑制劑（proton pump inhibitor）停藥後可能產生反彈性胃酸過度分泌"],"answer":1,"image":""},{"id":"md3-113-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"病房中的一位56歲女性病人突然開始解大量黑便及頭暈，您是值班醫師前去處理病情。下列急性上消化道出血之處理方式，何者最不恰當？","options":["(A) 詳細詢問病人之病史，以了解病人可能為何處出血","(B) 評估病人之心跳與血壓，以得知是否為臨床上有意義的嚴重出血","(C) 馬上抽血評估血色素。若血色素數值正常，則可以判斷病人無嚴重出血的可能性","(D) 病人接受內視鏡檢查，若發現有正在出血之潰瘍或潰瘍處可見血管，則內視鏡止血術可降低病人之再出血、住院天數及死亡率"],"answer":2,"image":""},{"id":"md3-113-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"關於胃腸道吸收（absorption），下列敘述何者正確？","options":["(A) 鐵與鈣的吸收主要在上端小腸","(B) 膽酸的吸收主要在大腸","(C) 維生素A、D、E、K為水溶性維生素","(D) 分泌型腹瀉（secretory diarrhea）在禁食24小時後腹瀉會減輕"],"answer":0,"image":""},{"id":"md3-113-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"關於急性腸阻塞（acute intestinal obstruction）之敘述，下列何者錯誤？","options":["(A) 小腸阻塞比起大腸阻塞常見","(B) 手術後沾黏是小腸阻塞的常見原因","(C) 腸扭轉（volvulus）是大腸阻塞最常見的原因","(D) 乙狀結腸扭轉引發之大腸阻塞可以內視鏡置放引流管減壓（decompression）"],"answer":2,"image":""},{"id":"md3-113-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"一般而言，癌症的確診都需要病理切片。由於肝細胞癌（hepatocellular carcinoma, HCC）有其特殊性，所以國際上的診斷標準除了切片外，如果在影像學上有典型的特徵，也可以不必做肝臟切片就符合肝細胞癌的診斷條件。下列何者情況即使沒有病理切片診斷，也符合肝細胞癌的診斷條件？","options":["(A) 在脂肪肝的背景下，有一顆3公分的肝腫瘤，在電腦斷層動脈相中影像增強（arterial enhancement），靜脈相中顯影劑沖失（venous washout）","(B) 肝硬化病人，不過沒有B型肝炎也沒有C型肝炎，有一顆5公分的肝腫瘤，在電腦斷層動脈相中影像增強（arterial enhancement），靜脈相中顯影劑沖失（venous washout）","(C) B型肝炎帶原者沒有肝硬化，有一顆2公分的肝腫瘤，在電腦斷層動脈相及靜脈相中，都具有影像增強（arterial enhancement）","(D) 慢性C型肝炎病人併有肝硬化，有一顆4公分的肝腫瘤，在電腦斷層動脈相中無影像增強（no arterial enhancement），在靜脈相中為呈現影像強度降低（hypodense）"],"answer":1,"image":""},{"id":"md3-113-1-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"下列何種族群，最不需要加強篩檢B型肝炎？","options":["(A) 懷孕婦女","(B) 女女性行為者（women who have sex with women, WSW）","(C) C型肝炎感染患者","(D) 接受免疫抑制劑治療的患者"],"answer":1,"image":""},{"id":"md3-113-1-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"55歲男性肝硬化病人，併發腹水與下肢水腫，抽血檢查血中鈉離子：130 mEq/L，白蛋白：2.6 g/dL。下列那一種處置對這位病人較恰當？","options":["(A) 每天限水1.5 L，每天補充鈉離子4 g，furosemide 40 mg/day + spironolactone 100 mg/day","(B) 每天限水1.5 L，每天限制鈉離子攝取2 g，furosemide 40 mg/day + spironolactone 100 mg/day","(C) 每天intravenous normal saline 2 L，furosemide 40 mg/day + spironolactone 100 mg/day","(D) 每天intravenous normal saline 2 L，每天補充鈉離子4 g"],"answer":1,"image":""},{"id":"md3-113-1-24","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"73歲男性，患有糖尿病、高血壓、慢性腎病，無呼吸困難、噁心、嘔吐、水腫之症狀，抽血檢驗發現血中2+ creatinine 9.8 mg/dL、腎絲球過濾率（eGFR）6 mL/min/1.73 m、K 4.2 mEq/L、血色素10.8 g/dL，病人計畫接受長期血液透析治療，預先建立血液透析血管通路（hemodialysis vascular access），下列何種為優先選擇？","options":["(A) 動靜脈瘻管（arteriovenous fistula）","(B) 動靜脈植入型搭橋瘻管（arteriovenous graft）","(C) 雙腔導管（double lumen catheter）","(D) 雙腔隧道式導管（double lumen tunneled catheter）"],"answer":0,"image":""},{"id":"md3-113-1-25","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"下列有關急性間質性腎炎（acute interstitial nephritis）的敘述，何者錯誤？","options":["(A) 發燒、紅疹及嗜伊紅性白血球增加只發生在少數因藥物過敏所致的病人","(B) 尿液檢驗可見膿尿，白血球圓柱體及顯微鏡下血尿","(C) 若病史夠清楚，通常不需要腎臟切片即可診斷","(D) 類固醇治療可加速腎功能恢復，並改善長期腎臟存活"],"answer":3,"image":""},{"id":"md3-113-1-26","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"下列何者不是成人逆流性腎病變（reflux nephropathy）的典型特徵？","options":["(A) 病人小時候常有尿床或重複泌尿道感染史","(B) 若演變成慢性腎臟病，尿液僅輕微蛋白尿無異常沉渣","(C) 超音波可見腎臟呈對稱性萎縮及不規則狀輪廓","(D) 積極控制血壓可減緩腎功能惡化的速度"],"answer":2,"image":""},{"id":"md3-113-1-27","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"下列何種臨床情境最不須將雙側尿路阻塞納入鑑別診斷之列？","options":["(A) acute kidney injury accompanied by anuria","(B) renal failure with postural hypotension","(C) azotemia with metabolic acidosis and hyperkalemia","(D) presence of acquired nephrogenic diabetes insipidus"],"answer":1,"image":""},{"id":"md3-113-1-28","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"一位26歲女性，有多年systemic lupus erythematosus（SLE）病史，但沒有規則追蹤。最近二週出現喘、水腫、尿量減少，體重增加近5公斤。安排住院後入院時，血壓160/94 mmHg，抽血檢驗結果如下：BUN 110 mg/dL，creatinine 4.0 mg/dL，urine protein（4+）。因為腎臟功能惡化，安排病人接受腎臟切片檢查（renal biopsy），切片下呈現狼瘡性腎炎（lupus nephritis），下列何者病理變化最不可能出現在該切片中？","options":["(A) diffuse proliferative nephritis with diffuse subendothelial deposit","(B) focal segmental glomerulosclerosis","(C) membranous glomerulonephritis with subepithelial immune complex deposit","(D) global endocapillary proliferation, crescent formation"],"answer":1,"image":""},{"id":"md3-113-1-29","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"一位40歲病人原本腎功能正常，現其血清creatinine在48小時內上升至2.5 mg/dL，下列何種狀況最可判斷此病人傾向內生性急性腎損傷（intrinsic acute kidney injury）？","options":["(A) 尿鈉排出比例（fractional excretion of sodium, FeNa）＜1%","(B) 尿液滲透壓＞500 mOsm/L","(C) 血液尿素與肌酸酐比率（BUN-to-creatinine ratio）＞20","(D) 尿沉澱物可見顆粒性圓柱體（granular cast）"],"answer":3,"image":""},{"id":"md3-113-1-30","subject":"md3","topic":"內科-腎臟","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"造成慢性腎臟病貧血的原因，下列何者錯誤？","options":["(A) 病患身體所製造之紅血球生成素（erythropoietin）過多","(B) 病患體內鐵質利用不良","(C) 病患合併出血傾向（bleeding diathesis）","(D) 病患處於慢性發炎狀態（chronic inflammation）"],"answer":0,"image":""},{"id":"md3-113-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"關於calcium pyrophosphate deposition（CPPD）disease的描述，下列何者最適當？","options":["(A) CPPD disease常被稱為假性痛風（pseudogout）而有類似痛風的臨床症狀，較常發生在年輕人","(B) 會有含calcium的結晶沉澱在關節，但此病與primary hyperparathyroidism沒有關係","(C) 常侵犯膝關節，關節液的偏光顯微鏡分析可發現菱形（rhomboid）或類似棒狀（rod-like）的正偏光結晶","(D) 關節X光可能會看到chondrocalcinosis，但此現象在痛風關節炎（gouty arthritis）也常被發現"],"answer":2,"image":""},{"id":"md3-113-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"有關diffuse cutaneous systemic sclerosis與limited cutaneous systemic sclerosis常見臨床表徵比較，下列敘述何者最適當？","options":["(A) joint contractures較常出現在limited cutaneous systemic sclerosis病人","(B) 快速進展的間質性肺炎（interstitial lung disease）較常出現在diffuse cutaneous systemic sclerosis病人","(C) calcinosis cutis較常出現在diffuse cutaneous systemic sclerosis病人","(D) scleroderma renal crisis較常出現在limited cutaneous systemic sclerosis病人"],"answer":1,"image":""},{"id":"md3-113-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"有關giant cell arteritis，下列敘述何者最適當？","options":["(A) 大多發生在小於50歲的病人","(B) 男性比女性常見","(C) 可以用tocilizumab治療","(D) 約5%病人會合併polymyalgia rheumatica"],"answer":2,"image":""},{"id":"md3-113-1-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"小李是一位計程車司機，近6個月來每到傍晚身上就開始出現奇癢的膨疹（wheals）。醫師幫小李驗血檢查沒有發現什麼特別的疾病，也沒有驗到過敏原，對於小李的治療，下列何者最適當？","options":["(A) desloratadine 5 mg daily","(B) diphenhydramine 50 mg every 6 hours daily","(C) prednisolone 0.5 mg/kg daily","(D) topical clobetasol as-needed"],"answer":0,"image":""},{"id":"md3-113-1-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"22歲蔡小姐，因為反覆發燒，多處關節腫痛以及下肢水腫約一個月而入院治療。初步抽血檢驗顯示33 WBC=3,200/mm，Hb=10 g/dL，platelet=56,000/mm，urine protein/creatinine ratio=3,800 mg/g，胸部X光發現兩側肋膜皆有少量積水。下列何項處置對疾病確診最無幫助？","options":["(A) 檢驗血中抗核抗體（antinuclear antibodies, ANA）","(B) 檢驗血中抗磷脂質抗體（anti-phospholipid antibodies）","(C) 安排肺部電腦斷層檢查","(D) 安排腎臟切片檢查"],"answer":2,"image":""},{"id":"md3-113-1-36","subject":"md3","topic":"內科-腫瘤","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"一位第四期癌症病人有噁心、嘔吐、頭暈及其他神經症狀，且證實有腦部轉移，下列腦部轉移的原發部位何者機率最低？","options":["(A) 肺癌","(B) 乳癌","(C) 前列腺癌","(D) 黑色素癌"],"answer":2,"image":""},{"id":"md3-113-1-37","subject":"md3","topic":"內科-腫瘤","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"一位45歲婦女因下腹部疼痛，至醫院就診，後經診斷為卵巢上皮細胞癌（epithelial ovarian cancer），關於卵巢上皮細胞癌治療之敘述，下列何者錯誤？","options":["(A) optimal resection定義為腫瘤切除手術後，殘餘腫瘤直徑介於1到2公分之間","(B) BRCA1或BRCA2可能與卵巢上皮細胞癌發生有關","(C) paclitaxel和carboplatin是卵巢上皮細胞癌常用的有效輔助性化學藥物","(D) histologic grade與預後相關"],"answer":0,"image":""},{"id":"md3-113-1-38","subject":"md3","topic":"內科-腫瘤","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"乳癌標靶治療發展日新月異，目前有很多標靶藥物上市，可以幫助臨床醫師治療病人，下列標靶治療藥物與相對應的主要分子標靶配對何者錯誤？","options":["(A) Pertuzumab—抗HER2抗體","(B) Denosumab—抗RANK Ligand抗體","(C) Ribociclib—CDK4/6抑制劑","(D) Everolimus—EGFR抑制劑"],"answer":3,"image":""},{"id":"md3-113-1-39","subject":"md3","topic":"內科-腫瘤","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"下列有關癌症治療引起副作用的敘述，何者最不恰當？","options":["(A) 預防tumor lysis syndrome最重要的方式是urine alkalization","(B) 輸注rituximab時發生的fever、chill和bronchospasm，是一種infusion reaction","(C) 使用chimeric antigen receptor（CAR）-engineered T cell therapy重要的急性毒性（acute toxicity）之一是cytokine release syndrome","(D) 某些化學治療藥物可能引起過敏反應（hypersensitivity reaction），如：taxane類藥物的過敏反應大多於第一或第二療程發生；而platinum類藥物的過敏反應則常於長期暴露後發生"],"answer":0,"image":""},{"id":"md3-113-1-40","subject":"md3","topic":"內科-腫瘤","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"惡性淋巴瘤病患接受rituximab治療時，下列何種疾病發生的機會最可能增加？","options":["(A) 潰瘍性大腸炎","(B) 類風濕性關節炎","(C) 腎病症候群","(D) 進行多發性白質腦病變（progressive multifocal leukoencephalopathy）"],"answer":3,"image":""},{"id":"md3-113-1-41","subject":"md3","topic":"內科-血液","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"下列有關acute lymphoblastic leukemia之治療的敘述，何者最不適當？","options":["(A) 以現代的化學治療處方，初次治療之完全緩解率（complete remission rate）可以高達80%以上","(B) 維持治療（maintenance therapy）通常包含6-mercaptopurine與methotrexate，且長達2年至2年半","(C) 對於帶有Philadelphia chromosome之acute lymphoblastic leukemia的維持治療（maintenance therapy），建議加上tyrosine kinase inhibitor","(D) 對於帶有Philadelphia chromosome之acute lymphoblastic leukemia之中樞神經的預防與治療，imatinib是理想選項"],"answer":3,"image":""},{"id":"md3-113-1-42","subject":"md3","topic":"內科-血液","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"下列何者不是一般急性出血後貧血（acute post hemorrhagic anemia）的特徵？","options":["(A) 初期病人可能有休克但只有輕度的貧血","(B) 在出血過多導致休克經由optimal fluid resuscitation矯正後，血液相會有血球濃缩（hemoconcentration）","(C) 周邊血reticulocyte數量上升","(D) 血清中erythropoietin值上升"],"answer":1,"image":""},{"id":"md3-113-1-43","subject":"md3","topic":"內科-血液","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"下列何者最不可能是骨髓增生性腫瘤（myeloproliferative neoplasm, MPN）常見產生突變的基因？","options":["(A) JAK2","(B) MPL","(C) CALR","(D) FLT-3"],"answer":3,"image":""},{"id":"md3-113-1-44","subject":"md3","topic":"內科-血液","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"有關多發性骨髓瘤（multiple myeloma）的敘述，下列何者最不適當？","options":["(A) 病人因免疫力低，常常容易受感染，最常見的感染病原菌之一是Streptococcus pneumoniae","(B) 病人常有骨骼疼痛的表現","(C) 病人常有高血鈣症","(D) 偵測病人骨骼的病灶，用同位素骨掃描（bone scan）比用X光（bone radiograph）更精確"],"answer":3,"image":""},{"id":"md3-113-1-45","subject":"md3","topic":"內科-胸腔","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"有關interstitial lung disease（ILD）的治療，下列何者最為適當？","options":["(A) 對於idiopathic pulmonary fibrosis病人，免疫抑制治療可以減少死亡率","(B) cryptogenic organizing pneumonia使用類固醇可以改善臨床症狀","(C) anti-fibrotic therapy（pirfenidone and nintedanib）對於idiopathic pulmonary fibrosis病人死亡率沒有改善","(D) connective tissue disease-associated ILDs病人不可以併用免疫抑制劑及抗纖維化治療"],"answer":1,"image":""},{"id":"md3-113-1-46","subject":"md3","topic":"內科-胸腔","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"下列何種指標不是阻塞型呼吸中止症候群（obstructive sleep apnea syndrome）嚴重度的指標？","options":["(A) 睡眠檢查apnea-hypopnea index（AHI）","(B) 夜間血氧濃度下降程度","(C) BMI數值","(D) 白天嗜睡情形"],"answer":2,"image":""},{"id":"md3-113-1-47","subject":"md3","topic":"內科-感染","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"18歲男性，過去身體健康良好。此次因發燒及咳嗽數天到門診就醫，其胸部X光檢查呈現雙下肺野的肺炎，3血液白血球數目為7.91 × 10/μL。下列何者是最可能的致病菌？","options":["(A) 金黃色葡萄球菌（Staphylococcus aureus）","(B) 黴漿菌（Mycoplasma pneumoniae）","(C) 肺炎克雷伯氏菌（Klebsiella pneumoniae）","(D) 綠膿桿菌（Pseudomonas aeruginosa）"],"answer":1,"image":""},{"id":"md3-113-1-48","subject":"md3","topic":"內科-感染","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"有關敗血症的治療，下列敘述何者最不適當？","options":["(A) 抗生素使用非常重要，選擇合適的抗生素立即給與，可以提高存活率","(B) 敗血症病人有血液酸化的情況，因此，給與碳酸氫鈉維持血液中酸鹼平衡是治療的首要目標","(C) 給與靜脈輸液，維持足夠器官灌流是治療的目標之一","(D) 當血壓太低，給與靜脈輸液後血壓仍低，應考慮給與升壓劑（vasopressor）"],"answer":1,"image":""},{"id":"md3-113-1-49","subject":"md3","topic":"內科-胸腔","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"急性低血氧性呼吸衰竭（acute hypoxemic respiratory failure），若胸部X光片顯示無異常，則鑑別診斷可包括：①肺栓塞 ②右至左分流（right-to-left shunt） ③氣胸 ④肝硬化 ⑤氣喘 ⑥肺水腫","options":["(A) ①②③⑤","(B) ②③④⑤","(C) ①②④⑤","(D) ①③④⑥"],"answer":2,"image":""},{"id":"md3-113-1-50","subject":"md3","topic":"內科-胸腔","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"下列何種檢查在診斷氣喘時最有價值？","options":["(A) 動脈血液氣體分析","(B) 胸部X光片","(C) 肺功能檢查","(D) 心電圖檢查"],"answer":2,"image":""},{"id":"md3-113-1-51","subject":"md3","topic":"內科-胸腔","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"30歲男性因咳嗽有痰數月而就醫，其胸部X光檢查如附圖。下列何者為最可能的診斷？","options":["(A) 肺結核","(B) 肺膿瘍","(C) 肺炎","(D) 肺癌"],"answer":0,"image":"md3-113-1-51.jpeg"},{"id":"md3-113-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"嗜鉻細胞瘤源自於交感或副交感神經系統，雖然比例上只占高血壓病患的0.1%，但如果沒有及時診斷，對於心臟及腦血管病變，是個重大的威脅。下列有關嗜鉻細胞瘤的診斷及表現，何者錯誤？","options":["(A) 嗜鉻細胞瘤可能的臨床表現包括：頭痛、焦慮及恐慌發作、多尿、姿勢性低血壓及血糖上升","(B) 正確診斷嗜鉻細胞瘤應該基於：病患之生化檢查顯示兒茶酚胺（catecholamine）過量以及影像學檢查腫瘤之定位，兩者同樣重要","(C) 傳統上提及嗜鉻細胞瘤的\"Rule of ten\"包括：10%為單側腎上腺腫瘤（unilateral）、10%為惡性嗜鉻細胞瘤（malignant pheochromocytoma），以及10%為腎上腺外之腫瘤（extraadrenal）","(D) 影像診斷學上，在施打顯影劑之後，電腦斷層（CT）及磁振造影（MRI）在診斷嗜鉻細胞瘤之敏感度是類似的"],"answer":2,"image":""},{"id":"md3-113-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"淋巴球性腦垂體炎（lymphocytic hypophysitis）是免疫功能干擾到內分泌系統的疾病，下列有關淋巴球性腦垂體炎的敘述，何者錯誤？","options":["(A) 本項疾病常見於剛生產後之女性，臨床上常以高泌乳激素血症（hyperprolactinemia）表現","(B) 磁振造影（MRI）檢查會發現空蝶鞍（empty sella）之影像學表現","(C) 此種病患，可能會因腦下垂體之病況，表現頭痛及視覺異常等症狀","(D) 淋巴球性腦垂體炎在經過類固醇治療後，因炎性反應緩解，腦下垂體之功能可能可以恢復正常"],"answer":1,"image":""},{"id":"md3-113-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"下列有關庫欣氏症候群（Cushing's syndrome）之臨床徵象描述，何者錯誤？","options":["(A) 中心性肥胖及水牛肩（buffalo hump）","(B) 遠端肌肉無力（distal myopathy），造成爬樓梯之困難","(C) 容易感染及血中白血球數明顯增加","(D) 增加肺栓塞及深部靜脈栓塞之風險"],"answer":1,"image":""},{"id":"md3-113-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"下列有關甲狀腺功能檢查之敘述，何者最不適當？","options":["(A) 自體免疫甲狀腺疾病之診斷，可以藉由測量甲狀腺球蛋白抗體及甲狀腺過氧化酶抗體得知","(B) 病患出現甲狀腺抗體時，比較容易發生甲狀腺機能異常","(C) 所有的甲狀腺毒症（thyrotoxicosis）的病患，血清中之甲狀腺球蛋白都會呈現上升的現象，但是服用甲狀腺素造成之甲狀腺亢進偽症（thyrotoxicosis factitia）是例外","(D) 單獨測量促甲狀腺素（thyrotropin, TSH），可以鑑別診斷病患因腦下垂體疾病造成的甲狀腺機能異常"],"answer":3,"image":""},{"id":"md3-113-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"有關第二型糖尿病（type 2 diabetes mellitus）的敘述，下列何者錯誤？","options":["(A) 第二型糖尿病有程度不一的胰島素阻抗（insulin resistance）","(B) 第二型糖尿病有程度不一的胰島素分泌減少","(C) 第二型糖尿病有程度不一的肝臟葡萄糖新生（gluconeogenesis）增加","(D) 原屬非胰島素依賴型的第二型糖尿病人，一旦須注射胰島素，就轉變成胰島素依賴型的第一型糖尿病人"],"answer":3,"image":""},{"id":"md3-113-1-57","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"下列有關血糖調控之敘述，何者最不適當？","options":["(A) 診斷低血糖（hypoglycemia）的Whipple's triad，包括血糖恢復正常後，症狀改善","(B) 一般空腹血漿血糖（fasting plasma glucose）的正常值的下限是50 mg/dL","(C) 肝臟和腎臟均有葡萄糖新生作用（gluconeogenesis）","(D) 血糖降低時，在胰島素分泌減少後，升糖素（glucagon）分泌跟著上升"],"answer":1,"image":""},{"id":"md3-113-1-58","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"下列有關高尿酸血症之敘述，何者最不適當？","options":["(A) 代謝症候群（metabolic syndrome）易伴有高尿酸血症（hyperuricemia）","(B) 急性血中尿酸（uric acid）濃度大幅上升，可引起急性腎衰竭","(C) 長期血中尿酸（uric acid）濃度偏高，可造成腎結石","(D) 高尿酸血症（hyperuricemia）病患，即使無症狀，一律應積極給與降尿酸藥物治療"],"answer":3,"image":""},{"id":"md3-113-1-59","subject":"md3","topic":"內科-感染","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"有關醫療照護相關感染肺炎致病原之敘述，下列敘述何者最不適當？","options":["(A) 口咽移生之抗藥性菌嗆咳，是發生醫療照護相關感染肺炎的危險因子","(B) 住院4天內發生早發性（early onset）醫療照護相關感染肺炎，致病原主要為社區性病原，如肺炎鏈球菌（Streptococcus pneumoniae）或嗜血流感桿菌（Haemophilus influenzae）","(C) 若培養未發現特定的抗藥性致病原，使用抗生素短期治療（8天）能減少病人後續抗藥性菌移生","(D) 床頭抬高15～20度是可以減少發生醫療照護相關感染肺炎的標準作業"],"answer":3,"image":""},{"id":"md3-113-1-60","subject":"md3","topic":"內科-感染","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"下列何種抗生素懷孕婦女應避免使用？","options":["(A) azithromycin","(B) clindamycin","(C) erythromycin","(D) tetracycline"],"answer":3,"image":""},{"id":"md3-113-1-61","subject":"md3","topic":"內科-感染","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"有關結核性腦膜炎的敘述，下列何者錯誤？","options":["(A) 腦脊髓液檢查通常會有淋巴球增多lymphocytic pleocytosis（10～500 cells/μL）","(B) 腦脊髓液檢查通常葡萄糖濃度會下降（20～40 mg/dL）","(C) 文獻報告少於一半的病人，腦脊髓液檢查acid-fast stain會呈陽性","(D) 腦脊髓液進行結核菌聚合酶鏈鎖反應（polymerase chain reaction, PCR）已經取代培養，成為最主要診斷工具"],"answer":3,"image":""},{"id":"md3-113-1-62","subject":"md3","topic":"內科-感染","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"80歲病人，有慢性C型肝炎相關的肝硬化病史，因為腹痛、腹瀉和發燒住院。住院後，血壓低，有黃疸，糞便和血液培養均長出Campylobacter jejuni。在藥物敏感檢測報告出來前，下列何者是最適當的抗生素治療？","options":["(A) trimethoprim-sulfamethoxazole","(B) metronidazole","(C) ampicillin","(D) carbapenem"],"answer":3,"image":""},{"id":"md3-113-1-63","subject":"md3","topic":"內科-感染","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"關於人類免疫不全病毒（HIV）的特徵，下列敘述何者錯誤？","options":["(A) HIV藉由與帶有CD8受器（receptor）和CCR5或者CXCR4的輔助受器（co-receptor）結合，進入人類CD8 T淋巴球","(B) HIV是RNA病毒，複製過程中需要將RNA反轉錄（reverse transcription）為DNA","(C) 在淋巴球內的複製過程中，HIV的DNA會進入細胞核並嵌入宿主細胞的DNA中","(D) 異性間不安全性行為，依然是全球HIV感染最常見的傳染途徑"],"answer":0,"image":""},{"id":"md3-113-1-64","subject":"md3","topic":"內科-感染","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"56歲的女性病人，主訴為右腳紅腫熱痛，已經在診所接受了一週的口服第一代cephalosporin藥物治療，因為沒有改善來到門診。病史詢問知道病人有糖尿病，已使用口服血糖藥物治療十多年，但是不知道自己血糖控制的情形。病人在廚房擔任清潔工作，長時間穿著膠鞋且常接觸到水，身體診察時發現右足底有一個潰瘍及黃綠色膿狀分泌物，依據上述，下列何者錯誤？","options":["(A) 如果懷疑骨髓炎，可以採取probe-to-bone的測試，即以金屬探針穿刺傷口處，若可觸及骨頭，則高度懷疑為骨髓炎","(B) 進一步可用磁振造影檢查（MRI）診斷，其敏感度高於X光檢查","(C) 傷口檢體（wound swab）與骨頭切片培養的結果通常是一致的，故骨頭切片培養是不必要的處置","(D) 因有綠膿桿菌感染風險，可考慮使用piperacillin-tazobactam或cefepime"],"answer":2,"image":""},{"id":"md3-113-1-65","subject":"md3","topic":"內科-感染","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"當皮膚軟組織感染合併水泡（vesicles or bullae），下列敘述何者錯誤？","options":["(A) coxsackievirus常好發於小孩，小水泡多分布於手腳或嘴巴","(B) Vibrio vulnificus的危險因子為接觸淡水","(C) staphylococcal scalded skin syndrome或toxic epidermal necrolysis不容易於外觀分辨，切片可幫助鑑別診斷","(D) 當水痘為紅黑色，紅腫區域快速蔓延或合併感染處感覺異常（anesthesia），應把壞死性筋膜炎列入鑑別診斷"],"answer":1,"image":""},{"id":"md3-113-1-66","subject":"md3","topic":"家醫-行為與社區醫學","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"關於Berlin等人所提出的「LEARN」看診模式，其所代表涵義，下列敘述何者正確？","options":["(A) L：Label，你覺得你是得了什麼病？","(B) E：Effect，這個疾病對於你的生活會帶來什麼不便？","(C) A：Affect，這個疾病對於你的情緒會造成什麼影響？","(D) R：Recommend，給予最佳的治療建議"],"answer":3,"image":""},{"id":"md3-113-1-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"關於失智症（dementia）的敘述，下列何者正確？","options":["(A) 血管性失智症是最常見的失智症類型","(B) 焦慮症是引起失智症最常見可回復的疾病","(C) 目前全臺灣各縣市都有失智共同照護中心，提供失智症病患服務","(D) 血管性失智症僅須控制好相關危險因子，使用乙醯膽鹼酯酶抑制劑（acetylcholinesterase inhibitors, AChEIs）沒有助益"],"answer":2,"image":""},{"id":"md3-113-1-68","subject":"md3","topic":"家醫-行為與社區醫學","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"60歲婦女獨自來家庭醫學科門診，主訴左側臉部麻及左側身體疼痛已經兩年，看過多家醫院且做過腦部核磁共振等多項檢查，均無異常發現且治療效果不佳。病史詢問發現其先生兩年前過世，她很擔心會發生腦中風成為子女負擔。初步診察並無異常發現，認知功能與判斷力正常，下一步處置何者最為適當？","options":["(A) 安排正子攝影進一步確認","(B) 轉介神經科醫師評估","(C) 轉介精神科醫師評估","(D) 進行家庭功能評估"],"answer":3,"image":""},{"id":"md3-113-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"關於預防醫學（preventive medicine）三段五級中各階段的內容，下列敘述何者正確？","options":["(A) 「早期發現早期治療」屬初段預防（primary prevention）","(B) 「注射疫苗預防流感」屬次段預防（secondary prevention）","(C) 「高血壓病人服用降血壓藥物以減少併發症」屬三段預防（tertiary prevention）","(D) 「衛生教育」屬次段預防（secondary prevention）"],"answer":2,"image":""},{"id":"md3-113-1-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"2一位身體質量指數達到33.2 kg/m的35歲已婚女性，由先生陪同來到體重管理門診諮詢，下列敘述何者最正確？","options":["(A) 此個案目前對於改變體重應該已經進入跨理論模式（transtheoretical model）之認知期（contemplation）","(B) 此個案應可開始給予認知行為治療（cognitive behavior therapy）並配合飲食與運動的介入","(C) 此個案符合衛生福利部規範得以使用減重藥物治療","(D) 跨理論模式運用在體重管理已證實具有長期的效果"],"answer":2,"image":""},{"id":"md3-113-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"在門診醫病會談中，離開診間前的提問（Hand-on-the-Doorknob Syndrome）代表何種潛在意思？","options":["(A) 醫師「不想處理困難病人（difficult patient）」的行為表現","(B) 病人「害怕醫師會拒絕其所提出問題但又想提問」的行為表現","(C) 病人「不想回答醫師提問而希望能趕快離開診間」的行為表現","(D) 是身體化症狀（somatization）病人要求更多檢查的行為表現"],"answer":1,"image":""},{"id":"md3-113-1-72","subject":"md3","topic":"內科-胸腔","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"有關煤礦工人塵肺症（coal workers pneumoconiosis, CWP）與矽肺症（silicosis）臨床表現的比較，煤礦工人塵肺症之特徵，下列敘述何者正確？","options":["(A) 罹患肺癌之風險較高","(B) 易併有硬皮症（scleroderma）","(C) 易有肺門淋巴結鈣化現象","(D) 罹患肺結核或黴菌感染之風險較低"],"answer":3,"image":""},{"id":"md3-113-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"下列關於末期病人疼痛控制的敘述，何者錯誤？","options":["(A) 疼痛的評估應包括生理、心理、社會及靈性層面","(B) 針劑止痛的效果最為迅速，因此為末期病人止痛給藥途徑的首選","(C) 若末期病人的疼痛屬於本體痛（nociceptive pain），對嗎啡類藥物反應良好","(D) 骨頭轉移的疼痛，以非類固醇類抗發炎藥物（non-steroidal anti-inflammatory drug）為首選"],"answer":1,"image":""},{"id":"md3-113-1-74","subject":"md3","topic":"影像醫學","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"下列何者最有機會出現腹部正中央的鈣化（central abdominal calcification）？","options":["(A) 慢性胰臟炎（chronic pancreatitis）","(B) 膀胱結石（bladder stone）","(C) 臀部因藥物注射產生的鈣化（calcifications in buttocks from injections）","(D) 髂靜脈或股靜脈的鈣化（calcifications in iliac or femoral vessels）"],"answer":0,"image":""},{"id":"md3-113-1-75","subject":"md3","topic":"影像醫學","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"有關肝內血管瘤（hepatic hemangioma）的影像發現，下列何者為最典型之影像特徵？","options":["(A) 靜脈注射CT影像上呈現早期顯影劑流失（early wash-out pattern）","(B) 靜脈注射CT影像上呈現周圍結節狀顯影及中央顯影劑流入（peripheral nodular enhancement with central fill-in pattern）","(C) 腫瘤於磁振造影T1序列出現高訊號（hyperintense nodule on T1WI）","(D) 腫瘤於磁振造影T2序列出現低訊號（hypointense nodule on T2WI）"],"answer":1,"image":""},{"id":"md3-113-1-76","subject":"md3","topic":"急診醫學","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"30歲女性從火場救出，體重50公斤，全身有一度燒燙傷（30% Body Surface Area, BSA）、二度燒燙傷（20% BSA）、三度燒燙傷（5% BSA），依據Parkland formula，前8小時須給與多少林格氏（lactated Ringer's）輸液？","options":["(A) 2,500 mL","(B) 3,500 mL","(C) 4,500 mL","(D) 5,500 mL"],"answer":0,"image":""},{"id":"md3-113-1-77","subject":"md3","topic":"急診醫學","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"70歲男性因胸痛、冒冷汗、呼吸急促被送至急診，心電圖如下所示，關於此病人之處置何者最不適當？","options":["(A) 胸痛病人最好在到急診後10分鐘內完成心電圖檢查","(B) 立即加做右側心電圖（right side ECG）","(C) 床邊心臟超音波可評估主動脈根部（aortic root）是否有主動脈剝離（aortic dissection）","(D) 若心肌酵素正常，則可排除心肌梗塞，須尋找其他胸痛原因"],"answer":3,"image":"md3-113-1-77.jpeg"},{"id":"md3-113-1-78","subject":"md3","topic":"家醫-緩和醫學","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"有關末期病人的「緩和治療（palliative care）」，下列敘述何者最不適當？","options":["(A) 在止痛方面，morphine仍是首選，但須注意呼吸抑制等副作用","(B) morphine可以用來減少病人呼吸困難的症狀，起始劑量為需要止痛劑量的雙倍","(C) 皮質類固醇可以改善癌末病人腸道阻塞或顱內壓增高所導致的嘔吐","(D) 對於其他藥物無效的嘔吐，可嘗試用多巴胺拮抗劑（dopamine antagonist）"],"answer":1,"image":""},{"id":"md3-113-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"吳先生84歲，肺癌末期，之前在家中已明確告知太太，病情惡化時不希望接受氣管內管插管，本次因為呼吸急促、意識模糊送至急診，子女討論後，希望能夠插管積極治療，但太太希望遵照病人的意願。針對本案例「不予急救」的議題，下列敘述何者正確？","options":["(A) 因為病人沒有簽署文件，所以應依照家屬的共識來執行","(B) 因為病人有口頭明確表達「不予急救」的意思，家屬應遵照病人意願簽署「不予急救同意書」","(C) 若急診當下已緊急插管，家屬仍無法達成共識，即不得撤除維生醫療","(D) 「不予急救」及「撤除維生醫療」，在安寧緩和醫療條例中適用不同規範"],"answer":1,"image":""},{"id":"md3-113-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"當病人無意識或喪失行為能力，且針對醫療選項先前未表達明確意願時，就需要由代理人做出醫療決定。身為病人的醫療代理人，在代理決定時，下列考量何者應最優先？","options":["(A) 自己若處於病人的境遇，會希望獲得何種治療","(B) 依據醫療團隊說明，選擇對病況最有效的治療","(C) 依據自己對病人的了解，選擇病人最希望的治療","(D) 依據正義原則，選擇多數人最能接受的治療"],"answer":2,"image":""},{"id":"md3-113-2-1","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"葡萄柚汁（grapefruit juice）會抑制代謝酵素cytochrome P450（CYP）3A的活性而使某些藥物的血中濃度 增高，下列何者主要的代謝途徑不是經由CYP3A？","options":["(A) pravastatin","(B) lovastatin","(C) simvastatin","(D) atorvastatin"],"answer":0,"image":""},{"id":"md3-113-2-2","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"關於懷孕期甲狀腺功能變化的敘述，下列何者最不適當？","options":["(A) 懷孕期因雌激素（estrogen）刺激甲狀腺素結合蛋白（thyroxine-binding globulin）製造，導致血中total T3、total T4上升","(B) 第一孕程（first trimester）的中後段，因高濃度人類絨毛膜促性腺激素（human chorionic gonadotropin, hCG）刺激甲狀腺，造成free T3、free T4上升","(C) 對於甲狀腺功能亢進（hyperthyroidism）的患者，在第一孕程（first trimester）使用methimazole可能與胚胎疾病相關聯","(D) 懷孕期以甲狀腺素（thyroxine）治療甲狀腺功能低下（hypothyroidism），目標是維持TSH在正常範圍，常需比懷孕前使用更低的劑量"],"answer":3,"image":""},{"id":"md3-113-2-3","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"70歲男性最近半年喉嚨時常有異物感，吞嚥時較為困難，且後咽部有刺痛感，最近1個月喝水時常發生咳嗽且水從鼻孔流出的現象，病人因此有點害怕吞嚥。關於此病人症狀的描述，不包含下列何者？","options":["(A) transfer dysphagia","(B) aphagia","(C) odynophagia","(D) phagophobia"],"answer":1,"image":""},{"id":"md3-113-2-4","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"有一位75歲男性病患，因最近2日呈嗜睡狀態、進食明顯減少而就醫。病患罹患高血壓與糖尿病25年以上，並因末期腎病接受長期血液透析治療已10年。病人平躺時，將其脖子向前彎，觀察其髖部及膝蓋是否有自主性屈曲（flexion）動作，此項身體診察欲測試的為何？","options":["(A) Babinski's sign","(B) Brudzinski's sign","(C) Kernig's sign","(D) Trendelenburg's sign"],"answer":1,"image":""},{"id":"md3-113-2-5","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"承上題，上述病人經實驗室檢查發現：血鈣2.78 mmol/L、血清白蛋白2.8 g/dL、胸部X光片異常。則此病人高鈣血症最不可能由下列那一原因引起？","options":["(A) 肺結核（tuberculosis）","(B) 肺部鱗狀細胞癌（squamous cell carcinoma）","(C) 次發性副甲狀腺機能亢進（secondary hyperparathyroidism）","(D) 三發性副甲狀腺機能亢進（tertiary hyperparathyroidism）"],"answer":2,"image":""},{"id":"md3-113-2-6","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"下列有關急性心肌梗塞的敘述，何者正確？","options":["(A) ST段上升心肌梗塞（STEMI）之致病冠狀動脈血管病灶，通常都是慢性、無血栓存在之高度狹窄，平時血流供應就不足，在心肌需氧量急遽增加、例如激烈運動時，無法維持心肌細胞需求而造成壞死","(B) ST段上升心肌梗塞（STEMI）若不及時恢復心肌灌流，所有病人心電圖最後都會出現Q波","(C) 第一型、自發性心肌梗塞，連續心肌酶cardiac troponin監測，不會有升高至大於99百分位（99th percentile）參考值上限（upper reference limit）","(D) 第五型心肌梗塞，連續心肌酶cardiac troponin監測，應該至少有一次升高至大於99百分位（99th percentile）參考值上限（upper reference limit）之十倍"],"answer":3,"image":""},{"id":"md3-113-2-7","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"下列有關成人先天性心臟病之敘述，何者正確？","options":["(A) 心房中隔缺損（atrial septal defect, ASD）為常見之成人先天性心臟病之一，因存在「左往右分流（left-to-right shunt）」，因此右心室擴大，且可能產生肺動脈高壓","(B) Ebstein氏異常（Ebstein anomaly）患者，因先天二尖瓣環較正常人為低而更靠近心尖部，因此常有反流現象造成左心房擴大","(C) 部分肺靜脈回流異常（partial anomalous pulmonary venous return, PAPVR）因終究會造成肺動脈高壓，因此經確診後應儘早進行外科手術治療","(D) 心室中隔缺損（ventricular septal defect, VSD）因存在高壓力差，所以無論缺損大小，很少會自行關閉"],"answer":0,"image":""},{"id":"md3-113-2-8","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"下列對於診斷冠狀動脈心臟病的工具的適切性（appropriateness），何者敘述錯誤？","options":["(A) 對於冠狀動脈心臟病接受過支架治療的病人，無論有無症狀，每年定期做壓力摧迫性（stress）測試並非必要","(B) 冠狀動脈心臟病低風險但有典型胸痛症狀的病人，也可考慮運動心電圖壓力摧迫性（stress）測試以評估風險","(C) 冠狀動脈心臟病高風險，在典型胸痛症狀的病人，且無法運動或是無法接受壓力摧迫性（stress）測試時，考慮做心導管檢查是適切的","(D) 具有典型胸痛症狀的病人，無論冠狀動脈心臟病風險高低，電腦斷層鈣化指數都是最合適的檢查工具"],"answer":3,"image":""},{"id":"md3-113-2-9","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"下列何者最不可能造成房室傳導阻斷（atrioventricular block）？","options":["(A) carotid sinus hypersensitivity","(B) Lyme disease","(C) myocardial infarction","(D) cat scratch disease"],"answer":3,"image":""},{"id":"md3-113-2-10","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"一位30歲男性，過去有法洛式四重症（tetralogy of Fallot）病史並開過刀。早上突然因為胸悶至急診，十二導程心電圖顯示left bundle branch block（LBBB）pattern monomorphic ventricular tachycardia（VT）。下列何者最有可能為此患者VT出處（origin）？","options":["(A) right atrium","(B) right ventricle","(C) left atrium","(D) left ventricle"],"answer":1,"image":""},{"id":"md3-113-2-11","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"關於瓣膜性心臟病的描述，下列何者錯誤？","options":["(A) 主動脈瓣二葉畸形（bicuspid aortic valve）伴隨的主動脈病變，主要是發生在主動脈弓","(B) 隨著人口的老化，感染性心內膜炎的發生率升高","(C) 成人發生的主動脈瓣狹窄，主要是因主動脈瓣退化性鈣化造成的","(D) 傳統的動脈粥狀硬化危險因子，常會合併出現在鈣化性主動脈瓣狹窄的進展過程中"],"answer":0,"image":""},{"id":"md3-113-2-12","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"關於心包膜疾病的描述，下列何者正確？","options":["(A) 心包填塞（cardiac tamponade）的三個主要特徵（Beck's triad）為hypotension、pericardial friction rub和jugular venous distention","(B) 心包膜積水在臨床優先考慮的診斷工具為胸部X光","(C) 限制性心肌病（restrictive cardiomyopathy）經常合併有束縮性心包膜炎（constrictive pericarditis）","(D) 心包膜積水的病人一旦發現有心包填塞（cardiac tamponade），此時應緊急施行心包腔穿刺（pericardiocentesis）"],"answer":3,"image":""},{"id":"md3-113-2-13","subject":"md3","topic":"內科-心臟血管","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"有關心衰竭的敘述，下列何者錯誤？","options":["(A) 冠狀動脈疾病通常被認為是心衰竭的重要原因","(B) 心衰竭在家族裡可有群聚效應。例如，親代心衰竭與其後代的左心室質量、心臟大小、收縮功能異常的比例有關","(C) 長期嚴重高血壓也是造成心衰竭的原因之一","(D) 左心室射出分率正常的心衰竭（heart failure with preserved ejection fraction）的病人與左心室射出分率降低的心衰竭（heart failure with reduced ejection fraction）的病人其病因存在相當大的重疊，以目前藥物治療臨床試驗對兩者的效果看起來是相同的"],"answer":3,"image":""},{"id":"md3-113-2-14","subject":"md3","topic":"影像醫學","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"有關心臟核子醫學心肌灌注掃描SPECT的描述，何者錯誤？","options":["(A) 壓力測試核子醫學心肌灌注掃描（SPECT）常用於冠狀動脈疾病評估","(B) 附圖（左）核子醫學心肌灌注掃描（SPECT）呈現可逆的心肌灌注缺損，暗示心肌有缺血","(C) 附圖（右）核子醫學心肌灌注掃描（SPECT）則呈現固定的灌注缺損，通常反映陳舊性心肌梗塞","(D) 核子醫學心肌灌注掃描（SPECT）與電腦斷層冠狀動脈造影相比，對於冠狀動脈疾病的診斷更加敏感，尤其是在多支血管疾病的情況下"],"answer":3,"image":"md3-113-2-14.jpeg"},{"id":"md3-113-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"有關自體免疫肝炎（autoimmune hepatitis）的病理機轉，何者錯誤？","options":["(A) 病理特色為肝細胞的壞死發炎，經常合併纖維化，可能導致肝硬化甚至肝衰竭","(B) 肝臟內調節性T淋巴細胞（regulatory T cells）活性上升","(C) CTLA-4或TNFA*2的基因多形性（polymorphism）和此疾病的發生有關","(D) 病患血清中常出現抗核抗體（antinuclear antibody）、antibody to liver-kidney microsomes（anti- LKM）等自體抗體"],"answer":1,"image":""},{"id":"md3-113-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"一位50歲糖尿病人主訴右上腹痛、發燒5天來醫院求診，電腦斷層圖示如附圖，下列敘述何者錯誤？","options":["(A) 應做血液細菌培養","(B) 安排肝病灶抽吸","(C) 有肝腫瘤可能","(D) Escherichia coli是最常見的感染細菌"],"answer":3,"image":"md3-113-2-16.jpeg"},{"id":"md3-113-2-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"關於腸躁症（irritable bowel syndrome）的敘述何者錯誤？","options":["(A) 糞便檢查常見糞便潛血反應，也可見到糞便中白血球過多","(B) 可以依照症狀分為便秘型、腹瀉型及混合型","(C) 治療上的第一步是同理及支持病人，建議飲食上避免會發酵的寡糖類及豆類食物","(D) 糞便體積增加劑（bulking agent）、止瀉劑、瀉劑、抗腸痙攣藥物、血清素促進劑或拮抗劑、抗憂鬱劑、選擇性血清素回收抑制劑等藥物及益生菌可以用來治療"],"answer":0,"image":""},{"id":"md3-113-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"關於急性腸阻塞（acute intestinal obstruction）的敘述，下列何者錯誤？","options":["(A) 機械性腸阻塞（mechanical obstruction）常見的原因為術後沾黏、腫瘤、疝氣、腸套疊或是腸扭轉，以及發炎性腸病變","(B) 腸功能性阻塞也稱為偽阻塞（pseudo-obstruction），主要是腸道蠕動功能異常引起，常見的原因為脊椎受傷、代謝及電解質異常、使用鴉片類或是抗膽鹼藥物、腸道缺血等","(C) 機械性腸阻塞（mechanical obstruction）阻塞處前端的腸子會擴大，腸管腔內壓力上升，之後導致腸壁水腫及缺氧，最後腸壁會缺血及壞死","(D) 小腸阻塞時，腸音常會先由正常變慢（hypoactive）進展為無腸音（absent bowel sound）。之後因為腸子加速蠕動，會形成高頻（high-pitched）快速蠕動的腸音"],"answer":3,"image":""},{"id":"md3-113-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"幽門螺旋桿菌感染會造成胃潰瘍、胃癌及胃淋巴瘤之風險增加，因此必須選擇適當且高成功率之幽門螺旋桿菌除菌方法。下列除菌療法在clarithromycin抗藥比例小於15%之地區，何者目前不推薦使用？","options":["(A) 七日療程之clarithromycin triple therapy（proton pump inhibitor, clarithromycin, amoxicillin）","(B) 十四日療程之clarithromycin triple therapy（proton pump inhibitor, clarithromycin, amoxicillin）","(C) 十至十四日療程之concomitant therapy（proton pump inhibitor, clarithromycin, amoxicillin, metronidazole）","(D) 十至十四日療程之bismuth quadruple therapy（proton pump inhibitor, bismuth, tetracycline, metronidazole）"],"answer":0,"image":""},{"id":"md3-113-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"對於膽結石引發之急性胰臟炎（acute pancreatitis），下列何者為最重要的治療？","options":["(A) 抗生素","(B) 內視鏡逆行性膽管造影術（endoscopic retrograde cholangiography）確認是否有總膽管結石，若有則進行內視鏡取石","(C) 積極的靜脈輸液","(D) 鼻胃管引流"],"answer":2,"image":""},{"id":"md3-113-2-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"下列何者不是慢性胰臟炎（chronic pancreatitis）常見的併發症？","options":["(A) 慢性腹痛","(B) 糖尿病酮酸中毒症（diabetic ketoacidosis）","(C) 吸收不良（malabsorption）","(D) 膽道狹窄"],"answer":1,"image":""},{"id":"md3-113-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"對於肝硬化病人的胃食道靜脈曲張（gastroesophageal varices）處理，下列敘述何者正確？","options":["(A) 食道靜脈曲張通常是在病人發生腹水之後才會出現","(B) 新診斷的肝硬化病人，大約50%已經有胃食道靜脈曲張","(C) 除了使用內視鏡來做靜脈結紮術（variceal ligation）外，藥物治療並無法有效的預防胃食道靜脈曲張出血","(D) 就算發生胃食道靜脈曲張出血，只要還沒有黃疸，沒有腹水，沒有肝性腦病變，就還不算是肝失代償（decompensation）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第22題一律給分 (原公告答案 B)"},{"id":"md3-113-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"35歲患者有胃部分切除病史，主訴進食後腹痛、腹瀉，約2小時後有頭暈、盜汗症狀，最可能的診斷為何？","options":["(A) afferent loop syndrome","(B) adhesion ileus","(C) dumping syndrome","(D) postvagotomy diarrhea"],"answer":2,"image":""},{"id":"md3-113-2-24","subject":"md3","topic":"內科-腎臟","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"65歲男性，血液透析病人，每次透析開始幾分鐘後，開始右胸痛或背痛，血壓穩定、無心悸、無發燒，隨著透析繼續進行，不適感覺就漸消失，下列何種處置最可能改善其症狀？","options":["(A) 使用無肝素（non-heparin）透析","(B) 增加乾體重","(C) 更換不同材質透析器","(D) 使用鈉離子模式（sodium modeling）透析"],"answer":2,"image":""},{"id":"md3-113-2-25","subject":"md3","topic":"內科-腎臟","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"下列何項處置最不適合治療尿酸性尿路結石？","options":["(A) reduced protein diet","(B) benzbromarone","(C) potassium citrate","(D) febuxostat"],"answer":1,"image":""},{"id":"md3-113-2-26","subject":"md3","topic":"內科-腎臟","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"一名33歲女性，本次因近半年反覆頭暈及容易疲勞而住院。實驗室檢驗：肌酸酐2.3 mg/dL，血紅素7 g/dL（住院前8個月分別為1.4 mg/dL，9 g/dL），白蛋白3.8 g/dL，血鈣2.3 mmol/L，尿酸8.0 mg/dL，血糖98 mg/dL，尿液分析：比重1.012，蛋白尿980 mg/24小時，紅血球0～2/高倍視野，葡萄糖0.27 mg/dL，腎臟超音波右側8.7公分、左側8.9公分，腎臟病理切片如圖。病人最可能的診斷為何？","options":["(A) myeloma cast nephropathy","(B) allergic interstitial nephritis","(C) chronic uric acid nephropathy","(D) aristolochic acid nephropathy"],"answer":3,"image":"md3-113-2-26.jpeg"},{"id":"md3-113-2-27","subject":"md3","topic":"內科-腎臟","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"一位40歲男性，C型肝炎帶原者，定期在門診追蹤。最近一個月來，出現蛋白尿2.5 g/day，脛前與足踝水腫，體重略增加近3公斤，血壓152/92 mmHg。抽血檢查：有血清補體（complement, C3與C4）偏低情形。因為不明原因蛋白尿，安排病人接受腎臟切片檢查（renal biopsy），切片下的病理變化，最有可能是下列何者？","options":["(A) membranous nephropathy（MN）","(B) membranoproliferative glomerulonephritis（MPGN）","(C) focal segmental glomerulosclerosis（FSGS）","(D) Henoch-Schönlein purpura（HSP）"],"answer":1,"image":""},{"id":"md3-113-2-28","subject":"md3","topic":"內科-腎臟","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"有關腎小管–腎絲球回饋機轉（tubuloglomerular feedback, TGF），下列敘述何者正確？","options":["(A) 藉由出球小動脈（efferent arteriole）的反射性血管收縮或擴張來調節腎絲球過濾率（glomerular filtration rate）","(B) 藉由Henle氏環上行枝粗管的管腔膜上緻密斑（macula densa）細胞來感應腎小管內NaCl濃度及液體的流速","(C) 當過高的腎絲球過濾率（glomerular filtration rate）使流經緻密斑（macula densa）的NaCl濃度過高時，會誘發出球小動脈血管收縮使得腎絲球過濾率下降至正常","(D) NaCl再吸收增加時，二磷酸腺苷（adenosine diphosphate, ADP）是緻密斑（macula densa）細胞釋放出來的訊號，來調控腎小管–腎絲球回饋"],"answer":1,"image":""},{"id":"md3-113-2-29","subject":"md3","topic":"內科-腫瘤","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"有關腫瘤溶解症候群（tumor lysis syndrome），下列敘述何者最不適當？","options":["(A) 因為大量腫瘤細胞死亡，細胞內代謝物釋放至血液中導致高尿酸血症、高血鉀症、高血磷症","(B) 由於尿酸結晶會堆積於腎小管，處置上必須給與大量補充體液，並用rasburicase藥物來預防高尿酸血症","(C) 鹼化尿液能夠減少磷酸鈣（calcium phosphate）的沉澱而降低急性腎損傷","(D) 若造成急性腎損傷合併寡尿、高血鉀症，可考慮透析治療"],"answer":2,"image":""},{"id":"md3-113-2-30","subject":"md3","topic":"內科-腎臟","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"下列有關腎移植抗排斥藥物與其副作用之配對，何者錯誤？","options":["(A) 類固醇（corticosteroid）：骨質疏鬆","(B) 環孢靈（cyclosporine）：低尿酸血症","(C) 普樂可復（tacrolimus）：移植後糖尿病","(D) 斥消靈（sirolimus）：蛋白尿"],"answer":1,"image":""},{"id":"md3-113-2-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"關於IgG4-related disease的描述，下列何者最適當？","options":["(A) 可侵犯眼部造成periocular tissue swelling，可能合併有allergy和eosinophilia","(B) 主要的組織病理特點為IgG4在組織血管內的沉積，但不會看到B淋巴球的浸潤","(C) 大於90%病人血中IgG4的濃度會上升，且血中IgG4的濃度與疾病嚴重度成正相關","(D) 大量IgG4在組織活化T淋巴球，因此本疾病常造成急性的器官破壞而應給與大量steroid治療"],"answer":0,"image":""},{"id":"md3-113-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"一位80歲男性病人有膝關節疼痛，膝關節液的分析為呈現黏稠的（viscous）關節液且白血球數為100/μL，關節液細胞以mononuclear cell為主，此病人最可能患有下列何種關節炎？","options":["(A) osteoarthritis","(B) reactive arthritis","(C) rheumatoid arthritis","(D) septic arthritis"],"answer":0,"image":""},{"id":"md3-113-2-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"有關類風濕性關節炎的關節外表現（extraarticular manifestations），下列何者最常見？","options":["(A) hyperandrogenism","(B) osteoporosis","(C) pulmonary artery hypertension","(D) lumbar myelopathy"],"answer":1,"image":""},{"id":"md3-113-2-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"下列疾病與human leukocyte antigen（HLA）之相關性，何者最高？","options":["(A) Type 1 diabetes mellitus與HLA-B5801","(B) Behçet's disease與HLA-B1502","(C) Sjögren's syndrome與HLA-DR8","(D) 類風濕性關節炎（rheumatoid arthritis）與HLA-DR4"],"answer":3,"image":""},{"id":"md3-113-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"34歲陳女士，因為多次原因不明的laryngeal edema掛急診，其中一次因喉頭水腫太嚴重無法插管，還需緊急氣切才挽回生命。陳女士記得她從有記憶起，就曾經多次因為嚴重腹痛合併腹水而住院，但都沒有找到病因。平時也有很多次突然整個臉或手掌、腳掌突然腫起來。病人發作時皮膚從來沒有蕁麻疹，好幾位醫師曾經幫她驗過血，但也都沒有找到過敏原。下列處置何者對病情最沒有幫助？","options":["(A) 檢驗血中C4","(B) 檢驗C1 esterase inhibitor","(C) 檢驗total IgE","(D) 處方danazol"],"answer":2,"image":""},{"id":"md3-113-2-36","subject":"md3","topic":"內科-腫瘤","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"一位38歲女性，一開始以左側腋下腫瘤表現至醫院就診，腋下腫瘤切片證實為腺癌（adenocarcinoma），但乳房影像檢查（包括超音波，攝影及核磁共振）並無顯現乳房腫塊，關於此病人後續檢查或治療，下列何者最不合適？","options":["(A) 檢測estrogen receptor、GATA3、HER-2基因表現","(B) 同側乳房切除手術治療","(C) 局部放射治療","(D) 全身性化學治療或抗賀爾蒙治療"],"answer":1,"image":""},{"id":"md3-113-2-37","subject":"md3","topic":"內科-腫瘤","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"癌症治療學的進展一方面大大提升癌症病患的存活機會，但也可能合併許多late treatment consequences。下列癌症治療藥物和late treatment consequence的組合，何者最不恰當？","options":["(A) anthracycline — neuropathy","(B) bleomycin — pulmonary fibrosis","(C) trastuzumab — cardiac dysfunction","(D) glucocorticoids — avascular necrosis of bones"],"answer":0,"image":""},{"id":"md3-113-2-38","subject":"md3","topic":"內科-腫瘤","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"關於第四期的皮膚惡性黑色素細胞癌（malignant melanoma）之治療，下列敘述何者最不適當？","options":["(A) 標靶治療（BRAF抑制劑、MEK抑制劑）相較於免疫治療（抗CTLA-4抗體、抗PD-1抗體）最大的好處是標靶治療效果的持久性（durability）較佳","(B) 使用標靶治療的副作用之一為產生皮膚鱗狀上皮癌。合併使用BRAF抑制劑加上MEK抑制劑，產生此一副作用之機會比單獨使用BRAF抑制劑為低","(C) 如果是沒有BRAF突變的惡性黑色素細胞癌，第一線的治療可以使用免疫治療","(D) 如果是有BRAF突變的惡性黑色素細胞癌，第一線的治療可以使用免疫治療或標靶治療（BRAF抑制劑加上MEK抑制劑）"],"answer":0,"image":""},{"id":"md3-113-2-39","subject":"md3","topic":"內科-腫瘤","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"攝護腺癌（prostate cancer）合併遠端轉移，病患血中睪固酮（testosterone）已經小於50 ng/mL，下列何種藥物目前尚無明確證實有效的證據？","options":["(A) abiraterone acetate + prednisone","(B) enzalutamide","(C) 化學治療的docetaxel","(D) 免疫治療的pembrolizumab"],"answer":3,"image":""},{"id":"md3-113-2-40","subject":"md3","topic":"內科-腫瘤","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"下列何種情形血中攝護腺特異性抗原（prostate specific antigen, PSA）最不可能高於正常值？","options":["(A) 良性攝護腺肥大（benign prostate hypertrophy）","(B) 攝護腺切片（prostate biopsy）之後","(C) 攝護腺癌（prostate cancer）","(D) 根除性攝護腺切除（radical prostatectomy）之後"],"answer":3,"image":""},{"id":"md3-113-2-41","subject":"md3","topic":"內科-血液","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"下列發生於acute myeloid leukemia的染色體變化與相對應的基因融合（fusion），何者錯誤？","options":["(A) t(8;21)與RUNX1-RUNX1T1","(B) t(15;17)與PML-RARA","(C) inv(16)與CBFB-MYH11","(D) t(9;11)與DEK-NUP214"],"answer":3,"image":""},{"id":"md3-113-2-42","subject":"md3","topic":"內科-血液","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"有關巨球母細胞性貧血（megaloblastic anemia）的敘述，下列何者錯誤？","options":["(A) 可以和葉酸缺乏有關","(B) 可以和維生素B12缺乏有關","(C) 其基本形成的原因是DNA轉錄到mRNA的過程受到阻斷","(D) 其血液學的表現可以是全血球低下（pancytopenia）"],"answer":2,"image":""},{"id":"md3-113-2-43","subject":"md3","topic":"內科-血液","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"有關何杰金氏淋巴癌病源的敘述何者正確？","options":["(A) 目前認為其淋巴癌細胞最可能是源自於B細胞淋巴球","(B) 目前認為其淋巴癌細胞最可能是源自於T細胞淋巴球","(C) HIV感染相關之何杰金氏淋巴癌細胞裡幾乎都看不到EBV感染的證據","(D) 非HIV感染相關之何杰金氏淋巴癌細胞裡幾乎都看得到EBV感染的證據"],"answer":0,"image":""},{"id":"md3-113-2-44","subject":"md3","topic":"內科-血液","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"下列何者最不可能是多發性骨髓癌（multiple myeloma）常見的臨床表現特徵？","options":["(A) 脊椎壓迫性骨折","(B) 腎功能異常","(C) 高血鈣症（hypercalcemia）","(D) 多血症（polycythemia）"],"answer":3,"image":""},{"id":"md3-113-2-45","subject":"md3","topic":"內科-胸腔","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"下列何者不是診斷usual interstitial pneumonia在胸部電腦斷層的典型特徵？","options":["(A) subpleural reticulation","(B) traction bronchiectasis","(C) honeycombing appearance","(D) micronodules"],"answer":3,"image":""},{"id":"md3-113-2-46","subject":"md3","topic":"內科-胸腔","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"60歲女性病人，因近日有呼吸困難及胸痛情形前來就診。就診時身體診察發現有右腳單隻腳水腫之情形，最有可能的診斷為何？","options":["(A) 心衰竭","(B) 肺栓塞","(C) 氣胸","(D) 慢性阻塞性肺病"],"answer":1,"image":""},{"id":"md3-113-2-47","subject":"md3","topic":"內科-胸腔","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"關於肺膿瘍的敘述，下列何者錯誤？","options":["(A) 原發性肺膿瘍最常見的位置是上肺葉的後節及下肺葉的上節","(B) 金黃色葡萄球菌是敗血性血栓（septic emboli）所致的肺膿瘍之常見致病菌","(C) 厭氧性細菌常發生於原發性肺膿瘍","(D) 抗生素治療時間通常為7～10天；必要時，需進行手術"],"answer":3,"image":""},{"id":"md3-113-2-48","subject":"md3","topic":"急診醫學","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"45歲女性病人因間皮瘤（mesothelioma）接受化學治療。在藥物輸注10分鐘後，開始有皮疹、嘴唇腫脹、呼吸困難及血壓下降的情形，下列處置何者最為優先？","options":["(A) 因為血壓下降懷疑敗血症休克，應給與大量輸液及抗生素","(B) 因為呼吸困難，應立即給與插管使用呼吸器","(C) 因為皮疹應給與類固醇","(D) 因為發生在藥物使用後，應立即給與腎上腺素（epinephrine）及其他輔助藥物，如：抗組織胺、類固醇"],"answer":3,"image":""},{"id":"md3-113-2-49","subject":"md3","topic":"內科-胸腔","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"68歲男性，長期吸菸，有高血壓，近5年內因腦血管栓塞住院2次，都無後遺症。因最近一週劇烈咳嗽、黃痰、呼吸喘促、發燒至急診求治。胸部X光顯示右上肺葉大葉性浸潤，同側肋膜積液。痰檢顯示痰中有許多白血球，染色看到許多革蘭氏陽性雙球菌（diplococci），下列何種敘述正確？①為吸入性肺炎（aspiration pneumonia） ②應選擇可以涵蓋Streptococcus pneumoniae之抗生素治療 ③應選擇可以涵蓋Pseudomonas aeruginosa之抗生素治療 ④應考慮住院及檢驗肋膜積液","options":["(A) ①②","(B) ①③④","(C) ②④","(D) 僅①④"],"answer":2,"image":""},{"id":"md3-113-2-50","subject":"md3","topic":"內科-胸腔","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"病人因慢性阻塞性肺病急性發作至急診求診，下列處置何者缺乏實證支持？","options":["(A) 靜脈注射茶鹼（theophylline）","(B) 靜脈注射抗生素","(C) 靜脈注射類固醇","(D) 支氣管擴張劑（bronchodilator）霧化治療"],"answer":0,"image":""},{"id":"md3-113-2-51","subject":"md3","topic":"內科-胸腔","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"75歲中風而長期臥床男性病人，因為要入住安養中心而進行身體健康檢查。胸部X光並無異常發現，但痰液塗片耐酸性染色鏡檢（acid-fast stain）為陽性。下列敘述何者最適當？","options":["(A) 應等待痰的分枝桿菌培養結果後，再決定是否可入住安養中心及接受抗結核藥物治療","(B) 此檢體應進行結核菌核酸增幅檢驗（nucleic acid amplification test）","(C) 應立即另外再採集3套痰檢體進行分枝桿菌培養及鑑定","(D) 應立刻進行胸部電腦斷層檢查"],"answer":1,"image":""},{"id":"md3-113-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"下列有關於女性更年期停經的敘述，何者最不適當？","options":["(A) 基本上，女性在35歲之後，卵巢功能，以及生育能力就開始下降","(B) 女性更年期的症狀，包括潮紅（hot flush），以及夜間盜汗（night sweating）","(C) 停經後，濾泡刺激素（follicle-stimulating hormone）及雌二醇（estradiol）會持續偏低","(D) 停經後，女性補充雌激素，可以改善停經後的症狀，但補充雌激素可能增加發生子宮內膜癌（endometrial cancer）或靜脈血栓症（venous thromboembolism）的風險"],"answer":2,"image":""},{"id":"md3-113-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"下列有關basal-bolus胰島素注射法的敘述，何者最適當？","options":["(A) 三餐注射短效或速效的胰島素，並每日給與一次長效型的胰島素注射","(B) 三餐給與預混型的胰島素，並於睡前給與一次長效型的胰島素注射","(C) 每天給與一次超長效的胰島素注射","(D) 每天給與四次速效型的胰島素注射"],"answer":0,"image":""},{"id":"md3-113-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"糖尿病下肢病變是導致截肢的主要原因，下列敘述何者最不適當？","options":["(A) 下肢病變可以是血管阻塞或神經病變所引起","(B) 足部潰瘍會因為血管病變而難以癒合","(C) 足部潰瘍很難透過衛教來預防","(D) 足部潰瘍發生時要避免患部的外來壓力"],"answer":2,"image":""},{"id":"md3-113-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"下列有關肥胖及其生理機轉之敘述，何者最適當？","options":["(A) 體重100公斤，身高180公分之男子，其身體質量指數（body mass index）為32","(B) 男性肥胖定義，身體質量指數（body mass index）為27，女性則為25","(C) 瘦素（leptin）主要由脂肪組織分泌","(D) 一般而言，瘦的人血中瘦素（leptin）濃度較肥胖者高"],"answer":2,"image":""},{"id":"md3-113-2-56","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"術前診斷甲狀腺結節良惡性的黃金標準為下列何者？","options":["(A) 甲狀腺超音波檢查","(B) 抽血檢驗血中甲狀腺球蛋白（thyroglobulin）濃度","(C) 甲狀腺細針穿刺細胞學檢查","(D) 頸部核磁共振檢查"],"answer":2,"image":""},{"id":"md3-113-2-57","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"造成肢端肥大症的腦下垂體腫瘤的治療首選為何？","options":["(A) 放射線治療","(B) 多巴胺受體作用劑（dopamine receptor agonist）","(C) 經蝶鞍手術（transsphenoidal surgery）去除腫瘤","(D) 注射體抑素類似物（somatostatin analogue）"],"answer":2,"image":""},{"id":"md3-113-2-58","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"下列檢查，那一項是診斷「疾病甲狀腺正能症（sick euthyroid syndrome）」最關鍵的指標？","options":["(A) 三碘甲狀腺素（T3）","(B) 四碘甲狀腺素（T4）","(C) 逆位三碘甲狀腺素（reverse T3）","(D) 甲狀腺超音波"],"answer":2,"image":""},{"id":"md3-113-2-59","subject":"md3","topic":"內科-感染","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"導管長期置放是造成醫療照護相關感染的常見危險因子，導尿管置放後每日發生尿路感染的機會，約為多少？","options":["(A) 0.03%～0.07%","(B) 0.3%～0.7%","(C) 3%～7%","(D) 30%～70%"],"answer":2,"image":""},{"id":"md3-113-2-60","subject":"md3","topic":"內科-感染","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"下列有關抗生素的主要抑制機轉配對，何者最不適當？","options":["(A) 盤尼西林（penicillin）— 細胞壁合成（cell wall synthesis）","(B) 四環黴素（tetracycline）— 蛋白質合成（protein synthesis）","(C) 巨環素（macrolide）— DNA合成（DNA synthesis）","(D) 磺胺類（sulfonamide）— 葉酸合成（folate synthesis）"],"answer":2,"image":""},{"id":"md3-113-2-61","subject":"md3","topic":"內科-感染","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"有關中樞神經感染單純疱疹病毒（HSV）診斷工具中的HSV腦脊髓液聚合酶鏈鎖反應（polymerase chain reaction, PCR），下列敘述何者錯誤？","options":["(A) 敏感性（sensitivity）及專一性（specificity）都超過90%","(B) 在發病的72小時內，腦脊髓液HSV PCR有可能呈現陰性","(C) 腦脊髓液HSV PCR的陽性率會隨著病程而逐漸降低，發病超過14天之病人，大約只有20%仍然呈現陽性","(D) 抗病毒藥物之治療對腦脊髓液HSV PCR的陽性率有重大影響，治療3天後，腦脊髓液HSV PCR的陽性率即低於10%"],"answer":3,"image":""},{"id":"md3-113-2-62","subject":"md3","topic":"內科-感染","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"25歲男性，因為軀幹紅疹，合併手掌與足底多處脫屑紅疹，以及陰莖底部無痛性潰瘍而就醫，血液檢測後，醫師診斷為一期與二期梅毒。經進一步檢測，病人並沒有感染人類免疫不全病毒。關於梅毒處置之敘述，下列何者錯誤？","options":["(A) 梅毒篩檢與確診的血清檢查，分別使用rapid plasma reagin（RPR）與Treponema pallidum particle agglutination（TPPA）檢測","(B) 美國疾病管制局（US Centers for Disease Control and Prevention）2015年的性病治療指引對於早期梅毒（early syphilis）治療，針對沒有penicillin過敏，且沒有神經病徵者，建議使用一次單劑肌肉注射benzathine penicillin G（2.4 mU）","(C) 美國疾病管制局（US Centers for Disease Control and Prevention）2015年的性病治療指引對於早期梅毒（early syphilis）治療，針對penicillin過敏，但沒有神經病徵者，建議使用doxycycline 100 mg，每日兩次，服用14天","(D) 此病人梅毒治療後的療效評估，是在治療後6個月與12個月追蹤TPPA檢測，確認抗體效價下降至少4倍或以上"],"answer":[1,3],"image":"","answer_note":"更正:第62題答Ｂ或Ｄ或BD者均給分"},{"id":"md3-113-2-63","subject":"md3","topic":"內科-感染","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"25歲病人因為發燒多日、腹瀉、皮疹、咽喉痛和頸部淋巴腺腫就醫。診視發現口腔上顎有幾點白斑，血液相（hemogram）出現白血球與血小板降低，生化檢查發現轉氨酶（transaminases）10倍上升。醫師懷疑是人類免疫不全病毒（HIV）急性感染所引起的急性反轉錄病毒感染症候群（acute retroviral syndrome）。經病史詢問，發現病人在14天前第一次與網路上認識的一位男性發生未戴保險套的肛交性行為。下列敘述何者正確？","options":["(A) 此時以第四代合併抗原與抗體的HIV檢測，對這位病人，100%可以確診HIV感染","(B) 此時這位感染HIV的病人，儘快進行西方墨點（Western blot），因為它是最敏感而且確認HIV感染的檢測","(C) HIV核酸檢測（nucleic-acid amplification test）是診斷這位急性HIV感染病人最敏感和特異性（specificity）最高的檢測方式","(D) 這位病人急性HIV感染病症會自然改善，並不急著給與抗病毒治療。根據國內外治療指引，等到他血液中的3 CD4數值降低到350 cells/mm以下，或者出現愛滋病（AIDS）相關病症再開始治療即可"],"answer":2,"image":""},{"id":"md3-113-2-64","subject":"md3","topic":"內科-感染","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"關於蜂窩性組織炎的致病菌描述，下列何者錯誤？","options":["(A) 經由切片（punch biopsy）培養陽性結果的機會可高達70%","(B) 鏈球菌（streptococci）在下肢循環不良的病人常導致反覆感染","(C) 被貓狗咬傷易產生厭氧菌相關感染","(D) 綠膿桿菌（Pseudomonas aeruginosa）可見於被鐵釘穿刺傷（penetrating injury）造成的傷口感染"],"answer":0,"image":""},{"id":"md3-113-2-65","subject":"md3","topic":"內科-感染","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"引起社區型肺炎的菌種，常與特殊的旅遊史或接觸史有關，下列配對何者錯誤？","options":["(A) structural lung disease — Pseudomonas aeruginosa","(B) 在發病前二週內住過旅館或郵輪 — Acinetobacter spp.","(C) 近期接觸過鳥 — Chlamydia psittaci","(D) 近期接觸過羊 — Coxiella burnetii"],"answer":1,"image":""},{"id":"md3-113-2-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"28歲女性因急性腎衰竭住院，醫師建議洗腎，但個案因傳統信仰一直猶豫是否要接受洗腎。處理跨文化之差異時，Berlin與Fowkes提出解決之方式「LEARN model」，下列敘述何者錯誤？","options":["(A) Listen：以同理心傾聽並瞭解病人的想法","(B) Explain：以病人能了解的方式，解釋病人的問題","(C) Reward：對病人解釋治療的好處","(D) Negotiate：與病人討論以取得治療共識"],"answer":2,"image":""},{"id":"md3-113-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"75歲獨居男性有高血壓與糖尿病，服藥種類有8種，服藥次數有每天1次、2次、3次，服藥時間有飯前、飯後服用，因病人常忘記服藥，導致病情控制不良。某日半夜起床解尿跌倒，導致下背痛，經診斷為腰椎壓迫性骨折。下列何者是此門診個案最合適的處理？","options":["(A) 應進行周全性老年醫學評估","(B) 應指導病人依照醫囑服用每一種藥物","(C) 應建議長期住護理之家接受照顧、管理服藥問題","(D) 應置入導尿管以預防再跌倒"],"answer":0,"image":""},{"id":"md3-113-2-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"63歲婦女獨自來家庭醫學科門診，自述過去健康狀況良好，最近2週血壓偶爾偏高（BP 160/96 mmHg），他院醫師開立兩種降血壓藥物，服用後血壓降至100/60 mmHg並有頭暈現象。病史詢問得知她唯一的女兒1個月前罹患肺癌過世，讓她情緒非常低落，無法入眠。下一步處置何者最不適當？","options":["(A) 減輕藥物劑量，請病人在家記錄血壓","(B) 評估家庭結構及動態功能","(C) 建議病人繼續依原醫囑服藥，以免發生中風","(D) 進行悲傷撫慰"],"answer":2,"image":""},{"id":"md3-113-2-69","subject":"md3","topic":"內科-感染","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"有關狂犬病（rabies）疫苗接種的敘述，下列何者最正確？","options":["(A) 暴露前預防接種的時程為第0天、第3天、第7天，共3劑","(B) 若預防接種後間隔1年再次進入疫區，建議應追加1劑","(C) 免疫功能正常者若曾接受完整暴露前疫苗接種，暴露後只需於第0天與第3天接種，共兩劑疫苗","(D) 小孩可接種，但孕婦不可接種"],"answer":2,"image":""},{"id":"md3-113-2-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"①在整個生病或壓力生活事件過程中，給予病人及家屬想法、感受和情緒的支持 ②辨識影響負面想法的觸發因素或障礙，及對目前問題的反應 ③設定家庭成員在有限時間內，可學習以降低不良行為的目標。下列何種治療包含前述3項處置？","options":["(A) Motivational Interviewing","(B) Solution-focused Brief Therapy","(C) Cognitive Behavioral Therapy","(D) Family Psychoeducation"],"answer":2,"image":""},{"id":"md3-113-2-71","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"「居家醫療的主導醫師應持續地進行自我反思（self-reflective process）以避免工作倦怠，維持對工作的熱誠，打造理想療癒環境（optimal healing environment, OHE）」，這是屬於理想療癒環境架構中的：","options":["(A) 內在環境（inner personal environment）","(B) 人際環境（interpersonal environment）","(C) 行為環境（behavioral environment）","(D) 外在環境（external environment）"],"answer":0,"image":""},{"id":"md3-113-2-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"75歲女士來到門診抱怨最近身體很累，睡不好，常覺得自己沒什麼用了，心情快樂不起來。進一步詢問，她並不會想哭，也沒有自殺念頭；老人憂鬱症篩檢量表（GDS）得分9分（總分15分）。後續處置以下列何者最適宜？","options":["(A) 給與鎮靜安眠藥即可","(B) 僅心情不快樂，非老人憂鬱症，無須特別處理","(C) 轉介社福單位進一步介入","(D) 可能有憂鬱症，應進一步確認診斷"],"answer":3,"image":""},{"id":"md3-113-2-73","subject":"md3","topic":"醫學倫理與法規","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"具完全行為能力的意願人，可以透過預立醫療照護諮商（Advance Care Planning）的程序，與親友和醫療機構人員討論善終意願，並簽屬預立醫囑（Advance Directive）。在臺灣，預立醫囑是依據那個法令執行？","options":["(A) 民法","(B) 安寧緩和醫療條例","(C) 醫療法","(D) 病人自主權利法"],"answer":3,"image":""},{"id":"md3-113-2-74","subject":"md3","topic":"影像醫學","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"56歲男性病患，過去有高血壓病史，突然有發燒、嘔吐與腹痛的症狀，緊急安排了電腦斷層檢查影像如附圖，下列何者為最可能的診斷？","options":["(A) 盲腸炎（acute appendicitis）","(B) 主動脈剝離（aortic dissection）","(C) 上腸繫膜靜脈血栓（superior mesenteric vein thrombosis）","(D) 大腸憩室炎（colonic diverticulitis）"],"answer":2,"image":"md3-113-2-74.jpeg"},{"id":"md3-113-2-75","subject":"md3","topic":"影像醫學","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"在胸部電腦斷層，若發現肺結節（lung nodule）具有下列那一個特徵時，最可能是良性的？","options":["(A) 8 mm大小的毛玻璃狀結節（ground-glass nodule）","(B) 12 mm大小的結節出現中央型粗鈣化（central coarse calcification）","(C) 8 mm大小的部分實質結節（part-solid nodule）","(D) 12 mm大小的實質結節（solid nodule）"],"answer":1,"image":""},{"id":"md3-113-2-76","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"老人受傷常比年輕人嚴重，下列生理變化何者錯誤？","options":["(A) 心肌細胞數量減少，心臟收縮力下降","(B) 心臟傳導系統功能改變導致心跳變慢","(C) 呼吸肌無力容易併發呼吸衰竭","(D) 腎臟功能下降容易導致脫水"],"answer":1,"image":""},{"id":"md3-113-2-77","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"56歲女性3天前曾經接受甲狀腺全切除手術，因食慾不振、虛弱無力，被家人送到急診室，抽血檢驗發現病人游離鈣離子：3.5 mg/dL。下列處置何者最不適當？","options":["(A) 嚴重低血鈣病人有可能出現錐體外（extrapyramidal）症狀、癲癇發作和幻覺","(B) 檢查者用手指輕拍病人耳前的面頰，顏面肌肉會跟著收縮，此稱為Chvostek sign","(C) 低血鈣病人的心電圖特徵，經常呈現QTc期間縮短及T波變高","(D) 若病人使用毛地黃藥物，靜脈補充鈣離子可能會增加毒性"],"answer":2,"image":""},{"id":"md3-113-2-78","subject":"md3","topic":"內科-內分泌代謝","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"下列那一類降血壓藥物最常發生低血糖（hypoglycemia）之不良反應？","options":["(A) biguanides（例如metformin）","(B) thiazolidinediones（例如pioglitazone）","(C) sulfonylureas（例如glipizide）","(D) α-glucosidase inhibitors（例如acarbose）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第78題一律給分 (原公告答案 C)"},{"id":"md3-113-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"我國醫療法規對於病人病情告知的規定，下列敘述何者錯誤？","options":["(A) 醫師法規定，應告知病人或其家屬","(B) 醫療法規定，應告知病人或其法定代理人、配偶、親屬或關係人","(C) 安寧緩和醫療條例規定，應告知末期病人或其家屬，但病人有明確意思表示欲知病情時，應予告知","(D) 病人自主權利法規定，應告知本人或關係人"],"answer":3,"image":""},{"id":"md3-113-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"知名藝人A君在家中被人發現昏迷不醒，以救護車送至B醫院急診室後不治死亡。媒體盛傳A君是吸毒過量致死，而且今年年初曾因為毒癮至B醫院接受治療，新聞記者在採訪急診室主任時，一直要急診室主任證實A君是否曾住院戒毒，你認為急診室主任可以說明嗎？","options":["(A) 可以，因為病人死後醫師就沒有保密義務","(B) 不可以，即使病人死後，醫師還是有保密義務","(C) 可以，因為A君是公眾人物","(D) 不可以，雖然病人死後醫師就沒有保密義務，但是洩露這個消息會妨害病人名譽"],"answer":1,"image":""},{"id":"md3-114-1-1","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"治療高鉀血症（hyperkalemia）時，下列那一項藥品的使用敘述最不適當？","options":["(A) 10%的葡萄糖酸鈣（calcium gluconate）10 mL靜脈注射","(B) 胰島素10單位靜脈注射後立即給與50%的葡萄糖水50 mL靜脈注射。若血糖超過250 mg/dL，可以只注射胰島素","(C) 吸入型beta 2-擬交感神經作用劑（beta-2 agonist），如albuterol汽化噴霧劑10～20 mg，混合4 mL生理食鹽水吸入","(D) 口服patiromer，屬陽離子交換樹脂（cation exchange resin），此藥較常見的副作用是便秘與高鎂血症（hypermagnesemia）"],"answer":3,"image":""},{"id":"md3-114-1-2","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"35歲男性於健檢時發現血尿（hematuria）。門診再追蹤尿液檢查發現：蛋白排泄量（protein excretion）1500 mg/day、10～20 RBCs/HPF、dysmorphic RBC (+)、RBC cast (+)。後續安排下列評估，何者最不適當？","options":["(A) 檢測免疫血清學檢查，例如complement levels（C3, C4）、cryoglobulins、anti-GBM antibody、ANCA、ASLO、VDRL、HIV","(B) 測B型肝炎（hepatitis B）、C型肝炎（hepatitis C）病毒血清學檢查","(C) 靜脈腎盂造影（intravenous pyelography）或逆行性腎盂攝影（retrograde pyelography）","(D) 腎臟超音波（renal ultrasonography），必要時考慮腎臟切片（renal biopsy）檢查"],"answer":2,"image":""},{"id":"md3-114-1-3","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"30歲男性接受疝氣手術後，出現鞏膜變黃、茶色尿等症狀，抽血發現total bilirubin為4.1 mg/dL，下列那一項診斷最不可能？","options":["(A) Gilbert's syndrome","(B) Crigler-Najjar syndrome type I","(C) 腹腔內感染","(D) 溶血（hemolysis）"],"answer":1,"image":""},{"id":"md3-114-1-4","subject":"md3","topic":"內科-胸腔","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"關於氣促（dyspnea）身體診察與可能病態生理的對應，下列何者配對最適當？","options":["(A) 心音的P2消失，考慮右心室壓力增加","(B) 聽診出現bronchial sound，考慮有肋膜積水","(C) 奇脈（pulsus paradoxus），考慮心包膜異常","(D) 吐氣期腹部向內凹陷，考慮橫膈膜無力"],"answer":2,"image":""},{"id":"md3-114-1-5","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"有關急性主動脈剝離（acute aortic dissection）之描述，下列何者最不適當？","options":["(A) 發生於後背肩胛骨間的撕裂性疼痛，比單純前胸的撕裂性疼痛更危險","(B) 可能出現上肢單側脈搏消失","(C) 若出現頸靜脈怒張（jugular vein engorgement），需考慮心包膜填塞","(D) 可能同時伴有急性心肌梗塞"],"answer":0,"image":""},{"id":"md3-114-1-6","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"利用介入心導管技術、不開刀處置結構性心臟病，為近年來重要醫學進展之一，下列相關敘述何者錯誤？","options":["(A) 經由阻塞器（occluder）置放，可以有效關閉心房中隔缺損（atrial septal defect, ASD）、開放性卵圓窗（patent foramen ovale, PFO）、或開放性動脈導管（patent ductus arteriosus, PDA）等疾病","(B) 氣球瓣膜擴張術可用於治療風濕性二尖瓣狹窄，目前常用術式中，氣球導管是經由股靜脈送入","(C) 經導管主動脈瓣置換（transcatheter aortic valve replacement, TAVR）可治療嚴重主動脈瓣狹窄，適合用於高度及中度外科手術風險之病患","(D) 經導管二尖瓣緣對緣（edge-to-edge）修補術可治療嚴重二尖瓣閉鎖不全，特別適合用於因腱索斷裂（chordae rupture）造成瓣膜逆流之病患"],"answer":3,"image":""},{"id":"md3-114-1-7","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"關於核醫心肌灌流造影用於已知冠狀動脈疾病病人的臨床應用，下列敘述何者錯誤？","options":["(A) 接受冠狀動脈繞道術後5年內，在病人無症狀的情形下，常規的心肌灌流造影評估是必要的檢查項目","(B) 接受經皮冠狀動脈介入治療（PCI）後2年內，在病人無症狀的情形下，常規的心肌灌流造影評估並非必要的常規檢查項目","(C) 在接受冠狀動脈繞道術後仍有症狀的病人，核醫心肌灌流造影可用以評估術後血管的狹窄造成心肌缺血之嚴重程度","(D) 經皮冠狀動脈介入治療（PCI）後的早期，核醫心肌灌流造影仍可能觀察到輕微可逆性的心肌灌流缺損"],"answer":0,"image":""},{"id":"md3-114-1-8","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"47歲男性，曾頭暈昏倒多次，心電圖檢查顯示多發性心室期外收縮。磁振造影發現左心室較大，下壁及下外側壁收縮功能較差，顯影劑注射後，磁振造影出現顯影劑延遲增強（late gadolinium enhancement, LGE），如附圖所示。下敘述何者錯誤？","options":["(A) 此病患的LGE位於心壁的中外層（mid myocardial, epicardial region），是典型浸潤型疾病（infiltration）的特殊表現，如肉瘤病（sarcoidosis），在此切片檢查（biopsy）可增加陽性率","(B) 如果是擴大型心肌病變的LGE多位於心壁中間（midwall），呈現斑塊（patchy）或是細線狀（linear），最常見位置是basal septum","(C) 心肌梗塞病人的LGE代表心肌結疤處，多寡與心臟功能及預後有關，一般由心內膜開始（subendocardial region）","(D) 心肌水腫時在MRI的T1訊號會增加，與LGE分別代表不同的組織變化，此與疾病的不同時期有關"],"answer":3,"image":"md3-114-1-8.jpeg"},{"id":"md3-114-1-9","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"心臟動作電位（action potential）由許多離子通道（ion channel）調控。下列何種離子不直接參與心臟動作電位的產生與維持？ +","options":["(A) 鈉離子（Na） +","(B) 鉀離子（K）2+","(C) 鈣離子（Ca）2+","(D) 鎂離子（Mg）"],"answer":3,"image":""},{"id":"md3-114-1-10","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"下列何種藥物不會造成心電圖QT interval prolong？","options":["(A) quinidine","(B) digoxin","(C) ibutilide","(D) sotalol"],"answer":1,"image":""},{"id":"md3-114-1-11","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"下列何者不是genetic arrhythmia syndrome？","options":["(A) long QT syndrome","(B) Brugada syndrome","(C) catecholaminergic polymorphic ventricular tachycardia（VT）","(D) ventricular tachycardia（VT）with structural heart disease"],"answer":3,"image":""},{"id":"md3-114-1-12","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"關於heart failure with preserved ejection fraction的敘述，下列何者正確？","options":["(A) 常見於急性心肌梗塞的急性期","(B) 常見於甲狀腺亢進早期的病人","(C) 常見於有多年高血壓病史的老年人","(D) 常見於病毒性心肌炎的急性期"],"answer":2,"image":""},{"id":"md3-114-1-13","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"下列關於心房顫動（atrial fibrillation）臨床上使用抗血栓治療之敘述，何者錯誤？","options":["(A) atrial fibrillation在老人較多，80歲以上約有10%","(B) 發生atrial fibrillation的危險因素包括高血壓、糖尿病、心臟病、肥胖症和睡眠呼吸暫停","(C) atrial fibrillation使中風的風險增加約5倍，據估計占所有中風的病人約25%","(D) 如果atrial fibrillation的持續時間超過48小時或未知，但中風風險較低（CHA2DS2-VASc為0或1）的病人中，在未給抗凝血劑的狀況下，將心臟電擊回正常心律應是安全而被建議的"],"answer":3,"image":""},{"id":"md3-114-1-14","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"有關心衰竭（heart failure, HF）治療同時考慮其他共病時，下列敘述何者錯誤？","options":["(A) 雖然有些治療糖尿病的藥物與增加HF的風險有關，但是使用第二型鈉依賴型葡萄糖共同運輸蛋白抑制劑（SGLT2 inhibitor，如empagliflozin）降低血糖被證明可降低糖尿病患者HF的風險","(B) 較高的身體活動量與較低的HF發生風險有關","(C) 在中年人和老年人中，吸菸是HF的風險因素之一","(D) 在Framingham心臟研究中，心肌梗塞病史、右束支傳導阻滯（RBBB）、無症狀左心室收縮功能障礙、總血紅蛋白濃度升高都與HF風險增加顯著相關"],"answer":3,"image":""},{"id":"md3-114-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"一位慢性B型肝炎帶原者因活動性肺結核併發燒而接受下列藥物治療：isoniazid、rifampin、ethambutol、streptomycin。一個月後抽血檢查發現aspartate aminotransferase（AST）/alanine aminotransferase（ALT）：120/140（U/L），total bilirubin：0.9（mg/dL），肝功能其他項目仍在正常範圍內。下列敘述何者正確？","options":["(A) 應立即停止所有抗結核藥物","(B) 如同acetaminophen，isoniazid服用的劑量越大，肝的傷害也就越大","(C) 口服類固醇可降低肝臟發炎，改善肝指數異常情形","(D) isoniazid引起肝炎的風險較ethambutol為高"],"answer":3,"image":""},{"id":"md3-114-1-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"一位剛上大學的女性因流涎、肢體僵硬及震顫等運動性障礙，住進神經科病房。住院抽血發現肝功能異常會診胃腸肝膽科醫師。病人血清檢查HBsAg及anti-HCV皆呈陰性。下列敘述何者最適當？①可能發生急性猛爆性肝炎（fulminant hepatitis），血清及膽汁內的銅離子濃度減少 ②口服zinc、trientine 不可用於懷孕期 ③身體診察在病人的角膜上可見Kayser-Fleischer ring ④肝臟病理切片呈現hepato-lenticular degeneration","options":["(A) ①④","(B) ①③","(C) ③④","(D) ②④"],"answer":2,"image":""},{"id":"md3-114-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"80歲的林先生被送來急診室，主訴嚴重且無法緩解的腹痛一天，由身體診察發現體溫為攝氐36.5度，血壓95/58 mmHg，心跳105 bpm。心音快且不規則，兩側肺部聽診正常，腹部脹且腸音較慢，但腹部柔軟，並沒有明顯的腹膜炎徵象，其他身體診察大致正常。他平常有高血壓及高血脂且用藥控制中，最近因為胸悶有接受過心導管檢查。下列針對他的疾病的敘述及治療方式何者錯誤？","options":["(A) 由於年齡大且有心律不整，最近有接受過心導管檢查，需考慮缺血性腸炎","(B) 血壓降低及有血管粥狀硬化的風險，是疾病的加重因子，需要儘速給與血管收縮劑以提升血壓","(C) 可以檢查全血球計數、血液生化檢查包括胰澱粉酶及胰脂酶、凝血功能、乳酸、動脈血液氣體分析、心肌酵素及心電圖等","(D) 可以利用電腦斷層合併血管攝影來協助診斷，治療上應給與針對革蘭氏陰性菌及厭氧菌的抗生素。若有腹膜炎的徵象時，需要考慮剖腹探查"],"answer":1,"image":""},{"id":"md3-114-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"關於下列食道構造及功能性之疾病敘述，何者錯誤？","options":["(A) 在橫膈膜裂孔疝氣（hiatal hernia）中以第一型之滑脫型（sliding hernia）占最多","(B) 食道憩室Zenker's diverticulum產生之處為上端食道之食道壁脆弱之位置（Killian's triangle）","(C) 食道遲緩不能（achalasia）為吞嚥時近端食道括約肌無法放鬆所造成","(D) 高解析度食道壓力測量（manometry）為一食道功能性疾病之診斷工具"],"answer":2,"image":""},{"id":"md3-114-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"一位38歲女性病人因胃痛求診，胃鏡下發現胃潰瘍。病人自述家庭中也有數人有胃或十二指腸潰瘍的病史。下列何者正確？","options":["(A) 胃潰瘍成因可能為幽門螺旋桿菌感染，要確診唯一的方法僅有做胃部切片進行組織病理檢驗檢出細菌","(B) 若病人組織切片培養不出幽門螺旋桿菌，則病人不可能感染幽門螺旋桿菌","(C) 病人得到胃腺癌和胃部淋巴瘤的機會增加","(D) 尿素呼氣測試（urea breath test）的原理為胃幽門螺旋桿菌存在下，會抑制同位素標定尿素水解的反應，減少呼氣中標定碳13的含量"],"answer":2,"image":""},{"id":"md3-114-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"下列關於克隆氏病（Crohn's disease）之敘述何者錯誤？","options":["(A) 主要侵犯小腸，有時也會侵犯大腸","(B) 末端迴腸（ileum）是最好發部位","(C) 可能會引發進食後腹痛與脂肪便（steatorrhea）","(D) 抗腫瘤壞死因子（anti-TNF）製劑於中重度Crohn's disease之治療效果不佳"],"answer":3,"image":""},{"id":"md3-114-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"預測急性胰臟炎（acute pancreatitis）嚴重度之指標Bedside Index of Severity in Acute Pancreatitis（BISAP）不包含下列何項？","options":["(A) BUN＞25 mg/dL","(B) 意識障礙","(C) 腹水","(D) 胸部X光顯示有肋膜積液（pleural effusion）"],"answer":2,"image":""},{"id":"md3-114-1-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"臨床上常用Child-Turcotte-Pugh score來判斷肝硬化嚴重度，Child-Turcotte-Pugh score並未包含下列何項？","options":["(A) bilirubin","(B) prothrombin time","(C) hepatic encephalopathy","(D) alanine aminotransferase（ALT）"],"answer":3,"image":""},{"id":"md3-114-1-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"下列何者不是非酒精性脂肪肝（nonalcoholic fatty liver disease, NAFLD）的主要危險因子？","options":["(A) 肥胖","(B) 高尿酸血症","(C) 糖尿病","(D) 高血脂症"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第23題一律給分 (原公告答案 B)"},{"id":"md3-114-1-24","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"56歲女性，末期腎病病人，接受連續性可攜式腹膜透析（CAPD）治療2年，最近3個月開始有下肢水腫、體液堆積的現象。此病人接受腹膜平衡測驗（peritoneal equilibrium test）結果顯示其腹膜為高腹膜通透性（high transporter），為解決其體液過多（fluid overload）現象，下列何種處置最不適當？","options":["(A) 增加透析藥水葡萄糖濃度","(B) 採用不易吸收碳水化合物（icodextrin）透析藥水","(C) 延長透析藥水的留滯時間","(D) 改使用連續性循環式腹膜透析（CCPD）"],"answer":2,"image":""},{"id":"md3-114-1-25","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"49歲男性腎移植病人，移植3年後近期改變免疫抑制劑的處方，3週後發生口腔潰爛、下肢水腫、尿中蛋白 ＞300 mg/dL（試紙），血中LDL 168 mg/dL，下列何種藥物最可能造成上述表現？","options":["(A) cyclosporine","(B) tacrolimus","(C) mycophenolate mofetil","(D) sirolimus"],"answer":3,"image":""},{"id":"md3-114-1-26","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"有關Fabry disease的敘述，何者錯誤？","options":["(A) 為一種罕見之遺傳性疾病，各人種都有。此病是因負責製造α-galactosidase A酵素的基因缺陷引起","(B) 屬性聯遺傳疾病，父親帶有此基因缺陷時，其所生的子女，女兒有一半的機會帶因，而兒子會發病","(C) 臨床診斷要以家族病史、四肢疼痛、皮膚病變、特有的渦狀角膜濁斑，以及在尿道沉渣或組織檢體中發現充滿脂質的細胞為基礎。再以白血球中α-galactosidase A酵素的活性作最後確診。進一步也可做基因突變的分析","(D) 目前治療可分為症狀治療及酵素替代療法（enzyme replacement therapy）。神經痛可透過藥物來緩解，心臟及腦血管併發症仍依一般治療原則，腎衰竭則需要透析治療"],"answer":1,"image":""},{"id":"md3-114-1-27","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"有關血栓性微血管病（thrombotic microangiopathy, TMA），下列何者錯誤？","options":["(A) 診斷TMA，必須血小板低下加上microangiopathic hemolytic anemia（MAHA）兩個條件同時成立，而MAHA就是檢驗數據上看到LDH上升、haptoglobin下降，以及血液抹片上有schistocyte","(B) TMA的臨床表現包括神經學症狀、腎臟侵犯及腸胃道症狀","(C) 診斷TMA後，如果ADAMTS13酵素的活性＞15%，則可以診斷栓塞性血小板低下紫斑（TTP）","(D) 栓塞性血小板低下紫斑（TTP）可使用plasma exchange加上corticosteroid治療"],"answer":2,"image":""},{"id":"md3-114-1-28","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"有關腎絲球過濾率（glomerular filtration rate）自我調節（autoregulation）的三個調控因素中，下列敘述何者正確？","options":["(A) 作用於出球小動脈（efferent arteriole）的自主性肌源反射（autonomous myogenic reflex）","(B) 腎小管–腎絲球回饋機轉（tubuloglomerular feedback）","(C) 血管收縮素II（angiotensin II）作用於入球小動脈（afferent arteriole）的血管收縮","(D) 前列腺素E1（prostaglandin E1）作用於出球小動脈（efferent arteriole）的血管擴張"],"answer":1,"image":""},{"id":"md3-114-1-29","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"下列有關慢性腎臟病的敘述，何者最不適當？","options":["(A) 高血壓乃目前臺灣新發生長期透析（incident dialysis）病患最主要之原發病因","(B) 慢性腎臟病患合併糖尿病，其血壓值應控制在130/80 mmHg以下","(C) 心血管疾病為最常造成慢性腎臟病患死亡的原因","(D) 低蛋白飲食可以改善尿毒症狀，但可能會增加營養不良的風險"],"answer":0,"image":""},{"id":"md3-114-1-30","subject":"md3","topic":"內科-腫瘤","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"下列有關腫瘤溶解（tumor lysis）所造成之電解質或代謝異常表現，何者最不常見？","options":["(A) hyperphosphatemia","(B) hyperuricemia","(C) hypocalcemia","(D) hyponatremia"],"answer":3,"image":""},{"id":"md3-114-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"關於退化性關節炎（osteoarthritis, OA）的描述，下列何者最適當？","options":["(A) 最常發生OA的部位包括手部的metacarpophalangeal joints、手腕關節和膝關節","(B) 造成OA的危險因素包括increased age、genetic susceptibility和obesity","(C) OA的關節X光變化包括narrowed joint space和bone erosion","(D) tumor necrosis factor（TNF）在致病機轉扮演重要角色，因此anti-TNF藥物對OA的治療效果很好"],"answer":1,"image":""},{"id":"md3-114-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"關於一些遺傳性的autoinflammatory disease（例如familial Mediterranean fever）之描述，下列何者最適當？","options":["(A) autoinflammatory disease可以起因於pyrin、p55 TNF receptor或NLRP3基因的突變","(B) 目前發現的基因突變均屬於隱性（recessive）遺傳，因此個案數很少","(C) 發炎體（inflammasome）的活化直接造成interleukin-2（IL-2）的分泌過多而產生發燒和關節炎的症狀","(D) 血中的interleukin-1（IL-1）濃度會上升，但IL-1抑制劑的治療效果通常不好而需要使用glucocorticoid來治療"],"answer":0,"image":""},{"id":"md3-114-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"50歲女性罹患類風濕性關節炎多年，長期服用methotrexate每週15毫克、hydroxychloroquine每天400毫克與低劑量類固醇控制，但仍有許多關節腫痛，抽血檢驗發現發炎指數越來越高，考慮加上生物製劑治療，下列何種藥物治療最適當？","options":["(A) secukinumab","(B) ustekinumab","(C) ixekizumab","(D) tocilizumab"],"answer":3,"image":""},{"id":"md3-114-1-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"李小姐20歲，因為全身皮膚癢疹，由家人帶來求診，想知道是否對某種東西過敏而發癢。由病史得知，病人從小就常有鼻竇炎，每年至少發生3～4次，也長期有腹瀉問題，5年前還曾因嚴重腹瀉住院，培養出Giardia lamblia，而使用metronidazole治療。下列何項處置對確認病因最有幫助？","options":["(A) 檢驗allergen-specific IgE","(B) 檢驗血中IgG、IgA、IgM","(C) 檢驗allergen skin testings","(D) 檢驗serum albumin、prealbumin及transferrin"],"answer":1,"image":""},{"id":"md3-114-1-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"下列何者是antiphospholipid syndrome最常出現的臨床表現？","options":["(A) deep vein thrombosis","(B) retinal artery thrombosis","(C) pre-eclampsia","(D) Libman-Sacks endocarditis"],"answer":0,"image":""},{"id":"md3-114-1-36","subject":"md3","topic":"內科-腫瘤","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"有關Ewing氏肉瘤（Ewing's sarcoma）之臨床病理特徵，下列敘述何者錯誤？","options":["(A) 常好發於長端骨頭之diaphyseal區域","(B) platelet-derived growth factor receptor-α（PDGFRA）是最常見的基因異常","(C) CT影像可以看到onion peel表徵","(D) 最常轉移的地方是肺部和其他骨頭區域"],"answer":1,"image":""},{"id":"md3-114-1-37","subject":"md3","topic":"內科-腫瘤","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"一位38歲停經前女性，因左側有一乳房腫塊併背部強烈疼痛就診，左側乳房腫瘤經病理切片證實為estrogen receptor陽性和HER2陰性之侵襲性乳癌，經過全身影像檢查後，證實有骨頭轉移但無肝臟及肺臟轉移。下列治療處方，何者最不適宜？","options":["(A) oophorectomy","(B) tamoxifen","(C) GnRH agonist","(D) aromatase inhibitor"],"answer":3,"image":""},{"id":"md3-114-1-38","subject":"md3","topic":"內科-腫瘤","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"有關胃腸道或胰臟神經內分泌細胞瘤（neuroendocrine tumor, NET）的病理診斷，下列敘述何者正確？","options":["(A) chromogranin A的免疫組織染色，有助於NET的診斷","(B) synaptophysin的染色呈陽性，可排除NET的診斷","(C) 若腫瘤細胞serotonin及substance P的免疫組織染色呈陽性，即可證實病患的腫瘤會分泌serotonin及substance P並造成臨床表現的症候群（clinical syndrome）","(D) 根據NET腫瘤細胞的分化程度可分成low grade（G1）、intermediate grade（G2）及high grade（G3）。一般將G1稱為well-differentiated NET，G2及G3稱為poorly-differentiated NET"],"answer":0,"image":""},{"id":"md3-114-1-39","subject":"md3","topic":"內科-腫瘤","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"亞洲人最常見的皮膚惡性黑色素細胞癌（malignant melanoma）屬於下列那一分型：","options":["(A) 表淺擴散型（superficial spreading）","(B) 結節型（nodular）","(C) 惡性小痣型（lentigo maligna）","(D) 肢端小痣型（acral lentiginous）"],"answer":3,"image":""},{"id":"md3-114-1-40","subject":"md3","topic":"內科-腫瘤","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"關於腎細胞癌（renal cell carcinoma）的敘述，下列何者錯誤？","options":["(A) 腎細胞癌最常見的組織型是乳突（papillary tumor）型","(B) 腎細胞癌合併高鈣血症，可能是骨骼轉移或是paraneoplastic症候群","(C) 對於第一期、第二期病人的標準治療是根除性（radical）或局部（partial）腎切除術（nephrectomy）","(D) 對於第一期、第二期病人如果腎功能不佳或只有一顆腎臟，根據腎細胞癌的大小、位置，可以考慮腎元保留（nephron-sparing）手術"],"answer":0,"image":""},{"id":"md3-114-1-41","subject":"md3","topic":"內科-血液","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"下列有關acute lymphoblastic leukemia之免疫治療敘述，何者最不適當？","options":["(A) inotuzumab ozogamicin是一種抗CD19的抗體並接合細胞毒物，可以有效治療復發或是頑強的acute lymphoblastic leukemia","(B) blinatumomab是一種雙特異性的抗體，同時辨識CD3（T細胞）與CD19（B細胞），可以有效治療B- lineage acute lymphoblastic leukemia","(C) chimeric antigen receptor（CAR）T cells可以設計成針對CD19抗原，用於治療復發或是頑強且帶有CD19的acute lymphoblastic leukemia","(D) chimeric antigen receptor（CAR）T cells的治療可能造成cytokine release syndrome（CRS）之副作用，症狀可能包括發燒、低血壓與神智不清"],"answer":0,"image":""},{"id":"md3-114-1-42","subject":"md3","topic":"內科-血液","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"下列有關HbH disease的敘述，何者錯誤？","options":["(A) 是一種β thalassemia","(B) 臨床上常伴隨溶血的表現","(C) 在成人會有β4 tetramer的形成","(D) 成年病人其HbA的生成，約為正常人的25～30%"],"answer":[0,3],"image":"","answer_note":"更正:第42題答Ａ或Ｄ或AD者均給分"},{"id":"md3-114-1-43","subject":"md3","topic":"內科-血液","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"下列何者最不會導致葉酸缺乏？","options":["(A) 酗酒","(B) 高胱胺酸尿症（homocysteinuria）","(C) 孕婦","(D) 血清偵測到高效價的抗胃壁細胞抗體（gastric parietal cell antibody）"],"answer":3,"image":""},{"id":"md3-114-1-44","subject":"md3","topic":"內科-血液","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"有關ABO血型不同的輸血，下列敘述何者正確？","options":["(A) A型紅血球輸入O型病人體內所造成的溶血反應，主要是經由免疫球蛋白G（IgG）的抗原抗體反應所造成","(B) 在緊急的時候，A型的血小板濃縮液仍不可以輸入O型的病人體內","(C) 在緊急的時候，A型的紅血球濃縮液仍不可以輸入O型的病人體內","(D) O型兒子的紅血球可以不經過任何處理輸入其A型親生母親的體內"],"answer":2,"image":""},{"id":"md3-114-1-45","subject":"md3","topic":"內科-胸腔","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"有關hypersensitivity pneumonitis，下列敘述何者最適當？","options":["(A) 因吸入環境中的抗原導致肺泡及小呼吸道發炎","(B) 肺功能檢查是最有效的診斷工具","(C) 血液中precipitating IgG antibody against specific antigen是診斷的標準","(D) bronchoalveolar lavage出現lymphocytosis是診斷的唯一標準"],"answer":0,"image":""},{"id":"md3-114-1-46","subject":"md3","topic":"內科-胸腔","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"65歲男性病人因運動時呼吸困難前來就診，其肺功能檢查顯示：FEV1/FVC 58%，FEV1為70%預測值，DLCO為55%預測值，則最有可能之診斷為何？","options":["(A) 氣喘","(B) 肺血管栓塞","(C) 肺氣腫","(D) 肺纖維化"],"answer":2,"image":""},{"id":"md3-114-1-47","subject":"md3","topic":"內科-感染","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"關於潛伏結核感染（latent TB infection）的相關敘述，下列何者最為適當？","options":["(A) 當結核菌素皮膚測驗（tuberculin skin test）呈現陽性時，代表人體對於結核菌產生延遲性過敏反應（delayed-type hypersensitivity），可保護人體免於再被結核菌感染（reinfection）","(B) 丙型干擾素血液測驗（interferon-γ release assay）可用來預測潛伏結核感染者是否會發展成為活動性肺結核","(C) 結核菌素皮膚測驗（tuberculin skin test）及丙型干擾素血液測驗（interferon-γ release assay），可用來區分潛伏結核感染或活動性肺結核","(D) 即使結核菌素皮膚測驗（tuberculin skin test）為陰性，也無法診斷此受試者並未被結核菌感染"],"answer":3,"image":""},{"id":"md3-114-1-48","subject":"md3","topic":"內科-胸腔","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"關於肋膜積水（pleural effusion）的描述，下列何者最為適當？","options":["(A) 肺癌所致的肋膜積水為exudate，且積水中的glucose濃度為正常","(B) 結核性肋膜積水為exudate，積液中的細胞通常以淋巴球最常見","(C) 乳糜胸（chylothorax）的定義為肋膜積水中膽固醇大於110 mg/dL","(D) 血胸（hemothorax）的定義為肋膜積水中血紅素大於10 g/dL"],"answer":1,"image":""},{"id":"md3-114-1-49","subject":"md3","topic":"內科-胸腔","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"48歲女性抽菸30年有嚴重的肺氣腫，這次住院因為感冒後喘的情形加重，動脈血中CO2上升，主治醫師決定給與非侵襲性正壓呼吸器（non-invasive ventilator），下列敘述何者錯誤？","options":["(A) 在慢性阻塞性肺病（chronic obstructive pulmonary disease）的病人，非侵襲性正壓呼吸器在急性發作時使用，可以降低加護病房住院天數","(B) 意識不清的病人適合使用非侵襲性正壓呼吸器","(C) 須使用密封的面罩以避免漏氣，所以臉部（特別是下半部）畸形或是受傷的病人不適合使用","(D) 因為不方便讓痰液排出，痰量太多的病人，不適合使用非侵襲性正壓呼吸器"],"answer":1,"image":""},{"id":"md3-114-1-50","subject":"md3","topic":"內科-胸腔","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"一位56歲男性病患，身高162 cm，體重89 kg，主訴運動時呼吸困難，血壓偏高控制不好，睡眠頻頻中斷，造成白天嗜睡，精神不濟，記憶衰退。休息時血氧濃度都在85%以下，動脈血中的PaCO2 51mmHg，為呼吸性酸中毒。對於此病患的臨床判斷，下列何者最不適當？","options":["(A) 應安排睡眠多項生理檢驗（sleep polysomnography），診斷是否有睡眠呼吸中止症（obstructive sleep apnea）","(B) 病患呼吸困難又有呼吸性酸中毒，因此可以判定是慢性阻塞性肺病（chronic obstructive pulmonary disease）","(C) 造成呼吸低下症候群（hypoventilation syndrome）的原因很多，不完全是因為肥胖所造成","(D) 有時會發現這類病患呼吸中樞反應有障礙"],"answer":1,"image":""},{"id":"md3-114-1-51","subject":"md3","topic":"急診醫學","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"下列何者所導致的休克狀態，周邊血管阻抗（systemic vascular resistance）的改變與其他三者明顯不同？","options":["(A) 進行電腦斷層掃描時注射顯影劑發生過敏","(B) 病毒性心肌炎","(C) 嚴重脊髓損傷","(D) 金黃色葡萄球菌敗血症"],"answer":1,"image":""},{"id":"md3-114-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"下列何者最不可能是甲狀腺結節病患發生甲狀腺癌之危險因子？","options":["(A) 年齡介於20至50歲之女性","(B) 合併頸部單側淋巴結病變","(C) 頭頸部曾接受放射線治療","(D) 聲音沙啞合併聲帶麻痺"],"answer":0,"image":""},{"id":"md3-114-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"多發性內分泌腫瘤2A型（Multiple endocrine neoplasia 2A, MEN 2A）會以甲狀腺髓質癌、嗜鉻細胞瘤及副甲狀腺腺瘤做為臨床表現。MEN 2A型最常見之基因突變密碼（mutated codon）是下列何者？","options":["(A) RET 634","(B) RET 918","(C) RET 618","(D) CDKN1B"],"answer":0,"image":""},{"id":"md3-114-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"下列何者不是降低血糖的用藥？","options":["(A) metformin","(B) glargine","(C) glucagon","(D) degludec"],"answer":2,"image":""},{"id":"md3-114-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"關於肥胖之敘述，下列何者錯誤？","options":["(A) 與肥胖相關的內分泌疾病包含甲狀腺功能異常","(B) 臺灣人男、女性肥胖腰圍切點皆為90公分","(C) 庫欣氏症候群（Cushing's syndrome）會有肥胖的表現","(D) 第二型糖尿病與肥胖有關"],"answer":1,"image":""},{"id":"md3-114-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"關於糖尿病酮酸中毒（diabetic ketoacidosis）之敘述，下列何者錯誤？","options":["(A) 大多發生於第一型糖尿病（type 1 diabetes mellitus）病人","(B) 初始治療應注射一劑每公斤體重1單位常規胰島素（regular insulin），以快速降血糖","(C) 感染是誘發此症之常見原因","(D) 起始輸液治療，於前1～3小時，通常需給與2～3公升之0.9%食鹽水"],"answer":1,"image":""},{"id":"md3-114-1-57","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"一位65歲女性，40年前生產時有大出血，這次因為泌尿道感染、發燒、意識不清被送來急診。她血壓為85/45 mmHg，心跳每分鐘125下，對於大量靜脈輸液灌注與升壓劑反應不良，其血鈉亦過低，強烈懷疑有腎上腺機能不足的危症（adrenal crisis）。此刻下列何種診治最合適？","options":["(A) 立刻抽血測量ACTH和cortisol，等待檢查結果，確定異常再給與hydrocortisone治療","(B) 抽血測量8AM和4PM的ACTH和cortisol，等待檢查結果，確定異常再給與hydrocortisone治療","(C) 立刻抽血送ACTH和cortisol檢驗，一抽完血不等待檢驗結果，就給與hydrocortisone治療","(D) 立刻進行cosyntropin test（即ACTH stimulation test），等待檢查結果，確定異常再給與hydrocortisone治療"],"answer":2,"image":""},{"id":"md3-114-1-58","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"下列何者不是對甲狀腺風暴（thyroid storm）引起心房顫動、心搏過速、心衰竭患者的建議用藥？","options":["(A) propylthiouracil或methimazole","(B) hydrocortisone","(C) saturated solution of potassium iodide","(D) amiodarone"],"answer":3,"image":""},{"id":"md3-114-1-59","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"80歲男性，胃潰瘍出血，呼吸衰竭使用呼吸器，預防呼吸器相關肺炎及併發症的措施，下列何者最不適當？","options":["(A) 床頭抬高30至45度","(B) 若使用鎮定劑須每日中斷評估（sedation vacation）","(C) 使用抗凝血劑預防靜脈栓塞（venous thromboembolism）","(D) 每日評估是否拔管"],"answer":2,"image":""},{"id":"md3-114-1-60","subject":"md3","topic":"內科-感染","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"下列有關β-lactamase抗藥性基因及其作用機轉的敘述，何者錯誤？","options":["(A) AmpC抗藥性基因常存在於Enterobacter spp.染色體上","(B) 存在於K. pneumoniae染色體上的β-lactamase基因比較傾向於水解cephalosporins而非penicillins","(C) cefoxitin及cefepime對於AmpC是比較穩定不容易被水解的cephalosporins","(D) 如果對cefepime產生抗藥性，常見是因為AmpC加上另一個抗藥機轉，如porin diffusion通道減少"],"answer":1,"image":""},{"id":"md3-114-1-61","subject":"md3","topic":"內科-感染","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"下列何種病毒最不可能造成急性腦炎？","options":["(A) 腸病毒（enterovirus）","(B) 巨細胞病毒（cytomegalovirus）","(C) 第6型人類疱疹病毒（human herpesvirus 6）","(D) 卡波西氏肉瘤疱疹病毒（Kaposi's sarcoma-associated herpesvirus, human herpesvirus 8）"],"answer":3,"image":""},{"id":"md3-114-1-62","subject":"md3","topic":"內科-感染","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"30歲男性，因尿道炎入院治療，尿液經細菌培養並未發現致病細菌，接受口服cefixime治療多次效果不佳，後續發生副睪炎（epididymitis）和嚴重的潰瘍性直腸和大腸發炎出血（ulcerative, hemorrhagic proctocolitis），腹股溝淋巴腺逐日腫大和潰瘍與下肢淋巴水腫。經過核酸增幅檢測（nucleic acid amplification test），發現是披衣菌（Chlamydia）感染，臨床醫師的診斷是lymphogranuloma venereum。下列關於此疾病的病因與處置之敘述，何者錯誤？","options":["(A) 致病原是Chlamydia trachomatis LGV serovars L1、L2及L3","(B) 致病原是Chlamydia psittaci","(C) 可以採用三週doxycycline（100 mg每日口服兩次）治療","(D) 可以採用三週erythromycin base（500 mg每日口服四次）治療"],"answer":1,"image":""},{"id":"md3-114-1-63","subject":"md3","topic":"內科-感染","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"關於人類免疫不全病毒（HIV）感染所致免疫系統缺損引起的伺機性感染（opportunistic infections）與首選治療之配對，下列何者錯誤？","options":["(A) non-typhoid salmonellosis — ceftriaxone","(B) oral candidiasis — fluconazole","(C) cytomegalovirus retinitis — valacyclovir","(D) cryptococcal meningitis — amphotericin B + flucytosine"],"answer":2,"image":""},{"id":"md3-114-1-64","subject":"md3","topic":"內科-胸腔","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"關於社區型肺炎的治療結果，下列敘述何者錯誤？","options":["(A) 在有效治療下，一般可在2～4天退燒","(B) 在有效治療下，胸部X光檢查病灶一般可在7天內完全消失","(C) 需住院之社區型肺炎患者，一般死亡率約12～40%","(D) 若後續胸部X光追蹤又再次發現病灶在相同地方（relapse or recurrence），須懷疑是否有癌症的可能性"],"answer":1,"image":""},{"id":"md3-114-1-65","subject":"md3","topic":"內科-心臟血管","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"下列何者最不需要於牙科手術前接受預防性抗生素以避免心內膜炎？","options":["(A) 具人工瓣膜（prosthetic heart valves）","(B) 之前曾得過心內膜炎（endocarditis）","(C) 先天性心臟病經完整修復術6個月以後","(D) 未修復之發紺性先天性心臟病（cyanotic congenital heart disease）"],"answer":2,"image":""},{"id":"md3-114-1-66","subject":"md3","topic":"家醫-行為與社區醫學","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"以生理心理社會模式（biopsychosocial model）來看代謝症候群的病因，下列敘述何者最適當？","options":["(A) 代謝症候群是生活型態病，與基因遺傳無明顯相關","(B) 有精神疾病的人較容易導致代謝症候群","(C) 社會經濟地位（socioeconomic status）較低者，較不易導致代謝症候群","(D) 後天因素胎兒營養失調（fetal malnutrition）之低出生體重者，較不易導致代謝症候群"],"answer":1,"image":""},{"id":"md3-114-1-67","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"關於譫妄（delirium）的敘述，下列何者最適當？","options":["(A) 譫妄是一種慢性且病程波動起伏的疾病","(B) 譫妄的致病機轉明確，造成譫妄的原因相對單純","(C) 譫妄的精神症狀治療藥物，同時也可以治療其潛在疾病","(D) 評估工具可使用混亂評估方法（Confusion Assessment Method, CAM）"],"answer":3,"image":""},{"id":"md3-114-1-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"下列有關吸菸、酗酒、缺乏運動、不好的飲食習慣等不健康行為與家庭關係的敘述，何者錯誤？","options":["(A) 這些行為的養成與家庭有關","(B) WHO強調家庭是健康促進最主要的社會因素","(C) 社會型態改變導致外食增加，飲食習慣仍會受到家庭其他成員的影響","(D) 如果父母或兄長吸菸，青少年吸菸的機會增加兩倍"],"answer":3,"image":""},{"id":"md3-114-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"利用篩檢工具進行隨機雙盲分組研究，發現有篩檢組的死亡人數為每千人有4位，未篩檢組的死亡人數為每千人有8位，顯示可以降低50%的疾病死亡率（RR= 0.5），此項篩檢工具的number needed to screen（NNS）應該是多少？","options":["(A) 4","(B) 125","(C) 250","(D) 500"],"answer":2,"image":""},{"id":"md3-114-1-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"根據美國預防醫學工作小組（U.S. Preventive Services Task Force）的建議，關於骨質疏鬆症的篩檢，下列何者最適當？","options":["(A) 對於65歲（含）以上婦女，建議篩檢","(B) 對於50歲（含）以上所有停經婦女，建議篩檢","(C) 對於65歲（含）以上男性，建議篩檢","(D) 對於50歲（不含）以下所有男性或女性，均不建議篩檢"],"answer":0,"image":""},{"id":"md3-114-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"動機性晤談（motivational interviewing, MI）是一種有效的工具，晤談進行過程的主要指導原則，下列敘述何者最不適當？","options":["(A) 抵抗自己的「更正反射」（resist the “righting reflex”）：儘量做到讓自己在諮商過程不要試圖更正對方，也不要給對方建議","(B) 規劃病人的動機（planning patient's motivation）：為個別病人打造、規劃明確的改變動機","(C) 聆聽病人（listen to your patient）：使用同理心和主動傾聽技巧，改變「醫務人員才是對的」的心態","(D) 賦權病人（empower your patient）：促進病人積極參與自身照護，並對改變過程承擔責任，可爭取更好的療效"],"answer":1,"image":""},{"id":"md3-114-1-72","subject":"md3","topic":"內科-腎臟","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"陳醫師參與社區醫療群，執行全民健康保險初期慢性腎臟病醫療方案，有一個案58歲古先生糖尿病病史12年，常主訴肩頸痠痛，腎絲球過濾率（estimated glomerular filtration rate, eGFR）56 mL/min/1.73 2 m，白蛋白尿（urine albumin/creatinine ratio, UACR）380 mg/g，有關慢性腎臟病，下列敘述何者錯誤？2","options":["(A) 演進成為末期腎臟病的風險高於eGFR 40 mL/min/1.73 m且UACR 28 mg/g的病人","(B) 屬於慢性腎臟病stage 3a","(C) 長期服用非類固醇止痛消炎藥（nonsteroid anti-inflammatory drugs, NSAIDs）會惡化慢性腎臟病","(D) 不應繼續使用metformin"],"answer":3,"image":""},{"id":"md3-114-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"關於緩解末期癌症病人食慾不振的建議，下列敘述何者最不適當？","options":["(A) 控制不佳的疼痛，會降低病人的食慾，疼痛若改善，通常食慾不佳也會緩解","(B) 輕度噁心、口腔念珠菌症和便秘均會影響進食，但通常可以有效治療","(C) 可以考慮額外增加每日靜脈營養輸液750～1000 mL，以協助緩解病人的口乾及食慾不振","(D) 皮質類固醇和megestrol對有些病人有益，但可能會引起副作用"],"answer":2,"image":""},{"id":"md3-114-1-74","subject":"md3","topic":"影像醫學","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"65歲男性病人，主訴腎功能不良，常規腹部Ｘ光片（KUB）顯示如附圖。下列何者為最可能的診斷？","options":["(A) 腎水腫（renal hydronephrosis）","(B) 腎膿瘍（renal abscess）","(C) 晚期腎結核（renal tuberculosis, late stage）","(D) 腎細胞癌（renal cell carcinoma）"],"answer":2,"image":"md3-114-1-74.jpeg"},{"id":"md3-114-1-75","subject":"md3","topic":"影像醫學","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"下列何者影像徵象最不傾向於活動性肺結核（active TB）？","options":["(A) 比較系列影像之後，該病灶為新出現的病灶","(B) X光片影像出現開洞（cavitation）的病灶","(C) 該病灶在X光片上出現界線不明確（ill-defined）的徵象","(D) 該病灶鈣化程度明顯，呈現近乎完全鈣化現象"],"answer":3,"image":""},{"id":"md3-114-1-76","subject":"md3","topic":"內科-感染","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"下列有關接觸到有狂犬病（rabies）動物的描述，何者得到狂犬病的機率最低？","options":["(A) 口腔黏膜接觸到動物的尿液","(B) 口腔黏膜接觸到動物的唾液","(C) 皮膚傷口接觸到動物的唾液","(D) 肢體或臉部被動物咬傷"],"answer":0,"image":""},{"id":"md3-114-1-77","subject":"md3","topic":"急診醫學","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"36歲男性體重60公斤，因工作壓力大常常頭痛，此次頭痛很厲害，在治療無效下共吃了20顆acetaminophen（500 mg），在他吃藥4小時後被送到醫院就診，下列何者最不適當？","options":["(A) 給與N-acetylcysteine治療","(B) 用activated charcoal洗胃","(C) 檢查肝功能指數","(D) 檢查acetaminophen血中濃度"],"answer":1,"image":""},{"id":"md3-114-1-78","subject":"md3","topic":"急診醫學","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"下列何者不是高山肺水腫（high-altitude pulmonary edema）發生的危險因子？","options":["(A) 登山活動量大","(B) 爬升的速度快","(C) 低鹽飲食","(D) 使用安眠藥"],"answer":2,"image":""},{"id":"md3-114-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"醫師考量病人的生活品質，主要依據何種倫理原則？①自主原則 ②行善原則 ③不傷害原則 ④保密原則","options":["(A) 僅①②③","(B) 僅②③","(C) 僅①","(D) ①②③④"],"answer":0,"image":""},{"id":"md3-114-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"一位78歲男性患者平常相當健康，還可以從事許多農事。最近一個多月，因為多次血便求診。大腸鏡檢查發現乙狀結腸有一腫瘤，切片檢查證實為腺癌。醫師於門診告知需住院接受手術治療。病患家屬要求醫師隱瞞病情，同時在討論後，代替病患拒絕了手術的建議，決定尋求其他偏方治療。下列敘述何者錯誤？","options":["(A) 病患為成年人，而且意識清楚，家屬並沒有權利要求醫師隱瞞病情","(B) 病患為成年人，而且意識清楚，家屬並沒有權利幫病患拒絕手術的建議","(C) 醫師應該充分尊重家屬的意見，隱瞞相關病情，並同意家屬拒絕醫療的決定","(D) 醫師應該與家屬溝通，讓家屬了解病患本身才有權利決定其治療方針，同時應該將相關病情告知患者"],"answer":2,"image":""},{"id":"md3-114-2-1","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"下列有關致癌因子（carcinogen）及其可能誘發的病變，何者最不適當？","options":["(A) estrogen可能誘發子宮內膜癌（endometrial cancer）","(B) human papilloma virus可能誘發子宮頸癌（cervical cancer）","(C) schistosomiasis可能誘發膀胱癌（bladder cancer）","(D) Helicobacter pylori可能誘發肺癌（lung cancer）"],"answer":3,"image":""},{"id":"md3-114-2-2","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"厭食症（anorexia nervosa）的病人最不常有下列何表現？","options":["(A) 低血壓","(B) 低血糖","(C) 腹瀉","(D) cortisol增加"],"answer":2,"image":""},{"id":"md3-114-2-3","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"有關急性痛風性關節炎之建議用藥，下列何者最不適當？","options":["(A) nonsteroidal anti-inflammatory drugs（NSAIDs）","(B) colchicine","(C) glucocorticoids","(D) allopurinol"],"answer":3,"image":""},{"id":"md3-114-2-4","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"一位90歲女性巴金森氏症（Parkinson's disease）病友因肺炎住院，住院後發現有意識混亂、注意力無法集中之情況，有時答非所問，有時嗜睡不易叫醒，有時認不得家人，更時常半夜失眠吵鬧，狀況時好時壞，一天中起伏很大；住院前並無此種現象。欲確診其目前病況，下列何種工具之敏感度（sensitivity）與特異度（specificity）最佳？","options":["(A) Confusion Assessment Method","(B) Clinical Dementia Rating","(C) Mini-Cog test","(D) Mini-Mental Status Examination"],"answer":0,"image":""},{"id":"md3-114-2-5","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"一位60歲男性，有吸菸嚼食檳榔習慣，主訴有頭暈、食慾差、倦怠、體重減輕與便秘等症狀。身體診察發現脫水現象，實驗室檢查發現高血鈣（3.1 mmol/L）、低血磷（2.1 mg/dL）及腎功能不全（血液尿素氮57 mg/dL、肌酸酐2.3 mg/dL）。其血清中白蛋白（albumin 3.0 g/dL）及副甲狀腺激素（parathyroid hormone 7.7 pg/mL）濃度皆低於正常參考值。下列敘述何者最不適當？","options":["(A) 校正後血清鈣濃度為3.9 mmol/L","(B) 有可能是惡性腫瘤的併發症","(C) 牛奶–鹼劑症候群（milk-alkali syndrome）有可能是本病人之病因","(D) 可利用生理食鹽水（normal saline）利尿，以促進鈣的排泄"],"answer":0,"image":""},{"id":"md3-114-2-6","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"下列關於經皮冠狀動脈介入（percutaneous coronary intervention, PCI）術前、術中、術後使用之抗凝血、抗血小板藥物之敘述，何者錯誤？","options":["(A) 若已知病人將接受PCI且未曾服用抗血小板藥物，術前應給與aspirin 325 mg及clopidogrel 600 mg以降低術中血栓併發症風險","(B) 若經植入第二代或更新的藥物塗層冠狀動脈金屬支架，因其晚期支架內血栓之風險較低，故術後血小板雙抗藥物治療（dual antiplatelet therapy）可於6個月後停止","(C) PCI術中為預防血栓形成，須以傳統肝素、低分子肝素、或第一凝血因子（fibrinogen）抑制劑預防凝血","(D) 在急性心肌梗塞且冠狀動脈內有大量血栓存在時，可靜脈投與醣蛋白IIb/IIIa受體抑制劑"],"answer":2,"image":""},{"id":"md3-114-2-7","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"胡先生72歲，有抽菸（每天1包），並患有糖尿病、高血壓，於心臟科門診定期追蹤治療。原本只要兩種高血壓用藥便可將血壓維持在130/80 mmHg，但近期血壓不時高至200/130 mmHg，病人體重、食慾並無明顯變化，身體診察發現下肢血壓高於上肢血壓，驗血serum creatinine從原本1.2 mg/dL上升至2.0 mg/dL，鉀離子為3.5 mmol/L，若懷疑病人為續發性高血壓，最可能診斷為何？","options":["(A) 高醛固酮症（hyperaldosteronism）","(B) 腎動脈狹窄","(C) 庫欣氏症候群（Cushing syndrome）","(D) 甲狀腺亢進"],"answer":1,"image":""},{"id":"md3-114-2-8","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"下列有關高血壓藥物治療的敘述，何者錯誤？","options":["(A) 高血壓合併左心室功能異常的病人，選用利尿劑、angiotensin-converting enzyme inhibitor、angiotensin receptor blocker或β-blocker皆可","(B) 高血壓合併蛋白尿的病人，宜優先選用β-blocker或利尿劑","(C) ＜50歲的單純高血壓病人，可優先選用angiotensin-converting enzyme inhibitor","(D) ＞80歲的單純高血壓病人，可優先選用利尿劑及鈣離子阻斷劑"],"answer":[0,1],"image":"","answer_note":"更正:第8題答Ａ或Ｂ或AB者均給分"},{"id":"md3-114-2-9","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"馬伯伯1年前因為急性心肌梗塞導致心臟功能受損，需要長期服藥控制。最近因天氣炎熱，每天都喝很多冰水消暑。但是他慢慢覺得走路不到10公尺就喘得很厲害，小腿也比以前腫脹，即使沒有活動整天看電視也覺得很容易疲勞。到了半夜睡覺的時候，常常因為喘而需要坐起來，一整夜需起來5、6次，睡眠品質相當不好。馬伯伯的症狀中，那一項較不屬於典型心臟衰竭的臨床表現？","options":["(A) 喝很多冰水消暑","(B) 小腿比以前腫脹","(C) 整天覺得很疲勞","(D) 半夜睡覺的時候，常常因為喘而需要坐起來"],"answer":0,"image":""},{"id":"md3-114-2-10","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"一位35歲的男性病人懷疑是白袍高血壓（white coat hypertension），下列何項診斷工具對鑑別診斷或病情評估的幫助可能最小？","options":["(A) 24小時行動血壓計","(B) 居家血壓監測","(C) 心臟超音波","(D) 運動心電圖"],"answer":3,"image":""},{"id":"md3-114-2-11","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"一位24歲女性，其哥哥及弟弟均在青年時期因昏倒猝死送醫不治，本身過去並無重大疾病史，此次在坐雲霄飛車時昏厥被送至急診，心電圖如下圖，下列敘述何者錯誤？","options":["(A) 應詳盡地詢問病患的過去用藥史，並抽血檢驗血液中的電解質是否正常","(B) 依病患心電圖所顯現，可能心肌鈉離子或鉀離子通道異常而導致action potential的時間延長所致","(C) 如診斷為genetic arrhythmia syndrome，不同基因型也會影響疾病的預後","(D) 放置implantable cardioverter-defibrillator（ICD）對於這類病患都不能有效的改善預後"],"answer":3,"image":"md3-114-2-11.jpeg"},{"id":"md3-114-2-12","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"一位60歲女性，高血壓病人，經藥物治療3個月控制穩定，血壓已降至130/85 mmHg左右。最近一個月，常有突發性劇烈乾咳，肺部聽診正常，胸部X光亦正常。下列何種處置應最優先？","options":["(A) 立即開立化痰藥水","(B) 立即開立氣管擴張劑","(C) 詢問使用何種高血壓藥物","(D) 安排胸部斷層攝影"],"answer":2,"image":""},{"id":"md3-114-2-13","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"關於冠狀動脈疾病（coronary artery disease）合併穩定心絞痛病人的藥物治療，下列敘述，何者正確？","options":["(A) 如無禁忌症，乙型交感神經阻斷劑（beta blocker）應優先使用，但曾發生心肌梗塞者除外","(B) 合併糖尿病或左心室功能不全者，均應給與血管張力素轉換酶抑制劑（angiotensin converting enzyme inhibitor），但要注意病人腎功能變化","(C) 鈣離子通道阻斷劑（calcium channel blocker）可有效降低血壓，但不應與長效硝化物（nitrate）合用，以免發生水腫","(D) dipyridamole可抑制血小板凝集，建議應常規給與"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第13題一律給分 (原公告答案 B)"},{"id":"md3-114-2-14","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"女性病人因近日胸悶及心悸至心臟科門診求診。病人過去並無內科或全身性病史。身體診察發現有輕微收縮期心雜音。心電圖與胸部X光檢查皆無異常。心臟超音波顯示心臟收縮功能正常，但卻發現有二尖瓣脫垂現象。下列敘述何者錯誤？","options":["(A) 常見於女性，好發年紀約40～60歲","(B) 心臟瓣膜黏液性（myxomatous）變化可能會影響到三尖瓣或主動脈瓣膜","(C) 可能與結締組織疾病有關，例如成骨不全症（osteogenesis imperfecta）","(D) 當病人因二尖瓣迴流出現心房顫動且發生缺血性中風時，應給與抗凝血藥物"],"answer":0,"image":""},{"id":"md3-114-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"陳先生平時工作忙碌，最近因腹痛及血便至醫院求診，經檢查後懷疑是克隆氏病（Crohn's disease）。關於Crohn's disease，下列敘述何者錯誤？","options":["(A) 腸道可能會出現瘻管（fistula）之併發症","(B) 腸道黏膜發炎多半為連續性病兆（continuous lesion），而非節段性病兆（segmental lesion）","(C) 不一定會侵犯直腸","(D) 經常會造成小腸狹窄或阻塞的後遺症"],"answer":1,"image":""},{"id":"md3-114-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"55歲肥胖男性因為胃酸逆流、胸口灼熱接受胃鏡檢查，結果如圖。下列敘述何者錯誤？","options":["(A) 減重有助症狀控制","(B) 質子幫浦抑制劑可改善症狀","(C) 一般的藥物治療（antisecretory treatment）無法使已發生metaplasia的黏膜逆轉回正常細胞","(D) 食道鱗狀細胞癌的風險增加"],"answer":3,"image":"md3-114-2-16.jpeg"},{"id":"md3-114-2-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"位於頭部之胰臟癌相對於體、尾部之胰臟癌較常見的症狀為何？","options":["(A) 黃疸","(B) 體重減低","(C) 腹痛","(D) 噁心嘔吐"],"answer":0,"image":""},{"id":"md3-114-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"一位54歲男性病人主訴倦怠、食慾差，過去肝炎史不詳，抽血生化檢查顯示：ALT（GPT）：1860 U/L、AST（GOT）：1256 U/L、total bilirubin：6.8 mg/dL、鹼性磷酸酶（alkaline phosphatase）：95 U/L（正常值＜100 U/L）。下列何者為最適宜之進一步檢查組合？","options":["(A) HBsAg，anti-HBs，anti-HBc","(B) anti-HBc，anti-HCV","(C) HBsAg，anti-HBs","(D) HBsAg，anti-HCV 2"],"answer":3,"image":""},{"id":"md3-114-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"60歲肥胖（BMI：27 kg/m）、有糖尿病史、不曾喝酒的婦女，於健康檢查接受腹部超音波檢查時發現脂肪肝。下列敘述，何者最不恰當？","options":["(A) 患者可以診斷為非酒精性脂肪肝病（non-alcoholic fatty liver disease, NAFLD），定義為肝臟裡面脂肪（主要是triglyceride）含量過高","(B) 腹部超音波檢查除了偵測脂肪浸潤（hepatic steatosis）外，也可同時偵測脂肪性肝炎（steatohepatitis）的存在","(C) 使用藥物如methotrexate, tamoxifen及glucocorticoid也可能造成脂肪肝","(D) 非酒精性脂肪肝病（non-alcoholic fatty liver disease, NAFLD）病患的AST及ALT數值可能有異常現象，但數值高低與組織學嚴重度無關"],"answer":1,"image":""},{"id":"md3-114-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"下列有關肝腎症候群（hepatorenal syndrome, HRS）的敘述，何者錯誤？","options":["(A) HRS常常發生於嚴重肝硬化而且合併難治性腹水（refractory ascites）的患者","(B) 第一型（type 1）HRS是一種急性而且在兩星期內快速惡化的腎衰竭","(C) HRS的發生與全身血管收縮阻力上升有關","(D) 一般而言，一旦發生HRS，患者預後極差，須依賴肝移植救治"],"answer":[2,3],"image":"","answer_note":"更正:第20題答Ｃ或Ｄ或CD者均給分"},{"id":"md3-114-2-21","subject":"md3","topic":"內科-感染","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"有關B型肝炎疫苗的敘述，下列何者錯誤？","options":["(A) anti-HBs至少大於100 mIU/mL才具有保護力","(B) 新生兒接種後，保護力至少5年，且可能達20年以上","(C) 免疫抑制中的個案，若是anti-HBs消失需要追加疫苗注射","(D) 血液透析患者，接種B型肝炎疫苗後，需要每年監測anti-HBs效價"],"answer":0,"image":""},{"id":"md3-114-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"60歲的病人因腹水住院，下列抽血及腹水檢查數值，何者最可能是肝硬化所引起的腹水？","options":["(A) 血中白蛋白（albumin）值3.1 g/dL，腹水的白蛋白（albumin）值2.1 g/dL，腹水的總蛋白（total protein）值2.3 g/dL","(B) 血中白蛋白（albumin）值4.3 g/dL，腹水的白蛋白（albumin）值2.6 g/dL，腹水的總蛋白（total protein）值3.0 g/dL","(C) 血中白蛋白（albumin）值2.8 g/dL，腹水的白蛋白（albumin）值2.0 g/dL，腹水的總蛋白（total protein）值2.8 g/dL","(D) 血中白蛋白（albumin）值2.8 g/dL，腹水的白蛋白（albumin）值1.2 g/dL，腹水的總蛋白（total protein）值2.0 g/dL"],"answer":3,"image":""},{"id":"md3-114-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"Esophageal motility disorders是導因於esophageal neuromuscular dysfunction，關於不同的esophageal motility disorders，下列敘述何者正確？","options":["(A) achalasia病因是loss of ganglion cells within the esophageal myenteric plexus，臨床罕見，發生率約為1/100,000，好發於60～80歲年邁族群","(B) eosinophilic esophagitis的臨床表徵是episode of dysphagia and chest pain，在X光攝影下可能呈現corkscrew esophagus、rosary bead esophagus、pseudodiverticula","(C) diffuse esophageal spasm的發生率逐年增加，其食道切片檢查可發現squamous epithelial eosinophil- predominant inflammation，其對口服類固醇的效果良好","(D) gastroesophageal reflux disease為相當盛行的文明病，其致病機轉包括transient lower esophageal sphincter（LES）relaxation、LES hypotension、anatomical distortion"],"answer":3,"image":""},{"id":"md3-114-2-24","subject":"md3","topic":"內科-腎臟","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"下列何者不是顯影劑造成急性腎傷害之機轉？","options":["(A) 腎臟外髓質部微循環系統之阻塞","(B) 腎小管上皮細胞毒性","(C) 腎小球微血管系統阻塞","(D) 暫時性腎小管阻塞 -+-"],"answer":2,"image":""},{"id":"md3-114-2-25","subject":"md3","topic":"內科-腎臟","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"一位病人的動脈血氣體分析結果：pH 7.30，PaCO2 32 mmHg，HCO3 16 mEq/L，血Na 136 mmol/L，血Cl ++- 100 mmol/L；尿Na 60 mmol/L，尿K 40 mmol/L，尿Cl 115 mmol/L，這是何種酸鹼平衡異常？","options":["(A) 高陰離子隙代謝性酸中毒","(B) 正常陰離子隙代謝性酸中毒","(C) 高陰離子隙代謝性酸中毒合併呼吸性鹼中毒","(D) 急性呼吸性酸中毒"],"answer":0,"image":""},{"id":"md3-114-2-26","subject":"md3","topic":"內科-腎臟","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"有關慢性末期腎臟病人鈣磷平衡的敘述，下列何者正確？","options":["(A) 這些病人血磷升高主要是因為腸道吸收磷的能力比正常人高","(B) 服用過多的鈣片或活性維生素D（vitamin D3），會引起adynamic bone disease","(C) 這些病人因為維生素D缺乏，因此應服用25（OH）vitamin D可以增加鈣的吸收，並抑制副甲狀腺素分泌","(D) 含有鋁的磷結合劑因為效果較差，不建議使用 +"],"answer":1,"image":""},{"id":"md3-114-2-27","subject":"md3","topic":"內科-腎臟","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"25歲男性病人，無自覺不適症狀，血壓160/100 mmHg、抽血檢驗發現血中creatinine 0.9 mg/dL、K 2.5 + - mEq/L、Na141 mEq/L，動脈血氣體分析（ABG）結果：pH 7.45、PaO2 101 mmHg、PaCO2 41 mmHg、HCO3 26 mEq/L。此病人最有可能的診斷為：","options":["(A) 牛奶–鹼症候群（milk-alkali syndrome）","(B) Gitelman's症候群","(C) 大腸腫瘤（villous adenoma）","(D) 鹽皮質素過多（mineralocorticoid excess） -"],"answer":3,"image":""},{"id":"md3-114-2-28","subject":"md3","topic":"內科-腎臟","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"一名低血鉀，高血壓病人，其靜脈血氣體分析結果：pH 7.45，HCO3 31 mEq/L，PvCO2 47 mmHg，尿鉀30 mmol/L，在鑑別診斷過程中，下列何種plasma renin activity及plasma aldosterone concentration組合最不可能出現？","options":["(A) plasma renin activity上升，plasma aldosterone concentration上升","(B) plasma renin activity上升，plasma aldosterone concentration下降","(C) plasma renin activity下降，plasma aldosterone concentration上升","(D) plasma renin activity下降，plasma aldosterone concentration下降"],"answer":1,"image":""},{"id":"md3-114-2-29","subject":"md3","topic":"內科-腎臟","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"下列預防血液透析中發生低血壓的措施，何者最適當？","options":["(A) 避免透析中進食","(B) 先透析後超過濾","(C) 保持透析液與體溫相近","(D) 使用生物相容性較高的人工腎臟"],"answer":0,"image":""},{"id":"md3-114-2-30","subject":"md3","topic":"內科-腎臟","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"一位54歲男性無過去病史，參加完馬拉松賽後隔天出現尿量減少（350 mL/day）合併肌肉痠痛，身體診察發現皮膚膨脹程度偏低（dry skin turgor）。實驗室檢查發現血清肌酸激酶（creatine kinase）58,000 U/L，尿素氮50 mg/dL，肌酸酐2.1 mg/dL。腎臟超音波檢查：腎臟大小無異常，也無水腎（hydronephrosis）。有關此病患之腎功能異常，下列敘述何者錯誤？","options":["(A) 若此病患之尿鈉排出分率（fractional excretion of sodium, FeNa）小於1%，則可確定脫水為造成腎衰竭之主因","(B) 此病患治療方式除積極補充靜脈輸液外，可考慮給與碳酸氫鈉（NaHCO3）溶液來鹼化尿液","(C) 若併發肺水腫、高血鉀、代謝性酸中毒，且藥物治療無效，則可考慮透析治療","(D) 應檢測血鉀、血鈉、血磷，並評估用藥史"],"answer":0,"image":""},{"id":"md3-114-2-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"一60歲女性，已有類風濕性關節炎5年，目前使用methotrexate 10 mg/週及plaquenil 200 mg/日，控制3良好；但近2週來，尤其在運動時突有右膝關節疼痛及積水，抽取關節液時，白血球數為800/mm。有關右膝疼痛的原因，下列何種診斷最有可能？","options":["(A) 類風濕性關節炎突然變成活躍（active）","(B) 藥物已無法控制之類風濕性關節炎","(C) 痛風","(D) 退化性關節炎"],"answer":3,"image":""},{"id":"md3-114-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"下列那一種腸道細菌的感染最不易誘發反應性關節炎（reactive arthritis）的發生？","options":["(A) Shigella","(B) Yersinia","(C) Clostridium","(D) Campylobacter"],"answer":2,"image":""},{"id":"md3-114-2-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"一位22歲女性病人主訴最近一個多月常無故發燒，也常覺得兩側手指及腕關節不舒服。開學體檢被發現有白血球及血小板減少現象，且有蛋白尿的情形。下列那一項檢查最容易出現陽性的結果？","options":["(A) anti-dsDNA antibodies","(B) anti-Smith antibodies","(C) antinuclear antibodies","(D) anticardiolipin antibodies"],"answer":2,"image":""},{"id":"md3-114-2-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"下列何種原發性免疫缺陷疾病（primary immunodeficiency diseases）是因為T淋巴細胞之CD40L基因異常所引起？","options":["(A) X-linked chronic granulomatous disease","(B) Wiskott-Aldrich syndrome","(C) common variable immunodeficiency","(D) X-linked hyper-IgM syndrome"],"answer":3,"image":""},{"id":"md3-114-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"有關血管炎的敘述，下列何者正確？","options":["(A) granulomatosis with polyangiitis與B型肝炎有關","(B) polyarteritis nodosa與C型肝炎有關","(C) microscopic polyangiitis與antineutrophil cytoplasmic antibodies有關","(D) cryoglobulinemic vasculitis與A型肝炎有關"],"answer":2,"image":""},{"id":"md3-114-2-36","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"化學藥物主要用來治療轉移性癌症或做癌症輔助性治療，關於化學藥物之副作用，下列敘述何者最不合適？","options":["(A) taxanes常造成周圍神經病變","(B) bleomycin常造成骨髓抑制","(C) cisplatin可能造成腎功能病變","(D) epirubicin可能造成心臟毒性"],"answer":1,"image":""},{"id":"md3-114-2-37","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"近年來基因定序研究的進展，已對肝細胞癌（hepatocellular carcinoma [HCC]）的分子基因變異（molecular and genetic alterations）有更進一步的瞭解。有關HCC的分子基因變異中，盛行率（prevalence）最低的是：","options":["(A) TSC1/TSC2 mutation","(B) TERT promoter mutation","(C) CTNNB1 mutation","(D) TP53 mutation"],"answer":0,"image":""},{"id":"md3-114-2-38","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"下列有關non-Hodgkin's lymphoma的描述，何者錯誤？","options":["(A) diffuse large B-cell lymphoma在東西方國家均是發生率最高的non-Hodgkin's lymphoma","(B) CD10是B細胞特有的細胞表面抗原，存在於較不成熟與成熟的B細胞表面，是rituximab的治療標的","(C) 對於Burkitt's lymphoma之治療，中樞神經之預防性治療是必要的。只要治療得當，超過一半比例的病人可以長期存活","(D) mycosis fungoides是一種T細胞的淋巴瘤，以侵犯皮膚為主"],"answer":1,"image":""},{"id":"md3-114-2-39","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"有些淋巴瘤（lymphoma）之發生與病毒或細菌感染有關連性。下列連結何者最不適當？","options":["(A) cytomegalovirus與中非地區的Burkitt's lymphoma","(B) Epstein-Barr virus與亞洲地區的extranodal nasal NK/T-cell lymphoma","(C) human T-cell lymphotropic virus 1（HTLV-1）與adult T-cell lymphoma（ATL）","(D) Helicobacter pylori與gastric MALT（mucosa-associated lymphoid tissue）lymphoma"],"answer":0,"image":""},{"id":"md3-114-2-40","subject":"md3","topic":"內科-血液","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"一位43歲女士過去無特殊病史，在健康檢查時發現血紅素14.5 g/dL，白血球78,500/μL，血小板495,000/μL；血液抹片如圖所示。此病人最可能的診斷為何？","options":["(A) essential thrombocytosis","(B) chronic myeloid leukemia","(C) leukemoid reaction","(D) acute myeloid leukemia"],"answer":1,"image":"md3-114-2-40.jpeg"},{"id":"md3-114-2-41","subject":"md3","topic":"內科-血液","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"一位35歲婦女，過去無特殊病史。最近3個月來皮膚經常出現瘀青，這幾天變得更厲害。身體診察發現手腳多處瘀青，其他無異常。抽血檢查顯示血紅素12.1 g/dL，白血球7,850/μL且分類正常，血小板13,000/μ L；肝、腎功能正常，HIV抗體陰性，抗核抗體（ANA）陰性，大、小便無潛血；病人過去並無特殊服藥史。對此病人目前最常見的優先處置為何？","options":["(A) platelet transfusion","(B) intravenous immunoglobulin infusion","(C) corticosteroid treatment","(D) eltrombopag treatment"],"answer":2,"image":""},{"id":"md3-114-2-42","subject":"md3","topic":"內科-消化肝膽胰","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"一位45歲女性病人因為黃疸就醫，抽血檢查發現血紅素為9.6 g/dL，白血球5,600/μL，血小板235,000/ μL，總膽紅素4.5 mg/dL，直接型膽紅素0.6 mg/dL，AST（GOT）85 U/L，ALT（GPT）32 U/L；尿液如圖所示。此病人最可能的診斷為何？","options":["(A) hepatitis","(B) intravascular hemolysis","(C) urinary tract infection","(D) gallbladder stones"],"answer":1,"image":"md3-114-2-42.jpeg"},{"id":"md3-114-2-43","subject":"md3","topic":"內科-血液","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"某病人7年前患有嚴重型再生不良性貧血症（aplastic anemia），成功接受血型相同HLA資料庫配對成功之非血親造血幹細胞移植（HLA-matched unrelated hematopoietic stem cell transplantation），下列何者可以提供該病人現在最可靠的人身血緣鑑定？","options":["(A) 血液","(B) 髮根","(C) 骨髓","(D) 白血球"],"answer":1,"image":""},{"id":"md3-114-2-44","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"大腸直腸癌（colorectal cancer）是全世界最常見的癌症之一，在臺灣地區的盛行率也逐年上升。腺瘤樣息肉（adenomatous polyp）被視為是大腸直腸癌的前趨病灶；大腸直腸癌會經過以下的「系列的基因變異」，而轉變成大腸直腸癌。下列的基因變異，何者與腺瘤樣息肉轉變成大腸直腸癌無關？","options":["(A) APC inactivation","(B) K-ras inactivation","(C) SMAD4 inactivation","(D) p53 inactivation"],"answer":1,"image":""},{"id":"md3-114-2-45","subject":"md3","topic":"內科-胸腔","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"下列何者不是CURB-65用來評估社區型肺炎嚴重度的指標項目？","options":["(A) 心跳次數","(B) 血中尿素氮","(C) 呼吸次數","(D) 血壓"],"answer":0,"image":""},{"id":"md3-114-2-46","subject":"md3","topic":"內科-胸腔","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"王先生有糖尿病病史多年，今發燒咳嗽有膿痰已5天，胸部X光攝影顯示肺有空洞（cavitation）之實質化（consolidation）病變，關於其治療與處置，下列敘述何者錯誤？","options":["(A) 痰液和血液培養若為Klebsiella pneumoniae，應安排眼底和腹部超音波檢查","(B) 若經治療後病情未改善，而痰液和血液培養為陰性，需進一步安排超音波或電腦斷層導引穿刺取得檢體做微生物培養","(C) 抗生素治療時應涵蓋厭氧菌","(D) 以廣效抗生素治療兩週"],"answer":3,"image":""},{"id":"md3-114-2-47","subject":"md3","topic":"內科-胸腔","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"一位氣喘病患平時使用支氣管擴張劑及茶鹼控制氣喘。最近其氣喘幾乎每天發作3～4次，每月幾乎都需要到急診求治，肺功能FEV1降至56%預期值，對支氣管擴張劑的反應越來越差。對於這位病患的處置應該如何調整最為適當？","options":["(A) 規則使用吸入性類固醇或其他抗發炎藥物","(B) 規則使用口服支氣管擴張劑以改善症狀","(C) 規則使用吸入型長效型抗膽鹼藥物改善肺功能","(D) 規則使用長效型支氣管擴張劑"],"answer":0,"image":""},{"id":"md3-114-2-48","subject":"md3","topic":"內科-胸腔","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"35歲家庭主婦因一個星期的咳嗽和呼吸短促求診。胸部X光檢查發現兩側肺浸潤，經支氣管鏡檢查，支氣管無異常。肺泡灌洗術（bronchoalveolar lavage）發現eosinophil 20%。下列何者最不可能是其致病原因？","options":["(A) Churg-Strauss syndrome","(B) Loffler's syndrome","(C) hypersensitivity pneumonitis","(D) eosinophilic pneumonia"],"answer":2,"image":""},{"id":"md3-114-2-49","subject":"md3","topic":"內科-胸腔","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"有關肺炎臨床診斷之定義，下列何者錯誤？","options":["(A) 發生在住院未滿48小時之病人，出現肺實質的急性感染，屬社區肺炎（community-acquired pneumonia）","(B) 上次住院結束後14天內發生肺實質的急性感染者，屬院內肺炎（hospital-acquired pneumonia）","(C) 使用呼吸器24小時以後產生的院內肺炎，屬呼吸器相關肺炎（ventilator-associated pneumonia）","(D) 在90天內曾在急性病醫院住院大於2天者，屬健康照護相關肺炎（health care-associated pneumonia）"],"answer":2,"image":""},{"id":"md3-114-2-50","subject":"md3","topic":"內科-腫瘤","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"關於肺癌的敘述，下列何者正確？","options":["(A) 肺癌最主要的危險因子是家族肺癌病史","(B) 抽菸的病人即使得了第四期肺癌仍要戒菸，因為抽菸會降低肺癌治療的效果","(C) 低劑量電腦斷層輻射量低，因此沒有輻射導致肺癌的風險","(D) 抽菸者大量補充抗氧化維生素，可以預防肺癌的產生"],"answer":1,"image":""},{"id":"md3-114-2-51","subject":"md3","topic":"內科-胸腔","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"關於乳糜胸（chylothorax）的敘述，下列何者正確？","options":["(A) 胸水呈牛乳狀，檢測會發現膽固醇（cholesterol）數值高於110 mg/dL","(B) 最常見的原因是胸管創傷（thoracic duct trauma）","(C) 是屬於濾出液（transudate）","(D) 治療方法是長期使用豬尾巴導管（pig-tail）引流"],"answer":1,"image":""},{"id":"md3-114-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"70歲男性因咳嗽就診，胸部X光在左下肺葉有2公分腫瘤。病人每天抽2包菸已有45年，目前並無服用任何藥物。身體診察：血壓156/95 mmHg（右手）、162/94 mmHg（左手），胸腹部電腦斷層發現除了胸部腫瘤及左腎上腺2公分腫瘤外，並無轉移現象。對於此腎上腺腫瘤下列何項處置最適當？","options":["(A) 測量24hr尿液catecholamine及VMA","(B) 切除腫瘤","(C) 電腦斷層指引下進行左腎上腺細針穿刺細胞學","(D) 3～6個月再做腎上腺電腦斷層追蹤"],"answer":0,"image":""},{"id":"md3-114-2-53","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"治療肢端肥大症，下列那一項藥物能夠最有效降低生長素（growth hormone, GH）和IGF-I（insulin-like growth factor I）？","options":["(A) cabergoline","(B) pegvisomant","(C) somatostatin analogues","(D) bromocriptine"],"answer":2,"image":""},{"id":"md3-114-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"下列何種藥物，通常在甲狀腺危象（thyrotoxic crisis）時才會使用？","options":["(A) propranolol","(B) propylthiouracil","(C) carbimazole","(D) Lugol's solution"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第54題除未作答者不給分外，其餘均給分 (原公告答案 D)"},{"id":"md3-114-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"關於糖尿病慢性併發症之敘述，下列何者最不適當？","options":["(A) 糖尿病視網膜病變是一種微血管病變（microvascular complication）","(B) 冠狀動脈心臟病（coronary heart disease）是一種大血管病變（macrovascular complication）","(C) 糖尿病足病變（diabetic foot）的成因是微血管病變（microvascular complication），不是大血管病變（macrovascular complication）","(D) 慢性高血糖（chronic hyperglycemia）是否直接造成大血管病變（macrovascular complication）較無定論"],"answer":[2,3],"image":"","answer_note":"更正:第55題答Ｃ或Ｄ或CD者均給分"},{"id":"md3-114-2-56","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"根據National Cholesterol Education Program and Adult Treatment Panel III（NCEP:ATPIII）診斷標準，下列那位男性成人屬於代謝症候群（metabolic syndrome）個案？","options":["(A) 腰圍89 cm、血壓132/78 mmHg、白蛋白尿排泄率10 μg/min、三酸甘油酯190 mg/dL、HDL-C 46 mg/dL","(B) BMI 24、血壓127/76 mmHg、空腹血糖109 mg/dL、三酸甘油酯242 mg/dL、白蛋白尿排泄率25 μg/min","(C) 腰圍105 cm、血壓142/86 mmHg、空腹血糖116 mg/dL、三酸甘油酯216 mg/dL、HDL-C 42 mg/dL","(D) BMI 30、血壓146/88 mmHg、總膽固醇254 mg/dL、HDL-C 46 mg/dL、空腹血糖123 mg/dL"],"answer":2,"image":""},{"id":"md3-114-2-57","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"下列何者最不可能導致低血糖？","options":["(A) 服用thiazide類藥物","(B) 胰島素瘤","(C) 服用過量的glimepiride","(D) 敗血症"],"answer":0,"image":""},{"id":"md3-114-2-58","subject":"md3","topic":"內科-內分泌代謝","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"一位25歲年輕男性病人，因心悸、氣喘、噁心、嘔吐、腹痛至急診就醫。病史詢問得知病人罹患糖尿病數年，須靠注射胰島素控制血糖，近日因工作壓力大、須加班熬夜，經常喝飲料提神。病人最近小便變多、口渴及體重減輕3公斤。身體診察發現病人體溫攝氏37度，呼吸每分鐘20次，脈搏每分鐘100下，血壓110/70 mmHg，腹部無明顯按壓痛。隨機指尖血糖值為560 mg/dL。下列處置何者最不適當？","options":["(A) 應再抽血檢查血糖、電解質及血液pH值","(B) 可給與靜脈輸液及胰島素治療","(C) 因胰島素無效，須改用其他降血糖藥物","(D) 讓病人住院治療與觀察"],"answer":2,"image":""},{"id":"md3-114-2-59","subject":"md3","topic":"內科-感染","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"病毒性腦炎（viral encephalitis）病人的腦脊髓液（CSF）檢查報告，最不可能出現下列何種結果？","options":["(A) 紅血球（red blood cell）數目增加","(B) 蛋白質濃度增加","(C) 白血球數目增加，且以淋巴球為主","(D) 腦脊髓液與血液葡萄糖濃度比值（CSF/serum glucose ratio）下降至小於0.4"],"answer":3,"image":""},{"id":"md3-114-2-60","subject":"md3","topic":"內科-感染","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"下列何者最不可能傳播人類免疫不全病毒（HIV）？","options":["(A) 陰道性交","(B) 共用針頭","(C) 親吻","(D) 肛交"],"answer":2,"image":""},{"id":"md3-114-2-61","subject":"md3","topic":"內科-心臟血管","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"心內膜炎在下列那些情形，需要心臟外科手術治療？①chordae tendineae rupture合併嚴重急性心臟衰竭 ②瓣膜功能異常合併經7～10天抗生素治療仍持續菌血症發生 ③治療3天仍然持續發燒 ④人工瓣膜心內膜炎，經積極抗生素治療後仍復發","options":["(A) ②③","(B) ③④","(C) ①②③","(D) ①②④"],"answer":3,"image":""},{"id":"md3-114-2-62","subject":"md3","topic":"內科-感染","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"40歲男性有慢性Ｂ型肝炎病史，未規則追蹤；至市場買魚時不慎被掉落的海魚刺到腳背，數小時後被刺傷的足背迅速紅腫疼痛，出現水泡（如圖）。12小時後轉送到院，血壓77/50 mmHg，脈搏115/分，呼吸22/分；3血液檢驗：肌酸酐（creatinine）2.5 mg/dL；總膽紅素3.6 mg/dL；ALT 230 U/L；白血球15,500/mm 3（band 12%）；血小板64,000/mm；綜合病史及病程，最可能的致病菌為何？","options":["(A) Pseudomonas aeruginosa","(B) Staphylococcus aureus","(C) Proteus mirabilis","(D) Vibrio vulnificus"],"answer":3,"image":"md3-114-2-62.jpeg"},{"id":"md3-114-2-63","subject":"md3","topic":"內科-感染","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"關於醫院內標準防護措施（standard precaution）之實施對象及目的，下列敘述何者正確？","options":["(A) 針對愛滋病病人，以減少由已知來源之致病菌傳播","(B) 針對肝炎病人，以減少由已知來源之致病菌傳播","(C) 針對多重抗藥性細菌感染病人，以減少由已知來源之致病菌傳播","(D) 針對所有病人的基本防護，以減少由已知及未知來源之致病菌傳播"],"answer":3,"image":""},{"id":"md3-114-2-64","subject":"md3","topic":"內科-感染","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"Aminoglycoside與下列何種抗生素併用具加成作用（synergistic effect）？","options":["(A) penicillin","(B) tetracycline","(C) sulfonamide","(D) trimethoprim"],"answer":0,"image":""},{"id":"md3-114-2-65","subject":"md3","topic":"內科-感染","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"進行性多發腦白質病變（progressive multifocal leukoencephalopathy, PML）是後天免疫缺乏症候群（AIDS）病人的腦病變之一，下列何者為引起該病變之致病原？","options":["(A) human immunodeficiency virus（HIV）","(B) John Cunningham virus（JC virus）","(C) Epstein-Barr virus（EBV）","(D) cytomegalovirus（CMV）"],"answer":1,"image":""},{"id":"md3-114-2-66","subject":"md3","topic":"家醫-行為與社區醫學","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"38歲陳女士常常因頭痛與肩頸痠痛就醫，診斷為緊張性頭痛（tension headache），依據生理心理社會模式（biopsychosocial model, BPS model）之觀點，下列敘述何者錯誤？","options":["(A) 其症狀與頭頸部肌肉緊張收縮有相關","(B) 焦慮憂鬱心理狀態會提升疼痛閥值","(C) 生活壓力事件影響頭痛頻率","(D) 社會支持不足而減弱對壓力適應之緩衝，容易致病"],"answer":1,"image":""},{"id":"md3-114-2-67","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"面對高齡病人時，下列敘述何項是最適當的臨床藥物處方原則？","options":["(A) 務必要與社區護理師共同作業（work with community nurse mandatorily）","(B) 總是啟用頻次相近的藥物（start medicines at similar dosing frequency always）","(C) 任何病人症狀的原因，都要考慮是藥物的副作用所造成（consider an adverse drug event as a cause of any new patient symptom）","(D) 每日更新與回顧所使用的藥物（update and review the medication list daily）"],"answer":2,"image":""},{"id":"md3-114-2-68","subject":"md3","topic":"家醫-行為與社區醫學","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"LGBTQIA+（lesbian, gay, bisexual, transgender, questioning [their sexuality or gender]/queer, intersex or asexual）的青少年，被霸凌或人身攻擊的發生率較高，憂鬱和自殺的發生率較高，其中那一類青少年發生上述問題的風險最高？","options":["(A) 雙性戀（bisexual）","(B) 男同性戀（gay）","(C) 雙性人（intersex）","(D) 跨性別青少年（transgender）"],"answer":3,"image":""},{"id":"md3-114-2-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"美國運動醫學會建議的運動處方內容，下列何者錯誤？","options":["(A) 最佳的運動效果是每週3～5次，每次持續時間20～60分鐘","(B) 中等強度定義為主觀運動強度評分表（Rating of Perceived Exertion Scale）強度9～11分","(C) 每次運動時段應包括熱身、運動及緩和三個階段","(D) 建議運動後要有至少3～5分鐘的緩和運動"],"answer":1,"image":""},{"id":"md3-114-2-70","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"美國預防醫學工作小組（U.S. Preventive Services Task Force）的化學性預防建議事項中，下列何者建議等級最高？","options":["(A) 65歲以上的社區老人補充維生素D，以預防跌倒骨折","(B) 補充維生素E，以預防心血管疾病","(C) 準備懷孕婦女每日補充葉酸（folic acid）0.4～0.8 mg，以預防胎兒神經管缺陷","(D) 60歲以上成年人每日服阿斯匹靈（aspirin）100 mg，以預防心血管疾病"],"answer":2,"image":""},{"id":"md3-114-2-71","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"有關家庭暴力受害者的檢查或處置，下列敘述何者最適當？","options":["(A) 可藉由觀察瘀傷的顏色、範圍、型態等，正確判斷出傷害的時間","(B) 2歲以下小孩出現瘀傷，應開立X光檢查骨骼狀況，並於2～3週後再以X光追蹤檢查骨骼","(C) 1歲以下嬰兒，當神經學檢查正常時，就可排除顱內傷害（intracranial injury）","(D) 性侵害中的育齡女性受害者應於7天內給與口服1.5 mg levonorgestrel一次，作為緊急避孕措施"],"answer":1,"image":""},{"id":"md3-114-2-72","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"實證醫學（evidence-based medicine）的證據層級，由高至低之排列順序為何？ ①世代研究（cohort study） ②專家意見（expert opinion） ③統合分析（meta-analysis） ④個案對照研究（case- control study） ⑤個案報告（case report）","options":["(A) ①②③④⑤","(B) ③①④⑤②","(C) ①③④⑤②","(D) ③①②④⑤"],"answer":1,"image":""},{"id":"md3-114-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"臨終譫妄（terminal delirium）被定義為臨終前數小時出現的不可逆躁動，下列處置方式何者最適當？","options":["(A) 在病床旁播放輕柔的音樂或是播放宗教性的唱誦","(B) 增加病人翻身的頻率，以避免出現壓傷（瘡）","(C) 使用苯二氮平類藥物（benzodiazepines），如每小時可舌下給與lorazepam（Ativan）1～2 mg","(D) 使用高劑量的非典型抗精神病藥物，如olanzapine以及GABA agonist來處理躁動和幻覺症狀"],"answer":[0,2],"image":"","answer_note":"更正:第73題答Ａ或Ｃ或AC者均給分"},{"id":"md3-114-2-74","subject":"md3","topic":"影像醫學","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"下列關於主動脈疾病的影像學表現，何者正確？","options":["(A) 主動脈瘤者很少出現主動脈壁鈣化的情形","(B) 一般體表超音波可良好評估主動脈弓及降主動脈情形","(C) 胸主動脈瘤最主要的診斷工具為電腦斷層","(D) 輕微主動脈擴張常可以經由一般胸部或腹部X光檢查發現"],"answer":2,"image":""},{"id":"md3-114-2-75","subject":"md3","topic":"影像醫學","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"12歲的張小弟，近三日無正常解便，早上媽媽發現他解出黏液狀的排泄物，被家人送到急診室。醫師診察後安排腹部Ｘ光及腹部超音波檢查，如圖所示。張小弟最有可能罹患下列何者疾病？","options":["(A) 急性闌尾炎（acute appendicitis）","(B) 疝氣（inguinal hernia）","(C) 惡性大腸癌（malignant colon cancer）","(D) 腸套疊（intussusception）"],"answer":3,"image":"md3-114-2-75.jpeg"},{"id":"md3-114-2-76","subject":"md3","topic":"急診醫學","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"關於孕婦的復甦急救（resuscitation）敘述，何者最適當？","options":["(A) 心跳停止的孕婦執行心肺復甦術時需左側躺（left lateral tilt position），以維持血液的回流","(B) 心房顫動（atrial fibrillation）的孕婦，可以給與amiodarone矯正心律","(C) 孕婦氣管插管時使用快速順序插管（rapid sequence intubation）的藥物劑量與一般成人相同","(D) 20週以上的孕婦靜脈注射途徑應優先考慮股靜脈注射"],"answer":2,"image":""},{"id":"md3-114-2-77","subject":"md3","topic":"急診醫學","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"臺灣南部發生芮氏規模6.6的地震，造成房屋倒塌與大量人員傷亡。根據簡單檢傷及快速治療（simple triage and rapid treatment, START）的原則，下列4位病人治療的優先順序為何？ ① 30歲男性，無脈搏頭部嚴重變形 ② 60歲女性，大腿開放性骨折橈動脈微弱 ③ 70歲男性，四肢多處擦傷可正常行走 ④ 20歲女性，心跳正常左小腿變形","options":["(A) ①②④③","(B) ②④③①","(C) ②④①③","(D) ①②③④"],"answer":1,"image":""},{"id":"md3-114-2-78","subject":"md3","topic":"急診醫學","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"一位末期腎病變病人，每週三次血液透析治療已6年，今日因胸部不適來院就診，在急診意識不清，脈搏摸不到，心律顯示每分鐘約50下且不規則，根據2020年American Heart Association（AHA）緊急心血管照護指引，須考量的可逆原因中，何者最不可能？","options":["(A) 高血鉀","(B) 低體溫","(C) 急性冠心症","(D) 高血糖"],"answer":3,"image":""},{"id":"md3-114-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"關於醫師與同儕間的關係，下列何者正確？","options":["(A) 依據世界醫師會的病人權利宣言，醫師有義務與其他健康照護者互相協調合作","(B) 當發現同儕醫師有專業能力不足或倫理上的不當行為時，第一優先是向醫學倫理委員會或司法單位舉報","(C) 醫學倫理要求醫師必須尊重師長。當老師要求學生獨立操作超越其能力的醫療行為時，仍應全力配合","(D) 醫學是追求卓越的高度競爭行業，並不需要講求與其他同儕的合作"],"answer":0,"image":""},{"id":"md3-114-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"A病患已屬末期病人，家屬希望讓他接受安寧緩和醫療，但是都沒有人願意去告訴A病患這件事。依據安寧緩和醫療條例之規定，下列敘述何者錯誤？","options":["(A) 應將病情及治療方針告知家屬或病患","(B) 病患要求要知道時，由醫師告知","(C) 病患要求要知道時，由護理人員或病患的親密家屬告知，以減少其心理衝擊","(D) 告知內容包括病情、安寧緩和醫療之治療方針及維生醫療抉擇"],"answer":2,"image":""},{"id":"md3-115-1-1","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"有關衰弱（frailty）的量表或測量工具，下列何者錯誤？","options":["(A) Linda Fried. Physical Frailty Index，≧1分即為衰弱","(B) Kenneth Rockwood Cumulative Deficit Frailty Index要評估許多面向，分數的算法是（有缺損的面向總數／評估的面向總數）得到一個0～1的分數","(C) Venerable Elder Survey 13工具，≧3分即為衰弱","(D) Strawbridge等人1994年設計的Frailty Measure，problem/difficulties in≧2 domains即為衰弱"],"answer":[0,2],"image":"","answer_note":"更正:第1題答Ａ或Ｃ或AC者均給分"},{"id":"md3-115-1-2","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"下列何者是可以調節的（modifiable）骨鬆危險因子？","options":["(A) 年老","(B) 抽菸","(C) 女性","(D) 一等親屬骨折史"],"answer":1,"image":""},{"id":"md3-115-1-3","subject":"md3","topic":"家醫-緩和醫學","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"王先生，68歲，罹患晚期轉移性肺癌，近一週因無法口服進食而改由鼻胃管灌食，目前住進安寧病房。原先使用口服長效嗎啡控制慢性骨轉移疼痛已有良好效果。今日因疾病惡化無法再吞嚥藥物，但仍持續表示疼痛「像刀割一樣痛到睡不著」。如果身為安寧病房醫療團隊住院醫師，下一步最適當的疼痛處理策略為何？","options":["(A) 停用嗎啡，改以NSAIDs貼片治療以減少副作用","(B) 改為嗎啡靜脈輸注或皮下持續給藥，並依先前口服劑量進行等效轉換","(C) 改開口服短效嗎啡並囑咐家屬協助灌食時服用","(D) 延後止痛藥物調整，先以抗焦慮藥物處理情緒與失眠"],"answer":1,"image":""},{"id":"md3-115-1-4","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"昏厥（syncope）的原因，最不可能包括下列何者？","options":["(A) 迷走神經性昏厥（vasovagal syncope）","(B) 姿態性低血壓（orthostatic hypotension）","(C) 心因性昏厥（cardiac syncope）","(D) 手術性昏厥（operation related）"],"answer":3,"image":""},{"id":"md3-115-1-5","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"史帝芬－強生氏症候群（Stevens-Johnson syndrome, SJS）及中毒性表皮壞死鬆解症（toxic epidermal necrolysis, TEN）是具致命危險的嚴重藥物過敏。在臺灣漢族血統者（Han Chinese），使用allopurinol而引起SJS/TEN嚴重皮膚不良反應與下列那一個HLA基因型的相關性最高？","options":["(A) HLA-B*15:02","(B) HLA-B*31:01","(C) HLA-B*57:01","(D) HLA-B*58:01"],"answer":3,"image":""},{"id":"md3-115-1-6","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"有關缺血性心臟病（ischemic heart disease, IHD）診斷方式之敘述，下列何者最不適當？","options":["(A) 運動式心電圖是診斷IHD的工具之一，雖然有萬分之一的死亡風險，但只要有適當人員、設備在場，且限制心率上限，於無併發症之心肌梗塞一週後即可進行檢查","(B) 當病人因關節疾病、衰弱等原因無法進行運動測試時，可安排如：adenosine thallium 201 scan、dobutamine stress等影像學檢查","(C) 當使用電腦斷層成像計算Agatston score以估測冠脈斑塊鈣化程度時，並不需要注射顯影劑","(D) 診斷性心導管冠脈造影雖具侵入性，但可早期確診IHD以進行相關治療，因此有助減少穩定性心絞痛病人之心絞痛症狀、心肌梗塞及死亡之風險"],"answer":3,"image":""},{"id":"md3-115-1-7","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"有關高血壓（hypertension）所造成的器官損傷，下列敘述何者錯誤？","options":["(A) 高血壓可以導致左心室肥大、心衰竭和心律失常，包括心房顫動（atrial fibrillation）","(B) 高血壓是引發腦中風（stroke）的最強危險因子，大部分都是腦出血，其餘是腦梗塞","(C) 高血壓與老年人口的認知功能障礙及失智症有關","(D) 高血壓造成的腎臟損傷，與收縮壓的關係比舒張壓更密切"],"answer":1,"image":""},{"id":"md3-115-1-8","subject":"md3","topic":"內科-胸腔","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"下列何項臨床狀況，發生肺栓塞（pulmonary embolism）且經過治療一段時間後，如果停用抗凝血藥物，其再發生靜脈血栓栓塞（venous thromboembolism）的風險最低？","options":["(A) 活動性癌症（active cancer）","(B) 長途飛行（long-haul flight）","(C) 無可確認的靜脈血栓栓塞危險因子（no identifiable risk factor of venous thromboembolism）","(D) 外傷（trauma）2"],"answer":[2,3],"image":"","answer_note":"更正:第8題答Ｃ或Ｄ或CD者均給分"},{"id":"md3-115-1-9","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"40歲男性有10年心悸病史未妥善就醫，近一星期症狀加重，呼吸困難。到院時，BMI=41 kg/m，BP 126/72 mmHg，HR 141/min，RR 28/min，Temp 36.90 ℃，SpO2 97％，無貧血，甲狀腺觸診未有異常，未有第三心音及心雜音，肝脾不大，無腹水，雙下肢微腫。相關檢查如附圖。抽血報告如下：NT Pro-BNP 2470 pg/mL，Troponin T 0.019 ng/mL，D-dimer 20 mg/L FEU，ALT 196 U/L。下列何項診斷最符合目前狀況？","options":["(A) 急性心肌炎","(B) 高血壓心臟病","(C) 肥厚性心肌病","(D) 肺動脈栓塞症"],"answer":3,"image":"md3-115-1-9.jpeg"},{"id":"md3-115-1-10","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"根據Vaughan Williams classification，可將抗心律不整藥分為以下幾大類，何者敘述錯誤？","options":["(A) Class Ⅰ藥物主要針對鈉離子通道（sodium channel），如flecainide","(B) Class Ⅱ藥物主要針對乙型交感神經受體（beta adrenergic receptor），如bisoprolol","(C) Class Ⅲ藥物主要針對鉀離子通道（potassium channel），如amiodarone","(D) Class Ⅳ藥物主要針對鈣離子通道（calcium channel），如amlodipine"],"answer":3,"image":""},{"id":"md3-115-1-11","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"58歲男性，有慢性肺病和糖尿病病史，住院期間診斷為多重起源心房心搏過速（multifocal atrial tachycardia, MAT）。心電圖顯示130 bpm的心率，並有三種不同形態的P波。血液報告顯示正常的凝血功能，並未使用抗凝劑。關於MAT的血栓風險，下列敘述何者最適當？","options":["(A) MAT的血栓風險類似於心房顫動（atrial fibrillation, AF）","(B) MAT的血栓風險目前缺乏大型臨床試驗證實","(C) MAT的血栓風險與心室顫動相同","(D) MAT患者需立即開始抗凝治療"],"answer":1,"image":""},{"id":"md3-115-1-12","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"下列血液檢查項目中，何者與高血壓致病機轉的探索最無相關？","options":["(A) 肌酸酐","(B) 鉀離子","(C) 甲狀腺素","(D) 尿酸"],"answer":3,"image":""},{"id":"md3-115-1-13","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"心導管檢查可用於冠狀動脈心臟病之診斷，下列敘述何者最不適當？","options":["(A) 於血管攝影時，冠狀動脈左前降支可能受心肌橋（myocardial bridge）壓迫，在心收縮期變細、舒張期恢復正常","(B) 當冠狀動脈嚴重狹窄時，狹窄遠端血流會減少，以致顯影劑僅能微量充盈遠端血管，此種情況可定義為TIMI三級血流","(C) 血管內超音波（intravascular ultrasound, IVUS）及光學同調斷層攝影（optic coherence tomography, OCT）等檢查工具，可送入冠狀動脈內進行細部觀測，而OCT之空間解析度高於IVUS，但可觀察之範圍深度較淺","(D) 血流儲備分數（fractional flow reserve, FFR）實際上是測量狹窄遠端及近端的壓力比值，在以藥物引發最大充血（maximal hyperemia）情況下，若FFR＜0.8表示病灶狹窄程度顯著，具有影響血行動力學之意義"],"answer":1,"image":""},{"id":"md3-115-1-14","subject":"md3","topic":"影像醫學","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"有關核醫心肌灌注掃描，下列敘述何者最不適當？","options":["(A) 壓力催迫（stress）後，肺部攝取量增加（lung uptake），如附圖所示，可能代表嚴重且冠狀動脈多條血管阻塞","(B) 在壓力測試後，若觀察到短暫左心室擴大，可能與冠狀動脈多條血管阻塞有關","(C) 壓力催迫（stress）後肺部攝取量增加和短暫左心室擴大，對於冠狀動脈疾病的診斷專一性，比大區域或多處血管分布區域出現可逆性灌流缺損更高","(D) 在心臟以外區域若有Thallium-201同位素蓄積，如附圖箭頭所示，有可能是乳房腫瘤"],"answer":2,"image":"md3-115-1-14.jpeg"},{"id":"md3-115-1-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"下列何種nucleos(t)ide analogue不建議在懷孕的慢性B型肝炎婦女使用？","options":["(A) entecavir","(B) telbivudine","(C) tenofovir（TDF）","(D) tenofovir（TAF）"],"answer":0,"image":""},{"id":"md3-115-1-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"關於消化性潰瘍治療用藥，下列何者錯誤？","options":["(A) 可使用sucralfate一天服用4次，每次1 g","(B) 乙型組織胺受器（H2 receptor）拮抗劑cimetidine，因其成分受到N-nitrosodimethylamine污染，具致癌性已被下架停用","(C) 使用氫離子幫浦阻斷劑（proton pump inhibitor）會造成血中胃泌素（gastrin）上升","(D) 使用氫離子幫浦阻斷劑（proton pump inhibitor）數個月，發生腹瀉，要懷疑有無困難梭菌（Clostridium difficile）感染"],"answer":1,"image":""},{"id":"md3-115-1-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"關於肝細胞癌hepatocellular carcinoma（HCC）預防的措施，下列何者正確？","options":["(A) 世界衛生組織建議僅對高危險成人施打HBV疫苗","(B) 抗病毒治療使慢性HBV感染者血中HBV DNA持續陰性，可降低HCC發生風險","(C) HCV感染患者達到持續病毒學反應sustained virological response（SVR），肝硬化患者HCC風險可完全消除","(D) 兒童及新生兒無需接種HBV疫苗，因其HCC風險極低"],"answer":1,"image":""},{"id":"md3-115-1-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"關於肝腎症候群（hepatorenal syndrome, HRS）的敘述，下列何者正確？","options":["(A) HRS是一種結構性腎臟損傷，腎臟切片可明顯發現病理改變","(B) HRS的主要病理機轉為腎血管擴張導致腎血流增加","(C) HRS治療首選為利尿劑及血管擴張劑合併使用","(D) 肝移植是HRS最有效的治療，且可恢復腎功能"],"answer":3,"image":""},{"id":"md3-115-1-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"關於養分吸收不良（nutrient malabsorption）與臨床徵狀之配對，下列何者錯誤？","options":["(A) 鐵（iron）—貧血（anemia）","(B) 維他命K（vitamin K）—瘀斑（ecchymosis）","(C) 必需脂肪酸（essential fatty acids）—皮膚炎（dermatitis）","(D) 維他命B 12（vitamin B12）—抽搐（tetany）"],"answer":3,"image":""},{"id":"md3-115-1-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"下列何者並非急性胰臟炎之可能原因？","options":["(A) 高三酸甘油酯血症（hypertriglyeridemia）","(B) 低血鈣症（hypocalcemia）","(C) 胰腺癌（pancreatic adenocarcinoma）","(D) 膽結石（cholelithiasis）"],"answer":1,"image":""},{"id":"md3-115-1-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"關於發炎性腸道疾病（inflammatory bowel disease）臨床表現的敘述，下列何者錯誤？","options":["(A) 闌尾切除（appendectomy）對於潰瘍性大腸炎（ulcerative colitis）的發生有保護作用","(B) 三分之一的克隆氏症患者有肛周疾病，表現為直腸周瘻管、肛裂、膿腫和肛門狹窄","(C) 中毒性巨結腸（toxic megacolon）通常發生於嚴重潰瘍性大腸炎病患，其定義為左側結腸直徑大於6公分且失去結腸袋（haustration）構造","(D) 約10～30％的克隆氏症患者會在病程中的某段時間發生腹腔或骨盆腔膿腫。穿孔造成的腹膜炎，尤其是結腸性腹膜炎，可能會致命"],"answer":2,"image":""},{"id":"md3-115-1-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"下列何者不是膽囊／膽管結石所引發的併發症？","options":["(A) 急性膽囊炎（acute cholecystitis）","(B) 膽管囊腫（choledochal cyst）","(C) 急性胰臟炎（acute pancreatitis）","(D) 急性膽管炎（acute cholangitis）"],"answer":1,"image":""},{"id":"md3-115-1-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"下列關於急性腸繫膜缺血（acute mesenteric ischemia）之敘述，何者最不適當？","options":["(A) 可能因動脈血栓所引起","(B) 病程初期腹部身體診察多半沒有明顯之反彈痛","(C) 以內科治療為優先，儘可能避免開腹探查及手術治療","(D) 電腦斷層血管攝影（CT angiography）對於診斷上腸繫膜動脈阻塞具有高敏感度"],"answer":2,"image":""},{"id":"md3-115-1-24","subject":"md3","topic":"內科-腎臟","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"下列何者是慢性腎臟疾病最不常見之障礙？","options":["(A) 高血鈉","(B) 高血磷","(C) 次發性副甲狀腺機能亢進","(D) 貧血"],"answer":0,"image":""},{"id":"md3-115-1-25","subject":"md3","topic":"內科-腎臟","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"下列何種感染，最容易發生在腎臟移植手術後的1個月內？","options":["(A) 口腔念珠菌感染","(B) 巨細胞病毒感染","(C) 肺囊蟲肺炎","(D) 人類多瘤性病毒（BK病毒）感染"],"answer":0,"image":""},{"id":"md3-115-1-26","subject":"md3","topic":"內科-腎臟","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"關於感染後腎絲球腎炎（post-infectious glomerulonephritis）的臨床表現，下列敘述何者最適當？","options":["(A) 常出現肉眼可視血尿，唯少見血塊","(B) 典型發生於葡萄球菌型咽喉炎或皮膚感染後10天至3週","(C) 治療首重抗生素，以期逆轉或縮短急性腎炎病程","(D) 通常伴隨C3補體下降，可用於區分IgA腎病變急性發作"],"answer":3,"image":""},{"id":"md3-115-1-27","subject":"md3","topic":"內科-腎臟","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"診斷間質性膀胱炎（interstitial cystitis/bladder pain syndrome, IC/BPS）通常要求症狀持續至少多久時間？","options":["(A) 1週","(B) 6週","(C) 3個月","(D) 6個月"],"answer":1,"image":""},{"id":"md3-115-1-28","subject":"md3","topic":"內科-腎臟","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"下列關於各種類型結石形成之敘述，何者錯誤？","options":["(A) 草酸鈣結石（calcium oxalate stones）的危險因子，包括較高的尿鈣濃度、較高的尿草酸濃度以及較低的尿檸檬酸濃度。在生理範圍內，這種結石類型對尿液酸鹼值（pH）並不敏感","(B) 磷酸鈣結石（calcium phosphate stones）的危險因子，包括較高的尿鈣濃度及較低的尿檸檬酸濃度","(C) 尿酸結石（uric acid stone）的危險因子為持續偏低的尿液酸鹼值（低pH）以及較高的尿酸排泄量","(D) 胱胺酸結石（cystine stones）的危險因子，包括較高的尿鈣濃度以及較低的尿檸檬酸濃度"],"answer":3,"image":""},{"id":"md3-115-1-29","subject":"md3","topic":"內科-腎臟","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"有關慢性腎臟病所併發之腎性貧血（renal anemia），下列何者錯誤？","options":["(A) 腎性貧血之紅血球型態常為正常血球大小（normocytic）與正常色素性（normochromic）","(B) 腎性貧血常出現虛弱、運動耐受力不良（exercise intolerance）、心衰竭與認知功能異常等症狀","(C) 造成腎性貧血最主要的原因為紅血球生成素（erythropoietin）不足","(D) 為改善腎性貧血病患之死亡率，應將病患之血色素值矯正至正常人標準值（≧13 g/dL）"],"answer":3,"image":""},{"id":"md3-115-1-30","subject":"md3","topic":"內科-腎臟","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"有關慢性腎臟病的治療，下列何者最適當？","options":["(A) 慢性腎臟病患者合併高血壓，其降血壓藥物首選為乙型腎上腺交感神經阻斷劑（beta blocker）","(B) 糖尿病慢性腎臟病患者使用第2型鈉–葡萄糖共同轉運蛋白抑制劑（SGLT2 inhibitor）可有效降低腎功能衰退","(C) 患有重度蛋白尿之糖尿病慢性腎臟病患者，最好合併使用血管張力素轉化酶抑制劑（ACEi）和血管張力素Ⅱ 型受體拮抗劑（ARB）來治療","(D) 患有腎病症候群之慢性腎臟病患者，應採用高蛋白飲食療法以矯正低蛋白血症"],"answer":1,"image":""},{"id":"md3-115-1-31","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"下列何者的臨床表現對診斷抗磷脂症候群（anti-phospholipid syndrome）最沒有幫助？","options":["(A) 血小板低下","(B) 反覆胃腸出血","(C) 反覆流產","(D) 血液檢查有anti-β2 glycoprotein I（anti-β2GPI）抗體"],"answer":1,"image":""},{"id":"md3-115-1-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"關於Sjögren's syndrome的敘述，下列何者最不適當？","options":["(A) Sjögren's syndrome最常侵犯唾液腺和淚腺，因此常有蛀牙的情形","(B) Sjögren's syndrome常有腎絲球的病變，較少有關節疼痛／關節炎症狀","(C) Anti-SSA（Ro）抗體和Sjögren's syndrome有關","(D) Sjögren's syndrome有較高的lymphoma發生機率"],"answer":1,"image":""},{"id":"md3-115-1-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"關於calcium pyrophosphate deposition（CPPD）和calcium apatite deposition（CAD）結晶引起的關節炎之敘述，下列何者最適當？","options":["(A) CPPD的關節炎好發在年輕族群","(B) 年輕族群有CPPD疾病常合併其它代謝的疾病","(C) 在偏光顯微鏡下可由看到CAD的結晶而與CPPD結晶來區別","(D) 只要有CAD的結晶在關節內就會引起急性關節炎"],"answer":1,"image":""},{"id":"md3-115-1-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"關於類風濕性關節炎，下列敘述何者最適當？","options":["(A) 較常發生在下肢大關節","(B) 患者的晨間僵硬感通常小於30分鐘","(C) 較常出現左右對稱的多關節炎，但疾病初期也可以從單關節炎開始","(D) 遠端指間關節（distal interphalangeal joint）如果也影響到，代表疾病嚴重度較高"],"answer":2,"image":""},{"id":"md3-115-1-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"下列疾病與其已知的自體抗原（auto-antigen）之配對，何者最不適當？","options":["(A) myasthenia gravis—acetylcholine receptor","(B) autoimmune thyroiditis—thyroglobulin","(C) progressive systemic sclerosis—tubulin","(D) granulomatosis with polyangiitis—proteinase 3"],"answer":2,"image":""},{"id":"md3-115-1-36","subject":"md3","topic":"內科-腫瘤","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"下列關於ECOG體能狀態和Karnofsky performance status的敘述，何者錯誤？","options":["(A) ECOG系統以0～5為評分標準，數字越小表示功能越好","(B) ECOG 0約等同於Karnofsky 100分","(C) Karnofsky＜50分通常與ECOG≦2接近","(D) ECOG和Karnofsky分數可用作癌症預後及治療耐受性的指標"],"answer":2,"image":""},{"id":"md3-115-1-37","subject":"md3","topic":"內科-腫瘤","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"一名骨肉瘤的年輕病人，手術後進行高劑量methotrexate的輔助性化療，3天後出現黏膜炎、輕度骨髓抑制7及血中methotrexate濃度偏高（＞10⁻ M）且腎功能惡化，尿液偏酸性。除持續監測血中methotrexate濃度外，下列處置何者最適合？","options":["(A) 立即停用leucovorin（N5-formyltetrahydrofolate），減少進一步干擾治療效果","(B) 改為投與folic acid取代leucovorin 2","(C) 增加leucovorin劑量至50～100 mg/m","(D) 使用L-glutamine以改善腎功能"],"answer":2,"image":""},{"id":"md3-115-1-38","subject":"md3","topic":"內科-腫瘤","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"子宮頸癌（cervical cancer）的發生與human papilloma virus（HPV）有十分密切的關係。下列敘述何者最適當？","options":["(A) HPV16和HPV18是子宮頸癌發生相關的high-risk strains","(B) 8-kb的HPV基因體在導致上皮細胞癌化過程中均呈episomal form，不會嵌入宿主細胞的DNA","(C) HPV的E7及E8基因，分別作用在宿主細胞的RB及p53，導致細胞週期調控的異常","(D) 少數的子宮頸癌與HPV無關（所謂的HPV-negative cervical cancers），多發生於年輕的女性"],"answer":0,"image":""},{"id":"md3-115-1-39","subject":"md3","topic":"內科-腫瘤","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"食道癌常見的兩種組織學型態為esophageal squamous cell carcinoma（ESCC）及esophageal adenocarcinoma（EAC），ESCC及EAC有很不同的危險因子及發生機制。下列敘述何者最不適當？","options":["(A) ESCC發生的危險因子包括飲酒與吸菸","(B) EAC發生的危險因子包括慢性胃食道逆流（chronic gastroesophageal reflux）","(C) 腫瘤基因變異中，HER2/ERBB2 amplification在EAC發生的比率較ESCC為高","(D) Lynch syndrome的患者，發生ESCC的機率大於EAC"],"answer":3,"image":""},{"id":"md3-115-1-40","subject":"md3","topic":"內科-血液","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"下列何種疾病會有大於90％的比率發生JAK2 V617F的基因突變？","options":["(A) polycythemia vera","(B) essential thrombocythemia","(C) primary myelofibrosis","(D) chronic neutrophilic leukemia"],"answer":0,"image":""},{"id":"md3-115-1-41","subject":"md3","topic":"內科-腫瘤","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"Paraneoplastic neurologic disorder（PND）指癌症病患出現神經學的症狀，但並非由於癌症轉移或癌症相關之合併症而影響病患的中樞神經、周邊神經、神經肌肉交接處或肌肉所致。下列有關PND的敘述，何者最適當？","options":["(A) 以合併發生PND的機率而言，非小細胞肺癌（non-small cell lung cancer）顯著地大於小細胞肺癌（small cell lung cancer）","(B) PND的致病機轉可能與癌細胞表現神經細胞抗原而誘發的免疫反應有關。例如：anti-Hu抗體常可於encephalomyelitis病患的血清或腦脊髓液中檢測出","(C) 一旦確診PND導因於免疫相關機制時，使用intravenous immunoglobulin或plasma exchange治療，可以得到很好的治療成效","(D) PND的神經學症狀多出現於癌症診斷之後，其症狀大多緩慢地出現與進展"],"answer":1,"image":""},{"id":"md3-115-1-42","subject":"md3","topic":"內科-胸腔","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"關於肺癌的敘述，下列何者最適當？","options":["(A) 在4種最常見的肺癌組織型中，鱗狀上皮細胞癌（squamous cell carcinoma）和小細胞癌（small cell carcinoma）與菸癮大的人（heavy smokers）相關性最大","(B) 在女性、年輕（小於60歲）肺癌病患，大細胞癌（large cell carcinoma）是最常見的肺癌組織型","(C) 臨床上，如果是第四期肺癌，肺癌組織型只要區分為小細胞肺癌（small cell lung cancer）、非小細胞肺癌（non-small cell lung cancer）。非小細胞肺癌沒有必要進一步區分是鱗狀上皮細胞癌（squamous cell carcinoma）、腺癌（adenocarcinoma）等","(D) 在確診肺癌之後，戒菸對病患則無幫助"],"answer":0,"image":""},{"id":"md3-115-1-43","subject":"md3","topic":"內科-血液","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"下列有關動脈血栓與靜脈血栓的敘述，何者最不適當？","options":["(A) 靜脈血栓主要源於tissue factor之暴露與coagulation cascade之啟動，而動脈血栓主要源於血小板黏附（adhesion）於受傷之血管","(B) 一些已知能導致靜脈血栓的因子，如factor V Leiden與prothrombin G20210A mutation，它們在動脈血栓形成之角色則較未明確","(C) 靜脈血栓之危險因子，如吸菸、肥胖、代謝症候群與年齡，也是動脈血栓的危險因子","(D) 靜脈血栓最終是由於thrombin之產生與fibrin之形成，而動脈血栓則與thrombin之產生無關"],"answer":3,"image":""},{"id":"md3-115-1-44","subject":"md3","topic":"內科-血液","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"下列何者屬於單一的凝血因子缺乏，而造成凝血功能異常？","options":["(A) 遺傳性B型血友病","(B) 酒精性肝炎","(C) 敗血症","(D) 維他命K缺乏"],"answer":0,"image":""},{"id":"md3-115-1-45","subject":"md3","topic":"內科-胸腔","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"下列有關阻塞性睡眠呼吸中止症（obstructive sleep apnea, OSA）的敘述，何者最不適當？","options":["(A) apnea的定義為airflow停止≧10秒","(B) apnea-hypopnea index（AHI）必須＞15 events／hour","(C) 診斷標準為overnight polysomnography（PSG），如果實驗室（in-laboratory）PSG為陰性通常可排除OSA診斷","(D) continuous positive airway pressure（CPAP）是目前最有證據的標準治療"],"answer":1,"image":""},{"id":"md3-115-1-46","subject":"md3","topic":"內科-感染","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"下列病人中，何者最容易罹患綠膿桿菌（Pseudomonas aeruginosa）引起的社區性肺炎（community- acquired pneumonia）？","options":["(A) alcoholism","(B) severe COPD","(C) stroke","(D) diabetes mellitus"],"answer":1,"image":""},{"id":"md3-115-1-47","subject":"md3","topic":"內科-胸腔","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"65歲男性病人，身體一向健康沒有慢性疾病。因近二年多來有漸進性的乾咳及運動時呼吸困難而前來門診就診，身體檢查發現兩側下肺葉有fine crackles，手指有杵狀指，其他檢查正常。肺功能檢查顯示TLC 65％ predicted，FEV1/FVC 78％，DLco 50％ predicted，下列何種藥物治療對病人最適當？","options":["(A) theophylline","(B) dual bronchodilator","(C) colchicine","(D) nintedanib"],"answer":3,"image":""},{"id":"md3-115-1-48","subject":"md3","topic":"內科-胸腔","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"65歲男性，每天抽菸1包，平時有爬山的習慣，來到急診時自訴咳嗽兩週，有黃色濃痰，呼吸有wheezing聲，下列鑑別診斷中最不可能的是：","options":["(A) 慢性阻塞性肺病（chronic obstructive pulmonary disease, COPD）急性發作","(B) 急性心臟衰竭（acute heart failure）","(C) 支氣管擴張症（bronchiectasis）惡化","(D) 細菌性肺炎"],"answer":1,"image":""},{"id":"md3-115-1-49","subject":"md3","topic":"影像醫學","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"胸腔超音波檢查對下列何者疾病，幫助診斷價值最低？","options":["(A) 氣胸","(B) 肋膜腔積液","(C) 縱膈腔淋巴結腫大","(D) 膈神經麻痺（phrenic nerve palsy）"],"answer":2,"image":""},{"id":"md3-115-1-50","subject":"md3","topic":"內科-腫瘤","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"一位59歲健康男性，吸菸習慣為每日1包，持續超過30年。因右鎖骨上方發現明顯腫塊，前來腫瘤科門診就診。切片檢查結果顯示腫塊為鱗狀細胞癌，PD-L1表現≧50％，但原發部位未能確定。正子斷層造影顯示右上肺、右鎖骨上方及縱膈腔內局部淋巴結有顯影，並未見遠端器官轉移。下列那種治療方式對於病人的預後幫助相對較小？","options":["(A) 高劑量放射治療","(B) 手術切除","(C) 化學治療","(D) 免疫治療"],"answer":1,"image":""},{"id":"md3-115-1-51","subject":"md3","topic":"內科-胸腔","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"呼吸困難（dyspnea）是一種主觀感受，包含強度各異、性質不同的感覺。其體驗源自多種生理、心理、社會和環境因素，並可能引發繼發性生理及行為反應。下列何者不是造成慢性呼吸困難（chronic dyspnea）的主要原因？","options":["(A) 重度脊柱後側彎（kyphoscoliosis）","(B) 肺部良性腫瘤如錯構瘤（hamartoma）","(C) 運動神經元疾病（motor neuron disease）例如amyotrophic lateral sclerosis（ALS）","(D) 肺高壓（pulmonary hypertension）"],"answer":1,"image":""},{"id":"md3-115-1-52","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"下列何者為希漢氏症候群（Sheehan's syndrome）的主要發病機制？","options":["(A) 腦下垂體腫瘤增生導致壓迫性損傷","(B) 產後出血導致腦下垂體缺血性壞死","(C) 高泌乳素血症導致下視丘–腦下垂體軸抑制","(D) 自體免疫性攻擊導致腦下垂體細胞凋亡"],"answer":1,"image":""},{"id":"md3-115-1-53","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"下列何者為調控血漿抗利尿激素（AVP）的主要機制？","options":["(A) 促腎上腺皮質激素（ACTH）濃度","(B) 血漿滲透壓（plasma osmolality）","(C) 甲狀腺素（T3/T4）濃度","(D) 血糖濃度"],"answer":1,"image":""},{"id":"md3-115-1-54","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"下列何者為嗜鉻細胞瘤／副神經節瘤（pheochromocytoma/ catecholamine-secreting paragangliomas）診斷中，敏感度最高且特異性佳的生化測試？","options":["(A) 24小時尿中catecholamines檢測","(B) 血漿游離metanephrines測定","(C) 低劑量dexamethasone抑制試驗","(D) 促腎上腺皮質激素（ACTH）刺激試驗"],"answer":1,"image":""},{"id":"md3-115-1-55","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"關於龐貝氏症（Pompe disease），下列敘述何者正確？","options":["(A) 是一種體染色體隱性遺傳罕見疾病，通常在成年期發病","(B) 又名肝醣儲積症第一型（Glycogen Storage Disease type Ⅰ, Type Ⅰ GSD）","(C) 是由於肝臟磷酸化酶激酶（Liver Phosphorylase Kinase）缺乏無法分解肝醣所引起，最常見的症狀為肝臟腫大、肌肉無力及心臟肥大等","(D) 在臺灣已被列為新生兒篩檢疾病之一，可藉由定期酵素替代治療（enzyme replacement therapy）來改善症狀"],"answer":3,"image":""},{"id":"md3-115-1-56","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"潛伏性成人自體免疫糖尿病（Latent autoimmune diabetes in adults, LADA）的敘述，下列何者錯誤？","options":["(A) 發病初期病人不須接受胰島素治療","(B) 發病年齡較典型第1型糖尿病來的晚","(C) anti-glutamic acid decarboxylase antibody（anti-GAD65）可作為主要檢測的抗體","(D) 胰島β細胞的功能喪失的速度較第1型糖尿病人快"],"answer":3,"image":""},{"id":"md3-115-1-57","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"關於原發性副甲狀腺機能過高（primary hyperparathyroidism）典型的臨床表徵，下列何者最不常見？","options":["(A) 骨質疏鬆","(B) 反覆腎結石","(C) 便秘","(D) 手麻與抽筋"],"answer":3,"image":""},{"id":"md3-115-1-58","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"下列何者不是葛雷夫氏症（Graves' disease）的特徵？","options":["(A) 甲狀腺機能亢進","(B) 眼病變（ophthalmopathy）","(C) 甲狀腺腫","(D) 脛前可壓凹陷的水腫（pretibial pitting edema）"],"answer":3,"image":""},{"id":"md3-115-1-59","subject":"md3","topic":"內科-感染","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"比較腦膜炎雙球菌（Neisseria meningitidis）和肺炎鏈球菌（Streptococcus pneumoniae）所引發的腦膜炎，兩者的處置與預後差異，下列敘述何者最適當？","options":["(A) 腦膜炎雙球菌腦膜炎比肺炎鏈球菌腦膜炎需要更長時間的抗生素治療","(B) 肺炎鏈球菌腦膜炎的死亡率高於腦膜炎雙球菌腦膜炎","(C) 兩者的密切接觸者都需要立即進行預防性投藥","(D) 兩者的首選抗生素皆是Fluoroquinolone類"],"answer":1,"image":""},{"id":"md3-115-1-60","subject":"md3","topic":"內科-感染","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"關於人工關節感染（prosthetic joint infections）與其他非植入物相關的敗血性關節炎（septic arthritis）的病理生理機制和治療策略的差異，下列敘述何者最適當？","options":["(A) 葡萄球菌（staphylococci）是人工關節感染最常見的菌種","(B) 生物膜形成是其他非植入物相關的敗血性關節炎的關鍵致病因子","(C) 兩者免疫反應的模式與炎症反應的強度類似","(D) 其他非植入物相關的敗血性關節炎較常需要分階段手術"],"answer":0,"image":""},{"id":"md3-115-1-61","subject":"md3","topic":"內科-感染","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"下列關於病毒感染的敘述，何者最不適當？","options":["(A) 能經口進食的輕症病人，流行性感冒（influenza）的治療首選藥物是oseltamivir","(B) 麻疹（measle）病毒傳播力低和致病力弱，且有抗病毒藥物治療","(C) 對於高風險新生兒，palivizumab的使用可以降低human respiratory syncytial virus（RSV）感染住院的風險","(D) 未經治療的人類免疫不全病毒（HIV）感染的傳播力與感染者的血漿病毒量和潰瘍性生殖道疾病相關"],"answer":1,"image":""},{"id":"md3-115-1-62","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"48歲女性，主訴為3個月來腹痛、食慾不振、體重減輕。曾經吃過2至3天的抗生素，但沒有改善。過去病史中，病人提及20年前有裝過子宮內避孕器（intrauterine contraceptive device, IUCD），理學檢查沒有摸到明顯的腫塊，電腦斷層掃描（computed tomography, CT）顯示有子宮膿瘍，蔓延到腹腔壁。CT引導的引流液中，抹片發現有革蘭氏陽性桿菌及黃色硫磺顆粒（sulfur granule）。下列敘述何者最不適當？","options":["(A) 子宮內避孕器是得到此疾病的危險因子之一","(B) 治療可使用penicillin或是amoxicillin","(C) 可使用電腦斷層掃描或核磁共振（magnetic resonance imaging, MRI）追蹤治療成效","(D) 建議抗生素治療時間為兩週"],"answer":3,"image":""},{"id":"md3-115-1-63","subject":"md3","topic":"內科-感染","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"下列何種抗生素是懷孕婦女使用相對安全的（pregnancy category B）？","options":["(A) cephalosporin","(B) amikacin","(C) sulfonamide","(D) fluoroquinolone"],"answer":0,"image":""},{"id":"md3-115-1-64","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"53歲男性因為數個月下腹不適、腹瀉就醫，糞檢發現有潛血（occult blood）反應，大腸鏡檢切片疑似發炎性腸道疾病（inflammatory bowel disease）。病人接受類固醇（steroid）和sulfadiazine治療後，腹瀉及血便更嚴重。病人到急診就醫時，有發燒、腹脹、廣泛腹部壓痛和反彈痛。經影像學檢查診斷是腸穿孔，病人接受全大腸切除，病理學檢查低倍顯微鏡檢下發現大腸出現燒杯狀潰瘍（flask-shaped ulcer），腸黏膜下和肌肉層出現許多吞噬紅血球的滋養體（trophozoites）。下列敘述何者最不適當？","options":["(A) 最有可能的原蟲感染是Giardia lamblia","(B) 和其他寄生蟲感染不同，此侵犯性原蟲感染並不會引起eosinophilia","(C) 針對此侵犯性原蟲感染最好的治療藥物是metronidazole或tinidazole","(D) 預防再發，完治後病人仍需接受口服luminal agent（paromomycin or iodoquinol）"],"answer":0,"image":""},{"id":"md3-115-1-65","subject":"md3","topic":"內科-心臟血管","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"心內膜炎即使在有效抗生素治療下，仍可能發生的併發症中，下列何者最不需要合併外科處置？","options":["(A) 因為心瓣膜破損導致的嚴重心衰竭","(B) 心內膜炎進展至瓣膜周圍膿瘍（perivalvular abscess）","(C) 人工瓣膜脫位不穩（dehisced unstable prosthetic valve）","(D) 抗生素治療3天後，血液培養仍為陽性"],"answer":3,"image":""},{"id":"md3-115-1-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"有關老人的衰弱症（frailty）及肌少症（sarcopenia）測量，下列敘述何者錯誤？","options":["(A) 骨骼肌量測量可使用雙能量X光吸收儀（DXA）測量","(B) 肌力測量可使用握力器測量手部握力（grip strength）","(C) 活動力表現可測量走路速度（gait speed）","(D) 肌耐力測量可計算連續半身仰臥起坐（partial curl-up）的次數"],"answer":3,"image":""},{"id":"md3-115-1-67","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"關於糖尿病的敘述，下列何者正確？","options":["(A) 西元2000年後，臺灣40歲以上成年人糖尿病盛行率為5%","(B) 不論病人的年紀及功能，糖化血色素（HbA1c）控制目標皆小於7.0%","(C) 雙肽胜肽酶-4抑制劑（DPP-4 inhibitor）類藥物有降低體重、不易低血糖的好處","(D) 鈉葡萄糖共同輸送器抑制劑（SGLT-2 inhibitor）類藥物有降低體重、不易低血糖的好處"],"answer":3,"image":""},{"id":"md3-115-1-68","subject":"md3","topic":"內科-感染","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"51歲男性，主訴間歇性的輕度發燒有一年之久；發燒的時間在下午，偶爾會咳嗽和膿痰，自行服用退燒藥，但這一、兩個月來食慾變差，體重從64公斤掉到62公斤，又發現頸部左邊出現數個質地軟且不痛的小腫塊，而來求診。下列何種檢查之異常，可直接診斷病因？","options":["(A) 全血球計數","(B) 尿液檢查","(C) 痰抹片acid fast染色檢查及痰培養","(D) 胸部X光檢查"],"answer":2,"image":""},{"id":"md3-115-1-69","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"關於高山症的預防或處置，下列何者最符合現行建議或事實？","options":["(A) 建議若需要在海拔1,200公尺以上過夜時，應採取高山症預防措施","(B) sildenafil能預防高山症頭痛症狀，建議在登山前後全程服用","(C) dexamethasone有助於適應，也可改善急性高山症症狀","(D) acetazolamide建議在登山前開始服用，持續到旅行者適應最高海拔後"],"answer":3,"image":""},{"id":"md3-115-1-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"當病人遭遇急性的暴力／衝突事件，下列處置何者最不適當？","options":["(A) 詳細了解事件發生的始末，將事件還原與呈現","(B) 檢討病人為何沒有事先防範","(C) 聚焦在急性危險評估，包括自殺，暴力及急性醫療狀況","(D) 發展支持系統，從家族史及社會心理支持系統開始"],"answer":1,"image":""},{"id":"md3-115-1-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"邊緣性人格障礙（borderline personality disorder, BPD）與功能不良、生活品質低落和死亡率增加有關。大多數BPD病人需要心理健康專業人員進行持續1～2年的心理治療，以持久改善。下列何種類型的心理治療，未被證明可以有效治療這類型的人格障礙？","options":["(A) 辯證行為訓練（dialectical behavior training）","(B) 以移情為中心的心理治療（transference-focused psychotherapy）","(C) 心理動力取向治療（psychodynamic therapy）","(D) 心智化導向的心理治療（mentalization-based psychotherapy）"],"answer":2,"image":""},{"id":"md3-115-1-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"這張流程圖最適用於下列何者？","options":["(A) Person centered primary care model","(B) Disease oriented primary care model","(C) Artificial integrated primary care model","(D) Community oriented primary care model"],"answer":3,"image":"md3-115-1-72.jpeg"},{"id":"md3-115-1-73","subject":"md3","topic":"家醫-緩和醫學","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"許多心臟病末期病人都有植入心律調節器（pacemakers）和植入式心臟去顫器（implantable cardioverter- defibrillators, ICDs）。關於使用上述裝置的描述，何者最不適當？","options":["(A) 心律調節器被認為可能延長生命的終點","(B) 停用心律調節器可能會導致心絞痛或呼吸困難","(C) ICDs會引起類似電擊的疼痛，並被認為與急救過程的電擊一樣令人不舒服","(D) 在植入ICDs裝置的部位，放置一塊約ICDs大小的磁鐵，可以使ICDs暫時失效無法電擊"],"answer":0,"image":""},{"id":"md3-115-1-74","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"34歲男性長期在風濕免疫科就診，最近開始抱怨左手腕疼痛，醫師告知手腕的月狀骨（lunate bone）有異常。病人的手腕X光片影像如圖所示，下列何者最可能造成月狀骨影像之異常？","options":["(A) 退化性關節炎（osteoarthritis）","(B) 類風濕性關節炎（rheumatoid arthritis）","(C) 痛風性關節炎（gouty arthritis）","(D) 缺血性壞死（avascular necrosis）"],"answer":3,"image":"md3-115-1-74.jpeg"},{"id":"md3-115-1-75","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"下列何者不屬於肝門脈系統（portal venous system）？","options":["(A) 肝靜脈（hepatic vein）","(B) 上腸繫膜靜脈（superior mesenteric vein）","(C) 下腸繫膜靜脈（inferior mesenteric vein）","(D) 脾靜脈（splenic vein）"],"answer":0,"image":""},{"id":"md3-115-1-76","subject":"md3","topic":"急診醫學","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"有關特殊狀況下的急救，下列敘述何者正確？","options":["(A) 電傷害（electric injury）時，同電量直流電比交流電容易產生心室顫動（ventricular fibrillation）o","(B) 體溫低於32C的病人，其心電圖常可出現典型的Osborn J waves","(C) 治療高血鉀的藥物中，可以將鉀離子轉進細胞內的藥物，包括葡萄糖酸鈣、胰島素加葡萄糖及碳酸氫鈉等","(D) 病人溺水後意識清楚沒有症狀應在醫院觀察12小時以上，以免發生病情惡化"],"answer":1,"image":""},{"id":"md3-115-1-77","subject":"md3","topic":"內科-感染","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"下列有關登革熱（Dengue fever）的敘述，何者最正確？","options":["(A) 症狀有發燒、紅疹、肌肉痠痛及淋巴腺腫大","(B) 如有肋膜積水、血小板低下及血比容（hematocrit）降低是登革出血熱（Dengue hemorrhagic fever）的表現","(C) 感染登革熱時，成人比小兒較多機會惡化成登革出血熱","(D) 退燒的藥物只能使用acetaminophen不能用非類固醇抗發炎藥（nonsteroidal anti-inflammatory drugs）"],"answer":3,"image":""},{"id":"md3-115-1-78","subject":"md3","topic":"急診醫學","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"下列何者不是腦中風病人接受r-tPA治療的排除條件？","options":["(A) 血糖65 mg/dL","(B) 血壓200/120 mmHg 3","(C) 血小板85,000/mm","(D) 電腦斷層顯示多葉低密度影像＞1/3大腦半球"],"answer":0,"image":""},{"id":"md3-115-1-79","subject":"md3","topic":"醫學倫理與法規","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"關於未成年人的醫療決定，下列何者錯誤？","options":["(A) 學齡前兒童並不具有對重大事務的決定能力，無法行使醫療上的同意","(B) 小學時期的孩童可以參與醫療決定，不過還不具有完整的決定能力","(C) 因為家長是孩童的法定代理人，即使家長的決定違背孩童的最佳利益，還是應尊重家長的決定權","(D) 隨著青少年接近成年，會發展出更成熟的心智與決定能力，家長和醫師不應排除青少年參與自身的醫療決定"],"answer":2,"image":""},{"id":"md3-115-1-80","subject":"md3","topic":"醫學倫理與法規","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"陳老太太75歲，因腹部腫瘤入院檢查，其家人擔心若診斷為癌症會影響病人心情，要求不告知壞消息，病人則希望知道結果。今檢查顯示為肝癌末期，下列敘述何者錯誤？","options":["(A) 基於「尊重自主原則」，應告知病人","(B) 基於「不傷害原則」，應配合家屬不予告知，以避免病人心情低落","(C) 基於「保密及隱私之倫理規則」，應先告知病人","(D) 不告知可能導致病人權益受損，應告知病人"],"answer":1,"image":""},{"id":"md3-115-2-1","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"下列有關器官與系統的老化，何者最適當？","options":["(A) 味覺與嗅覺會隨著年紀增長而退化","(B) 腎絲球過濾率每年以5％左右下降","(C) 20～80歲左心室的功能會改變","(D) 血清中睪固酮在30歲以後開始下降"],"answer":[0,2,3],"image":"","answer_note":"更正:第1題答Ａ或Ｃ或Ｄ或AC或AD或CD或ACD者均給分"},{"id":"md3-115-2-2","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"下列何者不是骨鬆相關骨折（osteoporosis-related fracture）的好發部位？","options":["(A) 髖部","(B) 脊柱","(C) 手腕","(D) 手指"],"answer":3,"image":""},{"id":"md3-115-2-3","subject":"md3","topic":"內科-胸腔","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"關於缺氧（hypoxia）的說明，下列何者最不適當？","options":["(A) 肺部呼吸疾病導致的缺氧，最常見的原因是perfusion-ventilation mismatch","(B) 常見的perfusion-ventilation mismatch，給與100％純氧，缺氧情形較可以改善","(C) 換氣不足（hypoventilation），也會hypoxia，但動脈中二氧化碳的濃度通常不變","(D) 肺內的血液分流（shunting），給與100％純氧，缺氧情形較無法改善或僅能部分改善"],"answer":2,"image":""},{"id":"md3-115-2-4","subject":"md3","topic":"內科-胸腔","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"杵狀指（Clubbing finger）的可能相關疾病，下列何者除外？","options":["(A) 原發性肺癌","(B) 轉移性肺腫瘤","(C) 支氣管擴張","(D) 急性肺炎"],"answer":3,"image":""},{"id":"md3-115-2-5","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"重度酒精性肝硬化的黃疸病人，最不可能出現下列何者身體診察徵象？","options":["(A) spider nevus","(B) parotid gland enlargement","(C) Dupuytren's contracture","(D) Corrigan pulse"],"answer":3,"image":""},{"id":"md3-115-2-6","subject":"md3","topic":"內科-心臟血管","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"冠狀動脈循環提供心肌所需之氧氣及養分，下列敘述何者最不適當？","options":["(A) 心肌需氧量（myocardial oxygen demand）的主要決定因子為：心率、心肌收縮強度以及心肌壁張力","(B) 正常冠脈血流在心臟收縮循環中呈現週期式變化，於心室舒張期血流量較多","(C) 在正常、無嚴重狹窄病灶的冠脈循環中，大部分血流阻力來自於近端、心外膜（epicardial）冠脈節段","(D) 除嚴重狹窄病灶外，冠脈痙攣、血栓、先天冠脈異常開口等，也可能導致冠脈血流不足"],"answer":2,"image":""},{"id":"md3-115-2-7","subject":"md3","topic":"內科-心臟血管","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"72歲男性，本身有高血壓、第二型糖尿病及慢性阻塞性肺病，本次因肺炎併慢性阻塞性肺病急性惡化由急診收住院治療，住院持續抱怨心悸氣促，做得以下心電圖，血行動力學穩定。下列選項組合何者正確？①此心律應為心房顫動（atrial fibrillation） ②此類心律不整的機轉最可能是reentry ③考慮做急性心率控制（acute rate control），首選靜脈輸注propranolol ④施行頸動脈按摩無法終止此類心律不整 ⑤綜合考量此類心律不整及病人共病的血栓風險，應給與抗凝血藥物 ⑥此類心律不整無明顯血栓風險，並不優先考慮給與抗凝血藥物","options":["(A) 僅②④⑤","(B) 僅①②④⑤","(C) 僅②③⑥","(D) ①②③④⑤⑥"],"answer":0,"image":"md3-115-2-7.jpeg"},{"id":"md3-115-2-8","subject":"md3","topic":"內科-心臟血管","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"有關血管平滑肌細胞，下列敘述何者最適當？","options":["(A) 血管平滑肌細胞的收縮主要是靠血液中的鈉離子流入細胞內，再引發細胞內儲存的鈣離子釋放","(B) 血管平滑肌細胞的收縮主要是靠肌凝蛋白輕鏈（myosin light chain）的去磷酸化","(C) 血管平滑肌細胞緊張度的調解主要是靠自主神經系統和內皮細胞來協調","(D) 在健康且完整的內皮功能狀態，乙醯膽鹼（acetylcholine）會促進血管平滑肌細胞的收縮"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第8題一律給分 (原公告答案 C)"},{"id":"md3-115-2-9","subject":"md3","topic":"內科-症狀診斷治療概論","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"有關身體診察（physical examination），下列敘述何者最適當？","options":["(A) 中心性發紺（central cyanosis）常伴隨心臟或肺部顯著的右向左分流，使脫氧的血液到達體循環。因為四肢缺氧，血管收縮導致只有軀幹部呈現紫色","(B) 周圍發紺（peripheral cyanosis）或手足發紺（acrocyanosis），通常見於嚴重心臟衰竭、休克或周邊血管疾病患者，與血管收縮有關","(C) 開放性動脈導管引起的差別性發紺（differential cyanosis），即使是在手術關閉後仍然一定會存在差別性發紺","(D) 發紺病人的鑑別診斷及處置不受血紅素異常的影響"],"answer":1,"image":""},{"id":"md3-115-2-10","subject":"md3","topic":"內科-心臟血管","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"下列何者通常不被認為是正常收縮分率的心臟衰竭（heart failure with preserved ejection fraction, HFpEF）的危險標記（risk markers）？","options":["(A) 高血壓","(B) 肥胖","(C) 心搏緩慢","(D) 老化"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第10題一律給分 (原公告答案 C)"},{"id":"md3-115-2-11","subject":"md3","topic":"急診醫學","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"王先生45歲，有三高病史，平日服藥並不規則，今早7點上班時因追趕公車，忽覺左胸前緊迫且喘不過氣，全身冷汗直流，10點被同事送到醫院急診室時仍明顯胸痛，心電圖顯示V1～V4 ST段上升，且抽血發現Troponin高於99分位值（99％percentile）三倍，當時血壓160/80 mmHg，呼吸急促但指尖脈搏血氧監測顯示SpO2 95％，下肺野有濕囉音（rales），但胸部X光無明顯異常，下列急診處置何者最為適當？","options":["(A) 立即給與高劑量可嚼型aspirin 600 mg，請病人咬碎後服下","(B) 含服舌下硝酸甘油片0.4 mg","(C) 給與nifedipine 5 mg膠囊，刺破後服下","(D) 給與高劑量enoxaparin 5 mg/kg皮下注射"],"answer":1,"image":""},{"id":"md3-115-2-12","subject":"md3","topic":"內科-心臟血管","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"承上題，王先生接受緊急心導管檢查，發現左前降支血管完全阻塞，其餘血管無嚴重狹窄，並順利於胸痛發作後4小時內成功植入藥物塗層金屬支架，轉入加護病房，其後續處置，下列何者最不適當？","options":["(A) 不論心臟收縮功能是否下降，只要血行動力正常、收縮壓高於100 mmHg，建議投與angiotensin- converting enzyme inhibitor或angiotensin receptor blocker","(B) 若心臟超音波顯示有心尖部心室瘤（apical aneurysm），且其中有室壁血栓存在，即使臨床上沒有症狀，若無出血風險，便可考慮投與抗凝血治療3～6個月","(C) 心肌梗塞發作24小時內，若有發生心室頻脈或心室顫動，恢復竇性心律後應預防性給與lidocaine","(D) 血清鎂離子濃度應監控，若偏低則須補充至正常範圍，以減低心律不整風險"],"answer":2,"image":""},{"id":"md3-115-2-13","subject":"md3","topic":"內科-心臟血管","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"有關心肌缺氧時產生變化的敘述，下列何者最不適當？","options":["(A) 左心室收縮功能的些微變化可早於心電圖變化之前","(B) 心肌灌流（myocardial perfusion）的減少早於左心室壁局部運動（regional wall motion）的變化","(C) 左心室舒張功能的變化先於收縮功能的變化","(D) 心電圖出現變化時周邊血中的心肌酵素一定會升高"],"answer":3,"image":""},{"id":"md3-115-2-14","subject":"md3","topic":"內科-心臟血管","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"有關主動脈瓣（aortic valve）疾病的敘述，下列何者最不適當？","options":["(A) 主動脈瓣膜疾病的病人不分男女患病率均隨著年齡的增長而顯著增加","(B) 嚴重的主動脈瓣狹窄（aortic stenosis）較常見於75歲以上的老年人","(C) 感染性心內膜炎（infective endocarditis, IE）的發生率隨著人口高齡化，血管置入外物和心內裝置物的普及，產生多重抗藥性的微生物出現增加","(D) 雙瓣主動脈瓣（bicuspid aortic valve）不易造成嚴重的狹窄，常見於女性"],"answer":3,"image":""},{"id":"md3-115-2-15","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"關於食道癌的描述，下列何者錯誤？","options":["(A) 食道鱗狀上皮細胞癌（squamous cell cancer）分布在食道中上段，風險因子包括吸菸與喝酒","(B) 嚼食檳榔（betel nut chewing）也是造成食道鱗狀上皮細胞癌的風險因子","(C) 食道下段發生癌症的風險因子包括巴瑞特氏食道（Barrett's esophagus）","(D) 肥胖也是食道鱗狀上皮細胞癌的相關因子"],"answer":3,"image":""},{"id":"md3-115-2-16","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"關於幽門螺旋桿菌的描述，下列何者正確？","options":["(A) 糞便幽門螺旋桿菌抗體檢測有9成的敏感性與特異性","(B) 快速尿素酶檢驗（rapid urease test）為侵入性檢查13","(C) 吹氣試驗（urea breath test）為非侵入性檢查項目，但C具輻射性，不宜用於小孩及孕婦","(D) 根除幽門螺旋桿菌使用抗生素治療後，建議需在停藥1週後即檢驗是否殺菌成功"],"answer":1,"image":""},{"id":"md3-115-2-17","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"肝硬化病理特徵中，肝細胞質量減少及血流改變主要是因為何種細胞活化導致？","options":["(A) Kupffer細胞","(B) 肝星狀細胞（hepatic stellate cells）","(C) 肝細胞","(D) 肝臟內皮細胞"],"answer":1,"image":""},{"id":"md3-115-2-18","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"關於肝性腦病變(hepatic encephalopathy)的治療，下列何者正確？","options":["(A) 目前限制蛋白質攝取是肝性腦病變的首選治療方法","(B) 乳果糖（lactulose）透過腸道酸化促進氮代謝物排除，是治療主力","(C) 利用新型全身性抗生素如neomycin與metronidazole可避免副作用","(D) rifaximin因全身吸收率高，常用於急性肝性腦病變治療"],"answer":1,"image":""},{"id":"md3-115-2-19","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"關於胰腺癌（pancreatic adenocarcinoma）之敘述，下列何者錯誤？","options":["(A) 外科手術切除腫瘤有根治的可能","(B) 手術後輔助性化學治療（adjuvant chemotherapy）可降低術後復發風險","(C) 第4期胰臟癌之標準治療為手術切除腫瘤後追加輔助性化學治療（adjuvant chemotherapy）","(D) 胰腺癌會增加靜脈血栓（venous thrombosis）的風險"],"answer":2,"image":""},{"id":"md3-115-2-20","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"關於發炎性腸道疾病（inflammatory bowel disease）的敘述，下列何者錯誤？","options":["(A) 診斷為發炎性腸道疾病者，初始有高達15％的病例無法區分為潰瘍性大腸炎（ulcerative colitis）和克隆氏病（Crohn's disease）","(B) 眼睛相關的併發症如虹彩炎（uveitis）在潰瘍性大腸炎（ulcerative colitis）和克隆氏病（Crohn's disease）兩者均有可能發生","(C) 在發炎性腸道疾病的患者當中，未來罹患大腸癌風險只有潰瘍性大腸炎（ulcerative colitis）會上升，在克隆氏病（Crohn's disease）則無增加，因此監測大腸鏡（surveillance colonoscopy）追蹤只需要在前者定期安排","(D) 用以治療發炎性腸道疾病的免疫抑制劑如azathioprine常與生物製劑（biologics）並用，其副作用包括白血球減少、噁心與肝炎等"],"answer":2,"image":""},{"id":"md3-115-2-21","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"關於大腸直腸癌的敘述，下列何者正確？","options":["(A) 50歲以下的大腸癌，不論在歐美國家或亞太地區都有逐年增加的趨勢","(B) 腺瘤（adenoma）為癌前病變，幾乎所有的腺瘤都會轉變為癌症，因此大腸鏡檢查時必須將所有偵測到並診斷為腺瘤性息肉的病灶均予以切除","(C) 遺傳性大腸癌當中Lynch syndrome的長期預後較一般散發性（sporadic）大腸直腸癌差","(D) 吸菸是大腸直腸癌最重要的危險因子"],"answer":0,"image":""},{"id":"md3-115-2-22","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"一位45歲女性來到門診，主訴最近聲音沙啞、胸口時常疼痛、灼熱，起床後嘴巴常常有苦味，沒有慢性疾病病史。下列選項組合何者最適當？ ①本病人最可能的診斷為胃食道逆流，亦要考慮其他食道疾病（感染、藥物性灼傷、嗜酸性球性食道炎等），但不可能為冠狀動脈疾病 ②若胃鏡下無胃食道交界處發炎則本病人不可能為胃食道逆流 ③胃食道交界處發炎嚴重且切片下呈現巴瑞特氏食道低度分化異常（Barrett's metaplasia with low grade dysplasia），未來發生食道鱗狀上皮細胞癌（squamous cell carcinoma）之機會增加 ④氫離子幫浦阻斷劑（PPI）較H2組織胺受體阻斷劑（H2RA）可以有效解決胃食道逆流症狀","options":["(A) ①②④","(B) 僅②④","(C) 僅④","(D) ②③"],"answer":2,"image":""},{"id":"md3-115-2-23","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"下列關於小腸細菌過度生長（small-intestinal bacterial overgrowth）之敘述，何者錯誤？","options":["(A) 可能會引發脂肪便（steatorrhea）","(B) 可能會引發大球性貧血（macrocytic anemia）","(C) 手術後腸道結構改變或小腸狹窄是可能的原因","(D) 常導致葉酸（folate）缺乏"],"answer":3,"image":""},{"id":"md3-115-2-24","subject":"md3","topic":"內科-腎臟","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"下列何者不是慢性腎臟病病人之常見危險因子？","options":["(A) 吸菸","(B) 喝酒","(C) 糖尿病","(D) 高血壓"],"answer":1,"image":""},{"id":"md3-115-2-25","subject":"md3","topic":"內科-腎臟","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"臨床上可以使用estimated glomerular filtration rate（eGFR）與urinary albumin creatinine ratio（UACR）來判斷腎臟病的嚴重程度，與評估進展到末期腎臟病的危險度，下列何種情況最嚴重？2","options":["(A) eGFR 80（mL/min/1.73 m），UACR＞300 mg/g 2","(B) eGFR 70（mL/min/1.73 m），UACR 30～300 mg/g 2","(C) eGFR 60（mL/min/1.73 m），UACR＜30 mg/g 2","(D) eGFR 50（mL/min/1.73 m），UACR＜30 mg/g"],"answer":0,"image":""},{"id":"md3-115-2-26","subject":"md3","topic":"內科-腎臟","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"45歲女性，因急性腸胃炎（acute gastroenteritis），上吐下瀉，血壓130/80 mmHg，血中肌酸酐 + （creatinine）0.8 mg/dL，鈉離子（Na）濃度132 mmol/L，下列何種賀爾蒙分泌上升是其低鈉血症（hyponatremia）的最可能原因？","options":["(A) 甲狀腺素（thyroxine）","(B) 抗利尿激素（vasopressin）","(C) 醛固酮（aldosterone）","(D) 醣化皮質類固醇（glucocorticoid）"],"answer":1,"image":""},{"id":"md3-115-2-27","subject":"md3","topic":"內科-腎臟","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"下列那項不屬於間質性膀胱炎／膀胱疼痛症候群（interstitial cystitis/bladder pain syndrome, IC/BPS）的病因假說？","options":["(A) 感染與尿道菌群","(B) 自體免疫","(C) 神經生物學因素與中樞敏感化","(D) 尿路結石及結晶"],"answer":3,"image":""},{"id":"md3-115-2-28","subject":"md3","topic":"內科-腎臟","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"針對急性腎損傷病人的治療反應監測，下列那項最能準確反映腎功能恢復狀態？","options":["(A) 連續監測血清肌酸酐與尿量變化","(B) 每日進行腹部超音波檢查","(C) 連續監測血尿及蛋白尿","(D) 定期重複尿液培養"],"answer":0,"image":""},{"id":"md3-115-2-29","subject":"md3","topic":"內科-腎臟","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"58歲女性，接受腎移植10年，腎功能於最近2年逐漸變差，2年內creatinine由1.2 mg/dL升至2.8 mg/dL，使用的免疫抑制劑為tacrolimus 8 mg/day、mycophenolate mofetil 1,000 mg/day，腎臟切片呈現間質纖維化、腎內小動脈壁增厚、無淋巴球浸潤，下列何種處置最適當？","options":["(A) 加上口服類固醇","(B) 檢驗血中tacrolimus濃度（trough level）","(C) 用cyclosporine取代tacrolimus","(D) 增加mycophenolate mofetil劑量至2,000 mg/day"],"answer":1,"image":""},{"id":"md3-115-2-30","subject":"md3","topic":"內科-腎臟","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"62歲男性，因最近半年出現雙側腳水腫、疲倦而來到門診，病人任職電池工廠，有痛風病史，發作時會自行至藥局購買消炎止痛藥。身體診察血壓160/90 mmHg，抽血發現肌酸酐5.5 mg/dL，尿液分析顯示蛋白尿(+3)，其電腦斷層顯像（未施打顯影劑）如圖。此病人最可能的診斷為何？","options":["(A) 馬兜鈴酸腎病變","(B) 止痛藥腎病變","(C) 鉛腎病變","(D) 慢性腎絲球腎炎"],"answer":1,"image":"md3-115-2-30.jpeg"},{"id":"md3-115-2-31","subject":"md3","topic":"內科-胸腔","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"35歲女性，因慢性乾咳及疲倦就醫，胸部X光顯示雙側肺門淋巴結腫大，淋巴結的病理顯示非乾酪性肉芽腫（noncaseating granulomas），最可能的診斷為何？","options":["(A) 結核病（tuberculosis）","(B) 類肉瘤（sarcoidosis）","(C) 過敏性肺炎（hypersensitivity pneumonitis）","(D) 矽肺症（silicosis）"],"answer":1,"image":""},{"id":"md3-115-2-32","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"75歲女性因最近3個月單側頭痛與不明原因發燒來門診求助，經抽血檢驗發現ANA、rheumatoid factor皆為陰性，ESR＞100 mm/hr，CRP 5.38 mg/dL，沒有感染之證據。下列敘述何者最不適當？","options":["(A) 若病人合併有jaw claudication，需考慮giant cell arteritis","(B) 可以考慮安排超音波檢查temporal artery或axillary artery是否有發炎","(C) 若病人合併有雙側肩膀與髖關節疼痛，需考慮同時有polymyalgia rheumatica","(D) 若考慮使用生物製劑治療，應考慮優先選擇adalimumab"],"answer":3,"image":""},{"id":"md3-115-2-33","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"關於inflammatory myositis的myositis specific antibodies與臨床表現，下列敘述何者最不適當？","options":["(A) anti–MDA5 antibodies：amyopathic dermatomyositis with digital ulcers","(B) anti–NXP–2 antibodies：higher risk of cancer","(C) anti–Mi–2 antibodies：a favorable response to treatment","(D) anti–TIF1–γ antibodies：lower risk of cancer"],"answer":3,"image":""},{"id":"md3-115-2-34","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"病人因為反覆invasive Neisseria感染，懷疑有免疫不全症，下列檢查何者最適當？","options":["(A) Lymphocyte phenotype","(B) CH50 and AP50","(C) Nitroblue tetrazolium（NBT）assay","(D) Immunoglobulin serum levels"],"answer":1,"image":""},{"id":"md3-115-2-35","subject":"md3","topic":"內科-風濕免疫過敏","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"下列何種分子（molecule）不同的isoforms在細胞表面的表現，可被用來區分memory和naïve T淋巴球？","options":["(A) CD45","(B) CD2","(C) CD28","(D) CD44"],"answer":0,"image":""},{"id":"md3-115-2-36","subject":"md3","topic":"內科-腫瘤","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"下列有關腫瘤分期（staging）與TNM分期系統的敘述，何者錯誤？","options":["(A) TNM分期系統是以腫瘤的解剖位置為基礎，依腫瘤大小、淋巴結侵犯及是否有遠處轉移來分類","(B) TNM分期系統通常不適用於血液腫瘤，例如：白血病、淋巴瘤、多發性骨髓瘤","(C) ypTNM分期是指病人在接受手術後的初次病理分期","(D) TNM分期有時會結合腫瘤的組織學分級（grading）"],"answer":[2,3],"image":"","answer_note":"更正:第36題答Ｃ或Ｄ或CD者均給分"},{"id":"md3-115-2-37","subject":"md3","topic":"內科-腫瘤","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"關於去勢抗性前列腺癌（castration-resistant prostate cancer, CRPC）的敘述，下列何者錯誤？","options":["(A) 其定義為當血清睪固酮高於100 ng/mL時仍有病情惡化","(B) prostate-specific antigen（PSA）上升伴隨骨轉移惡化是常見的表現","(C) 對於有骨轉移疼痛的病人，緩解疼痛比降低PSA數值可能更具臨床意義","(D) 針對帶有BRCA2突變的CRPC患者，可以考慮使用poly-ADP ribose polymerase（PARP）抑制劑"],"answer":0,"image":""},{"id":"md3-115-2-38","subject":"md3","topic":"內科-腫瘤","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"下列何者並非皮膚常見原發癌症的組織類型？","options":["(A) 鱗狀細胞癌（squamous cell carcinoma）","(B) 基底細胞癌（basal cell carcinoma）","(C) 腺癌（adenocarcinoma）","(D) 默克細胞癌（Merkel cell carcinoma）"],"answer":[2,3],"image":"","answer_note":"更正:第38題答Ｃ或Ｄ或CD者均給分"},{"id":"md3-115-2-39","subject":"md3","topic":"內科-腫瘤","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"有關消化系統神經內分性細胞瘤（gastrointestinal）neuroendocrine tumors（NETs）的臨床表徵及診治，下列敘述何者最適當？","options":["(A) 病理學上常使用chromogranins及synaptophysin的免疫組織染色輔助診斷","(B) 絕大多數（＞80％）的pancreatic NET是有功能性的（functional），即會表現出hormone secretion相關的症狀","(C) Functional pancreatic NETs中，最常見的類型是gastrinoma","(D) 血液中的synaptophysin-A是診斷及追蹤此類疾病常用的腫瘤指標"],"answer":0,"image":""},{"id":"md3-115-2-40","subject":"md3","topic":"內科-腫瘤","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"胃淋巴瘤（gastric lymphoma）約僅占胃惡性腫瘤的3％，但其處置與一般胃腺癌有極大不同。下列有關胃淋巴瘤敘述，何者最不適當？","options":["(A) mucosa-associated lymphoid tissue subtype通常與H. pylori感染有關，可以抗生素進行H. pylori eradication治療此類淋巴瘤","(B) mucosa-associated lymphoid tissue subtype的發生率遠大於diffuse large B-cell lymphoma，其比率約為70％：30％","(C) mucosa-associated lymphoid tissue subtype的胃淋巴瘤若併有t(11;18) translocation，該基因變異將形成一API1與MALT1的chimeric protein","(D) diffuse large B-cell lymphoma可能是原生型（de novo），也可能是mucosa-associated lymphoid tissue subtype轉變而來，原生型多為BCL-2及CD10陽性"],"answer":[1,2],"image":"","answer_note":"更正:第40題答Ｂ或Ｃ或BC者均給分"},{"id":"md3-115-2-41","subject":"md3","topic":"內科-腫瘤","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"癌症的發生是由於基因和環境的暴露相互作用所導致。目前已知的環境致癌因子（含微生物或化合物）與其好發癌症的組合中，下列何者最不適當？","options":["(A) asbestos：cancer of the lung, pleura, peritoneum","(B) alkylating agents：acute myeloid leukemia","(C) human immunodeficiency virus：adult T-cell leukemia／lymphoma","(D) vinyl chloride：liver cancer（angiosarcoma）"],"answer":2,"image":""},{"id":"md3-115-2-42","subject":"md3","topic":"內科-血液","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"下列關於immune thrombocytopenic purpura（ITP）的描述，何者正確？","options":["(A) 與凝血因子缺乏的出血不同的是，ITP常有深部組織（如：肌肉）的出血","(B) 在小孩子中通常為急性表現，較少變成慢性疾病；在成人則多為慢性表現","(C) 血球數據上，大多合併白血球過多與分類異常，並且常有貧血","(D) 骨髓切片常看到megakaryocytes的數量明顯減少，鮮有其他異常"],"answer":1,"image":""},{"id":"md3-115-2-43","subject":"md3","topic":"內科-血液","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"下列關於血液製品的描述，何者正確？","options":["(A) 一般而言，血庫中的紅血球儲存於攝氏1～6℃，而血小板則是置於室溫（攝氏20～24℃）且須輕微搖晃","(B) 經過放射線照射的紅血球血品，可以預防transfusion-associated graft-versus-host disease，且不影響其儲存期限","(C) 血小板與血漿製品，最好取自男性或是從未懷孕的女性，主要目的為降低傳播巨細胞病毒（cytomegalovirus）的機會","(D) 冷凍沉澱品（cryoprecipitate）是由新鮮冷凍血漿（fresh frozen plasma）在攝氏37℃加熱後所得到的沉澱物集合而成，富含fibrinogen，必須立刻輸注，不可以再冷凍保存"],"answer":0,"image":""},{"id":"md3-115-2-44","subject":"md3","topic":"內科-腫瘤","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"60歲女性病患，剛被診斷有多發性骨轉移的第四期肺腺癌，其肺腺癌的基因檢測為發現EML4-ALK融合變化。下列那一種治療對該病患最適合？","options":["(A) osimertinib標靶治療","(B) pemetrexed + platinum化學治療","(C) alectinib標靶治療","(D) gefitinib標靶治療"],"answer":2,"image":""},{"id":"md3-115-2-45","subject":"md3","topic":"內科-胸腔","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"有關氣喘type 2及non-type 2 inflammation之敘述，下列何者最不適當？","options":["(A) type 2 inflammation以嗜酸性白血球為主，參與發炎介質主要包括IL-4、IL-5及IL-13","(B) non-type 2 inflammation以嗜中性白血球為主，參與發炎介質主要包括IL-6、IL-8及IL-17","(C) IL-4、IL-5及IL-13主要由Th2 cell產生","(D) IL-17主要由Th1 cell產生"],"answer":3,"image":""},{"id":"md3-115-2-46","subject":"md3","topic":"內科-胸腔","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"有關慢性阻塞性肺病（chronic obstructive pulmonary disease）的治療，下列敘述何者最不適當？［註：ICS：inhaled corticosteroid；LABA：long-acting beta agonist；LAMA：long-acting muscarinic antagonist］","options":["(A) 症狀嚴重，急性發作頻繁，可以初始治療即給與LABA＋LAMA","(B) 一般初始治療可以考慮給與LABA或LAMA單一治療","(C) 若病患使用LABA＋LAMA治療，仍常有急性發作且血中嗜酸性白血球≧100 cells/μL可考慮轉換成LABA＋ LAMA＋ICS","(D) 依據GOLD指引，治療原則以FEV1及FEV1/FVC為主要考量"],"answer":3,"image":""},{"id":"md3-115-2-47","subject":"md3","topic":"內科-感染","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"下列各種對於社區性肺炎（community-acquired pneumonia）致病原檢查（etiologic diagnosis），何者有最高的特異性（specificity）？","options":["(A) sputum Gram stain","(B) procalcitonin","(C) urine legionella antigen test","(D) serum Mycoplasma pneumoniae IgG titer"],"answer":2,"image":""},{"id":"md3-115-2-48","subject":"md3","topic":"內科-感染","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"下列肺外結核疾病中，何者最為常見？","options":["(A) tubeculous meningitis","(B) genitourinary tuberculosis","(C) tuberculous lymphadenitis","(D) tuberculous pericarditis"],"answer":2,"image":""},{"id":"md3-115-2-49","subject":"md3","topic":"內科-胸腔","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"有關肋膜腔積液（pleural effusion）的診斷，下列敘述何者錯誤？","options":["(A) 如果肋膜腔積液amylase level上升，應該考慮是否有膽道發炎","(B) 如果病人有發燒，肋膜腔積液檢測發現大部分是多形核白血球細胞（polymorphonuclear cells），而且胸腔電腦斷層發現肺實質無異常（no pulmonary parenchymal abnormalities），應考慮有腹腔內膿瘍（intraabdominal abscess）","(C) 藥物引起的肋膜腔積液中，常見有嗜伊紅性白血球（eosinophil）","(D) 肋膜腔積液也可能發生在接受冠狀動脈繞道手術之後"],"answer":0,"image":""},{"id":"md3-115-2-50","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"75歲男性，長期吸菸，因體重減輕前來門診檢查。經一系列檢查發現肺部有10公分大的腫瘤，然而一年前的胸部X光報告顯示正常。此次因意識不清被送至急診，抽血檢查顯示血糖正常，但意外發現鈉離子偏低，僅114 meq/L，鉀離子則正常。下列診斷及處置何者最不適當？","options":["(A) 鈉離子偏低合併意識不清時，需要在24小時內將鈉離子補回正常範圍，以避免永久性腦部傷害","(B) 鈉離子偏低可能是由抗利尿激素分泌不當症候群（SIADH）","(C) 可以考慮使用限水療法進行治療","(D) 病人的肺部腫瘤，小細胞肺癌的可能性高於鱗狀細胞癌"],"answer":0,"image":""},{"id":"md3-115-2-51","subject":"md3","topic":"內科-胸腔","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"下列有關interstitial lung disease（ILD）的敘述，何者最適當？","options":["(A) idiopathic pulmonary fibrosis出現lung basal crackles的機會很低","(B) respiratory bronchiolitis associated ILD出現clubbing finger的機會很高","(C) non-specific interstitial pneumonia在電腦斷層出現honeycombing的機會很少","(D) sarcoidosis在電腦斷層不會出現peribronchovascular thickening"],"answer":2,"image":""},{"id":"md3-115-2-52","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"原發性醛固酮增多症（primary aldosteronism）的特徵不包括下列何項？","options":["(A) 高血壓","(B) 低血鉀","(C) 代謝性酸中毒","(D) 醛固酮和腎素活性（aldosterone/renin activity）之比值升高"],"answer":2,"image":""},{"id":"md3-115-2-53","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"關於胰臟的神經內分泌腫瘤（neuroendocrine tumor, NET），下列敘述何者正確？","options":["(A) 大部分的胰臟神經內分泌腫瘤是沒有功能（nonfunctional）","(B) 最常見的功能性胰臟內分泌腫瘤是升糖素瘤（glucagonoma）","(C) 無功能的胰臟神經內分泌腫瘤（nonfunctional pancreatic neuroendocrine tumor），無論大小只要追蹤即可","(D) Verner-Morrison syndrome、水樣腹瀉、低血鉀和胃酸缺乏症是升糖素瘤的常見臨床表現"],"answer":0,"image":""},{"id":"md3-115-2-54","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"關於糖尿病的致病機轉中，胰臟分泌胰島素及其相關機制，下列敘述何者正確？","options":["(A) 胰島素阻抗性以及胰島素分泌不足是第2型糖尿病發生的主因，通常胰島素分泌不足比胰島素阻抗性早發生","(B) 在健康人身上，當胰島素敏感性增加的時候，胰島素分泌也要隨之增加，以維持血糖正常","(C) 在糖尿病的致病機轉上，與西方族群相比，亞洲族群有較高的胰島素阻抗性，西方族群胰島素分泌比較不足","(D) 目前認為，糖尿病人的胰島素阻抗性主要是來自於胰島素受體的「受體後缺陷（\"postreceptor\" defect）」"],"answer":3,"image":""},{"id":"md3-115-2-55","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"關於肝醣儲積症（glycogen storage disease）的敘述，下列敘述何者正確？","options":["(A) 發生率約為五萬分之一至十萬分之一","(B) 肝醣代謝異常會導致肝醣堆積在肌肉、肝臟、心臟等組織，堆積的肝醣結構可能正常也可能不正常","(C) 不同的肝醣儲積症臨床表現有顯著差異，但通常只要有適當的飲食治療就可以有效避免長期併發症","(D) 最常見的成人疾病是葡萄糖-6-磷酸酶（glucose-6-phosphatase deficiency）缺乏症（GSD type I）；最常見的兒童疾病是肌磷酸化酶（myophosphorylase deficiency）缺乏症（GSD type V）"],"answer":1,"image":""},{"id":"md3-115-2-56","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"關於威爾森氏症（Wilson's disease）的敘述，下列何者正確？","options":["(A) 主要臨床症狀包含神經／精神系統與肝臟相關症狀，而出現肝臟相關症狀者幾乎都大於30歲","(B) 可能影響內分泌系統，如導致青春期延遲或無月經。而腎小管功能受影響時則會導致胺基酸、電解質、鈣、磷和葡萄糖的異常流失","(C) 是由ATP7B的變異引起的，ATP7B是一種P-type ion-motive ATPase，它可將肝臟中的鋁離子清除排泄到膽汁中，並防止腦內的鋁蓄積","(D) 早期診斷並接受肝臟移植是最有效的治療方式"],"answer":1,"image":""},{"id":"md3-115-2-57","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"關於代謝相關性脂肪肝炎（metabolic dysfunction-associated steatohepatitish, MASH）與代謝相關性脂肪肝疾病（metabolic dysfunction-associated steatotic liver disease, MASLD）的敘述，下列何者正確？","options":["(A) 約40％MASLD的成年人患有MASH","(B) 腹部影像學檢查無法確定那些MASLD者有MASH，目前也沒有可以診斷MASH的特定抽血檢測項目","(C) 所有MASLD患者都需要接受適當藥物治療，以避免肝硬化、肝癌等不良預後","(D) 研究顯示，每天800 IU的維生素E可以改善脂肪肝，且完全沒有任何不良反應"],"answer":1,"image":""},{"id":"md3-115-2-58","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"一位50歲女性，身高150公分，體重45公斤，腰圍75公分，其身體質量指數（body mass index）為多少？","options":["(A) 20","(B) 25","(C) 30","(D) 35"],"answer":0,"image":""},{"id":"md3-115-2-59","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"感染性胃腸炎或食物中毒的致病因子、鑑別診斷與治療，下列敘述何者最不適當？","options":["(A) 出血性大腸桿菌（Enterohemorrhagic E. coli, EHEC）造成出血性腹瀉，治療的主要方法是支持性療法，抗生素可能會增加溶血性尿毒症候群（hemorrhagic uremic syndrome）的風險","(B) 產氣莢膜梭菌（Clostridium perfringens）食物中毒，潛伏期6～8小時，最常見症狀是嘔吐與發燒","(C) 金黃色葡萄球菌（Staphylococcus aureus）食物中毒，潛伏期短為1～6小時，主要症狀為噁心、嘔吐與腹瀉","(D) 沙門氏菌（Salmonella spp.）感染的潛伏期較長可達12～72小時，有明顯的發燒和腹瀉症狀"],"answer":1,"image":""},{"id":"md3-115-2-60","subject":"md3","topic":"內科-感染","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"下列疾病與建議的治療藥物配對，何者最不適當？","options":["(A) 肺囊蟲肺炎（Pneumocystis jirovecii pneumonia）—trimethoprim-sulfamethoxazole","(B) 蟯蟲感染（Enterobiasis）—mebendazole或albendazole","(C) 糞小桿線蟲過度感染（Strongyloides stercoralis hyperinfection）—praziquantel","(D) 弓蟲腦炎（Toxoplasma encephalitis）—clindamycin＋pyrimethamine"],"answer":2,"image":""},{"id":"md3-115-2-61","subject":"md3","topic":"內科-感染","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"下列何種抗生素最不推薦用於治療methicillin抗藥性金黃色葡萄球菌（methicillin-resistant Staphylococcus aureus）感染症？","options":["(A) linezolid","(B) vancomycin","(C) imipenem-cilastatin","(D) teicoplanin"],"answer":2,"image":""},{"id":"md3-115-2-62","subject":"md3","topic":"內科-感染","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"62歲糖尿病病人，其血糖控制非常不良，這次因為左臉紅腫熱痛而入院。入院後，會診耳鼻喉科醫師，發現左邊鼻腔內有一片黑色壞死組織，切片HE染色（Hematoxylin and eosin stain）發現病原體形狀為broad, ribbon-like nonseptate hyphae，關於此病人病情，下列敘述何者最適當？","options":["(A) 最可能的診斷為侵襲性麴菌病（invasive aspergillosis）","(B) 建議第一線治療藥物為echinocandins","(C) 除藥物治療外，最重要的治療是合併外科清瘡手術","(D) 治療藥物除fluconazole外，亦可選用voriconazole"],"answer":2,"image":""},{"id":"md3-115-2-63","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"55歲已婚女性，因車禍脾臟破裂，經脾臟切除術後，到門診諮詢脾臟切除後需接受的疫苗注射，下列何種疫苗與現在的病情需求最沒有相關性？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）疫苗","(B) 流行性感冒嗜血桿菌（Haemophilus influenzae）疫苗","(C) 腦膜炎雙球菌（Neisseria meningitidis）疫苗","(D) 人類乳突瘤病毒（Human papillomavirus）疫苗"],"answer":3,"image":""},{"id":"md3-115-2-64","subject":"md3","topic":"內科-感染","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"下列關於結核病（tuberculosis）的敘述，何者最不適當？","options":["(A) 可以經由飛沫核（droplet nuclei）傳染","(B) 接觸有傳染性的肺結核患者後，是否會被傳染受宿主及環境因素影響","(C) 沒有防護下接觸痰液抗酸性染色（acid-fast stain, AFS）陰性之肺結核患者不會被傳染","(D) 單純肺外結核的患者基本上不具有傳染力"],"answer":2,"image":""},{"id":"md3-115-2-65","subject":"md3","topic":"內科-感染","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"下列有關動物咬傷之處置，何者最不適當？","options":["(A) 貓咬傷所造成之穿刺傷口，感染率較狗咬傷為低，儘量在第一時間進行傷口縫合","(B) 一般臉部傷口可以在充分清潔後進行縫合","(C) 四肢傷口，若咬傷後超過12小時沒有接受傷口縫合處理，可能需要給與預防性抗生素","(D) 被咬傷之病人，若5年內曾接受過破傷風疫苗注射，可以不用追加注射"],"answer":0,"image":""},{"id":"md3-115-2-66","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"有關老年尿失禁的敘述，下列何者最適當？","options":["(A) 對於老年婦女尿失禁，局部雌激素補充療法效果明確，是目前第一線首選治療","(B) mirabegron是選擇性β-3乙型交感受體促進劑，不具抗膽鹼副作用，優點是使用前不需確認病人膀胱餘尿是否正常","(C) 婦女因生產導致膀胱及膀胱頸過動（hypermobility），是造成急迫型尿失禁（urge urinary incontinence）的主要原因","(D) 夜間多尿可能為藥物所引起，如：利尿劑（diuretics）、乙型阻斷劑（beta-blockers）等，也可能為攝取過多水分、咖啡因或酒精引起"],"answer":3,"image":""},{"id":"md3-115-2-67","subject":"md3","topic":"家醫-行為與社區醫學","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"根據Stock Keister等人（2004）的研究，從事家庭醫業時，了解病人對於醫師的期待，有助於醫病之間的滿意度，下列何者不是病人的期待？","options":["(A) 真誠地傾聽（truly listens to me）","(B) 嘗試了解認識我（tries to get to know me）","(C) 任何問題都能幫助我（can help with any problem）","(D) 總能誠實並間接性的提醒我（is always honest and indirect to remind me）"],"answer":3,"image":""},{"id":"md3-115-2-68","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"關於老人跌倒之評估與預防之敘述，下列何者最適當？","options":["(A) 依衛生福利部國民健康署2017年調查，臺灣老人跌倒發生率小於10％","(B) 太極的訓練包含了肌力及平衡，有助於預防老人的跌倒","(C) 美國預防醫學工作小組（U.S. Preventive Services Task Force）建議所有老人每天補充維他命D 1,000 IU，可減少跌倒的風險","(D) 大部分的老人跌倒都是碰撞到物品或人造成，而不是滑倒或絆倒"],"answer":1,"image":""},{"id":"md3-115-2-69","subject":"md3","topic":"內科-血液","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"有關維生素B12缺乏症（Vitamin B12 deficiency）的敘述，下列何者最適當？","options":["(A) 維生素B12主要吸收部位在十二指腸","(B) 測量血清維生素B12濃度是診斷本症正確率最高的方法","(C) 病人接受維生素B12補充治療後，血清高半胱胺酸（homocysteine）濃度會迅速降低","(D) 抗壁細胞抗體（anti-parietal cell antibody）陽性病人，宜每日口服維生素B12 1,000 mcg以有效改善症狀"],"answer":2,"image":""},{"id":"md3-115-2-70","subject":"md3","topic":"家醫-行為與社區醫學","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"下列何種與病人面談溝通的方式，對病人的健康行為最有正面影響？","options":["(A) 父權式面談（paternalistic interviewing）","(B) 默認式面談（default interviewing）","(C) 動機式面談（motivational interviewing）","(D) 病人主導式面談（consumerism interviewing）"],"answer":2,"image":""},{"id":"md3-115-2-71","subject":"md3","topic":"家醫-行為與社區醫學","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"關於我國現行長照計畫2.0的失能評估與給付制度更新現況，下列敘述何者正確？","options":["(A) 經照顧管理專員評估符合失能等級為2～8級者，將交由C單位個管員與個案及家屬共同擬定照顧服務計畫","(B) 服務方式可分為居家式到宅服務及機構住宿式服務二種","(C) 衰弱程度可採用study of osteoporotic fracture（SOF）評估","(D) 收入程度越低（如：中低收入戶、低收入戶），給付額度越多"],"answer":2,"image":""},{"id":"md3-115-2-72","subject":"md3","topic":"家醫-家庭醫業與預防醫學","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"某一社區大型女性荷爾蒙補充療法（HRT）隨機分派臨床試驗，計算其HRT治療介入與對照組兩組試驗結果（心血管事件（CHD）發生）之相對風險（relative risk, RR）為下列何者？（對照組每年發生28 CHD events/10,000 women，而HRT治療介入組每年發生38 CHD events/10,000 women）","options":["(A) 1/1,000","(B) 0.737","(C) 1.357","(D) 1,000"],"answer":2,"image":""},{"id":"md3-115-2-73","subject":"md3","topic":"家醫-緩和醫學","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"下列關於安寧療護的敘述，何者錯誤？","options":["(A) 安寧療護主要是提供給存活期小於或等於12個月的病人舒適照護","(B) 大多數的病人都太晚照會安寧療護，平均存活期只有3星期","(C) 安寧療護的目的之一，是讓病人可以回家善終","(D) 安寧團隊提供病人及家屬的照顧，尤其是對家屬的悲傷撫慰，可以提供至1年"],"answer":0,"image":""},{"id":"md3-115-2-74","subject":"md3","topic":"內科-消化肝膽胰","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"急性胰臟炎（acute pancreatitis）的晚期併發症，下列何者最不常見？","options":["(A) 膽結石的產生（gallbladder stone formation）","(B) 胰管阻塞（pancreatic duct obstruction）","(C) 胰臟假性囊腫的產生（pseudocyst formation）","(D) 後腹腔膿瘍（abscess）"],"answer":0,"image":""},{"id":"md3-115-2-75","subject":"md3","topic":"影像醫學","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"下圖為心臟電腦斷層（CT）檢查圖，箭號所指的血管最可能為：","options":["(A) 右冠狀動脈","(B) 左主冠狀動脈","(C) 左前降支冠狀動脈","(D) 左迴旋冠狀動脈（left circumflex artery）"],"answer":2,"image":"md3-115-2-75.jpeg"},{"id":"md3-115-2-76","subject":"md3","topic":"急診醫學","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"根據2020美國心臟學會心肺復甦術及緊急心臟照護指引，對於院前心跳停止（out-of-hospital cardiac arrest, OHCA）與院內心跳停止（in-hospital cardiac arrest, IHCA）之比較，下列敘述何者正確？","options":["(A) 整體而言，OHCA病人比IHCA病人存活率較高","(B) 對所有OHCA病人做心肺復甦術（cardiopulmonary resuscitation, CPR）時，執行心臟按壓及吹氣之順序都是先壓心臟再吹氣","(C) 目前在臺灣高級救護技術員，可以依預立醫療流程對OHCA病人執行給藥、施行氣管插管及使用自動體外去顫器等，中級救護技術員可以使用自動體外去顫器","(D) 低溫療法針對OHCA或IHCA病人都很重要，是此兩類所有病人恢復心跳後的標準治療"],"answer":2,"image":""},{"id":"md3-115-2-77","subject":"md3","topic":"內科-內分泌代謝","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"對於抗利尿激素不適當分泌症候群（syndrome of inappropriate secretion of antidiuretic hormone, SIADH）導致低血鈉症的診斷標準，下列何者錯誤？","options":["(A) 血液滲透壓偏低，通常小於275 mOsm/Kg H2O","(B) 尿液滲透壓不適當的偏低，通常小於100 mOsm/Kg +","(C) 尿液的[Na]升高，通常高於20 mEq/L","(D) 正常體容積（euvolemia）"],"answer":1,"image":""},{"id":"md3-115-2-78","subject":"md3","topic":"急診醫學","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"下列何種症狀為診斷急性高山症的必要條件？","options":["(A) 噁心與嘔吐（GI symptoms）","(B) 疲憊虛弱（fatigue/weakness）","(C) 頭痛（headache）","(D) 頭暈（dizziness/light-headedness）"],"answer":2,"image":""},{"id":"md3-115-2-79","subject":"md3","topic":"醫學倫理與法規","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"凌晨兩點值班住院醫師甲正在緊急處理一位病情嚴重，但沒有家屬在旁陪伴的病人乙。護理師丙告訴醫師甲，病房中有一位病人丁突發腹痛，家屬十分焦急，此時醫師甲應如何處置最適當？","options":["(A) 請護理師丙先幫腹痛病人丁施打生理食鹽水，以安撫家屬","(B) 放下正在處理中的病人乙，立即趕過去處理腹痛病人丁","(C) 請護理師丙聯絡值班的二線醫師協助處理","(D) 請護理師丙代為處理病人丁，並安撫家屬"],"answer":2,"image":""},{"id":"md3-115-2-80","subject":"md3","topic":"醫學倫理與法規","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"醫師對病人資訊守密，是治療關係中重要的基礎，且受倫理法律的規範。然而守密並非沒有例外，下列何種情境仍應嚴守守密義務？","options":["(A) 對非同住親友揭露病人HIV陽性檢驗之結果","(B) 精神科病人透露極可能為真的預定攻擊計畫","(C) 認知障礙的年長病人，有多處不明原因的傷痕","(D) 法院或健康保險署調閱病人就醫資料"],"answer":0,"image":""}];
